  str_item_6001532 = "แสงดาวของคุณ",
  str_item_intro_6000001 = "เหรียญยืนเคียงข้างฉัน หลายปีผ่านไป จำนวนเหรียญเพิ่มขึ้นจนน่าตกใจ ณ จุดนี้ มีเพียงกระเป๋าเงินขนาดเท่าบ้านเท่านั้นที่สามารถมีความมั่งคั่งได้มากขนาดนี้",
  str_item_intro_6000002 = "เหรียญยืนเคียงข้างฉัน แทบจะเป็นไปไม่ได้เลยที่จะคำนวณความมั่งคั่งที่สะสมไว้จำนวนมหาศาลนี้ การกล้าทำเช่นนั้นจะทำให้แม้แต่พ่อค้า Umbraton ที่โลภมากที่สุดก็เวียนหัวจนเป็นลม",
  str_item_intro_6000101 = "เหรียญยืนเคียงข้างฉัน ยินดีด้วย! แม้จะลองไม่กี่ครั้ง แต่ก็ไม่มีใครบอกได้ว่าอนาคตจะเป็นอย่างไร!",
  str_item_intro_6000102 = "เหรียญยืนเคียงข้างฉัน คุณสามารถขับยานโคลอสซัสได้แล้ว! ความผูกพันของคุณกับหิ่งห้อยดูเหมือนจะแข็งแกร่งขึ้นเช่นกัน",
  str_item_intro_6000103 = "เหรียญยืนเคียงข้างฉัน เมฆอยู่ตรงหน้าคุณ และมีเมฆอยู่รอบตัวคุณ จุ่มลงไปด้านล่างเพื่อดูโลกอันกว้างใหญ่เบื้องล่าง และท้องฟ้าสีฟ้าที่มีเมฆปกคลุมอยู่เบื้องบน",
  str_item_intro_6000104 = "เหรียญยืนเคียงข้างฉัน คุณได้เดินทางไกลและไกลในฐานะนักนำทางแห่งโซรอซ หนึ่งอาจกล่าวได้ว่าบ้านที่แท้จริงของคุณอยู่ในท้องฟ้าที่ไร้ขอบเขตเหนือแอสตร้า",
  str_item_intro_6000201 = "เหรียญยืนเคียงข้างฉัน ให้ภาพแผ่นดินอยู่ในใจ แล้วโบกมือไปในที่ที่ท่านพอใจ โลกทั้งใบอยู่ในมือคุณ",
  str_item_intro_6000202 = "เหรียญยืนเคียงข้างฉัน หลังจากเดินทางมาหลายหน ผืนดินก็ต้องฝังลึกอยู่ในใจ ใช่ไหม? คุณมองเห็นภูเขาและแม่น้ำของมันแม้ในขณะที่คุณหลับตาไหม?",
  str_item_intro_6000301 = "เหรียญยืนเคียงข้างฉัน ทางข้างหน้าจะยาวไกลและลำบากแน่นอน การหาเพื่อนที่น่าเชื่อถือจากทุกสาขาอาชีพจะให้บริการคุณเป็นอย่างดี",
  str_item_intro_6000302 = "เหรียญยืนเคียงข้างฉัน ตลอดการเดินทางของคุณ คุณได้สร้างมิตรภาพใหม่ ๆ กับผู้คนทั่วโลกเช่นเดียวกัน ผลงานที่น่าทึ่งจริงๆ!",
  str_item_intro_6000303 = "เหรียญยืนเคียงข้างฉัน ไม่ว่าคุณจะไปที่ไหน คุณมักจะถูกรายล้อมไปด้วยเพื่อนสนิทเสมอ เพื่อนฝูงที่จะหัวเราะและร้องไห้อยู่เคียงข้างคุณ และเผชิญกับความทุกข์ยากใดๆ ที่อาจเข้ามาหาคุณ...",
  str_item_intro_6000401 = "เหรียญยืนเคียงข้างฉัน ท้องฟ้าดูสดใสขึ้นเล็กน้อยเมื่อมีพันธมิตรใหม่ทุกคนที่ตระหนักถึงศักยภาพที่แท้จริงของพวกเขา บางทีแสงลึกลับนี้อาจเป็นพลังที่รวมตัวคุณและเพื่อนของคุณเข้าด้วยกัน?",
  str_item_intro_6000402 = "เหรียญยืนเคียงข้างฉัน หลังจากที่พันธมิตรของคุณได้รับพลังแห่งแสง พลังงานที่ทำให้ท้องฟ้าสดใสก็สามารถมองเห็นได้ในมือของพวกเขาเช่นกัน",
  str_item_intro_6000403 = "เหรียญยืนเคียงข้างฉัน ผู้ที่ได้รับพรด้วยพลังแห่งแสงสว่างจะมารวมตัวกันและมอบความแข็งแกร่งให้กับบุตรแห่งโชคชะตา เพื่อที่ความเฉลียวฉลาดของพวกเขาจะไปถึงแม้แต่มุมที่มืดมนที่สุดและสิ้นหวังที่สุดของโลก",
  str_item_intro_6000501 = "เหรียญยืนเคียงข้างฉัน เมื่อดาวสองดวงปรากฏขึ้นใกล้กัน แสงระยิบระยับของพวกมันเป็นสัญลักษณ์ของความไว้วางใจ ซึ่งเป็นสัญญาณว่าพวกเขาจะสะท้อนความสดใสของกันและกันไปอีกนาน",
  str_item_intro_6000502 = "เหรียญยืนเคียงข้างฉัน ขณะที่ดวงดาวเดินทางข้ามฟากฟ้า เส้นทางของพวกมันมาบรรจบกัน เชื่อมโยงกัน และสะท้อนเหมือนหัวใจและความคิดของวิญญาณเครือญาติที่มีความเชื่อคล้ายคลึงกัน",
  str_item_intro_6000503 = "เหรียญยืนเคียงข้างฉัน เช่นเดียวกับกลุ่มดาวในท้องฟ้ายามค่ำคืน พันธมิตรของคุณเปล่งประกายด้วยแสงแห่งความไว้วางใจและความสามัคคีอย่างแท้จริง ความผูกพันที่เชื่อมโยงคุณแสดงถึงการบรรจบกันของความหวังและความคิดของคุณ",
  str_item_intro_6000601 = "เหรียญยืนเคียงข้างฉัน แม้จะเป็นครั้งแรกที่คุณได้เห็นพวกเขา เมล็ดพันธุ์แห่งความเข้าใจก็ถูกหว่านลงไปแล้ว สี่มือประสานกันที่ปลายนิ้ว แสดงถึงความเชื่อมโยงระหว่างหัวใจสองดวง",
  str_item_intro_6000602 = "เหรียญยืนเคียงข้างฉัน แม้จะใช้เวลาหลายปีอยู่ใต้ดิน ความเบิกบานใจของการบินก็ไม่เคยลืมไป แม้ว่านี่จะเป็นครั้งแรก แต่ก็มากเกินพอ",
  str_item_intro_6000603 = "เหรียญยืนเคียงข้างฉัน เสียงฝีเท้าที่ใกล้เข้ามาไม่เพียงแสดงถึงอันตรายเท่านั้น แต่ยังหมายถึงการมาถึงของการทำลายล้างทั้งหมด",
  str_item_intro_6000604 = "เหรียญยืนเคียงข้างฉัน ในการเผชิญหน้าศัตรูนับไม่ถ้วน เขาเลือกที่จะจบทุกอย่างด้วยเสียงคำรามที่สั่นสะเทือนโลก มันไม่ใช่การเสียสละอย่างสิ้นหวัง แต่เป็นกลยุทธ์ที่คำนวณและตั้งใจไว้",
  str_item_intro_6000605 = "เหรียญยืนเคียงข้างฉัน ข้อความจากคนของคุณ! แต่อดีตแบบไหนที่อยู่เบื้องหลังเสียงพูดที่แผ่วเบานั้น?",
  str_item_intro_6000606 = "เหรียญยืนเคียงข้างฉัน ที่พำนักชั่วนิรันดร์ในท้องฟ้าสีครามเบื้องบน เป็นศูนย์กลางของอารยธรรมทั้งปวงและเป็นสัญลักษณ์แห่งแสงสว่าง",
  str_item_intro_6000607 = "เหรียญยืนเคียงข้างฉัน \"อนาคตไม่ใช่ของความสว่าง แต่เป็นของความมืด\" ในขณะนั้น รอยยิ้มของเธอบิดเบี้ยวเป็นบางสิ่งที่ดุร้าย... บางอย่างที่ชั่วร้าย แม้จะเป็นคนเดียวกันกับคุณ แต่เธอก็หลงทางไปนานแล้ว",
  str_item_intro_6000608 = "เหรียญยืนเคียงข้างฉัน ศัตรูยิ้มอย่างโอ้อวดเมื่อแผนการชั่วร้ายของพวกเขาบรรลุผล ในความสิ้นหวังที่มืดมนที่สุด ดอกแดนดิไลอันลอยตามสายลมอ่อนๆ อนาคตจะเป็นอย่างไรสำหรับเราทุกคน? หรือมากกว่า... ยังมีอนาคตที่จะได้เห็น?",
  str_item_intro_6000609 = "เหรียญยืนเคียงข้างฉัน มีคำกล่าวใน Astra ว่า \"ทางเลือกของคนๆ หนึ่งมีมากกว่าความพยายาม\" หลายคนลังเลที่ทางแยกที่สำคัญที่สุดของโชคชะตา เมื่อต้องเผชิญกับการตัดสินใจเหล่านี้ พวกเขาสามารถพึ่งพาหัวใจ สัญชาตญาณ และเพื่อนของพวกเขาเท่านั้น",
  str_item_intro_6000610 = "เหรียญยืนเคียงข้างฉัน อาวุธที่เปลี่ยนแสงเป็นลำแสงพลังงานอันทรงพลังคือโดเมนของ Lumopolis และ Lumopolis เพียงอย่างเดียว แม้ว่าราคาจะสูงลิ่ว แต่การคุกคามที่ใกล้จะเกิดขึ้นของศัตรูจะต้องถูกหลีกเลี่ยงในทุกกรณี",
  str_item_intro_6000611 = "เหรียญยืนเคียงข้างฉัน ยักษ์ใหญ่สีดำพ่ายแพ้ และทั้งนายและเครื่องจักรได้ตกลงสู่พื้นหุบเขาที่ห่างไกล อย่างไรก็ตาม ความพ่ายแพ้ของพวกเขา ไม่ได้หมายถึงการล่มสลายของพวกเขาเสมอไป...",
  str_item_intro_6000612 = "เหรียญยืนเคียงข้างฉัน บรรดาผู้ที่แสวงหาอำนาจด้วยเจตนาอันเป็นเอกภาพจะถึงวาระที่จะพินาศด้วยอำนาจนั้น เมื่อเธอโยนตัวเองเข้าไปในความมืด มันคือพรหมลิขิตของเธอที่จะพบกับจุดจบของเธอในความมืดเช่นกัน",
  str_item_intro_6000613 = "เหรียญยืนเคียงข้างฉัน เส้นคือ \"ธรรมชาติ\" ที่แสดงออกมาในวิชาคณิตศาสตร์ เปลือกเป็นภาชนะของสกุลเงิน และความต่อเนื่องไม่จำเป็น",
  str_item_intro_6000614 = "เหรียญยืนเคียงข้างฉัน คู่ที่ครั้งหนึ่งเคยต่อสู้ในฐานะสหายในสงครามได้แยกทางกันเนื่องจากความแตกต่างในอดีต",
  str_item_intro_6000615 = "เหรียญยืนเคียงข้างฉัน เธอตกลงไปในห้วงนิทราไม่รู้จบภายใต้คอร์ดลิงค์ เมื่อตื่นขึ้น คาดหวังให้เธอปลดปล่อยพลังอันยิ่งใหญ่",
  str_item_intro_6000616 = "เหรียญยืนเคียงข้างฉัน ในที่สุดชาว Caelestite ก็มีสถานที่ที่เรียกว่าบ้านภายใต้ Obelisk of Return แต่การปรากฏตัวของมันก็เปลี่ยนชะตากรรมของเขาเช่นกัน...",
  str_item_intro_6000617 = "เหรียญยืนโดยฉัน. เพื่อสำรวจอาณาเขตของ Eternal Night เหล่าอัศวิน Lumopolis และเจ้าหน้าที่ของสหพันธ์ Illumina จะต้องร่วมมือกัน เพราะอันตรายนั้นไม่มีอะไรธรรมดา",
  str_item_intro_6000618 = "เหรียญยืนโดยฉัน. นับเป็นเกียรติอย่างยิ่งในการฝึกซ้อมทางทหารที่มีหลายเหล่าทัพเข้าร่วม",
  str_item_intro_6000619 = "เหรียญยืนโดยฉัน. ประตูหนากั้นผู้บุกรุกทั้งหมดที่ระดับต่ำสุดของ Undercity เพื่อปกป้องสิ่งของสำคัญและมีค่าจากหัวขโมยและอันธพาล",
  str_item_intro_6000701 = "เหรียญยืนเคียงข้างฉัน นี่ไม่ใช่แค่จุดเริ่มต้นเท่านั้น แต่ยังเป็นโอกาสที่จะก้าวขึ้นเหนือสิ่งอื่นใด ผู้ที่กล้าพอที่จะก้าวไปข้างหน้าเสมอจะเป็นคนที่เอาชนะความทุกข์ยากและไปถึงจุดสูงสุด",
  str_item_intro_6000702 = "เหรียญยืนเคียงข้างฉัน แม้ว่าอุปสรรคมากมายรออยู่ข้างหน้า แต่การต่อสู้ยังคงเหมือนเดิม และเราต้องไม่หยุดพยายามปรับปรุงและไปให้ถึงจุดสูงสุด นี่อาจเป็นพลังแห่งการเสด็จขึ้นสู่สวรรค์?",
  str_item_intro_6000703 = "เหรียญยืนเคียงข้างฉัน หลังจากไปถึงยอดเขาแล้ว มองลงมายังโลกเบื้องล่างได้อย่างง่ายดายและพักผ่อนบนเกียรติยศ อย่างไรก็ตาม สำหรับความทะเยอทะยานอย่างแท้จริง ความพึงพอใจนี้เป็นเพียงช่วงเวลาแห่งความสุขชั่วขณะระหว่างการเดินทางเพื่อไปให้ถึงจุดสูงสุด...",
  str_item_intro_6000704 = "เหรียญยืนเคียงข้างฉัน บรรดาผู้ที่ไปถึงจุดสูงสุดนั้นเหนือกว่าผู้ท้าชิงหลายคน แต่ความหิวกระหายที่จะพิชิตก็ไม่สามารถอิ่มเอมได้ และฝีเท้าก็ไม่เคยหยุดนิ่ง",
  str_item_intro_6000705 = "เหรียญยืนเคียงข้างฉัน จุดสูงสุดได้เห็นการต่อสู้หลายครั้ง\nบนยอดเขาเท่านั้นที่จะรู้ถึงความยากลำบาก\nจุดสูงสุดสงวนไว้สำหรับผู้ชนะ\nบนยอดเขาเท่านั้นที่จะมองข้ามส่วนที่เหลือ",
  str_item_intro_6000706 = "เหรียญ Stand By Me. แม้ว่านี่จะเป็นเพียงครั้งแรก แต่ผู้ที่สามารถทำได้นั้นยอดเยี่ยมและยิ่งใหญ่กว่าหลายๆ คน",
  str_item_intro_6000801 = "เหรียญยืนเคียงข้างฉัน กักขังประหลาดใจ การรวมตัวที่ไม่คาดคิด;\nอยู่ในกรงสูง พวกที่ไม่ยอมติดกับดักก็หักโซ่ตรวน",
  str_item_intro_6000802 = "เหรียญยืนเคียงข้างฉัน แมวต้องการอะไร? นอกจากอาหารกระป๋องที่ชอบแล้ว ก็ต้อง...",
  str_item_intro_6000803 = "เหรียญยืนเคียงข้างฉัน เป็นครอบครัวที่ต้อง \"วันหยุด\" และทำให้เธอรู้ว่าร้านกาแฟคือบ้านของเธอ และเป็นที่ที่เธอควรอยู่...",
  str_item_intro_6000804 = "เหรียญยืนเคียงข้างฉัน พระราชวังถูกปิดอย่างแน่นหนาท่ามกลางหิมะและน้ำค้างแข็ง แต่เมื่อร่างเพรียวบางนั้นมาถึงแสงออโรร่าก็จะเปิดออก",
  str_item_intro_6000901 = "เหรียญยืนเคียงข้างฉัน รอยแยกแผ่กว้างเหมือนใยแมงมุมบนพื้น และสัญญาณทั้งหมดชี้ให้เห็นความสกปรกที่โผล่ออกมาจากด้านล่าง...",
  str_item_intro_6000902 = "เหรียญยืนเคียงข้างฉัน ถ้ำมืดยกเว้นแหล่งกำเนิดแสงของผู้บุกรุก แต่ที่นี่ไม่เงียบสำหรับ \"ชาวนา\" หลายคน...",
  str_item_intro_6000903 = "เหรียญยืนเคียงข้างฉัน มีจุดสิ้นสุดนี้หรือไม่? ความคิดมักจะหลอกหลอนนักสำรวจ แม้ว่าผู้แข็งแกร่งจะไม่มีความกลัวและกล้าเสี่ยงอีกครั้ง",
  str_item_intro_6001001 = "เหรียญยืนเคียงข้างฉัน รูปภาพสามารถเป็นอาวุธได้ และภาพลวงตาสามารถทำอันตรายได้ บางครั้งตาแหลมก็ดีกว่าแขนแข็งๆ",
  str_item_intro_6001002 = "เหรียญยืนเคียงข้างฉัน ปล่อยให้มันเผา! พยานเปลวไฟทำลายคนนอกศาสนา!",
  str_item_intro_6001003 = "เหรียญยืนเคียงข้างฉัน เสียงเรียกอันดังประกาศการมีอยู่ของศัตรู และความเงียบบ่งบอกถึงการสิ้นสุดและจุดจบของมัน",
  str_item_intro_6001004 = "เหรียญยืนเคียงข้างฉัน คู่ต่อสู้หรือความว่างเปล่าน่ากลัวกว่ากัน? ดูเหมือนวิธีเดียวที่จะเอาชนะมันได้คือการผูกมัดและดักจับตลอดไป",
  str_item_intro_6001005 = "เหรียญยืนเคียงข้างฉัน ไม่มีร่างมนุษย์ มีเพียงความตระหนักที่ลอยอยู่ แม้ว่ามันจะกระจายไปในแสงที่บวมเท่านั้น",
  str_item_intro_6001006 = "เหรียญยืนเคียงข้างฉัน ความอยุติธรรมของโชคชะตาสามารถทำให้คนบ้าและกลายเป็นความมืดได้ เมื่อถึงจุดนั้น ปืนและใบมีดเป็นวิธีแก้ปัญหาเพียงอย่างเดียว",
  str_item_intro_6001007 = "เหรียญยืนเคียงข้างฉัน เมื่อต้องเผชิญกับความเจ็บปวดและความโกรธเคืองตลอดเวลา การสิ้นสุดคือของขวัญที่ดีที่สุด",
  str_item_intro_6001008 = "เหรียญยืนเคียงข้างฉัน มืดที่สุดก่อนสว่าง อดทนไว้ แล้วคุณจะเห็นดวงอาทิตย์ส่องแสงบนเส้นทางที่คุณกำลังมุ่งหน้าไป",
  str_item_intro_6001009 = "เหรียญยืนเคียงข้างฉัน เสียงที่แยกออกมาและเสียงที่ทนไม่ได้ประสานกันเพื่อสร้างความเจ็บปวดและฝันร้ายของศัตรู",
  str_item_intro_6001010 = "เหรียญยืนเคียงข้างฉัน คนที่ไม่มีบ้านสามารถถูกเนรเทศได้หรือไม่? อาจจะ แต่น้อยคนนักที่จะรู้เรื่องนี้",
  str_item_intro_6001011 = "เหรียญยืนเคียงข้างฉัน หินสีแดงเข้มมีต้นกำเนิดมาจากเป้าหมายที่ปนเปื้อน และหลังจากหลุดพ้นแล้ว ก็กลายเป็นอัญมณีที่สวยงามที่สุด",
  str_item_intro_6001012 = "เหรียญยืนเคียงข้างฉัน มนุษย์ไม่มีค่าอะไรนอกจากวิญญาณของพวกเขาซึ่งเหล่าทวยเทพต่อสู้เพื่อแย่งชิง",
  str_item_intro_6001013 = "เหรียญยืนโดยฉัน. ไม่ใช่อัศวินแห่ง Lumopolis แต่เป็นศัตรูที่ยืนยาวของพวกเขา การปลอมตัวของพวกเขาถูกทำลาย—ตอนนี้สิ่งที่เหลืออยู่คือการต่อสู้จนถึงที่สุด",
  str_item_intro_6001101 = "เหรียญยืนเคียงข้างฉัน ทุกครั้งที่เปิดหน้าข้อความมหัศจรรย์จะท่วมตาและกระตุ้นจิตใจราวกับระฆังที่น่ารื่นรมย์",
  str_item_intro_6001102 = "เหรียญยืนเคียงข้างฉัน ไม่ใช่เป็นการดูหมิ่นที่จะนั่งอ่านหนังสือเมื่อคุณได้เรียนรู้ทุกอย่างในนั้นแล้ว",
  str_item_intro_6001103 = "เหรียญยืนเคียงข้างฉัน การใช้หนังสือเป็นเตียงและหมอนหมายความว่าเราสามารถเพลิดเพลินกับโลกที่อยู่ในความฝันของคุณได้",
  str_item_intro_6001201 = "เหรียญยืนเคียงข้างฉัน ชาวสวนที่แท้จริงมักจะปลูกด้วยมือของพวกเขาเอง แม้ว่ามือและเสื้อผ้าของพวกเขามักจะเปื้อนเหงื่อและดิน แต่การได้เห็นต้นอ่อนแต่ละต้นโตเต็มที่และบานสะพรั่งเป็นความสุขที่สุดอย่างหนึ่งในชีวิตของพวกเขา",
  str_item_intro_6001202 = "เหรียญยืนเคียงข้างฉัน เมื่อพืชที่อยากรู้อยากเห็นเหล่านี้เติบโตและเติมเต็มพื้นที่ด้วยความงามตามธรรมชาติของพวกเขา Cloud Gardens จะดูแตกต่างออกไปมากในแสงแดดยามพระอาทิตย์ตก",
  str_item_intro_6001203 = "เหรียญยืนเคียงข้างฉัน มีเพียงผู้เชี่ยวชาญเท่านั้นที่สามารถจับปลาหายากเช่นนี้ได้!",
  str_item_intro_6001204 = "เหรียญยืนเคียงข้างฉัน นี่เป็นโอกาสที่ยิ่งใหญ่สำหรับนักตกปลาทุกคน ไม่ใช่เพียงเพราะเทศกาลเท่านั้น แต่เนื่องจากการมาถึงของปรมาจารย์ชาวประมงบางคน",
  str_item_intro_6001205 = "เหรียญยืนเคียงข้างฉัน คุณได้สะสมความรู้มากมายสำหรับการสร้างโครงสร้างใหม่โดยไม่รู้ตัว ในไม่ช้า พื้นที่ว่างในหุบเขานั้นจะดูไม่รกร้าง",
  str_item_intro_6001206 = "เหรียญยืนเคียงข้างฉัน หลังจากเชี่ยวชาญการก่อสร้างโครงสร้างต่างๆ มากมายแล้ว คุณก็พร้อมที่จะเปลี่ยน Cloud Gardens ให้เป็นเมืองที่เจริญรุ่งเรืองได้ตลอดเวลา ในฐานะที่เป็นเจ้าแห่ง Cloud Gardens หน้าที่นี้ตกอยู่กับคุณคนเดียว",
  str_item_intro_6001301 = "เหรียญยืนเคียงข้างฉัน Elysium สถานที่ที่มีอดีตในตำนาน... หลังจากปลุกฮีโร่ที่หลับใหลมานาน พวกเขาจะมีความผูกพันแบบไหนกัน?",
  str_item_intro_6001302 = "เหรียญยืนเคียงข้างฉัน คำสาบานจากวันเวลาผ่านไปนานยังคงไม่บุบสลาย และศัตรูในสมัยนั้นยังคงเป็นภัยคุกคาม คำพูดไม่สามารถทำลายคำปฏิญาณหรือป้องกันไม่ให้พวกเขาดำเนินการ",
  str_item_intro_6001400 = "เหรียญยืนโดยฉัน. ชีวิตก็เหมือนเกม และการผจญภัยที่เล่นในมือคุณก็น่าตื่นเต้นไม่แพ้กัน ผู้ที่สามารถเคลียร์ด่านด้วยเงื่อนไขที่ยากลำบากเช่นนี้ได้ก็จะประสบความสำเร็จในชีวิตจริงเช่นกัน",
  str_item_intro_6001401 = "เหรียญยืนเคียงข้างฉัน มีการลงบันทึกอย่างซื่อสัตย์โดยไม่มีอคติหรือปกปิด มันเก็บความทรงจำให้คุณอ่านวันเก่า ๆ ที่ดี",
  str_item_intro_6001402 = "เหรียญยืนเคียงข้างฉัน เวทีที่ลอยอยู่บนท้องฟ้ากึกก้องไปด้วยเพลงสรรเสริญที่ดังกึกก้องไปทั่วทุกมุมของทวีปราวกับพรจากสวรรค์ ระหว่างความฝันและนิมิต บทเพลงแห่งความรักและการเยียวยา",
  str_item_intro_6001403 = "เหรียญยืนโดยฉัน. พันธมิตรที่ขาดไม่ได้ในมหาสมุทรที่ไม่มีที่สิ้นสุด ว่ากันว่าไม่เพียงนำทางเรือไปตามเส้นทางที่ถูกต้องเท่านั้น แต่ยังนำทางผ่านเขาวงกตแห่งโชคชะตาด้วย...",
  str_item_intro_6001404 = "เหรียญยืนเคียงข้างฉัน มันเป็นของขวัญ การแสดงออกของหัวใจ รูปแบบของการสื่อสาร ไม่จำเป็นต้องมีคำพูด แค่มอบให้คนที่คุณรักก็เพียงพอแล้ว",
  str_item_intro_6001405 = "เหรียญยืนโดยฉัน. ช่อดอกไม้สำหรับวันพิเศษ เมื่อถึงเวลานัดหมายก็จะพากันบานสะพรั่งส่งกลิ่นหอมอบอวลไปด้วยกลิ่นแห่งความรัก หายใจเข้าลึก ๆ และเพลิดเพลินไปกับช่วงเวลาที่ล้ำค่านี้",
  str_item_intro_6001406 = "เหรียญ Stand By Me. ไม่เคยละทิ้งด้านของนักสืบ สิ่งที่นักสืบต้องทำคือติดต่อและจะให้บริการ ด้วยสิ่งนี้ แม้กระทั่งเงื่อนงำที่เล็กที่สุดก็สามารถค้นพบได้",
  str_item_intro_6001407 = "เหรียญ Stand By Me. ความทรงจำแห่งวันครอบครัว ภาพลวงตาที่หายวับไปในประกายแวววาวของคริสตัล แม้ว่าเหตุการณ์ลวงตาเหล่านี้จะอยู่ในดินแดนลวงตาของผู้คนและสิ่งของลวงตา แต่ทุกสิ่งดูเหมือนจริงมาก ราวกับว่าเคยสัมผัสโดยตรง",
  str_item_intro_6001408 = "คนจริงๆ ติดอยู่ในอาณาจักรที่สร้างขึ้น ซึ่งไม่สามารถทำลายได้ด้วยกำลัง มิฉะนั้นพวกเขาจะติดอยู่ภายในตลอดไป...",
  str_item_intro_6001409 = "เหรียญยืนเคียงข้างฉัน แทนคนที่อยู่เดี่ยวในหุบเขา Denuo ที่โยนเกล็ดประกายและฝุ่นวิเศษในขณะที่เต้นอย่างงดงาม สร้างความหลงใหลให้กับทุกคนที่มองเห็น...",
  str_item_intro_6001410 = "เหรียญยืนเคียงข้างฉัน ชัยชนะไม่ได้เกิดจากการสู้รบเพียงอย่างเดียว แต่ยังมีรากฐานอยู่ในการก่อตั้งประจำวัน การเติบโต และการพัฒนาอย่างต่อเนื่อง",
  str_item_intro_6002001 = "เหรียญยืนเคียงข้างฉัน ผู้พิทักษ์คนดีและผู้ส่งสารของพระเจ้ามีอยู่จริงหรือไม่? หรือเป็นเพียงจินตนาการ?",
  str_item_intro_6002002 = "เหรียญยืนเคียงข้างฉัน เตรียมตัวให้พร้อมในขณะที่พระอาทิตย์ยังส่องแสงอยู่ ท่ามกลางแสงตะวัน อย่าลืมภัยจากความมืดมิด ในยามสงบอย่าลืมว่าศัตรูอาจแฝงตัวอยู่ในเงามืดอยู่ใกล้ๆ...",
  str_item_intro_6002003 = "เหรียญยืนเคียงข้างฉัน สัตว์ร้ายลึกลับในตำนานจากแดนเหนืออันไกลโพ้น ว่ากันว่าพ่นไฟจากน้ำแข็งที่เย็นที่สุด และสามารถแช่แข็งทั้งหมู่บ้านได้ในคราวเดียว",
  str_item_intro_6002004 = "เหรียญยืนเคียงข้างฉัน มีกระจกเงาอยู่แห่งใดแห่งหนึ่งในโลก ซึ่งจะสะท้อนให้เห็นเฉพาะหน้าตาของผู้ชมเท่านั้น ไม่มีกระจกเงาของใครอื่น สะท้อนว่ามีชีวิตและความคิดของตัวเอง ...",
  str_item_intro_6002005 = "เหรียญยืนเคียงข้างฉัน พวกเขาเริ่มต้นเป็นวัตถุทั่วไป เฉพาะผู้มีปัญญาเท่านั้นที่พวกเขาจะได้รับความตระหนักรู้และจิตวิญญาณเพื่อทำภารกิจให้สำเร็จ",
  str_item_intro_6002006 = "เหรียญยืนเคียงข้างฉัน ถ้าเหล็กหนักกว่าอากาศ แล้วทำไมถึงทำบินได้? และถ้าเหล็กหนักกว่าน้ำแล้วจะใช้ทำเรือได้อย่างไร? เมื่อเผชิญกับคำถามเช่นนี้ ความรู้และตรรกะจะช่วยคุณได้ดีกว่า \"สามัญสำนึก\"",
  str_item_intro_6002007 = "เหรียญยืนเคียงข้างฉัน พระเจ้าเท่านั้นที่สามารถทำให้เหล็กขนาดใหญ่เคลื่อนไหวได้เหมือนเสียงที่ไม่มีตัวตน",
  str_item_intro_6002008 = "เหรียญยืนเคียงข้างฉัน ทะเลทรายไม่มีที่สิ้นสุด เหตุใดจึงไม่มีใครรู้จักเดินเตร่ที่นี่ หรือนั่นอาจเป็นความตั้งใจเพียงอย่างเดียวที่จะเดินเตร่",
  str_item_intro_6002009 = "เหรียญยืนเคียงข้างฉัน ความเพลิดเพลินมาในราคา ไม่ว่าคุณจะเป็นใคร แม้ว่าราคานั้นจะไม่ได้จ่ายในตอนแรก มันก็จะจ่ายในสักวันหนึ่ง… และพร้อมดอกเบี้ย",
  str_item_intro_6002010 = "เหรียญยืนเคียงข้างฉัน เสียงกรีดร้องที่น่าสะพรึงกลัว เสียงเชียร์ของพันธมิตร... เสน่ห์ของสงครามไม่ได้อยู่ที่การพิชิต กลยุทธ์ หรือความกล้าหาญ แต่อยู่ในชัยชนะและความจริงที่ว่ามีกษัตริย์องค์อื่นถือกำเนิดขึ้น",
  str_item_intro_6002011 = "เหรียญยืนเคียงข้างฉัน เปลือกเหล็กไม่เพียงพอที่จะเปลี่ยนคนธรรมดาให้เป็นนักสู้ที่ทำลายไม่ได้ คุณจะต้องมีการประสานงาน ความยืดหยุ่น และความพากเพียร",
  str_item_intro_6002012 = "เหรียญยืนเคียงข้างฉัน จะมีสิ่งเช่นขวดที่ไม่มีภายในหรือภายนอกหรือไม่? หากปราศจากความแตกต่างนี้ จะไม่มีที่ว่างและขวดใดให้พูดถึง... แต่บางที พื้นที่นั้นไม่มีที่สิ้นสุด และไม่ต้องการความแตกต่าง? ไม่ว่าในกรณีใด วัตถุดังกล่าวจะอยู่ในอาณาจักรของเหล่าทวยเทพ และสามารถดำรงอยู่ได้ด้วยวิธีการอันศักดิ์สิทธิ์เท่านั้น",
  str_item_intro_6002013 = "เหรียญยืนเคียงข้างฉัน แถบกระดาษมีด้านเดียวได้ไหม? คำตอบนั้นซ่อนอยู่ภายในแถบนั้นเอง สิ่งเดียวที่ต้องทำคือดูให้ถูกวิธี การทำเช่นนี้จะทำให้คนๆ หนึ่งมองเห็นโลกทั้งใบในมุมมองที่ต่างไปจากเดิม...",
  str_item_intro_6002014 = "เหรียญยืนเคียงข้างฉัน สิ่งต่าง ๆ สามารถมีอยู่ได้แม้ในพื้นที่ที่เล็กที่สุด เมื่อมองโลกนี้ในขวด คุณเคยคิดไหมว่าอาจมีคนทำแบบเดียวกันกับโลกของคุณด้วย?",
  str_item_intro_6002015 = "เหรียญยืนเคียงข้างฉัน ตำนานมากมายกล่าวว่าสิ่งมีชีวิตทั้งหมดเกิดมาจากต้นไม้ต้นเดียวกัน ซึ่งเป็นแนวคิดที่เชิญชวนให้คนจำนวนมากเยาะเย้ยถากถาง เมื่อค้นคว้าหาต้นกำเนิดของสิ่งมีชีวิตบางชนิด คนเหล่านั้นย่อมเริ่มสงสัยในคำพูดก่อนหน้านี้อย่างหลีกเลี่ยงไม่ได้...",
  str_item_intro_6002016 = "เหรียญยืนเคียงข้างฉัน หากสตริงหนึ่งแถวสามารถทำให้เกิดเสียงที่วาววับได้ ถ้าเป็นแถวคู่ล่ะ? แม้ว่าจะต้องใช้นักดนตรีที่มีทักษะและความแข็งแกร่งเป็นพิเศษ",
  str_item_intro_6002017 = "เหรียญยืนเคียงข้างฉัน ล้อคือลำตัว การเหยียบเป็นการโจมตีหลัก อธิษฐานว่าคุณจะไม่ต้องเผชิญกับใบมีดในการต่อสู้",
  str_item_intro_6002018 = "เหรียญยืนเคียงข้างฉัน หากวันหนึ่งป้อมปราการสามารถครองดินแดนได้เหมือนยักษ์ใหญ่ในตำนาน พวกเขาจะอยู่ยงคงกระพัน",
  str_item_intro_6002019 = "เหรียญยืนเคียงข้างฉัน เมื่อมนุษย์นึกถึง \"ความว่างเปล่า\" พวกเขาให้ยืมการดำรงอยู่ ไร้รูปร่าง มันเข้าตา เจาะลึกเข้าไปในจิตใจ และสร้าง \"ความว่างเปล่า\" ที่แตกต่างออกไป",
  str_item_intro_6002020 = "เหรียญยืนเคียงข้างฉัน ไม่เหน็ดเหนื่อย ไม่มีข้อตำหนิ... นั่นจะอธิบายเกี่ยวกับภูเขาสำหรับผู้ที่เดินทางข้ามทะเลทราย",
  str_item_intro_6002021 = "เหรียญยืนเคียงข้างฉัน สนุกกับเกมกลยุทธ์ได้ทุกที่ในโลก และผู้ที่มีตำแหน่งสูงในสังคมมักจะมองว่าส่วนที่เหลือของโลกเป็นเกมหมากรุก อย่างไรก็ตาม \"ชิ้น\" ในเกมหมากรุกนี้มีความตระหนักในตัวเอง เช่นเดียวกับกระดานหมากรุก ดังนั้น เกมหมากรุกเหล่านี้หลายเกมจึงถูกกำหนดให้พังทลายอย่างสิ้นเชิง ดังที่มันเคยมีมาตลอดประวัติศาสตร์",
  str_item_intro_6002022 = "เหรียญยืนเคียงข้างฉัน \"ตกสู่ความพินาศชั่วนิรันดร์... มองดูโลกอีกครั้ง และปล่อยให้มันเป็นความทรงจำสุดท้ายของคุณ\" นี่คือสิ่งที่สิ่งมีชีวิตแห่งความมืดพูดกับสิ่งมีชีวิตทั้งหมดในโลก",
  str_item_intro_6002023 = "เหรียญยืนเคียงข้างฉัน กล่าวคือ ตำแหน่งของดวงดาวบนท้องฟ้าแสดงถึงชะตากรรมของมนุษย์ ดังนั้นมนุษย์จึงสร้างหอคอยสูงตระหง่านเพื่อสังเกตดวงดาวและทำนายอนาคต น่าแปลกที่อนาคตของหอคอยแห่งนี้ไม่สามารถคาดเดาได้",
  str_item_intro_6002024 = "เหรียญยืนเคียงข้างฉัน สัตว์อสูรที่ดุร้ายด้วยร่างกายที่แข็งแรงและการเคลื่อนไหวที่รวดเร็ว แต่สิ่งที่น่าสะพรึงกลัวอย่างแท้จริงของผู้คนคือแหลมหางที่แหลมคมและมีพิษ",
  str_item_intro_6002025 = "เหรียญยืนเคียงข้างฉัน เหมือนผู้ส่งสารจากนรก มายังโลกนี้ด้วยความพิโรธ โลกใต้พิภพไม่ใช่ที่ที่มันเป็น แต่เป็นวัฏจักรแห่งความตายและการกลับชาติมาเกิด",
  str_item_intro_6001500 = "เหรียญยืนเคียงข้างฉัน\nเสียงกว้างขวาง, บานชื่นในยุคที่สมบูรณ์ ลุกขึ้น ฟังเสียงสะท้อนเหมือนกลอน ลมตะวันออกพาเสียงดอกไม้สะพรั่ง ในศาลา, ช่วงเวลาที่สวยงาม",
  str_item_intro_6001507 = "เหรียญยืนเคียงข้างฉัน\nในแดนเหนือ, บางเกล็ดหิมะตกใหม่และบางอันยืนยาวมานับเอียน หมวดหมู่ใดที่เหรียญนี้ที่คุณถืออยู่เป็นส่วนหนึ่ง?",
  str_item_intro_6001508 = "เหรียญยืนเคียงข้างฉัน\nทุกการผจญภัยที่เราผ่านมาจะเป็นที่รักและเก็บไว้ในใจ",
  str_item_intro_6001510 = "ดอกไม้บริสุทธิ์นี้สวยงามและบริสุทธิ์มาก\nเหมือนเธอเลย",
  str_item_intro_6001511 = "เหรียญยืนเคียงข้างฉัน ด้วยปัญญาที่ไม่ธรรมดา คนหนึ่งสามารถสร้างเรือเพื่อเชื่อมต่อแดนที่ห่างไกลหรือสร้างอาวุธเพื่อปล่อยความวุ่นวาย ในช่วงเวลาเช่นนี้ ปัญญาที่แท้จริงคือการเลือกของคนนั้น",
  str_item_intro_6000620 = "เหรียญยืนเคียงข้างฉัน\nหุ่นยนต์ยักษ์สำหรับการต่อสู้ที่ถูกสร้างขึ้นโดย Illumina มีโครงสร้างที่แข็งแกร่งและพลังปืนที่น่าเกรงขาม อย่างไรก็ตาม จุดอ่อนของยักษ์พวกนี้มักถูกซ่อนอยู่ใต้ผิว...",
  str_item_intro_6000621 = "เหรียญยืนเคียงข้างฉัน ป้อมปืนที่คอยปกป้องแนวป้องกันสุดท้าย กำจัดศัตรูที่เข้ามาทั้งหมด",
  str_item_intro_6001512 = "เหรียญยืนเคียงข้างฉัน ทุกคนต่างต้องการมัน แต่ไม่ใช่ทุกคนที่สามารถรับรองภาระของมันได้",
  str_item_intro_6001515 = "เหรียญยืนเคียงข้างฉัน\nเครื่องจักรที่เต็มไปด้วยอันตรายที่ไม่ทราบจำนวน ไม่มีใครรู้ว่ามันจะทำงานต่อไปได้นานแค่ไหน และมันมักทำเสียงฟ่องฟู่ที่น่ากลัวในกลางคืน",
  str_item_intro_6001516 = "เหรียญยืนเคียงข้างฉัน\nออโรเรียนและฟีนด์ลิ่ง พวกเขาแตกต่างกันอย่างไร? ทั้งคู่ชอบกินตุ๊กตาน้ำตาลที่หวานใต้ไฟฟ้าวันเทศกาลใบไม้ผลิ ฉลองโอกาสดีดีนี้ด้วยกัน",
  str_item_intro_6001517 = "เหรียญยืนเคียงข้างฉัน\nAlgol ได้พัฒนาสร้อยข้อมือนี้เพื่อตรวจสอบข้อมูลสุขภาพ เช่น อัตราการเต้นของหัวใจ ความดันโลหิต และความอิ่มตัวของออกซิเจนในเลือดแบบเรียลไทม์ และใช้ข้อมูลนี้ในการสร้างแผนการออกกำลังกายสำหรับผู้สวมใส่",
  str_item_intro_6001520 = "เหรียญยืนเคียงข้างฉัน \nหน้าที่ของผู้คุ้มครองมีน้ำหนักที่หนักหน่วง แต่พวกเขายินดีที่จะรับมัน และเลือกที่จะอยู่ภายในพายุหิมะ",
  str_item_intro_6001521 = "เหรียญยืนเคียงข้างฉัน\nการเสียสละไม่ควรทำเพียงเพื่อเกียรติยศ \"คุณอาจเป็นวีรบุรุษ แต่คุณยังมีค่ามากกว่านั้นอีก\"",
  str_item_intro_6001524 = "เหรียญยืนเคียงข้างฉัน\n\"นั่นสนุกมาก! ไปอีกครั้งนะ, ไปอีกครั้งนะ!\"",
  str_item_intro_6001525 = "เหรียญยืนเคียงข้างฉัน แรงบันดาลใจลุกโชนในใจฉัน ทำให้เป็นช่วงเวลาที่น่าจดจำสำหรับหนังสือบันทึก",
  str_item_intro_6001526 = "เหรียญยืนเคียงข้างฉัน\n\"พลังนี้ไม่ใช่ของฉันคนเดียว\"",
  str_item_intro_6001529 = "เหรียญยืนเคียงข้างฉัน\n\"มันผ่านมาสักพักแล้ว ผู้รับจ้างของฉัน แม้ว่าจะเต็มไปด้วยอันตราย แต่การเดินทางนี้นำไปสู่ความจริง\"",
  str_item_intro_6001530 = "เหรียญยืนเคียงข้างฉัน แม้ว่าเจ้าชายจะไม่เคยกลับมา แต่การเดินทางของเขาได้เปิดทางสู่การรอดชีวิตของประชาชนของเขา ไม่ว่าเวลาจะผ่านไปมากแค่ไหน หัวใจของพวกเขาจะเสมอมาเชื่อมต่อกัน เพราะฉะนั้น ลูกหลานของพวกเขาจะในวันหนึ่ง ไม่ว่าเร็วหรือช้า จะได้พบกันอีกครั้งบนทวีปนี้",
  str_item_intro_6001531 = "เหรียญยืนเคียงข้างฉัน\nเธอถูกบอกว่าความรักเหมือนกับฝันที่สวยงาม",
  str_item_intro_6001532 = "เหรียญยืนเคียงข้างฉัน\nมันเป็นการเดินทางที่ยากลำบาก แต่ในที่สุด มันดูเหมือนว่าคุณกำลังดูความสุขของคนอื่นที่ได้พบกันอีกครั้ง\nแต่ยังไง สำหรับความพยายามทั้งหมดของคุณในการช่วยดวงดาว ทำไมเราจึงไม่ให้ความขอบคุณอย่างลึกซึ้งของเราแก่คุณ?",
  str_item_6100001 = "กระดานที่ระลึก Stand By Me",
  str_item_6100002 = "Stand By Me แบทเทิลบอร์ด",
  str_item_6100003 = "สแตนด์บายมี ออบซิเดียน สแลบ",
  str_item_6100004 = "คณะกรรมการเครื่องจักร Stand By Me",
  str_item_intro_6100001 = "คณะกรรมการอนุสรณ์ Stand By Me. กระดานที่ระลึกที่เหมาะกับ Cloud Gardens ซึ่งสามารถแสดง Stand By Me Medallions ได้",
  str_item_intro_6100002 = "คณะกรรมการอนุสรณ์ Stand By Me. แม้ว่าภาพบนกระดานนี้จะทำให้นึกถึงสงคราม แต่ก็ไม่ได้ทำให้ใครหยุดการมอบเหรียญรางวัลให้กับมัน",
  str_item_intro_6100003 = "คณะกรรมการอนุสรณ์ Stand By Me. หินสีดำนี้ดูเหมือนอยู่ในป่า ใครย้ายมันมาที่นี่? อย่างน้อยการกระแทกเล็กน้อยก็ยอดเยี่ยมสำหรับการรักษาเหรียญให้เข้าที่",
  str_item_intro_6100004 = "คณะกรรมการอนุสรณ์ Stand By Me. พื้นหลังนี้ทำให้คุณรู้สึกเหมือนอยู่ในเครื่องจักรขนาดใหญ่หรือโรงงาน และคุณไม่สามารถต้านทานความอยากที่จะจัดเหรียญของคุณได้อย่างเรียบร้อย แต่การจัดเรียงอย่างอิสระก็เป็นไปได้เช่นกัน บางทีความเป็นธรรมชาติอาจจะรู้สึกพิเศษ?",
