  str_item_4090334 = "ความทรงจำแห่งซากุระ",
  str_item_intro_1400851 = "ผู้บันทึกเรื่องราวของอัมบราตันที่มักเป็นกลางไม่ว่าจะมีเหตุการณ์อะไร พกบันทึกจำนวนมหาศาลในกระเป๋าติดตัวตลอดเวลา ว่ากันว่าเป็นคลังข้อมูลเคลื่อนที่ของอัมบราตัน",
  str_item_intro_3000220 = "คะแนนดำเนินการ: ใช้เพื่อท้าทายด่านอีเวนต์พิเศษ ฟื้นฟูโดยอัตโนมัติเมื่อเวลาผ่านไป",
  str_item_intro_3000221 = "ผลมิสเซิลโทหายาก ชาวนอร์ธแลนด์ถือว่าเป็นสัญลักษณ์แห่งความหวังและความอุดมสมบูรณ์ ใช้เพื่อแลกเปลี่ยนเป็นของขวัญที่ตลาดต้นสน",
  str_item_intro_3000001 = "แคริเออร์แห่งแสงผลิตโดยใช้เทคนิคพิเศษ จำเป็นสำหรับการเดินทางทุกรูปแบบ",
  str_item_intro_3000002 = "เหรียญที่ออกโดยลูโมโพลิส ส่องสว่างและมีทั่วทุกที่ ผู้คนรู้จักและใช้แลกเปลี่ยนกันทั่วทั้งทวีป",
  str_item_intro_3000003 = "เพชรที่ได้จากการขัดเงาลูโมคริสตัล\nสามารถใช้เรียกออโรเรียน, แลกเปลี่ยนสำหรับ Star Flares พิเศษ และ Star Flares ตามปกติ นอกจากนี้ยังสามารถซื้อปริซึม",
  str_item_intro_3000004 = "ความรู้จากคำบัญชาก่อนหน้าและประสบการณ์รบ ยิ่งเลเวลสูงเท่าไรก็ยิ่งเชื่อมกับโคลอสซัสได้ดีเท่านั้น มีประโยชน์สำหรับการเรียนรู้โคลอสซัสให้มากขึ้น",
  str_item_intro_3000005 = "หิ่งห้อยจะฟื้นฟูอัตโนมัติ\nความเร็วการฟื้นฟูขึ้นอยู่กับคลังเก็บลูมินา\nและสามารถเพิ่มขึ้นได้โดยการหลอม\nแผ่นวัสดุโคลอสซัสในโรงงาน\nสิ่งประดิษฐ์จิ๋วนี้ทำงานภายใต้คำสั่งของ\nผู้ควบคุมโคลอสซัส มีหน้าที่ฟื้นฟูและ\nบำรุงรักษาโครงสร้างของโคลอสซัส",
  str_item_intro_3000006 = "อ่านค่าบนลูมินามิเตอร์ ทุกคนต้องสละฐานเมื่อลดลงถึง 0 ไม่อย่างนั้นอันตรายก็จะมาถึงตัว",
  str_item_intro_3000007 = "เศษชิ้นส่วนตำราโบราณที่พบในดินแดนลับ มีกลุ่มองค์กรที่สนใจพอที่จะซื้อชิ้นส่วนเหล่านี้",
  str_item_intro_3000008 = "คะแนนที่ได้รับจากการทำเควสต์ประจำวันสำเร็จ รับรางวัลพิเศษเมื่อได้คะแนนรวมถึงที่กำหนด",
  str_item_intro_3000009 = "หลักฐานความสำเร็จ",
  str_item_intro_3000010 = "ออโรเรียนจะสนิทกับคุณมากขึ้น",
  str_item_intro_3000011 = "ลูกเต๋าศักดิ์สิทธิ์",
  str_item_intro_3000012 = "โครงสร้างพิเศษที่พบใน Resource Station มันสามารถรวบรวมทรัพยากรทุกประเภทสำหรับคุณ\n(ใช้ระหว่าง Consecutive Sweep เพื่อลดปริมาณ Prism ที่ต้องใช้ในการเคลียร์ด่านและรับทรัพยากรทันที)",
  str_item_intro_3000013 = "สารพิเศษที่สร้างขึ้นโดยโรงงานโคลอสซัส หลักการทำงานของมันมาจากเทคโนโลยีโบราณ ใช้เพื่อเปลี่ยนองค์ประกอบพื้นฐานของไอเทมบางชนิดแล้วแปลงเป็นไอเทมใหม่",
  str_item_intro_3000014 = "คริสตัลธรรมชาติที่มีลูมินาอยู่ภายใน\nคุณสามารถใช้ลูโมคริสตัลในร้านค้าเพื่อซื้อแพ็กของขวัญและชุดออโรเรียน นอกจากนี้คุณยังสามารถแปลงลูโมคริสตัลเป็นลูมแอมเบอร์เพื่อเรียกออโรเรียนและกู้คืนปริซึม",
  str_item_intro_3000015 = "อัญมณีโปร่งแสงที่พบพร้อมกับฮาร์ทสโตน\nเปล่งประกายแสงแรงกล้าและสามารถแลกกับไอเทมล้ำค่า\nในร้านอัญมณีดาวได้",
  str_item_intro_3000016 = "อัญมณีดาวที่หายากยิ่งขึ้นไปอีก ล้ำค่าอย่างยิ่งยวดและเป็นที่นิยมในร้านดวงดาวสุด ๆ",
  str_item_intro_3000017 = "วัสดุที่จำเป็นต่อกิจกรรมในโคลอสซัส\nถูกแจกจ่ายโดยคลังเก็บลูมินาที่จ่าย\nพลังงานให้โคลอสซัส",
  str_item_intro_3000018 = "ชิ้นส่วนหินที่พบในส่วนต่าง ๆ ของสวนลอยฟ้าซึ่งน่าจะเป็นวัตถุโบราณ แต่ยังไม่ทราบว่าไว้ใช้ทำอะไร ชับบ์ชอบชิ้นส่วนเหล่านี้มากและจะนำของบางอย่างมาแลกด้วย",
  str_item_intro_3000019 = "อัญมณีดาวหายากที่ราคาสูงเกินกว่าคนส่วนใหญ่จะเป็นเจ้าของได้ ใช้ซื้อขายในร้านแอสทรัลเท่านั้น",
  str_item_intro_3000021 = "ดิสก์จัดเก็บข้อมูลที่ห้องบังคับการของโซรอซและซิมูเลเตอร์สร้างขึ้น ผู้นำทางสามารถใส่ความทรงจำของเขาเข้าไปเพื่อสร้างโฮโลแกรมในคลาวด์ดิสก์ของโคลอสซัส",
  str_item_intro_3000022 = "ไม้หายากและล้ำค่าที่กล่าวกันว่ามาจากต้นไม้พิเศษบางชนิด เป็นที่นิยมในหมู่ชนชั้นสูงเพราะหายากและมีรูปร่างกลมเรียบเป็นธรรมชาติ มีกิลด์ในอัมบราตันที่รับซื้อโดยเฉพาะและใช้เป็นสกุลเงินในบางพื้นที่เท่านั้น",
  str_item_intro_3000025 = "มีข่าวลือว่ามีคำพูดของ The Forsaken สิ่งประดิษฐ์ดังกล่าวยังไม่ได้รับการถอดรหัส ปล่อยให้การอ้างสิทธิ์เหล่านี้เป็นเพียงการเก็งกำไรเท่านั้น ถึงกระนั้น เงื่อนไขที่ดีของมันทำให้มันน่าสนใจสำหรับองค์กรที่แสวงหาความจริงซึ่งสนใจที่จะซื้อมัน",
  str_item_intro_3000026 = "มีข่าวลือว่ามีคำพูดของ The Forsaken สิ่งประดิษฐ์ดังกล่าวยังไม่ได้รับการถอดรหัส ปล่อยให้การอ้างสิทธิ์เหล่านี้เป็นเพียงการเก็งกำไรเท่านั้น สถานะที่กระจัดกระจายแสดงให้เห็นว่าอาจจำเป็นต้องรวบรวมชิ้นส่วนหลายชิ้นเพื่อดึงดูดผู้ซื้อที่มีศักยภาพ",
  str_item_intro_3000029 = "ที่คั่นหนังสือสีทองที่ได้รับจากผู้ที่เสร็จสิ้นหนังสืออีเวนต์พิเศษ\nสามารถแลกเป็นรางวัลในร้านค้าหนังสืออีเวนต์",
  str_item_intro_3000030 = "ที่คั่นหนังสือที่ผู้เล่นที่ผ่านหนังสืออีเวนต์พิเศษสามารถได้รับ\nสามารถแลกเป็นรางวัลในร้านค้าหนังสืออีเวนต์",
  str_item_intro_3000031 = "รายการที่ผู้เล่นที่ผ่านหนังสืออีเวนต์พิเศษสามารถรับได้\nสามารถแลกเปลี่ยนเป็นชุดปกติในร้านค้าหนังสืออีเวนต์",
  str_item_intro_3000032 = "ไอเทมที่ผู้เล่นที่ผ่านเหตุการณ์พิเศษในหนังสือสามารถรับได้\nสามารถแลกเป็นเฟอร์นิเจอร์สำหรับยานโคลอสซัสในร้านหนังสือเหตุการณ์",
  str_item_intro_3501001 = "รายการที่ใช้ในการปรับแต่งอุปกรณ์\nสารลึกลับนี้สร้างสายสัมพันธ์ที่แน่นแฟ้นระหว่างสิ่งของกับผู้ถือ แต่ต้องเก็บไว้ในภาชนะพิเศษเพื่อป้องกันไม่ให้กระจายออกไป",
  str_item_intro_3000100 = "อุปกรณ์สามารถส่งสัญญาณสำหรับสรรหา\nสามารถใช้ในการสรรหาเพื่อได้รับออโรเรียน",
  str_item_intro_3000101 = "อุปกรณ์สามารถส่งสัญญาณสำหรับสรรหาคนพิเศษ\nสามารถใช้ในการสรรหาเวลาจำกัดเพื่อได้รับออโรเรียน",
  str_item_intro_3000110 = "ไอเทมอัญเชิญเฉพาะช่วงฮาโลวีน ให้คุณอัญเชิญได้สิบครั้งในตู้อัญเชิญฮาโลวีนพิเศษ\nนี่คือไอเทมจำกัดเวลา หลังจากการอัญเชิญฮาโลวีนพิเศษสิ้นสุดลง ไอเทมนี้จะแปลงเป็น 3,000 ลูมแอมเบอร์",
  str_item_intro_3000112 = "ไอเทมอัญเชิญเฉพาะช่วงคริสต์มาส ให้คุณอัญเชิญได้ ×10 ครั้งในตู้อัญเชิญคริสต์มาส\nนี่คือไอเทมจำกัดเวลาซึ่งจะแปลงเป็น 3,000 ลูมแอมเบอร์หลังจากการอัญเชิญคริสต์มาสสิ้นสุดลง",
  str_item_intro_3000113 = "ไอเทมอัญเชิญเอ็กซ์คลูซีฟคอลแลปที่สามารถ\nใช้ในการอัญเชิญคอลแลป 10 ครั้ง\nไอเทมนี้หมดอายุได้ โปรดใช้ภายในวันที่ 26 \nมกราคม 2022 เวลา 09:00 น. (UTC+0) \nมิฉะนั้นจะหายไป \nและจะไม่แปลงเป็นไอเทมอื่นหลังจากหมดอายุ",
  str_item_intro_3000114 = "ไอเทมอัญเชิญเอ็กซ์คลูซีฟคอลแลปที่สามารถใช้ในการอัญเชิญคอลแลป 10 ครั้ง\nโปรดใช้ไอเทมจำกัดเวลานี้ภายในวันที่ 12 กุมภาพันธ์ 2022 เวลา 09:00 น. (UTC+0) มิฉะนั้นจะหายไปและจะไม่แปลงเป็นไอเทมอื่น",
  str_item_intro_3000343 = "ไอเทมอัญเชิญเอ็กซ์คลูซีฟคอลแลปที่สามารถใช้ในการอัญเชิญคอลแลป 10 ครั้ง\nโปรดใช้ไอเทมจำกัดเวลานี้ก่อนวันที่ 7 พฤศจิกายน 2022 เวลา 09:00 น. (UTC+0) หรือ 04:00 น. (UTC-5) มิฉะนั้นจะหมดอายุ และจะไม่แปลงเป็นไอเทมอื่น",
  str_item_intro_3000115 = "ไอเทมอัญเชิญเฉพาะคาร์นิวัลพิเศษ ให้คุณอัญเชิญได้ ×10 ครั้งในตู้อัญเชิญคาร์นิวัลพิเศษ\nเป็นไอเทมจำกัดเวลาซึ่งจะแปลงเป็น 3,000 ลูมแอมเบอร์หลังจากการอัญเชิญคาร์นิวัลพิเศษสิ้นสุดลง",
  str_item_intro_3000116 = "สามารถใช้ในการอัญเชิญเอ็กซ์คลูซีฟแสงกระจ่างจุดประกาย 1 ครั้ง\nไอเทมนี้หมดอายุได้ โปรดใช้ก่อนสิ้นสุดการอัญเชิญเอ็กซ์คลูซีฟแสงกระจ่างจุดประกาย มิฉะนั้นจะหายไป และจะไม่แปลงเป็นไอเทมอื่นหลังจากหมดอายุ",
