  str_item_intro_3000141 = "สามารถใช้เพื่อรับสมัคร 10 ครั้งในการรับสมัครเฉพาะของ Enlightened Illumination หรือการรับสมัครที่แนะนำของ Lone Vigilante\nไอเทมนี้หมดอายุได้ ดังนั้นโปรดใช้ก่อนที่การรับสมัครเหล่านี้จะสิ้นสุด มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นไอเทมอื่นเมื่อหมดอายุ",
