  str_item_intro_3000122 = "อนุญาตให้คุณเกณฑ์สิบครั้งจาก Winter Glaze Special Recruitment\nไอเทมจำกัดเวลาจะถูกแปลงเป็น 3,000 Lumamber เมื่อสิ้นสุดการรับสมัครพิเศษ Winter Glaze",
  str_item_intro_3000123 = "สามารถใช้ในการเกณฑ์ครั้งเดียวจากการรับสมัครเฉพาะของ Queen of the North ปัจจุบัน\nรายการนี้จะหมดอายุ ดังนั้นโปรดใช้ก่อนที่จะสิ้นสุดการรับสมัครเฉพาะของ Queen of the North ปัจจุบัน มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นรายการอื่นเมื่อหมดอายุ",
  str_item_intro_3000124 = "นี่ไม่ใช่สมุดลายเซ็นธรรมดาเพราะมันมีลายเซ็นของโกลดี้! คุณจะมีความสัมพันธ์ลึกลับกับไอดอลคนนี้เพียงแค่มีหนังสือเล่มนี้!\nสามารถใช้รับสมัครได้ครั้งเดียวจากการรับสมัครพิเศษของ Lucky Star\nรายการนี้จะหมดอายุ ดังนั้นโปรดใช้ก่อนที่จะสิ้นสุดการรับสมัครพิเศษของ Lucky Star มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นรายการอื่นเมื่อหมดอายุ",
  str_item_intro_3000125 = "อนุญาตให้คุณรับสมัครสิบครั้งจากการเกณฑ์พิเศษเทศกาลฤดูใบไม้ผลิ\nไอเทมจำกัดเวลาจะถูกแปลงเป็น 3,000 Lumamber เมื่อสิ้นสุดการรับสมัครพิเศษเทศกาลฤดูใบไม้ผลิ",
  str_item_intro_3000126 = "อนุญาตให้คุณรับสมัครสิบครั้งจากการเกณฑ์พิเศษหน่วยลาดตระเวน ไอเทมจำกัดเวลา จะถูกแปลงเป็น 3,000 Lumamber เมื่อสิ้นสุดการรับสมัครพิเศษของ Patrol Squad",
  str_item_intro_3000127 = "สามารถใช้รับสมัครได้ครั้งเดียวจากการรับสมัครพิเศษของ Lustrous Soul\nรายการนี้จะหมดอายุ ดังนั้นโปรดใช้ก่อนที่จะสิ้นสุดการรับสมัครพิเศษของ Lustrous Soul มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นรายการอื่นเมื่อหมดอายุ",
  str_item_intro_3000128 = "สามารถใช้เพื่อรับสมัครสิบครั้งจากการรับสมัครเฉพาะของ Lustrous Soul\nรายการนี้จะหมดอายุ ดังนั้นโปรดใช้ก่อนที่จะสิ้นสุดการรับสมัครพิเศษของ Lustrous Soul มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นรายการอื่นเมื่อหมดอายุ",
  str_item_intro_3000129 = "ให้คุณสามารถสรรหาได้สิบครั้งจากการสรรหาพิเศษงานเฉลิมฉลอง\nไอเทมจำกัดเวลา หลังจากการสรรหาพิเศษงานเฉลิมฉลองจบ มันจะถูกแปลงเป็น 3,000 ลูมแอมเบอร์",
  str_item_intro_3000133 = "อนุญาตให้คุณเกณฑ์สิบครั้งจาก Winter Ode Special Recruitment\nไอเทมจำกัดเวลาจะถูกแปลงเป็น 3,000 Lumamber เมื่อสิ้นสุดการรับสมัครพิเศษ Winter Ode",
  str_item_intro_3000138 = "อนุญาตให้คุณรับสมัครสิบครั้งจากการเกณฑ์พิเศษเทศกาลพิเศษ\nไอเทมจำกัดเวลา จะถูกแปลงเป็น 3,000 Lumamber เมื่อสิ้นสุดการรับสมัครพิเศษเทศกาลพิเศษ",
  str_item_intro_3000201 = "ตราเล็ก ๆ ที่ทำขึ้นโดยสมาชิกเรดีเซล เวรนช์ จากการปรับแต่งนอต พวกเขาเชื่อว่าตรานี้เป็นตัวแทนการยอมรับในทะเลทราย ดังนั้นจึงมีไว้สำหรับคนที่เรดีเซล เวรนช์ยอมรับเท่านั้น",
  str_item_intro_3000211 = "บัตรของขวัญที่สามารถแลกเป็นของขวัญพิเศษได้ที่แผนกต้อนรับของโรงแรมทีร์ ว่ากันว่าตราประทับที่หน้าบัตรเป็นภาพวาดผู้จัดการทั่วไปของโรงแรม",
  str_item_intro_3000212 = "หลังจากทำเควสต์ต่าง ๆ ในหนังสืออีเวนต์พิเศษเสร็จสมบูรณ์ คุณจะได้รับคะแนนการมีส่วนร่วมอัมบราตันในจำนวนที่กำหนด ซึ่งสามารถใช้ปลดล็อกรางวัลได้ อัมบราตันมีรอยยิ้มให้กับนักผจญภัยผู้กล้าที่จะฝันเสมอ",
  str_item_intro_3000213 = "คะแนนดำเนินการ: ใช้เพื่อท้าทายด่านอีเวนต์บางด่าน คะแนนดำเนินการจะฟื้นฟูโดยอัตโนมัติเมื่อเวลาผ่านไป",
  str_item_intro_3000214 = "อาหารพิเศษที่สหภาพผู้ส่งสารแจกจ่ายเพื่อเสริมพลังงานให้กับผู้ส่งสารที่ทำงานหนัก รสชาติของแต่ละซองจะเป็นปริศนาจนกว่าจะเปิดออก... ลองชิมดูสักครั้งก็ได้นะ",
  str_item_intro_3000215 = "ความคืบหน้าการตกแต่งห้องใหม่ (ยังไม่มีรายละเอียดในขณะนี้)",
  str_item_intro_3000217 = "คุณความดี คือ ความสำเร็จทางการทหารของบุคคลที่แสดงให้เห็นเป็นรูปธรรม เป็นเครื่องแสดงถึงคุณูปการของทหารที่มีต่อสหพันธรัฐอิลลูมินา",
  str_item_intro_3000219 = "อดทนต่อความเจ็บปวดจากการต่อสู้และพิสูจน์ตัวเองด้วยหยาดเหงื่อและเลือดเนื้อในอารีน่าใต้ดิน! ให้ชื่ออันรุ่งโรจน์ของคุณกึกก้องไปทั่วอัมบราตัน!",
  str_item_intro_3000202 = "ไอเทมอีเวนต์ สามารถใช้ได้ในอีเวนต์จับรางวัลดารุมะ สแมช เก็บรวบรวมให้ได้จำนวนที่กำหนดเพื่อปลดล็อกเนื้อเรื่องพิเศษของฮิอิโระ\nกลีบซากุระเมฆาที่ร่วงหล่นนี้เป็นของพิเศษบนภูเขาเมฆา ผู้อยู่อาศัยบนภูเขาเมฆาต่างเชื่อว่านำความโชคดีมาให้",
  str_item_intro_3000224 = "ไอเทมอีเวนต์ออโรรานิรันดร์กาล สะสมให้ได้จำนวนหนึ่งเพื่อรับรางวัลบันไดสู่ความรุ่งโรจน์",
  str_item_intro_3000225 = "ไอเทมวันหยุดของเมดมังกรสำหรับจับรางวัลในโทรุคิทเช่น\nอาหารร้อน ๆ ใกล้เสร็จแล้ว เตรียมจานให้พร้อมนะ!",
  str_item_intro_3000226 = "เครื่องดื่มที่มีไม่มากนักในแอสตรา ผู้ที่ดื่มจะรู้สึกกระปรี้กระเปร่า",
  str_item_intro_3000227 = "เหรียญที่ดูเก่า ต่างจากเหรียญที่เห็นในปัจจุบัน",
  str_item_intro_3000229 = "เหรียญเชิดชูเกียรติสำหรับนักสำรวจและนักผจญภัย มักจะได้มาโดยความพยายามอันสุดแสนจะลำบากหรือเอาชนะความทุกข์ยากใหญ่หลวง",
  str_item_intro_3000236 = "คะแนนที่ได้จากการพิชิตความท้าทาย โดยคะแนนจะมากน้อยแตกต่างกันไปตามระดับความยากแต่ละระดับ",
  str_item_intro_3000238 = "ในงานเทศกาล ชาวเกาะเมฆาจะเขียนคำอวยพรลงบนกระดาษแผ่นนี้เพื่อขอพรให้มีความสุขตลอดปี",
  str_item_intro_3000239 = "เป็นที่ชื่นชอบของชาวตะวันออกไกล ดูน่ารักและพกพาสะดวก มักจะเสิร์ฟพร้อมเครื่องเคียง",
  str_item_intro_3000240 = "ไอเทมสำหรับกระจกอธิษฐาน \"แพรไหมชวนฝัน\" โดยเฉพาะ ให้คุณสามารถอธิษฐานกับกระจกอธิษฐานของ \"แพรไหมชวนฝัน\"\nนี่คือไอเทมจำกัดเวลา หลังจากกระจกอธิษฐาน \"แพรไหมชวนฝัน\" สิ้นสุดลงแล้ว ไอเทมนี้จะแปลงเป็น 100 ลูมแอมเบอร์",
  str_item_intro_3000241 = "เหรียญเงินนี้เป็นสกุลเงินหลักบนเกาะเมฆา",
  str_item_intro_3000242 = "การ์ดบันทึกประวัติผลงานของผู้เข้าแข่งขันแต่ละคน และมีลายเซ็นของเจ้าหน้าที่ประจำเช็กพอยต์แต่ละจุด",
  str_item_intro_3000244 = "มีพลังงานที่อธิบายไม่ได้ สามารถช่วยให้ผู้คนที่ติดกับได้รับอิสระและหลุดพ้นจากพันธนาการ...",
  str_item_intro_3000245 = "กล่าวกันว่าเป็นผลิตภัณฑ์ของชิ้นส่วนวิญญาณบางชนิดในวาร์ป เป็นที่สนใจอย่างมากสำหรับคนบางกลุ่ม",
  str_item_intro_3000246 = "ข้อมูลที่ได้รับหลังจากการหาปริมาณและประมวลผลรอบด้าน ใช้ร่างขอบเขตการค้นหาได้",
  str_item_intro_3000247 = "สัญญาณปกติที่เครื่องตรวจจับพกพาจับได้",
  str_item_intro_3000248 = "สัญญาณพิเศษที่เครื่องตรวจจับพกพาจับได้",
  str_item_intro_3000253 = "ตั๋วที่ออกโดยสมาคมแอนเดอร์เซนที่เคยเรืองอำนาจในอดีต หากคุณหาคนที่ยินดีจะรับรองได้ ก็ใช้ตั๋วนี้แลกสิ่งต่าง ๆ ได้",
  str_item_intro_3000256 = "คะแนนที่ใช้ในการโจมตีที่ซ่อนตัวของพวกโจร เอาชนะศัตรูที่พบเจอและเดินหน้าไปเรื่อย ๆ!",
  str_item_intro_3000258 = "เป็นข่าว เกร็ดเล็กเกร็ดน้อย และเรื่องซุบซิบ ที่จดไว้คร่าว ๆ ถ้าอยากรู้เรื่องราวทั้งหมด แค่ทำตามภาพและค้นหาด้วยตัวคุณเอง",
  str_item_intro_3000259 = "ในงานประจำปีฮาร์เบอร์แฟร์ เมืองฮาร์เบอร์จะแจกเหรียญพิเศษที่ใช้แทนเงินในสตรีทแฟร์ให้กับชาวเมืองทุกคน",
  str_item_intro_3000266 = "อควาเรียมเปิดใหม่! มีอุปกรณ์และสัตว์น้ำทุกชนิดเท่าที่คุณจะจินตนาการได้ และคนน้อยมากด้วย! พลาดไม่ได้แล้ว รีบไปดูกันเถอะ!\nไอเทมพิเศษสำหรับอธิษฐานใน \"เที่ยวอควาเรียม\" ซึ่งเป็นไอเทมจำกัดเวลา เมื่ออีเวนต์ \"เที่ยวอควาเรียม\" สิ้นสุดลง ไอเทมนี้จะแปลงเป็น 100 ลูมแอมเบอร์",
  str_item_intro_3000267 = "สัญญาณปกติที่เครื่องตรวจจับพกพาจับได้",
  str_item_intro_3000268 = "สัญญาณพิเศษที่เครื่องตรวจจับพกพาจับได้",
  str_item_intro_3000270 = "มีนักมายากลคนหนึ่งกล่าวว่า ไพ่ที่ดูแสนจะธรรมดานี้มีพลังวิเศษที่ทำให้เขาแปลงร่างเป็นสิ่งต่าง ๆ ได้!\nรับได้โดยการใช้ปริซึมเคลียร์ด่านในช่วงอีเวนต์",
  str_item_intro_3000271 = "ปลอกกระสุนเปล่าที่นำกลับมาใช้ใหม่ได้ ซึ่งสามารถแลกเปลี่ยนได้ที่ Supply Depot สำหรับเสบียง\nได้มาจากการใช้ Prism เพื่อเคลียร์ด่านระหว่างกิจกรรม",
  str_item_intro_3000275 = "ตั๋วใบนี้ไม่เพียงแต่ให้คุณชมภาพยนตร์ล่าสุดของนักแสดงชื่อดังบางคนเท่านั้น แต่ยังให้คุณได้สัมภาษณ์ตัวต่อตัวกับพวกเขาอีกด้วย!\nไอเท็มกิจกรรม Under the Spotlight สุดพิเศษที่สามารถใช้ขอพรได้ ไอเทมจำกัดเวลานี้จะถูกแปลงเป็น 100 Lumamber เมื่อกิจกรรม Under the Spotlight สิ้นสุดลง",
  str_item_intro_3000276 = "อุปกรณ์ประกอบฉากเหมือนเหรียญที่ทำโดย Nina เพื่อเพิ่มบรรยากาศที่น่ากลัวของบ้านผีสิง สามารถใช้แลกของที่ระลึกได้",
  str_item_intro_3000278 = "ชิ้นส่วนที่ถูกทิ้งเกลื่อนกลาดไปทั่ว บางทีพวกเขาอาจจะใช้ประโยชน์ได้บ้าง!\nได้รับจากการใช้ Prism เพื่อเคลียร์ด่านระหว่างกิจกรรม",
  str_item_intro_3000280 = "รายการรีรันพิเศษ Fluffy Serendipity ส่องกระจกเพื่อขอพร\nนี่เป็นรายการที่มีเวลาจำกัด เมื่อการฉายซ้ำ Fluffy Serendipity - Wishing Mirror หมดอายุ ไอเทมนี้จะถูกแปลงเป็น Lumamber 100 ชิ้น",
  str_item_intro_3000281 = "ตำนานกล่าวขานว่าเป็นผลงานของผู้กำกับอัจฉริยะ เขาหัวเราะหนักมากเมื่อได้ชมภาพยนตร์ที่จบแล้วของเขาเป็นครั้งแรกที่เขาเสียชีวิต",
  str_item_intro_3000282 = "ดูเหมือนว่าจะเป็นสคริปต์สำหรับการผจญภัยแฟนตาซี แม้ว่าบางส่วนจะค่อนข้างโรแมนติกและเต็มไปด้วยจินตนาการ",
  str_item_intro_3000283 = "สคริปต์นี้ดูเหมือนจะเป็นการดัดแปลงจากเรื่องจริง อย่างไรก็ตาม เนื่องจากไม่มีใครรู้ชะตากรรมสุดท้ายของตัวเอกดั้งเดิม ตอนจบจึงเหลือขึ้นอยู่กับการตีความทางศิลปะของนักเขียน",
  str_item_intro_3000284 = "สคริปต์ที่ Jomu แอบเข้าไปในมือคุณอย่างลึกลับ เขาพูดถึงบางอย่างเกี่ยวกับการชดเชยที่หนักหน่วงเมื่อ \"พูดและทำเสร็จแล้ว\"",
  str_item_intro_3000285 = "สคริปต์ที่ลิลิกามอบให้คุณ ด้วยความเชื่อว่าคุณมีศักยภาพในการกำกับ เธอจึงมอบหมายงานให้คุณถ่ายวิดีโอโปรโมตให้",
  str_item_intro_3000286 = "สคริปต์ที่วิเวียนมอบให้คุณ ตามที่เธอกล่าว มันเป็นความพยายามครั้งล่าสุดของสหพันธ์ Illumina เพื่อสนับสนุนความพยายามในการสรรหาบุคลากร",
  str_item_intro_3000288 = "สมุดที่เต็มไปด้วยความคิดที่คุณและเบธเลเฮมคิดค้นขึ้นระหว่างการสร้างฝัน\nไอเท็ม Exclusive Sweet Melody's Embrace จำเป็นสำหรับการขอพรในช่วง Sweet Melody's Embrace นี่เป็นรายการที่มีเวลาจำกัด เมื่อ Sweet Melody's Embrace สิ้นสุดลง ไอเทมนี้จะถูกแปลงเป็น 100 Lumamber",
  str_item_intro_3000291 = "บันทึกสิ่งที่ค้นพบระหว่างการเดินทางของคุณ ด้วยสิ่งนี้ คุณจะสามารถเรียกคืนข้อมูลสำคัญได้มากมายแม้หลังจากที่คุณกลับถึงบ้านแล้ว",
  str_item_intro_3000292 = "คุณจะพลาดสินค้าสุดพิเศษสำหรับไอดอลที่โด่งดังที่สุดในทวีปได้อย่างไร! นักฉวยโอกาสจะต้องมองหาการสร้างรายได้อย่างรวดเร็วจากแฟนตัวยงด้วยสินค้าพิเศษเช่นนี้อย่างแน่นอน",
  str_item_intro_3000293 = "รายการ Northland แบบดั้งเดิม ในคืนก่อนเทศกาลฤดูหนาว เด็กๆ จะแขวนถุงน่องจากเตียงและเขียนจดหมายระบุสิ่งที่พวกเขาต้องการมากที่สุด เช้าวันต่อมา ของขวัญที่พวกเขาอยากได้ก็ปรากฎอยู่ในถุงน่อง! ส่วนใครวางไว้ตรงนั้น ใครจะรู้?",
  str_item_intro_3000294 = "การ์ดเปล่าใบนี้ดูเหมือนจะมีพลังเวทย์มนตร์บางอย่าง ตำนานกล่าวว่าถ้าคุณเขียนความปรารถนาของคุณบนนั้น มันจะเป็นจริง แม้ว่ามันจะยากที่จะเชื่อคำกล่าวอ้างที่อุกอาจเช่นนี้ แต่ใครเล่าจะมีโอกาสได้รับพรเช่นนี้?",
  str_item_intro_3000297 = "สคริปต์นี้ได้รับจากบุคคลนิรนามดูเหมือนจะมีเรื่องราวที่น่าตื่นเต้นและโรแมนติก\nแต่เรื่องราวในนั้นดูคุ้นเคยด้วยเหตุผลบางอย่าง...",
  str_item_intro_3000298 = "สคริปต์ที่ดัดแปลงมาจากเรื่องราวที่เล่าขานกันทั่วโลก คุณจะพบเรื่องราวเกี่ยวกับอันตรายและสิ่งชั่วร้ายทุกประเภทที่นี่",
  str_item_intro_3000299 = "หนังสือนิทานที่ได้รับความนิยมมากที่สุดเล่มหนึ่งบนเกาะคลาวด์ในขณะนี้ คุณได้รับสิ่งนี้จากบุคคลลึกลับที่ข้ามมหาสมุทร\nเมื่อมองแวบแรก ดูเหมือนว่าจะเป็นเรื่องราวเกี่ยวกับการต่อสู้ด้วยดาบและวันโลกาวินาศที่กำลังจะมาถึง...",
  str_item_intro_3000300 = "เช็คจาก Lin Guild สามารถแลกเป็นสินค้าได้ที่ The Docks ตามจำนวนที่ระบุไว้ข้างต้น",
  str_item_intro_3000307 = "เศษปูนปลาสเตอร์ที่ดูแปลกประหลาดซึ่งดูเหมือนว่าจะหลุดออกจากรูปปั้น อาจมีเงื่อนงำบางอย่าง...",
  str_item_intro_3000311 = "ตำนานเล่าว่าหากคุณดื่มอวยพรผู้อื่นในขณะที่ดื่มจากแก้วอันโอ่อ่านี้ คุณจะสร่างเมาตลอดทั้งคืน\nรายการพิเศษเฉพาะ Mesmerizing Eventide ใช้ในช่วงกิจกรรมเพื่อขอพร! นี่เป็นไอเทมจำกัดเวลา และจะเปลี่ยนเป็น 100 Lumamber เมื่อกิจกรรม Mesmerizing Eventide สิ้นสุดลง",
  str_item_intro_3000313 = "สกุลเงินที่ใช้ใน Illumina Supply Center มันเป็นเพียงหลักฐานของการขนส่งและการติดตั้งเสบียง",
  str_item_intro_3000321 = "สิ่งเหล่านี้ดูเหมือนจะเป็นชิ้นส่วนของคริสตัลที่น่าสงสัย ซึ่งมีหยดน้ำที่น่าสงสัยยิ่งกว่านั้น\nใช้: คุณสามารถซื้อรายการที่คุณต้องการในห้องทำนาย\nที่มา: ทำเนื้อเรื่องหลักหรือด่าน Raid ทรัพยากรให้สำเร็จซึ่งต้องใช้ปริซึม",
  str_item_intro_3000326 = "เหรียญที่ดูงดงามแต่กลับมีกลิ่นอายอันตราย...ก็คุณร็อตบอกว่ามันแลกกับอะไรบางอย่างได้ก็น่าจะโอเค...\nที่มา: ทำภารกิจของ Ms. Rot ให้สำเร็จ",
  str_item_intro_3000330 = "ดอกไม้ที่ถูกพันธนาการด้วยหนามจะผลิบานหรือไม่นั้นขึ้นอยู่กับดอกไม้นั้นทั้งหมด ไม่ได้ขึ้นอยู่กับสิ่งที่โลกคิดเกี่ยวกับดอกไม้นั้น ไอเท็มพิเศษจากกิจกรรม Blooming Firethorn สามารถใช้ขอพรได้ในช่วงเทศกาลดอกไม้ไฟ นี่เป็นไอเทมจำกัดเวลา และจะเปลี่ยนเป็น 100 Lumamber เมื่อกิจกรรม Blooming Firethorn สิ้นสุดลง",
  str_item_intro_3000332 = "งานสะสมกันเป็นภูเขาในขณะป้องกันการรบกวนของอิคลิพไซท์และติดตามการเคลื่อนไหวข้างหน้า... ทั้งหมดนี้ทำให้วราธ: กระตือรือร้นในความภาคภูมิต้องตัดสินใจจัดการกำลังคนจำนวนน้อยอย่างรอบคอบเพื่อการฟื้นฟู Twilight บางส่วนเท่านั้น",
  str_item_intro_3000334 = "การยอมรับของบาร์ตันต่อกลยุทธ์ของวราธ",
  str_item_intro_3000335 = "การยอมรับของฮิอิโระต่อกลยุทธ์ของวราธ",
  str_item_intro_3000336 = "การยอมรับของวิเวียนต่อกลยุทธ์ของวราธ",
  str_item_intro_3000337 = "การยอมรับของชาโรนาต่อกลยุทธ์ของวราธ",
  str_item_intro_3000353 = "คำอธิษฐานของคุณจะเป็นจริงในวันหนึ่ง",
  str_item_intro_3000354 = "สะสมจำนวน Divergent Cocoons บางจำนวนและแลกเปลี่ยนเป็นของขวัญที่ Exchange Center",
  str_item_intro_3000356 = "ธูปที่ได้รับความนิยมในราชอาณาจักรจิ ออกแบบอย่างรอบคอบด้วยกลิ่นหอมอ่อนๆ\n\"เมื่อธูปเผาขึ้นส่งควันขึ้นสู่ท้องฟ้า คนๆหนึ่งส่งของสังเวยสู่สวรรค์และโลก - เฉินนี่เข้าใจประเพณีนี้ แต่มีวันที่ควันหนาแน่นจนเฉินนี่ไม่สามารถเปิดตาได้...\"",
  str_item_intro_3000361 = "การเก็บรวบรวมและจัดเรียงข้อมูลที่ได้รับความเสียหายจากการทำงานผิดพลาดจะต้องใช้ความพยายามมาก\nเมื่อมีการใช้จ่ายจำนวนที่กำหนด ด่านการซ่อมแซมภาพถ่ายใหม่จะถูกปลดล็อก",
  str_item_intro_3000366 = "รายการจำเป็นสำหรับการทำสัญญากับออโรเรียนที่เฉพาะเจาะจง",
  str_item_intro_3000367 = "อมยิ้มพิเศษจาก Umbraton ที่มีรสชาติเปลี่ยนแปลงแบบสุ่ม มอบความประหลาดใหม่ๆ อย่างไม่รู้จบ ในความขัดสนของทะเลทราย ความคุ้มค่าของลูกอมนี้เทียบเท่ากับทองคำ",
  str_item_intro_3000368 = "ชุดอุปกรณ์ที่เตรียมไว้สำหรับผู้นำทางทุกคนที่ทำงานหนัก\nความพยายามและการเติบโตของคุณทั้งหมดจะถูกบันทึกและได้รับรางวัล",
  str_item_intro_3000374 = "เหรียญเกมที่มีลักษณะคล้ายความทรงจำและหยาบต่อสัมผัส มีคำกล่าวว่าผู้เล่นที่ดีที่สุดต้องการเพียงหนึ่งเหรียญเพื่อเล่นตลอดคืน",
  str_item_intro_3000376 = "สามารถแลกเปลี่ยนเป็นบัตรคูปองสินค้าประจำวันในเมืองแกนน่อน ผู้ที่มีการสนับสนุนพิเศษต่อ Illumina ยังสามารถใช้มันเพื่อสมัครรับสินค้าที่ปรับแต่งเป็นส่วนบุคคลได้",
  str_item_intro_3000377 = "ตามตำนานที่เล่ามา โลหิตของนักบุญจะไม่ไหลไปโดยสาปสูญ แต่จะยังคงอยู่ตลอดกาล เหมือนกับอำพัน การถวายมันให้กับความจริงก็เหมือนกับการถวายความอุทิศตนให้แก่พระเจ้า",
  str_item_intro_3000381 = "ตื่นขึ้นจากความฝันที่ยิ่งใหญ่ น้ำค้างที่ควบแน่นระหว่างใบไม้หายไปในทันทีเหมือนกับความฝันสวยงามที่คุณไม่สามารถกลับไปในนั้นได้อีก นำมันไปเสนอให้กับมังกรมิราจในความฝันเพื่อความเป็นไปได้ที่จะได้รับรางวัล",
  str_item_intro_3000383 = "ความมหัศจรรย์ของวินเดเลียนกลับมามีชีวิตด้วยกระดาษสีของ Eraveil ลักษณะที่นุ่มและทนทานเหมาะสมสำหรับการสร้างเครื่องประดับที่ไม่ซ้ำใครหรือตุ๊กตาวินเดเลียน มันเป็นภาชนะสำหรับความทรงจำที่รักษาไว้และเป็นแรงปลุกสำหรับฝันที่ยังไม่เกิดขึ้น",
  str_item_intro_3100001 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุไม้\nแจสเปอร์เขียว เพ่งสมาธิเมื่อใช้เพื่อฟื้นความทรงจำในการต่อสู้และรับ EXP เล็กน้อย",
  str_item_intro_3100002 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุไม้\nแจสเปอร์เขียวล้ำค่า ใช้เพื่อให้เห็นภาพการต่อสู้เกิดขึ้นในหัวและรับ EXP ปานกลาง",
  str_item_intro_3100003 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุไม้\nแจสเปอร์เขียวล้ำค่าสูงส่ง ใช้เพื่อย้อนการต่อสู้ในอดีตคืนมาอีกครั้งและรับ EXP มหาศาล",
  str_item_intro_3100004 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุน้ำ\nแจสเปอร์น้ำเงิน เพ่งสมาธิเมื่อใช้เพื่อฟื้นความทรงจำในการต่อสู้และรับ EXP เล็กน้อย",
