  str_item_intro_3100006 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุน้ำ\nแจสเปอร์น้ำเงินล้ำค่าสูงส่ง ใช้เพื่อย้อนการต่อสู้ในอดีตคืนมาอีกครั้งและรับ EXP มหาศาล",
