  str_item_intro_3100008 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุสายฟ้า\nแจสเปอร์เหลืองล้ำค่า ใช้เพื่อให้เห็นภาพการต่อสู้เกิดขึ้นในหัวและรับ EXP ปานกลาง",
