  str_item_intro_3100011 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุไฟ\nแจสเปอร์แดงล้ำค่า ใช้เพื่อให้เห็นภาพการต่อสู้เกิดขึ้นในหัวและรับ EXP ปานกลาง",
  str_item_intro_3100012 = "ใช้เพิ่มเลเวลออโรเรียน +50% EXP ให้ออโรเรียนธาตุไฟ\nแจสเปอร์แดงล้ำค่าสูงส่ง ใช้เพื่อย้อนการต่อสู้ในอดีตคืนมาอีกครั้งและรับ EXP มหาศาล",
  str_item_intro_3100013 = "ใช้เพื่อเพิ่มเลเวลออโรเรียน\nแจสเปอร์เทาหม่นที่มีพลังงานพิเศษ ออโรเรียนทุกรายสามารถใช้รับ EXP เล็กน้อยได้",
  str_item_intro_3100014 = "ใช้เพื่อเพิ่มเลเวลออโรเรียน\nแจสเปอร์เทาหม่นล้ำค่า\nออโรเรียนทุกรายสามารถใช้เพื่อให้เห็นภาพการต่อสู้เกิดขึ้นในหัว\nและรับ EXP ปานกลาง",
  str_item_intro_3100015 = "ใช้เพื่อเพิ่มเลเวลออโรเรียน\nแจสเปอร์เทาหม่นที่หายากมาก ออโรเรียนสามารถใช้เพื่อย้อนการต่อสู้ในอดีตคืนมาอีกครั้งและรับ EXP มหาศาล",
  str_item_intro_3210101 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนลูโมโพลิส\nถูกเก็บไว้ในอุษาวิทยาลัยแห่งลูโมโพลิสและเพิ่มพลังด้วย\nเวทมนตร์เฉพาะตัว มันสามารถเพิ่มพลังให้ออโรเรียนได้",
  str_item_intro_3210201 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนอัมบราตัน\nเป็นสุราพิเศษที่นิยมกันในอัมบราตัน ทั้งแรงและละมุนลิ้น มันสามารถเพิ่มพลังให้นักดื่มคอแข็งได้",
  str_item_intro_3210301 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนนอร์ธแลนด์\nน้ำค้างยอดสนควบแน่นที่ดูดซึมธาตุอันโดดเด่นของนอร์ธแลนด์\nไว้ใช้มอบพลังยิ่งใหญ่ให้ชาวนอร์ธแลนด์",
  str_item_intro_3210401 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนเรดีเซล เวรนช์\nเรดีเซลพิเศษที่มีรสชาติเผ็ดร้อนซึ่งมีแต่สมาชิกเรดีเซล เวรนช์\nเท่านั้นที่กล้าลองชิม",
  str_item_intro_3210501 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนสหพันธรัฐ\nอิลลูมินา\nบันทึกการต่อสู้ของสหพันธรัฐอิลลูมินาที่ช่วยพัฒนาสกิล\nการต่อสู้ให้ผู้อ่าน",
  str_item_intro_3210601 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนทรู ออเดอร์\nคัมภีร์ที่บันทึกความรู้โบราณไว้ สมาชิกทรู ออเดอร์\nสามารถพัฒนาตนเองได้โดยการถอดความคัมภีร์",
  str_item_intro_3210701 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้เลื่อนขั้นออโรเรียนอิสระ\nเรื่องราวประวัติผู้คนจากหลากหลายพื้นเพที่มีศัพท์เฉพาะ\nชวนสับสน ผู้อ่านอิสระจะเรียนรู้เคล็ดลับการเอาตัวรอด\nหลายอย่าง",
  str_item_intro_3210801 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่ใช้สำหรับการเลื่อนขั้นออโรเรียนหลงโจว\nผลิตโดยโรงยาหลงโจว ยาเม็ดพิเศษนี้ช่วยเพิ่มพลังกายและเสริมกระดูกและกล้ามเนื้อ",
  str_item_intro_3210102 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนลูโมโพลิส\nถูกเก็บไว้ในอุษาวิทยาลัยแห่งลูโมโพลิส ว่ากันว่ามันสร้างขึ้นจากพลังแห่งแสงยามเช้าและสามารถเพิ่ม\nพลังให้ออโรเรียนได้อย่างมาก",
  str_item_intro_3210202 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนอัมบราตัน\nแชมเปญแห่งชะตา I แบบกลั่นบริสุทธิ์ ทั้งแรงและนุ่มลิ้นยิ่งกว่าอย่างนี้เพิ่มพลังได้มากกว่าเดิม",
  str_item_intro_3210302 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนนอร์ธแลนด์\nน้ำแข็งยอดสนควบแน่นพิเศษ ทรัพยากรหนึ่งที่สำคัญมากสำหรับเวทมนตร์นอร์ธแลนด์",
  str_item_intro_3210402 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนแห่งเรดีเซล เวรนช์\nพบได้ในใจกลางทะเลทรายเรดีเซลเท่านั้น มันจะช่วยเพิ่มความสามารถในการต่อสู้ของสมาชิกเรดีเซล เวรนช์",
  str_item_intro_3210502 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนสหพันธรัฐอิลลูมินา\nบันทึกการต่อสู้ของสหพันธรัฐอิลลูมินาพร้อมด้วยข้อมูลสำคัญที่\nช่วยพัฒนาทักษะการต่อสู้ของผู้อ่านอย่างมาก",
  str_item_intro_3210602 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนทรู ออเดอร์\nคัมภีร์ชุดที่บันทึกความรู้โบราณสำคัญไว้ สมาชิกทรู ออเดอร์สามารถพัฒนาตนเองได้อย่างมากโดยการถอดความ\nคัมภีร์",
  str_item_intro_3210702 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้เลื่อนขั้นออโรเรียนอิสระ\nเคล็ดลับจากผู้คนในหลากหลายพื้นเพสำหรับให้ผู้อ่านอิสระนำไป\nประยุกต์ใช้",
  str_item_intro_3210802 = "วัตถุดิบเลื่อนขั้นทั่วไปที่ใช้สำหรับการเลื่อนขั้นออโรเรียนลองโจว\nยาเม็ดนี้ถูกสกัดโดยผู้ปลูกลองโจวด้วยวัตถุทางจิตวิญญาณ และกล่าวว่ามีผลในการล้างเนื้อเยื่อในร่างกายของคน",
  str_item_intro_3210103 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนลูโมโพลิส\nถูกเก็บไว้ในอุษาวิทยาลัยแห่งลูโมโพลิสและเพิ่มพลังด้วยเวทมนตร์เฉพาะตัว มันสามารถเพิ่มพลังของออโรเรียนได้อีกระดับ",
  str_item_intro_3210203 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนอัมบราตัน\nแชมเปญแห่งชะตา I แบบคุณภาพดีที่สุดซึ่งมีรสชาติอันเหลือเชื่อสำหรับเพิ่มพลังอย่างมหาศาล",
  str_item_intro_3210303 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนนอร์ธแลนด์\nน่าจะเป็นคริสตัลน้ำค้างอันสมบูรณ์แบบที่มีชื่อเล่นว่า \"น้ำตานอร์ธแลนด์\" มันให้พลังงานเวทมนตร์ที่น่าสะพรึงแก่ชาวนอร์ธแลนด์",
  str_item_intro_3210403 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนแห่งเรดีเซล เวรนช์\nเรดีเซลที่บริสุทธิ์ที่สุดในรูปแบบกึ่งน้ำ มีเพียงเรดีเซล เวรนช์ที่แข็งแกร่งที่สุดเท่านั้นที่กล้าเข้าไปใกล้",
  str_item_intro_3210503 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนสหพันธรัฐ\nอิลลูมินา\nบันทึกการต่อสู้ของสหพันธรัฐอิลลูมินาที่มีข้อมูลมหาศาลซึ่งช่วย\nเพิ่มทักษะการต่อสู้ของผู้อ่านไปอีกระดับหนึ่ง",
