  str_item_intro_3210703 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้เลื่อนขั้นออโรเรียนอิสระ\nเรื่องราวและภูมิปัญญาโดยละเอียดจากผู้คนในหลากหลายพื้นเพสำหรับ\nเพิ่มการดำรงชีพอย่างยอดเยี่ยม",
  str_item_intro_3210803 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่ใช้สำหรับการเลื่อนขั้นออโรเรียนลองโจว\nสารสกัดของสวรรค์และโลกถูกสาปลงในเม็ดยานี้โดยอาจารย์ลับของลองโจว ทำให้มันมีพลังในการสร้างตัวขึ้นใหม่ บรรลุความสำเร็จ และเพิ่มความสามารถในการปลูกฝังอย่างมาก",
  str_item_intro_3201011 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุน้ำ\nละอองเรืองแสงที่มักจะพบในดินใกล้แหล่งน้ำ หนึ่งในวัตถุดิบสำหรับกระบวนการอุตสาหกรรมขนาดใหญ่",
