  str_item_intro_3201041 = "วัตถุดิบเลื่อนขั้นพื้นฐานที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียน\nธาตุสายฟ้า\nละอองเรืองแสงสื่อนำไฟฟ้าอย่างรุนแรงที่มีการใช้งานใน\nอุตสาหกรรมอย่างกว้างขวาง แม้ว่าขั้นตอนก่อนกรรมวิธี\nจะจำเป็นอย่างมากก็ตาม",
