  str_item_intro_3205012 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุน้ำ\nอัญมณีหายากที่ทำมาจากคริสตัลน้ำเงินผสมลูมินาหลายชิ้น",
  str_item_intro_3205013 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุน้ำ\nผลิตภัณฑ์ที่กลั่นจากโพชั่นธาตุน้ำ III ซึ่งเพิ่มอำนาจให้ออโรเรียนอย่างมหาศาล",
  str_item_intro_3205014 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุน้ำ\nวัตถุแข็งสร้างจากน้ำทะเลลึก งดงาม นุ่มลื่นและราคาสูงมาก",
  str_item_intro_3205021 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไฟ\nเหล็กประสานจากบล็อกเหลือบธาตุไฟแปรรูปและสารอื่น ๆ ผลิตภัณฑ์อุตสาหกรรมเกรดสูงที่สุด",
  str_item_intro_3205022 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไฟ\nอัญมณีหายากที่ทำมาจากคริสตัลแดงผสมลูมินาหลายชิ้น",
  str_item_intro_3205023 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไฟ\nผลิตภัณฑ์ที่กลั่นจากโพชั่นธาตุไฟ III ซึ่งเพิ่มอำนาจให้ออโรเรียนอย่างมหาศาล",
  str_item_intro_3205024 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไฟ\nคลัสเตอร์เงินสีแดงแข็งที่หลอมมาจากหินภูเขาไฟด้วยไฟร้อนระอุ ราคาสูงมาก",
  str_item_intro_3205031 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไม้\nเหล็กประสานจากบล็อกเหลือบธาตุไม้แปรรูปและสารอื่น ๆ ผลิตภัณฑ์อุตสาหกรรมเกรดสูงที่สุด",
  str_item_intro_3205032 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไม้\nอัญมณีหายากที่ทำมาจากคริสตัลเขียวผสมลูมินาหลายชิ้น",
  str_item_intro_3205033 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไม้\nผลิตภัณฑ์ที่กลั่นจากโพชั่นธาตุไม้ III ซึ่งเพิ่มอำนาจให้ออโรเรียนอย่างมหาศาล",
  str_item_intro_3205034 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุไม้\nคลัสเตอร์เงินที่ทำจากการผ่าและกลั่นเมล็ดพืชหายากโดยใช้วิธีลับ ราคาสูงมาก",
  str_item_intro_3205041 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุสายฟ้า\nเหล็กประสานจากบล็อกเหลือบธาตุสายฟ้าแปรรูปและสารอื่น ๆ ผลิตภัณฑ์อุตสาหกรรมเกรดสูงที่สุด",
  str_item_intro_3205042 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุสายฟ้า\nอัญมณีหายากที่ทำมาจากคริสตัลเหลืองผสมลูมินาหลายชิ้น",
  str_item_intro_3205043 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุสายฟ้า\nผลิตภัณฑ์ที่กลั่นจากโพชั่นธาตุสายฟ้า III ซึ่งเพิ่มอำนาจให้ออโรเรียนอย่างมหาศาล",
  str_item_intro_3205044 = "วัตถุดิบเลื่อนขั้นขั้นสูงที่จำเป็นสำหรับการเลื่อนขั้นออโรเรียนธาตุสายฟ้า\nวัตถุดิบเวทมนตร์ที่ได้รับมาจากเงินผสมกับกระแสไฟฟ้า แข็งอย่างมากและมีพลังสายฟ้าอยู่",
  str_item_intro_3220000 = "มีประโยชน์อย่างมากในการพัฒนาออโรเรียน\nอัญมณีหายากที่มีพลังงานลึกลับที่ส่งพลังพิเศษให้ออโรเรียน\nบางคนที่ควบคุม คนที่มีความสามารถอาจปลดล็อกได้โดยการใช้งานจนเชี่ยวชาญ",
  str_item_intro_3220001 = "วัตถุพัฒนาการที่สำคัญของนิคินิส\nอัญมณีพิเศษลักษณะคล้ายกระจก การตรวจสอบใกล้ชิด\nเผยให้เห็นภาพสะท้อนของหญิงสาวในชุดขาว",
  str_item_intro_3220002 = "วัตถุพัฒนาการที่สำคัญของฮิอิโระ\nอัญมณีล้ำค่าที่มักจะแสดงรูปมังกรสีแดงเชอร์รี่",
  str_item_intro_3220004 = "วัตถุพัฒนาการที่สำคัญของคุมะกับเพนจี้\nอัญมณีนี้ชวนให้ขนลุกเมื่อคุมะกับเพนจี้สวมใส่มัน แถมพวกเขายังชอบมากเสียด้วย",
  str_item_intro_3220005 = "วัตถุพัฒนาการที่สำคัญของมีอา\nอัญมณีนี้น่าจะกักขังอีกด้านหนึ่งของมีอาไว้ภายใน... บางทีมันอาจแสดงให้เห็นถึงตัวตนที่แท้จริงของเธอก็ได้",
  str_item_intro_3220006 = "วัตถุพัฒนาการที่สำคัญของคาร์ลีน\nอัญมณีนี้จะเปล่งแสงสีซีดสลัวรูปทรงเหมือนหอกออกมาเป็นบางครั้ง",
  str_item_intro_3220009 = "วัตถุพัฒนาการที่สำคัญของเฟาสต์\nอัญมณีลวดลายคดโค้งแปลกประหลาดที่ทำให้เกิดความตื่นกลัว ทว่าเฟาสต์กลับไม่ถอยไปแต่รู้สึกสนใจมันแทน",
  str_item_intro_3220010 = "วัตถุพัฒนาการที่สำคัญของลูอิส\nอัญมณีสว่างไสวโดดเด่นที่อ้างว่าทำให้ลูอิส คาร์ลิเซิลมีแรงบันดาลใจในการแต่งเรื่องราวนับไม่ถ้วน",
  str_item_intro_3220011 = "วัตถุพัฒนาการที่สำคัญของชาโรนา\nดูให้ดีแล้วจะเห็นภาพมังกรยักษ์เบลอ ๆ ลอยผ่านไป",
  str_item_intro_3220012 = "วัตถุพัฒนาการที่สำคัญของเนเมซิส\nอัญมณีแข็งเปี่ยมไปด้วยพลังที่เจียระไนมาอย่างสมบูรณ์แบบ",
  str_item_intro_3220013 = "วัตถุพัฒนาการที่สำคัญของโนอาห์\nแตะแล้วหนาวเย็นโดยไม่ถูกน้ำแข็งกัดหรือสร้างความเสียหายใด ๆ ของโปรดของโนอาห์เลย",
  str_item_intro_3220014 = "วัตถุพัฒนาการที่สำคัญของชวาตส์\nอัญมณีพลอยสีขาวที่เปล่งแสงจ้า ชวาตส์ไม่เพียงแต่รู้สึกว่ามันเปรียบดั่งตัวแทนของเขาแต่ยังหมายถึงลูโมโพลิสด้วย",
  str_item_intro_3220015 = "ฮาชิและกินมองเห็นสิ่งต่าง ๆ มากมายภายในอัญมณีชิ้นนี้ และได้รับแรงบันดาลใจเชิงศิลปะอย่างล้นเหลือ\nวัตถุพัฒนาการที่สำคัญของฮาชิ & กิน",
  str_item_intro_3220016 = "วัตถุพัฒนาการที่สำคัญของคาฟกา\nอัญมณีที่แข็งมาก ลือกันว่ามันปกป้องคนจากการโจมตีร้ายแรงมาก่อน",
  str_item_intro_3220017 = "วัตถุพัฒนาการที่สำคัญของแรบบี้\nตรวจสอบให้แน่ชัดแล้วจึงเผยว่าเปลวไฟกระโดดไปมาตลอดเวลานั้นคล้ายกระต่าย เครื่องรางนำโชคของแรบบี้",
  str_item_intro_3220018 = "วัตถุพัฒนาการที่สำคัญของเรจินา\nอัญมณีที่เหมือนดวงตะวันอันส่องสว่างแม้มุมมืดมิดที่สุดได้ ในขณะที่นำดนตรีของเรจินาไปไกลอีกระดับ",
  str_item_intro_3220019 = "วัตถุพัฒนาการที่สำคัญของวิกตอเรีย\nอัญมณีนี้มีอนุภาครูปร่างเหมือนน้ำตานับไม่ถ้วน น่าจะเป็นเลือดของวิกตอเรียเอง",
  str_item_intro_3220021 = "วัตถุพัฒนาการที่สำคัญของโจลา\nเมื่อโจลาแตะอัญมณีนี้ ระลอกคลื่นเขียวทรงโซ่จะระบำออกมาจากปลายอัญมณี",
  str_item_intro_3220023 = "วัตถุพัฒนาการที่สำคัญของคอนนอลลี\nการควบแน่นของหยาดฝนสีทมิฬจนค่อย ๆ เปลี่ยนรูปลักษณ์เป็นอัญมณีอดามันต์ในมือของคอนนอลลี",
  str_item_intro_3220024 = "วัตถุพัฒนาการที่สำคัญของเบนนี่กับคุโระ\nอัญมณีนี้เปล่งแสงแดงและดำ คุณอาจได้ยินเสียงดาบและกระสุนฟาดฟันกันถ้าเข้าไปใกล้มัน",
  str_item_intro_3220025 = "วัตถุพัฒนาการที่สำคัญของคารอน\nของโปรดของคารอน อัญมณีนี้เปล่งประกายแสงเป็นลายแดงและดำ",
  str_item_intro_3220026 = "วัตถุพัฒนาการที่สำคัญของอูริเอล\nอัญมณีที่เปล่งเพลิงสีดำและน้ำตาลออกมาเป็นบางครั้ง ดูแล้วก็งดงามมากแต่ก็ดูทำลายล้างสูง...",
  str_item_intro_3220027 = "วัตถุพัฒนาการที่สำคัญของมิคาเอล\nรายงานว่าถูกพบในพายุฝนฟ้าคะนองรุนแรง อัญมณีนี้มอบพลังมหาศาลให้เจ้าของผู้อัจฉริยะ",
  str_item_intro_3220028 = "วัตถุพัฒนาการที่สำคัญของราฟาเอล\nอัญมณีโปร่งแสงที่มีพลังน่าอัศจรรย์ เมื่อราฟาเอลใช้อัญมณีแล้ว ความสามารถด้านการรักษาของเธอจะเพิ่มขึ้น",
  str_item_intro_3220029 = "วัตถุพัฒนาการที่สำคัญของกาบริเอล\nอัญมณีนี้ส่องแสงสีเขียวงดงามออกมาเมื่อกาบริเอลใช้งานมัน",
  str_item_intro_3220030 = "วัตถุพัฒนาการที่สำคัญของซินซา\nอัญมณีนี้ส่งความร้อนระอุออกมาตลอดเวลา มีเพียงซินซาที่สวมใส่มันได้",
  str_item_intro_3220033 = "วัตถุพัฒนาการที่สำคัญของไวซ์\nอัญมณีนี้แสดงให้เห็นสีริบหรี่ต่างกันทีละสีราวกับว่าเศษเสี้ยวอดีต\nเปล่งแสงออกมา",
  str_item_intro_3220036 = "วัตถุพัฒนาการที่สำคัญของไฮแดรด\nอัญมณีโชคร้าย ทว่าไฮแดรดน่ะไม่กลัวและถึงขนาดโม้บ่อย ๆ ว่า \"เจ้านี่เหมือนฉันเลย\"",
  str_item_intro_3220038 = "วัตถุพัฒนาการที่สำคัญของกรอนรู\nลือกันว่าบรรจุธาตุเทียมไว้มากมาย จึงดูไม่เหมือนสิ่งของธรรมชาติแต่มีร่องรอยของอารยธรรมโบราณ",
  str_item_intro_3220040 = "วัตถุพัฒนาการที่สำคัญของโจแอนนี บูม\nเพื่อความปลอดภัย ไม่ควรไปยุ่มย่ามกับอัญมณีติดไฟนี้",
  str_item_intro_3220041 = "วัตถุพัฒนาการที่สำคัญของมิสบลังค์\nอัญมณีที่มีแสงงดงามที่มองแล้วผ่อนคลาย เหมาะสมอย่างยิ่งสำหรับหญิงสาวผู้สง่างาม",
  str_item_intro_3220042 = "วัตถุพัฒนาการที่สำคัญของบาร์ตัน\nอัญมณีนี้ปกปิดจุดสงครามเพลิงแดงที่มีเพียงบาร์ตันเท่านั้นที่เห็น หรืออาจเป็นการแสดงความต้องการลึก ๆ ในใจของเขาก็ได้",
  str_item_intro_3220044 = "วัตถุพัฒนาการที่สำคัญของวิเวียน\nอัญมณีที่มีแสงเจิดจ้า เครื่องประดับมหัศจรรย์สำหรับทำด้ามจับดาบ",
  str_item_intro_3220045 = "วัตถุพัฒนาการที่สำคัญของเนลส์\nมีคนเรียกมุมแหลมคมของอัญมณีนี้ว่าตัวแทนของการสำเร็จโทษ",
  str_item_intro_3220046 = "วัตถุพัฒนาการที่สำคัญของคีตติง\n\"กลอน\" จำนวนมากจะปิ๊งขึ้นมาในหัวของสมาชิกคีตติงเวลาสวมใส่อัญมณีนี้",
  str_item_intro_3220048 = "วัตถุพัฒนาการที่สำคัญของเดย์นา\nเดย์นาสามารถเรียนรู้สกิลการต่อสู้เพิ่มได้อีกด้วยอัญมณีนี้",
  str_item_intro_3220054 = "วัตถุพัฒนาการที่สำคัญของนาดีน\nอัญมณีขาวที่มักส่องแสงสบายตาอ่อน ๆ ออกมา",
  str_item_intro_3220055 = "พิตต์แมนมักพบว่าตัวเองเดินหลงทางบนเส้นทางสู่ความจริง แต่คริสตัลนี้มอบพลังและปณิธานให้กับเขา\nวัตถุพัฒนาการที่สำคัญของพิตต์แมน",
  str_item_intro_3220056 = "วัตถุพัฒนาการที่สำคัญของคอนสแตนติน\nอัญมณีนี้จะบันทึกทุกอย่างเมื่อคอนสแตนตินล่าอิคลิพไซท์ไว้อัตโนมัติ แถมยังเป็นคู่หูซี้ปึ้กที่สุดของคอนสแตนตินด้วย",
  str_item_intro_3220057 = "วัตถุพัฒนาการที่สำคัญของฟิลิชี\nคริสตัลนี้บางครั้งก็จะปล่อยลมหายใจมืดมิดให้คนเห็นธาตุแท้ของฟิลิชีเมื่อเข้ามาใกล้",
  str_item_intro_3220060 = "วัตถุพัฒนาการที่สำคัญของโจนา\nฐานทองแดงละลายของคริสตัลนี้หลอมมาจากกระสุนของโจนา\nและเป็นการอวดโอ้ความสำเร็จในอดีตของเธอ",
  str_item_intro_3220061 = "วัตถุพัฒนาการที่สำคัญของแชนดรา\nเมื่อสำรวจใกล้ ๆ แล้ว ภายในอัญมณีโปร่งแสงนี้มีพลังงาน\nที่เต้นวนเวียนอยู่ราวกับว่ากักเก็บอารมณ์ที่เธอสะสมมาหลายอย่างไว้",
  str_item_intro_3220062 = "วัตถุพัฒนาการที่สำคัญของซิลวา\nว่ากันว่าอัญมณีนี้ถูกพบลึกเข้าไปในป่าลู่ลม รู้สึกหนาวเย็นเมื่อสัมผัสและเป็นตัวแทนซิลวา ผู้พิทักษ์ผืนป่า",
  str_item_intro_3220064 = "วัตถุพัฒนาการที่สำคัญของวราธ\nอัญมณีหนักหนานี้จะเบาเมื่ออยู่ในมือของวราธ เบาพอให้เขวี้ยงไปบนอากาศได้เลย",
  str_item_intro_3220065 = "เมื่อทวีตตี้มองเข้าไปในคริสตัลนี้ เธอเห็นเงาราง ๆ ของบ้านเกิดเมืองนอน นั่นคือภูเขาเมฆา...\nวัตถุพัฒนาการที่สำคัญของทวีตตี้",
  str_item_intro_3220067 = "วัตถุพัฒนาการที่สำคัญของอลิซ\nอัญมณีนี้จะกลายสภาพเป็นรูปหัวใจที่เปี่ยมไปด้วยพลังชีวิตเมื่ออลิซถือมันไว้",
  str_item_intro_3220068 = "วัตถุพัฒนาการที่สำคัญของเวนดี้\nอัญมณีเบาหวิวนี้แข็งแกร่งมาก สะท้อนนิสัยของเวนดี้",
  str_item_intro_3220070 = "วัตถุพัฒนาการที่สำคัญของลีโอนา\nจ้องมองเข้าไปในคริสตัลนี้แล้วฟังเสียงมังกรสายฟ้าคำรามในหูของคุณ",
  str_item_intro_3220071 = "วัตถุพัฒนาการที่สำคัญของทาคิ\nฉากมังกรพ่นไฟยักษ์ปรากฎขึ้นมาในอัญมณีนี้เป็นบางครั้ง เป็นสัญลักษณ์ของทาคิเพราะอัญมณีนี้เป็นของเขาเพียงผู้เดียวเท่านั้น",
  str_item_intro_3220073 = "วัตถุพัฒนาการที่สำคัญของแพตตี้กับแพตซี่\nอัญมณีนี้สลับเปลี่ยนระหว่างปล่อยแสงสีเลือดและสัมผัสมืดมนออกมา",
  str_item_intro_3220075 = "วัตถุพัฒนาการที่สำคัญของโอดี\nคุณอาจได้ยินเสียงที่สถิตอยู่เบา ๆ เมื่อวางอัญมณีนี้ไว้ข้างหู บางทีอาจเอาไว้ใช้สื่อสาร",
  str_item_intro_3220076 = "วัตถุพัฒนาการที่สำคัญของเคลเคน\nอัญมณีมหัศจรรย์ที่แสดงเฉดสีต่างกันในต่างมุม จะยิ่งเปลี่ยนสีเมื่ออยู่ในมือของเคลเคน",
  str_item_intro_3220077 = "วัตถุพัฒนาการที่สำคัญของเบธเลเฮม\nใสและเย็นมากเมื่อจับต้อง น่าจะพัฒนามาจากน้ำแข็งกลุ่มก้อนแรกในประวัติศาสตร์ และมีเพียงราชินีแห่งแดนเหนือเท่านั้นที่ใส่ได้",
  str_item_intro_3220078 = "วัตถุพัฒนาการที่สำคัญของโรบิน\nอัญมณีมรกตเขียวที่ลือว่าล้างพิษทุกอย่างให้ผู้สวมใส่ เป็นเครื่องรางของโรบิน",
  str_item_intro_3220079 = "วัตถุพัฒนาการที่สำคัญของมิเชนนี\nอัญมณีสี่เหลี่ยมที่สมดุลไร้ที่ติ เหมาะสำหรับการรักษาความสมดุลของตราชั่ง",
  str_item_intro_3220081 = "วัตถุพัฒนาการที่สำคัญของบร็อค\nอัญมณีนี้จะร้อนมากเมื่อจับต้อง สะท้อนพลังชั่วนิรันดร์ของใครบางคน",
  str_item_intro_3220083 = "วัตถุพัฒนาการที่สำคัญของลิลเลียม\nเมื่ออัญมณีนี้อยู่ใกล้เจ้าของที่แท้จริงจะแสดงลวดลายของไฟฟ้าขึ้นมา",
  str_item_intro_3220084 = "วัตถุพัฒนาการที่สำคัญของอีสต์วาน\nเพลิงสีฟ้ามักจะลุกโชนบริเวณขอบของอัญมณีนี้ ถ้าเข้าไปใกล้ จะได้ยินแว่วเสียงเรียกหาเจ้าแห่งเงา",
  str_item_intro_3220085 = "วัตถุพัฒนาการที่สำคัญของเจน\nหากจ้องอัญมณีสีทมิฬนี้นานพอ คุณจะเห็นข้อความที่บันทึก",
  str_item_intro_3220086 = "วัตถุพัฒนาการที่สำคัญของยูริอาห์\nหยกงดงามสีขาวนี้มีรูปทรงเป็นดอกไม้",
  str_item_intro_3220087 = "วัตถุพัฒนาการที่สำคัญของเบเวอร์ลี\nสายฟ้าทรงหอกที่เหมือนหอกสายฟ้าของเบเวอร์ลีวูบวาบในอัญมณีนี้เป็นครั้งคราว",
  str_item_intro_3220088 = "วัตถุพัฒนาการที่สำคัญของแม็กกี้\nบางทีคริสตัลนี้ก็ส่องแสงสีเหลืองประหลาดขึ้นมาแวบหนึ่ง ตรวจสอบมันใกล้ ๆ แล้วคุณจะเห็นภาพเงาของเด็กสาวคนหนึ่ง",
  str_item_intro_3220089 = "วัตถุพัฒนาการที่สำคัญของอิริดอน\nอัญมณีนี้ส่องแสงสายฟ้าสีน้ำเงินเป็นบางครั้งและมีพลังพิเศษอยู่",
  str_item_intro_3220090 = "วัตถุพัฒนาการที่สำคัญของบาร์บาร่า\nเข้าไปใกล้อัญมณีที่มีฐานสีแดงนี้ แล้วคุณจะได้ยินเสียงเพลงดังหนวกหู",
  str_item_intro_3220091 = "วัตถุพัฒนาการที่สำคัญของโคลอี้\nคริสตัลสีขาวนี้เหมือนจะมีรูปร่างคล้ายหยาดน้ำตาควบแน่น เข้าไปใกล้แล้วคุณจะได้ยินเสียงฮาร์ปที่นุ่มนวล",
  str_item_intro_3220092 = "วัตถุพัฒนาการที่สำคัญของแพกต์\nอัญมณีนี้แข็งอย่างเหลือเชื่อและน่าจะไม่เคยมีรอยขีดข่วนเลย",
  str_item_intro_3220093 = "วัตถุพัฒนาการที่สำคัญของมิการ์ด\nอัญมณีที่กักเก็บพลังงานปริศนาไว้นี้ ดูเหมือนสกัดออกมาจากสิ่งมีชีวิตเทียม",
  str_item_intro_3220095 = "วัตถุพัฒนาการที่สำคัญของเลสเตอร์\nถ้าคุณได้กลิ่นอัญมณีนี้จะรู้สึกเหมือนกำลังอยู่ในป่าเขา เลสเตอร์สามารถใช้อัญมณีนี้หากลิ่นที่ชอบได้",
  str_item_intro_3220096 = "วัตถุพัฒนาการที่สำคัญของซาริเอล\nเมื่อซาริเอลถืออัญมณีนี้ มันจะเปลี่ยนรูปร่างเป็นหยดน้ำ อัญมณีนี้จะมอบพลังมหาศาลให้ซาริเอล",
  str_item_intro_3220097 = "วัตถุพัฒนาการที่สำคัญของโคแร็กซ์\nอัญมณีนี้ให้ความรู้สึกเย็นยะเยือกดุจน้ำแข็งและมีมุมแหลมคมอย่างมาก มันสามารถใช้แทนมีดได้",
  str_item_intro_3220098 = "วัตถุพัฒนาการที่สำคัญของคุสคูตา\nถ้าคุณตรวจสอบอัญมณีนี้ดี ๆ จะพบดอกไม้เฉาสีดำอยู่ข้างใน",
  str_item_intro_3220099 = "วัตถุพัฒนาการที่สำคัญของอาเรีย\nคำสาปที่สาปอาเรียไว้ดูเหมือนจะอ่อนแอลงเมื่อเธอมองอัญมณีนี้",
  str_item_intro_3220100 = "วัตถุพัฒนาการที่สำคัญของซิคาเร\nท้องฟ้าดาวพร่างพรายซ่อนอยู่ในอัญมณีนี้ บางคนก็ว่าเป็นขุมพลังที่แท้จริงของซิคาเร",
  str_item_intro_3220101 = "วัตถุพัฒนาการที่สำคัญของแอนเซีย\nอัญมณีนี้มีทองเหลืองมันเงาที่งดงามและสั่นไหวเพียงเบา ๆ แรงสั่นไหวใกล้เคียงกับความถี่เสียงของคลื่นบางอย่าง",
  str_item_intro_3220102 = "วัตถุพัฒนาการที่สำคัญของเทสซา\nสายฟ้าแลบเป็นระยะในอัญมณีนี้ตลอดเวลาและจะระเบิดเมื่อมีคนเข้าใกล้ มีเพียงเทสซาที่ถือมันได้",
  str_item_intro_3220103 = "วัตถุพัฒนาการที่สำคัญของเอซี่\nถ้าคุณจ้องเข้าไปในอัญมณีนี้ คุณจะเห็นแสงอันน่าสะพรึงฉายออกมา",
  str_item_intro_3220104 = "วัตถุพัฒนาการที่สำคัญของดอว์น\nอัญมณีนี้เป็นของดอว์นเพราะมันจะสะท้อนเงาดอกไม้สีขาวเวลาที่เธอถือไว้และดอกไม้นี้ก็เป็นที่พักพิงทางจิตใจของเธอ",
  str_item_intro_3220105 = "วัตถุพัฒนาการที่สำคัญของอีฟ\nโค้งสายฟ้าเล็ก ๆ ปรากฎขึ้นรอบอัญมณีเมื่ออีฟสัมผัสมัน นี่เป็นพลังพิเศษของอีฟ",
  str_item_intro_3220107 = "โซลแอมเบอร์ของรีกัล",
  str_item_intro_3220108 = "โซลแอมเบอร์ของฟรอสต์ไฟร์",
  str_item_intro_3220109 = "โซลแอมเบอร์ของมิธอส",
  str_item_intro_3220110 = "โซลแอมเบอร์ของเรเควียม",
  str_item_intro_3220111 = "วัตถุพัฒนาการที่สำคัญของเบริล\nคริสตัลนี้จะเปลี่ยนเป็นสีแดงโลหิตเมื่ออยู่ในมือของเบริล เหมือนกับคริสตัลที่อยู่ตามร่างกายของเธอ",
  str_item_intro_3220112 = "วัตถุพัฒนาการที่สำคัญของสโมกกี้\nอัญมณีนี้ดูเหมือนจะทำให้วัตถุไวไฟที่อยู่ใกล้เคียงลุกไหม้ได้อย่างไร้คำอธิบาย พลังแปลกประหลาดนี้จะแผ่วลงเมื่ออยู่ในมือของสโมกกี้เท่านั้น",
  str_item_intro_3220113 = "วัตถุพัฒนาการที่สำคัญของโบนาชี\nเมื่อโบนาชีสัมผัสอัญมณีนี้ แรงบันดาลใจจะท่วมท้นขึ้นในจิตใจของเธอ ทำให้เธอสามารถคิดหาท่วงท่าการเคลื่อนไหวที่ยากจะลืมเลือนขึ้นได้",
  str_item_intro_3220114 = "วัตถุพัฒนาการที่สำคัญของเจเนวีฟ\nอัญมณีนี้เปล่งแสงสีแดงออกมาตลอดเวลาราวกับเปลวไฟ บางครั้งก็มีเสียงโอดครวญออกมาด้วย...",
  str_item_intro_3220115 = "เมื่อนาโรเซลสวมคริสตัลนี้ เธอจะได้ยินเสียงของธรรมชาติอย่างชัดเจน ทำให้ความสามารถในการสื่อสารกับสัตว์และพืชของเธอเพิ่มขึ้น\nวัตถุพัฒนาการที่สำคัญของนาโรเซล",
  str_item_intro_3220116 = "วัตถุพัฒนาการที่สำคัญของเฟลอร์\nอัญมณีนี้สามารถให้แรงบันดาลใจในการออกแบบกับเฟลอร์ได้อย่างมาก ทำให้ \"แผนการผลิตจักรกล\" ของเขาเข้าใกล้ความเป็นจริงยิ่งขึ้น",
  str_item_intro_3220117 = "เมื่อแกรมถือสิ่งนี้ไว้ในมือ เขาจะรู้สึกเหมือนถูกดึงกลับไปในช่วงวันเวลาที่อยู่กับสโตนฟอร์ซอีกครั้ง และหัวใจจะพองโตด้วยความรู้สึกมากมาย\nวัตถุพัฒนาการที่สำคัญของแกรม",
  str_item_intro_3220119 = "เมื่อเรวี่สัมผัสอัญมณีชิ้นนี้ คุณจะได้ยินเสียงหึ่งของดาบยักษ์ที่บดกระทบกับโซ่ และรู้สึกได้ถึงกระแสไฟฟ้าที่พุ่งปะทุ\nวัตถุพัฒนาการที่สำคัญของเรวี่",
  str_item_intro_3220120 = "ภายใต้แสงอาทิตย์ที่ส่องสว่าง อัญมณีนี้เปล่งประกายวับวาวราวกับเกราะสีขาวอันรุ่งโรจน์\nวัตถุพัฒนาการที่สำคัญของเฮดี้",
  str_item_intro_3220121 = "ในบางครั้งอัญมณีเม็ดนี้จะแสดงรูปร่างของหญิงสาวผมสั้นที่พาโลม่าจดจำไม่ได้แล้ว...\nวัตถุพัฒนาการที่สำคัญของพาโลม่า",
  str_item_intro_3220122 = "เมื่ออัลลัวรานำอัญมณีชิ้นนี้ไปแนบหู จะได้ยินเสียงนาฬิกาเดิน ทำให้เธอใช้ความชำนาญเมื่อเวลาผ่านไปได้แม่นยำยิ่งขึ้น\nวัตถุพัฒนาการที่สำคัญของอัลลัวรา",
  str_item_intro_3220123 = "ด้วยอัญมณีนี้ คอร์ดี้สามารถรับมือกับเหตุฉุกเฉินทุกรูปแบบได้อย่างง่ายดาย\nวัตถุพัฒนาการที่สำคัญของคอร์ดี้",
  str_item_intro_3220126 = "คริสตัลนี้สามารถติดไว้กับอัญมณีที่บริเวณหน้าอกของเบเธลและเพิ่มความเจิดจรัสของมันได้\nวัตถุพัฒนาการที่สำคัญของเบเธล",
  str_item_intro_3220127 = "วัตถุพัฒนาการที่สำคัญของพาโซโล่\nเมื่ออยู่ในมือของพาโซโล่ คริสตัลนี้จะบางเบาสุด ๆ และสามารถเต้นระบำในอากาศได้เหมือนกระดาษที่ปลิวอยู่กลางสายลม",
  str_item_intro_3220129 = "คริสตัลนี้มีน้ำหนักเบามากจนลุคสามารถทำให้มันลอยในอากาศและเต้นรำราวกับผีเสื้อ\nวัตถุพัฒนาการที่สำคัญของลุค",
  str_item_intro_3220131 = "อัญมณีนี้มีข้อความโบราณสลักไว้ และดูเหมือนจะมีแค่โนวิโอเท่านั้นที่เข้าใจความหมาย\nวัตถุพัฒนาการที่สำคัญของโนวิโอ",
  str_item_intro_3220132 = "อัญมณีที่แช่ในน้ำผึ้ง ส่องประกายวาววับและส่งกลิ่นหอมหวาน\nวัตถุพัฒนาการที่สำคัญของโลล่า",
  str_item_intro_3220133 = "อัญมณีที่ระเบิดลุกเป็นไฟทุกครั้งที่มีคนเข้าใกล้ ยกเว้นสำหรับโคบายาชิที่มันจะกลายเป็นสีชมพูอ่อน วัตถุพัฒนาการที่สำคัญของโทรุ",
  str_item_intro_3220134 = "อัญมณีที่ส่องแสงสายฟ้าเป็นครั้งคราว เมื่อถือไว้ในมือกลับนุ่มอย่างคาดไม่ถึง\nวัตถุพัฒนาการที่สำคัญของคันนะ",
  str_item_intro_3220135 = "มีกระแสคลื่นอบอุ่นไหลผ่านอัญมณีนี้อย่างต่อเนื่อง หากจิตสงบจะได้ยินเสียงลำธารเชี่ยวกราก\nวัตถุพัฒนาการที่สำคัญของเอลมา",
  str_item_intro_3220136 = "ถ้ามองนาน ๆ จะเห็นบางอย่างเช่น ท้องฟ้า ทะเล ภูเขา แม่น้ำ เมือง และสุดท้ายก็มีสายตาคู่แปลก ๆ จ้องกลับมา\nวัตถุพัฒนาการที่สำคัญของลูโคอา",
  str_item_intro_3220137 = "คุณจะได้ยินเสียงคำรามแห่งลางร้ายจากอัญมณีนี้ รวมกับคาถาที่ไม่อาจได้ยินของฟาฟนีร์\nวัตถุพัฒนาการที่สำคัญของฟาฟนีร์",
  str_item_intro_3220138 = "รู้สึกเหมือนจะเห็นเส้นด้ายสีเขียวเวลาเชอวานถือมันไว้...\nวัตถุพัฒนาการที่สำคัญของเชอวาน",
  str_item_intro_3220139 = "นำอัญมณีชิ้นนี้มาแนบหูและตั้งใจฟังให้ดี คุณอาจได้ยินเสียงสิ่งลึกลับกำลังถูกเรียก\nวัตถุพัฒนาการที่สำคัญของเอริก้า",
  str_item_intro_3220140 = "อัญมณีที่ขัดผิวอย่างดี มีกลิ่นของกระดาษหนังสัตว์และหมึก คล้ายกับมีเสียงพึมพำของการอ่านและภาวนา\nวัตถุพัฒนาการที่สำคัญของฟลอรีน",
  str_item_intro_3220141 = "อัญมณีที่แข็งมากซึ่งจะให้เสียงที่ใสแจ๋วเมื่อหวดด้วยไม้เบสบอล ยอดเยี่ยมสำหรับการฝึกซ้อมวงสวิงของรูบี้\nวัตถุพัฒนาการที่สำคัญของรูบี้",
  str_item_intro_3220142 = "อัญมณีที่ดูธรรมดา\nที่สามารถสร้างภาพลวงตาของเปลวไฟ\nที่โหมกระหน่ำภายใต้สัมผัสอันอ่อนโยนของรูจ\nวัตถุพัฒนาการที่สำคัญของรูจ",
  str_item_intro_3220143 = "อัญมณีที่เปล่งแสงสีชมพูอ่อนเป็นบางครั้ง เมื่อเขย่าเบา ๆ จะเกิดเสียงที่ฟังแล้วสบายใจและมีความสุข\nไอเทมพัฒนาการของรินเนะ",
  str_item_intro_3220144 = "อัญมณีที่ดูเรียบง่าย เมื่อสัมผัสจะรู้สึกเย็น เปล่งแสงอ่อน ๆ ในความมืด\nไอเทมพัฒนาการของคายาโนะ",
  str_item_intro_3220145 = "เมื่ออัญมณีชิ้นนี้อยู่ในมืออาเมะโมริ มันจะเบาขึ้น และปรากฏคำว่า \"อดทน\" เป็นครั้งคราว\nวัตถุพัฒนาการที่สำคัญของอาเมะโมริ",
  str_item_intro_3220146 = "อัญมณีส่งกลิ่นหอมอ่อน ๆ ของอาหาร และเมื่อมองดูใกล้ ๆ ก็ดูเหมือนจะสะท้อนแสงสีแดงเพลิงแปลก ๆ\nวัตถุพัฒนาการที่สำคัญของเหยา",
  str_item_intro_3220147 = "อัญมณีหลากสีที่ดึงดูดให้ผู้คนคิดว่ามันอร่อย เมื่อตรวจสอบดูใกล้ ๆ จะเห็นไฟที่คล้ายกันสองดวงอยู่ในนั้น\nวัตถุพัฒนาการที่สำคัญของโมโมะ & อันสึ",
  str_item_intro_3220148 = "หินชิ้นนี้ให้สัมผัสเย็นและปล่อยแสงสีฟ้าซีดจางเมื่อมีแสงอาทิตย์มากระทบ\nวัตถุพัฒนาการที่สำคัญของแอเชอร์",
  str_item_intro_3220149 = "หินที่มีพื้นผิวขรุขระเล็กน้อยและดูไม่มีพิษภัย บางครั้งจะมีเงาคนที่มีเส้นผมสีเงินปรากฏขึ้น และยังไม่ทันที่คุณจะมองเห็นว่าเป็นใคร รอยก็จะนำหินชิ้นนี้ไปซ่อน เพราะยังไงเขาก็ตัวสูงเกินกว่าที่ใครจะมาแย่งเอาไปจากเขาได้\nวัตถุพัฒนาการที่สำคัญของรอย",
  str_item_intro_3220150 = "เหตุผลบางอย่างทำให้อัญมณีชนิดนี้ส่งเสียงหวีดแหลมออกมาตลอดเวลาราวกับว่ามันหัวเสียเรื่องอะไรสักอย่าง\nไอเทมพัฒนาการที่สำคัญของเลนอร์",
  str_item_intro_3220151 = "อัญมณีชิ้นนี้แข็งและร้อนจัดมาก สัมผัสของไจลส์สามารถเปลี่ยนมันให้กลายเป็นเขาแกะได้อย่างน่าอัศจรรย์\nไอเทมพัฒนาการที่สำคัญของไจลส์",
  str_item_intro_3220152 = "เมื่อเมย์จับต้อง จะทำให้เกิดเป็นภาพแมวขึ้นที่พื้นผิวของอัญมณีชิ้นนี้ บางครั้งจะมีออโรเรียนปรากฏตัวขึ้นมา แต่ไม่มีใครบอกได้ว่าเป็นใคร\nไอเทมพัฒนาการที่สำคัญของเมย์",
  str_item_intro_3220153 = "ขัดด้วยมือของช่างอัญมณีที่มีชื่อมากที่สุดคนหนึ่งของอิลลูมินา เฉพาะผู้ที่ยืนอยู่จุดสูงสุดของสหพันธรัฐอิลลูมินาเท่านั้นที่สามารถใช้มันได้\nวัตถุพัฒนาการที่สำคัญสำหรับไรน์ฮาร์ต",
  str_item_intro_3220154 = "เมื่อไวซ์อยู่ใกล้ อัญมณีเริ่มส่องแสงสีแดงและเขียวออกมา\nวัตถุพัฒนาการที่สำคัญสำหรับไวซ์: สายตาเฉียบคม",
  str_item_intro_3220187 = "อัญมณีเล็ก ๆ ที่เหนียวนิด ๆ ส่งกลิ่นหอมหวานและอ่อนโยนที่สามารถรับรู้ได้เมื่อใครสักคนเข้าใกล้ ลี่เทียนเซียนมักมีรอยยิ้มที่พอใจทุกครั้งที่เขาใช้มัน บางทีมันอาจจะเป็นแท่งขนมหวานจริง ๆ หรือเปล่า?\nวัตถุการพัฒนาที่จำเป็นสำหรับ Li Tianxian.",
  str_item_intro_3220188 = "อัญมณีนี้มีลักษณะเนื้อสัมผัสเนียน ๆ และกลิ่นหอมดอกไม้อ่อนๆ ถ้าคุณสังเกตใกล้ ๆ คุณจะพบลวดลายซับซ้อนที่มีรูปร่างเป็นดอกเบโกเนีย\nวัตถุการพัฒนาที่จำเป็นสำหรับ Dantang",
  str_item_intro_3221000 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนเอ็กซ์คลูซีฟ",
  str_item_intro_3221001 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุไม้ 5 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221002 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุสายฟ้า 5 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221003 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุไฟ 5 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221004 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุน้ำ 5 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221005 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุไม้ 6 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221006 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุสายฟ้า 6 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221007 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุไฟ 6 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_3221008 = "สามารถแลกเป็นโซลแอมเบอร์ออโรเรียนธาตุน้ำ 6 ดาว ที่ไม่ใช่เอ็กซ์คลูซีฟ",
  str_item_intro_5840001 = "แพ็กเมล็ดพันธุ์ต้นไม้มหัศจรรย์ทั่วไปสำหรับปลูกต้นไม้มหัศจรรย์ทั่วไป",
  str_item_intro_5840002 = "แพ็กเมล็ดพันธุ์ต้นไม้มหัศจรรย์ II สำหรับปลูกต้นไม้มหัศจรรย์ II ที่มีการกลายพันธุ์เล็กน้อย",
  str_item_intro_5840003 = "แพ็กเมล็ดพันธุ์ต้นไม้มหัศจรรย์ III สำหรับปลูกต้นไม้มหัศจรรย์ III ที่มีการกลายพันธุ์บ่อยครั้ง",
  str_item_intro_5840004 = "แพ็กเมล็ดพันธุ์ต้นไม้มหัศจรรย์ IV สำหรับปลูกต้นไม้มหัศจรรย์ IV ที่มีการกลายพันธุ์ซับซ้อน",
  str_item_intro_3220155 = "อัญมณีที่แข็งและหนัก บ่อยครั้งจะมองเห็นเงาดำขนาดมหึมาส่องประกายอยู่ภายใน พร้อมด้วยสิ่งที่ดูเหมือนจะเป็นเสียงคำรามของสัตว์ร้าย\nวัตถุพัฒนาการที่สำคัญสำหรับบาร์ตัน: ดาบสำแดงเดช",
  str_item_intro_3220156 = "อัญมณีหายาก เมื่อมองดูใกล้ ๆ จะเห็นแสงสว่างที่วูบไหวไม่หยุดนิ่ง ราวกับสัญลักษณ์ของความไม่ยอมจำนน\nวัตถุพัฒนาการที่สำคัญของนีน่า",
  str_item_intro_3220157 = "อัญมณีที่ทำจากวัสดุทนทานอย่างมาก ตกยังไงก็ไม่แตก เรารู้ได้ยังไงน่ะเหรอ? อืม คุณต้องไปถามซานาเอะดูนะ\nวัตถุพัฒนาการที่สำคัญของซานาเอะ",
  str_item_intro_3220158 = "ไอเทมสำหรับพัฒนาการของโจ๊กเกอร์\nอัญมณีแวววาวสดใส\nอัดแน่นด้วยความรู้สึกต่อต้านที่รุนแรง",
  str_item_intro_3220159 = "ไอเทมสำหรับพัฒนาการของควีน\nอัญมณีที่โปร่งแสงอย่างหมดจด\nอัดแน่นด้วยความรู้สึกต่อต้านที่รุนแรง",
  str_item_intro_3220160 = "ไอเทมสำหรับพัฒนาการของฟ็อกซ์\nอัญมณีที่มีสัมผัสอบอุ่น\nอัดแน่นด้วยความรู้สึกต่อต้านที่รุนแรง",
  str_item_intro_3220161 = "ไอเทมสำหรับพัฒนาการของไวโอเล็ต\nอัญมณีรูปดอกไม้\nอัดแน่นด้วยความรู้สึกต่อต้านที่รุนแรง",
  str_item_intro_3220162 = "ไอเทมสำหรับพัฒนาการของโมน่า\nอัญมณีที่มีรอยขีดข่วนดูเหมือนเกิดจากกรงเล็บที่แหลมคม\nอัดแน่นด้วยความรู้สึกต่อต้านที่รุนแรง",
  str_item_intro_3220164 = "เมื่อมองแวบแรก อัญมณีนี้ดูเหมือนจะเต็มไปด้วยไอน้ำและลุกเป็นไฟในฉับพลัน แต่ไม่ว่าจะเกิดการเปลี่ยนแปลงอย่างไรภายในอัญมณี คุณสมบัติความแน่วแน่ของมันก็จะยังคงเดิม\nวัตถุพัฒนาการที่สำคัญของคาร์ลีน: จิตจรัสแสง",
  str_item_intro_3220165 = "เมื่อเซียลมองดูคริสตัลนี้ใกล้ ๆ ก็เหมือนว่าเธอจะเห็นสูตรลึกลับบางอย่างที่สร้างแรงบันดาลใจอันแน่วแน่ให้แก่เธอ\nวัตถุพัฒนาการที่สำคัญของเซียล",
  str_item_intro_3220166 = "อัญมณีชนิดนี้จะสั่นสะท้านอย่างรุนแรงเมื่อมีสัตว์มหัศจรรย์อยู่ใกล้\nวัตถุพัฒนาการที่สำคัญของฟีญ่า",
  str_item_intro_3220167 = "อัญมณีวิเศษนี้สร้างภาพลวงแทนตัวเองขึ้นมาได้... ระวังอย่าให้มันหลอกเอานะ\nวัตถุพัฒนาการที่สำคัญของเจโน่",
  str_item_intro_3220168 = "อัญมณีชนิดนี้ให้สัมผัสที่เย็น บางครั้งได้ยินเสียงเกลียวคลื่นดังออกมาจากข้างใน\nวัตถุพัฒนาการที่สำคัญของเรนโบว์",
  str_item_intro_3220169 = "เมื่อใดก็ตามที่เธอถืออัญมณีนี้ Sadie รู้สึกถึงความกล้าหาญอันยิ่งใหญ่ที่ไหลจากฝ่ามือของเธอไปสู่ส่วนอื่นๆ ของร่างกายของเธอ แม้แต่การเต้นของหัวใจของเธอก็เปลี่ยนไปตามนั้น!\nวัตถุทะลุทะลวงที่จำเป็นสำหรับ Sadie",
  str_item_intro_3220170 = "อัญมณีที่มีกลิ่นควันแรง ที่น่าทึ่งกว่านั้นคือภาพใบมีดที่สั่นไหวเป็นครั้งคราวบนพื้นผิวของมัน\nออบเจ็กต์ Breakthrough ที่จำเป็นสำหรับ Pollux",
  str_item_intro_3220171 = "เมื่อคุณฟังอัญมณีล้ำค่านี้อย่างใกล้ชิด คุณจะได้ยินเสียงนกกาที่มาจากภายใน\nวัตถุทะลุทะลวงที่จำเป็นสำหรับ Casta",
  str_item_intro_3220172 = "หากคุณมองดีๆ อัญมณีนี้จะกะพริบและวาบราวกับช่วงเวลาที่ยิ่งใหญ่ที่สุดในประวัติศาสตร์ภาพยนตร์ ด้วยทักษะนี้ ทักษะของลิลิกาจึงสามารถไปถึงระดับที่ใหม่กว่าได้!\nวัตถุทะลุทะลวงที่จำเป็นสำหรับ Lilica",
