  str_item_intro_3220176 = "อัญมณีที่เปล่งประกายเจิดจรัสด้วยสีสันมากมาย มันเปล่งประกายเจิดจรัสแม้ไม่ได้ผ่านการขัดเงา และสามารถมองเห็นเงาของนกบินอยู่ภายในอัญมณีเป็นครั้งคราว\nวัตถุที่ก้าวหน้าที่จำเป็นสำหรับเบเร็ตต้า",
  str_item_intro_3220177 = "อัญมณีหลากสีนี้ให้ความรู้สึกอบอุ่นอย่างไม่น่าเชื่อ หากคุณพกติดตัวไว้นานพอ คุณอาจแบ่งปันความโชคดีของโกลดี้ด้วยซ้ำ\nวัตถุการพัฒนาที่จำเป็นสำหรับโกลดี้",
  str_item_intro_3220178 = "อัญมณีนี้แข็งมาก แม้ว่าคุณจะต้องทุบมันให้แรงที่สุดเท่าที่จะทำได้ด้วยค้อนขนาดใหญ่ คุณก็จะไม่ทิ้งรอยขีดข่วนไว้\nวัตถุการพัฒนาที่จำเป็นสำหรับ Vic",
  str_item_intro_3220180 = "ให้ความรู้สึกมั่นคง แต่จะเด้งกลับหากคุณกดลงไป เห็นได้ชัดว่าบรั่นดีใช้สิ่งนี้เพื่อฝึกความเร็วของนิ้วกดชัตเตอร์\nวัตถุที่ก้าวหน้าที่จำเป็นสำหรับบรั่นดี",
  str_item_intro_3220181 = "ความอบอุ่นของหินก้อนนี้ในมือเป็นเครื่องพิสูจน์ถึงหัวใจอันเร่าร้อนของ Zhong Xu\nวัตถุการพัฒนาที่จำเป็นสำหรับ Zhong Xu",
  str_item_intro_3220182 = "สีของอัญมณีที่บางและแข็งนี้จะเปลี่ยนไปตามมุมของแสงที่ส่องกระทบ\nวัตถุการพัฒนาที่จำเป็นสำหรับ Mu Yuebai",
  str_item_intro_3220183 = "อัญมณีเม็ดนี้มีกลิ่นหอมของสมุนไพรจางๆ มีรสขมเล็กน้อย และมีกลิ่นเหมือนเภสัชกรของ Liqing\nวัตถุการพัฒนาที่จำเป็นสำหรับ Liqing",
  str_item_intro_3220184 = "มันให้ความรู้สึกเก่าและผุกร่อน แต่ในขณะเดียวกันมันก็สดใสและสวยงามมาก\nวัตถุทะลวงที่จำเป็นสำหรับ Jeriah",
  str_item_intro_3220185 = "สัมผัสนุ่มนวลราวกับว่า Kya ลูบไล้บ่อยครั้ง เมื่อตรวจสอบอย่างใกล้ชิด ดูเหมือนว่าจะมีหน้าปัดเคลื่อนไหวอยู่ข้างใน... นี่นาฬิกาหรือเปล่า?\nวัตถุแห่งความก้าวหน้าที่จำเป็นสำหรับ Kya",
