  str_item_intro_3220189 = "หินนี้ยากต่อการสัมผัส สะท้อนแสงเป็นประกายภายใต้ดวงอาทิตย์ หากคุณดมอย่างระมัดระวัง คุณจะสัมผัสได้ถึงกลิ่นหอมของดอกไม้\nวัตถุการพัฒนาที่จำเป็นสำหรับ Leyn",
  str_item_intro_3220190 = "พลอยเจียระไนที่เจียระไนอย่างประณีตด้วยฝีมือชั้นเลิศ ไม่ว่าจะด้วยวิธีไหนก็ดูแพงมาก ดังนั้นควรใส่อย่างระมัดระวัง\nเป้าหมายการพัฒนาที่จำเป็นสำหรับ Matthieu",
  str_item_intro_3220191 = "แม้จะดูแข็งมาก แต่สัมผัสนุ่มและเด้งอย่างคาดไม่ถึงเหมือนอุ้งเท้าสุนัข คุณไม่สามารถหยุดตัวเองจากการบีบซ้ำแล้วซ้ำอีก\nวัตถุการพัฒนาที่จำเป็นสำหรับ Hati",
  str_item_intro_3220192 = "อัญมณีที่หมองคล้ำนี้ให้ความรู้สึกหยาบเมื่อสัมผัส ลีโอบอกว่านี่เป็นข้อพิสูจน์ว่ามันถูกลมและทรายขัดที่ชายแดน\nวัตถุการพัฒนาที่จำเป็นสำหรับลีโอ",
  str_item_intro_3220193 = "ขยับเข้าไปใกล้ๆ แล้วคุณจะได้ยินเสียงน้ำไหลชัดเจน บางทีคลื่นใต้น้ำที่พลุ่งพล่านแบบนี้อาจไหลวนอยู่ในใจของคริสเตน...\nวัตถุการพัฒนาที่จำเป็นสำหรับ Kristen",
  str_item_intro_3220199 = "สามารถได้ยินเสียงที่ไพเราะเหมือนนกจากภายในพลอยใสนี้\nวัตถุการพัฒนาที่จำเป็นสำหรับ Yingel",
  str_item_intro_3220200 = "อัญมณีที่ Anatoli รวบรวมได้ถูกสร้างขึ้นในเส้นเลือดภายใน Eternal Night และขนส่งกลับไปที่ Illumina เป็นระยะทางหลายพันไมล์ มันอุ่นเมื่อสัมผัส และเงาสะท้อนของใครบางคนสามารถมองเห็นได้ลางๆ บนผิวของมัน\nวัตถุการพัฒนาที่จำเป็นสำหรับอนาโตลี",
  str_item_intro_3220201 = "เมื่อมองแวบแรก ดูเหมือนว่าจะเป็นหินพันธุ์สวนทั่วไปของคุณ แต่ลองแนบหูฟังและตั้งใจฟังให้ดี คุณจะได้ยินเสียงคำรามสองคำที่กระทบกัน ซึ่งทำให้มันดูน่าตื่นตายิ่งขึ้นไปอีก\nวัตถุการพัฒนาที่จำเป็นสำหรับ Mia: Lustrous Soul",
  str_item_intro_3220202 = "จ้องมองเข้าไปในอัญมณีเม็ดนี้แล้วคุณจะเห็นสิ่งที่ดูเหมือนจะเป็นวันที่สดใสหลังจากพายุฝนฟ้าคะนอง นี่คืออนาคตที่รอคอย Lumopolis ภายใต้การปกครองของเขา\nวัตถุการพัฒนาที่สำคัญสำหรับ Schwartz: Almighty Clamour",
  str_item_intro_3220203 = "อัญมณีเม็ดงามที่ส่องแสงระยิบระยับหลากสีสันเมื่อโดนแสงแดดฉายภาพหนังสือทำนาย\nวัตถุการพัฒนาที่จำเป็นสำหรับ Jakine",
  str_item_intro_3220204 = "อัญมณีที่โอบล้อมด้วยแสงอันอบอุ่น เช่น เทียนไขในฤดูหนาวหรือตะเกียงตามท้องถนนในความมืดซึ่งนำทางผู้ที่หลงทาง\nวัตถุแห่งความก้าวหน้าที่จำเป็นสำหรับ Joshua",
  str_item_intro_3220205 = "อัญมณีเม็ดงามที่บลองเล่นด้วยบ่อยๆ เธอบอกว่าด้านล่างของอัญมณีนี้สะท้อนรัศมีสีแดง แต่ไม่มีใครมองเห็นได้\nวัตถุความก้าวหน้าที่จำเป็นสำหรับ Blanc: Pura Cordis",
  str_item_intro_3220206 = "ลอเรไลย์เล่นหัวกล่าวว่าอัญมณีนี้มีกลิ่นเงิน แต่เธอก็ยังหลงรักมันอยู่\nวัตถุพัฒนาการที่สำคัญสำหรับลอเรไลย์",
  str_item_intro_3220207 = "เรียบบนพื้นผิว แต่แหลมคมเมื่อสัมผัส คริสตัลนี้หมายความว่าภายใต้ผิวสะอาดอาจมีรอยแผลที่ซ่อนอยู่จากอดีตหรือไม่? วัตถุพัฒนาการสำคัญสำหรับ Cena.",
  str_item_intro_3220208 = "คริสตัลที่สว่างและสดใสกำลังหมุนเทช้า ๆ หน่อยนะ...\nวัตถุพัฒนาการสำคัญสำหรับบ็อปเปอร์",
  str_item_intro_3220209 = "วัตถุพัฒนาการที่สำคัญของวราธ: ความกระตือรือร้นของความภาคภูมิ\nมันจะแทงใครก็ตามที่กล้ายื่นมือสัมผัส เนื่องจากสายฟ้าสีแดงที่วุ่นวายอยู่ภายในคริสตัล รอให้เธอมาครองสนามรบที่เลือกของเธอ",
  str_item_intro_3220210 = "วัตถุพัฒนาการที่สำคัญของโจเซลีน\nเมื่อสังเกตใกล้ ๆ แสงอ่อนๆ สว่างขึ้นที่แกนกลางของอัญมณี - นึกถึงเสียงสวดมนต์ของผู้นับถือที่อุตสาหะและแสงศักดิ์สิทธิ์ที่ทำลายความมืดในคืน",
  str_item_intro_3220211 = "อัญมณีนี้ถูกกลบภายใต้ดินมานับเอียน จนกระทั่งแอนโทนีขุดค้นพบ ลบความสกปรกออก และค้นพบรากฐานของความลึกลับของมัน\nวัตถุการพัฒนาที่จำเป็นสำหรับแอนโทนี",
  str_item_intro_3220212 = "มันดูเหมือนคริสตัลน้ำแข็งที่เกิดขึ้นเองมากกว่าอัญมณี บางทีซาร์ยาอาจจะทำมันขึ้นเองหรือเปล่า?\nวัตถุพัฒนาการที่สำคัญของซาร์ยา",
  str_item_intro_3220213 = "หมายเลข 33 พบอัญมณีนี้ใกล้กับซากปรักหักพังที่เธอเคยปกป้อง ครั้งใดก็ตามที่ความเหงาของเธอน่าทนไม่ไหว หมายเลข 33 ถือว่ามันเป็นเพื่อนคู่ความเหงาของเธอและพยายามสื่อสารกับมัน\nวัตถุพัฒนาการที่จำเป็นสำหรับหมายเลข 33",
  str_item_intro_3220214 = "วัตถุพัฒนาการที่สำคัญของเรเบคก้า อัญมณีนี้ถูกมอบให้เรเบคก้าจากพ่อแม่ของเธอ เมื่อใดก็ตามที่เธอกัดกั้นมันแน่น ๆ เธอสามารถรู้สึกถึงความอบอุ่นอันน่าที่จะไม่สิ้นสุดของครอบครัวของเธอ",
  str_item_intro_3220215 = "อัญมณีที่สร้างขึ้นจากพิษของเรเบคก้า อีซ่ารู้สึกเหมือนร่างกายของเธอเต็มไปด้วยพลังงานเมื่อมีอัญมณีนี้อยู่กับเธอ\nวัตถุพัฒนาการที่สำคัญของอีซ่า",
  str_item_intro_3220216 = "หินที่ดูธรรมดานี้มีพลังงานที่ไม่รู้จักอยู่ ไม่มีใครรู้ว่า Xuan Ji จะฝังหินนี้ลงในกับดักหรือสิ่งประดิษฐ์เครื่องปั่นอะไร\nวัตถุการพัฒนาที่จำเป็นสำหรับ Xuan Ji",
  str_item_intro_3220218 = "อัญมณีลึกลับนี้มีน้ำหนักเท่ากับไนเทียม ถ้าคุณฟังอย่างระมัดระวัง คุณยังสามารถได้ยินเสียงของไนเทียมที่สั่นภายในอัญมณี\nวัตถุพัฒนาการที่สำคัญของเชโอล",
  str_item_intro_3220219 = "อัญมณีที่สว่างสดใสและหนักนี้รู้สึกเหมือนกำลังสั่นเบา ๆ จากความรู้สึกที่ห่างไกลในมือของคุณ มันเหมือนกับเหตุการณ์ในอดีตที่ถูกฝังลึกลงไปกำลังจะระเบิดออกมา\nวัตถุการพัฒนาที่จำเป็นสำหรับอีสต์วาน: Scarred Pith",
  str_item_intro_3220220 = "เวอร์จิลประเมินว่าอัญมณีนี้มีค่าทางศิลปะสูง มีรายงานว่าเขาชอบพกอัญมณีนี้ติดตัวเหมือนเครื่องรางของโชคดี วัตถุทะลุทะลวงที่จำเป็นสำหรับเวอร์จิล",
  str_item_intro_3220221 = "อัญมณีที่ลึกซึ้งและที่ทำให้หายใจหยุดอย่างมากจากแหล่งกำเนิดที่ไม่ทราบ มันดูเหมือนจะทำนายอนาคตที่ลึกลับและไม่สามารถคาดเดาของ Aurorians...\nวัตถุการพัฒนาที่จำเป็นสำหรับ Algol.",
  str_item_intro_3220223 = "หินที่สร้างขึ้นจากเกล็ดในยุคโบราณ อาจจะถือความคิดสะท้อนไกลของครอบครัว Chen'ni\nวัตถุการพัฒนาที่จำเป็นสำหรับ Chen'ni",
  str_item_intro_3220224 = "หินที่อาจจะมีพลังงานลึกลับอยู่ภายใน ลูโอ้ ซงอาจจะใช้มันเพื่อทำให้เหล่าปีศาจเล่นงานรู้จักความสำคัญ\nวัตถุการพัฒนาที่จำเป็นสำหรับลูโอ้ ซง",
  str_item_intro_3220225 = "อัญมณีที่มีสีป้องกันที่ผสมผสานได้อย่างลงตัวกับน้ำแข็งเมื่อตกลงไปในหิมะ ทำให้การเก็บกู้เป็นไปได้ยาก ดังนั้น ควรจัดการอย่างระมัดระวัง\nวัตถุการพัฒนาที่จำเป็นสำหรับเทียเร่",
  str_item_intro_3220227 = "ชิ้นของ Lumamber ที่มีขอบและมุมที่แหลมคมอย่างผิดปกติ แม้ว่าจะต้องใช้ความระมัดระวังมากเมื่อจับจัด Lumamber นี้ แต่คุณสามารถรู้สึกได้ถึงความอบอุ่นที่อ่อนโยนและนุ่มนวลที่มาจากมัน\nวัตถุการพัฒนาที่จำเป็นสำหรับราเชล",
  str_item_intro_3220228 = "อัญมณีสวยงามที่ปล่อยแสงสีสันสดใสและกลิ่นหอมของลูกอมอย่างเบาๆ\nวัตถุพัฒนาการที่สำคัญสำหรับเซต้า",
  str_item_intro_3220229 = "หินธรรมดาที่บาเทียกล่าวว่าสามารถได้มาโดยการใช้ขวานเจาะและเตาเผา รวมถึงวิธีอื่น ๆ \nวัตถุพัฒนาการที่สำคัญของบาเทีย",
  str_item_intro_3220230 = "ในขณะที่คุณสัมผัสอัญมณีนี้ คุณจะได้ยินเสียงกระซิบที่โบราณ ไม่ไกลหรือใกล้หูของคุณ แต่ลึกลงไปในใจความคิดของคุณ เหมือนมีสิ่งมีชีวิตโบราณที่กำลังเต้นและพยายามหลุดพ้น\nวัตถุพัฒนาการที่สำคัญของวิกตอเรีย: เอลีจี",
  str_item_intro_3220231 = "อัญมณีที่มีสีสันที่น่ากลัวและสดใส เมื่อคุณสัมผัสมัน คุณจะเห็นเลือดเริ่มหยดลงมาที่ผนัง แต่เมื่อคุณถอนมือของคุณออกในความกลัว คุณจึงเห็นว่ามันเป็นแค่ภาพลวงตา\nวัตถุพัฒนาการที่สำคัญของวิลเฮล์ม",
  str_item_intro_3220232 = "เมื่อคุณจับอัญมณีนี้ไว้ทันที คุณจะเห็นพันธ์มากมายของดาบตกจากท้องฟ้า ตัดเข้าสู่เนื้อเยื่อของคุณ คุณกรีดร้องเจ็บปวด แต่เมื่อคุณมองตัวเอง คุณพบว่าไม่มีอันตราย\nวัตถุพัฒนาการที่สำคัญของเนลส์: พิธีศักดิ์สิทธิ์",
  str_item_intro_3220233 = "อัญมณีที่ขุดขึ้นมาจากซากปรักษา บางทีคุณอาจจะรู้สึกถึงความหลงใหลในการผจญภัยจากมัน\nวัตถุพัฒนาการที่สำคัญของรายซ่า",
  str_item_intro_3220234 = "อัญมณีที่ขุดขึ้นมาจากซากปรักษา บางทีคุณอาจจะรู้สึกถึงความงามของดนตรีจากมัน\nวัตถุพัฒนาการที่สำคัญของคลาวเดีย",
  str_item_intro_3220235 = "อัญมณีที่ขุดขึ้นมาจากซากปรัมปรา บางทีคุณอาจจะรู้สึกถึงอารมณ์ขันอาการชนชั้นสูงจากมัน\nวัตถุพัฒนาการที่สำคัญของปัทริเซีย",
  str_item_intro_3220237 = "พลอยใสที่มีสัมผัสของลมเย็นที่สูงกว่าเมฆและความนุ่มนวลชื้นของทะเลลึก\nถือมันไว้ในมือของคุณและคุณจะได้ยินเสียงกระซิบเงียบๆ \"อย่ากลัว โลกกำลังหลับในฝันของคุณ\"\nวัตถุพัฒนาการที่สำคัญของมายา",
  str_item_intro_3220238 = "ดูเรียบง่ายในครั้งแรก แต่เมื่อคุณสัมผัสขอบ คุณจะเห็นว่ามันคมจริงๆ มีพลังงานที่เต้นหัวในตัว ดูเหมือนความโกรธที่ไม่ได้พูดออกมา\nวัตถุที่ก้าวหน้าที่จำเป็นสำหรับ Mithra",
  str_item_intro_3231101 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนลูโมโพลิส\nแผ่นเงินบอบบางที่เบาราวขนนก ของที่ทุกคนโปรดปรานในลูโมโพลิส",
  str_item_intro_3232101 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนลูโมโพลิส\nลูมแอมเบอร์ที่ห่อมาด้วยทอง อัญมณีเบื้องต้นของสังคมชั้นสูงในลูโมโพลิส",
  str_item_intro_3233101 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนลูโมโพลิส\nงานฝีมือล้ำค่ามากที่ทำจากอัญมณีลูมินา ติดลงบนคริสตัลขาวราคาสูง",
