  str_item_intro_3233102 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอัมบราตัน\nอัญมณีดึงดูดใจที่เปล่งประกายสีเขียวพิเศษ เป็นที่ต้องการในอัมบราตันอย่างมาก",
  str_item_intro_3231103 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนเรดีเซล เวรนช์\nสารที่เหลือใช้จากโบราณกาล ชาวเรดีเซล เวรนช์ใช้เพื่อตกแต่งหรือใช้ดูแลโคลอสซัสของพวกเขา",
  str_item_intro_3232103 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนเรดีเซล เวรนช์\nของสำคัญในการทำไดนาไมต์ กระสุนและระเบิด เป็นสกุลเงินที่เป็นวัตถุของเรดีเซล เวรนช์",
  str_item_intro_3233103 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนเรดีเซล เวรนช์\nน้ำเมาแรงหายากที่ทำให้ร้อนท้องหลังจากดื่มไปช็อตเดียว เป็นที่ชื่นชอบของชาวเรดีเซล เวรนช์ทุกคน",
