  str_item_intro_3232104 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอิลลูมินา\nคู่มือของสหพันธรัฐอิลลูมินาที่สอนวิธีใช้วิทยาศาสตร์จัดการกับ\nปัญหาต่าง ๆ แก่ผู้อ่าน",
  str_item_intro_3233104 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอิลลูมินา\nสำหรับใช้ภายในสหพันธรัฐอิลลูมินาเท่านั้น รวมศาสตร์ความรู้ทุกแขนงซึ่งศึกษาค้นพบโดยสหพันธรัฐ",
