  str_item_intro_3232105 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนนอร์ธแลนด์\nอัญมณีสีสันสดใสมีราคาสูงที่ถูกพบใต้สายรุ้ง ชาวนอร์ธแลนด์เชื่อกันว่าจะนำโชคดีมาให้ตลอดกาล",
  str_item_intro_3233105 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนนอร์ธแลนด์\nแผ่นน้ำแข็งสีสันสดใสที่นำมาจากทะเลสาบกระจกเงาที่เป็นน้ำแข็งตลอดกาลในนอร์ธแลนด์ ของโปรดของชาวนอร์ธแลนด์",
  str_item_intro_3231106 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนทรู ออเดอร์\nแมลงปีกแข็งโบราณที่หุ้มไว้ด้วยอำพัน ทรู ออเดอร์เชื่อว่ามีพลังปริศนาอยู่",
  str_item_intro_3232106 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนทรู ออเดอร์\nคัมภีร์ที่มีการเปิดเผยสิ่งลึกลับ ความลับมากมายจะได้รับการเปิดเผย หากสมาชิกทรู ออเดอร์ถอดความของคัมภีร์",
  str_item_intro_3233106 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนทรู ออเดอร์\nทรู ออเดอร์เชื่อว่ามันมีการเปิดเผยสูงสุดที่จะเปลี่ยนอารยธรรมเท่าที่เรารู้กันในปัจจุบัน",
  str_item_intro_3231107 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอิสระ\nข้าวห่ออบแห้งน้ำหนักเบาขนาดพกพาซึ่งเป็นที่นิยมในหมู่ผู้อพยพกลุ่มเล็ก",
  str_item_intro_3232107 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอิสระ\nโพชั่นสุดแสนมหัศจรรย์ที่สามารถทำให้ใครก็ได้เป็นหมอ\nในกลุ่มผู้อพยพบางแห่ง",
  str_item_intro_3233107 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนอิสระ\nชิ้นส่วนแผนที่ขุมทรัพย์ที่บรรดาคนที่รู้สึกว่าคุ้มค่าแก่การเดิมพันต่างกำลังเสาะหา",
  str_item_intro_3232108 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนหลงโจว\nพัดพับที่มีโครงไม้ไผ่และพื้นผิวกระดาษที่วาดภูเขาและแม่น้ำอันน่ารัก ใช้ในห้องมืดของห้องใหญ่ในหลงโจว",
  str_item_intro_3233108 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนหลงโจว\nเงื่อนไขที่ทำจากเชือกสีแดงนี้ สัญลักษณ์ของความสัมพันธ์ที่เต็มใจและความรักต่อกัน ซึ่งเป็นของขวัญที่สำคัญที่สุดในหัวใจของคนหลงโจว",
  str_item_intro_3231201 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้บริสุทธิ์ราวกับเด็ก\nผู้มีจิตใจราวกับเด็กชื่นชอบอย่างมาก มีห้ารสชาติแถมยังเป่านกหวีดได้ด้วย",
  str_item_intro_3232201 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้บริสุทธิ์ราวกับเด็ก\nผลิตภัณฑ์เพื่อความบันเทิงสำหรับผู้มีจิตใจราวกับเด็ก ผู้เล่นจะเล่นไปตามการอธิบายเป็นคำพูด",
  str_item_intro_3233201 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้บริสุทธิ์ราวกับเด็ก\nโมเดลที่ผู้มีจิตใจราวกับเด็กชื่นชอบ งานละเอียดอย่างมากและเลิกผลิตแล้ว",
  str_item_intro_3231202 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้โรแมนติก\nตุ๊กตาเย็บด้วยมือที่คนโรแมนติกชื่นชอบ มันคล้ายคลึงกับทั้งกระต่ายและหมีโดยผู้สร้างนิรนาม",
  str_item_intro_3232202 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้โรแมนติก\nโรแมนติกมากที่ได้เห็นลำแสงที่งดงามในขวดที่มีฉากแสงสลัว",
  str_item_intro_3233202 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนผู้โรแมนติก\nที่คั่นหนังสือทำจากพืชหายาก แถมยังเปลี่ยนรูปร่างและสีสันอีกด้วย",
  str_item_intro_3231203 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่ชอบสิ่งลี้ลับ\nโด่งดังเพราะลักษณะพิลึก แมลงตัวนี้ดึงดูดนักสะสมที่ช่างสงสัย",
  str_item_intro_3232203 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่ชอบสิ่งลี้ลับ\nฟอสซิลแหลมคมที่ตกผลึกมาจากสิ่งมีชีวิตที่ไม่มีใครรู้จัก สำหรับนักสะสมที่ช่างสงสัย",
  str_item_intro_3233203 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่ชอบสิ่งลี้ลับ\nไม้เน่าที่คนช่างสงสัยเก็บสะสมเพราะบางครั้งก็ได้ยินเสียงกระซิบประหลาดตรงจุดเชื่อมของไม้",
  str_item_intro_3231204 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนชนชั้นสูง\nกระดิ่งเงินแกะสลักอย่างประณีตที่ทั้งเบาและพกพาง่าย ชนชั้นสูงทั้งหลายเชื่อว่าเป็นเครื่องรางนำโชค",
  str_item_intro_3232204 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนชนชั้นสูง\nแร่หายากที่เปล่งประกายเป็นสีต่าง ๆ ภายใต้ความเข้มของแสงที่ต่างกัน เป็นของขวัญในหมู่ชนชั้นสูง",
  str_item_intro_3233204 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนชนชั้นสูง\nเป็นวัตถุดิบแสนพิเศษและขาดแคลนที่เหล่าชนชั้นสูงเทิดทูน ส่วนใหญ่แล้วจะมาจากภูมิภาคอากาศหนาว มันนุ่ม เบา แต่ทนทานอย่างมาก",
  str_item_intro_3231205 = "ของขวัญทั่วไป ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่โผงผาง\nของพิเศษจากดินแดนรกร้าง คนขวานผ่าซากจะชอบรสชาติที่พิเศษของสิ่งนี้มาก",
  str_item_intro_3232205 = "ของขวัญล้ำค่า ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่โผงผาง\nกล่องเครื่องมือสำหรับสร้างและซ่อมสิ่งที่จำเป็น ของโปรดของคนที่ไม่ชอบเรื่องไร้สาระโดยเฉพาะ",
  str_item_intro_3233205 = "ส่งผลดีที่สุดเมื่อมอบให้ออโรเรียนที่โผงผาง\nสามารถวัดค่าประสิทธิภาพทางชีวภาพและเครื่องยนต์ได้ เป็นของที่สมบูรณ์แบบสำหรับคนชอบริเริ่ม",
  str_item_intro_3239997 = "เหล่านี้มาในทุกรสชาติ! มอบให้ Aurorians เพื่อเพิ่ม Affinity อย่างมาก",
  str_item_intro_3239998 = "มอบให้ออโรเรียนเพื่อเพิ่มสายสัมพันธ์ขึ้นอย่างมาก!",
  str_item_intro_3239999 = "ช็อกโกแลตอร่อยเกินห้ามใจ! มอบให้ออโรเรียนเพื่อเพิ่มสายสัมพันธ์ขึ้นอย่างมาก!",
  str_item_intro_3300001 = "สารที่แข็งมากแต่ไม่ใช่โลหะ\nเหมือนจะเป็นส่วนประกอบทางชีวภาพในสมัยโบราณกาล\nสามารถซ่อมพื้นที่เสียหายบางแห่งของโคลอสซัสและเชื่อม\nท่อพลังงานใหม่ได้",
  str_item_intro_3300002 = "เห็นได้ชัดว่าเป็นแผ่นวัสดุโคลอสซัสที่เสริมพลังแล้ว เพียงพอสำหรับเสริมความแข็งแกร่งให้ภายในของโคลอสซัส",
  str_item_intro_3300003 = "ไม่เพียงแต่ทนทานแต่ยังยืดหยุ่นด้วย มีข้อความลึกลับเลือนลางไปทั้งหมด เป็นวัตถุดิบที่จำเป็นสำหรับการฟื้นฟูสิ่งอำนวยความสะดวกสำคัญบางอย่างในโคลอสซัส",
  str_item_intro_3300004 = "จำเป็นสำหรับการอัปเกรดห้องบังคับการ การติดตั้งที่จำเป็นในโคลอสซัส หายากมาก กรุณาใช้งานด้วยความระมัดระวัง",
  str_item_intro_3300005 = "คิวบ์วิเศษที่มีโครงสร้างน่าสนใจ อาจเป็นสิ่งที่หลงเหลืออยู่ของนักสำรวจใจกล้า ถ้านำข้อมูลในนี้ไปใส่ลงในฐานข้อมูลของโคลอสซัส อาจปลดล็อกห้องใหม่ได้",
  str_item_intro_3300006 = "ปลั๊กอินนี้ฝังอยู่ในพื้นดินมานานหลายปีแล้ว มันดูเหมือนอันที่สูญหายไปจากโซรอซเมื่อสิบเจ็ดปีก่อนเป๊ะเลย สามารถใช้มันปลดล็อกห้องในโคลอสซัสได้",
