  str_item_intro_3400034 = "คอลเลคชั่นแจสเปอร์หลากหลาย รับแจสเปอร์ II สีละ 1 ชิ้น (น้ำเงิน แดง เหลืองหรือเขียว)",
  str_item_intro_3400035 = "แจสเปอร์ดิบที่มีสีสดใสกว่า รับแจสเปอร์ III แบบสุ่ม 1 ชิ้น (น้ำเงิน แดง เหลืองหรือเขียว)",
  str_item_intro_3400036 = "คอลเลคชั่นแจสเปอร์หลากหลาย รับแจสเปอร์ III สีละ 1 ชิ้น (น้ำเงิน แดง เหลืองหรือเขียว)",
  str_item_intro_3400037 = "ของขวัญจากแหล่งนิรนาม เปิดแล้วดูว่ามีอะไรอยู่ข้างใน\nใช้เพื่อรับของขวัญทั่วไปแบบสุ่ม 1 ชิ้น",
  str_item_intro_3400038 = "แพ็กของขวัญประณีตจากแหล่งนิรนาม ข้างในน่าจะมีของขวัญที่ดีกว่า ใช่ไหมนะ\nใช้เพื่อสุ่มรับของขวัญล้ำค่า 1 ชิ้น",
  str_item_intro_3400039 = "ของขวัญในกล่องอันน่าทึ่งนี้ต้องล้ำค่ามากแน่นอน เปิดเลย\nใช้เพื่อสุ่มรับของขวัญออโรเรียนที่มีค่าสูงมาก",
  str_item_intro_3400040 = "กล่องโปร่งแสงสร้างจากคริสตัลและเสริมให้แกร่งขึ้นด้วยลูมินาติกส์ ทั้งเบาและแข็งแรง มันมีลูมแอมเบอร์ล้ำค่าอยู่\nใช้เพื่อรับ 50 ลูมแอมเบอร์",
  str_item_intro_3400041 = "กล่องแข็งแรงสำหรับบรรจุทองที่ออกโดยลูโมโพลิส เห็นได้ทุกที่ในขณะนี้เพราะไนท์เทียมเป็นที่นิยม\nมี 100,000 ไนท์เทียม",
  str_item_intro_3400042 = "ตลับคริสตัลที่มีแสงส่องจาง ๆ และกักเก็บลูมินาไว้พอที่จะรีชาร์จปริซึมจนเต็ม\nใช้เพื่อรับ 10 ปริซึม",
  str_item_intro_3400043 = "กล่องคริสตัลจัตุรัสที่ตรงกลางส่องแสงซึ่งมอบพลังงานให้ปริซึมได้มากกว่า\nใช้เพื่อรับ 60 ปริซึม",
  str_item_intro_3400044 = "หีบขนาดใหญ่ที่สร้างขึ้นจากคริสตัลเจียระไนและตกแต่งสวยงาม มีลูมินามากพอที่จะรีชาร์จปริซึมด้วยพลังงานมากกว่าที่เคยมีมาก่อน\nใช้เพื่อรับ 50 ปริซึม",
  str_item_intro_3400045 = "ตลับคริสตัลขนาดใหญ่ที่มีแสงส่องจาง ๆ และกักเก็บลูมินาไว้พอที่จะรีชาร์จปริซึมจนเต็มหลายชิ้น\nใช้เพื่อรับ 60 ปริซึม",
  str_item_intro_3400046 = "กล่องเสบียงที่พัฒนาโดยแนวร่วมออโรเรียน รับวัตถุดิบสุ่ม 1 ชิ้นดังต่อไปนี้: หินรัตติกาลสีขาว แชมเปญแห่งชะตา I น้ำค้างยอดสน สารสกัดเรดีเซล บันทึกการต่อสู้ I คัมภีร์โบราณ เรื่องราวการเอาตัวรอด และยาเสริมกระดูก",
  str_item_intro_3400047 = "กล่องเสบียงที่พัฒนาโดยแนวร่วมออโรเรียน รับวัตถุดิบสุ่ม 1 ชิ้นดังต่อไปนี้: หินแห่งอุษา แชมเปญแห่งชะตา III น้ำแข็งยอดสน เรดีเซลเข้มข้น บันทึกการต่อสู้ II หนังสือโบราณ คู่มือการเอาตัวรอด 101 และยาล้างเนื้อเยื่อในกระดูก",
  str_item_intro_3400048 = "กล่องเสบียงที่พัฒนาโดยแนวร่วมออโรเรียน รับวัตถุดิบสุ่ม 1 ชิ้นดังต่อไปนี้: หินรุ่งอรุณ แชมเปญแห่งชะตา III น้ำตาต้นสน เรดีเซลเอสเซนส์ บันทึกการต่อสู้ III หนังสือโบราณ สารานุกรมการเอาตัวรอด และยาบำรุงการสร้างตัวใหม่",
  str_item_intro_3400049 = "ที่นอร์ธแลนด์มีหอคอยสูงตั้งตระหง่านพร้อมประภาคารที่ส่องสว่างอยู่บนยอด ตราบใดที่แสงนี้ไม่ดับลง อิคลิพไซท์จะไม่เป็นภัยคุกคามต่อดินแดนเหนือสุดของทวีป",
