  str_item_intro_3400052 = "ปลดล็อกพื้นหลัง: ผืนป่าหิมะ\nป่าทึบที่บริเวณชายแดนของนอร์ธแลนด์แห่งนี้ปกคลุมไปด้วยหิมะหนาทึบในฤดูหนาว ผู้ใดพลาดพลั้งเข้าไปในป่าที่งดงามนี้ล้วนต้องหลงวนเวียนอยู่ภายใน",
  str_item_intro_3400053 = "ปลดล็อกพื้นหลัง: สำนักตะวันออกไกล\nเป็นสถานที่ฝึกศิลปะการต่อสู้และการทำสมาธิซึ่งตั้งอยู่ที่ตะวันออกไกล",
  str_item_intro_3400054 = "ปลดล็อกพื้นหลัง: ท้องฟ้าตราตรึง\nในเมืองโบราณที่สาบสูญ ท้องฟ้าแห่งนี้เคยเป็นสถานที่ปลอบประโลมใจที่ยิ่งใหญ่ที่สุดสำหรับผู้อยู่อาศัย",
  str_item_intro_3400055 = "ปลดล็อกพื้นหลัง: เวทียังคงเดิม\nที่ที่สาว ๆ โชว์ลีลาการเต้นในฤดูร้อน แม้ว่าจะผ่านไปเนิ่นนานแล้ว แต่ทุกอย่างดูเหมือนจะไม่เปลี่ยนไปเลย",
  str_item_intro_3400056 = "ปลดล็อกพื้นหลัง: โถงทางเดินซากุระ\nโถงทางเดินและลานภายในสไตล์ตะวันออกไกลมีทัศนียภาพ\nเป็นเอกลักษณ์ในช่วงฤดูซากุระบาน",
  str_item_intro_3400057 = "ปลดล็อกพื้นหลัง: รถไฟผู้บัญชาการ\nเมื่อสี่ผู้บัญชาการกองทัพแห่งสหพันธรัฐอิลลูมินานั่งรถไฟขบวนพิเศษไปด้วยกัน จะต้องมีเรื่องสำคัญเกิดขึ้นแน่ ๆ...",
  str_item_intro_3400058 = "ปลดล็อกพื้นหลัง: โอเอซิส\nหนึ่งในฐานหลักของเรดีเซล เวรนช์ ตั้งอยู่ในภูมิประเทศที่มีความซับซ้อนและหลากหลาย",
  str_item_intro_3400059 = "ปลดล็อกพื้นหลัง: เทวทูตทั้งสี่\nผู้บัญชาการอัศวิน 4 คนเป็นตัวแทนของพลังที่เหนือกว่าผู้ใดของชนชั้นสูงลูโม",
  str_item_intro_3400060 = "ปลดล็อกพื้นหลัง: ปาร์ตี้ในคืนฤดูร้อน\nช่วงที่สนุกสุดเหวี่ยงของปาร์ตี้ในคืนฤดูร้อน สาว ๆ เพลิดเพลินกับเสียงเพลงอย่างเต็มที่ จนถึงทุกวันนี้ก็ยังคงได้ยินเสียงหัวเราะและร้องเพลงของพวกเธอ",
  str_item_intro_3400061 = "ปลดล็อกพื้นหลัง: เขี้ยวเพลิงลุกโชน\nหุบเขาที่ตั้งชื่อตามภูมิประเทศที่เว้าแหว่ง มีความลาดชันมากและยากต่อการนำทาง",
  str_item_intro_3400062 = "ปลดล็อกพื้นหลัง: คฤหาสน์ลึกลับ\nบ้านพักหรูหราที่ไม่ทราบที่มาและเจ้าของอย่างชัดเจน แต่ผู้อาศัยจะผ่อนคลายและไร้กังวลอย่างแน่นอน...",
