  str_item_intro_3400064 = "ปลดล็อกพื้นหลัง: คอร์ดลิงก์\nพลังงานลึกลับจากอวกาศลึกลับ...",
  str_item_intro_3400065 = "ปลดล็อกพื้นหลัง: เปียโนคู่\nยังจำตอนที่เริ่มใช้งานเจ้าสิ่งนี้กับไวซ์ได้มั้ย?",
  str_item_intro_3400066 = "ปลดล็อกพื้นหลัง: โคลอสซัสอีราเวล\nยานโคลอสซัสปรากฏขึ้นในอีราเวลอีกครั้งหนึ่งแล้ว มันมีความหมายอะไรรึเปล่านะ?",
  str_item_intro_3400067 = "ปลดล็อกพื้นหลัง: จดหมายจากสายลม\nสายลมนำจดหมายฉบับนี้มาให้ เพื่อบอกเคเลสไทต์ว่าได้เวลากลับบ้านแล้ว",
  str_item_intro_3400068 = "ปลดล็อกพื้นหลัง: สุสานเงียบสงบ\nสถานที่อันสงบเงียบในอีราเวล แม้แต่เวลาก็หยุดนิ่งในที่แห่งนี้",
  str_item_intro_3400069 = "ปลดล็อกพื้นหลัง: สำนักไปรษณีย์ตกแต่ง\nสำนักไปรษณีย์อีราเวลได้รับการตกแต่งใหม่ เตรียมฉลองกับค่ำคืนของวันหยุดในอีกไม่กี่วันนี้",
