  str_item_intro_3400072 = "ปลดล็อกพื้นหลัง: เงามืดแห่งราตรีกาล\nค่ำคืนของอัมบราตันกลืนกินทุกสิ่งที่สัมผัส ไม่รู้ว่าลำแสงจะทะลุผ่านได้หรือเปล่านะ?",
  str_item_intro_3400073 = "ปลดล็อกพื้นหลัง: คฤหาสน์แอนเดอร์เซน\nคฤหาสน์อันโอ่อ่านี้สะท้อนให้เห็นถึงความมั่งคั่งและความสง่างามของผู้เป็นเจ้าของ",
  str_item_intro_3400074 = "ปลดล็อกภาพพื้นหลัง: โรงแรมซากุระเมฆา\nอาหารดีงาม น้ำพุเลิศ แถมมีชุดยูกาตะให้ด้วย!",
  str_item_intro_3400075 = "ปลดล็อกภาพพื้นหลัง: ท่าเรือเมืองฮาร์เบอร์\nบริเวณข้างท่าเรือของเมืองฮาร์เบอร์เหมาะที่สุดสำหรับการเพลิดเพลินไปกับสายลมภายใต้ท้องฟ้าแจ่มใส!",
  str_item_intro_3400076 = "ปลดล็อกพื้นหลัง: คืนฤดูร้อน\nหากรักษาช่วงเวลานี้ให้คงอยู่ตลอดไปได้ นั่นจะเป็นความสุขสูงสุด",
  str_item_intro_3400077 = "ปลดล็อกพื้นหลัง: คำเตือนฟ้าผ่าที่ชายหาด\nฟาดเปรี้ยงลงมา แบบนี้จบเกมก่อนกำหนดแน่นอน!",
  str_item_intro_3400078 = "ปลดล็อกพื้นหลัง: Church Memory\nอาคารที่ผุพังใน Euphoria มันดีสำหรับที่พักพิงเท่านั้น เหมือนกับที่อื่นๆ เลย",
  str_item_intro_3400079 = "ปลดล็อกพื้นหลัง: ดินแดนลึกลับ\nดินแดนที่ซ่อนเร้นไร้ชื่อซึ่งมีการฝังอดีตมากเกินไป ความลับเหล่านี้จะได้เห็นแสงสว่างของวันอีกครั้งหรือไม่?",
  str_item_intro_3400080 = "ปลดล็อกพื้นหลัง: เสียสละ?\nเขาเลือกที่จะเสียสละตัวเองเพื่อต่อสู้กับสุริยุปราคาที่พุ่งเข้ามาหาเขา อย่างไรก็ตาม ไม่มีใครรู้ว่านี่เป็นเพียงส่วนหนึ่งของแผนของเขา...",
  str_item_intro_3400082 = "ปลดล็อกพื้นหลัง: Pursuit of Truth\nพวกเขาเชื่อว่าสิ่งที่โลกถือว่าความรู้ทั่วไปล้วนเป็นเท็จ ความจริงที่แท้จริงอยู่ไกลเกินกว่าที่ตาจะรับรู้ได้ เพียงแค่รอให้พวกเขาไล่ตาม",
  str_item_intro_3400083 = "ปลดล็อกพื้นหลัง: Colossus Stage\nมีเวทีที่มีอุปกรณ์ครบครันตั้งอยู่ใกล้กับบาร์บน Soroz เพื่อให้ทุกคนได้แสดงความสามารถของตน",
  str_item_intro_3400084 = "ปลดล็อกพื้นหลัง: เมืองร้างโบราณ\nแค่เห็นภาพอาคารขนาดใหญ่ที่พังทลายก็เพียงพอที่จะวาดภาพความหายนะในสงครามสมัยโบราณ",
  str_item_intro_3400085 = "ปลดล็อกพื้นหลัง: ภายใต้ท้องฟ้าฤดูหนาว\nหากคุณเห็นดาบส่องแสงและผมสีบลอนด์สว่างไสวไปในอากาศ เป็นไปได้ว่าราชินีแห่งทิศเหนือกำลังเคลื่อนตัวไปมาภายใต้ท้องฟ้าในฤดูหนาวขณะที่เธอเฝ้าดูอาณาจักรของเธอด้วยสายตาระแวดระวังในแต่ละฤดูหนาว",
  str_item_intro_3400086 = "ปลดล็อกพื้นหลัง: Aurora Sky\nแม้แต่ในนอร์ธแลนด์ แสงออโรร่าประเภทนี้ที่ปกคลุมทุกตารางนิ้วของท้องฟ้าและจางหายไปในขอบฟ้านั้นหาได้ยาก เขาว่าเมื่อไรก็ตามที่ปรากฏขึ้น อาจส่งผลถึงอนาคตโดยไม่รู้ตัว...",
  str_item_intro_3400087 = "ปลดล็อกพื้นหลัง: Road of Song\nในยักษ์ใหญ่ที่ท่องไปในดินแดนนับไม่ถ้วน ร่างของดาราหนุ่มผู้เจิดจรัสประดับห้องโถง เพลงศักดิ์สิทธิ์ของเธอที่เปี่ยมไปด้วยพลังแห่งความหวังจะแพร่กระจายไปทั่วทวีปในไม่ช้า",
  str_item_intro_3400088 = "ปลดล็อกพื้นหลัง: Deck of The Shadowind\nมีเพียงดาดฟ้าที่แข็งแรงและใหญ่โตนี้เท่านั้นที่สามารถรับปราสาทที่สูงเช่นนี้ได้",
  str_item_intro_3400089 = "ปลดล็อกพื้นหลัง: Eastern Docks\nท่าเทียบเรือ บ้าน และเรือของทวีปที่อยู่อีกฝั่งของทะเลค่อนข้างแตกต่างจากใน Astra แต่ฉากชีวิตที่จอแจและจอแจยังคงเหมือนเดิม",
  str_item_intro_3400090 = "ปลดล็อกพื้นหลัง: Comrades Noอีกต่อไป\nหลังจากต่อสู้เคียงบ่าเคียงไหล่กับจอมพล เอาชนะศัตรูด้วยกันนับไม่ถ้วน ถึงเวลาต่อสู้กับเธอแล้ว\nโชคชะตาทำไมคุณถึงเยาะเย้ยฉัน",
  str_item_intro_3400091 = "ปลดล็อกพื้นหลัง: Rediesel Courier\nสาขา Rediesel Desert ของ Courier Union ดูเหมือนจะค่อย ๆ ปรับตัวเข้ากับชีวิตในทะเลทราย Rediesel",
  str_item_intro_3400092 = "ปลดล็อกพื้นหลัง: สำนักงานของ Jeriah\nJeriah จัดการเรื่องประจำวันของเธอที่นี่และประทับที่นี่ด้วยสไตล์ส่วนตัวของเธอ",
  str_item_intro_3400093 = "ปลดล็อกพื้นหลัง: Carefree Place\nในบรรยากาศแบบนี้ ร้านกาแฟ ร้านอาหาร หรือบาร์ต่างก็มีหน้าที่ร่วมกันอย่างหนึ่งคือการพักผ่อน การพักฟื้น และสถานที่ให้ทุกคนมีช่วงเวลาพักผ่อนสบายๆ",
  str_item_intro_3400094 = "ปลดล็อกพื้นหลัง: Winter Wedding\nเครื่องประดับที่ใสเหมือนแก้วเหล่านี้สะท้อนถึงรูปร่างที่ไร้ที่ติและโปร่งใสของคู่รักและแสดงถึงความรู้สึกที่บริสุทธิ์ของพวกเขา แม้แต่ความหนาวเย็นก็ไม่สามารถต้านทานการสัมผัสใกล้ชิดกับหัวใจที่หลงใหลในงานแต่งงานในฤดูหนาวได้",
  str_item_intro_3400099 = "ปลดล็อกพื้นหลัง: เงาในเปลวไฟ\nขณะที่ปีศาจแผดเผาโจมตีจากรอบด้าน ร่างหนึ่งก็ยื่นมือเข้ามาช่วย...",
  str_item_intro_3400100 = "ปลดล็อกพื้นหลัง: ภาพรวมคลังสินค้า\nพื้นที่เก็บของรอบด้านจนสุดลูกหูลูกตา บางทีพวกเขาอาจซ่อนความลับของอดีตที่ไม่รู้จัก",
  str_item_intro_3400101 = "ปลดล็อคพื้นหลัง: วิวอัปทาวน์\nสวรรค์ที่สะอาดและสง่างาม ที่มีชื่อเสียงไม่ใช่เพียงแค่เป็นหัวใจที่ไม่สามารถปราบคว้าคุมของลูโมโพลิสเท่านั้น แต่ยังเป็นศูนย์กลางของทวีปคอนทิเนนต์ทั้งหมด",
  str_item_intro_3400102 = "ปลดล็อคพื้นหลัง: พี่น้องที่โลดเต้น\nฉากที่อบอุ่นของพี่น้องที่หัวเราะอยู่ในความสุข แม้วันและคืนจำนวนมากผ่านไปแล้ว แต่ความทรงจำยังคงสดใส และสลักอยู่ในหัวใจของพวกเขาตลอดไป",
  str_item_intro_3400103 = "ปลดล็อคพื้นหลัง: ยามราตรีพลาซ่า\nจัตุรัสกลางที่สง่างามในลูโมโพลิสส่องสว่างอย่างงดงามแม้ในยามค่ำคืน ยังคู่ควรกับความสว่างของกลางวัน",
  str_item_intro_3400109 = "ปลดล็อกพื้นหลัง: อุษาวิทยาลัยดอว์น\nมีสถานที่ในลูโมโพลิสที่ผู้ศรัทธาที่จริงใจศึกษาคำสอนของเทพเจ้าแห่งแสง และทุกคนที่ผ่านประตูที่เป็นที่เคารพนี้จะเต็มไปด้วยความนับถือ",
  str_item_intro_3400110 = "ปลดล็อกพื้นหลัง: ซากปรักหักพังลึกลับ\nในพื้นที่ลึกลับใต้แดนเหนือนี้ มันเหมือนว่ามีเครื่องจักรประดิษฐ์ที่ยังคงทำงานอยู่",
  str_item_intro_3400111 = "ปลดล็อกพื้นหลัง: แสงดาวอ่อนโยน\nคืนที่ไม่หลับตาคนเดียวบนสะพานใต้ท้องฟ้าเต็มดาว คุณยังสามารถได้ยินเสียงดนตรีของจักรวาลโดยไม่ต้องกดปุ่มในแผงควบคุม",
  str_item_intro_3400112 = "ปลดล็อกพื้นหลัง: บ่ายสงบ\nลูโมโพลิสเป็นที่บ้านของสวนเล็ก ๆ ที่อบอุ่นและซับซ้อน ที่ชนชั้นสูงชื่นชอบดื่มชาในยามบ่าย ความหายนะของโลกดูเหมือนจะห่างไกลจากที่นี่ถึงล้านไมล์",
  str_item_intro_3400113 = "ปลดล็อกพื้นหลัง: คลินิกใต้ดิน\nคลินิกที่ไม่ค่อยหรูหรา แต่เป็นที่เก็บความทรงจำที่มีค่าในใจ",
  str_item_intro_3400114 = "ปลดล็อกพื้นหลัง: มุมมืดที่สุด\nแม้หลงทางในความมืด แต่เธอยังคิดถึงการกอดครอบแสงสว่างอีกครั้ง",
  str_item_intro_3400115 = "ปลดล็อกพื้นหลัง: การต้อนรับ\nเฉพาะผู้ที่ได้รับการอนุมัติจากเชโอลเท่านั้นที่ได้รับอนุญาตให้พักอาศัยในห้องที่หรูหราและสะดวกสบายนี้",
  str_item_intro_3400116 = "ปลดล็อกพื้นหลัง: ทวีปใหม่\nShadowind ได้มาถึงทวีปใหม่อย่างประสบความสำเร็จ แต่นั่นไม่ได้หมายความว่าการผจญภัยของมันจบสิ้น เพราะยังมีสิ่งที่ไม่รู้จักเพียงพอที่รอคอยพวกเขา",
  str_item_intro_3400117 = "ปลดล็อกพื้นหลัง: เงามืดอยู่ทุกที่\nเจ้าแห่งเงายังคงเฝ้ามองอัมบราตัน และเงามืดจะคอยมองคุณอยู่เสมอ",
  str_item_intro_3400118 = "ปลดล็อกพื้นหลัง: ประวัติศาสตร์มืดมัว\nประวัติศาสตร์ที่ถูกปิดบังด้วยฝุ่นจะถูกเปิดเผยในวันหนึ่ง คนนี้เป็นผู้ปกครองที่ครองสมบัติอัมบราตันหรือเป็นฮีโร่ที่ช่วยชีวิตอัมบราตันหรือไม่?",
  str_item_intro_3400119 = "ปลดล็อกพื้นหลัง: ห้องรับแขก\nในห้องที่มีแสงสว่างพอเหมาะ มีการจัดวางสิ่งของและของตกแต่งต่าง ๆ อย่างเป็นระเบียบ ห้องนี้ถูกสรรค์สร้างมาเพื่อการทำงานและการต้อนรับแขก",
  str_item_intro_3400120 = "ปลดล็อกพื้นหลัง: มนต์เสน่ห์หลงโจว\nด้านตะวันตกของ Twin Pavilions Bay อยู่ภายใต้การจัดการของ Umbraton แต่ทางวัฒนธรรมแล้ว ความเป็นเอกลักษณ์ที่น่าตื่นตาตื่นใจของหลงโจวยังคงส่องสว่างอยู่ จากโคมไฟที่แขวนอยู่ในทุกถนนจนถึงขนมหลงโจวที่อร่อย ทั้งหมดนี้ทำให้เห็นภาพที่สดใสของแดนที่ห่างไกล ทำให้นักท่องเที่ยวที่มาที่นี่สามารถจมตัวเองได้อย่างเต็มที่ในวัฒนธรรมและประเพณีที่แปลกใหม",
  str_item_intro_3400121 = "ปลดล็อกพื้นหลัง: ท่าเรือของ Twin Pavilions Bay\nเรือบรรทุกที่ออกเดินทางจากทวีป Longzhou สุดท้ายจะจอดที่ท่าเรือใน Twin Pavilions Bay ที่พวกเขาทำการค้าและแลกเปลี่ยนสินค้าของก่อนที่จะกลับ ท่าเรือเหล่านี้มีบทบาทสำคัญในการขนส่งระหว่างทวีป Longzhou และ Astra",
  str_item_intro_3400122 = "ปลดล็อกพื้นหลัง: เทศกาลฤดูใบไม้ผลิในราชวงศ์จิ\nเทศกาลฤดูใบไม้ผลิเป็นเทศกาลที่สำคัญที่สุดในทวีปหลงโจว ราชวงศ์จะจัดงานเลี้ยงสำหรับแขกที่เคารพนับถือในขณะที่พลเมืองรวมตัวกันเพื่อสันทนาการและการติดตามข่าวสาร ในราชวงศ์จิ ชาวบ้านจัดงานวัด สักการะบูชาสาวมังกร และขับไล่สัตว์เนียนระหว่างเทศกาล หวังว่าจะมีสุขภาพและโชคดีในปีที่จะถึง มีพ่อค้าบางรายจ้างอสูรเพื่อจัดการแสดงที่มีธีมเกี่ยวกับพิธีไล่สัตว์ ทำให้เพิ่มความสนุกสนานในการเริ่มต้นปีใหม่",
  str_item_intro_3400126 = "ปลดล็อกพื้นหลัง: งานเลี้ยงสามัคคีในเทศกาลฤดูใบไม้ผลิ\nในหลงโจว, คืนของเทศกาลฤดูใบไม้ผลิเป็นเวลาที่ทุกคนรวมตัวกัน ชาวเคเลสไทต์และเพื่อนร่วมทางทั้งหมดในหลงโจวได้รวมตัวกันเพื่อทานอาหารที่อร่อยและมีความสุขในวันหยุดนี้ และขอให้ทุกคนมีเวลาที่ดีขึ้นในปีที่จะถึง",
  str_item_intro_3400123 = "ปลดล็อกพื้นหลัง: ทิวทัศน์คฤหาสน์\nด้วยทำเลทางภูมิศาสตร์ที่ไม่เหมือนใครและรากฐานวัฒนธรรมที่ลึกซึ้ง คฤหาสน์นี้บนเกาะอะซูไรท์มีทิวทัศน์ที่ทำให้หายใจหยุดและมีเสน่ห์ ทำให้เป็นสถานที่พักผ่อนที่โนเบิลลูโม่ชื่นชอบมาเดินเล่นและผ่อนคลาย",
  str_item_intro_3400129 = "ปลดล็อกพื้นหลัง: ถ้ำชายแดน\nลึกลงไปในถ้ำที่ปกคลุมด้วยน้ำแข็ง คอลัมน์น้ำแข็งเชื่อมโยงเรือนจ้างกับพื้นดิน ดูเหมือนประติมากรรมของเทพเจ้า ขณะที่แสงออโรร่าลงมา คอลัมน์น้ำแข็งที่สูงล้ำและขรุขระนี้และดอกไม้น้ำแข็งบนผนังถ้ำส่องสว่างในรูปร่างที่แปลกประหลาด สร้างบรรยากาศที่สงบและหนาวเย็นอย่างสมบูรณ์แบบ",
  str_item_intro_3400130 = "ปลดล็อกพื้นหลัง: ชายแดนที่ถูกหิมะปิดล้อม\nในวันที่หิมะตกหนัก ทะเลทรายหิมะที่ดูเหมือนจะไม่มีที่สิ้นสุดก็มีจุดสิ้นสุดอยู่—ภูเขาสูงๆยืนอยู่เหมือนกำแพงเมืองในท้องที่ไกล แบ่งแยกโลกออกเป็นสองส่วน บ้านเรือนเล็กๆที่ถูกหิมะและน้ำแข็งปิดทับสามารถมองเห็นได้เล็กน้อยที่ราบล่างของภูเขา ชีวิตที่นั่นต้องเต็มไปด้วยความเหงา ไม่ใช่หรือ?",
  str_item_intro_3400133 = "รับเพื่อปลดล็อกพื้นหลัง: แกนภูเขาไฟใต้ดิน\nหลังจากหลายปีที่ผ่านมา เรดีเซล เวรนช์ ผู้เร่ร่อนไม่เคยรู้ตัวว่าภูเขาไฟที่อยู่ใต้เท้าของพวกเขายังมีชีวิตอยู่อย่างต่อเนื่อง",
  str_item_intro_3400134 = "เมื่อได้รับจะปลดล็อกภาพพื้นหลัง: พระจันทร์เหนือทรายทะเลทราย\nนั่งอยู่ในทะเลทรายภายใต้ท้องฟ้ายามค่ำคืนนี้คือกลุ่มคนที่ไม่น่าจะเกิดขึ้น ดวงตาของพวกเขาเปล่งประกายในแสงดาว ความทรงจำของพวกเขาสัมผัสกัน",
  str_item_intro_3400135 = "ปลดล็อกพื้นหลัง: สเปียร์เฮด\nโครงสร้างภายในของมันเป็นไปอย่างราบรื่นและราบรื่นมากกว่าโซรอซ และแผงควบคุมแต่ละอันปล่อยออร่าที่อันตราย",
  str_item_intro_3400136 = "ปลดล็อกพื้นหลัง: ความสนุกที่ไฟแสนร้อน\nการกบฏและการเชื่อฟังเพียงแค่เป็นประเภทต่างๆของฟืนไฟ เมื่อมีความร้อนที่เหมาะสม ทั้งสองจะสามารถระเบิดและกลายเป็นลูกไฟที่หยุดไม่ได้!",
  str_item_intro_3400138 = "ปลดล็อกพื้นหลัง: Advent of Truth Parade\nคุณคือสัญลักษณ์ของปัญญารวมของทรู ออเดอร์ ทุกสิ่งที่คุณประสบจะนำทางทรู ออเดอร์สู่อนาคตที่ยิ่งใหญ่ขึ้นเรื่อยๆ",
  str_item_intro_3400139 = "ปลดล็อกพื้นหลัง: ชายหาดเกาะโดดเดี่ยว\nในทะเลที่ห่างไกล มีเกาะโดดเดี่ยวที่โลกลืมเลือน ล้อมรอบด้วยแอเชอร์ที่ไม่มีที่สิ้นสุดและปกคลุมด้วยพืชพรรณหนาแน่น ซากปรักหักพังโบราณอยู่ภายในเปลือกสีเขียวที่สะอาดสะอ้านนี้ ที่ได้รับการทนทานผ่านยุคสมัย.",
  str_item_intro_3400140 = "ปลดล็อกพื้นหลัง: การนัดพบที่ถูกกลืนโดยคลื่น\nเกาะนี้นอนอยู่อย่างเงียบ ๆ ที่ก้นทะเล พร้อมกับหลักฐานของความยิ่งใหญ่ในอดีต ตอนนี้ การผจญภัยในฤดูร้อนใหม่กำลังจะเริ่มขึ้น\nเพื่อนที่ยืนอยู่ข้างๆคุณคือสมบัติที่มีค่าที่สุด\nในเวลาจำกัดที่คุณมี สนุกกับการผจญภัยที่ไม่มีที่สิ้นสุดนี้กับเพื่อนของคุณ!",
  str_item_intro_3400141 = "ปลดล็อกพื้นหลัง: ความปรารถนาพันปี",
  str_item_intro_3400142 = "ปลดล็อกพื้นหลัง: พบกันอีกครั้ง\nเมื่อดวงดาวถึงจุดหมายของมัน\nเขาก้าวไปข้างหน้า สู่เพื่อนของเขาและสู่แสงแดด",
