  str_item_intro_3410605 = "คุณได้ทิ้งร่องรอยสำคัญไว้บน Codex ความอ้างว้างและได้รับรางวัลที่คุณสมควรได้รับ\nเปิดเพื่อรับวัสดุอัปเกรดแบบสุ่มต่างๆ พร้อมโอกาสเล็กน้อยที่จะได้รับ Star Flares!",
  str_item_intro_3410606 = "หีบสมบัตินี้คือหลักฐานความสัมพันธ์อันแนบแน่นของคุณกับสมาชิกนักล่าผู้เงียบงัน เปิดเพื่อรับรางวัลมูลค่าสูง",
