  str_item_intro_3410608 = "กล่องที่ได้รับระหว่างการฉลองคาร์นิวัลสุดอลหม่าน แม้จะไม่รู้ว่าข้างในกล่องมีอะไร แต่ใครบ้างล่ะที่ไม่ชอบเซอร์ไพรส์?",
