  str_item_intro_3410610 = "กล่องคำสั่งสีรุ้ง III. เปิดให้เลือกวัสดุแอสเซนชันขั้นสูง 1 รายการ",
  str_item_intro_3410611 = "กล่องคำสั่งสีรุ้ง IV. เปิดให้เลือก 1 วัสดุแอสเซนชันระดับพรีเมียม",
  str_item_intro_3410612 = "เลือก 1 อย่างจากผลึกโซลแอมเบอร์สายฟ้า, ผลึกโซลแอมเบอร์น้ำ, ผลึกโซลแอมเบอร์ไม้ และผลึกโซลแอมเบอร์ไฟ",
  str_item_intro_3410613 = "Rainbow Order Box I. เปิดเพื่อเลือก 1 วัสดุเลื่อนขั้นพื้นฐาน",
  str_item_intro_3410614 = "กล่องคำสั่งสีรุ้ง II. เปิดมันเพื่อเลือกวัสดุแอสเซนชันปกติ 1 ชิ้น",
  str_item_intro_3410615 = "รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนขั้นออโรเรียนเป็นขั้น III ได้แก่: แจสเปอร์ทั่วไป II ×300, ไนท์เทียม ×750,000, กล่องออเดอร์ร่วมมือ I ×10, กล่องออเดอร์ร่วมมือ II ×10, กล่องออเดอร์ร่วมมือ III ×10, กล่องออเดอร์สีรุ้ง I ×30, กล่องออเดอร์สีรุ้ง II ×50, กล่องออเดอร์สีรุ้ง III ×50 และกล่องออเดอร์สีรุ้ง IV ×20",
  str_item_intro_3410616 = "ความพยายามของคุณในการลาดตระเวนที่ยากลำบากและการขับไล่ที่อันตรายไม่ได้ไร้ประโยชน์ เปิดสิ่งนี้และดูว่าข้างในมีรางวัลอะไรบ้าง!",
  str_item_intro_3420101 = "ยอมรับการสนับสนุนของโคแร็กซ์ แล้วเขาจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญโคแร็กซ์แล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเขาขึ้นเป็นขั้น I เลเวล 10",
  str_item_intro_3420102 = "ยอมรับการสนับสนุนของลีโอนา แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญลีโอนาแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 10",
  str_item_intro_3420103 = "ยอมรับการสนับสนุนของมีอา แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญมีอาแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 10",
  str_item_intro_3420104 = "ยอมรับการสนับสนุนของอาเรีย แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญอาเรียแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 10",
  str_item_intro_3420105 = "ยอมรับการสนับสนุนของบาร์ตัน แล้วเขาจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญบาร์ตันแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเขาขึ้นเป็นขั้น I เลเวล 25",
  str_item_intro_3420106 = "ยอมรับการสนับสนุนของแม็กกี้ แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญแม็กกี้แล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 25",
  str_item_intro_3420107 = "ยอมรับการสนับสนุนของเนเมซิส แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญเนเมซิสแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 25",
  str_item_intro_3420108 = "ยอมรับการสนับสนุนของซิคาเร แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญซิคาเรแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น I เลเวล 25",
  str_item_intro_3420109 = "ยอมรับการสนับสนุนของไฮแดรด แล้วเขาจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญไฮแดรดแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเขาขึ้นเป็นขั้น II เลเวล 1",
  str_item_intro_3420110 = "ยอมรับการสนับสนุนของอีสต์วาน แล้วเขาจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญอีสต์วานแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเขาขึ้นเป็นขั้น II เลเวล 1",
  str_item_intro_3420111 = "ยอมรับการสนับสนุนของวิเวียน แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญวิเวียนแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น II เลเวล 1",
  str_item_intro_3420112 = "ยอมรับการสนับสนุนของลูอิส แล้วเธอจะร่วมผจญภัยไปกับคุณ!\nอัญเชิญลูอิสแล้วคุณจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนเธอขึ้นเป็นขั้น II เลเวล 1",
  str_item_intro_3420113 = "เลือกออโรเรียนหนึ่งรายจากออโรเรียน 6 ดาวที่กำหนดให้ต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>ฮิอิโระ/ซินซา/อีฟ/อูริเอล/คาร์ลีน/ชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ</color>.\nหมายเหตุ: ชุดอัญเชิญปีใหม่มีเวลาจำกัด เมื่อหมดอายุจะแปลงเป็น 3000 ลูมแอมเบอร์โดยอัตโนมัติและส่งให้คุณทางกล่องจดหมายในเกม กรุณาใช้ก่อนวันที่ 28 กุมภาพันธ์ 2022 เวลา 09:00 น. (UTC+0), 04:00 น. 28 กุมภาพันธ์ 2022 (UTC-5) กรุณาแปลงเวลานี้เป็นเขตเวลาของคุณเอง",
  str_item_intro_3420114 = "หลังจากใช้งาน คุณสามารถเลือกออโรเรียน 5 ดาวต่อไปนี้เพื่อเข้าร่วมการผจญภัยของคุณ\n（<color=#ffffff>เนเมซิส, บาร์ตัน, แม็กกี้, ซิคาเร</color>）",
  str_item_intro_3420115 = "หลังจากใช้ สามารถเลือกออโรเรียนหนึ่งราย (<color=#ffffff>ลูโคอา</color> หรือ <color=#ffffff>เอลมา</color>) ไปร่วมผจญภัยกับคุณ",
  str_item_intro_3420116 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ\n(<color=#ffffff>เฟาสต์, เคลเคน, แพกต์, หรือ เบเวอร์ลี</color>)",
  str_item_intro_3420134 = "หลังจากใช้งาน คุณสามารถเลือกออโรเรียน 6 ดาวต่อไปนี้เพื่อเข้าร่วมการผจญภัยของคุณ\n(<color=#ffffff>ซินซา, อีฟ, เฟลอร์, โจนา</color>)",
  str_item_3420134 = "กล่องเลือกอีลิทเรดีเซล",
  str_item_intro_3420117 = "เลือกออโรเรียนจากรายการออโรเรียน 5 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>คายาโนะ/เอริก้า/เดย์นา/วิเวียน/มีอา/เนเมซิส/เรจินา/โรบิน/เฟาสต์/เคลเคน/บาร์ตัน/คีตติง/ลูอิส/โนอาห์/ไฮแดรด/ชวาตส์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/แพกต์/โอดี/ฟิลิชี/โคแร็กซ์/เบนนี่กับคุโระ/คุสคูตา/อาเรีย/ซิคาเร /เบเวอร์ลี/ทาคิ/เจเนวีฟ/นาโรเซล/คอร์ดี้</color>.",
  str_item_intro_3420118 = "เลือก Aurorian จากรายการ 6 ดาวต่อไปนี้เพื่อร่วมรบไปกับคุณ: <color=#ffffff>ฮิอิโระ, ซินซา, อีฟ, อูริเอล, คาร์ลีน, ชาโรนา, ซาริเอล, ราฟาเอล, คอนนอลลี, คารอน, เอซี่, วิกตอเรีย, โจนา, นิคินิส, กาบริเอล, มิการ์ด, มิคาเอล, กรอนรู, อิริดอน, วราธ, เบริล, เฟลอร์, สโมคกี้, เรวี่, แกรม, พาโลม่า, เบเธล, ลุค, เฮดี้ หรือ โนวิโอ</color>.\nหมายเหตุ: ชุดอัญเชิญครบรอบ 1 ปี จะหมดอายุในวันที่ 31 สิงหาคม 2022 เวลา 09:00 น. (UTC+0), 04:00 น. 31 สิงหาคม 2022 (UTC-5). ถ้าไม่ได้รับภายในเวลานั้น มันจะถูกแปลงเป็น 3,000 ลูมแอมเบอร์โดยอัตโนมัติ ซึ่งจะถูกส่งถึงคุณผ่านกล่องจดหมายในเกม",
  str_item_intro_3420119 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ\n(<color=#ffffff>ไฮแดรด, อีสต์วาน, ลูอิส หรือ วิเวียน</color>)",
  str_item_intro_3420120 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ\n(<color=#ffffff>อาเรีย, ฟิลิชี, ชวาตส์ หรือ นาโรเซล</color>)",
  str_item_intro_3420121 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ\n(<color=#ffffff>ฟ็อกซ์, ไวโอเล็ต</color>)",
  str_item_intro_3420122 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ\n(<color=#ffffff>โคแร็กซ์, เบนนี่กับคุโระ, โอดี และ ชวาตส์</color>)",
  str_item_intro_3420123 = "เลือกออโรเรียนจากรายการออโรเรียน 5 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>ซานาเอะ/รอย/คายาโนะ/เอริก้า/เดย์นา/วิเวียน/มีอา/เนเมซิส/เรจินา/โรบิน/เฟาสต์/เคลเคน/บาร์ตัน/คีตติง/ลูอิส/โนอาห์/ไฮแดรด/ชวาตส์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/แพกต์/โอดี/ฟิลิชี/โคแร็กซ์/เบนนี่กับคุโระ/คุสคูตา/อาเรีย/ซิคาเร /เบเวอร์ลี/ทาคิ/เจเนวีฟ/นาโรเซล</color>.",
  str_item_intro_3420124 = "หลังจากใช้งาน คุณสามารถเลือกออโรเรียน 5 ดาวต่อไปนี้เพื่อเข้าร่วมการผจญภัยของคุณ\n(<color=#ffffff>โนอาห์, บาร์บาร่า, โอดี, คีทติ้ง</color>)",
  str_item_intro_3420125 = "เลือก Aurorian 5 ดาวจากรายการต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420126 = "นี่คือคำอวยพรจากเพื่อนร่วมผจญภัยของคุณ เลือก Aurorian จากรายการ Aurorian 5 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>ไฮดราด/อิสต์วาน/หลุยส์/รอย</color>.",
  str_item_intro_3420127 = "เลือก Aurorian จากรายการต่อไปนี้: <color=#ffffff>วิกตอเรีย, ราฟาเอล, คอนนอลลี่, ยูเรียล, กรอนรู, ชารอน, คาร์ลีน, ซินซา, ชาโรน่า, กาเบรียล, นิกินิส, อีฟ, โจน่า, ไมเคิล, ราธ, อิริดอน, ซาเรียล, เออิซี่, มิการ์ด, ฮิอิโระ, เบริล, เฟลอร์, สโมคกี้, เรวี่, กรัม, Paloma, Bethel, Luke, Hedy, Novio, Siobhan, Florine, Ruby, Rinne, Amemori, Yao, Azure, Lenore, Giles, Barton: Deft Blades</color>.\nหมายเหตุ: ชุดอุปกรณ์นี้จะหมดอายุเวลา 09:00 น. 31 มีนาคม 2023 (UTC+0) หรือ 04:00 น. 31 มีนาคม 2023 (UTC-5) รับตรงเวลา มิฉะนั้นจะถูกเปลี่ยนเป็น 3,000 Lumamber โดยอัตโนมัติและส่งถึงคุณทางกล่องจดหมายในเกม",
  str_item_intro_3420128 = "หลังจากใช้งาน คุณสามารถเลือกหนึ่งในออโรเรียน 5 ดาวต่อไปนี้เพื่อเข้าร่วมการผจญภัยของคุณ\n(<color=#ffffff>ไฮดรา หลุยส์ อิสต์วาน รอย</color>)",
  str_item_intro_3420129 = "เลือก Aurorian จากรายการ Aurorian 5 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>เบเร็ตต้า/คาสต้า/ชิเอล/ซาเน่/รอย/คายาโนะ/เอริก้า/เดย์น่า/วิเวียน/มีอา/กรรมตามสนอง/เรจิน่า/โรบิน/เฟาสท์/เคลเก้น/บาร์ตัน/คีทติ้ง/หลุยส์/โนอาห์/ไฮดรา/ชวาร์ตซ์/แม็กกี้/อิสต์วาน/บาร์บาร่า/ลีโอนา/ Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420132 = "เลือก Aurorian จากรายการ Aurorian 5 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>เบเร็ตตา/คาสต้า/ชิเอล/ซานาเอะ/รอย/คายาโนะ/เอริก้า/เดย์นา/วิเวียน/มีอา/เนเมซิส/เรจินา/โรบิน/เฟาสต์/เคลเคน/บาร์ตัน/คีตติง/ลูอิส/โนอาห์/ไฮแดรด/ชวาตส์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/แพกต์/โอดี/ฟิลิชี/โคแร็กซ์/เบนนี่กับคุโระ/คุสคูตา/อาเรีย/ซิคาเร /เบเวอร์ลี/ทาคิ/เจเนวีฟ/นาโรเซล/คอร์ดี้/คยา/คริสเตน/บลังค์: ปูรา คอร์ดิส/โจเซลีน</color>.",
  str_item_intro_3420135 = "เลือกออโรเรียนหนึ่งรายจากออโรเรียน 5 ดาวที่กำหนดให้ต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>เบเร็ตตา/คาสต้า/เซียล/ซานาเอะ/รอย/คายาโนะ/เอริก้า/เดย์นา/วิเวียน/มีอา/เนเมซิส/เรจินา/โรบิน/เฟาสต์/เคลเคน/บาร์ตัน/คีตติง/ลูอิส/โนอาห์/ไฮแดรด/ชวาตส์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/แพกต์/โอดี/ฟิลิชี/โคแร็กซ์/เบนนี่กับคุโระ/คุสคูตา/อาเรีย/ซิคาเร /เบเวอร์ลี/ทาคิ/เจเนวีฟ/นาโรเซล/คอร์ดี้/คยา/คริสเตน/บลังค์: ปูรา คอร์ดิส/โจเซลิน/อิซา/หลี่ เทียนเซียน</color>.",
  str_item_intro_3420130 = "เลือก Aurorian จากรายการต่อไปนี้: <color=#ffffff>วิกตอเรีย, ราฟาเอล, คอนนอลลี, ยูเรียล, กรอนรู, ชารอน, คาร์ลีน, ซินซา, ชาโรน่า, กาเบรียล, นิกินิส, อีฟ, โจน่า, ไมเคิล, ราธ, อิริดอน, ซาเรียล, เออิซี่, มิการ์ด, ฮิอิโระ, เบริล, เฟลอร์, สโมคกี้, เรวี่, กรัม, Paloma, Bethel, Luke, Hedy, Novio, Siobhan, Florine, Ruby, Rinne, Amemori, Yao, Azure, Lenore, Giles, Barton: Deft Blades, Nina, Carleen: Smoldering Soul, Fia, Jeno, Pollux, Lilica, Minos, Axelia, Vic</color>.\nหมายเหตุ: ชุดอุปกรณ์นี้จะหมดอายุเวลา 09:00 น. 31 สิงหาคม 2023 (UTC+0) หรือ 04:00 น. 31 สิงหาคม 2023 (UTC-5) รับตรงเวลา มิฉะนั้นจะถูกเปลี่ยนเป็น 3,000 Lumamber โดยอัตโนมัติและส่งถึงคุณทางกล่องจดหมายในเกม",
  str_item_intro_3430101 = "เปิดเพื่อเลือกโคแร็กซ์ ลีโอนา มีอา หรืออาเรีย และคุณยังจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนออโรเรียนขึ้นเป็นขั้น I เลเวล 10 อีกด้วย!",
  str_item_intro_3430102 = "เปิดเพื่อเลือกบาร์ตัน แม็กกี้ เนเมซิส หรือซิคาเร และคุณยังจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนออโรเรียนขึ้นเป็นขั้น I เลเวล 25 อีกด้วย!",
  str_item_intro_3430103 = "เปิดเพื่อเลือกไฮแดรด อีสต์วาน วิเวียน หรือลูอิส และคุณยังจะได้รับวัตถุดิบอัปเกรดทั้งหมดที่ต้องใช้ในการเลื่อนออโรเรียนขึ้นเป็นขั้น II เลเวล 1 อีกด้วย!",
  str_item_intro_3440001 = "ใช้เพื่อรับดาร์กช็อกโกแลต ลูมแอมเบอร์ และวัสดุอัปเกรดออโรเรียนแบบสุ่ม",
  str_item_intro_3440002 = "ใช้เพื่อรับ Sunny Sweets, Lumamber และวัสดุอัปเกรด Aurorian แบบสุ่ม",
  str_item_intro_3440003 = "กัปตัน Mu Yuebai มอบซองแดงให้ทุกคนเมื่อคุณเฉลิมฉลองเทศกาลฤดูใบไม้ผลิด้วยกันที่ Shadowind อะไรจะน่าประหลาดใจอยู่ข้างใน?",
  str_item_intro_3440005 = "ใช้เพื่อรับ Lumamber และวัสดุอัปเกรด Aurorian แบบสุ่ม",
  str_item_intro_3500001 = "วัตถุดิบปริศนาที่พบในซากโบราณ มันมีพลังมหาศาลและจำเป็นต่อการปรับปรุงอุปกรณ์",
  str_item_intro_3500003 = "เลื่อนขั้นออโรเรียนเป็นขั้น II Lv.1\nเรลิกโบราณลึกลับประกอบด้วยสสารและเปล่งประกายเจิดจ้า สามารถเพิ่มพลังของออโรเรียนสู่ระดับสูงได้",
  str_item_intro_3511001 = "เพิ่มระดับการตื่นตัวของธาตุน้ำ\nฝังลูกบาศก์ลึกลับที่ได้รับจาก Enlightener ลงบนแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกตื่นตัว",
  str_item_intro_3511002 = "เพิ่มระดับการรู้ตัวของธาตุน้ำ\nฝังคิวบ์ลึกลับที่ได้รับจากผู้สร้างความรู้ตัวลงในแท็บเล็ตอย่างลื่นไหลเพื่อเปิดใช้งานและเปิดเผยส่วนของการฝึกฝนความรู้ตัวแบบสุ่ม",
  str_item_intro_3511003 = "เพิ่มระดับการรู้ตัวธาตุน้ำ\nฝังคิวบ์ลึกลับที่ได้รับจากผู้สร้างความรู้ตัวลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกฝนความรู้ตัว",
  str_item_intro_3511004 = "เพิ่มระดับการตื่นตัวของธาตุน้ำ\nฝังลูกบาศก์ลึกลับที่ได้รับจากผู้สร้างแสงสว่างลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนสำคัญของการฝึกฝนในการตื่นตัว",
  str_item_intro_3511005 = "เพิ่มระดับความรู้สึกของธาตุน้ำ\nฝังลูกบาศก์ลึกลับที่ได้รับจาก Enlightener ลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเผยลำดับคีย์สำคัญของการฝึกความรู้สึก",
  str_item_intro_3512001 = "เพิ่มระดับการตื่นตัวด้วยไฟ\nฝังลูกบาศก์ลึกลับที่ได้รับจาก Enlightener ลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกสติตื่นตัว",
  str_item_intro_3512002 = "เพิ่มระดับการตื่นตัวด้านไฟ\nฝังลูกบาศก์ลึกลับที่ได้รับจากผู้กระจ่างให้เข้ากันอย่างลงตัวกับแท็บเล็ตเพื่อเปิดใช้งานและเปิดเผยส่วนของการฝึกตื่นตัวแบบสุ่ม",
  str_item_intro_3512003 = "เพิ่มระดับการตื่นตัวของธาตุไฟ\nฝังลูกบาศก์ลึกลับที่ได้รับจาก Enlightener ลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกฝนในการตื่นตัว",
  str_item_intro_3512004 = "เพิ่มระดับการตื่นตัวของธาตุไฟ\nฝังลูกบาศก์ลึกลับที่ได้รับจากผู้สร้างแสงสว่างลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนสำคัญของการฝึกฝนในการตื่นตัว",
  str_item_intro_3512005 = "เพิ่มระดับการตื่นตัวด้วยไฟ\nฝังลูกบาศก์ลึกลับที่ได้รับจาก Enlightener ลงในแท็บเล็ตอย่างลื่นไหลเพื่อเปิดใช้งานและเผยลำดับคีย์สำคัญของการฝึกตื่นตัว",
  str_item_intro_3513001 = "เพิ่มระดับความรู้สึกของธาตุไม้\nนำคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างใจนำไปฝังลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเผยแผนที่การฝึกความรู้สึก",
  str_item_intro_3513002 = "เพิ่มระดับการรู้สำหรับธาตุไม้\nฝังลูกบาศก์ลึกลับที่ได้รับจากผู้รู้ให้เข้ากันอย่างลงตัวกับแท็บเล็ตเพื่อเปิดใช้งานและเปิดเผยส่วนของการฝึกฝนในการรู้สุ่ม",
  str_item_intro_3513003 = "เพิ่มระดับการรู้สำหรับธาตุไม้\nฝังคิวบ์ลึกลับที่ได้รับจากผู้รู้ให้เข้ากันอย่างลงตัวในแท็บเล็ตเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกฝนในการรู้สึก",
  str_item_intro_3513004 = "เพิ่มระดับการรู้สำหรับธาตุไม้\nฝังคิวบ์ลึกลับที่ได้รับจากผู้สอนให้เข้ากันอย่างลงตัวกับแท็บเล็ตเพื่อเปิดใช้งานและเผยส่วนสำคัญของการฝึกฝนในการรู้สู่ตัว",
  str_item_intro_3513005 = "เพิ่มระดับการตื่นตัวของธาตุไม้\nฝังคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างให้เข้ากันอย่างลงตัวกับแท็บเล็ตเพื่อเปิดใช้งานและเผยลำดับคีย์สำคัญของการฝึกตื่นตัว",
  str_item_intro_3514001 = "เพิ่มระดับความรู้สึกของธาตุสายฟ้า\nนำคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างใส่ในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเผยแผนที่การฝึกสติความรู้สึก",
  str_item_intro_3514002 = "เพิ่มระดับความรู้สึกของธาตุสายฟ้า\nฝังคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างให้เข้ากันอย่างลงตัวกับแท็บเล็ตเพื่อเปิดใช้งานและเปิดเผยส่วนของการฝึกฝนความรู้สึกแบบสุ่ม",
  str_item_intro_3514003 = "เพิ่มระดับการรู้สำหรับธาตุสายฟ้า\nนำคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างใจนำไปฝังลงในแท็บเล็ตอย่างลงตัวเพื่อเปิดใช้งานและเปิดเผยส่วนหนึ่งของการฝึกฝนในการรู้สำหรับธาตุสายฟ้า",
  str_item_intro_3514004 = "เพิ่มระดับภูมิปัญญาธาตุสายฟ้า\nฝังคิวบ์ลึกลับที่ได้รับจากผู้กระจ่างให้เข้ากันอย่างลงตัวในแท็บเล็ตเพื่อเปิดใช้งานและเผยส่วนสำคัญของการฝึกฝนในการตื่นตัว",
  str_item_intro_3514005 = "เพิ่มระดับการตื่นตัวของธาตุสายฟ้า\nฝังคิวบ์ลึกลับที่ได้รับจาก Enlightener ลงในแท็บเล็ตอย่างลื่นไหลเพื่อเปิดใช้งานและเผยลำดับคีย์สำคัญของการฝึกตื่นตัว",
  str_item_intro_3621001 = "เก้าอี้บุเบาะที่มีพนักพิงหลังสูง รับส่วนหลังได้ดีและดูท่าทางงีบหลับได้สบาย",
  str_item_intro_3621002 = "โซฟาเล็กสำหรับนั่งคนเดียว เพราะว่าไม่มีพนักพิงหลัง อาจวางโต๊ะเล็ก ๆ ไว้ข้างหน้าโซฟาด้วยก็ดี",
  str_item_intro_3621003 = "โซฟากว้างที่นั่งได้สองคน แม้ว่านั่งคนเดียวจะสบายมากก็ตามที",
  str_item_intro_3621004 = "โซฟาไม่ธรรมดาที่นั่งได้สี่คน เหมาะสำหรับการรวมตัวที่ใหญ่กว่า",
  str_item_intro_3621005 = "โต๊ะหกเหลี่ยมขนาดเล็กที่มักใช้วางเครื่องดื่ม กาน้ำชา ถ้วยและจานของว่าง จะดีที่สุดถ้าวางไว้ในห้องปาร์ตี้ขนาดเล็ก",
  str_item_intro_3621006 = "โต๊ะน้ำชายาว ปกติมักจับคู่กับโซฟาเลิฟซีตหรือโซฟา 4 ที่นั่ง จะดีที่สุดถ้าวางไว้ในห้องปาร์ตี้ขนาดใหญ่",
  str_item_intro_3621007 = "เครื่องเสิร์ฟเครื่องดื่มอัตโนมัติ ตราบใดที่มีเครื่องดื่มในสต็อกพร้อมวัตถุดิบที่ถูกต้อง ยังไงก็ชงกาแฟโดยใช้แค่น้ำกับน้ำตาลไม่ได้อยู่แล้ว",
  str_item_intro_3621008 = "เครื่องดนตรีที่ใช้กันในเผ่าที่ไม่มีใครรู้จักในดินแดนห่างไกล แต่เริ่มเดิมทีเป็นที่นิยมในอัมบราตัน ปกติแล้วจะประกอบด้วยกลองใหญ่และกลองเล็กมากมาย รวมถึงฉาบด้วย อาจเพิ่มเครื่องดนตรีเคาะจังหวะอื่นมาด้วย ไม่ว่าจะกำหนดใช้อะไรอย่างไร ยังไงทั้งชุดก็จะเล่นโดยนักดนตรีคนเดียวเท่านั้น",
  str_item_intro_3621009 = "พืชขนาดเล็กในกระถางเล็ก ช่วยกรองอากาศในห้องและเพิ่มสีเขียวในห้องด้วย",
  str_item_intro_3621010 = "ต้นไม้ใส่กระถางที่สูงขนาดเท่าคน มันกรองอากาศรอบตัวแล้วทำให้ห้องเหมือนธรรมชาติมากขึ้น อีกทั้งยังเป็นที่ซ่อนตัวที่ดีอีกด้วย",
  str_item_intro_3622001 = "ภาพวาดทิวทัศน์ที่วิจิตรบรรจงและสลับซับซ้อน ทำให้ผู้ชมรู้สึกเห็นคุณค่าของความงดงามในธรรมชาติโดยไม่ต้องออกจากบ้าน",
  str_item_intro_3623001 = "โคมไฟรูปพระอาทิต์ที่สามารถติดกับเพดานได้ ชื่อนี้ได้มาเพราะแสงไฟเจิดจ้าและไฟส่องทั่วในบริเวณกว้าง",
  str_item_intro_3623002 = "ไฟเพดานในบ้านที่ติดตั้งง่ายและน้ำหนักเบาโดยมีเหล็กดาม ใช้ตกแต่งได้หลากหลายทำให้เป็นที่นิยมมาก",
  str_item_intro_3623003 = "ทำให้ห้องมีลมเย็น แต่เดิมใช้เดินลมสะอาดเข้าไปในเมืองใต้ดิน หลังจากนั้นไม่นานจึงถูกค้นพบว่าทำให้ห้องเย็น สดชื่นและสบายได้",
  str_item_intro_3623004 = "ไฟติดเพดาน ใช้ในเมืองรัฐหลายแห่งเพราะใช้พลังงานต่ำ แสงสว่างกว้างขวางและขนาดกะทัดรัด",
  str_item_intro_3623005 = "ไฟติดเพดานที่ห้อยลงมาจากเพดาน โครงสร้างล็อกแบบเกี่ยวทำให้จัดได้อย่างง่ายด้ายแต่ก็จะเหวี่ยงไปมาเมื่อแผ่นดินไหวหรือเกิดสภาวะอากาศลมแรงซึ่งเป็นอันตรายอย่างมาก ด้วยเหตุนี้ จึงห้ามใช้ไฟประเภทนี้บนเรือ",
  str_item_intro_3631001 = "การตกแต่งภายในอันหรูหราที่นำเข้ามาจากตะวันออกไกลทางกองเรือซึ่งครอบครองทะเลอยู่ สีและสไตล์โก้เก๋แต่บอบบางยามจับต้อง เวลาวางต้องระวังให้ดี",
  str_item_intro_3631002 = "ไอคอนรูปพระอาทิตย์ เงียบสงบและจริงจัง มันมอบศรัทธาให้แก่คนที่ได้เห็น",
  str_item_intro_3631003 = "ถังหายากที่งดงามสร้างโดยช่างฝีมือในตำนาน มีเพียงไวน์รสดีที่สุดเท่านั้นที่สามารถเก็บไว้ในภาชนะที่ล้ำค่าเช่นนี้ได้",
  str_item_intro_3631004 = "ว่ากันว่าดั้งเดิมมาจากตะวันออกไกล ชิ้นส่วนมีประโยชน์แต่เรียบง่ายนี้สามารถกันลม แยกพื้นที่และสร้างความเป็นส่วนตัวได้ นอกจากนี้ยังสามารถประดับเพื่อความสวยงามของพื้นที่โดยรอบและสร้างความรู้สึกที่ลึกลับให้เจ้าของได้ เป็นที่นิยมในเมืองใหญ่และเมืองแอสตราอย่างรวดเร็ว",
  str_item_intro_3631005 = "เครื่องกลขนาดใหญ่ชุบทองประดับด้วยอัญมณีพลอยหลายชนิดที่เป็นตัวแทนเหล่าเทหวัตถุ\nที่แตกต่างกันทั้งหลาย ช่วยให้นักวิชาการคุ้นเคยกับวิชาโหราศาสตร์และทำนายดวงได้อย่างรวดเร็ว\nแต่ความแม่นยำนั้นก็เป็นที่น่าสงสัย",
  str_item_intro_3632001 = "อุปกรณ์สื่อสารของสหพันธรัฐอิลลูมินาที่แต่เดิมใช้สื่อสารในเมืองใต้ดิน เมื่อการติดต่อกันระหว่างรัฐเมืองเพิ่มขึ้น การรับเทคโนโลยีนี้ไปใช้ก็เพิ่มขึ้นเช่นกัน",
  str_item_intro_3632002 = "จอกทองที่พบเห็นบ่อยครั้งในการฉลองลูโมโพลิส ผู้สร้างได้ชุบจอกนี้ด้วยลูมินาติกส์ปริศนา ทำให้มันมีปีกลวงตาที่ขยับได้",
  str_item_intro_3632003 = "กระดานนูนนี้แสดงภาพของประวัติศาสตร์โบราณของอารยธรรมลูโมโพลิส ว่ากันว่าแต่ละลายนั้นกล่าวถึงวรรณกรรมหลายอย่าง เมื่อชมแล้วจะรู้สึกถึงความเหนือกาลเวลา",
  str_item_intro_3632004 = "เชิงเทียนเพิ่มพลังลูมินาติกส์ แม้โดนควันก็ไม่เป็นสีดำ สามารถจุดไฟและดับไฟให้เทียนได้อัตโนมัติ",
  str_item_intro_3632005 = "นาฬิกาแขวนอันประณีตที่เกิดจากการผสมผสานสุดลงตัวของเครื่องจักรอิลลูมินาและงานฝีมือของลูโมโพลิส การใช้งานเบื้องต้นก็เพื่อการตกแต่งเท่านั้น แต่มันบังเอิญบอกเวลาได้ตรงด้วยเช่นกัน",
  str_item_intro_3641101 = "ชุดเกราะตกแต่ง เป็นการตกแต่งแบบดั้งเดิมในหมู่สมาคมชนชั้นสูงของลูโมโพลิส โดยเฉพาะกลุ่มที่มีประวัติเป็นนักรบมาก่อน อีกทั้งยังใช้ตกแต่งเพื่อนึกถึงมรดกด้านการต่อสู้ของบรรพบุรุษมียศศักดิ์และเพื่อเตือนไม่ให้มีนิสัยเจ้าสำราญในครอบครัวอีกด้วย",
  str_item_intro_3641201 = "เฟอร์นิเจอร์ตกแต่งที่ชาวอัมบราตันผู้รักในวัฒนธรรมชื่นชอบอย่างมาก ส่วนใหญ่แล้วจะสร้างขึ้นด้วยไม้ล้ำค่าและมีหนังสือคลาสสิกกับภาชนะมีราคาวางบนนั้น อย่างไรก็ตาม ก็คงมีคนสงสัยว่าเป็นของโบราณจริงแท้แค่ไหน",
  str_item_intro_3641301 = "ชั้นวางปืนไรเฟิลที่สหพันธรัฐอิลลูมินาสร้างขึ้น ช่วยเติมเต็มห้องทุกห้องด้วยจิตวิญญาณการต่อสู้ เมื่อเป็นหน้าที่ของกองกำลังหลักในการต่อสู้กับอิคลิพไซท์ จึงเกิดเฟอร์นิเจอร์ชิ้นนี้ขึ้น เทียบกับการออกแบบครั้งก่อนแล้ว ชั้นวางปืนไรเฟิลนี้โดยรวมแล้วจะเบากว่า แถมยังเพิ่มความมั่นคงสูงขึ้น",
  str_item_intro_3641501 = "โมเดลย่อขนาดของรถยนต์ที่มาพร้อมท่อ หมุดและแผ่นเหล็กทั้งหมด อีกทั้งยังมีบางส่วนที่เป็นไม้ด้วย โมเดลจิ๋วที่ปะติดปะต่อขึ้นมานี้เป็นภาพที่แสดงถึงความภาคภูมิใจและความสุขของเรดีเซล เวรนช์ มันคือรถเปิดประทุนพาวเวอร์บอล",
  str_item_intro_3641102 = "พรมที่ทำจากผ้าหรูหราโดยช่างผู้ชำนาญของลูโมโพลิสที่มีฝีมือช่างเก่งกาจ นี่ไม่ใช่พรมที่คนทั่วไปสามารถซื้อได้ นอกจากมีราคาค่อนข้างสูงแล้ว ยังเป็นสัญลักษณ์ของยศศักดิ์ด้วย",
  str_item_intro_3641202 = "พรมสีดำขนาดใหญ่ที่ผลิตขึ้นในอัมบราตัน นุ่มและหนา ทักถอขึ้นมาอย่างเชี่ยวชาญและเก็บเสียงเดินได้เงียบสนิท",
  str_item_intro_3641302 = "พรมทรงสี่เหลี่ยมที่มีลายถักเรียบร้อยทั้งแนวตั้งและแนวนอนบ่งบอกถึงสไตล์อุตสาหกรรมของสหพันธรัฐอิลลูมินา มองปราดเดียวก็รู้ว่าผลิตจากโรงงานในเมืองแกนน่อน ทนทานมาก",
  str_item_intro_3641402 = "พรมที่หนักและหนา ทอด้วยฝ้ายและขนสัตว์จำนวนมากของนอร์ธแลนด์ ช่วยให้รู้สึกสบายขึ้นแม้ในสภาพแวดล้อมที่หนาวที่สุด",
  str_item_intro_3641502 = "คนหยาบเรดีเซล เวรนช์ต้องสุ่มหยิบผ้าเก่ามาเย็บติดกันเพื่อทำเป็นพรมนี้ขึ้นมา กลิ่นเรดีเซลชี้ให้เห็นว่าต้องใช้เรดีเซลย้อมสีผ้านี้แน่นอน จะมีใครยอมจ่ายเงินจำนวนมากเพื่อซื้อและเก็บสิ่งนี้ไว้ที่บ้านไหม",
  str_item_intro_3641602 = "พรมแดงสะดุดตาที่มีลายที่แทบจะมองไม่เห็น เมื่อตรวจสอบใกล้ ๆ ลายนั้นดูเหมือนจะหมุนวนและสั่นเล็กน้อย ทำให้รู้สึกงงงวยและไม่สบายตาต่อคนที่จ้องมอง ใครจะซื้อพรมแบบนี้กัน",
  str_item_intro_3642102 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nงานชิ้นเอกที่สร้างสรรค์โดยจิตรกรไม่ทราบชื่อแห่งลูโมโพลิส ชิ้นงานต้นฉบับนั้นอยู่ในคอลเลคชั่นของขุนนางระดับสูง และแน่นอนว่านี่คือชิ้นงานจำลอง ทักษะการวาดที่ยอดเยี่ยมทำให้ผู้ชื่นชมผ่อนคลายอย่างอธิบายไม่ถูก และนี่คือเหตุผลที่ทำให้มีการทำซ้ำขึ้นมามากมาย แม้กระนั้นแต่ละชิ้นก็ยังมีราคาค่อนข้างสูง และผู้ซื้อก็พากันแย่งชิงเพื่อที่จะได้มีไว้ในครอบครอง",
  str_item_intro_3642201 = "กองกำลังใต้ดินของอัมบราตันสู้ในที่เปิดโล่งและเงามืด ดาบสองเล่มนี้ถูกใข้งานเมื่อมีข้อถกเถียงที่ประนีประนอมกันไม่ได้ ทั้งสองฝ่ายที่มีข้อพิพาทกันจะแต่งตั้งนักดาบขึ้นมาเพื่อประลองฝีมือด้วยดาบเพื่อตัดสิน",
  str_item_intro_3642301 = "ตัวอย่างของอิทธิพลกองทัพอันแข็งแกร่งที่มีต่อการตกแต่งบ้านของอิลลูมินา ปืนไรเฟิลนี้เป็นสิ่งแรกที่นึกถึงเมื่อชาวอิลลูมินาคิดจะตกแต่งกำแพง—ดูเหมือนพวกเขาจะพร้อมรบอยู่ตลอดเวลา",
  str_item_intro_3642401 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nแม้แต่ในเมืองหนาวอย่างนอร์ธแลนด์ มันก็ยังคงมีสีเขียวได้อย่างยาวนาน\nดังนั้นคนท้องถิ่นจึงมองว่ามันเป็นสัญลักษณ์แห่งความหวังและความ\nอุดมสมบูรณ์ โดยกล่าวกันว่า \"ถ้าขาดมิสเซิลโท ก็ขาดความสุข\"\nพวกเขามักเก็บต้นไม้ชนิดนี้มาถักเป็นพวง\nใช้ประดับบ้านเพื่อนำโชคลาภมาให้",
  str_item_intro_3641103 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nไอเทมนี้เป็นตัวแทนพลังอำนาจของเจ้าชายและขุนนางแห่งลูโมโพลิส มีการประดับประดาอย่างเว่อร์วังอลังการ ทั้งยังทำจากโลหะมีค่า มันแสดงถึงการล่อลวงของอำนาจ และเป็นสัญลักษณ์แทนภาระหนักอึ้งที่มาพร้อมกัน",
  str_item_intro_3641503 = "การผสมผสานกันของเศษโลหะ แผ่นเหล็กกล้า และหมอนปักหมุดจากที่ไหนก็ไม่ทราบได้... ถึงแม้จะดูดิบและเสียหายไปบ้าง แต่ก็นุ่มและแข็งแรงอย่างน่าประหลาด",
  str_item_intro_3651001 = "โมเดลหอคอยขนาดเล็ก เป็นแบบจำลองของหอคอยต้นแบบที่มีคุณภาพสูง เหมือนว่าจะมีพลังของหอคอยต้นแบบผนึกไว้ด้วย",
  str_item_intro_3651002 = "เจ้านี่เหมือนเป็นหอคอยเวอร์ชันจิ๋วที่สมจริงอย่างมาก คุณจะรู้สึกได้ถึงพลังลึกลับโบราณในหอคอยหากเข้าไปใกล้มัน",
  str_item_intro_3651003 = "มีเพียงผู้ที่สำรวจชั้นสูงสุดของหอคอยเท่านั้นที่จะได้รับของ\nตกแต่งนี้ ไม่เพียงแต่สมจริงมากเท่านั้นแต่ยังมีพลังของ\nหอคอยอยู่ด้วย เมื่อผู้คนเห็นสิ่งนี้แล้วจะรู้สึกเหมือนกำลังยืน\nอยู่หน้าหอคอยจริง ๆ",
  str_item_intro_3651004 = "นี่เป็นของที่ระลึกหายากที่มีเพียงผู้สำรวจหอคอยเท่านั้นที่จะได้รับ \nถึงแม้จะเป็นแค่โมเดลแต่ก็ดูเหมือนหอคอยไม่มีผิด \nถ้าคุณสังเกตดูอย่างละเอียดแล้วก็จะเห็นรายละเอียดหอคอยจริง\nมากมาย ว่ากันว่าสิ่งนี้ส่งผลกับหอคอยจริงได้ด้วย",
  str_item_intro_3651005 = "ของที่ระลึกสุดลึกลับที่หอคอยมอบให้ และสามารถรับได้จากการสำรวจส่วนลึกของหอคอยเท่านั้น บางคนบอกว่ามันเป็นสัญลักษณ์ของเจตจำนงแห่งหอคอยและการยอมรับในตัวผู้กล้าที่อาจหาญเข้าไปสำรวจ",
  str_item_intro_3651101 = "รูปแกะสลักอิคลิพไซท์จิ๋วที่พบในดินแดนลับ ดูเหมือนเป็นของที่ระลึกที่นักสำรวจคนอื่นทิ้งไว้ มันขาดความดุร้ายที่น่ากลัวของต้นฉบับอย่างมาก ออกจะดูน่ารักด้วยซ้ำ...พอคุ้นชินกับมันแล้วน่ะนะ",
  str_item_intro_3651102 = "พบลึกเข้าไปในดินแดนลับ รูปแกะสลักนี้น่าจะสร้างให้เหมือน\nอิคลิพไซท์ระดับสูงตัวหนึ่ง มันสร้างความหวาดกลัวให้ผู้คน\nมากมายด้วยใบหน้าที่น่าเกลียดน่ากลัว ถึงมันจะไม่ขยับเลยก็ตาม \nทว่าถ้าชินกับมันแล้วก็สามารถใช้มันไล่โจรขโมยที่ย่องเข้ามาใน\nห้องได้",
  str_item_intro_3651201 = "รูปแกะสลักหายากมากที่ดูเหมือนโซรอซ สร้างขึ้นด้วยลูมินาติกส์เข้มข้นของเพื่อนผู้นำทาง และผลิตด้วยเทคนิคการสร้างอันลึกลับของโซรอซ มันแสดงให้เห็นถึงสายสัมพันธ์ที่มั่นคงระหว่างโซรอซ ผู้นำทางและผองเพื่อน",
  str_item_intro_3662001 = "หลังจากรอดพ้นจากการไล่ตามของอิคลิพไซท์ โซรอซจึงวานให้หิ่งห้อยวาดรูปแขวนนี้\nจากภาพที่เก็บไว้เพื่อระลึกถึงครั้งแรกที่ทุกคนพบกันโดยเฉพาะ เกือบทุกคนคิดว่ารูปนี้\nเป็นภาพถ่าย เพราะฉากนั้นสร้างขึ้นมาใหม่อย่างสมจริง",
  str_item_intro_3661101 = "หินที่พบในหุบเขาตาแดงที่มีพลังภูเขาไฟเล็กน้อยอยู่ จับแล้วรู้สึกร้อน ทุกเมื่อเชื่อวันมันจะสร้างเสียงสั่นระงมหรือปะทุออกมาเล็กน้อยแต่ก็ค่อนข้างไร้พิษภัย คนที่ใจกล้าพออาจใช้สิ่งนี้ทำอาหารหรือเนื้อบาร์บีคิวได้",
  str_item_intro_3661102 = "ดอกไม้แห่งอรุณที่ขึ้นอยู่ในหุบเขาตาแดง มันจะเบ่งบานแต่ละครั้งในรอบหลายปี ดอกไม้สวยงามและตามภาษาดอกไม้จะหมายถึง \"ความหวังยามรุ่งอรุณ\"",
  str_item_intro_3662101 = "เพราะอาการป่วยของเธอทำให้อีฟดื่มได้แต่เพียงน้ำเย็นประมาณ 15 องศาและน้ำอุ่นประมาณ 45 องศา ในทะเลทรายเรดีเซลที่ขาดแคลนน้ำ ซินซามักจะพกขวดน้ำเก็บอุณหภูมิไว้กับตัวเสมอเพื่อให้น้องสาวมีน้ำดื่มตลอดเวลา เขาวาดรูปหน้ายิ้มลงบนขวดเพื่อให้น้องสาวมีความสุขด้วย",
  str_item_intro_3661103 = "ถึงแม้จะไม่มีสำนักแล้ว ชั้นวางดาบคาตานะของสำนักซาคาเอะก็เก็บรักษาอยู่ในสภาพดี ปัดฝุ่นและวางดาบคาตานะเพื่อสร้างสำนักซาคาเอะที่รุ่งเรืองในอดีตขึ้นมาใหม่",
  str_item_intro_3661104 = "ต้นเชอร์รีสีสันสดใสและหายากนี้พบในดินแดนภูเขาเมฆาเท่านั้น ผู้คนชอบเซ่นของทุกอย่างกับต้นไม้นี้เพื่อขอให้ความต้องการเป็นจริง",
  str_item_intro_3662102 = "ภาพวาดแปลกใหม่ของมังกรยิ้มแยกเขี้ยวและกรงเล็บเต้นระบำอย่างดุเดือด\nอย่างไรก็ดี แทนที่จะทำให้ผู้คนหวาดกลัวแต่มันกลับทำให้คนรู้สึกปลอดภัยอย่างประหลาด\nบางทีนี่อาจเกี่ยวข้องกับวัฒนธรรมเฉพาะของตะวันออกไกลก็ได้",
  str_item_intro_3661105 = "ดารุมะยอดนิยมในเขตภูเขาเมฆา เก็บตุ๊กตานี้ไว้ที่บ้านเพื่อนำโชคมาให้ มันอาจทำให้พรของเจ้าของเป็นจริงได้ด้วย",
  str_item_intro_3661106 = "ดารุมะที่ดูชั่วร้ายเล็กน้อย เก็บตุ๊กตานี้ไว้ที่บ้านเพื่อปัดเป่าโชคร้ายและป้องกันไม่ให้สิ่งชั่วร้ายมาเยือน",
  str_item_intro_3661107 = "ดารุมะที่เปล่งแสงสีทองออกมาทุกเมื่อเชื่อวัน เมื่อมองดูจะรู้สึกว่าโชคลาภกำลังเข้ามาหาคุณ ก็หวังว่ามันจะเป็นจริงนะ",
  str_item_intro_3661108 = "ดารุมะที่เป็นตัวแทนของความรู้ ว่ากันว่าตุ๊กตาให้พรนี้นำความสำเร็จด้านวิชาการมาให้ ดังนั้นนักศึกษามากมายจึงอธิษฐานกับดารุมะนี้ ตุ๊กตานี้น่าจะเป็นที่นิยมมากในเมืองแกนน่อน",
  str_item_intro_3661109 = "ว่ากันว่าทุกคนจะได้พานพบดารุมะที่เหมาะกับตัวเองที่สุด ตุ๊กตาเหล่านี้จะทำให้สมปรารถนาและอวยพรให้ตลอดชีวิตของคุณ",
  str_item_intro_3661110 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nแบบจำลองปราสาทริมทะเลที่พูดถึงกันมากเกินเหตุ ถ่ายทอดออร่าลึกลับและแปลกประหลาดได้อย่างสมบูรณ์แบบ มีเสียงพูดที่ฟังไม่ออกดังมาให้ได้ยินเป็นครั้งคราวจากภายในกำแพง ไม่ค่อยแตกต่างจากตำนานโบราณที่เกี่ยวข้องกับสิ่งก่อสร้างหลังนี้เท่าไรนัก",
  str_item_intro_3661111 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nหลังจากศึกษาเทคโนโลยีของโซรอซ เฟลอร์ได้สร้างเครื่องจักรกลขึ้นมา เรียกว่า \"เรดีเซล สตีล เอ็มเควี ซีโร่\" ซึ่งนี่คือแบบจำลองของเครื่องจักรกลดังกล่าว เมื่อเทียบกับของจริงแล้ว แบบจำลองนี้สามารถอวดสรรพคุณได้ว่ามีประสิทธิภาพดีกว่าของจริงต้นแบบ เรียกว่าสมบูรณ์แบบทีเดียว เว้นแต่ว่ามันเล็กมากแค่นั้นเอง",
  str_item_intro_3661112 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรถเข็นทำขึ้นเพื่อหารายได้พิเศษในช่วงฤดูร้อน มีอุปกรณ์พิเศษสำหรับทำน้ำแข็งก้อนแล้วบดให้เป็นน้ำแข็งไส มอบขนมหวานอร่อยล้ำให้กับลูกค้าผู้โชคดีในวันที่ร้อนระอุกลางฤดูร้อน แม้ฤดูกาลน้ำแข็งไสจะหมดไปแล้ว อุปกรณ์บนรถเข็นก็ยังใช้งานได้อยู่ และบางทีก็เดินเครื่องเองเสียด้วย... แสดงให้เห็นอย่างชัดเจนว่ามันเชื่อว่าตัวเองยังเด็กเกินกว่าที่จะเกษียณอายุ",
  str_item_intro_3661113 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโซฟาเป่าลมผลิตโดยโรงแรมทีร์ พร้อมติดตั้งปืนฉีดน้ำไว้ด้านหลัง ซึ่งจะพ่นน้ำออกมาเป็นระยะอย่างสม่ำเสมอ ทำให้ทุกคนรู้สึกเย็นฉ่ำและสดชื่นกลางแดดฤดูร้อนที่แผดเผา",
  str_item_intro_3661114 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโซฟาเป่าลมผลิตโดยโรงแรมทีร์ เครื่องพ่นน้ำที่อยู่ด้านหลังเบาะสามารถสร้างละอองน้ำได้เหมือนน้ำพุเป็นระยะอย่างสม่ำเสมอ แม้จะให้การผ่อนคลายที่มากกว่า แต่น้ำพุนี้ถือได้ว่ามีความรุนแรงมาก และบางครั้งก็ทำให้ผู้ที่นั่งอยู่ตกใจกลัวได้",
  str_item_intro_3661115 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโซฟาเป่าลมผลิตโดยโรงแรมทีร์ ต้องใช้งานด้วยความระมัดระวังเนื่องจากมีเครื่องจุดดอกไม้ไฟอัตโนมัติติดตั้งอยู่ด้านหลัง ซึ่งจะจุดดอกไม้ไฟหลากหลายประเภท ทำให้ผู้ที่อยู่ใกล้เคียงได้ชมการแสดงดอกไม้ไฟเล็ก ๆ มุมในการยิงดอกไม้ไฟนั้นวางใจได้ว่าผู้ที่นั่งอยู่ที่โซฟานี้พ้นจากอันตรายอย่างแน่นอน แต่ไม่ได้หมายความว่าจะไม่ทำให้อกสั่นขวัญแขวนนะ",
  str_item_intro_3661116 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโซฟาเป่าลมผลิตโดยโรงแรมทีร์ มือจับทั้งสองข้างนั้นที่จริงแล้วคือเครื่องพ่นฟอง เมื่อเปิดใช้งานจะมีฟองหลากสีลอยล่องขึ้นในอากาศ ทำให้เป็นที่ชื่นชอบอย่างมากในหมู่เด็ก ๆ",
  str_item_intro_3661117 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโซฟาน้ำเคลื่อนที่ผลิตโดยโรงแรมทีร์ หลังจากคลี่โซฟาออกมา สามารถนำอุปกรณ์ประดับต้นมะพร้าวมาประดับได้ เมื่อเติมน้ำแล้วจะทำให้รู้สึกเหมือนได้ไปชายทะเลทุกวันเลย",
  str_item_intro_3661118 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nกระดานโต้คลื่นผลิตโดยโรงแรมทีร์ ทำจากวัสดุพิเศษ จึงได้กระดานที่เบา ทนทาน และแข็งแรง รูปทรงที่สร้างสรรค์ด้วยความชำนาญเพื่อการเคลื่อนไหวที่ผิวน้ำทำให้กระดานโต้คลื่นนี้สามารถสยบคลื่นได้ทุกรูปแบบ",
  str_item_intro_3662103 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nของที่ระลึกถึงช่วงเวลาของคุณที่เทศกาลราชันมหาสมุทร เมื่อมองทะเลและท้องฟ้าสีสด ชายหาดที่มีต้นไม้เขียวพลิ้วไหว ก็รู้สึกประหนึ่งว่าคุณได้กลับไปที่ชายทะเลและสัมผัสวันแห่งความสุขอีกครั้ง",
  str_item_intro_3661119 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเมืองใต้ดินหมายเลข 24 คือฐานแห่งหนึ่งที่สำคัญของแนวป้องกันดูนไฟร์ และเป็นสถานที่ดำเนินการด้านระบบขนส่ง การฝึกฝน ปฏิบัติการทางการแพทย์ และอื่น ๆ อีกมาก แบบจำลองขนาดเล็กนี้สะท้อนให้เห็นถึงความครบวงจรของมันได้เป็นอย่างดี",
  str_item_intro_3661120 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโต๊ะวางกลยุทธ์นี้เคยเป็นของใช้ภายในของวิทยาลัยทหารสหพันธรัฐอิลลูมินา มีนักสำรวจพิเศษทำแผนที่แยกออกจากกัน แล้วลดสัดส่วนลงให้เหมาะสม โต๊ะนี้ประกอบด้วยทราย ไม้ และหุ่นจิ๋ว ซึ่งจำลองสถานการณ์การวางกลยุทธ์ในสนามรบจริงได้อย่างถูกต้อง และทำให้นักเรียนฝึกรับคำสั่งการรบได้ในสภาวการณ์การต่อสู้ต่าง ๆ",
  str_item_intro_3661121 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nส่วนหลักของกระดานชุดสะสมเหรียญตรานี้เป็นแผ่นเหล็กที่มีช่องจำนวนมาก ของชิ้นนี้ว่ากันว่าเป็นเครื่องสดุดีในความพยายามที่กล้าหาญของสโตนฟอร์ซในการต่อสู้กับอิคลิพไซท์ นอกจากนี้ยังเป็นสัญลักษณ์แห่งเกียรติยศที่ยั่งยืนของพวกเขาอีกด้วย เหรียญตราที่แขวนอยู่นั้นเป็นเครื่องแสดงว่าสโตนฟอร์ซไม่เคยไปไหนไกล และจะยืนหยัดอย่างมั่นคงอยู่ที่แนวป้องกัน ด้วยทหารรุ่นใหม่ ๆ ที่คอยต้านทานภัยคุกคามจากเหล่าอิคลิพไซท์",
  str_item_intro_3662104 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nส่วนกลางของสหพันธรัฐอิลลูมินากำหนดธงนี้ขึ้นมาเป็นพิเศษให้กับผู้ปกป้องของแนวป้องกันดูนไฟร์ เพื่อยกย่องพวกเขาที่ขับไล่การรุกรานครั้งใหญ่ของอิคลิพไซท์ได้สำเร็จ เมื่อไรก็ตามที่เหล่าผู้ปกป้องเห็นธงนี้โบกสะบัดอยู่ที่แนวป้องกัน เกียรติยศที่แฝงไว้กับธงนี้จะเตือนให้นึกถึงความเชื่อมั่นที่หนักแน่นจริงจังของพวกเขา เมื่อไรก็ตามที่ชีวิตต้องเผชิญกับภัยอันตราย คุณจะได้พบกับเรา",
  str_item_intro_3661122 = "ไม่ต้องห่วง ไม่มีศพคนตายฝังอยู่ที่นี่สักหน่อย ดังนั้นคุณก็เรียกป้ายนี่ว่าป้ายหลุมศพไม่ได้หรอกนะ ว่าไงนะ มือนั่นน่ะเหรอ อ๋อ มันเป็นแค่ส่วนหนึ่งของการแสดงน่ะ!",
  str_item_intro_3661123 = "ปรากฏตัวทุกครั้งที่คุณไม่ยอมให้ไนท์เทียม! คือ มันพูดไม่ได้หรอกนะ จริง ๆ แล้ว มันไม่ใช่ผี แต่เป็นแค่ไก่ที่คลุมผ้าปูเตียงอยู่น่ะ",
  str_item_intro_3662105 = "จริง ๆ แล้วโคมไฟนี้สร้างขึ้นจากแผ่นไม้ที่แกะสลักเป็นรูปฟักทอง เมื่อเปิดสวิตช์ จะมีแสงสว่างจากตา จมูก และปากของมัน ทำให้บรรยากาศดูน่าขนลุก",
  str_item_intro_3661124 = "สีขาวโพลนตั้งแต่ยอดถึงฐาน พร้อมยอดที่ตรงแบบไร้ที่ติ หอคอยสูงตระหง่านทำหน้าที่เป็นสัญลักษณ์ของอีราเวล โมเดลแสนประณีตนี้สร้างตามแบบของอนุสาวรีย์แห่งความภาคภูมิใจนั้นได้อย่างสมบูรณ์แบบ",
  str_item_intro_3661125 = "ตุ๊กตาเด็กชาวเคเลสไทต์ จะดูน่ารักมากถ้าตั้งไว้บนพื้น และดูเหมือนว่าหิ่งห้อยจะชอบกันเป็นพิเศษเลยนะ",
  str_item_intro_3661126 = "แดนดิไลออนที่ปลูกในกระถาง แม้ว่าดอกของมันจะดูบอบบางเหลือเกิน แต่พืชแสนทรหดนี้มีชีวิตรอดอยู่ได้ทุกที่ ขอแค่มีน้ำกับดินก็พอ",
  str_item_intro_3661127 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nนี่เป็นแค่โมเดลเฉย ๆ รึเปล่า? เปล่าเลย มันคือโลกจำลอง! นอกจากมีรถไฟเคลื่อนที่ได้แล้ว ยังมีภูมิทัศน์ธรรมชาติที่สมจริง ทั้งภูเขา แม่น้ำ และต้นไม้! แค่ดูรถไฟจำลองวิ่งในแถบภูเขาแป๊บเดียวก็รู้สึกเหมือนคุณเป็นส่วนหนึ่งของโลกจำลองนี้ เอาทิวทัศน์แสนสวยไปตั้งเถอะ",
  str_item_intro_3661128 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nทีนี้คุณก็ชมต้นไม้ฤดูใบไม้ร่วงสวย ๆ บนยานโคลอสซัสได้แล้ว! ด้วยเหตุผลบางอย่าง ต้นบอนไซนี้ยังคงสีสันแห่งฤดูกาลได้ตลอดปี ใบไม้สีเหลืองของมันร่วงหล่นเป็นครั้งคราว ทำให้คุณสุขใจกับฤดูใบไม้ร่วงอันน่าหดหู่แบบปลอม ๆ ได้ทุกที่ทุกเวลา แม้มันจะสร้างความเละเทะให้พวกหิ่งห้อยต้องทำความสะอาดก็ตามที",
  str_item_intro_3661129 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nดอกไม้นี้หันหน้าหาดวงอาทิตย์ตลอดเลย! ดูเจ้าไม้กระถางต้นเล็กที่มองโลกในแง่ดีนี่สิ... เอาไปไว้ในห้องของคุณและมองดูความอบอุ่นและมุมมองดี ๆ ที่เต็มเปี่ยมได้เลย",
  str_item_intro_3661130 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเข็มขัดทองที่เป็นสัญลักษณ์ของเกียรติยศและเป็นหลักฐานของการเสียเลือด หยาดเหงื่อ และน้ำตาของคุณในอารีน่าใต้ดินที่อัมบราตัน แม้ว่าคุณไม่อาจปล่อยให้คนอื่นแตะต้องมันได้ แต่ถ้าชื่นชมอยู่ไกล ๆ ก็ไม่เป็นไรหรอก",
  str_item_intro_3661131 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nธุรกรรมที่สมเหตุผลควรยุติธรรมกับทั้งสองฝ่าย ตาชั่งเคลือบทองนี้คือสัญลักษณ์ของการชั่งน้ำหนักสินค้า และเป็นตัวแทนของแนวคิดเรื่องความยุติธรรมที่เกิดกับทั้งสองฝ่าย จึงมักนำไปไว้ตามห้องโถงของกิลด์ต่าง ๆ ในอัมบราตัน เพื่อแสดงให้ผู้มาเยือนเห็นว่าธุรกรรมของพวกเขานั้นยุติธรรมและซื่อสัตย์",
  str_item_intro_3662106 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nพัดที่เต็มไปด้วยวัฒนธรรมต่างแดน ทำจากกระดาษเหนียวนุ่ม ภาพวาดบนพัดแสดงออกถึงศิลปะแบบแปลกตาที่ไม่ค่อยพบเห็นในซีกโลกนี้",
  str_item_intro_3662107 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโมเสกกระจกสีที่ทำขึ้นโดยช่างฝีมือลูโมโพลิสที่งดงามเหนือธรรมชาติ เมื่อต้องแสง จะสะท้อนสีสันสดใสออกมาเป็นภาพปรากฏที่งดงามน่าอัศจรรย์",
  str_item_intro_3661132 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nว่ากันว่านอร์ธแลนด์เคยมีมังกรน้ำแข็งลาดตระเวนอยู่บนฟ้า แต่ตอนนี้มันไม่มีอันตรายแล้วเพราะว่าเป็นแค่รูปปั้น แต่ก็ยังแผ่ลมที่เย็นเยือกออกมาได้อยู่ดี จะดีอะไรอย่างนี้!",
  str_item_intro_3661133 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nราวแขวนกับเสื้อคลุมนี้ดูธรรมดาก็จริง แต่คนเก่าคนแก่ในนอร์ธแลนด์บอกว่ามันมีตำนานเบื้องหลังที่น่าพิศวงมาก...",
  str_item_intro_3661134 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nตามตำนานของนอร์ธแลนด์ หากสวมใส่มันจะทำให้คุณพบรักแท้!",
  str_item_intro_3661135 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nบ้านที่พบมากที่สุดในนอร์ธแลนด์ จำลองเหมือนจริงกระทั่งควันที่ปล่อยออกมาเป็นระยะจากปล่องบนหลังคาที่มีหิมะปกคลุม แสงจากหน้าต่างทำให้คิดไปว่าบ้านจำลองหลังนี้มีคนอยู่ข้างใน",
  str_item_intro_3662109 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nหัวกวางเรนเดียร์ แต่ไม่ใช่ของจริง ที่จริงแล้วมันคือขนสัตว์ยัดไส้เศษไม้ และมีกลไกพิเศษที่ทำให้ดวงตาขยับได้เป็นระยะ!",
  str_item_intro_3661136 = "เฟอร์นิเจอร์สำหรับห้องบนโคลอสซัส\nไม่มีอะไรแสดงความรักได้ดีกว่าการทำอาหารและเสิร์ฟส่วนหนึ่งของร่างกายตัวเองให้อีกแล้ว ดูจากจำนวนของไขมันแล้ว โทรุมั่นใจว่ารสชาติหางของเธออร่อยเหาะ เธอเป็นเจ้าแห่งการปิ้งย่างเพราะฝึกฝนมาจนชำนาญเต็มที่ แต่ยังไงก็ต้องระวังหน่อยเพราะมันมีพิษนะ",
  str_item_intro_3661137 = "เฟอร์นิเจอร์สำหรับห้องบนโคลอสซัส\nงานฝีมือที่โทรุทำไปโดยสัญชาตญาณ สำหรับมังกรแล้ว ศิลปะของมนุษย์นั้นยากที่จะเข้าใจได้เพราะวัตถุและขั้นตอนต่างก็ง่ายดายเกินไป โทรุเลียนแบบงานของคนในการทำไม้แกะสลักนี้ เธอไม่สนใจว่าทำไปเพื่ออะไร แค่ให้เป็นที่ชื่นชมก็พอ",
  str_item_intro_3662110 = "เฟอร์นิเจอร์สำหรับห้องบนโคลอสซัส\nการถ่ายเซลฟี่หมู่เป็นสิ่งที่ขาดไม่ได้เมื่อไปออกทริปกับผองเพื่อน! ยืนชิด ๆ กันหน่อยสิ... มันยากนะที่จะอัดมังกรตั้งห้าตัวให้อยู่ในรูปเดียวกัน... เซย์ชีส!",
  str_item_intro_3661138 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nเปียโนที่พบในเมืองที่สาบสูญ แม้ว่าจะมีสไตล์คล้ายกับเปียโนบางตัวในแอสตรา มันถูกสร้างขึ้นอย่างปราณีตและยังคงให้เสียงที่ไพเราะแม้จะผ่านไปหลายปีแล้ว แม้ว่าเสียงจะเบาไปหน่อย แต่ก็ยังปรับได้ตามโครงสร้างภายในที่เป็นเอกลักษณ์! ช่างเป็นของล้ำค่าที่หายากสำหรับนักดนตรี!",
  str_item_intro_3661139 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nชิ้นงานที่ดูเรียบ ๆ แตกต่างไปจากสไตล์เรียบง่ายทั่วไปของอิลลูมินา ด้วยพื้นผิวเรียบที่เป็นเอกลักษณ์และการออกแบบที่สวยงาม แม้แต่คนจากลูโมโพลิสก็ยังชื่นชอบ",
  str_item_intro_3661140 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nพรมที่พบในเมืองที่สาบสูญ ไม่เพียงแต่ทำจากวัสดุที่พิเศษมากเท่านั้น ลวดลายรูปข้ามหลามตัดที่สลับตัดกันยังทำให้ดูโดดเด่นยิ่งขึ้น",
  str_item_intro_3661141 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nพบเห็นได้ทั่วไปในเมืองที่สาบสูญ มีอยู่มากมายจนเกือบจะเหมือนกับไฟถนน ดูจะเป็นสิ่งที่ดึงดูดใจมากกว่าป้ายจราจร... หน้าจอมีรูปแบบที่เปิดและปิดอยู่ตลอดเวลา เป็นไปไม่ได้เลยที่จะรู้ว่ามีอะไรอยู่ข้างใน วิธีเดียวที่จะรู้ได้คงต้องทุบให้แตก",
  str_item_intro_3661142 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nกล่องจดหมายที่พบในเมืองที่สาบสูญ เนื่องจากรอยสลักบนนั้นจางลง ตอนแรกจึงเข้าใจผิดว่าเป็นกล่องเสบียงสำหรับกรณีฉุกเฉิน จนกระทั่งพบจดหมายอยู่ภายในจึงได้รู้ว่ามันคือกล่องจดหมาย แต่ดูเหมือนจะไม่มีใครใช้มันแล้ว",
  str_item_intro_3661143 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nของประดับทั่วไปที่ตั้งไว้ริมถนนในเมืองที่สาบสูญเพื่อให้ผู้สัญจรไปมาได้พักผ่อน ถ้าตั้งไว้ที่บ้านก็ใช้นั่งหรือเอนนอนได้",
  str_item_intro_3661144 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nหลังจากผ่านไปหลายปีก็ยังเหมือนเดิมอย่างน่าอัศจรรย์! เทคโนโลยีในเมืองที่สาบสูญนั้นน่าทึ่งมาก เมื่อใส่กระดาษเข้าไปมันจะตัดเป็นเส้นเล็ก ๆ ทันที ทำให้ไม่มีใครเข้าใจข้อความในกระดาษได้",
  str_item_intro_3661145 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nมันยังคงอยู่ในสภาพที่ยอดเยี่ยมหลังจากผ่านมาหลายปี... แต่ไม่มีใครใช้งานแล้ว การจัดระเบียบเล็กน้อยเผยให้เห็นหน้าโต๊ะที่สะอาดและไม่รก และอุปกรณ์สำนักงานทุกประเภทที่เติมพลังงานให้กับสำนักงานได้",
  str_item_intro_3661146 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nไม่เพียงแต่หมุนได้รอบตัว แต่ยังปรับความสูงของเบาะได้อีกด้วย แม้แต่พนักพิงก็ลดระดับลงได้ ผู้ใช้สามารถนอนราบลงพักสายตาได้อย่างสบาย ในแง่ของบรรยากาศ การวางคู่กับโต๊ะจะสร้างความรู้สึกเป็นหนึ่งเดียวที่ยอดเยี่ยม คราวนี้ก็ทำงานจนลืมเวลาไปได้เลย",
  str_item_intro_3661147 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nเครื่องประดับจากตะวันออกไกล ทำจากไม้ไผ่และต้องใช้น้ำไหลเป็นตัวขับเคลื่อน กลไกอันชาญฉลาดของมันทำให้เกิดเสียง \"ติ๋ง\" ที่ฟังแล้วสบายใจและมีความสุขเป็นช่วงจังหวะที่แน่นอน ซึ่งใช้เป็นตัวจับเวลาได้ด้วย",
  str_item_intro_3661148 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nต้นไผ่ที่เติบโตอย่างรวดเร็วซึ่งต้องตัดแต่งกิ่งเป็นประจำ แม้จะยุ่งยากไปบ้าง แต่คุณจะได้กระบอกไม้ไผ่เป็นกระบุง และเสียงกรอบแกรบเวลาใบไผ่ลู่ลมก็ให้ความรู้สึกที่สดชื่นเช่นกัน",
  str_item_intro_3663001 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nตุ๊กตาที่แขวนอยู่ใต้ชายคา ทำง่ายและน่ารักมาก ๆ เมื่อลมพัดมา\nมันจะเต้นรำไปกับสายลมราวกับภาวนาให้ฝนหยุดตก\nถ้าได้ผลก็แสดงว่าสวรรค์มองเห็นการเต้นรำของตุ๊กตาเหล่านี้",
  str_item_intro_3661149 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nหมวกที่นักรบตะวันออกไกลสวมใส่ ตกแต่งด้วยเครื่องประดับระดับสูงที่สุดซึ่งกล่าวกันว่าไม่เพียงแต่แสดงถึงพลังหรือสังกัดของนักรบเท่านั้น ที่สำคัญยิ่งกว่าคือมันเป็นสัญลักษณ์แห่งเกียรติยศ",
  str_item_intro_3661150 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nเดิมทีเป็นธงที่ทหารหรือซามูไรปักไว้ที่หลังเพื่อนำทางกองทัพแนวหลังในการสู้รบ เมื่อนำมาประดับบ้านจะให้ความรู้สึกเคร่งขรึม",
  str_item_intro_3662111 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nอักษรวิจิตรของตะวันออกไกลอันเลื่องชื่อที่มักเขียนโดยนักประดิษฐ์ตัวอักษร แต่แน่นอนว่าส่วนใหญ่เป็นเพียงฉบับสำเนา ตัวอักษรเหล่านี้ถือเป็นความงามสุดพิเศษในสายตาของชาวตะวันออกไกล และแทบเป็นไปไม่ได้ที่บุคคลภายนอกจะชื่นชม",
  str_item_intro_3661151 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nแม้จะเรียกว่า \"ทิวทัศน์\" แต่คำว่า \"เซน\" นั้นบ่งชี้ว่าทิวทัศน์จำลองนี้\nเป็นแบบแห้ง ใช้ทรายละเอียดแทนน้ำ และใช้หินแทนภูเขา\nในตะวันออกไกลมีความเชื่อว่าทิวทัศน์ที่มีความคงที่จะช่วยให้\nมีสมาธิและจิตใจสงบ",
  str_item_intro_3661152 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nไฟถนนที่ตกแต่งในสไตล์ตะวันออกไกลซึ่งพบได้ทั่วไปบนเกาะเมฆา คนที่นี่ไม่ได้ใช้ไฟแบบนี้เพื่อให้แสงสว่างเท่านั้น แต่ยังใช้เป็นป้ายบอกทางอีกด้วย",
  str_item_intro_3663002 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nชาวเมืองโคฟุโจแขวนโคมไฟเหล่านี้ไว้ที่ประตูเพื่อให้แสงสว่าง\nและโคมไฟจากบ้านแต่ละหลังก็ทำให้ถนนสว่างไสวราวกับเป็น\nเวลากลางวัน นอกจากนี้ยังนำไปแขวนกับท่อนไม้ไผ่เพื่อใช้\nส่องทางในยามค่ำคืนได้ด้วย",
  str_item_intro_3661159 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nหอกที่มอบให้คาร์ลีนเมื่อเธอได้รับแต่งตั้งเป็นอัศวิน ต่อมากลายเป็นอาวุธต่อสู้ประจำตัวของเธอ แม้ว่านี่จะเป็นเพียงของจำลอง แต่ก็ยังคงปล่อยพลังดักแด้จันทราเมื่อวางไว้ที่บ้าน...",
  str_item_intro_3662116 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nของประดับชิ้นโปรดของ Tourdog โปรดิวเซอร์ชื่อดัง เขาบอกว่าถ้าแขวนสเลทนี้ไว้บนผนังบ้าน เขาก็มักจะได้ยินเสียงตบฉับ ๆ ดังออกมา ซึ่งเป็นแรงกระตุ้นให้เขาเริ่มต้นวันใหม่ในการทำงาน เมื่อเห็นว่าเขาทำงานอย่างขยันขันแข็ง ผู้ชมก็เกิดมีกำลังใจในการทำงานหนักเช่นกัน",
  str_item_intro_3661153 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nของคู่กายสำหรับเชียร์ลีดเดอร์ในงานแข่งขันแรลลี่เพื่อใช้ประกอบท่าเต้นเชียร์ทั้งหลาย แต่ว่ามีคนปรับปรุงปอมปอมคู่นี้โดยติดตั้งชิ้นส่วนประหลาดเข้าไป และตอนนี้มันก็เชียร์ของมันเองได้เสียด้วย ตอนแรกคุณอาจคิดว่ามันแปลก แต่พอชินแล้วจะคิดว่าตลกดี",
  str_item_intro_3661154 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nยางรถแข่งเก่า ๆ ที่รีไซเคิลนำมาใช้ใหม่โดยวางซ้อนกันเป็นชั้น\nเพื่อทำเป็นเก้าอี้ เป็นชิ้นงานที่ดูดิบแต่นุ่มมาก",
  str_item_intro_3662112 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nธงนี้ว่ากันว่าเคยเป็นธงประจำเส้นชัยของแรลลี่เพลิงลุกโชน ผู้เข้าร่วมการแข่งขันชอบนำกลับไปตกแต่งบ้าน หรือแขวนไว้ในรถเพื่อเป็นที่ระลึก",
  str_item_intro_3661155 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nทุกปี สมาชิกเกือบทั้งหมดของเรดีเซล เวรนช์จะมาเข้าร่วมแข่งขันกัน\nในแรลลี่ที่พวกเขาจัดขึ้นเอง ซึ่งก็สามารถดึงความสนใจจากผู้ชม\nทุกแขนงมาได้ ถ้วยรางวัลของงานนี้คือเครื่องพิสูจน์ถึงความสามารถ\nที่เก่งกาจในการแข่งแรลลี่ของผู้ที่ได้ครอบครอง",
  str_item_intro_3661156 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nต้นไม้ที่มักงอกงามได้เฉพาะในทะเลทราย ทานทนต่อสภาพอากาศที่หนาวเย็นและร้อนจัดแบบสุดขั้ว พืชชนิดนี้อยู่ในกลุ่มไม้ในร่มที่อึดที่สุดและแทบไม่ต้องรดน้ำเลย ระวังหนามด้วยนะ!",
  str_item_intro_3662113 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nแม้จะถูกเรียกว่า \"ยางรถยนต์มีพลัง\" แต่ที่จริงแล้วก็เป็นแค่ยางรถธรรมดาสำหรับรถแข่งเท่านั้น แต่อย่างไรก็ดี เมื่อนำไปประดับไว้บนฝาผนัง ก็จะทำให้ห้องเต็มไปด้วยบรรยากาศอันน่าตื่นเต้นของแรลลี่ได้",
  str_item_intro_3661157 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nสมาชิกทรู ออเดอร์บอกว่า มีผู้ค้นพบคัมภีร์นี้ในซากโบราณ มันไม่มีข้อความอะไรเขียนอยู่เลย แต่พวกที่ทรู ออเดอร์ก็สามารถเผยความจริงจากภายในออกมาได้...",
  str_item_intro_3642602 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nวาดขึ้นโดยสมาชิกที่ไม่ทราบชื่อของทรู ออเดอร์ ผู้ที่กล่าวว่าเคยเห็นสัจธรรมของโลกมาก่อน แต่แล้วก็ทิ้งสิ่งนี้ไว้และหายตัวไป คนส่วนใหญ่ยังสงสัยในคำกล่าวอ้างของเขา แต่ก็ปฏิเสธไม่ได้ว่ามีบางอย่างที่ดูคลุมเครืออยู่เกี่ยวกับภาพวาดอันแสนประหลาดนี้...",
  str_item_intro_3661158 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nแยกจากกันไม่ได้ สมบูรณ์แบบ วนเวียน จริงแท้ มีเอกลักษณ์... สมาชิกในทรู ออเดอร์เข้าใจลวดลายนี้แตกต่างกันไป แต่ต่างก็เชื่อว่าการปูพรมลายดาวกระจายนี้ไว้ใต้เท้าของตัวเองจะช่วยให้พวกเขามองเห็นสัจธรรมอันเป็นที่สุดได้...",
  str_item_intro_3662115 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nเนินทราย! รถแข่ง! แรลลี่เพลิงลุกโชนขอเชิญชวนนักแข่งที่กล้าหาญที่สุด ทรหดที่สุด และกว้างขวางที่สุดมาร่วมงานเลี้ยงฉลองความเร็วกัน! แรงสุดใจ! ไปให้ไกลสุดขอบโลก!",
  str_item_intro_3661169 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเครื่องจักรเครื่องเล็กที่ทำงานด้วยพลังลึกลับที่จะหมุนไม่หยุดเมื่อออกแรงผลักเพียงเล็กน้อย ลือกันว่าถ้าไม่หยุดมัน มันจะหมุนอยู่อย่างนั้นจนกว่าโลกจะแตกดับ",
  str_item_intro_3661170 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nประตูที่เคยตั้งอยู่ในสวนลอยฟ้า เป็นของที่มีคลาสและเหมาะสำหรับตกแต่งในที่ต่าง ๆ",
  str_item_intro_3661162 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nใครที่สามารถแกะก้างปลาออกมาโดยไม่เสียหายและนำมาจัดวางได้อย่างเรียบร้อยแบบนี้ต้องมีความรู้เรื่องปลาอย่างลึกซึ้งแน่นอน เครื่องประดับก้างปลานี้ไม่ใช่ชิ้นงานสำหรับตกแต่งเท่านั้น แต่เป็นเครื่องแสดงฝีมืองานประดิษฐ์ของผู้สร้างสรรค์อีกด้วย",
  str_item_intro_3662117 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเพียงแค่เห็นภาพพิมพ์นี้ก็จินตนาการได้ถึงทักษะของนักตกปลา ปลาตัวใหญ่ยักษ์แบบนี้ต้องตีคลื่นน้ำอย่างหนักหน่วงตอนที่มันดิ้นอย่างแน่นอน นักตกปลาคงต้องปล้ำกับมันอยู่พักใหญ่จึงจะปราบมันได้ และตัดสินใจเก็บภาพหินขูดนี้ไว้เป็นที่ระลึก",
  str_item_intro_3661163 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเก้าอี้ที่ทำจากตอไม้กลม ๆ พื้นผิวหยาบและมองเห็นวงปี แต่ก็ทำให้ห้องมีความรู้สึกเป็นธรรมชาติขึ้นมานะ",
  str_item_intro_3661164 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nพรมผืนนี้ลือกันว่าพวกเคเลสไทต์เคยใช้งานมาก่อน มีการวาดลวดลายที่ประกอบด้วยลายเส้นและรูปทรงต่าง ๆ บ้างก็ว่าลวดลายนี้ดูเหมือนส่วนหนึ่งของหอคอยถ้าจ้องมองนาน ๆ บ้างก็ว่าเหมือนท้องฟ้า ช่างลึกลับดีแท้",
  str_item_intro_3661165 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโมเดลยานพาหนะจากโลกอื่น\nดูเหมือนจะเป็นสิ่งของที่คุ้นเคยสำหรับแฟนท่อมธีฟส์ จอมโจรแห่งจิตใจ\nโมน่ามองดูโมเดลนี้ด้วยรอยยิ้มพออกพอใจ หรือว่าคิดไปเองกันแน่นะ?",
  str_item_intro_3661166 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nตุ๊กตาปีศาจของเล่นจากโลกอื่น\nรูปร่างคล้ายกับมนุษย์หิมะ ทำให้หลายคนชื่นชอบ\nคุณได้ยินไหม? เหมือนได้ยินเสียงคนร้องโห่ฮิ้วเลย",
  str_item_intro_3661167 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nอุปกรณ์ลึกลับที่พบในซากปรักหักพังโบราณ ว่ากันว่าสามารถทอดอาหารได้และมีความสามารถในการปรุงรสด้วย! เป็นของหายากและล้ำค่าที่หลายคนเข้าร่วมการแข่งขัน Food Cart King เพื่อโอกาสในการได้รับมัน...",
  str_item_intro_3661168 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nใส่น้ำมัน เมล็ดธัญพืช และเครื่องปรุงต่าง ๆ ซึ่งมักจะเป็นน้ำตาล เมื่อเปิดเครื่อง เมล็ดธัญพืชจะเริ่มพองตัวกลายเป็นอาหารว่างที่ยอดเยี่ยม แต่น่าเสียดายที่มันเป็นแค่ของตั้งโชว์ ใช้งานจริงไม่ได้...",
  str_item_intro_3661160 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nสวนสนุกทุกแห่งต้องมี! เด็ก ๆ ชอบกันมากเลย! แน่นอนว่าชุดนี้เล็กไปหน่อย... ใช้เป็นของตกแต่งได้อย่างเดียว",
  str_item_intro_3661161 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nมันคือไม้กระดก! ไม้กระดก! แต่ดูเหมือนจะสร้างมาเพื่อสัตว์ขนาดเล็กเท่านั้น หิ่งห้อยบนยานโคลอสซัสชอบกันมากทีเดียว คุณมักจะได้เห็นพวกมันเด้งขึ้นเด้งลงฝึกความพร้อมเพรียงกันอยู่บ่อยครั้ง",
  str_item_intro_3661001 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเมื่อเป่าลมให้พองสุด ห่วงยางว่ายน้ำนี้จะดูเหมือน... อิคลิพไซท์ที่ทรงพลังเนี่ยนะ?! เอ่อ... ยังไงมันก็แค่ห่วงยางแหละนะ แถมยังสีชมพูด้วย แลดูไม่น่ากลัวเท่าไรหรอก... ออกจะน่ารักด้วยซ้ำไป",
  str_item_intro_3661002 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเดิมทีผลิตและจำหน่ายในสหพันธรัฐอิลลูมินา และมีเมืองเล็ก ๆ นำมาทำสีใหม่เพื่อเพิ่มอารมณ์ความเป็นฤดูร้อน หลังจากทำสีใหม่แล้ว ว่ากันว่ามันให้ลมที่เย็นสบายยิ่งกว่าเดิมเสียอีก!",
  str_item_intro_3661003 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nป้ายสถานีจากท่าจอดยานลูโมโพลิสนี้ดูแข็งแกร่งและทนทานอย่างน่าพิศวง ไม่มีสนิมเกาะแม้จะตากแดดตากฝนมานานหลายปี สีสันที่เรียบง่ายและการออกแบบที่เก๋ไก๋ทำให้มันเป็นของที่ระลึกยอดเยี่ยมสำหรับการเดินทางที่ยาวไกลสู่ลูโมโพลิส",
  str_item_intro_3661004 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nแม้ว่ามงกุฎนี้จะไม่ให้อำนาจอะไรจริง ๆ กับคุณ แต่มันก็เป็นสัญลักษณ์ของผู้ที่มีเสน่ห์อย่างแท้จริง ครั้งหนึ่งมงกุฎนี้เคยเป็นเครื่องหมายของผู้ที่ชนะการประกวดมิสอัมบราตัน อัญมณีสุดตระการตาล้วนเหมาะสมกับความสวยงามชั้นเลิศ ซึ่งทำให้ผู้คนต่างพากันประทับใจ",
  str_item_intro_3661005 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nหมวกใบนี้เป็นที่นิยมอย่างมากในดินแดนทะเลทราย ขอบที่กว้างเป็นพิเศษช่วยป้องกันลมและทราย ผู้ที่อาศัยอยู่ในทะเลทรายหรือพื้นที่โดยรอบมักสวมเสื้อคลุมและหมวก พร้อมทั้งสวมหน้ากากเป็นชุดแบบนี้ในบางเทศกาล โดยจะร้องรำทำเพลงให้คนภายนอกได้ชมเป็นการเผยแพร่วัฒนธรรมของถิ่นที่อยู่ของตนเอง",
  str_item_intro_3661006 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\n\"บีนแบ็ก\" นี้เดิมทีเป็นอาหารชั้นเลิศในแถบทะเลทราย ทำจากถั่วที่พบได้ทั่วไปในพื้นที่แห่งนี้ สุดท้ายแล้วแนวคิดนี้ก็มีการนำไปใช้กับวงการการทำเฟอร์นิเจอร์ คนในพื้นที่บอกว่าถ้าทำให้บีนแบ็กมีหน้าตาน่ารักน่าเอ็นดู จะยิ่งทำให้ผู้คนอยากล้มตัวลงนอนมากยิ่งขึ้น",
  str_item_intro_3661007 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nย้อนรอยการต่อสู้ในอารีน่าใต้ดินบนยานโคลอสซัสของคุณ! ภาพของผู้ท้าชิงที่ฉายแสดงทุกรายละเอียดของการต่อสู้ และสร้างความตื่นเต้นของการแข่งขันขึ้นมาใหม่อีกครั้ง",
  str_item_intro_3661008 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nต้นบอนไซเมเปิลขนาดใหญ่ที่ตกแต่งห้องทั้งห้องได้จบในต้นเดียว แน่นอนว่าถ้ามีของตกแต่งเพิ่มเติมสักสองสามชิ้นมาเสริมอีกก็ยิ่งดีใหญ่",
  str_item_intro_3661009 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nกระถางต้นเมเปิลขนาดเล็ก เมื่อรวมกับไม้กระถางหลากหลายก็จะจัดแต่งได้สวยงามอย่างยิ่ง",
  str_item_intro_3661010 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nชาวบ้านบางกลุ่มเชื่อว่าหน้ากากนี้มีพลังขับไล่ความชั่วร้ายและนำโชคดีมาให้ จึงมักนำไปวางไว้ในบ้านเรือนในตำแหน่งที่เห็นได้เด่นชัด โดยหวังว่าทั้งครอบครัวจะได้รับพร",
  str_item_intro_3661011 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nของชิ้นนี้มีต้นกำเนิดมาจากทางตะวันออกไกล เฟอร์นิเจอร์ประเภทนี้ค่อย ๆ ได้รับความนิยมมากขึ้นในทวีปนี้เมื่อไม่กี่ปีที่ผ่านมา ในฤดูหนาวมันจะให้ความอบอุ่นและทำให้จิตใจสงบนิ่ง และทันทีที่คุณนั่งลง คุณจะอยู่ตรงนั้นได้นานทั้งวันโดยไม่ต้องขยับตัวไปไหน บางคนก็เริ่มเรียกปรากฏการณ์นี้ว่ามนตร์สะกดแห่งโต๊ะอันอบอุ่น",
  str_item_intro_3661012 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nต้นสนเป็นต้นไม้ที่พบได้มากที่สุดในนอร์ธแลนด์ และเป็นวัตถุดิบสำคัญที่ใช้ในการสร้างบ้านเรือนและเฟอร์นิเจอร์ ด้วยเหตุนี้ ต้นสนจึงเป็นตัวแทนของแนวคิดของครอบครัวในนอร์ธแลนด์ และชาวนอร์ธแลนด์ก็วางต้นสนไว้ที่บ้านในช่วงวันหยุดปีใหม่ พวกเขาแขวนของประดับตกแต่งต่าง ๆ จากกิ่งของต้นสนและวางของขวัญไว้ข้างใต้และเปิดต่อหน้าครอบครัวเพื่อเฉลิมฉลองเทศกาลที่สำคัญที่สุดของพวกเขา",
  str_item_intro_3661013 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nชาวตะวันออกไกลชอบใช้สำหรับฉลองวันหยุด แรกเริ่มเดิมทีก็เป็นอาหาร แต่พอคนนอร์ธแลนด์เชื่อกันว่าเป็นของศักดิ์สิทธิ์ ก็เลยใช้ดินเหนียวกับผ้ามาทำแทน แต่ดูไปแล้ว... ก็เหมือนทวีตตี้อยู่นะ",
  str_item_intro_3661014 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\n\"ทำเค้กรูปหัวใจให้คนพิเศษของคุณเมื่อถึงเวลา\" กระแสที่ฮิตขึ้นมาในชั่วข้ามคืน ค่อนข้างนิยมกันในหมู่เด็กสาว เพราะถึงอย่างไรนอกจากจะสวยงามถูกใจแล้วยังอร่อยอีกด้วย และที่สำคัญ มันดีต่อใจสุด ๆ!",
  str_item_intro_3661015 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nดูเหมือนว่าจะเป็นเครื่องประดับที่ใช้แขวนจากตะวันออกไกล เบาและสะดวก จะแขวนไว้ใต้ชายคา ที่ประตูหรือหน้าต่างก็ได้ เมื่อลมพัดจะส่งเสียงกรุ๊งกริ๊งใสแจ๋วที่ฟังแล้วสดชื่นและผ่อนคลาย",
  str_item_intro_3661016 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nน้องหมีน่าเอ็นดูเหมาะที่จะให้เป็นของขวัญ แถมรสชาติก็อร่อยกว่าที่คิดอีกด้วย แต่ว่า... จะกินลงจริง ๆ หรือ?",
  str_item_intro_3661017 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nว่ากันว่าเป็นของเล่นที่มีพื้นฐานมาจาก \"ตัวตลก\" ของกษัตริย์ในสมัยโบราณ มันดูโง่เง่าและน่ารัก เป็นของขวัญที่มอบความสุขที่แตกต่างไปอีกแบบ",
  str_item_intro_3661018 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nหมวกนี้เป็นที่ชื่นชอบในหมู่สมาชิกเรดีเซล เวรนช์ และให้การปกป้องเมื่อเกิดอุบัติเหตุทุกประเภท รวมทั้งป้องกันนักแข่งจากลมและฝุ่นอีกด้วย สีสันสุดแจ่มแจ๋วนี้ทำให้มั่นใจได้ว่าจะไม่มีใครมองข้ามผู้ที่สวมใส่อย่างแน่นอน",
  str_item_intro_3661019 = "เฟอร์นิเจอร์สำหรับวางในห้องต่าง ๆ บนยานโคลอสซัส\nโซรอซลำนี้ทำจากกระดาษพิเศษหลาย ๆ แผ่น และดูเหมือนเป็นผลงานชิ้นเอกของเด็กที่ไหนสักคน มันดูเหมือนอากาศยานของจริงในหลายแง่มุม แต่รายละเอียดบางส่วนก็เผยให้เห็นถึงความสุขและอารมณ์ขันของเด็กเล็ก ๆ เช่นกัน",
  str_item_intro_3661020 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเค้กหอคอยขนาดยักษ์ที่สั่งทำพิเศษเพื่อฉลองการอยู่ด้วยกันมาครบหนึ่งปี น่าอัศจรรย์อย่างยิ่งเมื่อนำมาวางตรงหน้า เพราะว่ามันช่าง... สูงเหลือเกิน! นอกจากรูปลักษณ์ที่น่าทึ่งแล้ว แต่ละชั้นของมันยังหมุนไปเล็กน้อย เผยให้เห็นชั้นสีอันสดใสอีกด้วย",
  str_item_intro_3661021 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nอ๊ะ... ผ่านไปหนึ่งปีแล้ว สามารถดูความทรงจำในอดีตได้ที่นี่",
  str_item_intro_3662118 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโปสเตอร์จดหมายเตือนที่แฟนท่อมธีฟส์ จอมโจรแห่งจิตใจส่งให้กับเป้าหมายในโลกอื่น ลวดลายดีไซน์สวยงามเป็นศิลปะ\nเมื่อมองดูโปสเตอร์แผ่นนี้แล้ว ท่าทางฟ็อกซ์จะพึงพอใจกับตัวเองอย่างมาก หรือว่าคิดไปเองกันแน่นะ?",
  str_item_intro_3661022 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรู้สึกว่าโทนสีคุ้น ๆ มั้ย? ถูกตัอง! กระดานโต้คลื่นนี้ออกแบบตามสไตล์ของบร็อค และยังมีความถึกทน ไว้ใจได้ และควบคุมง่ายเหมือนกับเขาอีกด้วย!",
  str_item_intro_3661176 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nมีคนเอาต้นไม้ทั้งต้นมาปลูกในกระถางจริง ๆ! เอาไว้ดูเฉย ๆ เลยด้วย! คงต้องชอบต้นปาล์มมากสินะ ถึงคิดได้ว่าต้องทำแบบนี้",
  str_item_intro_3661171 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรูปปั้นปลาดาวเหมือนจริง ซึ่งมองแวบแรกอาจจะคิดว่านี่คือของจริง แม้จะทำจากทรายนุ่ม ๆ แต่ก็รักษารูปทรงได้ดี และแข็งแกร่งอย่างไม่น่าเชื่อ",
  str_item_intro_3661172 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nใช่แล้ว มันเป็นของแข็ง แต่ก็ยังทำด้วยทรายอยู่ดี ดังนั้นก็อย่าจริงจังกับชื่อของมันมากนัก! เขาตั้งไว้เพราะหวังให้มันอยู่ได้นาน ๆ หน่อย และเท่าที่ผ่านมา ปราสาทนี้ก็ยังเป็นรูปเป็นร่างดีอยู่",
  str_item_intro_3661173 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nตรวจสอบออก! เต็มอิ่มกับการแสดงสุดตระการตามากมายที่ผู้ชมจะไม่มีวันลืม! นั่นเป็นเหตุผลที่แม้แต่โปสเตอร์ก็ดูเย้ายวน",
  str_item_intro_3661174 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nลูกบอลที่ตกแต่งหลากสีสัน แค่เอาไปเดาะเล่นบนเวทีก็เพียงพอแล้วที่จะดึงดูดความสนใจจากผู้ชมได้ อย่าว่าแต่เอามาใช้ในการแสดงเลย นี่คืออุปกรณ์หลักอย่างหนึ่งที่จำเป็นสำหรับการแสดงที่ล้ำเลิศ",
  str_item_intro_3661175 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nลูกโป่งมากมาย! พวกมันมีสีสันและทำให้คุณรู้สึกลอยตัวเล็กน้อยเมื่อจับมัน! เพียงจำไว้ว่าอย่าให้เด็กที่ยังเด็กเกินไปเล่นกับพวกเขา มิฉะนั้น ลูกโป่งอาจลากพวกเขาขึ้นไปบนฟ้า!",
  str_item_intro_3661177 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nนี่คือต้นไม้ชนิดใด? กิ่งก้านของมันเป็นตะปุ่มตะป่ำและบิดเบี้ยว... ดูเหมือนต้นไม้ที่คุณเห็นในภาพยนตร์สยองขวัญ มันคงน่ากลัวกว่านี้ถ้ามีโคมน่ากลัวสองสามตัวห้อยลงมาจากมัน...",
  str_item_intro_3661178 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nควรจะเป็น...ยิ้ม? คนทำเท่านั้นที่จะรู้ แต่มีบางอย่างแปลก ๆ เกี่ยวกับรอยยิ้มของมัน อีกครั้ง นั่นคือรอยยิ้มจริงๆเหรอ...?",
  str_item_intro_3661179 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nGlub, glub, glub... ใครจะรู้ว่าการปรุงบ้า ๆ แบบใดที่กำลังเดือดอยู่ในหม้อนี้? อาจเป็นยาแห่งความรักเหมือนในเทพนิยายหรือไม่? หรืออาจจะมีอะไรน่ากลัวกว่านั้นมาก...",
  str_item_intro_3661180 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบนยักษ์ใหญ่ของคุณ\nหุ่นกระบอกแปลก ๆ ที่สร้างโดยพ่อค้าที่แปลกกว่าในอัมบราตัน บนพื้นผิว มันดูเหมือนโซรอซ แต่ถ้าคุณบีบมันเพียงเล็กน้อย... มันส่งเสียงกรี๊ดดังและน่าขนลุก ฉันสงสัยว่ามันควรจะเป็นเรื่องตลกแบบไหน?",
  str_item_intro_3661023 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nอุปกรณ์สร้างกระแสน้ำไหลโดยใช้กลไกที่ติดตั้งอยู่ภายในเมื่อนำน้ำไปเติม ช่วยลดความร้อนและเหมาะกับช่วงฤดูร้อนเป็นอย่างยิ่ง ว่าแต่ใช้แล้วอย่าลืมเช็ดพื้นให้แห้งด้วยนะ",
  str_item_intro_3661024 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบนยักษ์ใหญ่ของคุณ\nunicycle นี้สามารถก้าวไปข้างหน้าได้จริงด้วยล้อเดียว! มันช้าไปหน่อย... เมื่อได้ดูทักษะการขี่กายกรรมของนักขี่ ก็อดไม่ได้ที่จะรู้สึกทึ่งและวิตกกังวลไปพร้อม ๆ กัน",
  str_item_intro_3661025 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nดูเหมือนว่าจะเป็นอุปกรณ์โบราณที่พบในซากปรักหักพังลึกลับหลายแห่งของแอสตร้า แม้จะค่อนข้างเก่า แต่ก็ยังใช้งานได้ดีอย่างน่าประหลาดใจ และสามารถบันทึกภาพวิดีโอได้อย่างเที่ยงตรง",
