  str_item_intro_3711005 = "หนังสือเล่มนี้เป็นแค่หนึ่งเล่มในชุดเท่านั้น วางไว้บนชั้นวางหนังสือในคาเฟ่ จะได้หยิบอ่านได้ทุกเมื่อที่ต้องการ!",
  str_item_intro_3751002 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nฉันคิดอะไรดี ๆ ออกแล้ว! โอ๊ะ คุณก็เหมือนกันเหรอ จุ๊ ๆ เก็บไว้เป็นความลับระหว่างเราสองคนนะ",
  str_item_intro_3751003 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nดูคนนั้นสิ เท่อ๊าาา! ว้าว คนนั้น! ไม่นะ ไม่นะ ไม่นะ!",
  str_item_intro_3751004 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nผิดแผนอีกแล้ว! คราวนี้จะทำยังไง ไม่อยากสบถเลยนะ แต่...",
  str_item_intro_3751005 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nอ๊ะ... แย่จริง เป็นแบบนี้ไปได้ยังไง? ดูเหมือนยังมีบางอย่างที่ต้องปรับปรุง ต้องพยายามให้มากขึ้นอีก!",
  str_item_intro_3751006 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nไม่นะ เราทำภารกิจพังซะแล้ว หัวหน้าจะด่าเราไหมนะ ไม่สิ อย่าเพิ่งคิดลบดีกว่า",
  str_item_intro_3751009 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nโปรดอย่าได้สงสัยในตัวเอง ทุกคนล้วนมีภาระหน้าที่ที่ต้องทำ ฉันมั่นใจ!",
  str_item_intro_3751011 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nทำเควสต์ทั้งหมดที่มอบหมายให้เสร็จแล้วรึยัง? เอ้า เอาดอกไม้แดงดอกน้อยนี่ไปสิ",
  str_item_intro_3751015 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nช่างเป็นเสียงที่ไพเราะเสนาะหูเสียจริง อยากฟังด้วยกันไหม",
  str_item_intro_3751017 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nฉันนั่งเฉย ๆ เป็นภาระใครไม่ได้หรอกนะ ประดิษฐ์อะไรใหม่ ๆ ดีไหม อาจจะเป็น...",
  str_item_intro_3751019 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nขนาดมีความรู้ตั้งมากมาย ก็ไม่สามารถอธิบายสิ่งที่เกิดขึ้นได้ อึ้งจนทำอะไรไม่ถูกเลย...",
  str_item_intro_3751023 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nจะรีบไปไหน มีอาหารฟรีเหรอ งั้นรีบไปเดี๋ยวไม่ทัน",
  str_item_intro_3751025 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nคนน่าสงสาร ทำไมถึงอยากฆ่าเวลานัก ไม่มีอย่างอื่นให้ทำแล้วเหรอ",
  str_item_intro_3751030 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nโคลอสซัสที่รัก เหตุใดต้องฝืนตัวเองเพื่อโบยบินบนท้องฟ้าด้วยเล่า",
  str_item_intro_3751032 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nทำไมไม่รู้ตัว ทำไมไม่ส่องกระจกเสียบ้าง พวกคนไร้ประโยชน์มักจะไม่แยแสต่อสิ่งใดจริง ๆ...",
  str_item_intro_3751033 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nใกล้เคียงกัน ใบมีดของฉันไม่ให้ค่าเผื่อผู้ฝ่าฝืน",
  str_item_intro_3751034 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nเมื่อคุณจ้องไปที่เงา เงากำลังมองคุณอยู่",
  str_item_intro_3751035 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nความจริงมักซ่อนอยู่ในก้อนเมฆ กึ่งปิดบังและเปิดเผยครึ่งหนึ่ง คุณและฉันต่างต้องเปิดตาของเรา",
  str_item_intro_3751036 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nคำสั่ง? กฎ? ฮาฮา! นั่นอะไร?",
  str_item_intro_3751037 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nอนาคตยังมืดมน แต่ฉันเห็นแสงแห่งความหวัง",
  str_item_intro_3751038 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nทำได้ดี! เข้าร่วมกับฉันในการต่อสู้กับ Eclipsites! อิลลูมิน่า สุดอลังการ!",
  str_item_intro_3751301 = "รับเพื่อใช้รูปประจำตัวนี้\n\"ไม่เลวนะ! นี่ ๆ อยากเข้าร่วมกับเรดีเซล เวรนช์ไหมล่ะ\"",
  str_item_intro_3751302 = "รับเพื่อใช้รูปประจำตัวนี้\n\"ขอบคุณนะทุกคน ความแข็งแกร่งของฉันกลับมาแล้ว... พวกคุณอยากให้ฉันจัดการอิคลิพไซท์หน่อยไหมล่ะ\"",
  str_item_intro_3751303 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nมากับฉันที่ภูเขาเมฆา แล้วสนุกร่าเริงท่ามกลางดอกซากุระที่เต้นระบำด้วยกันนะ",
  str_item_intro_3751304 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nน้ำแข็งไสที่เจ้าของซุ้มทำอย่างพิถีพิถัน เย็นจี๊ดขึ้นสมอง รับประกันอภิมหาความสดชื่นท่ามกลางฤดูร้อนอันแดดจ้า",
  str_item_intro_3751305 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nสวมซะแล้วมาเป็นเรดีเซล สตีล เอ็มเควี ซีโร่เลย!",
  str_item_intro_3751306 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nหา...? ทุกคนออกไปสนุกกันหมดแล้วเหรอ? งั้นฉันไปบ้างดีกว่า...",
  str_item_intro_3751307 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nอยากดับร้อนเหรอ? ฉันช่วยเอง! บุปผาน้ำแข็ง!",
  str_item_intro_3751308 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\n100 วันแล้วเหรอ? แบบนี้ต้องมีเค้ก!",
  str_item_intro_3751309 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nอืมม... ฉันชักจะชอบทะเลทรายขึ้นมาแล้วสิ",
  str_item_intro_3751310 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nทำไมถึงหนักหัวแบบนี้นะ? โอ้ พวกมันนั่นเอง... ได้ งั้นก็ช่างมันเถอะ",
  str_item_intro_3751311 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nเราชนะแล้วเหรอ? เอาดอกไม้ไฟมาเลย! ได้เวลาฉลองแล้ว!",
  str_item_intro_3751312 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nหวังว่าเราจะเห็นพ้องต้องกันได้ในเรื่องนี้นะ",
  str_item_intro_3751313 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nอยากเห็นหน้าภายใต้หน้ากากเหรอ? ได้สิ... แค่มาเข้าร่วมหน่วยทหารรับจ้างของฉันเท่านั้นเอง",
  str_item_intro_3751314 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nขอเทิดทูนรัตติกาลสีขาว... สักวันหนึ่ง ฉันจะกำจัดความอยุติธรรมในโลกนี้ให้หมดสิ้นไป",
  str_item_intro_3751315 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nมันแสดงถึงเกียรติสูงสุดของการแข่งขันต่อสู้ใต้ดินที่อัมบราตัน! หลักฐานที่ปฏิเสธไม่ได้ว่าคุณคือเจ้าแห่งการต่อสู้!",
  str_item_intro_3751316 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nผู้นำ-ผู้นำ-ผู้นำทาง! ฉันจะแฉดงเวทมนตร์ให้ดูนะ!",
  str_item_intro_3751317 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nยิ้มเจ้าเล่ห์จริงนะ... ไปสร้างความโกลาหลกันเถอะ!",
  str_item_intro_3751318 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nฉันไปพบกับลูกแมวน่ารักเข้าระหว่างลาดตระเวน วันนี้เป็นวันที่ดีจริง ๆ!",
  str_item_intro_3751319 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nนี่คือสัญลักษณ์ของอำนาจในลูโมโพลิสที่มักสงวนไว้ให้ขุนนางชั้นสูง",
  str_item_intro_3751320 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nชาวนอร์ธแลนด์จะแต่งตัวอย่างนี้กันในวันปีใหม่ ไม่เว้นแม้แต่ฉัน",
  str_item_intro_3751321 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nในโอกาสปีใหม่นี้ ขอความสงบและความสุขจงบังเกิดกับคุณ",
  str_item_intro_3751322 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nทีนี้รู้แล้วใช่มั้ยคะว่าโทรุน่ะเป็นเมดที่เจ๋งที่สุดในโลก!",
  str_item_intro_3751323 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nเด็กดีจะสุภาพอ่อนโยนแม้แต่ตอนนอนหลับ เธอนอนไม่ดิ้นเลย คุณจะวางส้มบนหัวเธอตอนที่หลับอยู่ก็ยังได้",
  str_item_intro_3751324 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันจะบรรจงวาดทีละเส้นจนเสร็จ...\"",
  str_item_intro_3751325 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ดูนี่สิ... ฉันว่ามันเก่าแก่เป็นพันปีเลยนะ!\"",
  str_item_intro_3751326 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"อยากฉลองเหรอ? แต่ละเทศกาลมีเอกลักษณ์เฉพาะตัวนะ\"",
  str_item_intro_3751327 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"นี่! ไปขี่รถเล่นกันมั้ย?!\"",
  str_item_intro_3751328 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ความจำดีขนาดไหน ก็ไม่เท่าจดไว้ในสมุด\"",
  str_item_intro_3751329 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n*โฮก* หวังว่านายจะไม่ตกใจนะ!",
  str_item_intro_3751330 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ความรักแสนล้ำค่า\nอิสระล้ำค่ายิ่ง\nสองอย่างพร้อมละทิ้ง\nเพื่อรักษาสัตย์ปฏิญาณ\"",
  str_item_intro_3751331 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"กรุ๊งกริ๊ง! อยากได้กระพรวนหรอ เมี้ยว?\"",
  str_item_intro_3751332 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"โปรดฟังเสียงของกระดิ่งรำบวงสรวงเถิด\"",
  str_item_intro_3751333 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันจะไม่แบ่งซาลาเปาให้ใครทั้งนั้น!\"",
  str_item_intro_3751334 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ตื่นแล้วเหรอ? งั้นรีบไปทำงานเถอะ!\"",
  str_item_intro_3751335 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nชนะแล้ว! เรามาฉลองด้วยการทำอะไรสนุก ๆ กันดีไหม?",
  str_item_intro_3751336 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nมันดูเหมือนฉันเปล่า?",
  str_item_intro_3751338 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nอ่ะฮ้า หัวเจ้าเหมียวกำลังจ้องคุณอยู่",
  str_item_intro_3751339 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"พวกมัน... ต่างกันยังไงเหรอ?\"",
  str_item_intro_3751340 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"นายดูแลฉันอย่างดีมาโดยตลอด เพราะงั้นก็รับไว้เถอะนะ\"",
  str_item_intro_3751341 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ได้ยินว่าวันนี้เป็นวันแสดงความในใจ... ใช่มั้ย?\"",
  str_item_intro_3751342 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันได้ยินว่าชุดนอนตัวนี้กำลังได้รับความนิยมในหมู่ผู้นำทาง แล้วฉันก็ต่อคิวอยู่นานมากกว่าจะซื้อมันมาได้!\"",
  str_item_intro_3751343 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nสีของดวงตา... เปลี่ยนไปแล้ว",
  str_item_intro_3751344 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"หืมม... นี่ฉันลืมทำอะไรรึเปล่านะ?\"",
  str_item_intro_3751345 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nการจดเรื่องที่มีความสำคัญมาก ๆ เอาไว้เป็นนิสัยที่ดีของเสนาธิการ",
  str_item_intro_3751346 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ชุดนี้น่ะเหรอ? ฉันเลือกซื้อมาตอนที่ไปเดินช้อปปิ้งที่อัมบราตัน มันดูไม่ซ้ำใครดีใช่มั้ยล่ะ?\"",
  str_item_intro_3751347 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nดูเหมือนพ่อค้าชับบ์จะได้รับของขวัญชิ้นใหญ่ เขากำลังร้องเพลงอย่างมีความสุข",
  str_item_intro_3751348 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"อิลลูมินาต้องการเธอ! พวกเรารอเธออยู่นะ!\"",
  str_item_intro_3751349 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"หืมม? อยากฟังฉันร้องเพลงเหรอ? ได้สิ เพื่อเป็นการแลกเปลี่ยน นายต้องเล่นเกมกับฉันนะ!\"",
  str_item_intro_3751350 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ทำไมฉันใส่ชุดเป็นยูมิน่ะเหรอ? ก็เพราะเธอน่ารักสุด ๆ ยังไงล่ะ\"",
  str_item_intro_3751351 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"หูนี่น่ะเหรอ? ฟิลิชีให้ฉันใส่ไว้ ไม่งั้นเธอจะไปรายงานคุณชาโรนาว่าฉันเหยียบหางเธอ...\"",
  str_item_intro_3751352 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"มารวมทีมกับฉัน แล้วจะไม่มีวันแพ้!\"",
  str_item_intro_3751353 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"หา? มันยากตรงไหนกันล่ะนั่น?\"",
  str_item_intro_3751354 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ต้องหาเวลาพักผ่อนบ้างนะ\"",
  str_item_intro_3751355 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันขุดมาถึงไหนแล้วเนี่ย?\"",
  str_item_intro_3751356 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"โอยยย! ร้อน ๆ!\"",
  str_item_intro_3751357 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฤดูร้อนปีนี้ร้อนมาก สวมหมวกไว้จะป้องกันแดดได้ดี ผู้นำทาง เธอเองก็ต้องป้องกันความร้อนด้วยนะ\"",
  str_item_intro_3751358 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ใครจะปฏิเสธน้ำแข็งไสเย็น ๆ อร่อย ๆ ในหน้าร้อนกันล่ะ?\"",
  str_item_intro_3751359 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nในฤดูร้อนนี้ คุณจะสัมผัสได้ถึงความเย็นฉ่ำเมื่ออยู่ข้างกายคาร์ลีน",
  str_item_intro_3751360 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ที่นี่อบอุ่นจริงๆ มาสนุกกับความสงบในคาร์นิวัลกันเถอะ\"",
  str_item_intro_3751361 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nกลางคืนคือเพื่อนของฉัน และค้างคาวคือเป้าหมายของฉัน ฉันเป็นใคร?",
  str_item_intro_3763022 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nไม่ต้องกลัว! ฉันได้โคมฟักทองนี้ทำขึ้นเพื่อเพิ่มบรรยากาศของงานในอีกไม่กี่วันข้างหน้า ไม่เลวใช่มั้ย",
  str_item_intro_3751362 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nให้ฉันดูว่าเกิดอะไรขึ้น!",
  str_item_intro_3751363 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nมันร้ายแรงมาก แต่งูยังคงได้รับอนุญาตให้อยู่บนหัวของฉัน",
  str_item_intro_3751365 = "ปลดล็อคอวาตาร์ที่เกี่ยวข้องหลังจากได้รับ \"ต้องการซื้อขนมไหม แลกเปลี่ยนเรื่องราวของคุณสำหรับพวกเขา\"",
  str_item_intro_3751366 = "ปลดล็อคอวาตาร์ที่เกี่ยวข้องหลังจากได้รับ “ไม่คิดจะให้ฉันแต่งตัวเป็นหมาป่าเหรอ?”",
  str_item_intro_3751367 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้องหลังจากได้รับ\n“ชารอนสวมฟันปลอมและเสื้อคลุมอย่างกระตือรือร้น การแสดงเริ่มขึ้นแล้ว!”",
  str_item_intro_3751368 = "ปลดล็อคอวาตาร์ที่เกี่ยวข้องหลังจากได้รับ \"สำหรับฮิอิโระ การกลายเป็นนักเวทย์ก็สามารถใช้เป็นการฝึกประเภทหนึ่งได้เช่นกัน\"",
  str_item_intro_3751369 = "ปลดล็อคอวาตาร์ที่เกี่ยวข้องหลังจากได้รับ “พาโลมาพันผ้าพันแผลเพื่อเซอร์ไพรส์เด็กๆ ทุกคนที่มาหลอกหรือรักษา”",
  str_item_intro_3751370 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"เหรียญนี้...แสดงถึงอดีตของฉัน\"",
  str_item_intro_3751371 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"แสงหลากสีเหล่านี้สวยงามมาก\"",
  str_item_intro_3751372 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"มาเป็นไอดอลกับฉันสิ!\"",
  str_item_intro_3751373 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"พร้อม...ปฏิบัติการ!\"",
  str_item_intro_3751374 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nPhilyshy บอกว่าเธอเอาปลาแห้งไปแลกกับชุดนอนปีใหม่ยอดนิยมเหล่านี้ อืม... สบายจริงๆ แต่ทำไมมีหูด้วยล่ะ?",
  str_item_intro_3751375 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง ก๋วยเตี๋ยวหอยทากแม่น้ำที่มีกลิ่นหอมเฉพาะตัวเป็นอาหารโปรดของมู่หยูไป๋",
  str_item_intro_3751376 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nคุณดูไม่ดีเกินไป คุณต้องการให้เราดูคุณหรือไม่?",
  str_item_intro_3751377 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nการสังเกตผู้คนและสิ่งของอย่างเงียบๆ เป็นนิสัยอย่างหนึ่งสำหรับ Jeriah",
  str_item_intro_3751378 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nด้วยสีหน้าที่ชอบธรรมของเธอ ไมเคิลคว้าดอกกุหลาบทุกดอกที่เธอหมายตาไว้",
  str_item_intro_3751379 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nการทักทายคนทั้งโลกด้วยเครื่องแต่งกายที่สะดุดตาบางครั้งอาจมอบประสบการณ์ที่แตกต่างไปจากเดิมอย่างสิ้นเชิง",
  str_item_intro_3751380 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อันตราย โปรดอย่าเลียนแบบ\"",
  str_item_intro_3751381 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“เจโน่ชวนคุณไปดื่มกาแฟดำกับเขา คุณตอบรับคำเชิญของเขาไหม”",
  str_item_intro_3751382 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ผู้พิพากษาแห่งลูโมโปลิสต้องมีความกล้าหาญในการตัดสินขั้นสุดท้าย\"",
  str_item_intro_3751383 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ตุ๊กตาตัวนี้ดูเหมือนฉัน ดังนั้นฉันจึงรู้สึกปลอดภัยเมื่อได้กอดเขา\"",
  str_item_intro_3751384 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ฉันชอบเพลงนี้เพราะมันทำให้ฉันสงบลง\"",
  str_item_intro_3751385 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"Yingel ผู้ซึ่งใกล้ชิดกับนกจับแมลงจริงๆ ต้องเป็นคนอ่อนโยนมาก\"",
  str_item_intro_3751386 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ใช้ดาบของคุณเพื่อขยายพรมแดนและมือของคุณเพื่อปลอบโยนหัวใจของผู้คน Leo ยึดมั่นในหลักการนี้อย่างแน่วแน่\"",
  str_item_intro_3751387 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"กลิ่นหอมของชาดำช่วยให้ Mia สงบลงและช่วยให้เธอรู้สึกผ่อนคลาย\"",
  str_item_intro_3751388 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ดอกไม้โปรดของใครคือไวโอเล็ตในมือของเขา\"",
  str_item_intro_3751389 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"คุณเห็นอะไรในลูกบอลคริสตัล อดีตหรืออนาคต\"",
  str_item_intro_3751390 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\n“เวลาคุณเศร้า กอดเบาๆ ช่วยให้ดีขึ้นได้ไหม”",
  str_item_intro_3751391 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\n\"เป็นผู้ชมของฉันหรือเป็นหุ้นส่วนของฉัน คุณเลือกอะไร\"",
  str_item_intro_3751392 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\n\"คลายร้อนในฤดูร้อนด้วยน้ำแข็งใสสักชาม!\"",
  str_item_intro_3751393 = "ปลดล็อครูปประจำตัวที่สอดคล้องกัน\nฉันมีไอเดียทำเงินที่ดีมาก อยากลองไหม?",
  str_item_intro_3751394 = "ปลดล็อครูปประจำตัวที่สอดคล้องกัน\nอยากรู้ว่าอะไรทำให้ฉันหัวเราะใช่มั้ย? ไปเถอะ ทายดูสิ!",
  str_item_intro_3751395 = "ปลดล็อครูปประจำตัวที่สอดคล้อง\nอยากทราบว่าของหวานในฤดูร้อนที่ฉันชอบมากที่สุดคืออะไรหรือไม่? นั่นคือ ไอศกรีมที่มีเนื้อกิ้งก่าย้อมแห้งโรยบนนั่นเอง",
  str_item_intro_3751501 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nดอกไม้แห่งอรุณนี้เป็นตัวแทนของความหวัง เมื่อสวมใส่จะขจัดความขมขื่นในอดีตของเจ้าให้หมดไป!",
  str_item_intro_3751502 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nนี่คือตราประจำตระกูลซากุระ เป็นสิ่งที่แสดงถึงการยอมรับที่ฮิอิโระมีต่อคุณ",
  str_item_intro_3751503 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nถ้าต้องการความช่วยเหลือจากนักรบลึกลับผู้นี้ โปรดติดต่องานจิปาถะของคุณทาคิ",
  str_item_intro_3751504 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nฮิฮิ... มาดื่มชายามบ่ายกันไหม\nหรือว่าคุณรับมือกับชาเจ็ดถังไม่ไหว",
  str_item_intro_3751505 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nจมดิ่งลงสู่ห้วงแห่งความมืดนิรันดร์กับข้าสิ",
  str_item_intro_3751506 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nสู้อิคลิพไซท์ไม่ไหวเหรอ? ไม่เป็นไร เดี๋ยวฉันจัดการให้เอง!",
  str_item_intro_3751507 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nเซอร์ไพรส์วันวินเดเลียน! จะมีของขวัญสวย ๆ อะไรบ้างนะ?",
  str_item_intro_3751508 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nมาดื่มกับฉัน แล้วมาสนุกกันในค่ำคืนแสนวิเศษ",
  str_item_intro_3751509 = "ปลดล็อกรูปประจำตัวแบบเดียวกันหลังจากได้รับ\n\"คุณ... ดูท่าทางต้องการความช่วยเหลือจากฉันนะ\"",
  str_item_intro_3751510 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nจะบอกให้นะ มื้อนี้ฉันทำให้คุณโคบายาชิโดยเฉพาะ ห้ามใครแตะต้องเด็ดขาด!",
  str_item_intro_3751511 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันเหรอ? ช่วงนี้นอนตั้งแต่หัวค่ำเลย...\"",
  str_item_intro_3751512 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"อ่าา... หิวน้ำจัง... น้ำอยู่ไหน?\"",
  str_item_intro_3751513 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"อยากรู้จริงเหรอ ว่าฉันคิดยังไงกับท่านผู้นำทาง...?\"",
  str_item_intro_3751514 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nที่ไหนมีของอร่อย ๆ ให้กินอีกน้า?",
  str_item_intro_3751515 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ไปขี่รถเล่นกัน!\"",
  str_item_intro_3751516 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"มีใครเข้าใจเลนอร์บ้าง?\"",
  str_item_intro_3751517 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"กลยุทธ์ในอนาคต...\"",
  str_item_intro_3751518 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"เวลาน้ำชายามบ่ายเป็นช่วงเวลาที่มีความสุขที่สุดของวัน\"",
  str_item_intro_3751519 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"รับทราบ\"",
  str_item_intro_3751520 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ถึงตาฉันแล้วเหรอ?\"",
  str_item_intro_3751521 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ลูโมโพลิสและทวีปแห่งนี้... เราจะต้องไม่กลายเป็นแบบนี้เด็ดขาด\"",
  str_item_intro_3751522 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nมีเรื่องไม่สบายใจเหรอ? มาเล่นน้ำให้สดชื่นกันดีกว่า!",
  str_item_intro_3751523 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"มาสิ มาประมือกันหน่อย!\"",
  str_item_intro_3751524 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“ฟู่... เสร็จแล้ว”",
  str_item_intro_3751525 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nเพื่อความอยู่รอดหรือพินาศ?\nนั่นคือคำถาม.",
  str_item_intro_3751526 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nแรงบันดาลใจมาแล้ว! เข้าใจแล้ว! งานนี้ท่าจะฮิตแน่!",
  str_item_intro_3751527 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nหมวกที่มีหัวกะโหลกอยู่บนนั้น swashbuckler โฉบลงมาด้วยหมวกกะโหลกศีรษะ มันคือ Sadie และ Coolster ที่ลงโทษคนเลวและร้องเพลงแร็พ",
  str_item_intro_3751530 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"การจัดสวนช่วยให้อารมณ์ดีขึ้นได้จริงๆ!\"",
  str_item_intro_3751531 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"เธองดงามแต่ก็... อันตรายมากเช่นกัน\"",
  str_item_intro_3751532 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“อ๊ะ! อุ่นจัง... นุ่มจัง!”",
  str_item_intro_3751533 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“ดูเหมือนว่าเธอยังหมกมุ่นอยู่กับเรื่องเก่าๆ นั้น อย่าไปรบกวนเธอเลย”",
  str_item_intro_3751534 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"สวัสดีปีใหม่! มาจุดดอกไม้ไฟกันเถอะ!\"",
  str_item_intro_3751535 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nเรือลำนี้...มีเสน่ห์จริงๆ",
  str_item_intro_3751536 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nอร่อย! มีอีกไหม?",
  str_item_intro_3751537 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nฉันจะสาย! สงสัยวันนี้ต้องเดินกินอีกแล้ว!",
  str_item_intro_3751538 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ไม่ได้นอน...ซซซ...\"",
  str_item_intro_3751539 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“เคลียร์รวดเดียวเลยได้ไหม”",
  str_item_intro_3751540 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ป๊าครับแม่...\"",
  str_item_intro_3751541 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อาชญากรที่น่ารังเกียจนั่น... ฉันจะไม่ปล่อยให้คุณหนีไป!\"",
  str_item_intro_3751542 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"เหยื่อของฉันอยู่ที่ไหน อยู่ตรงหน้าฉันแน่นอน!\"",
  str_item_intro_3751543 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"สมุดบันทึกย่อมดีกว่าความทรงจำที่ดีเสมอ...\"",
  str_item_intro_3751544 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“การฝึกร่วมทางทหารเริ่มขึ้นแล้ว!”",
  str_item_intro_3751545 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อย่ามองข้ามสิ่งใดเพราะรายละเอียดมีความสำคัญ\"",
  str_item_intro_3751547 = "ปลดล็อครูปประจำตัวที่สอดคล้องกัน\n\"ดูพวกเขาแบบนี้ทำให้ฉันมีความสุข\"",
  str_item_intro_3751548 = "ปลดล็อครูปประจำตัวที่สอดคล้องกัน\nรู้สึกอยากใช่ไหม? ก็เพียงสนุกสนานด้วยความเปิดใจและความมั่นใจเท่านั้น",
  str_item_intro_3751549 = "ปลดล็อครูปประจำตัวที่สอดคล้อง\nความอันตรายจริงๆ ทำให้ความสวยงามเพิ่มขึ้นหรือไม่?",
  str_item_intro_3751550 = "ปลดล็อครูปประจำตัวที่สอดคล้องกัน\nความคิดที่มั่นคงและการกระทำเป็นรากฐานของความสำเร็จ!",
  str_item_intro_3751601 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nโล่ยักษ์ที่แตกร้าวซึ่งเป็นอาวุธเฉพาะเหล่าอัศวินลูโมเท่านั้น รูปร่างคล้ายว่าว ด้านบนกว้างและด้านล่างแคบ มีขอบชัดเจนและพื้นผิวสลักตราสัญลักษณ์ของโบสถ์",
  str_item_intro_3751602 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\n\"ต้นไม้แห้งประดับด้วยลูกบอลสามสี สำหรับมาร์ธา อดีตได้เหี่ยวเฉาไปแล้ว และในดินแดนหิมะแห่งนี้ก็แต่งแต้มด้วยสีสัน เธอจะต้อนรับชีวิตใหม่อีกครั้ง\"",
  str_item_intro_3751603 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ตรงกลางล้อติดเฟืองไว้หนึ่งอัน โรซ่าขับรถเข้าไปในทะเลทราย แล้วพวกที่ตามเธอเข้าไปก็ไม่เห็นเธออีกเลย มีแต่ร่องรอยของล้อรถเท่านั้น\"",
  str_item_intro_3751604 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ท่ามกลางดอกลิลลี่ที่บานสะพรั่งมีดาบอันแหลมคม จากถ้อยคำที่อีวอนเขียนไว้ ชะตาของคุณนายเร้ด เมอร์คิวรีกำลังจมดิ่งอยู่กลางสายหมอก ไม่มีใครรู้ว่าเธอจะชักดาบออกมาหรือยื่นดอกลิลลี่ที่แขนเสื้อให้\"",
  str_item_intro_3751901 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nโซรอซไม่ใช่แค่ยานโคลอสซัสธรรมดา แต่เป็นเพื่อนที่อยู่เคียงข้างคุณมาถึงสิบเจ็ดปีแล้ว",
  str_item_intro_3751902 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nเมื่อสวมหมวกใบนี้คุณจะรู้สึกราวกับเป็นผู้พิทักษ์แห่งรัตติกาลสีขาว รัตติกาลสีขาวแบบไหนน่ะเหรอ เอาเป็นว่าอย่าขุดคุ้ยเลยดีกว่า",
  str_item_intro_3755004 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"มุกวิ้งว้างอย่างอ่อนโยน ความงามของแสงเช้า; ดอกไม้บานเงียบ ความอ่อนโยนอันละเอียด; โลกนี้จะรับรู้ไหม การล่าสวยงามนี้?\"",
  str_item_intro_3762001 = "ปลดล็อกกรอบรูปประจำตัวแบบเดียวกัน\nลวดลายโบราณนี้แสดงถึงการยอมรับที่กลุ่มนักล่าผู้เงียบงันมีต่อคุณ กรุณารับเกียรติอันสูงส่งจากกาลก่อนนี้ไว้ด้วย",
  str_item_intro_3762002 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nของประดับสุดหรู ประดับรูปประจำตัวกันนะ!",
  str_item_intro_3763001 = "ปลดล็อกกรอบรูปประจำตัวแบบเดียวกัน\nใต้ดวงอาทิตย์ที่แผดเผา เหนือเกลียวคลื่นสีคราม ความทรงจำที่ไม่อาจลืมเลือนของเราจะคงอยู่ที่ชายหาดร้อนระอุแห่งนี้ตลอดไป",
  str_item_intro_3763002 = "ปลดล็อกกรอบรูปประจำตัวแบบเดียวกัน\nสวมหมวกใบนี้แล้วคุณจะดูเหมือนสุดยอดทหารอิลลูมินา",
  str_item_intro_3763003 = "ปลดล็อกกรอบรูปประจำตัวแบบเดียวกัน \nใครบ้างไม่ต้องการความช่วยเหลือในเวลาที่ต้องตัดสินใจอะไรบางอย่าง",
  str_item_intro_3763004 = "ปลดล็อกกรอบรูปประจำตัวแบบเดียวกัน\nสวมไว้ แล้วคุณจะฮิปที่สุดในปาร์ตี้!",
  str_item_intro_3763005 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nธงที่มอบให้นักเรียนดีเด่น! ต้องตั้งใจเรียนนะ!",
  str_item_intro_3763006 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nน่ารักตะมุตะมิใช่มั้ยล่ะ?",
  str_item_intro_3763007 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nเราจะอยู่เป็นเพื่อนคุณนะ....",
  str_item_intro_3763008 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nรางวัลจากการจับปลา!",
  str_item_intro_3763010 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nนี่แหละกลิ่นอายของฤดูใบไม้ผลิ!",
  str_item_intro_3763011 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ฉันรู้สึกว่าพอมีมันแล้ว ตัวเองจะได้กลายเป็นนักแข่งรถที่ยิ่งใหญ่เลยล่ะ!\"",
  str_item_intro_3763012 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nใต้ผ้าม่านสีแดงฉาน คือเพลงกล่อมเด็กสุดดาร์ค...",
  str_item_intro_3763013 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nมงกุฎอันโดดเด่นคือสัญลักษณ์ของเกียรติยศและศักดิ์ศรี",
  str_item_intro_3763014 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nสำหรับท่านจอมทัพเท่านั้น!",
  str_item_intro_3763015 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"สวมใส่แล้วจะเพิ่มทักษะการบริการไหมนะ?\"",
  str_item_intro_3763016 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nสวมนี่ซะ นักมายากลผู้ยิ่งใหญ่!",
  str_item_intro_3763017 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nแดดแรงมาก ดูแลตัวเองดี ๆ นะ อย่าให้โดนแดดเผา!",
  str_item_intro_3763018 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nฉลองครบรอบ 1 ปี! ใส่เพื่อไปฉลองกันเถอะ!",
  str_item_intro_3763019 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nแค่ใส่ไว้ ก็ดูเหมือนบิก้าแล้ว!",
  str_item_intro_3763020 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nไม่ต้องกลัว ไม่ร้อนหรอก!",
  str_item_intro_3763021 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\nดูเหมือนกรงเล็บของค้างคาวกำลังจับหัวคุณอยู่หรือเปล่า? แถบคาดศีรษะแน่นเกินไป",
  str_item_intro_3763023 = "ปลดล็อกเฟรมอวาตาร์ที่เกี่ยวข้อง\nเขาว่ากันว่าการใส่หมวกใบนี้จะช่วยให้คุณแร็พได้ดีขึ้น น่าแปลกที่มันช่วยพัฒนาทักษะการเล่นเบสบอลของคุณด้วย",
  str_item_intro_3763024 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\nต้องมีสำหรับนักร้องทุกคน! ดื่มด่ำไปกับเสียงเพลง!",
  str_item_intro_3763025 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\nไม่ได้มีไว้สำหรับกินแต่มีไว้สำหรับสวมใส่!",
  str_item_intro_3763026 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\nใส่ชุดนี้จะทำให้คุณแข็งแกร่งเหมือน Jeriah ได้จริงหรือ? สิ่งหนึ่งที่แน่นอน อย่างน้อยมันก็จะทำให้คุณปลอดภัยจากลม...",
  str_item_intro_3763027 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n“ที่จริงมันเป็นแว่นเลนส์ใส”",
  str_item_intro_3763028 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อ๊ะ! เขาเป็นตัวการ!\"",
  str_item_intro_3763029 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง \"ครบรอบ 2 ปีงั้นเหรอ เอาไว้ก่อน! อย่าลืมเอาอันเก่าของปีที่แล้วลงด้วยล่ะ\"",
  str_item_intro_3763031 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง \"โลกใบนั้นมีอยู่จริงหรือไม่ ถ้าไม่มี ฉันมาอยู่ที่นี่ทำไม\"",
  str_item_intro_3763032 = "ปลดล็อคกรอบรูปประจำตัวที่สอดคล้องกัน\nดูเหมือนว่าง่ายต่อการโดนเข็มแทง; ใครจะยินดีที่จะสวมมัน...",
  str_item_intro_3763033 = "ปลดล็อคเฟรมอวตารที่สอดคล้องกัน\nนั่นคือความหมายของการเป็นสุภาพบุรุษใช่ไหม?",
  str_item_intro_3800001 = "มี 50 ลูมแอมเบอร์",
  str_item_intro_3800002 = "มี 50 ลูมแอมเบอร์",
  str_item_intro_3800003 = "มี 50 ลูมแอมเบอร์",
  str_item_intro_3800004 = "มี 50 ลูมแอมเบอร์",
  str_item_intro_3800005 = "มี 50 ลูมแอมเบอร์",
  str_item_intro_3801001 = "วัตถุดิบพัฒนาการของออโรเรียนในตำนาน\nสมาชิกทุกคนในนักล่าผู้เงียบงันมีตรานี้อยู่ ถึงแม้จะผ่านไปนับพันปีแล้ว ก็ยังมีพลังมหาศาลและสามารถกระตุ้นความสามารถของนักล่าผู้เงียบงันได้",
  str_item_intro_3900101 = "หลังจำลองวางแผนแต่ละครั้ง คลังข้อมูลการรบจะมอบคะแนนให้ตามผลงานของคุณ หลังจากสะสมคะแนนการรบได้ระดับหนึ่ง คุณจะถูกเลื่อนขั้นตามเลเวลการรบ ที่แสดงถึงความเชี่ยวชาญทางยุทธวิธีของคุณ",
  str_item_intro_3900201 = "คุณสามารถรับชิ้นส่วนข้อมูลได้จากการต่อสู้ตามคำสั่งในห้องซิมูเลชั่น ด้วยข้อมูลจำนวนมหาศาลที่เก็บไว้ในดิสก์ข้อมูล เมื่อได้ชิ้นส่วนข้อมูลมากเพียงพอแล้ว คุณจะได้รับข้อความฉบับสมบูรณ์",
  str_item_intro_3910100 = "ชัยชนะย่อมมาจาก\nการหมั่นเพียรฝึกฝน\nเอาชนะศัตรูทั้งหมด\nในการท้าทายจาก\nดิสก์ข้อมูลนี้เพื่อเคลียร์ด่าน",
  str_item_intro_3910200 = "ชัยชนะย่อมมาจาก\nการหมั่นเพียรฝึกฝน\nเอาชนะศัตรูทั้งหมด\nในการท้าทายจาก\nดิสก์ข้อมูลนี้เพื่อเคลียร์ด่าน",
  str_item_intro_3910300 = "ปกป้องสหายให้ถึงที่สุด\nแม้ต้องสละชีพตัวเองก็ตาม\nในการท้าทายครั้งนี้\nจงปกป้อง NPC ให้มี\nชีวิตรอดนาน X รอบ",
  str_item_intro_3910400 = "คุณจะรู้หรือไม่ว่าศัตรูประเภท\nไหนรออยู่ข้างหน้า?\nรับรองเลยว่าพวกมันต้อง\nแข็งแกร่งมาก ระวังด้วยนะ\nในการท้าทายครั้งนี้\nจงเอาชนะศัตรูชั้นสูงให้ได้\nเพื่อเคลียร์ด่าน",
  str_item_intro_3910500 = "จิตใจนั้นเฉียบคมยิ่งกว่าดาบทุกเล่ม\nในการท้าทายจากดิสก์ข้อมูลครั้งนี้ คุณต้องไขปริศนาให้ได้เพื่อเคลียร์ด่าน",
  str_item_intro_3910600 = "การต่อสู้ก็คือเกม เหมือนหมากรุกนี่แหละ\nในการท้าทายจากดิสก์ข้อมูลครั้งนี้ จงเอาชนะศัตรูทั้งหมดเพื่อเคลียร์ด่าน",
  str_item_intro_3910700 = "ในสนามรบที่โหดร้าย ผู้ชนะที่แท้จริงคือผู้ที่เหลือรอดเป็นคนสุดท้าย\nในการท้าทายจากดิสก์ข้อมูลครั้งนี้ เอาตัวรอดให้ได้ X รอบเพื่อเคลียร์ด่าน",
  str_item_intro_3910800 = "ศัตรูโจมตีเหมือนคลื่นที่ถาโถม\nและการป้องกันของคุณก็คือ\nเขื่อนกั้นน้ำ จงหนักแน่นเข้าไว้\nในการท้าทายจากดิสก์ข้อมูล\nครั้งนี้ จงเอาชนะศัตรูทั้งหมด\nเพื่อเคลียร์ด่าน",
  str_item_intro_3910900 = "คุณกับศัตรูใช้กลยุทธ์เดียวกัน คุณอาจเป็นพวกเดียวกันก็ได้นะ\nในการท้าทายจากดิสก์ข้อมูลครั้งนี้ เอาชนะศัตรูทั้งหมดเพื่อเคลียร์ด่าน",
  str_item_intro_3911000 = "ถ้าตัดหัวงู หางย่อมสิ้นฤทธิ์\nเอาชนะหัวหน้าศัตรูให้ได้\nแล้วชัยชนะจะเป็นของคุณ\nในการท้าทายจากดิสก์ข้อมูล\nครั้งนี้ เอาชนะหัวหน้าศัตรู\nเพื่อเคลียร์ด่าน",
  str_item_intro_4090014 = "ถูกมัดมาด้วยโชคชะตา ความทรงจำของแฝดทั้งสองเริ่มสร้างภาพรวมอย่างช้าๆ ใต้การสร้างดอกแดฟโฟดิลสีขาวที่บานอยู่ใต้หิมะสีดำที่ตกลงมาที่ทะเลสาบกระจกเงา รอคอยการพบกันอีกครั้งผ่านกระจก",
  str_item_intro_4090334 = "ชุดที่ตัดเย็บโดยโรงแรมซากุระเมฆาซึ่งมีลักษณะเฉพาะของภูเขาเมฆา ชุดยูกาตะสำหรับผู้หญิงตัวนี้ปรับแต่งให้เข้ากับรูปร่างของไวซ์โดยเฉพาะ ด้วยการผสมผสานสีแบบมินิมอล มาพร้อมผ้าคาดและจี้ที่ไม่ซ้ำใคร เติมความขี้เล่นด้วยกระดิ่งกระจุ๋มกระจิ๋มน่ารัก ทั้งหมดนี้สร้างบรรยากาศความเขินอายแบบที่ไม่ค่อยพบเห็นในตัวไวซ์ เมื่อสวมชุดยูกาตะนี้ครั้งใด เธอจะหวนนึกถึงความทรงจำอันล้ำค่าและยากจะลืมเลือน",
  str_item_intro_4090923 = "หยุดจ้องมองฉันได้แล้ว...!\nจะมีอะไรน่าอายไปกว่านี้อีกมั้ย? หนามที่โอบล้อมยกเท้าของแพกต์ขึ้น ฉีกถุงน่องใยไหมและผ้าคลุมหน้าสีดำของเธอจนขาดวิ่น ในท่ามกลางความโกลาหล แพกต์พยายามถือแก้วไวน์แดงในมือของเธอให้มั่นคง ดูเหมือนว่าชุดที่สง่างามและหรูหรานี้ไม่ได้ควบคุมง่ายอย่างที่เห็นเลย",
  str_item_intro_4090383 = "แย่แล้ว! กรอนรูติดอยู่ในกล่องของเล่นออกมาไม่ได้! เพื่อฉลองวันปีใหม่ กรอนรูมีของขวัญเซอร์ไพรส์ให้คุณ! ดูสิว่าเธอน่ารักแค่ไหนที่เข้าไปอยู่รวมกับกองของเล่น พร้อมใส่ชุดสีแดงขาวเข้ากับวันรื่นเริง แถมยังผูกโบน่ารัก ๆ ไว้ที่แขนกลอีกด้วย! พยายามอย่าไปสนใจระเบิดที่ดูน่ากลัวในมือของเธอเลย...",
  str_item_intro_4090333 = "ไวซ์ได้เลือกชุดว่ายน้ำที่เรียบง่ายและสวมสบายเพื่อเข้าร่วมเทศกาลราชันมหาสมุทร ชุดว่ายน้ำนี้ใช้รูปแบบโครงสร้างพิเศษเพื่อให้ตรงกับนิสัยการสวมใส่ของไวซ์อย่างพอดิบพอดี ทำให้เธอเอาหางไว้ตรงไหนก็ได้อย่างอิสระ นอกเหนือจากโครงสร้างพิเศษของชุดนี้แล้ว ถ้ามองให้ดีคุณจะสังเกตเห็นว่าเปลือกนอกลายพระอาทิตย์สีดำทองยังเหมาะกับอุปนิสัยที่สดใสร่าเริงของเธออีกด้วย ในขณะที่เครื่องบดน้ำแข็งทำงานไปเรื่อย แม่โฉมงามผมสั้นผู้นี้ได้ส่งคำเชิญเป็นรอยยิ้มให้คุณไปเล่นน้ำด้วยกัน วอลเลย์บอลชายหาด เครื่องดื่มเย็นเจี๊ยบ รถเข็นน้ำแข็งไส... ในช่วงฤดูร้อนนั้น คุณกับไวซ์ได้แบ่งปันความทรงจำส่วนตัวที่ลึกซึ้งด้วยกัน",
  str_item_intro_4090853 = "ชุดที่ยอดเยี่ยมประกอบด้วยเสื้อที่เย้ายวนกับกระโปรงที่โก้หรู ให้ความรู้สึกเศร้าโศก บริสุทธิ์ และมีเสน่ห์ชวนขนลุก แขนเสื้อทออย่างสวยงาม ผ้าคลุมหน้าสำหรับพิธีการ รองเท้าบูทงามสง่า... ไม่เพียงแต่ชุดของเจนที่สวยงามจนน่าทึ่ง ดอกไม้ที่ชายกระโปรงยังมีความสำคัญเป็นพิเศษอีกด้วย แต่สิ่งหนึ่งที่ยังไม่ชัดเจนนัก... ทำไมเธอจึงเลือกสวมชุดที่น่าดึงดูดใจเช่นนี้ ในเมื่อภูมิใจที่ตัวเองเป็นคนนอก",
  str_item_intro_4090863 = "ส่วนหนึ่งในกลุ่มเครื่องแต่งกายของสตรีสีขาวที่ออกแบบเพื่อการฉลองราชันมหาสมุทร สีขาวบริสุทธิ์ที่เปล่งประกายได้รับการเลือกสรรโดยเฉพาะเพื่อสะท้อนถึงความไร้เดียงสาและศรัทธาแก่กล้าที่ไม่อาจแยกจากตัวตนของยูริอาห์ได้ เถาบุปผาที่ปรากฏรอบตัวเลื้อยพันเกี่ยวไปตามใจเธอ สำหรับคนอื่นแล้ว สภาพจิตใจของเธอยังคงไม่เปลี่ยนแปลง ทว่ามีเพียงดอกไม้รอบตัวเธอเท่านั้นที่รู้ ว่าเวลาที่ยืนอวดโฉมอยู่ริมหาดนั้น เธออดไม่ได้ที่จะรู้สึกเขินอายเล็กน้อยเมื่อสวมชุดนี้ ท้องฟ้าที่สว่างจ้า ไอทะเลเค็ม ๆ น้ำทะเลที่เย็นฉ่ำ... เวลาที่เธอกวัดแกว่งดาบพิธีกรรมของเธอ ดนตรีอันไพเราะราวบทกวีที่งดงามที่สุดจะบรรเลงขึ้นอีกครั้ง",
  str_item_intro_4090573 = "ขณะที่ฟิลิชีขดตัวอยู่บนเตียงในชุดนอนที่ยับยู่ยี่ เธอหลับสนิทและมีความฝันที่สวยงามในยามบ่าย ในความฝันนี้ ยูมิมาอยู่ข้าง ๆ กอดและลูบผมเธอ เหมือนเป็นเครื่องทำความร้อนส่วนตัว ทำให้หัวใจของเธออบอุ่นและพาเธอกลับไปสู่ช่วงเวลาที่เรียบง่าย",
  str_item_intro_4091023 = "เครื่องแต่งกายที่เรียบง่ายนี้รวบรวมแก่นแท้ความหมายของการมีจิตวิญญาณที่เร่าร้อน และในความมืดมิด ขอบเขตที่จำกัดของอารีน่าใต้ดิน มันทำหน้าที่เป็นแสงนำทางเพียงหนึ่งเดียว คนทรยศขึ้นเวที ต่อสู้ด้วยร่างกายที่แข็งแรง จิตวิญญาณ และความพากเพียร เลือดของพวกเขาแผดเผาราวกับไฟ พวกมันโหมกระหน่ำเหมือนอุกกาบาตที่ลุกโชติช่วงแล้วก็หายไปเหมือนเถ้าถ่าน เธอดีดนิ้ว พร้อมที่จะล่าทุกสิ่งในสายตา",
  str_item_intro_4090453 = "เมื่อหิมะเริ่มตก ในที่สุดฤดูหนาวก็มาเยือน ขณะนี้ถนนที่ว่างเปล่าเต็มไปด้วยแสงสีเหลืองอันอบอุ่น\nเท่านั้น หากคุณเป็นนักเดินทางผู้โดดเดี่ยว ไม่ต้องกังวลว่าจะหลงทาง เพียงแค่มองไปรอบ ๆ หัวมุม รถม้าของคุณรออยู่ที่นั่นแล้ว สุภาพบุรุษที่สุขุมและเงียบเชียบในชุดทักซิโด้สีขาว รองเท้าบูทสีดำ ผมสลวยเป็นประกาย และมารยาทที่สง่างาม เขาพร้อมแล้วที่จะพาคุณไป",
  str_item_intro_4090993 = "อาเรียขดตัวอย่างเขินอายอยู่บนเก้าอี้โซฟา เผยให้เห็นเรียวขาอันเปลือยเปล่า ถอดรองเท้าออกเหลือเพียงหนึ่งข้าง ชุดที่สวยสะดุดตานั้นบ่งบอกว่าเธอเพิ่งกลับมาจากงาน\nราตรี ราวกับเจ้าหญิงในเทพนิยาย ชุดราตรีงามหรูของเธอจะหายไปเมื่อนาฬิกาหมุนมา\nบรรจบ แต่ความทรงจำนี้... ในช่วงเวลานี้ที่อยู่กับคุณ... จะไม่มีวันจางหายไป",
  str_item_intro_4090263 = "การดำรงอยู่ของสติสัมปชัญญะที่ไร้ตัวตนมีความหมายอย่างไร? หลังจากใส่เสื้อผ้าแปลก ๆ ชุดนี้แล้ว อูริเอลก็เกิดคำถามงุนงงอยู่ในใจ พาให้เธอขบคิดไตร่ตรองไม่รู้จบ เธอจะพบคำตอบในโลกแห่งวรรณกรรมจำลองได้หรือไม่? ไม่มีใครรู้ แต่คุณสามารถเดิน คิด และรู้สึกไปกับภารกิจของเธอได้",
  str_item_intro_4090543 = "เคร่งขรึมและจริงจังคือวิธีปฏิบัติงานของนาดีน เธอทำหน้าที่อย่างไม่เคยเหน็ดเหนื่อย แม้จะสวมชุดฤดูใบไม้ผลิและถือตะเกียงน้อยน่ารัก บุคลิกของเธอก็เปล่งประกายออกมา",
  str_item_intro_4091113 = "เมื่อมาถึงชายหาด แม้แต่เบริลที่มักจะโศกเศร้าก็ยังดูผ่อนคลายกว่าปกติ แม้ว่าชุดว่ายน้ำนี้จะมีสไตล์เรียบง่ายมาก แต่ก็เผยให้เห็นเรือนร่างของเบริลเป็นครั้งคราว อย่างไรก็ตาม เธอลืมเรื่องนี้ทิ้งไปและทุ่มเทกำลังเพื่อสร้างปราสาททราย นี่อาจเป็นรางวัลที่ยิ่งใหญ่ที่สุดเมื่อเบริลไปทะเล",
  str_item_intro_4090883 = "ท้องฟ้าสีคราม เมฆสีขาว ถนนที่ราบเรียบ... นี่ดูไม่เหมือนทะเลทรายเรดีเซลเลย และแม็กกี้ก็ดูแตกต่างไปเช่นกัน เธอสวมเครื่องแบบกะลาสีสะอาดสะอ้าน โบอันใหญ่ปลิวว่อนไปตามลม ในเช้าที่สดใสนี้ เธอขี่รถสบาย ๆ ไปพร้อมกับแทะขนมปัง เธอจะไปโรงเรียนสายมั้ยนะ?\n\nชุดนี้ทำให้แม็กกี้โดดเด่นท่ามกลางเรดีเซล เวรนช์และยังช่วยให้เธอมองเห็นทิวทัศน์ที่ต่างไปจากเดิมอย่างสิ้นเชิง นี่อาจเป็นส่วนหนึ่งของความมหัศจรรย์ของชุดนี้รึเปล่านะ?",
  str_item_intro_4090963 = "เอ๊ะ... อาจารย์เหรอ? ใช่ซาริเอลหรือเปล่า? ดูเหมือนว่าซาริเอลจะจริงจังกับงานที่สองของเธอแถมยังใส่เครื่องแบบซะด้วย! ซาริเอลคนใหม่นี้ดูน่าเชื่อถือกว่าคนเก่ามาก เธอพูดจานุ่มนวลและคล่องแคล่วฉะฉาน อีกไม่นานคุณอาจจะได้เรียนวิชากับเธอก็ได้!",
  str_item_intro_4091053 = "เสื้อผ้าอาจจะธรรมดา แต่ถึงยังไงอีฟก็เป็นมิสป๊อบปูลาร์ประจำเรดีเซล เวรนช์ แม้จะไม่รู้ว่าตัวเองดังแค่ไหนก็เถอะ และตอนนี้ในฐานะเชียร์ลีดเดอร์ เธอก็ได้รับความรักมากขึ้นหลังจากสวมชุดนี้! แต่อย่าจ้องก็แล้วกัน! ไม่งั้นใบหน้าของคุณอาจได้สัมผัสกับประแจ!",
  str_item_intro_4090064 = "ชุดที่มีเนื้อผ้าบางเบา เรียบลื่น และติดริบบิ้นมากมายนี้... มันคือชุดนอนเหรอ?! ทำไมถึงมีคนคิดออกแบบอะไรอย่างนี้ได้นะ? แล้วจะให้ใส่ต่อหน้าคนอื่นได้ยังไง? ด้วยความหนักใจ คาร์ลีนไม่รู้ว่าจะทำอย่างไรดี เธอจึงลองใส่ดูก่อน แต่นึกไม่ถึงเลยว่าชุดนี้จะทำให้เธอดูแตกต่างไปจากตัวตนเดิมที่แสนจะจริงจังอย่างสิ้นเชิง\nเพื่อร่วมงานปาร์ตี้ชุดนอนและสนุกสนานกับทุกคน คาร์ลีนจึงตัดสินใจเป็นไงก็เป็นกัน",
  str_item_intro_4090303 = "แขนเสื้อสีดำสนิทและเสื้อคลุมสีแดงเข้ม ขอนำเสนอ... ซามูไรผู้ขจัดเหล่าร้ายให้หมดไปจากโลก เขาคือชินโนะสุเกะ!\nในฐานะผู้นำแห่งเรดีเซล เวรนช์ ซินซาได้ปรับตัวตามสุภาษิตที่ว่า \"เข้าเมืองตาหลิ่วต้องหลิ่วตาตาม\" ไม่ว่าจะเป็นเสื้อผ้าที่เขาสวมใส่หรือดาบที่เอว สิ่งเหล่านี้ล้วนแสดงออกถึงเสน่ห์ของเกาะเมฆาอย่างสมบูรณ์แบบ และแม้แต่เสียงหัวเราะของเขาก็ดูเป็นธรรมชาติไปหมด แต่ขอเตือนไว้ก่อนนะ ถ้าซามูไรโรนินคนนี้อารมณ์ดี เขาอาจจะแต่งกลอนไฮกุแล้วร้องเป็นเพลงก็ได้...",
  str_item_intro_4090443 = "สายลมพัดผ่านทิวสนและแสงแดดอบอุ่นส่องสว่างมายังห้องโถง ไหน ๆ ก็หนีจากความวุ่นวายในเมืองและการทำงานที่ไม่รู้จบมาแล้ว ทำไมไม่ถือโอกาสพักผ่อนที่โรงแรมภูเขาเมฆาที่แสนสงบล่ะ? หลักการสมดุลระหว่างชีวิตกับงานของวิเวียนเป็นวิธีเยียวยาให้ฟื้นพลังก่อนกลับมาทำงานอย่างแท้จริง!\nแน่นอนว่าทั้งหมดนี้ต้องมีการวางแผน!",
  str_item_intro_4090643 = "ชุดต่อสู้ใหม่ของวราธทอจากเส้นไหมตะวันออก ไม่เพียงแต่กระชับสัดส่วน ยังดูสง่าและงดงามมากอีกด้วย แม้จะดูบางไปหน่อยแต่ก็เคลื่อนไหวได้อย่างคล่องตัว และดูเหมือนจะไม่เป็นอุปสรรคในการต่อสู้ของเธอเลย\nไม่ว่าจะต่อยตี เบ่งกล้าม กระโจน หรือขจัดสิ่งกีดขวาง... ภัยอันตรายจะมาในรูปแบบไหน วราธผู้แน่วแน่จัดการได้อยู่หมัด!",
  str_item_intro_4090893 = "เพื่อใช้เวลาในวันหยุดที่หายากนี้ให้คุ้มที่สุด\nอิริดอนจึงเตรียมชุดสไตล์เกาะเมฆามาใส่\nผ้าสีทองที่ประดับประดาด้วยงานปัก\nเข้าคู่กับเสื้อคลุมขนสัตว์สีขาวราวหิมะดูเรียบหรู\nเธอเฝ้ารอที่จะสวมชุดแสนสวยนี้ออกไปเดินเล่นตามถนน\nในเกาะเมฆา หรือไม่ก็นั่งรถไฟเพื่อชมทิวทัศน์\nแต่แล้วก็เกิดเหตุการณ์กะทันหันที่มาเปลี่ยนแผนของเธอ\nทั้งหมด เพื่อรักษาวันหยุดพักร้อนนี้ไว้ อิริดอนไม่ลังเลใจ\nที่จะเปลี่ยนสถานีของเกาะเมฆาให้เป็นศาลยุติธรรม",
  str_item_intro_4090653 = "\"ผู้นำทาง มาเย่นฮาเนะสึกิกันเถอะ!\"\nทวีตตี้วิ่งเข้ามาหาอย่างตื่นเต้น แต่ใครจะรู้ว่าเกมสบาย ๆ ที่สนุกสนานจะกลายเป็นการต่อสู้ที่ไม่รู้จบเพื่อชิงความเป็นหนึ่ง?! ด้วยการตีลูกเสิร์ฟที่ยอดเยี่ยมและการตีลูกหยอดที่แข็งแกร่งแบบนั้น ผู้เล่นธรรมดาไม่มีทางที่จะรอดได้เลย!!\nใครแพ้เกมนี้ต้องโดนลงโทษโดยการวาดหน้า ได้แต่หวังว่าทวีตตี้จะเมตตาและออมมือไว้หน่อย...",
  str_item_intro_4090233 = "แม้ว่าจะเป็นคนที่มีนิสัยขี้อาย แต่คอนนอลลีก็ตัดสินใจที่จะให้กำลังใจเพื่อนของเธอในการเข้าร่วมการแข่งความเร็ว แต่ถ้าจะเทียบกับเสื้อผ้าที่เธอใส่อยู่เป็นประจำทุกวันแล้ว ชุดยูนิฟอร์มตัวนี้ช่างดู \"แปลกกว่าชุดอื่น\" ไปเสียจริง\nอย่างไรก็ตาม คอนนอลลีก็ยอมรับชุดแต่งกายที่แสนห้าวหาญนี้จากการคะยั้นคะยอของคนขายแต่โดยดี ด้วยความหวังว่าจะทำให้เธอกลายเป็นคนที่เข้าสังคมได้มากขึ้น",
  str_item_intro_4090613 = "\"โอ้โห... ทวีปมันหน้าตาเป็นอย่างงี้เองเหรอ!\"\nแชนดราลอยสูงขึ้นไปในก้อนเมฆโดยไม่กลัวความสูงเลย\nแม้แต่น้อย ขณะที่เธอมองดูการแข่งรถที่เกิดขึ้นในสนามด้วยความ\nสนใจ การแข่งขันที่ดุเดือดก็ทำให้เธอต้องพากย์เสียงออกมาเป็นระยะ ๆ แต่ว่า... บอลลูนลมร้อนและชุดแต่งกายแปลก ๆ ของเธอนี่มันยังไงนะ?\nและแล้วมันก็เป็นส่วนหนึ่งของ \"การบำบัดทางจินตนาการ\" ที่แสนลึกลับของเธอ แต่ว่ามันก็ดูเป็นวิธีใหม่ที่ใช้ปลดปล่อยอารมณ์ที่คั่งค้าง\nได้ล่ะ",
  str_item_intro_4090843 = "\"ร้อนดั่งเม็ดทรายในทะเลทราย แต่ก็สดชื่นเหมือนดั่งน้ำพุ การวางเคียงข้างเพื่อเปรียบเทียบกันระหว่างความทันสมัยกับการอนุรักษ์นิยม\"\n\"ช่างน่าตกใจและก้าวร้าวนัก...\"\nแม้ว่าจะมีความคิดเห็นที่แตกต่างกันไปต่าง ๆ นา ๆ แต่วินาทีที่อีสต์วานปรากฏตัวในชุดเสื้อผ้าของเขา คำวิจารณ์ทั้งหมดก็ต้องอันตรธานหายไป ถึงแม้มันจะเป็นชุดที่น่าจะเหมาะกับห้องจัดงานสุดอลังการมากกว่า แต่เขาก็ฉายแววให้เห็นถึงเสน่ห์ของซูเปอร์สตาร์ออกมาได้ บางทีอาจจะเป็นที่ออร่าของ \"เจ้าแห่งเงา\" ในตัวเขาที่ช่วยส่งเสริมเสน่ห์ให้อีกด้านก็ได้",
  str_item_intro_4090603 = "ชุดแต่งกายของผู้ตัดสินในการแข่งรถจะต้องมีความ\nโดดเด่นอยู่เสมอ เพื่อที่ว่านักแข่งรถจะได้มองเห็นผู้ตัดสินได้อย่างชัดเจน\nขณะที่ใช้ความเร็วสูงมาก\nและโจนา ผู้ที่ไม่มีเงินซื้อเหล้าดื่มแล้ว ก็ได้ค้นพบความลับด้านมืดของการแข่งรถหลังจากที่เธอได้สมัครเป็นผู้ตัดสิน เดิมทีโจนาตั้งใจที่จะสนใจแต่เรื่องของตัวเอง แต่เพื่อเด็กผู้หญิงตัวน้อย เธอจึงได้ตัดสินใจลงสู่สนามแข่งเพื่อนำความยุติธรรม\nกลับมาจากพวกอันธพาลที่ก็ลงแข่งด้วยเช่นกัน",
  str_item_intro_4090713 = "รถที่ใช้แข่งมีควันลอยขึ้นจากอุณหภูมิที่ร้อนแรง สภาพอากาศที่โหดร้าย และพระอาทิตย์ที่แผดเผา และเม็ดเหงื่อที่ร่วงสู่ทะเลทรายก็จะมลายหายวับไปใน\nพริบตา\nแม้จะเป็นเช่นนี้ แต่ทาคิก็ยังเข้าสู่การแข่งขันในสภาพที่ \"\"เตรียมพร้อมเต็มที่\"\" เพื่อเอาชนะคู่ต่อสู้และคว้าแชมป์มาให้ได้ หรือว่าเงินรางวัลจะทำให้เขากระตือรือร้นได้ถึงเพียงนี้?",
  str_item_intro_4091263 = "นักเขียนหนังสือขายดีซึ่งติดอยู่กับปัญหาความคิดตัน เธอแต่งตัวสวยและวางแผนที่จะเดินไปตามถนนเพื่อหาไอเดีย ทำไมต้องแต่งตัวสวยน่ะเหรอ? อาจเป็นเพราะเธอไม่ต้องการให้คนอื่นรู้ว่าผู้จัดการกิลด์ผู้ยิ่งใหญ่มีงานอดิเรก \"แบบสาวน้อย\"\nแต่ระวังอย่าดูถูกความทุ่มเทของเบเธลกับงานอดิเรกของเธอเชียวนะ... เธอเต็มใจที่จะเสี่ยงทุกอย่างเพื่อแรงบันดาลใจชั่วครู่...",
  str_item_intro_4090673 = "สายลมพัดมาและชุดเดรสสีขาวก็พลิ้วไหวเบา ๆ เผยให้เห็นดอกไม้สีแดงที่ปักไว้ ชุดของอลิซทำให้ผู้คนนึกถึง... เค้กชนิดหนึ่ง ใช่ เค้กสตรอว์เบอร์รีที่จะมีให้กินเฉพาะในงานวันเกิดเท่านั้น แต่ที่บ้านขนมหวานในฝัน คุณสามารถกินขนมทุกอย่างที่ชอบได้ฟรี ๆ เลย เพียงแค่ตอบคำถามของอลิซ เจ้าของร้านอย่างตรงไปตรงมา นี่คือสิ่งที่อลิซลงโทษคุณเป็นพิเศษ เอ้ย! ฉันหมายถึง... \"ให้รางวัล\" เป็นพิเศษน่ะ",
  str_item_intro_4090103 = "\"ชุดที่สะอาดและเป็นระเบียบเรียบร้อยคือความภาคภูมิใจของสาวใช้\"!\nสวมชุดเมดที่ลิตาเย็บด้วยมือและที่คาดผมประดับลูกไม้ อ้อ อย่าลืมผูกโบว์สีทองบนผ้ากันเปื้อนด้วยล่ะ\nวันนี้ลูอิสต้องช่วยนายท่านแต่งตัวและจัดน้ำชายามบ่าย ไม่ต้องห่วงนะคะ ทั้งผึ้ง กวาง และแม้แต่ก้อนเมฆก็จะมาช่วย\nดูสิคะ! เมดเริ่มทำงานแล้วนะ",
  str_item_intro_4090283 = "อะแฮ่ม ยินดีต้อนรับหัวหน้าสาวใช้แห่งคฤหาสน์อัปตัน! อะไรนะ หน้าตาเธอดูคุ้น ๆ เหรอ? ใช่แล้วล่ะ เธอคือราฟาเอลผู้น่ารักของเรานั่นเอง!\nไม่นานมานี้เธอได้รับมอบหมายพิเศษคือการฝึกทักษะการต่อสู้ให้บรรดาสาวใช้ของลูโมโพลิส และตอนนี้ก็ใกล้จะจบคอร์สแล้ว สาวใช้ทุกคนภายใต้การแนะนำของราฟาเอลต่างก็ประสบผลสำเร็จอย่างดีเยี่ยม เพียงแต่... อาชีพการเป็นสาวใช้ของราฟาเอลดูจะไปไม่ค่อยสวยนัก",
  str_item_intro_4091163 = "เฟลอร์ใช้เวลาและความพยายามอย่างมากในการทำขนมปังในความทรงจำของเขา แต่ไม่เคยประสบความสำเร็จ\nในครั้งนี้ เฟลอร์เตรียมพร้อมมากขึ้น เขาเปลี่ยนมาสวมเสื้อที่เย็บอย่างประณีต ผ้ากันเปื้อนที่รีดอย่างดี และสวมรองเท้าขัดเงาเอี่ยมอ่อง ว่ากันว่าการสวมเสื้อผ้าแบบนี้จะทำขนมปังที่แสนอร่อยได้อย่างแน่นอน แม้จะฟังดูไม่น่าเชื่อ แต่เฟลอร์ก็เลือกที่จะเชื่อตามที่หัวใจของเขาปรารถนา",
  str_item_intro_4090703 = "เมื่อถูกลีโอนาเพ่งมอง คุณรู้สึกว่าอากาศรอบตัวเริ่มร้อนผ่าวและคุณก็หายใจถี่ขึ้น นั่นคุณประหม่าเหรอ? ใช่สิ มีไม่กี่คนหรอกที่จะไม่ประหม่าเมื่ออยู่ต่อหน้าลีโอนา ผู้ที่ทั้งทรงพลังและสวยสะท้าน รองเท้าแตะแบบผูกเชือกที่พันรอบเรียวขา อีกทั้งร่างกายที่เต็มไปด้วยเครื่องประดับแตกต่างจากสไตล์ปกติ แม้กระนั้นเธอก็ยังแสดงบรรยากาศในโลกส่วนตัวของเธอให้เห็นอย่างเกียจคร้าน",
  str_item_intro_4090813 = "นี่คือชุดที่บร็อคเตรียมไว้ให้ตัวเองเป็นพิเศษเพื่อค้นหา \"บางอย่าง\" กางเกงว่ายน้ำที่ช่วยให้เขาเคลื่อนไหวได้อย่างคล่องตัว กระดานโต้คลื่นสไตล์พิเศษ และเสื้อคลุมใสที่ทำให้นึกถึงเสื้อกันฝน เสื้อคลุมใสเหรอ? พูดตรง ๆ เลยนะ เหตุผลแท้จริงที่บร็อคออกแบบเสื้อคลุมใสขึ้นมา ก็คงเพราะอยากให้พวกเราเอ่ยชมนั่นแหละ ดูสิ ร่างกายของเขาที่เสริมสร้างขึ้นจากโปรตีนผงและการออกกำลังกายอย่างหนัก จากแสงแดดและหยาดเหงื่อ กำลังต้องการคำชมเชยจากคุณ",
  str_item_intro_4091123 = "ช่วงนี้มีตำนานแพร่หลายในอัมบราตัน ทั้งจดหมายเตือน แก๊งโจรที่สร้างความวุ่นวายไปทั่ว อัญมณีที่ถูกขโมยไป... ผู้ต้องสงสัยเบอร์หนึ่งของเราจะใช่สโมกกี้ผู้ไม่สนโลกคนนี้รึเปล่านะ? ถ้าอยากรู้ความจริง คุณคงต้องปลดล็อกกุญแจมือให้เธอก่อน แน่นอนว่าฉายาใหม่ของเธอก็น่าสนใจไม่แพ้เสื้อผ้าใหม่เลย เธอคือ \"แบล็คแคท\" ผู้ที่จะมารับอัญมณีในอีกสามวันตามที่สัญญาไว้",
  str_item_intro_4090384 = "ต้องมีชุดนี้ก่อน หรือต้องมีเกมที่มีชุดนี้ก่อนกันแน่? นั่นไม่สำคัญอีกต่อไปแล้ว ที่สำคัญคือกรอนรูได้เตรียมชุดนี้ไว้เป็นพิเศษสำหรับวันหยุดพักผ่อนของเธอ และจะเข้าสู่โหมดวันหยุดทันทีหลังจากสวมใส่ แม้ว่าเธอจะไปอควาเรียม ไม่ใช่ไปทะเลก็เถอะ",
  str_item_intro_4090413 = "ตัวตนของเธอมีกี่อย่างกันแน่นะ? ไม่เพียงแต่เป็นไกด์ของลูโมโพลิส แต่เธอยังมีหน้าที่รับผิดชอบอีกมากมาย หนึ่งในนั้นคือการเป็นพรีเซ็นเตอร์โปรโมทโรงแรมทีร์ เธอสวมใส่ชุดว่ายน้ำนี้เพื่อถ่ายภาพทำโบรชัวร์ อ่อนนุ่มและปราณีต เป็นชุดที่มีเนื้อผ้าเลิศหรูที่สุด เมื่อมองดูเธอ ทุกคนต่างก็สนใจโรงแรมนี้ที่เธอกำลังโปรโมตอยู่",
  str_item_intro_4090873 = "เบเวอร์ลีสวมชุดว่ายน้ำที่เป็นเกราะเพื่อให้เข้ากับสภาพแวดล้อมในท้องถิ่นในตอนที่เธอไปเยือนอาณาเขตเกาะของครอบครัว แม้ว่ามันจะเป็นชิ้นเล็กชิ้นน้อยกว่าเครื่องแต่งกายปกติของเธอมาก แต่ออร่าชนชั้นสูงของเธอนั้นมีมากจนเกินกว่าจะซ่อนไว้ได้ นี่ไม่ใช่เพียงเพราะเธอมาจากตระกูลนักรบเท่านั้น แต่ยังเป็นเพราะการแสวงหาเกียรติยศของขุนนางด้วย",
  str_item_intro_4091293 = "แม้ว่าเขาจะสวมใส่เสื้อผ้าหน้าร้อนแบบเท่ ๆ แต่สายตาที่จริงจังคู่นั้นบอกทุกคนว่าเขาไม่ได้มาที่นี่เพื่อพักผ่อน แต่เพื่อทำภารกิจให้สำเร็จ ชุดนี้ช่วยให้ลุคสามารถรักษาพละกำลังในป่าที่ร้อนชื้น และยังเป็นชุดทางการซึ่งเตรียมมาเป็นพิเศษสำหรับการต่อสู้เพื่อปกป้องผีเสื้ออันล้ำค่าจากนักล่าที่ไร้ยางอายอีกด้วย",
  str_item_intro_4091483 = "ปาร์ตี้ใต้น้ำในทะเลทรายกำลังจะเริ่มต้นขึ้น แต่สิ่งที่ทำให้ผู้คนจำนวนมากตื่นเต้นเป็นพิเศษคือโอกาสที่จะได้เห็นรูปร่างที่น่าทึ่งของ Azure! เธอมีเสน่ห์เป็นพิเศษภายใต้เสื้อผ้าที่โปร่งสบาย... อะแฮ่ม โปรดควบคุมตัวเองและอย่าจ้องนานเกินไป! เพลิดเพลินไปกับสายลมยามเย็นที่อบอุ่นและชื้น ฟังเพลงเสียงดัง และเต้นรำกับฝูงชนเป็นครั้งคราวเป็นสิ่งที่ยอดเยี่ยม!",
  str_item_intro_4090254 = "ชุดการแสดงบนเวทีอันวิจิตรตระการตาที่ให้บรรยากาศอันสง่างามของขุนนางโบราณ มันดูไม่เข้ากับแฟชั่นในปัจจุบัน แต่นั่นเป็นเพราะชารอนออกแบบชุดใหม่ของเขาให้เป็นแบบนี้ ฟุ่มเฟือยอย่างที่ควรจะเป็น มันดึงดูดความสนใจของผู้ชมได้อย่างรวดเร็วเมื่อใดก็ตามที่ Charon ยืนอยู่หน้ากล้อง ทำให้เขามีโอกาสแสดงทักษะการแสดงที่น่าประทับใจอย่างไม่อาจลืมเลือนอย่างเต็มศักยภาพ พูดได้เลยว่าทั้งชารอนและชุดของเขาถูกสร้างมาเพื่อการแสดง",
  str_item_intro_4090683 = "พิเศษ พิเศษ! ความร่วมมือล่าสุดระหว่าง Courier Union และหนังสือพิมพ์ Umbraton ทำให้พนักงานส่งของมีงานเพิ่มขึ้น: การขายการสมัครสมาชิกหนังสือพิมพ์ และด้วยเหตุนี้ เวนดี้จึงสวมชุดสาวเปเปอร์เกิร์ลใหม่ล่าสุดและออกเดินทางไปขายหนังสือพิมพ์ด้วยความตื่นเต้นและความพากเพียรในแบบฉบับของเธอ! ธรรมชาติที่ว่องไวและร่าเริงของเวนดี้ไม่เคยปล่อยให้เธอตามหลังเพื่อนฝูง แม้แต่ตอนที่เธอทำภารกิจที่ไม่คุ้นเคย!",
  str_item_intro_4091003 = "Sikare ซึ่งมักจะผูกติดอยู่กับอดีต ได้เปลี่ยนลุคประจำของเธอเพื่อหาคนใหม่เพื่อรับมือกับสถานการณ์ที่ไม่คาดฝัน แม้ว่าเธอจะดูเหมือนแพทย์ทั่วไป แต่สิ่งของในกระเป๋าเอกสารของเธอเต็มไปด้วยเครื่องมือทางการแพทย์ที่ไม่ธรรมดา ทั้งนี้เพราะพระนางไม่เพียงแต่ต้องดูแลความเจ็บป่วยของคนเป็นเท่านั้น แต่ต้องดูแลความปราถนาของผู้จากไปอย่างสุดที่รักด้วย...",
  str_item_intro_4091203 = "ต้องขอบคุณความต้องการที่ได้รับความนิยม ทำให้ Hedy ได้เข้าร่วมในกิจกรรมแลกเปลี่ยนเพื่อส่งเสริมความสามัคคีและความร่วมมือระหว่าง Illumina Federation และ Lumopolis ตามคำสั่งของผู้บังคับบัญชา เธอเดินทางไปยังเมืองแกนนอนเพื่อทำหน้าที่เป็นนายอำเภอเป็นเวลาหนึ่งวัน เพื่อส่งเสริมความปลอดภัยในการจราจรและการป้องกันอาชญากรรมบนท้องถนน แม้จะเป็นอัศวินแห่งลูโมโปลิสที่น่าภาคภูมิใจ แต่เฮดี้ก็ยังเชื่อฟังและสวมชุดสหพันธ์ของเธอ แม้ว่าเธอจะรู้สึกอึดอัดบ้าง แต่ก็ไม่ได้ปิดบังเสน่ห์และความมั่นใจตามธรรมชาติของเธอ",
  str_item_intro_4091193 = "Revy ตั้งใจเอาตัวเองเข้าคุกในความพยายามของเธอเพื่อให้ได้ซอสเผ็ดในตำนานแห่งความทรงจำของเธอ มุ่งหน้าสู่อันตรายเพียงลำพัง หลังกำแพงหินขนาดใหญ่เหล่านั้น เธอพบว่าตัวเองรายล้อมไปด้วยอาชญากรที่เข้มแข็งจากพื้นที่อาละวาด สถานการณ์อันตรายจริงๆ... Revy ซึ่งมาจากสหพันธ์ Illumina และไม่เคยประสบกับอันตรายที่วุ่นวายของสถานที่ดังกล่าวมาก่อน จะประสบความสำเร็จในภารกิจลับพิเศษของเธอได้หรือไม่?",
  str_item_intro_4091213 = "A beautiful, crimson flower adorned with countless, vicious thorns: everything about Paloma's appearance screams, \"approach at your own peril.\" Coupled with a faint smile, an air of cold elegance surrounds her. Those who lay eyes on this deadly damsel know in their hearts that provoking her would be the last thing they ever do. Incurring the wrath of the most sinister Umbraton crime lord would be a wiser decision by comparison. Or has she already become a crime lord...",
  str_item_intro_4090123 = "อยู่มาวันหนึ่ง จู่ๆ ตำนานก็ปรากฏขึ้นในเมืองกันนอน—ตำนานของ \"ผู้บังคับใช้ความยุติธรรม\" หรือที่รู้จักในชื่อ \"ผู้ลงโทษ\" ทันใดนั้นฟ้าแลบก็ผ่าท้องฟ้าทุกครั้งที่มีคนฝ่าฝืนกฎ และเนเมซิสก็ปรากฏตัวขึ้นข้างๆ พวกเขาเพื่อมอบบทลงโทษอันน่าสยดสยอง หลังจากทำเช่นนั้น เธอก็ส่งสายเดี่ยวที่บาดพวกเขาถึงกระดูกและบังคับให้พวกเขากลับใจ หลังจากดำเนินการตามความยุติธรรมแล้ว เธอก็หายตัวไปในแสงวาบเพื่อลงโทษผู้กระทำความผิดอีกคน",
  str_item_intro_4090773 = "ในวันหยุดหายาก เบธเลเฮมบังเอิญเจอชีวประวัติของนักร้องสาวมากความสามารถ ในไม่ช้าเธอก็หลงทางในหน้าหนังสือเล่มนี้ กลายเป็นหนึ่งเดียวกับนักร้อง ประสบกับชื่อเสียงที่โด่งดัง ชัยชนะของเธอ และจากนั้นก็สูญเสียเสียงของเธอไป “แล้วถ้าฉันเป็นเหมือนเธอล่ะ” เป็นคำถามที่เบธเลเฮมไม่มีคำตอบ สิ่งที่เธอทำได้คือจินตนาการว่าตัวเองอยู่ในรองเท้าของนักร้องหญิง หยิบเครื่องดนตรีขึ้นมาและแสดง เธอจินตนาการถึงความหลงใหลในการสร้างสรรค์ เธอจินตนาการถึงการสูญเสียเสียงของเธออย่างหลีกเลี่ยงไม่ได้บนเวที เธอจินตนาการถึงชีวิตในฐานะนักร้องหญิง ในขณะที่กำลังตกลงกับอนาคตของเธอเอง",
  str_item_intro_4090833 = "เพื่อที่จะปลุก Lilin ที่พวกเขาปกป้องอย่างแข็งขัน พวกเขาต้อง... กลายเป็นไอดอล? ถึงกระนั้น พวกเขาก็ดูเหมือนจะปฏิบัติตามอย่างเคร่งครัดในการเขียนโปรแกรมในฐานะสาวใช้ พวกเขาสามารถก้าวไปสู่จุดสูงสุดของอาชีพที่ความมีชีวิตชีวาและความคิดสร้างสรรค์เป็นสิ่งสำคัญได้หรือไม่? ถ้ามีพิมพ์เขียวที่พวกเขาสามารถทำตามได้ และใช้ประโยชน์จากจำนวนของพวกเขาได้ มันอาจจะเป็นไปได้...",
  str_item_intro_4091313 = "แม้ว่าเขาจะรักษามุมมองต่อโลกที่เป็นเอกลักษณ์ของเขาไว้ แต่ Novio ก็กลายเป็นนักเปียโนระดับปรมาจารย์ทันทีที่เขาสวมลุคใหม่นี้ เขานำความอบอุ่นและความปรารถนาดีมาสู่ผู้รอดชีวิตที่มีจิตใจเข้มแข็งในนอร์ธแลนด์ และให้กำลังใจผู้ชมพิเศษบางคนให้อดทนและก้าวไปข้างหน้าอย่างเด็ดเดี่ยว มุ่งมั่นที่จะพัฒนาตนเองตลอดไป",
  str_item_intro_4091383 = "แม้ว่าหัวหน้าของเธอจะบังคับให้เธอเข้าร่วมการแข่งขันไอดอล แต่ Siobhan ก็ยังพยายามอย่างเต็มที่เพื่อเตรียมตัวให้ดี ในขณะที่ใช้ความสามารถของเธอ เธอยังทุ่มเทความพยายามอย่างมากในการค้นคว้าและออกแบบเครื่องแต่งกายที่สมบูรณ์แบบ จิตวิญญาณอันแน่วแน่ของการวิจัยทางวิทยาศาสตร์นำมาซึ่งการเปลี่ยนแปลงอันน่าทึ่งในตัว Siobhan—แสงที่ส่องประกายของเธอที่ไม่อาจดับได้ ซึ่งเป็นหนทางสู่ดาราในอนาคตที่ไม่อาจมองข้ามได้",
  str_item_intro_4090273 = "เธอเป็นที่สยดสยองในหมู่คนรักของลูโมโปลิส ทุกๆ วันพระจันทร์เสี้ยวจะมีอัศวินในชุดขาวออกลาดตระเวนทั่วทุกมุมเมืองเพื่อตามหาคนที่รัก ทันทีที่เธอพบเธอจะออก \"ห้ามตกหลุมรัก\" ทันที ดังนั้นเธอจึงถูกเรียกว่า \"สายฟ้าฟาดที่ทำลายความรัก\" ซึ่งทำให้คู่รักหวาดกลัว",
  str_item_intro_4090553 = "Pittman ดูเหมือนจะได้รับอิทธิพลจากเทศกาลวัน Mooncrown Day เมื่อเขาเลือกชุด ซึ่งแตกต่างจากลุคมืออาชีพตามปกติของเขา มันมีความอ่อนโยนที่ไม่ค่อยเห็นในตัวเขาโดยไม่สูญเสียความหนักแน่นและความสง่างามตามปกติของเขา แน่นอนว่านี่ไม่ใช่เพราะเขาถูกพูดถึง แต่เพียงเพื่อเป็นผู้ส่งสารที่มีคุณสมบัติและเติมเต็มความปรารถนาอันยาวนานของผู้อื่น",
  str_item_intro_4090913 = "ในโลกของ Chloe ความรักมาพร้อมกับการพลัดพรากเสมอ ดังนั้นคงจะมากเกินไปหน่อยที่จะขอให้เธอเปิดเพลงที่เฉลิมฉลองความรักอันแสนหวาน ในกรณีนั้น เราอาจสรรเสริญความรักนิรันดร์ในนามของพระเจ้า—ความรักของผู้คนอาจจางหายไปหลังจากไม่กี่ปี แต่อย่ากังวล แสงสว่างจะประทานพรและรักทุกคนเท่าๆ กัน",
  str_item_intro_4091673 = "ไม่มีการขาดแคลนมายากลทุกประเภทในสถานที่ทางสังคมเช่นนี้ แต่ความรู้สึกลึกลับเป็นกุญแจสำคัญในสิ่งเหล่านี้ทั้งหมด การ์ด คำพูด หรือแม้กระทั่งเพียงแวบเดียว เราสามารถแสดงการแสดงที่ยิ่งใหญ่และประณีตให้เสร็จสมบูรณ์ได้ในเวลาที่ไม่ตั้งใจโดยไม่มีใครฉลาดกว่าใคร แม้ว่าจะไม่มีเสียงปรบมือเหมือนปกติ แต่ก็เป็นเรื่องดีสำหรับเจโน่เมื่อเขาอยากจะช่วยเหลือเพื่อนบ้างเป็นครั้งคราว",
  str_item_intro_4090043 = "ศพเย็นชา เบาะแสที่ถูกทำเครื่องหมายไว้ วงล้อมแล้ววงล้อม... ฉากที่คลาสสิกและน่าตื่นเต้นเช่นนี้สามารถทำให้จินตนาการของทุกคนโลดแล่นได้เสมอ ตัวอย่างเช่น นักสืบอาจเป็นฆาตกรหรือสมรู้ร่วมคิดกับฆาตกร ฆาตกรอาจซ่อนตัวอยู่ในหมู่พวกเรา หรือพยานทั้งหมดอาจเป็นฆาตกร... ใครจะคิดว่าผู้ตายและนักสืบจะทำงานร่วมกัน",
  str_item_intro_4090483 = "บรรยากาศอันน่าสยดสยองคืบคลานเข้าสู่ถนนอันเงียบสงบของ Umbraton แม้ว่าผู้สัญจรผ่านไปมาบนถนนดูเหมือนจะเพลิดเพลินกับค่ำคืนอันเงียบสงบ แต่สายตาที่ระแวดระวังของเจ้าหน้าที่สายตรวจคนหนึ่งเฝ้าดูอย่างใกล้ชิดเพื่อจับร่องรอยของความบาปทั้งหมด ตราบใดที่พวกเขาซ่อนตัวอยู่ในเมืองนี้ เธอผู้พิทักษ์สันติจะไม่หยุดเดินตรวจตราตามท้องถนน ทุกอย่างก็เพื่อ...น้องสาวคนเดียวของเธอ!",
  str_item_intro_4091484 = "สำนักงานที่มีหน้าต่างสว่างและสะอาด โซฟานุ่มๆ ไวน์ที่ทำให้มึนเมา และผู้อำนวยการชั่วคราวนอนลงบนโซฟา อย่าปล่อยให้ท่าทางเกียจคร้านของเธอหลอกลวงคุณ—ผู้หญิงสวยคนนี้อันตราย โดยเฉพาะกับคนที่จะกลายเป็นเหยื่อของเธอในไม่ช้า ในทางที่แท้จริง",
  str_item_intro_4091663 = "“ก็...ตัวเล็กน่ารักไปไหนเนี่ย” เพื่อค้นหาสัตว์ร้ายเหล่านั้นและเปิดเผยความจริง Fia กลายเป็นนักสืบและเริ่มสืบสวนคดีลึกลับนี้อย่างรอบคอบโดยการตรวจสอบหลักฐานทุกประเภทและพิจารณาประเด็นสำคัญที่สงสัย เมื่อมองดูว่าเธอดูจริงจังและขยันขันแข็งเพียงใด บางทีเธออาจจะค้นพบบางสิ่งจริงๆ",
  str_item_intro_4090983 = "ภายใต้คำสั่งของ Shadowlord Cuscuta ผู้สันโดษได้รับมอบหมายให้เป็นนักสืบและจับอาชญากรอาละวาด แม้ว่าเธอจะต่อสู้กับการเยี่ยมตามท้องถนนและการสัมภาษณ์พยาน แต่สัญชาตญาณที่เฉียบแหลมของเธอทำให้เธอสามารถอนุมานถึงตัวตนของอาชญากรจากเงื่อนงำที่อยู่ในมือได้ จากที่นั่งสบายๆ บนเก้าอี้ของเธอ เธอสังเกตเกมหมากรุกและหมกมุ่นอยู่กับการครุ่นคิดจนกระทั่งพบคำตอบผ่านการหักเงิน",
  str_item_intro_4091034 = "ผู้คนไม่ควรก่ออาชญากรรม มิฉะนั้นพวกเขาจะถูกลงโทษจากสวรรค์ ซึ่งเป็นที่รู้จักกันในโลกมนุษย์ว่าเป็นการพิจารณาคดี การพิพากษา และการลงโทษ แน่นอนว่าขั้นตอนนี้ไม่ได้น่ากลัวอย่างที่คิด โดยเฉพาะอย่างยิ่งเมื่อ Eicy กลายเป็นเจ้าหน้าที่สอบสวนของคุณ เด็กสาวผู้อ่อนโยนไม่เคยพึ่งพาความรุนแรงในการทำลายการป้องกันของใครบางคน... หรือมากกว่านั้น การป้องกันเหล่านั้นไม่มีประโยชน์เลยตั้งแต่แรก ดังนั้นหากคุณเคยพบเธอ อย่าทะเลาะกันอย่างไร้จุดหมาย ปล่อยให้ทุกอย่างเป็นของ Eicy",
  str_item_intro_4090293 = "เพื่อเป็นเกียรติแก่ความปรารถนาสุดท้ายของเจ้านาย กาเบรียลได้สวมชุดหรูหราและเดินทางไปยังสถานเลี้ยงเด็กกำพร้าในเมืองอัมบราตัน สภาพแวดล้อมที่มืดมนและทรุดโทรมตัดกับเครื่องแต่งกายอันวิจิตรงดงาม และการกระทำที่ค่อนข้างเงอะงะของกาเบรียลทำให้เด็กกำพร้าเข้าใจผิดว่าเธอเป็นแม่มด แต่ท้ายที่สุด เด็กกำพร้าก็สัมผัสได้ถึงการอุทิศตนอย่างจริงใจของกาเบรียลในการปกป้องบ้านของพวกเขา และชุดเองก็ดูเหมือนจะส่องแสงที่ปลอบโยน",
  str_item_intro_4090463 = "สำหรับผู้ใหญ่ มันอาจจะเป็นเพียงมนต์ดำที่น่าสะพรึงกลัว แต่สำหรับพวกเขาแล้ว มันคือประตูสู่อาณาจักรแห่งจินตนาการ ความลุ่มหลง และสิ่งมหัศจรรย์ที่ไม่ธรรมดาซึ่งสร้างขึ้นเพื่อจิตวิญญาณที่อยากรู้อยากเห็นและมีชีวิตชีวาของพวกเขาโดยเฉพาะ ในการปรุงยาต้องห้าม พวกเขาค้นหาส่วนผสมที่แปลกประหลาดอย่างไม่รู้จักเหน็ดเหนื่อย สวมเครื่องแต่งกายที่ไม่เหมือนใครซึ่งเน้นย้ำถึงบุคลิกลักษณะของพวกเขาเท่านั้น",
  str_item_intro_4090623 = "เพื่อให้แน่ใจว่าเซสชั่นการศึกษาที่จัดโดย Leah ดำเนินไปอย่างราบรื่น Sylva ได้พยายามเป็นพิเศษในการสวมชุดทางการนี้ โดยดูเหมือนนักวิชาการหนุ่มที่พร้อมจะพบกับอาจารย์ที่เขาเคารพนับถือ ทั้งฉลาดเฉลียว ฉลาด และมีมารยาทดี ท่าทางของเขาทำให้การเรียนเต็มไปด้วยบรรยากาศในเชิงบวก ทำให้เขาได้รับสมญานามว่าเป็น 'นักเรียนต้นแบบ'...",
  str_item_intro_4091433 = "ขณะที่เดินทางในป่าในเวลากลางคืน มีการกล่าวกันว่าสิ่งมีชีวิตที่เป็นลางไม่ดียังคงอยู่ในโลกหลังเกิดพายุฝนฟ้าคะนอง ด้วยเหตุนี้ รินเนะจึงสวมชุดพิธีการของเธอและถือระฆังคางุระไว้สูง พร้อมที่จะกวาดล้างสิ่งชั่วร้ายให้หมดไปจากโลกนี้เพื่อปกป้องสิ่งมีชีวิต\n\"บทกวีถึงคนตายและคนเป็น ขอให้เพลงนี้ไปกับคุณที่อีกฝั่งของแม่น้ำเลธ\"\n\"แม่น้ำ Lethe ไหล ความแค้นและความขมขื่นเติบโตขึ้น\"\n\"ลำโพงร้องเพลงประสานเสียง\"\n\"ฟังอย่างสงบ ให้จิตวิญญาณของคุณติดตามฉัน\"",
  str_item_intro_5000001 = "ว่ากันว่ามีสารลึกลับบางอย่างที่มีข้อมูลโบราณ ซึ่งสามารถเร่งความเร็วการก่อสร้างอาคารและการทำเฟอร์นิเจอร์ได้",
  str_item_intro_5000002 = "สวนลอยฟ้า - รีเฟรชสมบัติ",
  str_item_intro_5002101 = "ไม้เนื้อแข็ง เหมาะสำหรับสร้างอาคาร ทำเฟอร์นิเจอร์ และอื่น ๆ",
  str_item_intro_5002201 = "แร่ที่เพิ่งขุดมาใหม่ ๆ จำเป็นต้องแปรรูปต่อไป แต่มันก็มีมูลค่าในตลาดเรียบร้อยแล้ว",
  str_item_intro_5003001 = "ชิ้นส่วนหินที่พบในส่วนต่าง ๆ ของสวนลอยฟ้าซึ่งน่าจะเป็นวัตถุโบราณ แต่ยังไม่ทราบว่าไว้ใช้ทำอะไร ชับบ์ชอบชิ้นส่วนเหล่านี้มากและจะนำของบางอย่างมาแลกด้วย",
  str_item_intro_5003101 = "กาวทั่วไปสำหรับสร้างอาคารและทำเฟอร์นิเจอร์ ซึ่งสามารถยึดวัสดุเข้าด้วยกันได้ดีและทำให้ส่วนประกอบต่าง ๆ แข็งแรง",
  str_item_intro_5003102 = "กาวที่ดีที่สุดสำหรับสร้างอาคารและทำเฟอร์นิเจอร์ เพียงเล็กน้อยก็เพียงพอที่จะติดวัสดุให้แน่นและทำให้ส่วนประกอบแข็งแรงมาก",
  str_item_intro_5011001 = "ขวานเบา Lv.1 มีด้ามเป็นโพรง จึงตัดต้นไม้ที่หนาได้อย่างรวดเร็ว",
  str_item_intro_5011002 = "ขวานเบา Lv.2 มีด้ามเป็นโพรง จึงตัดต้นไม้ที่หนาได้อย่างรวดเร็ว",
  str_item_intro_5011003 = "ขวานเบา Lv.3 มีด้ามเป็นโพรง จึงตัดต้นไม้ที่หนาได้อย่างรวดเร็ว",
  str_item_intro_5011004 = "ขวานเบา Lv.4 มีด้ามเป็นโพรง จึงตัดต้นไม้ที่หนาได้อย่างรวดเร็ว",
  str_item_intro_5011005 = "ขวานเบา Lv.5 มีด้ามเป็นโพรง จึงตัดต้นไม้ที่หนาได้อย่างรวดเร็ว",
