  str_item_intro_5012002 = "เบ็ดแชมเปี้ยน Lv.2 ด้วยคันเบ็ดที่สมดุล ทนทาน และมีสายเบ็ดที่แข็งแรง นี่จึงเป็นเครื่องมือที่ยอดเยี่ยมในการจับปลาตัวใหญ่",
  str_item_intro_5012003 = "เบ็ดแชมเปี้ยน Lv.3 ด้วยคันเบ็ดที่สมดุล ทนทาน และมีสายเบ็ดที่แข็งแรง นี่จึงเป็นเครื่องมือที่ยอดเยี่ยมในการจับปลาตัวใหญ่",
  str_item_intro_5012004 = "เบ็ดแชมเปี้ยน Lv.4 ด้วยคันเบ็ดที่สมดุล ทนทาน และมีสายเบ็ดที่แข็งแรง นี่จึงเป็นเครื่องมือที่ยอดเยี่ยมในการจับปลาตัวใหญ่",
  str_item_intro_5012005 = "เบ็ดแชมเปี้ยน Lv.5 ด้วยคันเบ็ดที่สมดุล ทนทาน และมีสายเบ็ดที่แข็งแรง นี่จึงเป็นเครื่องมือที่ยอดเยี่ยมในการจับปลาตัวใหญ่",
  str_item_intro_5013001 = "เสียมหนัก Lv.1\nด้วยหัวที่มีน้ำหนัก แรงเหวี่ยงของมันจึงแข็งแรงพอที่จะทำลายหินได้ทุกชนิด",
  str_item_intro_5013002 = "เสียมหนัก Lv.2\nด้วยหัวที่มีน้ำหนัก แรงเหวี่ยงของมันจึงแข็งแรงพอที่จะทำลายหินได้ทุกชนิด",
  str_item_intro_5013003 = "เสียมหนัก Lv.3\nด้วยหัวที่มีน้ำหนัก แรงเหวี่ยงของมันจึงแข็งแรงพอที่จะทำลายหินได้ทุกชนิด",
  str_item_intro_5013004 = "เสียมหนัก Lv.4\nด้วยหัวที่มีน้ำหนัก แรงเหวี่ยงของมันจึงแข็งแรงพอที่จะทำลายหินได้ทุกชนิด",
  str_item_intro_5013005 = "เสียมหนัก Lv.5\nด้วยหัวที่มีน้ำหนัก แรงเหวี่ยงของมันจึงแข็งแรงพอที่จะทำลายหินได้ทุกชนิด",
  str_item_intro_5014001 = "หัวพลั่วมีความหนา ดังนั้นถึงแม้จะกระแทกหินแข็งก็ไม่มีวันบิ่น ทำให้การขุดเป็นงานแสนง่าย",
  str_item_intro_5011012 = "หินหยาบและแข็งที่สามารถลับคมได้\nอัปเกรดขวานเบาได้ภายในกระเป๋า",
  str_item_intro_5012012 = "ด้วยไม้คุณภาพสูงที่พบในสวนลอยฟ้า นำมาตัดเป็นชิ้นบาง ๆ เพิ่มความแข็งแรงและรักษาความเหนียวแน่นให้กับคันเบ็ด ประกอบกับสายเบ็ดแบบพิเศษ ทำให้เบ็ดแชมเปี้ยนรับมือกับทุกสถานการณ์ได้อย่างง่ายดาย อัปเกรดเบ็ดแชมเปี้ยนได้ภายในกระเป๋า",
  str_item_intro_5013012 = "ด้วยการหมุนวงล้ออย่างรวดเร็วด้วยมือ คุณสามารถลับปลายทู่ของเสียมได้\nอัปเกรดเสียมหนักได้ภายในกระเป๋า",
  str_item_intro_5111001 = "นี่คือพิมพ์เขียวของศาลาผู้พิชิต ใช้เพื่อปลดล็อกวิธีการผลิตศาลาผู้พิชิตในหอคอยไฮยาซินท์",
