  str_item_intro_5134049 = "นี่คือพิมพ์เขียวของ Record Obelisk ใช้เพื่อปลดล็อกวิธีการผลิตไอเท็มใน Hyacinth Tower",
  str_item_intro_5211001 = "ศาลาที่มีเสาคดโค้งและหลังคาหินที่ปกคลุมไปด้วยตะไคร่น้ำ แม้ว่าจะไม่สอดคล้องกับความคิดทางสถาปัตยกรรม แต่มันก็แข็งแรงมาก",
  str_item_intro_5211002 = "กล่าวกันว่าซุ้มประตูโค้งนี้แกะสลักจากหินก้อนเดียว และถึงแม้จะมีหญ้าเป็นชั้น ๆ อยู่ด้านบน ก็ไม่ต้องกังวลเรื่องความทนทาน",
  str_item_intro_5211003 = "ที่แวะพักระหว่างขนส่งเสบียงในหุบเขา สร้างได้รวดเร็วและถอดแยกชิ้นส่วนได้ง่าย สามารถสร้างได้มากมายระหว่างทาง",
  str_item_intro_5211004 = "บ่อน้ำลึกที่สร้างขึ้นตรงแหล่งน้ำใต้ดิน มีการติดตั้งรั้วหินล้อมรอบเพื่อไม่ให้ตกลงไปในบ่อ เนื่องจากบ่อน้ำลึกมาก น้ำจึงบริสุทธิ์และเย็น",
  str_item_intro_5211005 = "กังหันลมที่มีรูปทรงเป็นเอกลักษณ์ แม้จะดูเหมือนว่าล้าหลัง แต่ก็ใช้ประโยชน์จากลมได้อย่างเหลือเฟือ! และด้วยเทคโนโลยีที่ยอดเยี่ยม ใบพัดจะค่อย ๆ หมุนไปแม้ไม่มีลม",
  str_item_intro_5221001 = "รั้วไม้ เมื่อเชื่อมต่อกันแล้ว พวกมันจะล้อมที่ดินในสวนลอยฟ้าได้",
  str_item_intro_5221002 = "ราวรั้วที่สั้นกว่า แผ่นไม้ที่ประกบกันแบบสะเปะสะปะให้บรรยากาศแบบชนบท",
  str_item_intro_5221003 = "รั้วกั้นอย่างง่าย เหมาะสำหรับกั้นเขตและแบ่งพื้นที่",
  str_item_intro_5221004 = "รั้วหินที่หนักแต่แข็งแรง มีความทนทานมากกว่ารั้วไม้",
  str_item_intro_5221005 = "รั้วกั้นหิน เมื่อฝังลงดินแล้วสามารถใช้งานได้หลายปี แม้จะต้องเผชิญกับสภาพอากาศรูปแบบต่าง ๆ",
  str_item_intro_5221006 = "ราวหินที่แข็งแรงไม่เพียงแต่ดูมั่นคง แต่ยังให้ความรู้สึกปลอดภัยแก่ผู้คน",
  str_item_intro_5223001 = "กระเบื้องปูพื้นสี่เหลี่ยมที่ปูได้อย่างเรียบร้อย เหมาะสำหรับถนนสายหลักและอาคารสำคัญ",
  str_item_intro_5223005 = "หินปูพื้นรูปทรงต่าง ๆ เหมาะสำหรับปูทางเดินและตกแต่งสนามหญ้า",
  str_item_intro_5231001 = "โต๊ะที่มีแผ่นหินสี่เหลี่ยมคางหมูสองแผ่นรองรับไว้ หนักแต่แข็งแรง",
  str_item_intro_5231002 = "โต๊ะหินกลมขนาดเล็ก เมื่อจับคู่กับเก้าอี้ที่เหมาะสม เหมาะสำหรับการพูดคุยแบบสบาย ๆ ระหว่างเพื่อนสองคน",
  str_item_intro_5231003 = "โต๊ะไม้ที่มีขารองรับทั้งสี่ด้าน กว้างและแบนราบ เหมาะสำหรับหลายคนมานั่งด้วยกันในยามว่าง",
  str_item_intro_5232001 = "ม้านั่งหินกลมที่มีเสาหินอยู่กลางลำตัวที่กลวงเพื่อรองรับน้ำหนัก ไม่เพียงแค่ทนทานเท่านั้น แต่ขอบที่โค้งมนยังช่วยลดอันตรายจากการเดินชนได้อีกด้วย",
  str_item_intro_5232002 = "ม้านั่งหินสี่เหลี่ยม ซึ่งมีฐานส่วนล่างกว้างและส่วนบนแคบ มีไม้อีกชั้นเพื่อกั้นความเย็นของหิน รูปร่างดูโอ่อ่าแถมผลิตก็ง่าย สิ่งเดียวที่ไม่ได้ดั่งใจคือง่ายต่อการกระแทกขอบเก้าอี้",
  str_item_intro_5232003 = "เก้าอี้ไม้น้ำหนักเบาและเรียบง่าย มีขารองรับทั้งสองด้าน เก้าอี้จะโคลงเคลงเล็กน้อยเมื่อคุณนั่ง",
  str_item_intro_5232005 = "แขวนไว้ด้วยเชือกจากเสาหินรูปทรงแปลกตา ตัวที่นั่งออกแบบให้เป็นรูปทรงของใบไม้กลม ๆ ซึ่งรักษาสมดุลอย่างชาญฉลาด และสามารถนอนได้อย่างสบายโดยไม่ตกลงมา",
  str_item_intro_5232006 = "ม้านั่งที่ประกอบด้วยแท่นหิน ไม่เพียงแต่นั่งได้ ยังสามารถนอนได้อีกด้วย เนื่องจากทำจากหินจึงให้สัมผัสที่เย็นสบาย",
  str_item_intro_5233001 = "เป็นหินสองก้อนที่วางซ้อนกัน ก้อนหนึ่งใหญ่และก้อนหนึ่งเล็ก หากวางไว้ในตำแหน่งที่เหมาะสม ก็จะสร้างทัศนียภาพที่เป็นเอกลักษณ์ให้กับที่พักโดยรอบได้",
  str_item_intro_5233002 = "ดูเหมือนหินงอกหินย้อยที่ถูกขยายใหญ่หลายเท่า หากตกแต่งอย่างดีก็จะให้ความรู้สึกที่แตกต่างออกไป",
  str_item_intro_5233003 = "ก้อนหินรูปร่างหลากหลายจำนวนมาก ใช้เป็นของตกแต่งตามถนนและในสวน",
  str_item_intro_5233004 = "หลังคาเป็นรูปร่ม ค้ำยันด้วยเสาที่จงใจออกแบบให้เอียงไปข้างหนึ่ง เพื่อให้เกิดร่มเงาได้มากขึ้น ด้านบนมีไม้เลื้อยปกคลุม เมื่อลมพัดผ่านกิ่งก้านและใบไม้ที่ห้อยลงมาจะเป็นภาพที่เพลินตาน่ามอง",
  str_item_intro_5233005 = "การผสมผสานของหินที่ซ้อนกัน น้ำตกขนาดเล็กที่เกิดจากน้ำกัดเซาะ และบ่อน้ำเล็ก ๆ ที่มีแผ่นหินน้อยใหญ่รายรอบ ทำให้เกิดเสียงน้ำที่ฟังแล้วสบายใจและต่อเนื่องภายในสวน",
  str_item_intro_5233006 = "เสาหินตั้งตรงที่ใช้เป็นแกนหลักของกลุ่มหินได้",
  str_item_intro_5233007 = "ประกอบด้วยเสาหินที่ลาดเอียงจำนวนมากและดูเหมือนภูเขาลูกเล็ก ๆ",
  str_item_intro_5233008 = "เสาหินที่ลาดเอียงเล็กน้อยเหมาะเป็นอย่างยิ่งที่จะเป็นตัวเชื่อมระหว่างหินที่มีรูปร่างแตกต่างกันอย่างมากมาย",
  str_item_intro_5233009 = "ด้วยยอดที่แหลมคมและรูปร่างโดยรวมที่เพรียว เสาหินนี้ให้ความรู้สึกเย็นยะเยือก ควรหาหินที่เหมาะสมมาจับคู่กับมัน",
  str_item_intro_5233010 = "มีลักษณะเป็นเนินลาดเอียงและใช้เป็นแกนหลักของกลุ่มหินได้เช่นกัน",
  str_item_intro_5234001 = "โคมไฟถนนที่ให้ความสว่างยาวนานโดยใช้เทคโนโลยีอันยอดเยี่ยม ไฟเตี้ย ๆ นี้ส่องสว่างได้ในพื้นที่เล็ก ๆ เท่านั้น",
  str_item_intro_5234002 = "โคมไฟถนนที่อยู่บนเสา ความสูงของแหล่งกำเนิดแสงนี้ช่วยให้ส่องสว่างในระยะไกลได้",
  str_item_intro_5234007 = "ชั้นวางดอกไม้ทรงสูงทำให้ผู้คนชมดอกไม้บานได้จากระยะไกล",
  str_item_intro_5234009 = "ด้วยป้ายบอกทางจำนวนมากที่ตอกตะปูอยู่บนเสา ป้ายไม้นี้ช่วยให้คนไม่หลงทางในสวนลอยฟ้า เพียงแค่มั่นใจว่าวางป้ายนี้ไว้ในตำแหน่งที่ถูกต้อง!",
  str_item_intro_5234011 = "ร่มที่ให้ร่มเงาได้อย่างเพียงพอ ข้อเสียของมันคือหนักไปหน่อยและถือยาก",
  str_item_intro_5234012 = "ดอกไม้ที่ตั้งชื่อตามดวงอาทิตย์ ลำต้นสูงและดอกขนาดใหญ่ทำให้มันดูเหมือนเย่อหยิ่ง บางคนเชื่อว่าดอกไม้นี้เป็นสัญลักษณ์ของ \"หัวใจที่แสวงหาแสงสว่าง\"",
  str_item_intro_5234013 = "เป็นพื้นยกระดับที่ก่อขึ้นด้วยหิน ใช้สำหรับปลูกดอกไม้ต่าง ๆ โดยเฉพาะ",
  str_item_intro_5234014 = "ชั้นวางดอกไม้ทรงเตี้ย เหมาะสำหรับประดับริมทางเดินและหน้าประตู",
  str_item_intro_5234018 = "เต็นท์แบบนอนได้คนเดียวที่ใช้ในป่า รูปทรงกรวยช่วยให้เต็นท์สูงเพียงพอ ติดตั้งง่าย แต่เล็กมากจนรองรับได้เพียงคนเดียว",
  str_item_intro_5234019 = "ผ้าปูโต๊ะที่มีอาหารทุกประเภท ดูเหมือนว่าคุณจะได้อิ่มหนำกับอาหารมื้ออร่อยในป่า",
  str_item_intro_5234020 = "เตาที่ทนทานและทนความร้อน ช่องว่างในฐานช่วยให้รับอากาศได้ดี จึงมีเปลวไฟขนาดใหญ่ที่ปล่อยความร้อนสูง",
  str_item_intro_5234023 = "แม้แต่วัชพืชก็ไม่ควรสิ้นเปลือง รวบรวมไว้ตอนนี้เผื่อได้ใช้ในภายหลัง",
  str_item_intro_5234024 = "ลังขนาดใหญ่ที่ทำจากไม้กระดาน แปรรูปง่าย เหมาะมากสำหรับใช้เก็บวัสดุ",
  str_item_intro_5234025 = "ลังไม้หลายใบที่วางซ้อนกัน เมื่อเห็นก็รู้ได้ทันทีว่านี่คือคลังสินค้า",
  str_item_intro_5234037 = "เตาแคมป์ไฟที่สร้างด้วยหิน เหมาะสำหรับก่อไฟในป่า",
  str_item_intro_5234038 = "สมอที่กู้ขึ้นมาจากก้นทะเล แข็งแกร่งและทนทานมาก ราวกับจะยึดเรือลำใหญ่ไว้กับที่ได้แม้ว่าคลื่นจะรุนแรง น่าเสียดายที่มันได้แต่รออย่างนิ่งเงียบให้ใครสักคนมาใช้งาน เพราะเจ้าของตัวจริงได้หายตัวไปแล้ว",
  str_item_intro_5234039 = "กระดานโต้คลื่นนี้ขับเคลื่อนด้วยลูกคลื่น ซึ่งผู้ใช้งานจะเคลื่อนที่ไปได้ตามต้องการบนผืนน้ำและเล่นท่าทางต่าง ๆ ได้ด้วย น่าเสียดายอยู่นะที่เอามาไว้ในสวนลอยฟ้า...",
  str_item_intro_5241002 = "ชิงช้าที่แกว่งไปมาเล็กน้อยเมื่อนั่งลงไป ระวังอย่าแกว่งสูงเกินไป! บางคนชอบมานั่งหลับที่นี่ การแกว่งไปมาทำให้ง่วงนอนได้เร็วจริง ๆ",
  str_item_intro_5241003 = "ของเล่นที่ให้ความรู้สึกเหมือนกับการขี่จริงเล็กน้อย ว่ากันว่าใช้ฝึกการทรงตัวได้",
  str_item_intro_5241004 = "การเล่นว่าวเป็นกิจกรรมที่ดีในวันที่อากาศแจ่มใสและมีลมแรง หลังจากว่าวขึ้นไปบนฟ้า ถ้าผูกเชือกว่าวไว้กับชั้นวาง ว่าวก็จะไม่ปลิวไป",
  str_item_intro_5241005 = "ขาตั้งน้ำหนักเบาที่ออกแบบมาสำหรับการวาดภาพกลางแจ้ง มีมุมและขนาดที่เหมาะสมที่จะทำให้คุณจดจ่อขณะวาดภาพ",
  str_item_intro_5241006 = "เวทีและลำโพงถูกจัดวางอย่างพิถีพิถันเพื่อให้ผู้ชมได้เพลิดเพลินกับการแสดงจากทุกมุม ว่ากันว่าโรงละครแห่งนี้ยังมีเทคโนโลยีที่ยอดเยี่ยม ซึ่งบางครั้งก็แสดงเอฟเฟกต์พิเศษมากมายให้กับรายการต่าง ๆ",
  str_item_intro_5241007 = "ว่ากันว่ารูปปั้นนี้สร้างขึ้นเพื่อรำลึกถึงหญิงชาวเคเลสไทต์ที่ได้ไปเยือนภูเขาและแม่น้ำที่มีชื่อเสียงทั้งหมดในทวีป แต่ไม่มีใครจำชื่อเธอได้แล้ว และรูปปั้นนี้ก็เหลือไว้ให้คนรุ่นหลังได้จดจำ",
  str_item_intro_5241008 = "ทุกครั้งถ้าได้เห็นทีไร คุณจะอยากชกมันสักสองสามครั้ง... แต่ยังไงก็ไม่มีวันล้มมันลงได้ ซึ่งก็ออกจะน่าผิดหวัง แต่ก็เป็นการระบายความแค้นที่สะใจดี",
  str_item_intro_5241016 = "ซุ้มทางเดินขนาดใหญ่ มีเสาคล้ายกับกระดูกของสิ่งมีชีวิตโบราณ... บางคนบอกว่าที่จริงมันเป็นโครงร่างสำคัญของโคลอสซัส",
  str_item_intro_5242101 = "แม้ว่าภายนอกจะดูแปลกตา แต่โครงสร้างที่เป็นเอกลักษณ์ช่วยให้ภายในห้องมีแสงและอากาศเพียงพอ ทำให้พักอาศัยได้",
  str_item_intro_5243001 = "ผืนดินอุดมสมบูรณ์ที่ให้สารอาหารเพียงพอสำหรับพืชทุกชนิด",
  str_item_intro_5234008 = "หัวของหุ่นไล่กาตัวนี้ทำจากผ้า ถ้ามองดูใกล้ ๆ จะเห็นว่าใบหน้ามีตกกระเยอะมาก ว่ากันว่าหน้าตาแบบนี้ทำให้หุ่นไล่กาใช้ได้ผลมากขึ้น!",
  str_item_intro_5234015 = "หนึ่งภาพมีค่ากว่าพันคำพูด แค่เห็นป้ายไม้นี้ก็เข้าใจความหมายได้ว่า: \"กรุณาอย่าทำร้ายแพ็งกาโล!\"",
  str_item_intro_5234016 = "เครื่องมือที่ใช้บอกเวลาได้จากการฉายแสงของแสงอาทิตย์ ซึ่งใช้เป็นนาฬิกาในยุคแรกเริ่ม ข้อเสียก็คือนาฬิกาแดดไม่สามารถใช้งานได้ในวันที่มีเมฆมาก ฝนตก หรือในช่วงเวลากลางคืน",
  str_item_intro_5234017 = "อุปกรณ์ที่ใช้บอกทิศทางลมนี้มีความละเอียดอ่อนมาก แม้แต่ลมที่พัดบางเบาก็ยังวัดได้อย่างแม่นยำ ถ้าลมแรงเกินไปและเปลี่ยนทิศทางบ่อย ก็อย่าลืมนำลงมานะ! ไม่งั้นมันจะหมุนเร็วเกินไปและหักได้",
  str_item_intro_5234026 = "เครื่องโม่หินที่ต้องลงมือลงแรงอย่างมาก ว่ากันว่าเคยใช้บดแป้งในยุคโบราณ ตอนนี้กลายเป็นเครื่องมือที่ใช้งานลำบากและขาดประสิทธิภาพไปแล้ว แต่จะใช้ออกกำลังกายเป็นบางครั้งคราวเพื่อสร้างความแข็งแกร่งก็ยังได้",
  str_item_intro_5234027 = "ถังไม้ที่มีน้ำหนักเบาแต่แข็งแรง มือจับเป็นแบบกันลื่น คนจึงไม่ค่อยทำหล่นและเสียแรงเปล่า",
  str_item_intro_5234028 = "แม้จะทำจากเซรามิก แต่บริเวณขอบได้รับการเสริมความแข็งแกร่ง จึงทนทานต่อการตกหล่นและกระแทก ทั้งยังมีมือจับช่วยในการหยิบยกอีกด้วย",
  str_item_intro_5234029 = "เครื่องจักรที่ใช้ปั่นด้ายและทอผ้าได้ด้วยตัวคนเดียว ข้อเสียคือการซ่อมบำรุงที่ยุ่งยากไปหน่อย...",
  str_item_intro_5234030 = "กระถางหญ้าเขียวชอุ่ม มีน้ำหนักมากและต้องออกพลังกล้ามในการเคลื่อนย้าย",
  str_item_intro_5234033 = "ระแนงไม้ที่มีเถาวัลย์ปกคลุม ให้ร่มเงาได้ในฤดูร้อนและยังคงเขียวขจีแม้ในช่วงปลายฤดูใบไม้ร่วง",
  str_item_intro_5234036 = "แปลงดอกไม้ที่เป็นหินสามชั้นซ้อนกัน นอกจากช่วยให้ดอกไม้ชั้นบนโดดเด่นสะดุดตาแล้ว สองชั้นข้างล่างยังปลูกหญ้าสีเขียวให้ตัดกับสีของดอกไม้ได้อีกด้วย",
  str_item_intro_5241015 = "เครื่องเล่นที่สามารถเล่นแผ่นบันทึกเสียงที่วางลงไป ลำโพงขยายเสียงทำให้มันส่งเสียงเพลงไปได้ไกล โดยมีเสียงดังกังวานเป็นเวลานาน",
  str_item_intro_5241017 = "อควาเรียม",
  str_item_intro_5251001 = "หอคอยไฮยาซินท์",
  str_item_intro_5252001 = "พิพิธภัณฑ์",
  str_item_intro_5253001 = "ร้านค้า",
  str_item_intro_5254001 = "น้ำพุแห่งความหวัง",
  str_item_intro_5255001 = "กล่องขนาดใหญ่ที่แข็งแกร่ง กันน้ำและกันฝุ่น สามารถเก็บของได้หลายชิ้น",
  str_item_intro_5256001 = "การผจญภัยกับเพื่อนของเราเต็มไปด้วยความท้าทาย ความตื่นเต้น ความสุขและเสียงหัวเราะมากมาย เพื่อรำลึกถึงช่วงเวลาที่น่าจดจำเหล่านี้ระหว่างการเดินทางของเรา เพื่อนๆ ของเราได้ทำป้ายเหล่านี้และนำมาไว้ที่นี่เพื่อเป็นรางวัลสำหรับชาว Caelestites และตัวพวกเขาเอง และเพื่อเป็นความทรงจำ",
  str_item_intro_5270001 = "แปลงเพาะพันธุ์",
  str_item_intro_5275001 = "เพื่อความรักและความหวัง มาเผยแพร่เพลงของเราไปทั่วทั้งทวีปกันเถอะ!\nเวทีนี้สร้างขึ้นเป็นพิเศษสำหรับการทัวร์คอนเสิร์ต—มีฟังก์ชันหลากหลาย สามารถสร้างได้ในเวลาไม่นาน ทั้งยังแข็งแรงมาก สามารถรับการร้องและการเต้นรำทุกรูปแบบบนพื้นผิวแข็งได้",
  str_item_intro_5275002 = "จังหวะไม่กี่จังหวะก็ช่วยเพิ่มบรรยากาศพิเศษให้กับการแสดงได้แล้ว! หากคุณเชื่อว่าวงดนตรีต้องมีผู้นำโดยธรรมชาติ คุณจะต้องเป็นมือกลอง นั่นเป็นเหตุผลว่าทำไมสิ่งนี้จึงจำเป็นสำหรับทุกระยะการเดินทาง",
  str_item_intro_5275003 = "แม้แต่เพลงเต้นรำก็ต้องการความรู้ด้านการประพันธ์ดนตรี และด้วยคีย์บอร์ดที่ใช้งานง่ายนี้ พร้อมเสียงและเอฟเฟ็กต์ที่หลากหลาย เครื่องเล่นคีย์บอร์ดที่ดีก็สามารถกลายเป็นเครื่องผลิตเพลงเดี่ยวได้",
  str_item_intro_5275004 = "ขอพรจากดวงดาว! ไม่มีใครรู้ว่าข่าวลือนี้เริ่มแพร่กระจายในหมู่แฟน ๆ ของไอดอลตั้งแต่เมื่อไหร่ แต่เห็นได้ชัดว่าเมื่อคุณขอพรจากการตกแต่งรูปดาวเช่นนี้ กำลังใจจากใจของคุณจะถูกส่งตรงไปยังไอดอลที่คุณชื่นชอบ!",
  str_item_intro_5275005 = "หากคุณต้องการเชียร์ไอดอลคนโปรด คุณจะต้องมีสินค้าอย่างเป็นทางการเพื่อโบกมือให้กลางอากาศ ดังนั้นการวางโต๊ะแบบนี้ไว้ใกล้เวทีจึงสมเหตุสมผล—วิธีนี้ทำให้แฟนๆ จับมือได้ทุกชนิด ของผู้สนับสนุนในยามที่พวกเขาต้องการมากที่สุด",
  str_item_intro_5275006 = "ทัวร์ส่วนใหญ่จำเป็นต้องเตรียมกีตาร์ไว้ล่วงหน้าหลายรุ่น ขาตั้งกีตาร์นี้ไม่เพียงแต่ช่วยให้นักกีตาร์เลือกกีตาร์ที่เหมาะกับสไตล์ของพวกเขาเท่านั้น แต่ยังช่วยให้นักกีตาร์หลายคนเสียบปลั๊กและเล่นพร้อมกันได้ เพิ่มระดับความตื่นเต้นให้กับการแสดงทุกประเภท",
  str_item_intro_5275007 = "อุปกรณ์ขยายสัญญาณประเภทนี้ขาดไม่ได้สำหรับศิลปินที่ออกทัวร์ ไม่ว่าสถานที่จะใหญ่แค่ไหน และไม่ว่าผู้ชมจะเยอะแค่ไหน สิ่งนี้จะทำให้ทุกคนได้ยินเสียงของไอดอล... และยังน่ารักมากอีกด้วย!",
  str_item_intro_5275008 = "ของตกแต่งเหล่านี้มักจะวางไว้ใกล้กับสถานที่ท่องเที่ยว เมื่อคุณเห็นพวกเขาลอยอยู่บนท้องฟ้าและบินไปในสายลม คุณอดไม่ได้ที่จะรู้สึกว่าพวกเขากำลังเต้นรำกับไอดอลที่นับถือของพวกเขาจริงๆ",
  str_item_intro_5275009 = "ไฟประดับเหล่านี้มักพบใกล้เวทีทัวร์คอนเสิร์ต และดูเหมือนว่าแฟนๆ จะใช้ไฟเพื่อเชียร์ไอดอลของพวกเขา แม้ว่าพวกเขาจะไม่ใช่สินค้าทางการ แต่ก็ทำออกมาได้ดีอย่างน่าประหลาดใจ",
  str_item_intro_5275010 = "ทัวร์จะสมบูรณ์ได้อย่างไรถ้าไม่มีไอดอล? แม้ว่าคุณจะไม่สามารถถ่ายรูปกับไอดอลของคุณหรือแม้แต่เห็นไอดอลของคุณอย่างใกล้ชิด ตราบใดที่คุณมีสิ่งนี้ คุณก็รับประกันได้ว่าคุณจะได้ภาพเซลฟี่ที่ดี",
  str_item_intro_5275011 = "ดอกไม้เป็นตัวแทนของความปรารถนาแห่งความสุข ดังนั้น โดยธรรมชาติ ดอกไม้หลายชนิดจึงเป็นตัวแทนของความปรารถนาแห่งความสุขมากมาย หากคุณไม่ระวัง สถานที่ทัวร์ทั้งหมดอาจเต็มไปด้วยกระเช้าดอกไม้ที่ส่งโดยแฟน ๆ ที่กระตือรือร้นที่ต้องการความสุขให้กับไอดอลที่พวกเขาชื่นชอบ",
  str_item_intro_5275012 = "เห็นได้ชัดว่าดาวที่ประดับอยู่บนผนังนี้ถูกติดด้วยพัดลมทีละตัว นี่ไม่ใช่แค่การตกแต่งเท่านั้น แต่นี่คือข้อพิสูจน์ถึงความทุ่มเทของฐานแฟนคลับ ซึ่งเป็นสัญลักษณ์ของความหวังอย่างจริงใจว่าไอดอลของพวกเขาจะประสบความสำเร็จในการทัวร์",
  str_item_intro_5275013 = "ที่นั่งเหล่านี้จัดไว้เป็นพิเศษสำหรับการทัวร์ แม้ว่าแฟนๆ หลายคนจะชอบยืนบนพวกเขาเพื่อให้กำลังใจไอดอลมากกว่านั่งบนนั้น มีอีกเหตุผลหนึ่งที่แฟนๆ ยืนบนเก้าอี้เหล่านี้ แน่นอนว่าเพื่อให้ไอดอลของพวกเขาเห็นพวกเขาท่ามกลางฝูงชน",
  str_item_intro_5234043 = "เนื่องจากหิมะนุ่มมาก ทำไมไม่ทำโซฟาล่ะ?\nบางทีหลายคนอาจมีความคิดนี้มาก่อน แน่นอนว่าโซฟาตัวนี้ทำมาจากวัสดุธรรมดา เพียงแต่ว่าด้านหลังดูเหมือนภูเขาหิมะ และด้วยเบาะนุ่มๆ มันทำให้คุณรู้สึกเหมือนกำลังนอนอยู่บนหิมะจริงๆ",
  str_item_intro_5234044 = "ตำนานเล่าว่าสิ่งมีชีวิตที่ไม่ธรรมดานี้ไม่มีวันแก่ และการจัดแสดงที่ยอดเยี่ยมนี้สะท้อนถึงแก่นแท้ของตำนานนั้น หากคุณจ้องมันสักพัก คุณอาจพบว่าตัวเองกำลังเสพติดมัน",
  str_item_intro_5234045 = "Courier Union นำพาความคิดและความปรารถนาของโลกไปจนถึงจุดจบของ Astra! กล่าวกันว่ากล่องจดหมายนี้ถูกสร้างขึ้นเป็นพิเศษเพื่อจุดประสงค์นี้ ช่วยลดระยะห่างระหว่างบุคคลอันเป็นที่รัก",
  str_item_intro_5234046 = "ถ้ามีอะไรที่คุณไม่กล้าพูดต่อหน้าใคร ให้เขียนเป็นจดหมายแล้ววางไว้ที่นี่ บางคนอาจเพียงแค่เห็นมันและเรียนรู้ว่าคุณรู้สึกอย่างไร",
  str_item_intro_5276001 = "สถานที่จัดพิธีนี้มักจะจัดขึ้นในวันไหว้พระจันทร์ เหมาะมากสำหรับจัดงานต่างๆ โดยเฉพาะงานแต่งงาน",
  str_item_intro_5276002 = "ไม่ว่าจะเป็นขบวนพาเหรดในเทศกาลหรืองานแต่งงาน นี่จะเป็นตัวเลือกที่ดีที่สุดสำหรับสไตล์ การตกแต่ง และความสะดวกสบาย",
  str_item_intro_5276003 = "สิ่งประดิษฐ์ใหม่ที่สนุกสนาน หากคู่รักยังคงดูแลกันและกันหลังจากไปเดินเล่นนั่นก็แสดงว่าพวกเขารักกันมากแค่ไหน",
  str_item_intro_5276004 = "ดอกกุหลาบบนศาลาแห่งนี้ได้รับการปลูกขึ้นเป็นพิเศษสำหรับเทศกาลนี้ และจะบานในวันไหว้พระจันทร์เพื่ออวยพรคู่บ่าวสาวที่มาที่นี่เท่านั้น",
  str_item_intro_5276005 = "ช็อกโกแลตมีรสขมที่ฐาน และจะหวานก็ต่อเมื่อเติมน้ำตาลเท่านั้น บางที... นี่อาจเป็นสัญลักษณ์ว่าความรักเป็นอย่างไร? ไม่ว่าในกรณีใด มันได้กลายเป็นหนึ่งในของขวัญเชิงสัญลักษณ์ของวันไหว้พระจันทร์ อาจเป็นเพราะคนส่วนใหญ่จดจำแต่ความหวานและไม่สนใจความขมขื่น",
  str_item_intro_5276006 = "ซุ้มประตูที่มีรูปทรงเป็นเอกลักษณ์นี้ประดับด้วยดอกไม้หลากสี เหมาะมากสำหรับคู่รักใหม่ที่จะมาถ่ายรูปหรือขอพรใต้ร่มไม้",
  str_item_intro_5276007 = "ของตกแต่งที่มักใช้ในวัน Mooncrown ประกอบด้วยแก้วทรงสูงหลายใบที่ใส่เครื่องดื่ม ใช้สำหรับรับรองแขกโดยเฉพาะ",
  str_item_intro_5276008 = "รูปทรงสูงของเชิงเทียนนี้ดูสบายตาและสามารถกระจายแสงที่ปล่อยออกมาจากเทียนได้อย่างสม่ำเสมอ เพิ่มความโรแมนติกให้กับงานแต่งงานที่นุ่มนวล",
  str_item_intro_5276009 = "เป็นที่รักของบ่าวสาวทุกคน อุปกรณ์นี้ช่วยให้แขกทุกคนที่มาร่วมงานได้ยินคำสาบานของคู่บ่าวสาวอย่างชัดเจน และยังสามารถเปิดเพลงเพื่อให้บรรยากาศสมบูรณ์แบบ",
  str_item_intro_5276010 = "เหมาะสำหรับคู่รักที่นั่งแม้ว่าจะไม่ใช่วันไหว้พระจันทร์ก็ตาม เกือบจะรับประกันได้ว่าจะถูกครอบครองในวัน Mooncrown",
  str_item_intro_5276011 = "ฮะ? พวกเขาเป็นคู่? อา มันเป็นแค่ชุดพิเศษที่ทำขึ้นสำหรับเทศกาล เหมาะสมกับกาลเทศะจริงๆ",
  str_item_intro_5276012 = "เหมาะสำหรับวันไหว้พระจันทร์เป็นทั้งของประดับตกแต่งและมอบเป็นของขวัญแก่ผู้อื่น ทำให้การเฉลิมฉลองมีสีสันและเติมอากาศด้วยกลิ่นหอมอ่อนๆ",
  str_item_intro_5276013 = "พรมทำจากกลีบกุหลาบ! บ่งบอกถึงความจริงจังของเจ้าภาพในพิธี เมื่อคู่บ่าวสาวก้าวเข้าสู่พิธี สายตาของแขกทุกคนที่มาร่วมงานจะมองมาทางพวกเขา",
  str_item_intro_5276101 = "โต๊ะพร้อมเก้าอี้ที่เข้าชุดกันซึ่งมีดีไซน์วินเทจที่แปลกตา ซึ่งโชคดีที่ยังนั่งสบายมาก และดูเหมือนจะเหมาะสำหรับการประชุมบางงาน โดยเฉพาะอย่างยิ่งเมื่อต้องหารือเกี่ยวกับกรณีที่ซับซ้อน บางทีแนวโน้มนี้อาจเป็นอิทธิพลของนักสืบที่มีชื่อเสียงบางคน",
  str_item_intro_5276102 = "พวกเขากล่าวว่านักสืบที่มีชื่อเสียงมักจะรวบรวมข้อมูล จัดระเบียบเบาะแส และทำการวิเคราะห์ต่างๆ บนกระดานประเภทนี้ แม้จะอาศัยวิธีการนี้เพียงอย่างเดียวในการหาตัวผู้กระทำผิด",
  str_item_intro_5276103 = "ตั้งแต่นักสืบชื่อดังคนนั้นมีชื่อเสียงโด่งดัง ยานพาหนะที่เขาเลือกก็ได้รับความนิยมเพิ่มขึ้นเช่นกัน ท้ายที่สุดแล้ว ใครจะไม่สนุกกับยานพาหนะที่ทนทาน รวดเร็ว และควบคุมง่ายเช่นนี้",
  str_item_intro_5276104 = "ถ้าจิตใจคุณรู้สึกปิดกั้น ให้ดื่มกาแฟสักแก้ว ถ้ายังคิดไม่ออกอีกถ้วย ในฐานะคู่หูที่ดีที่สุดสำหรับการครุ่นคิด นักสืบชื่อดังไม่เคยตระหนี่เมื่อต้องเลือกชุดกาแฟ",
  str_item_intro_5276105 = "อาชญากรรมมักจะเกิดขึ้นในคืนที่หนาวเย็น นักสืบที่เก่งกาจจึงจำเป็นต้องสวมเสื้อโค้ทและหมวกกันลม สิ่งนี้ทำให้ชั้นวางเสื้อโค้ทนี้เป็นสิ่งจำเป็นในภูมิลำเนาของนักสืบทุกคน",
  str_item_intro_5276106 = "รถเข็นขนาดเล็กน้ำหนักเบาสำหรับวางกาแฟ เครื่องดื่ม และของอื่นๆ สำหรับน้ำชายามบ่ายเป็นส่วนใหญ่ เมื่อเลี้ยงรับรองแขก จะสะดวกอย่างยิ่งสำหรับคนรับใช้ในการจัดรายการอาหารต่างๆ ให้ทันท่วงที",
  str_item_intro_5276107 = "เมื่อแรงบันดาลใจแบบนิรนัยของเขาเหือดแห้งไป หรือเขาติดอยู่ในวังวนแห่งความคิด นักสืบชื่อดังชอบที่จะใช้เครื่องมือนี้เพื่อผ่อนคลาย เติมเต็มทั้งถนนด้วยเสียงของเรื่องแย่ๆ ของเขา โชคดีที่สิ่งที่ผู้คนสนใจไม่ใช่ระดับความสามารถทางดนตรีของเขา แต่เป็นความหลงใหลที่มีต่อตำนานนักสืบผู้ยิ่งใหญ่ นี่คือเหตุผลที่ผู้คนจำนวนมากแห่กันซื้อเครื่องดนตรีนี้",
  str_item_intro_5276108 = "พนักพิงสูงและเบาะนุ่มให้ความสบายสูงสุดในขณะที่ช่วยรักษาท่าทางการนั่งที่ดี เหมาะอย่างยิ่งสำหรับนักสืบที่ชอบพักผ่อนและครุ่นคิด",
  str_item_intro_5276109 = "ชั้นวางที่ออกแบบมาอย่างมีเอกลักษณ์นี้สามารถรองรับท่อจำนวนมากและนำความรู้สึกนักสืบที่แท้จริงมาสู่บ้านของคุณ แน่นอนว่าทั้งหมดนี้เป็นเพราะความนิยมของนักสืบชื่อดังในหมู่แฟนนิยายอาชญากรรม ดังนั้นแม้แต่ผู้ที่ไม่สูบบุหรี่ก็สามารถซื้อมาประดับได้",
  str_item_intro_5276110 = "\"อย่าปล่อยให้เงื่อนงำเดียวหลุดจากคุณ!\" ครั้งแล้วครั้งเล่า รายละเอียดที่เล็กที่สุดจะเปิดเผยความจริง แว่นขยายแบบนี้เป็นอุปกรณ์มาตรฐานของนักสืบชื่อดังที่ขาดไม่ได้",
  str_item_intro_5276111 = "โคมไฟกันลมและน้ำหนักเบาพร้อมความสว่างและอายุการใช้งานที่เหนือกว่า ถือได้ง่ายด้วยมือข้างเดียว โดยธรรมชาติแล้วสามารถวางบนพื้นได้เช่นกัน",
  str_item_intro_5276112 = "กระดานดำขนาดเล็กนี้มีความสูงค่อนข้างต่ำ แม้แต่ตอนที่นักสืบชื่อดังนั่งอยู่บนเก้าอี้เท้าแขน เขาก็สามารถใช้มันเพื่อจัดระเบียบคดีปัจจุบันของเขาได้ ทำให้เป็นตัวช่วยที่มีประโยชน์สำหรับการวิเคราะห์อย่างรวดเร็ว",
  str_item_intro_5276113 = "รูปร่างของที่ยึดหนังสือแบบสองขานี้ค่อนข้างพิเศษ แต่ก็เป็นที่นิยมในหมู่นักสืบที่มีชื่อเสียงบางคน ความสวยงามของที่คั่นหนังสือของเขาแตกต่างจากคนอื่นๆ ทั่วไป แน่นอน ในฐานะผู้ที่ชื่นชอบนักสืบ คุณควรมีติดบ้านไว้สักคู่",
  str_item_intro_5276114 = "ไม่ว่าฝนจะตกหรือแดดออก ร่มก็เป็นเกราะกำบังที่ดีเสมอ และใช้เป็นอาวุธได้ในยามฉุกเฉิน ดังนั้นการวางตะกร้าใส่ร่มแบบนี้ไว้ที่ประตูจึงดูจำเป็นสำหรับการจัดเก็บร่มทั้งหมด",
  str_item_intro_5234047 = "\"เมื่อนักเขียนถูกพายุหิมะขังอยู่ในคฤหาสน์บนภูเขา ประสิทธิภาพการเขียนของพวกเขาจะเพิ่มขึ้นเป็นสิบเท่า\" สิ่งนี้ดูเหมือนจะเป็นความเชื่อร่วมกันในหมู่บรรณาธิการของ Umbraton และนำไปสู่ความนิยมของเครื่องพิมพ์ดีดยี่ห้อนี้ ซึ่งชั่วระยะเวลาหนึ่งกลายเป็นเครื่องพิมพ์ดีดที่นักเขียนของเมืองนี้เลือกใช้",
  str_item_intro_5234048 = "โซฟานี้เป็นสิ่งจำเป็นหากคุณต้องการเปิดบริษัทที่ยิ่งใหญ่ใน Umbraton กรรมการจะนั่งบนโซฟานี้เพื่อเข้าร่วมธุรกิจของพวกเขา",
  str_item_intro_5223003 = "กระเบื้องปูพื้นทรงกลมขนาดเล็กเหมาะสำหรับปูสนามหญ้าและตกแต่งริมถนน",
  str_item_intro_5223004 = "กระเบื้องปูพื้นทรงกลมขนาดค่อนข้างใหญ่ที่นอกจากจะใช้ปูทางเดินแล้วยังสามารถใช้เป็นส่วนประกอบหลักในการปูถนนได้อีกด้วย",
  str_item_intro_5351001 = "นี่คือสิ่งปลูกสร้างที่เตะตาที่สุดและเป็นแลนด์มาร์กของสวนลอยฟ้า ข้างในเต็มไปด้วยข้อมูลเกี่ยวกับการสร้างสวนลอยฟ้าขึ้นใหม่",
  str_item_intro_5351002 = "นี่คือสิ่งปลูกสร้างที่เตะตาที่สุดและเป็นแลนด์มาร์กของสวนลอยฟ้า ข้างในเต็มไปด้วยข้อมูลเกี่ยวกับการสร้างสวนลอยฟ้าขึ้นใหม่",
  str_item_intro_5351003 = "นี่คือสิ่งปลูกสร้างที่เตะตาที่สุดและเป็นแลนด์มาร์กของสวนลอยฟ้า ข้างในเต็มไปด้วยข้อมูลเกี่ยวกับการสร้างสวนลอยฟ้าขึ้นใหม่",
  str_item_intro_5352001 = "สถานที่จัดแสดงวัตถุหลากหลายชนิด รวมทั้งเก็บบันทึกและเผยแพร่ความรู้",
  str_item_intro_5352002 = "ไม่เพียงแต่มีพื้นที่ใหญ่ขึ้นเท่านั้น ยังเพิ่มการตกแต่งเล็กน้อยเพื่อให้ชมนิทรรศการได้ง่ายขึ้นอีกด้วย",
  str_item_intro_5352003 = "พิพิธภัณฑ์ที่ปรับปรุงให้มีห้องต่าง ๆ เพิ่มขึ้นจากเดิมอีกมาก ไม่เพียงแต่มีพื้นที่มากเท่านั้น ยังรองรับการจัดแสดงหลากหลายประเภทอีกด้วย",
  str_item_intro_5353001 = "สถานที่ค้าขายในสวนลอยฟ้า ไม่ได้มีไว้ทำการค้าขายทั่วไปเท่านั้น แต่ยังรับคำสั่งซื้อลึกลับอีกด้วย!",
  str_item_intro_5353002 = "เพิ่มการตกแต่งภายนอกที่งดงาม ตอนนี้มันดูเก๋ไก๋ขึ้นมาก",
  str_item_intro_5353003 = "ร้านค้าที่มีห้องมากมาย เป็นคฤหาสน์สำหรับการค้าโดยเฉพาะไปแล้วในเวลานี้",
  str_item_intro_5354001 = "ดูน้ำพุใส ๆ นั่นสิ นอกจากดูปลาสวย ๆ ได้แล้ว ยังโยนเหรียญลงไปเพื่อขอพรได้อีกด้วย",
  str_item_intro_5354002 = "บ่อน้ำขนาดค่อนข้างใหญ่ มองเห็นปลาแหวกว่ายอยู่ใต้น้ำที่วาววับ และความฝันของคุณก็เหมือนจะเป็นจริงขึ้นมาได้",
  str_item_intro_5354003 = "น้ำพุไม่เพียงแต่สะอาดสดชื่นจนปลาอาศัยอยู่ได้ ยังช่วยทำให้ความปรารถนาของคุณเป็นจริงอีกด้วย",
  str_item_intro_5355001 = "กล่องขนาดใหญ่ที่แข็งแกร่ง กันน้ำและกันฝุ่น สามารถเก็บของได้หลายชิ้น",
  str_item_intro_5276201 = "ที่นั่งในราชสำนักมักจะประดับประดาโดยส่วนท้ายของขุนนางผู้สูงศักดิ์ที่สุดของลูโมโปลิส การออกแบบที่ฟุ่มเฟือยของมันฉายรัศมีของพฤติกรรมอันสูงส่งของชนชั้นสูงได้อย่างมีประสิทธิภาพ สร้างความเกรงขามแก่ประชาชนที่หย่อนยาน ในขณะที่บังคับให้ผู้ครอบครองต้องจำกัดพฤติกรรมของตนเองโดยไม่รู้ตัว แน่นอนว่าผู้ครอบครองรายนี้จำเป็นต้องมีนิสัยใจคอที่เหมาะสมตั้งแต่แรก",
  str_item_intro_5276202 = "\"โลกภายในโลก\" มีคนบอกว่าลูกแก้วนี้บรรจุวิญญาณของเมืองใดเมืองหนึ่ง แต่สำหรับบางคน ถือว่าเป็นความทรงจำที่มีค่ามาก",
  str_item_intro_5276203 = "\"จงมีเมตตาต่อผู้อ่อนแอและกล้าหาญเมื่อเผชิญกับการรุกราน\" อัศวินเป็นรากฐานที่สำคัญของ Lumopolis และยังเป็นธงของนครรัฐที่บินสูงในสายลมของโลก แม้ว่าชื่อของรูปปั้นนี้จะไม่เป็นที่รู้จัก แต่แม้แต่คนทั่วไปก็ยังรู้สึกได้ถึงจิตวิญญาณแห่งความกล้าหาญเมื่อพวกเขาเห็นรูปปั้นที่สูงตระหง่าน",
  str_item_intro_5276204 = "ตู้โชว์นี้ไม่เพียงแค่ดีไซน์ที่หรูหราเท่านั้น แต่ยังมีโครงสร้างที่แข็งแรง ทำให้ใช้งานได้จริงและสวยงามพอที่จะเก็บของสะสมต่างๆ ได้",
  str_item_intro_5234049 = "\"จารึกไว้บนแผ่นหิน คำพูดสามารถคงอยู่ได้เป็นพันปี\" นานหลังจากที่ช่างแกะสลักได้ละทิ้งขดลวดมรรตัยนี้ เมืองนี้ก็ถูกทิ้งร้าง อารยธรรมกลายเป็นฝุ่นผง แต่อนุสรณ์สถานแห่งนี้ยังคงตั้งตระหง่านอยู่ ให้คนรุ่นหลังได้เห็นโลกแห่งอดีต บางทีนี่อาจเป็นจุดประสงค์ของการมีอยู่ของมัน",
  str_item_intro_5276206 = "เครื่องใช้ทั่วไปในที่พักอาศัยอันสูงส่งของ Lumopolis ซึ่งมักใช้เป็นโต๊ะยาว กว้างขวาง มั่นคง และสง่างาม เหมาะสำหรับรับรองแขก เพื่อนฝูง สังสรรค์ในครอบครัว หรือแม้แต่พูดคุยเรื่องสำคัญ",
  str_item_intro_5276207 = "เก้าอี้พนักพิงสูงเหล่านี้พบได้ทั่วไปในคฤหาสน์อันสูงส่งของลูโมโปลิส มั่นใจในความสบายในขณะที่ช่วยรักษาท่าทางที่ดีขึ้น หลีกเลี่ยงข้อผิดพลาดที่อาจเกิดขึ้นได้ตลอดเวลา",
  str_item_intro_5276208 = "ธงขาวสำหรับเมืองสีขาว สัญลักษณ์ของ Lumopolis เมื่อจ้องมองไปก็ทำให้นึกถึงทุกสิ่งที่ทำให้เมืองนี้เป็นอย่างที่เป็น อัศวิน ขุนนาง ท้องฟ้าสีคราม และความรุ่งเรืองของอารยธรรม",
  str_item_intro_5276209 = "ในจิตสำนึกส่วนรวมของมวลชน นี่คือแสงที่ไม่มีวันดับ และต้องขอบคุณ Luminatics อันทรงพลังของ Lumopolis ที่ทำให้แสงนี้ไม่มีวันดับ",
  str_item_intro_5276210 = "รั้วเตี้ยอันสง่างามนี้ไม่ได้ออกแบบมาเพื่อป้องกันไม่ให้บุคคลภายนอกเข้ามา แต่เพื่อกำหนดขอบเขตของคฤหาสน์และที่ดินอันสูงส่ง",
  str_item_intro_5276211 = "แม้แต่ไม้กระถางแบบนี้ Lumopolis ก็โดดเด่นกว่าใครอื่น กระถางไม่เพียงแค่สูงและสวยงามเท่านั้น แต่ต้นไม้สีเขียวที่อยู่ภายในยังเขียวชอุ่มและสง่างามอีกด้วย ดูเหมือนว่าจะตั้งอยู่สูงเสียดฟ้า มันต้องดูดซับแสงแดดไว้มาก",
  str_item_intro_5276212 = "เถาวัลย์จำนวนมากแผ่กิ่งก้านสาขาเหนือศีรษะ แม้ว่าพวกมันจะคืบคลานไปในทิศทางที่กระจัดกระจาย แต่ก็มีความสม่ำเสมอในการจัดเรียงของพวกมัน ด้วยช่องว่างระหว่างพวกมันที่ไม่ใหญ่หรือเล็ก กลุ่มที่ไม่เบาบางหรือหนาแน่น ทำให้แสงแดดส่องเข้ามาอย่างสบาย ๆ โดยไม่ทำให้เกิดความลำบากใจอย่างกะทันหัน เมื่อมีลมอ่อนๆ พัดผ่าน ทำให้เป็นสถานที่ที่เหมาะสำหรับการพักผ่อนและเพลิดเพลินกับน้ำชายามบ่าย",
  str_item_intro_5234050 = "อาจไม่เทียบเท่ากับความงดงามของชิงช้าสวรรค์จริง ๆ แต่ก็ยังคงใหญ่อยู่ พวกเราไม่สามารถขึ้นไป แต่เราเพียงมองจากระยะไกลและรำลึกถึงความรู้สึกของการขี่ชิงช้าสวรรค์ในใจเรา",
  str_item_intro_5234052 = "ในทะเลทราย ฝาครอบสีน้ำเงินและถังน้ำขนาดใหญ่กลับกันเป็นสัญลักษณ์ของความขัดแย้งเป็นปรากฏกายศักดิ์สิทธิ์ พวกเขาทำให้ฝนตกและน้ำค้าง นำความสดชื่นให้ความโล่งใจแก่ผู้ที่หายใจไม่ออกเนื่องจากภัยแล้ง",
  str_item_intro_5234053 = "ปั้นจำลองที่สมจริงคล้ายกับนกที่อ่อนโยนที่ถูกปกคลุมด้วยทราย สามารถหลอกตาได้ง่าย ระวังอย่าให้มันชื้น เพราะมิฉะนั้นมันจะ \"หายไป\" กลายเป็นกองน้ำทราย",
  str_item_intro_5234054 = "ใครสามารถนั่งบนเก้าอี้นี้ได้จริง ๆ หรือไม่? ในขณะที่ดอกไม้เพิ่มความงาม หนามที่ปักอยู่บนที่นั่งเป็นการเตือนให้ \"นั่งตัวตรง หรือเสี่ยงเจอปัญหาหนามแหลม\"",
  str_item_intro_5400001 = "ของเหลวลึกลับที่ลดระยะเวลาการเพาะพันธุ์ของต้นไม้มหัศจรรย์ได้อย่างมาก ระเหยง่ายจึงต้องบรรจุขวด",
  str_item_intro_5400002 = "ของเหลวข้นเหนียวที่น่าจะทำจากส่วนผสมของน้ำเลี้ยงต้นไม้มหัศจรรย์คุณภาพพรีเมียม นำไปต้มและเติมสารอาหารสูตรลับพิเศษ สามารถเปลี่ยนสายพันธุ์ของต้นไม้มหัศจรรย์ได้\nลักษณะภายนอก: ของเหลวสีเขียวเข้มข้น มีกากตะกอนสีเหลือง",
