  str_item_intro_5421333 = "ต้นควินแลน III ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง ใบสากและไม่เรียบเสมอกัน ให้ความรู้สึกเย็นสบายและงดงาม",
