  str_item_intro_5421342 = "ต้นควินแลน III ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง ใบมีขอบแหลม ยื่นออกมาผิดปกติ เมื่อลมพัดผ่านยอดไม้จะดูคล้ายใบมีดที่แหลมคมกำลังร่ายรำ ให้ความรู้สึกถึงความเกรี้ยวกราด",
  str_item_intro_5421343 = "พันธุ์ล้ำค่าของต้นควินแลน มิสทรัล ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ใบไม้สีเหลืองอ่อนทำให้ออร่าเย็นชาที่เคยมีนั้นอ่อนลงและนำมาซึ่งความอบอุ่น",
  str_item_intro_5421411 = "พันธุ์หายากของต้นควินแลน ซันเกซซิ่ง ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีน้ำเงินของต้นไม้นั้นดูคล้ายผู้มีใจบริสุทธิ์ที่กำลังแหงนมองดูฟ้าสีครามและสวดอธิษฐาน ดังนั้นจึงเรียกอีกอย่างว่า \"ต้นควินแลนอธิษฐาน\"",
  str_item_intro_5421412 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน รูปร่างเหมือนแตรที่หงายขึ้นสู่ท้องฟ้า มียอดขนาดใหญ่ตั้งอยู่บนลำต้นเรียวบาง ที่เป็นอย่างนี้ได้ คงเป็นฝีมือของพลังงานลึกลับเป็นแน่",
  str_item_intro_5421413 = "พันธุ์หายากของต้นควินแลน ซันเกซซิ่ง ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดรูปแตรสีเหลืองดูเหมือนเขาทองเหลือง ว่ากันว่าในสมัยโบราณ ยักษ์ถึงกับใช้เล่นดนตรี! ด้วยเหตุนี้จึงมีอีกชื่อหนึ่งว่า \"ต้นควินแลนเขาสัตว์\"",
  str_item_intro_5421421 = "พันธุ์หายากของต้นควินแลน โมโนลิธ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เมื่อยืนอยู่บนยอดสีเขียวของต้นไม้ คุณจะรู้สึกคล้ายว่ากำลังอยู่บนเนินเขา จึงถูกเรียกอีกอย่างว่า \"ต้นควินแลนเนินเขา\"",
  str_item_intro_5421422 = "พันธุ์หายากของต้นควินแลน โมโนลิธ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีขาวดูเรียบเนียนมาก และคุณยังสามารถนอนหลับบนนั้นได้อย่างสบายอีกด้วย",
  str_item_intro_5421423 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน ยอดไม้กลายเป็นแท่นหินไปแล้ว! ว่ากันว่าใจกลางลำต้นมีเสาหินซ่อนอยู่ ส่วนภายนอกเป็นเปลือกไม้หนาหุ้มไว้... มีการหารือกันว่ามันยังถือว่าเป็นพืชได้อีกหรือไม่",
  str_item_intro_5421431 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน ใบมีลักษณะเป็นใย อ่อนนุ่ม ละเอียดและพันกัน ดูเหมือนวิญญาณกระพือปีกที่บันทึกไว้ในตำนาน บางคนบอกว่าไม้พันธุ์นี้มีจิตสำนึกและแม้กระทั่งจิตวิญญาณในตัวเอง...",
  str_item_intro_5421432 = "พันธุ์หายากของต้นควินแลน ไซค์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีแดงดูเป็นลางไม่ดี แต่มีแรงดึงดูด เมื่อใบไม้ที่อ่อนโยนเหล่านั้นเต้นรำไปกับสายลม ก็ง่ายมากที่จะรู้สึกตื่นตาตื่นใจและมองดูได้ทั้งวันทั้งคืน",
  str_item_intro_5421433 = "พันธุ์หายากของต้นควินแลน ไซค์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ใบไม้สีเหลืองเรียงตัวเป็นเส้นเล็ก ๆ จำนวนมากแกว่งไกวไปมาบนยอดต้นไม้ราวกับกำลังต้อนรับใครสักคน จึงมีชื่อเล่นว่า \"ต้นควินแลนต้อนรับ\"",
  str_item_intro_5421441 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน ใบไม้ชิดติดกันจนเป็นซุ้มขนาดใหญ่หนาทึบ บ้างครั้งก็มีใบไม้ร่วงหล่นปลิวว่อนดูคล้ายกับฝนใบไม้ร่วง",
  str_item_intro_5421442 = "พันธุ์หายากของต้นควินแลน บลูมมิ่ง ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดไม้สีเขียวดูมีชีวิตชีวา หากคุณเข้าใกล้กิ่งก้านที่ห้อยย้อย มันจะสั่นไหวเล็กน้อย และต้นไม้ทั้งต้นก็จะส่งเสียงกรอบแกรบเหมือนกำลังตอบสนองต่อใครบางคน...",
  str_item_intro_5421443 = "พันธุ์หายากของต้นควินแลน บลูมมิ่ง ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เมื่อใบไม้สีน้ำเงินร่วงหล่นทับกัน ก็บังเกิดภาพที่ดูราวกับแม่น้ำหรือทะเล จึงมีชื่อเรียกอีกอย่างว่า \"ต้นควินแลนทะเลบนบก\"",
  str_item_intro_5421451 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์แบบซับซ้อน ต้นไม้ชนิดนี้หายากและแข็งแรงมาก ลือกันว่ามันเติบโตต่อได้แม้หลังจากที่ถูกตัดแล้ว สมกับชื่อของมัน",
  str_item_intro_5421452 = "ต้นควินแลน อันยีลดิ้งสายพันธุ์หายากที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ใบสีน้ำตาลของมันทำให้รู้สึกว่านี่เป็นต้นไม้แก่ แต่ที่จริงแล้วมันมีชีวิตชีวามาก ว่ากันว่ามันอยู่รอดได้แม้ไม่มีน้ำ",
  str_item_intro_5421453 = "ต้นควินแลน อันยีลดิ้งสายพันธุ์หายากที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ มันโตเร็วมากจนซุ้มยอดไม้สีน้ำเงินแทบจะเกิดขึ้นภายในชั่วข้ามคืน จึงได้ชื่อเล่นว่ามหาสมุทรใบไม้ไร้ที่สิ้นสุด",
  str_item_intro_5421461 = "ต้นควินแลน IV ที่ผ่านการกลายพันธุ์แบบซับซ้อน หายากมาก มันจะงอกกิ่งก้านออกมาจากราก แผ่ออกไปทั้งสองข้าง แล้ววนกลับขึ้นมาบรรจบกันเป็นวงกลม ดูเหมือนกรอบประตูที่ทำจากต้นไม้ไม่ผิดเพี้ยน จึงมีชื่ออย่างไม่เป็นทางการว่าควินแลนประตู",
  str_item_intro_5421462 = "ต้นควินแลน อาร์คเวย์สายพันธุ์หายากที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ บางครั้งเส้นโค้งสีน้ำเงินจะมีหมอกเกาะ และมีเกล็ดน้ำแข็งปกคลุมในช่วงฤดูหนาว เมื่อมองไกล ๆ จะเหมือนว่าเป็นหิมะและน้ำแข็งที่ก่อตัวขึ้น",
  str_item_intro_5421463 = "ต้นควินแลน อาร์คเวย์สายพันธุ์หายากที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ แทนที่จะให้ความรู้สึกน่ากลัวเมื่อมองดู ซุ้มประตูสีแดงนี้กลับให้ความรู้สึกอบอุ่นและสบายใจ บ้างก็บอกว่าต้นไม้ชนิดนี้ปลูกแล้วให้โชคอีกด้วย",
  str_item_intro_5421471 = "ต้นไม้ควินแลน IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ต้นไม้ที่หายากอย่างยิ่งต้นนี้ให้ความรู้สึกผ่อนคลายอย่างน่าทึ่งต่อทุกคนที่พบเห็น เนื่องจากลำต้นที่แตกกิ่งก้านและมงกุฎที่พลิ้วไหวไปตามสายลม และลักษณะที่แวววาวด้วยหยดน้ำค้าง ด้วยเหตุนี้จึงเป็นที่รู้จักในนาม \"ควินแลนไร้กังวล\"",
  str_item_intro_5421472 = "สกุลที่หายากของต้น Winsome Quinlan ซึ่งผ่านการกลายพันธุ์ที่ซับซ้อนหลังจากผสมพันธุ์กับ Rose Crystalloids เนื่องจากน้ำค้างสีฟ้าที่สะสมบนใบของมัน ควินแลนนี้จึงดูราวกับจมอยู่ในทะเลน้ำตื้นเมื่อมองจากระยะไกล จึงมีฉายาว่าประภาคารวินซัม",
  str_item_intro_5421473 = "สกุลที่หายากของต้น Winsome Quinlan ซึ่งผ่านการกลายพันธุ์ที่ซับซ้อนหลังจากผสมพันธุ์กับ Rose Crystalloids น้ำค้างสีม่วงทำให้ต้นไม้ที่มีเอกลักษณ์นี้เต็มไปด้วยเสน่ห์ ขณะที่มันพลิ้วไสวไปตามสายลม มันดูไร้กังวลและพึงพอใจในขณะที่เปล่งประกายเสน่ห์ที่น่าหลงใหล",
  str_item_intro_5421481 = "ต้นไม้ควินแลน IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ลำต้นที่ตั้งตรงและมงกุฎรูปเปลวไฟของต้นไม้ที่หายากยิ่งนี้ทำให้มันตั้งตระหง่านเหมือนไฟสัญญาณ เป็นไปได้ว่าผู้ที่จ้องมองรูปร่างของมันอาจเข้าใจผิดว่าเป็นแหล่งกำเนิดแสงที่แท้จริง!",
  str_item_intro_5421482 = "สกุลที่หายากของต้นควินแลนที่ลุกโชนซึ่งผ่านการกลายพันธุ์ที่ซับซ้อนหลังจากผสมพันธุ์กับโรสคริสตัลลอยด์ มงกุฎสีชมพูขนาดใหญ่ของต้นไม้นี้เป็นเหมือนเมฆหมอกลึกลับที่ลอยอยู่บนลำต้นและกิ่งก้าน เมื่อลมพัด มงกุฎของ \"ละอองน้ำกุหลาบ\" จะมีลักษณะผิดปกติ ทำให้ผู้ชมสัมผัสได้ถึงความรู้สึกที่แปลกประหลาด",
  str_item_intro_5421483 = "สกุลที่หายากของต้นควินแลนที่ลุกโชนซึ่งผ่านการกลายพันธุ์ที่ซับซ้อนหลังจากผสมพันธุ์กับโรสคริสตัลลอยด์ มงกุฎสีแดงทำให้เป็นคบเพลิงที่แท้จริง โดยเฉพาะอย่างยิ่งเมื่อมันร่ายรำในสายลม ทำให้เกิดภาพลวงตาของไฟทุ่งหญ้าที่โหมกระหน่ำ",
  str_item_intro_5422111 = "ต้นอาเธอร์สีเขียวมินต์ที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ มีลำต้นสูงและให้ความรู้สึกของฤดูใบไม้ผลิ",
  str_item_intro_5422112 = "ต้นอาเธอร์สีเขียวเข้มที่เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ มีความหนักแน่นมั่นคงและสงบเงียบ",
  str_item_intro_5422113 = "ต้นอาเธอร์ I ที่เพิ่งปลูก ดูแล้วไม่มีอะไรแปลกประหลาด ลำต้นที่สูงและตรง กิ่งก้านเรียวเล็กและใบรูปทรงคล้ายเข็มที่งอกขึ้นด้านบนทำให้มันไม่เหมือนใคร",
  str_item_intro_5422211 = "พันธุ์ของต้นอาเธอร์ใบสั้นที่กลายพันธุ์เล็กน้อย เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เข็มสีแดงนั้นสั้นมาก และเมื่อร่วงหล่นก็จะก่อตัวเป็นพรมแดงใต้ต้นไม้ซึ่งดูสวยงาม",
  str_item_intro_5422212 = "พันธุ์ของต้นอาเธอร์ใบสั้นที่กลายพันธุ์เล็กน้อย เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เข็มสั้น ๆ มีลวดลายสีเขียวคล้ายมรกตกระดำกระด่าง",
  str_item_intro_5422213 = "ต้นอาเธอร์ II ที่กลายพันธุ์เล็กน้อย แตกต่างจากพันธุ์ดั้งเดิมอย่างมาก ขณะที่กิ่งก้านยื่นออกไปด้านนอก ยอดจะบาง ส่วนใบก็สั้นและหนา หากไม่สังเกตให้ดีก็ยากที่จะดูออกว่านี่คือต้นอาเธอร์",
  str_item_intro_5422221 = "พันธุ์ของต้นอาเธอร์ใบยาวที่กลายพันธุ์เล็กน้อย เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ใบไม้แห้งอย่างรวดเร็วหลังจากร่วงหล่นและเมื่อเหยียบจะมีเสียง \"แกร๊บ\" ที่ฟังแล้วเพลิดเพลิน",
  str_item_intro_5422222 = "พันธุ์ของต้นอาเธอร์ใบยาวที่กลายพันธุ์เล็กน้อย เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ใบที่เรียวเล็กนั้นอ่อนนุ่มแต่แข็งแรง หลายคนชอบนำมาใช้ทำด้ามปากกา",
  str_item_intro_5422223 = "ต้นอาเธอร์ II ที่กลายพันธุ์เล็กน้อย รูปลักษณ์ของมันเปลี่ยนไปอย่างมาก กิ่งก้านเติบโตตามใจและใบก็ยาวขึ้นด้วย แทบจะนึกไม่ออกเลยว่ามันมาจากต้นอาเธอร์สูง ๆ เหล่านั้น",
