  str_item_intro_5422312 = "พันธุ์ล้ำค่าของอาเธอร์ ริดจ์ ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ พื้นผิวสีเขียวที่ด้านหนึ่งของกิ่งนั้นทำให้เข้าใจผิดได้ง่าย ๆ ว่าเป็นมอสติดอยู่",
  str_item_intro_5422313 = "พันธุ์ล้ำค่าของอาเธอร์ ริดจ์ ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เปลือกบางส่วนมีสีแดงอ่อนซึ่งทำให้เกิดเป็นเรื่องราวสยองขวัญเล่าต่อกัน แต่ก็เป็นเรื่องไร้สาระทั้งหมด",
  str_item_intro_5422321 = "ต้นอาเธอร์ III ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง มีทรงพุ่มเตี้ยและกิ่งอ่อนยาวห้อยลงมา ดูเหมือนป่าเล็ก ๆ เมื่อมองจากระยะไกล จึงได้ชื่อว่าเป็น \"ป่าต้นไม้เดียว\"",
  str_item_intro_5422322 = "พันธุ์ล้ำค่าของต้นอาเธอร์ บานยันที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีแดงมหึมาเหมือนร่ม ซึ่งเพียงพอแล้วที่จะบังแดดที่ร้อนแรงและมอบร่มเงาที่เย็นสบาย",
  str_item_intro_5422323 = "พันธุ์ล้ำค่าของต้นอาเธอร์ บานยัน ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ มียอดสีเขียวขนาดใหญ่และกิ่งก้านที่แข็งแรงห้อยลงมา ใครที่เดินไปใกล้คงคิดว่าหลงเข้าไปในป่าเล็ก ๆ",
  str_item_intro_5422331 = "พันธุ์ล้ำค่าของต้นอาเธอร์ ฮีธ ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ทรงพุ่มสีซีดเล็กน้อยเข้ากับลำต้นที่แตกร้าว ทำให้หลายคนคิดว่ามันแห้งตายแล้ว แต่เมื่อพวกเขาสังเกตเห็นว่าต้นไม้นั้นยืนต้นอยู่ที่นั่นเป็นเวลานานมาก พวกเขาก็จะเปลี่ยนความคิด",
  str_item_intro_5422332 = "ต้นอาเธอร์ III ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง คล้ายกับต้นไม้ที่เหี่ยวเฉาทั่วไปในถิ่นทุรกันดาร จึงเป็นที่มาของชื่อ อย่างไรก็ตาม ยอดขนาดเล็กที่เติบโตบนลำต้นที่บิดเป็นเกลียวนั้นแสดงให้เห็นถึงพลังอันแข็งแกร่งราวกับจะบอกกับทุกคนว่า \"ข้ายังไม่ตาย\"",
  str_item_intro_5422333 = "พันธุ์ล้ำค่าของต้นอาเธอร์ ฮีธ ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีเขียวและกิ่งที่เหี่ยวแห้งนั้นตัดกันอย่างเด่นชัด บางคนอาจสงสัยว่าทั้งสองอย่างมาจากต้นเดียวกันหรือไม่ แต่ความจริงก็คือพวกมันเป็นต้นอาเธอร์ ฮีทต้นเดียวกัน นี่อาจเป็นเสน่ห์ของต้นไม้มหัศจรรย์ก็ได้",
  str_item_intro_5422341 = "พันธุ์ล้ำค่าของต้นอาเธอร์ เลค ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ น้ำจากต้นไม้มีสีเหลืองอ่อนและมีรสขมเล็กน้อยในตอนแรก แต่รสที่ค้างอยู่ในคอจะหวานเล็กน้อย ว่ากันว่าน้ำนั้นดีต่อการฟื้นฟูร่างกาย และบางคนก็ว่าถ้าดื่มมากไปจะทำให้เวียนหัว",
  str_item_intro_5422342 = "ต้นอาเธอร์ III ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง ตั้งชื่อตามแอ่งน้ำตามธรรมชาติที่เกิดขึ้นที่โคนต้นไม้และปลายยอดมีน้ำหยดตลอดเวลา ไม่มีใครเข้าใจหลักการและความหมายของวัฏจักรลึกลับนี้ได้ ผู้คนสามารถดื่มน้ำจากสระรากและตื่นตาตื่นใจไปกับพลังการกลายพันธุ์ของมัน",
  str_item_intro_5422343 = "พันธุ์ล้ำค่าของต้นอาเธอร์ เลค ที่ผ่านการกลายพันธุ์มาแล้วหลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ น้ำในสระเป็นสีเขียว เมื่อมองแวบแรกมันดูมีพิษ แต่ที่จริงแล้วมันเย็นมากและมีกลิ่นหอมสดชื่น ซึ่งน่าประหลาดใจยิ่งนัก",
  str_item_intro_5422411 = "พันธุ์ล้ำค่าของต้นอาเธอร์ อิ๊งสโตน ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ส่วนหนึ่งของลำต้นและยอดจะเปล่งแสงสีเขียวราวกับมีลำธารไหลริน สวยงามมหัศจรรย์จริง ๆ",
  str_item_intro_5422412 = "ต้นอาเธอร์ IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน มีรากปรากฎภายนอก ลำต้นหนาและแข็ง ที่ส่วนยอดเต็มไปด้วยใบไม้เรืองแสง! เมื่อมองจากระยะไกลดูเหมือนประภาคารขนาดเล็ก จึงได้ชื่อว่า \"ต้นอาเธอร์ประภาคาร\"",
  str_item_intro_5422413 = "พันธุ์หายากของต้นอาเธอร์ อิ๊งสโตน ที่มีการกลายพันธุ์หลายครั้ง เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ลำต้นรูปทรงดั่งหินและยอดที่เปล่งประกายดุจทองคำ คนที่ไม่รู้จักอาจจะคิดว่าพวกเขากำลังอยู่ที่พระราชวังอันงดงาม ต้นไม้นี้จึงถูกเรียกอีกอย่างว่า \"ต้นอาเธอร์พระราชวัง\"",
  str_item_intro_5422421 = "ต้นอาเธอร์ IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน ส่วนหนึ่งของลำต้นได้รวมเข้ากับยอดแข็ง ทำให้เกิดเป็นแผ่นหินกลวงจำนวนหนึ่งที่แข็งแต่บางมาก เมื่อเคาะจะส่งเสียงระดับต่าง ๆ ได้ บางคนเชื่อว่าต้นไม้จะพูดออกมาทางยอดของมัน...",
  str_item_intro_5422422 = "พันธุ์หายากของต้นอาเธอร์ โบลเดอร์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ ยอดสีเขียวมหึมาเหมือนอัญมณีสีเขียว เพียงแค่แตะเบา ๆ ก็จะเกิดเสียงที่ไพเราะและชัดเจนทุกประเภท จึงมีชื่อเล่นว่า \"ต้นอาเธอร์นักดนตรี\"",
  str_item_intro_5422423 = "พันธุ์หายากของต้นอาเธอร์ โบลเดอร์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ แผ่นหินสีน้ำเงินทำให้เกิดเสียงไพเราะและสั่นเล็กน้อย ก่อให้เกิดภาพหลังเป็นสีฟ้าที่แวบวาบราวกับฝัน",
  str_item_intro_5422431 = "พันธุ์หายากของต้นอาเธอร์ ชัตเตอร์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เมื่อใจสีเหลืองของต้นไม้ส่องแสง พื้นผิวของลำต้นจะเกิดภาพลวงตาของใบไม้สีเหลืองอ่อน ทำให้ผู้คนรู้สึกว่าต้นไม้มหัศจรรย์นี้กลับมามีชีวิตชีวาอีกครั้ง! ดังนั้นชื่อเล่นของมันก็คือ \"ต้นอาเธอร์คืนชีพ\"",
  str_item_intro_5422432 = "ต้นอาเธอร์ IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน มีลำต้นกลวง ใจกลางของต้นไม้เป็นรูปทรงเห็ดแปลก ๆ ที่เปล่งแสงสวยงาม ว่ากันว่าเมื่อสัมผัสได้ถึงความอันตราย เปลือกนอกของต้นไม้จะปิดและบังแสงนั้นไว้ จึงมีชื่อเรียกอีกชื่อว่า \"ต้นอาเธอร์บังแสง\"",
  str_item_intro_5422433 = "พันธุ์หายากของต้นอาเธอร์ ชัตเตอร์ ซึ่งมีการกลายพันธุ์ซับซ้อน เพาะพันธุ์ด้วยโรสคริสตัลลอยด์ เปล่งแสงสีน้ำเงินจากใจกลางต้นไม้ หลังจากที่แสงหักเหในลำต้นกลวง จะเกิดเป็นภาพลวงตาให้ผู้คนเห็นว่าต้นไม้นั้นมีลำธารล้อมรอบ และพวกเขาก็จะเข้าใจผิดคิดว่าตัวเองอยู่ใต้น้ำ...",
  str_item_intro_5422441 = "ต้นอาเธอร์ IV ที่ผ่านการกลายพันธุ์มาอย่างซับซ้อน กิ่งก้านและใบบางกิ่งรวมตัวกันจนกลายพันธุ์เป็น \"ตะเกียง\" ส่วนของกิ่งก้านที่ทำหน้าที่เป็น \"ไส้ตะเกียง\" ก็เปล่งแสงอันอบอุ่นได้! ไม่ต้องสงสัยเลยว่านี่คือสัญญาณสำหรับนักเดินทางที่เดินอยู่ในถิ่นทุรกันดารที่มืดมิด",
  str_item_intro_5422442 = "พันธุ์หายากของต้นอาเธอร์ ไบรท์เนส ซึ่งมีการกลายพันธุ์ซับซ้อน ผสมพันธุ์ด้วยโรสคริสตัลลอยด์ ว่ากันว่า \"ตะเกียง\" ของต้นนี้ส่องแสงสีน้ำเงินที่อ่อนโยน เพราะลำต้นของมันประกอบด้วยลูมินา",
  str_item_intro_5422443 = "พันธุ์หายากของต้นอาเธอร์ ไบรท์เนส ซึ่งมีการกลายพันธุ์ซับซ้อน ผสมพันธุ์ด้วยโรสคริสตัลลอยด์ ใบไม้เป็นสีแดง แต่ \"ตะเกียง\" ของมันเปล่งแสงสีแดงอ่อน ๆ กระทบกับลำต้นสีขาวทำให้ดูสวยมีเสน่ห์เฉพาะตัว",
