  str_item_intro_5422463 = "พันธุ์ไม้หายากของ Arthur Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ฟลูออโรฟอร์สีเหลืองของมันเต็มไปด้วยพลังที่สัมผัสได้ และทำให้พืชใกล้เคียงเติบโตได้ด้วยพลังงาน",
  str_item_intro_5422471 = "Arthur Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน มงกุฎของมันได้กลายพันธุ์อย่างสมบูรณ์จนถึงจุดที่ตอนนี้มันกลายเป็นก้อนแข็งที่ห้อยลงมาทุกด้าน ก่อตัวเป็นรูปทรงชามที่แปลกประหลาด กิ่งอันสวยงามของมันยื่นออกมาจากใจกลางของ \"ชาม\" นี้ กระพริบเหมือนคบเพลิงเพื่อดึงดูดความสนใจของทุกคนที่จ้องมองมัน",
