  str_item_intro_5422481 = "Arthur Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ต้นไม้ทั้งต้นแข็งและกลายร่างเป็นแท่นหิน น้ำที่ไหลลงมาจากด้านบนบังเอิญไหลเข้าไปในรูของต้นไม้ ทำให้เกิดฉากที่สวยงามมากทีเดียว",
