  str_item_intro_5423212 = "สกุลของ Festive Blooming Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อยบางส่วนนั้นได้รับการอบรมด้วย Rose Crystalloids ดอกไม้สีเหลืองอ่อนคล้ายกับดวงอาทิตย์ดวงเล็กๆ หลายดวง ทำให้ทุกคนต้องตะลึง",
  str_item_intro_5423213 = "สกุลของ Festive Blooming Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อยบางส่วนนั้นได้รับการอบรมด้วย Rose Crystalloids ดอกไม้สีฟ้าอ่อนของมันโบกสะบัดไปตามลมอย่างแผ่วเบาราวกับเมฆที่ลอยอยู่บนท้องฟ้า",
  str_item_intro_5423221 = "Blooming Tree II ที่ได้รับการกลายพันธุ์เล็กน้อย แม้ว่าลำต้นของมันจะหนากว่าต้นไม้ผลิดอกทั่วไปอย่างเห็นได้ชัด แต่ความแตกต่างที่โดดเด่นที่สุดคือดอกไม้ของมัน ต้นไม้ที่มีรูปร่างยาวและมีรูปร่างคล้ายแตรนับไม่ถ้วน จึงเป็นที่มาของชื่อต้นไม้ต้นนี้",
  str_item_intro_5423222 = "สกุลของ Sonorous Blooming Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อยบางส่วนนั้นได้รับการอบรมด้วย Rose Crystalloids ดอกไม้สีฟ้ามีปริมาณน้ำสูงและสามารถใช้ดับกระหายหรือชงเครื่องดื่มพิเศษได้!",
  str_item_intro_5423223 = "สกุลของ Sonorous Blooming Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อยบางส่วนนั้นได้รับการอบรมด้วย Rose Crystalloids ดอกของมันเป็นสีแดงที่ลุกเป็นไฟ และจะอ่อนตัวและแห้งอย่างรวดเร็วเมื่อนำออกจากต้นไม้ ทำให้เป็นวัสดุจุดไฟที่เหมาะสมมาก",
  str_item_intro_5423311 = "Blooming Tree III ที่ได้รับการกลายพันธุ์บ่อยครั้ง ดอกไม้ของมันจะเติบโตบนลำต้นเท่านั้น ในขณะที่กิ่งหลายกิ่งงอกออกมาจากรากของมันและล้อมรอบพวกมัน ลักษณะลึกลับของมันเปรียบได้กับกลุ่มผู้พิทักษ์ของจักรพรรดิที่ปกป้องราชินีของพวกเขา",
