  str_item_intro_5423322 = "สกุลหายากของ Wistful Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ดอกไม้สีฟ้าห้อยต่ำและรูปทรงกลมสร้างทางเข้าตามธรรมชาติ แม้จะวางไว้ตรงทางเข้าสวนที่มนุษย์สร้างขึ้น แต่ก็เข้ากับสภาพแวดล้อมได้อย่างลงตัวในขณะที่ยังคงให้ทัศนียภาพที่น่าตื่นตาตื่นใจ",
  str_item_intro_5423323 = "ต้นไม้บานสะพรั่งที่ได้รับการกลายพันธุ์บ่อยครั้ง ดอกไม้ของมันเปลี่ยนเป็นสีขาวซีดและอ่อนโยน และสามารถสังเกตเห็นกลิ่นหอมสดชื่นของดอกไม้ขณะยืนอยู่ใต้ร่มไม้ ด้วยเหตุนี้ ดอกไม้จึงกลายเป็นวัตถุดิบสำคัญสำหรับน้ำหอมหลายชนิด",
  str_item_intro_5423331 = "Blooming Tree III ที่ได้รับการกลายพันธุ์บ่อยครั้ง ลำต้นของมันบิดเบี้ยวเป็นรูปร่างของดอกไม้ยักษ์ ซึ่งสามารถมองเห็นได้ไกลพอสมควร อย่างไรก็ตาม ดอกไม้จริง ๆ ของมันนั้นอยู่ภายในลำต้นและกิ่งที่มีปมเป็นปม ทำให้นักวิจัยตั้งทฤษฎีว่ารูปร่างที่เป็นเอกลักษณ์มีไว้เพื่อปกป้องพวกมันจากผู้ล่า",
  str_item_intro_5423332 = "สกุลหายากของ Iris Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ปลายกิ่งมีสีฟ้าอ่อนและมีสารคัดหลั่งที่เข้มกว่าหยด บางคนบอกว่าสารคัดหลั่งนี้สามารถใช้เป็นหมึกชนิดหนึ่ง หรือแม้แต่เป็นสีย้อมผ้าก็ได้",
  str_item_intro_5423333 = "Iris Blooming Tree ที่ได้รับการกลายพันธุ์บ่อยครั้ง ปลายกิ่งมีสีเขียวอ่อน ขณะที่แอ่งน้ำที่โคนมีแสงสีน้ำเงินเข้ม ให้แสงออร่าอันทรงพลังของพลังงานธรรมชาติ",
  str_item_intro_5423341 = "Blooming Tree III ที่ได้รับการกลายพันธุ์บ่อยครั้ง กล่าวกันว่าคล้ายต้นไม้จากแดนไกล ดอกไม้บานสะพรั่งทั้งสวยงามและอบอวลไปด้วยกลิ่นหอมอ่อนๆ เมื่อจ้องไปที่ต้นไม้ต้นนี้เป็นเวลานาน รุ้งก็จะปรากฏต่อหน้าต่อตาคุณในที่สุด แม้ว่านี่จะเป็นเพียงตำนาน แต่ก็เป็นเหตุผลที่ทำให้ต้นไม้ต้นนี้ได้รับชื่อ",
  str_item_intro_5423342 = "สกุลหายากของ Iridescent Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ดอกไม้สีม่วงมีเสน่ห์เป็นพิเศษ อันที่จริงแล้ว สีของพวกมันสดใสมากจนต้องใช้ในปริมาณที่พอเหมาะเมื่อใช้เป็นของตกแต่งหรือเน้นเสียง เกรงว่าพวกเขาจะเอาชนะความรู้สึกได้",
  str_item_intro_5423343 = "ต้นไม้บานสีรุ้งที่ได้รับการกลายพันธุ์บ่อยครั้ง ดอกไม้สีเหลืองของที่นี่เต็มไปด้วยชีวิตชีวา และดูเหมือนยังคงบานสะพรั่งทั้งกลางวันและกลางคืน มีข่าวลือว่าดอกไม้สามารถนำมาใช้ปรุงยาแห่งความมีชีวิตชีวาได้ ด้วยเหตุนี้จึงเป็นที่รู้จักโดยบางคนว่าเป็น \"ต้นไม้แห่งชีวิตสีรุ้ง\"",
  str_item_intro_5423411 = "Blooming Tree IV ที่ได้รับการกลายพันธุ์ที่ซับซ้อน แม้ว่าทรงพุ่มมีดอกเพียงดอกเดียว แต่ดอกไม้นั้นมีขนาดมหึมา มีสีเจิดจ้า และมีกลิ่นหอมหวานอย่างอันตราย บางคนถึงกับบอกว่าเกสรตัวผู้ของดอกไม้สามารถใช้เป็นเครื่องปรุงรสที่ยอดเยี่ยมสำหรับอาหารได้ ดอกไม้ของต้นไม้ต้นนี้มักเป็นเป้าหมายของการตรึงตรึงสำหรับใครหลายๆ คน ดูเหมือนดอกไม้ของต้นไม้นี้จะดึงดูดทุกชีวิตให้มองด้วยตา",
  str_item_intro_5423412 = "สกุลหายากของ Bewitching Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ดอกไม้สีฟ้าอ่อนของมันจะโบกไปมาในสายลมราวกับคลื่นในมหาสมุทร และยังส่งกลิ่นคาวที่ฝาดเล็กน้อย ดังนั้นผู้ที่อาศัยอยู่ห่างไกลจากทะเลอ้างว่าพวกเขายังคงสามารถสัมผัสความสุขของวันฤดูร้อนบนชายหาดได้เพียงแค่ชื่นชมดอกไม้ของต้นไม้ต้นนี้",
  str_item_intro_5423413 = "สกุลหายากของ Bewitching Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ดอกไม้ของมันกลายเป็นสีชมพูที่น่าดึงดูดใจจนน่ากลัว การมองดูเพียงอย่างเดียวก็ทำให้คนลืมความทุกข์ยากทั้งหมดได้ ทำให้ยากต่อการละสายตาจากมัน ที่จริงแล้ว บางคนถึงกับตั้งนาฬิกาปลุกเพื่อเตือนพวกเขาถึงอันตรายจากการหมกมุ่นอยู่กับภาพที่สวยงามเช่นนั้น",
  str_item_intro_5423421 = "Blooming Tree IV ที่ได้รับการกลายพันธุ์ที่ซับซ้อน ดอกของมันมีกลีบนับไม่ถ้วน ซึ่งแต่ละดอกมีความนุ่มและเรียวยาวราวกับใยไหม บางคนถึงกับพยายามใช้พวกมันในการทอผ้า แต่ดอกไม้ที่บอบบางเหล่านี้กลับเปราะบางอย่างรวดเร็วหลังจากถูกนำออกจากต้นไม้ ส่งผลให้ความงามตามธรรมชาติของมันสูญเปล่าไปอย่างน่าละอาย",
  str_item_intro_5423422 = "สกุลหายากของ Silken Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids หลังคาสีฟ้าของมันมักจะชวนให้นึกถึงภาพของ \"ธิดาแห่งท้องทะเล\" ซึ่งเป็นบุคคลในตำนานที่มีผมสีฟ้าราวกับท้องทะเล บางคนถึงกับบอกว่าดอกไม้ของต้นไม้ต้นนี้ส่งกลิ่นหอมจางๆ ของละอองทะเล...",
  str_item_intro_5423423 = "สกุลหายากของ Silken Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids กล่าวกันว่าดอกไม้ที่เขียวชอุ่มเป็นที่อยู่ของจิตวิญญาณของดอกไม้ทั้งหมด และการได้เห็นกับตาจะรับประกันรักแท้ตั้งแต่แรกเห็น...",
  str_item_intro_5423431 = "Blooming Tree IV ที่ได้รับการกลายพันธุ์ที่ซับซ้อน กลีบของดอกไม้ขนาดมหึมานั้นมีรูปร่างเหมือนจานอย่างชัดเจน และดูเหมือนจะหันไปทางที่สูงเบื้องบน เมื่อผู้คนสังเกตเห็น ดอกไม้ของมันดูเหมือนจะเบือนหน้าหนีจากสายตาของพวกเขา เป็นผลให้เป็นที่รู้จักกันในชื่อ \"Bashful Bloom\" ในบางวงการ",
  str_item_intro_5423432 = "สกุลหายากของ Skygazer Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids ดอกของมันมีสีแดงสดดุจเปลวไฟที่ควบคุมไม่ได้ ตำนานกล่าวว่าดอกไม้ที่แข็งแรงนี้แหงนมองท้องฟ้าเพื่อแบ่งปันความมีชีวิตชีวาให้กับคนทั้งโลก",
  str_item_intro_5423433 = "สกุลหายากของ Skygazer Blooming Tree ที่ผสมพันธุ์ด้วย Rose Crystalloids กลีบดอกไม้ของมันเป็นสีขาวราวกับหิมะและเปล่งประกายออกมาอย่างประหลาด บางคนบอกว่ามันสร้างภาพลวงตาได้หลากหลายขึ้นอยู่กับทิศทางที่มันหันไป ทำให้ชื่อเล่นว่า \"ช่างทอฝัน\"",
  str_item_intro_5423441 = "Blooming Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน กลีบดอกเกลี้ยงเกลาสวยงามซ้อนทับกันเป็นชั้นๆ แค่มองแวบเดียวก็ทำให้ใจหวิวได้แล้ว จึงเป็นที่ชื่นชอบของสาวๆ หลายคน",
  str_item_intro_5423442 = "สกุลหายากของ Virtuous Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids ท้องฟ้าสีฟ้าทำให้มึนเมา และผู้ชมหลายคนรู้สึกสดชื่นรอบๆ ราวกับท้องฟ้าแจ่มใสหลังฝนตก ด้วยเหตุนี้จึงมีชื่อเรียกอีกอย่างว่า \"ท้องฟ้าแจ่มใส\"",
  str_item_intro_5423443 = "สกุลหายากของ Virtuous Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids ดอกไม้สีม่วงนั้นดูอันตราย และว่ากันว่าดอกไม้ของมันจะแกว่งไปมาเล็กน้อยเมื่อมีคนมอง และดึงพวกเขาเข้าสู่ภวังค์ ยังไงก็ระวังกันด้วยนะครับ",
  str_item_intro_5423451 = "Blooming Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน เรือนยอดขนาดใหญ่ก่อตัวเป็นช่องทางตามธรรมชาติ และผนังด้านในที่เกิดจากกลีบดอกนั้นเรียบลื่นจนเก็บน้ำค้างยามเช้าไว้ในลำต้นเพื่อหล่อเลี้ยงตัวมันเอง",
  str_item_intro_5423452 = "ต้นไม้หายากสกุล Dawn Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids เรือนยอดสีม่วงย้อมน้ำค้างที่สะสมไว้ให้เป็นสีเดียวกัน นักวิชาการบางคนเชื่อว่าน้ำค้างนี้มีพลังลึกลับและใช้มันเพื่อเขียนหนังสือบางเล่ม",
  str_item_intro_5423453 = "ต้นไม้หายากสกุล Dawn Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids น้ำค้างที่สะสมจากเรือนยอดจะดูเป็นสีฟ้าและทำให้ผู้ที่มองดูสดชื่นได้ น้ำค้างนี้ดูเหมือนจะสามารถชำระสิ่งสกปรกออกจากร่างกายได้ ดังนั้นจึงเรียกอีกชื่อหนึ่งว่า \"ดีท็อกซ์แห่งรุ่งอรุณ\"",
  str_item_intro_5423461 = "Blooming Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน มงกุฎของมันแบ่งออกเป็นหลายส่วนยาวและละเอียดอ่อนซึ่งเซรอบศูนย์กลางของมัน พวกเขาบอกว่าหลังจากได้เห็นมัน ครั้งหนึ่งดีไซเนอร์ได้รับแรงบันดาลใจในการออกแบบชุดกระโปรงตามรูปทรงของกลีบดอก ซึ่งนำไปสู่สมญานามว่า \"Skirted Beauty\"",
  str_item_intro_5423462 = "ต้นไม้หายากสกุล Aureate Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids กลีบดอกสีส้มดูเหมือนจะมีสัมผัสแห่งความเย้ายวนใจ และด้วยกลิ่นหอมอันเป็นเอกลักษณ์ เป็นเครื่องเตือนใจอันทรงพลังถึงทุกสิ่งที่เย้ายวนใจแต่แฝงไปด้วยอันตรายในโลกนี้",
  str_item_intro_5423463 = "ต้นไม้หายากสกุล Aureate Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids กลีบของมันกลายเป็นสีของท้องฟ้า ประดับประดาด้วยใบไม้สีขาวที่กระจายความรู้สึกสดชื่นและสะอาด ทำให้เป็นที่นิยมในหมู่เด็กๆ",
  str_item_intro_5423471 = "Blooming Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน มงกุฎและเกสรตัวผู้ประกอบเป็นรูปทรงผีเสื้อ ซึ่งไม่เพียงสร้างความพิศวงให้กับผู้ที่พบเห็นเท่านั้น แต่ยังดึงดูดผีเสื้อจริงๆ ให้มาเต้นรำรอบๆ ราวกับว่าเป็นพระเจ้าของพวกมัน",
  str_item_intro_5423472 = "พืชสกุลหายากของ Fluttering Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids เมื่อมองจากระยะไกล เกสรตัวผู้สีเหลืองขนาดใหญ่ดูเหมือนผีเสื้อเกาะอยู่ เมื่อใดที่สายลมโชยพัดมา ก็ยิ่งยากที่จะแยกแยะ...",
  str_item_intro_5423473 = "พืชสกุลหายากของ Fluttering Blooming Tree ที่ผสมพันธุ์กับ Rose Crystalloids เกสรตัวผู้สีน้ำเงินและรูปร่างคล้ายผีเสื้อแต่กำเนิดทำให้ผู้คนรู้สึกประทับใจเมื่อแรกพบ เมื่อค้นพบร่างที่แท้จริงของมันในที่สุด ใครก็ได้แต่ถอนหายใจให้กับความมหัศจรรย์ของต้นไม้ต้นนี้ จึงถูกขนานนามว่าเป็น \"ผีเสื้อแสนสวยแห่งความลึกลับ\"",
  str_item_intro_5424111 = "เมื่อมองไปที่รากกลม เราสามารถเห็นความแตกต่างระหว่างต้นไม้สเตรนจ์ฟรุ๊ตพื้นฐานกับพันธุ์อื่นๆ และอดไม่ได้ที่จะประหลาดใจในความพิเศษของมัน",
  str_item_intro_5424112 = "ต้นไม้ผลไม้สีเหลืองที่ผสมพันธุ์กับ Rose Crystalloids มันออกผลและใบสีเหลืองซึ่งดูเหมือนจะเป็นสัญลักษณ์ของการโอบกอดของฤดูใบไม้ร่วง",
  str_item_intro_5424113 = "ต้นสเตรนจ์ฟรุตสีม่วงที่ผสมพันธุ์กับโรสคริสตัลลอยด์ คุณอาจพบว่ามีกลิ่นแปลก ๆ ในตอนแรก แต่น้ำเลี้ยงของมันกลับไม่มีรสเลย จนคล้ายกับน้ำบริสุทธิ์",
  str_item_intro_5424211 = "ต้นไม้สเตรนจ์ฟรุต II ที่มีการกลายพันธุ์เล็กน้อย รากของมันแข็งแกร่งและผลของมันมีหนามแหลมคมอยู่ภายนอก ซึ่งทำหน้าที่เป็นเกราะป้องกันที่น่าเกรงขาม เถาวัลย์รอบๆ ดูเหมือนจะเตือนคนแปลกหน้าให้รักษาระยะห่างด้วย",
  str_item_intro_5424212 = "สกุลของ Blooming Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids เถา ลำต้น และใบสีน้ำเงินแสดงว่ามันแตกต่างจากพันธุ์ดั้งเดิม แต่ดูเหมือนว่าผลของมันยังคงเหมือนเดิม",
  str_item_intro_5424213 = "สกุลของ Blooming Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids เถาและลำต้นของมันให้ความรู้สึกเหี่ยวเฉา แต่ผลไม้ข้างในนั้นอุดมสมบูรณ์และเขียวชอุ่ม ทำให้ดูเหมือนว่ามันปลอมตัวมา",
  str_item_intro_5424221 = "ต้นไม้สเตรนจ์ฟรุต II ที่มีการกลายพันธุ์เล็กน้อย ผลไม้ที่รากถูกบิดเบี้ยวเป็นรูปร่างที่แตกต่างไปจากเดิมอย่างสิ้นเชิง เชื่อกันว่าผลและกลีบใบที่แยกจากกันสามารถดูดซับสารอาหารได้ตามลำดับ ดังนั้นแม้ว่าส่วนหนึ่งของต้นไม้จะเสียหาย แต่ส่วนอื่นๆ ก็สามารถเติบโตต่อไปได้เพื่อความอยู่รอด",
  str_item_intro_5424222 = "ต้นไม้สกุล Flourishing Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids ลักษณะสีแดงของมันเป็นเพราะน้ำนมซึ่งมีสารเคมีหายาก",
  str_item_intro_5424223 = "ต้นไม้สกุล Flourishing Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้มีสีเหลืองพิเศษซึ่งดูเหมือนว่าเป็นผลมาจากการสูญเสียน้ำจากผิวของมัน เมื่อลอกผิวออกแล้ว ในไม่ช้าผิวจะเปราะและแตกเป็นกองเชื้อไฟ",
  str_item_intro_5424311 = "ต้นไม้ประหลาด III ที่มีการกลายพันธุ์บ่อยครั้ง ด้านนอกของผลจะแข็งกลายเป็นลูกหินที่ยากต่อการรับประทาน",
  str_item_intro_5424312 = "พืชสกุลหายากของต้นไม้ผลไม้แปลกที่เจริญงอกงามซึ่งผสมพันธุ์กับ Rose Crystalloids แม้ว่าจะไม่ชัดเจนว่าผลของมันกลายพันธุ์ด้วยหรือไม่ แต่คุณสัมผัสได้รางๆ จากใบ อาจไม่ใช่ความคิดที่ดีที่จะลิ้มรสผลไม้ของมัน",
  str_item_intro_5424313 = "ต้นไม้ผลประหลาดที่เจริญรุ่งเรืองซึ่งผ่านการกลายพันธุ์บ่อยครั้ง มงกุฎและใบของต้นไม้มีสีสันสดใส ซึ่งตรงกันข้ามกับผลไม้ที่มีลักษณะคล้ายหิน บางคนเรียกผลของมันว่า \"หินดอกไม้\"",
  str_item_intro_5424321 = "ต้นไม้ Arcadian Strangefruit ที่มีการกลายพันธุ์บ่อยครั้ง มีลำต้นคดงอและผลแบ่งออกเป็นสองส่วนสร้างเป็นลำตามธรรมชาติ ตราบใดที่คุณมี คุณจะไม่ต้องกังวลว่าจะกระหายน้ำ",
  str_item_intro_5424322 = "สกุลของต้นไม้อาร์เคเดียนสเตรนจ์ฟรุตที่ผสมพันธุ์กับโรสคริสตัลลอยด์ น้ำนมใน \"สระผลไม้\" มีรสชาติที่อธิบายไม่ได้ ซึ่งกล่าวกันว่าเกิดจากองค์ประกอบลึกลับที่ยังไม่ได้ค้นพบ",
  str_item_intro_5424323 = "ต้นไม้ Arcadian Strangefruit ที่มีการกลายพันธุ์บ่อยครั้ง มีน้ำผลไม้ที่ใสกว่าอยู่ตรงกลางที่สามารถคงความเย็นได้นาน จึงเหมาะสำหรับวันฤดูร้อน",
  str_item_intro_5424331 = "ต้นไม้ประหลาด III ที่มีการกลายพันธุ์บ่อยครั้ง ลำต้นบิดเบี้ยว แต่จริงๆ แล้วเกิดจากผลไม้ข้างใน จากการศึกษาบางส่วน เป็นเพราะผลไม้มีการงอ และสิ่งที่เรียกว่า \"ลำต้น\" ปกป้องผิวของผลไม้อย่างแท้จริง",
  str_item_intro_5424332 = "พืชหายากสกุล Mellifluous Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids หลังคาสีขาวดูเหมือนเมฆก้อนใหญ่บนท้องฟ้า",
  str_item_intro_5424333 = "ต้นไม้ผลประหลาดเมลลิฟลูอัสที่มีการกลายพันธุ์บ่อยครั้ง ความแตกต่างของสีของลำต้นของต้นไม้นั้นชัดเจนมาก ซึ่งบ่งบอกว่ารสชาติของผลไม้เปลี่ยนไปอย่างมาก ตามที่นักผจญภัยกล่าวว่ามีรสเผ็ดและเปรี้ยว",
  str_item_intro_5424341 = "ต้นไม้ประหลาด III ที่มีการกลายพันธุ์บ่อยครั้ง รูปร่างของมันสะท้อนแก่นแท้ของ Unique Tree ได้ดีที่สุด ผลไม้กองโต กิ่งก้านที่ยื่นออกมา... นี่คือเหตุผลว่าทำไมมันจึงถูกเรียกว่า \"ผลไม้ยักษ์\"",
  str_item_intro_5424342 = "พันธุ์หายากของ Hearty Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีฟ้าขนาดใหญ่ของมันดูอวบอ้วนมาก พิสูจน์ได้ว่ามันสมควรได้รับชื่อนี้จริงๆ กล่าวกันว่าน้ำผลไม้ที่บรรจุอยู่ภายในนั้นเพียงพอที่จะให้น้ำสำหรับทั้งหมู่บ้าน ด้วยเหตุนี้บางคนจึงเรียกมันว่า \"ต้นถังเก็บน้ำ\"",
  str_item_intro_5424343 = "พันธุ์หายากของ Hearty Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีแดงขนาดใหญ่นั้นสว่างมาก ดังนั้นไม่มีใครละเลยการมีอยู่ของมันได้ นี่คือเหตุผลที่บางตำนานอ้างว่าน้ำผลไม้สามารถคืนความอ่อนเยาว์ได้ แต่อาจเป็นเพียงตำนานเท่านั้น",
  str_item_intro_5424411 = "สกุลหายากของ Strangefruit Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ผลไม้มีขนาดใหญ่และมีสีสันสวยงาม นอกจากนี้กิ่งไม้ที่มีโครงสร้างที่ซับซ้อนสามารถกระตุ้นความปรารถนาที่จะครอบครองได้อย่างง่ายดายหลังจากดูเป็นเวลานานซึ่งนำไปสู่การโต้เถียงกับญาติและเพื่อน ด้วยเหตุนี้จึงมีชื่อเรียกอีกอย่างว่า \"Contrary Tree\"",
  str_item_intro_5424412 = "สกุลที่หายากของต้นไม้สเตรนจ์ฟรุตยืนต้นที่ผสมพันธุ์กับโรสคริสตัลลอยด์ ผลไม้สีเขียวมีรสธรรมชาติเข้มข้น หากคุณจ้องมันนานเกินไป คุณอาจพบว่าตัวเองจมอยู่ในนั้นราวกับว่าคุณอยู่ในป่า คุณสามารถได้ยินแม้กระทั่งเสียงแมลงและนกร้อง และสัมผัสได้ถึงใบไม้ที่ปลิวไปตามสายลม...",
  str_item_intro_5424413 = "สกุลที่หายากของต้นไม้สเตรนจ์ฟรุตยืนต้นที่ผสมพันธุ์กับโรสคริสตัลลอยด์ ผลไม้กลายเป็นสีชมพูสดใสและมีเสน่ห์ หากคุณจ้องมองเป็นเวลานาน คุณอาจเห็นจังหวะการกระโดดโผล่ออกมาจากข้างในในทันที ซึ่งเป็นภาพที่แปลกตามาก",
  str_item_intro_5424421 = "สกุลหายากของ Strangefruit Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ผลมีมากมายหลายขนาดเรียงซ้อนกันเป็นรูปกากบาท ว่ากันว่านี่คือหนึ่งใน Unique Trees ที่เก่าแก่ที่สุด และยังมีบันทึกว่ามีอยู่จริงในป่าด้วย! ด้วยเหตุนี้จึงมีชื่อเรียกอีกชื่อหนึ่งว่า \"ต้นไม้แห่งปฐมกาล\"",
  str_item_intro_5424422 = "สกุลหายากของต้นไม้โอฬารที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีชมพูทำให้ผู้คนอยากดื่มน้ำผลไม้ที่ผลิตขึ้น ว่ากันว่าสามารถใช้ชงเครื่องดื่มรสเลิศที่เชื้อพระวงศ์ยกย่องอย่างสูงได้ ดังนั้นจึงเรียกอีกชื่อหนึ่งว่า \"Regal Tree\"",
  str_item_intro_5424423 = "สกุลหายากของต้นไม้โอฬารที่ผสมพันธุ์กับ Rose Crystalloids จากระยะไกล ผลของมันดูเหมือนลูกบอลเหลวที่ควบแน่นจากน้ำทะเลสีฟ้า และคุณอาจเห็นระลอกคลื่นกระจายไปทั่ว อย่างไรก็ตาม ไม่ทราบว่านี่เป็นเพียงภาพลวงตาหรือไม่",
  str_item_intro_5424431 = "สกุลหายากของ Strangefruit Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ผลไม้ขนาดใหญ่ส่งกลิ่นหอมตลอดเวลา บางคนบอกว่ามันสามารถทำให้เกิดความกล้าหาญอย่างลึกลับแก่ผู้ที่ได้กลิ่น ทำให้พวกเขาปรารถนาที่จะพิชิตทุกสิ่งที่พวกเขาเห็น",
  str_item_intro_5424432 = "สกุลหายากของ Tranquil Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีเขียวของมันสามารถสงบสติทหารที่ดุร้ายที่สุดได้ ทำให้เหมาะสำหรับการทำสมาธิและคิดอย่างลึกซึ้ง กล่าวกันว่าผู้มีปัญญาจำนวนมากบรรลุการรู้แจ้งภายใต้อิทธิพลของมัน ซึ่งนำไปสู่สมญานามว่า \"ต้นไม้แห่งการเปิดเผย\"",
  str_item_intro_5424433 = "สกุลหายากของ Tranquil Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีชมพูขนาดมหึมาของมันไม่เพียงสร้างความกล้าหาญให้กับผู้คนเท่านั้น แต่ยังสามารถมอบความทะเยอทะยานอันแรงกล้าและความรู้สึกมุ่งมั่น เพื่อให้พวกเขาสามารถเริ่มต้นบนเส้นทางที่ไม่มีวันหวนกลับเพื่อต่อสู้เพื่ออำนาจสูงสุด ด้วยเหตุนี้จึงมีชื่อเรียกอีกอย่างว่า \"Kingmaker\"",
  str_item_intro_5424441 = "สกุลหายากของ Strangefruit Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน ผลของมันซ่อนอยู่ในลำต้น แต่ตามความเห็นของนักวิชาการบางคน ลำต้นคือผิวด้านนอกที่แข็งของผลไม้ ไม่ใช่ชั้นภายนอกที่ห่อหุ้มผลไม้! ดูเหมือนว่า Unique Tree นี้กำลังพยายามอย่างมากที่จะปกป้องผลของมัน",
  str_item_intro_5424442 = "พืชหายากสกุล Wonder Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids ว่ากันว่าผลไม้สีเขียวนี้ประกอบด้วยแก่นแท้ของชีวิต ซึ่งเมื่อสกัดอย่างถูกต้อง จะสามารถทำให้พืชเติบโตเร็วขึ้น เพิ่มผลผลิตของพืชผล และแม้แต่ปรับปรุงดินที่แห้งแล้งและดินที่เป็นด่างแข็ง! ด้วยเหตุนี้หลายคนจึงเรียกมันว่าผลไม้แห่งชีวิต",
  str_item_intro_5424443 = "พืชหายากสกุล Wonder Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids ผลสีฟ้าขนาดใหญ่ของมันประกอบด้วยน้ำหวาน และชั้น \"เปลือก\" ภายนอกของมันยังมีเอฟเฟกต์ความชุ่มชื้นอันทรงพลังที่ปกป้องน้ำภายในผลไม้ไม่ให้สูญเสียไป โดยพื้นฐานแล้วทำให้มันเป็นแหล่งกักเก็บน้ำ...",
  str_item_intro_5424451 = "สกุลหายากของ Strangefruit Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน แม้ว่าผลไม้ขนาดใหญ่จะดูธรรมดา แต่ในช่วงเวลาหนึ่ง มันจะส่งกลิ่นหอมอันน่าหลงใหลซึ่งกล่าวกันว่ายากจะลืมเลือน! บางทีนี่อาจเป็นเหตุผลว่าทำไมผีเสื้อจำนวนมากจึงกระพือปีกรอบๆ แม้ว่าปกติแล้วจะไม่มีกลิ่นพิเศษก็ตาม",
  str_item_intro_5424452 = "พันธุ์หายากของต้นไม้ผลไม้แปลกพิเศษที่ผสมพันธุ์กับ Rose Crystalloids ตามตำนานบางตำนาน ผลไม้สีม่วงนี้ปล่อยกลิ่นหอมที่แผ่ซ่านไปทั่วแผ่นดินทุกสองสามร้อยปี! นอกจากนี้ยังมีตำนานของ \"ราชา\" ที่จะอุบัติขึ้นในโลกนี้เมื่อกลิ่นหอมของมันแพร่กระจาย...",
  str_item_intro_5424453 = "พันธุ์หายากของต้นไม้ผลไม้แปลกพิเศษที่ผสมพันธุ์กับ Rose Crystalloids ซึ่งแตกต่างจากผลไม้ของต้นไม้ผลไม้แปลกที่โดดเด่นอื่นๆ ผลไม้สีฟ้านี้มีคำใบ้ของความสดชื่นและระงับกลิ่นอื่นๆ! ด้วยเหตุนี้จึงเป็นที่นิยมในหมู่ชาวสวน แต่การไม่สามารถปลูกถ่ายได้ทำให้ชาวสวนทั่วไปถอนหายใจ",
  str_item_intro_5424461 = "ต้นไม้สกุล Strangefruit หายากซึ่งผ่านการกลายพันธุ์ที่ซับซ้อน เปลือกนอกของมันกลายเป็นกรงที่เก็บผลไม้แสนอร่อย เป็นที่รู้กันว่าผลไม้ชนิดนี้ปล่อยหมอกออกมาเป็นครั้งคราว ซึ่งกล่าวกันว่าสามารถป้องกันผู้ที่คิดจะหาอาหารได้",
  str_item_intro_5424462 = "พืชสกุลหายากของ Misty Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ผลไม้สีเขียวสดมีรสเปรี้ยวและกลิ่นฉุนมาก ทำให้หลายคนเชื่อว่ามีพิษ ในความเป็นจริงผลไม้มีความปลอดภัยอย่างสมบูรณ์ในการรับประทาน",
  str_item_intro_5424463 = "พืชสกุลหายากของ Misty Strangefruit Tree ที่ผสมพันธุ์กับ Rose Crystalloids ส่วนที่เป็นเนื้อของผลไม้สีน้ำเงินได้ผ่านการเปลี่ยนแปลงอย่างลึกลับ ซึ่งทำให้มีความยืดหยุ่นและยืดหยุ่นสูง แม้ถูกรถชนหนักทับ ผลไม้ชนิดนี้จะกลับคืนสู่สภาพเดิมอย่างรวดเร็ว...",
  str_item_intro_5424471 = "ต้นไม้สกุล Strangefruit หายากซึ่งผ่านการกลายพันธุ์ที่ซับซ้อน ผลไม้แบ่งออกเป็นสองส่วน - ส่วนหลักของผลไม้นั้นจริงๆ แล้วมีเปลือกหนาปิดไว้ ในขณะที่ผลที่ส่องแสงห้อยลงมาจากปลายกิ่งว่ากันว่าเป็นผลมาจากการกลายพันธุ์ของทรงพุ่ม! อย่างไรก็ตาม รูปร่าง กลิ่น และรสชาติของผลไม้แทบไม่ช่วยยืนยันทฤษฎีนี้...",
  str_item_intro_5424472 = "พืชสกุลหายากของต้นไม้ Sparkling Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids กล่าวกันว่าแสงสีฟ้าของมันมีกลิ่นเหมือนมหาสมุทร จนได้รับสมญานามว่า \"ทูตแห่งลมทะเล\" อย่างไรก็ตาม คนอื่นๆ อ้างว่านี่เป็นเพียงผลหลอนประสาทที่เกิดจากกลิ่นของผลไม้",
  str_item_intro_5424473 = "พืชสกุลหายากของต้นไม้ Sparkling Strangefruit ที่ผสมพันธุ์กับ Rose Crystalloids แสงสีเขียวอ่อนๆ ที่ปล่อยออกมาจากผลมีผลทำให้สงบ ซึ่งน่าจะทำให้แม้แต่สัตว์ที่ดุร้ายที่สุดก็ยอมเชื่องเมื่อเข้าใกล้ เรื่องนี้จริงหรือไม่ยังไม่ได้รับการยืนยัน",
  str_item_intro_5425111 = "ต้นไม้ยูนิคนี้แตกต่างจากต้นไม้อื่นเสมอ อันที่จริงต้องสงสัยว่ามันสามารถนับเป็นต้นไม้ได้หรือไม่... จากการวิจัยของนักวิชาการหลายคน แท้จริงแล้วมันคือต้นไม้ ดังนั้นจึงกล่าวได้ว่าเป็นต้นไม้ที่มีเอกลักษณ์เฉพาะซึ่งดูและให้ความรู้สึกที่ยอดเยี่ยมอย่างแท้จริง",
  str_item_intro_5425112 = "ต้นเห็ดแดงที่ผสมพันธุ์กับโรสคริสตัลลอยด์ เรือนยอดสีแดงทำให้ผู้คนรู้สึกกระสับกระส่ายและกระสับกระส่าย จึงอาจไม่ใช่ต้นไม้ที่ดีที่สุดที่จะนั่งใต้ร่มเงา",
  str_item_intro_5425113 = "ต้นเห็ดสีน้ำเงินที่ผสมพันธุ์กับโรสคริสตัลลอยด์ หลังคาสีน้ำเงินสร้างภาพลวงตาของท้องฟ้าอันกว้างใหญ่ บางคนบอกว่าพวกเขาได้กลิ่นหอมของเมฆที่อยู่ข้างใต้",
  str_item_intro_5425211 = "ต้นเห็ด II ที่ผ่านการกลายพันธุ์เล็กน้อย เรือนยอดได้ผ่านการเปลี่ยนแปลงหลายอย่าง ทำให้อ่อนและแกร่งในเวลาเดียวกัน และกิ่งก้านห้อยต่ำเนื่องจากน้ำหนักของมัน ทำให้เกิดภาพลวงตาของซุ้มประตู หากคุณเพิ่มคานไม้สำหรับรองรับและตั้งกำแพง คุณอาจแปลงบ้านหลังนี้เป็นบ้านหลังเล็กได้",
  str_item_intro_5425212 = "สกุลของ Fuzzy Mushroom Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อย ได้รับการผสมพันธุ์กับ Rose Crystalloids ด้านในหลังคาเป็นสีฟ้าซึ่งสร้างภาพลวงตาเหมือนอยู่ในทะเล",
  str_item_intro_5425213 = "สกุลของ Fuzzy Mushroom Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อย ได้รับการผสมพันธุ์กับ Rose Crystalloids ข้างในสีแดงของหลังคานั้นน่ากลัวสำหรับบางคน มีข่าวลือว่าต้นไม้นี้มีพิษด้วย อย่างไรก็ตาม นี่เป็นคำพูดของผู้มีอคติ",
  str_item_intro_5425221 = "ต้นเห็ด II ที่ผ่านการกลายพันธุ์เล็กน้อย ด้วยลำต้นที่หนาและทรงพุ่มที่หดลง ต้นไม้ชนิดนี้ให้ความรู้สึกเหมือนถังน้ำ และลำต้นที่หนาของมันสามารถดูดซับน้ำและกักเก็บไว้ได้ ซึ่งเป็นเหตุผลว่าทำไมจึงเรียกมันว่าเห็ดน้ำ",
  str_item_intro_5425222 = "สกุลของ Stoic Mushroom Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อย ได้รับการผสมพันธุ์กับ Rose Crystalloids แม้ว่าจะเป็นสีแดง แต่น้ำที่กักเก็บไว้ภายในก็ไม่ได้รับผลกระทบ คุณสามารถได้ยินเสียงน้ำไหลภายในได้หากคุณเข้าไปใกล้พอ",
  str_item_intro_5425223 = "สกุลของ Stoic Mushroom Tree ซึ่งผ่านการกลายพันธุ์เล็กน้อย ได้รับการผสมพันธุ์กับ Rose Crystalloids บางคนเรียกหลังคาสีน้ำเงินว่า \"หลังคามหาสมุทร\" เนื่องจากได้รับผลกระทบจากน้ำที่กักเก็บไว้ภายใน บางคนบอกว่าคุณจะได้ยินเสียงคลื่นกระทบฝั่งจากลำต้นหนาหากคุณยืนบนหลังคาแล้วเอาหูแนบ",
  str_item_intro_5425311 = "ต้นเห็ด II ที่มีการกลายพันธุ์บ่อยครั้ง หลังคายังคงขนาดเดิมไว้และหนาขึ้นกว่าเดิม แถมยังหอมชื่นใจ...",
  str_item_intro_5425312 = "สกุลหายากของ Enticing Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids เนื่องจากหลังคาเป็นสีฟ้าทั้งหมด คุณจะรู้สึกเหมือนอยู่ก้นทะเลน้ำตื้นแม้ว่าคุณจะจ้องมองจากระยะไกลก็ตาม",
  str_item_intro_5425313 = "สกุลหายากของ Enticing Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids เรือนยอดสีแดงสดเป็นที่ดึงดูดใจอย่างมากสำหรับบางคน และมีพลังวิเศษที่ดึงดูดผู้ชมให้เข้ามาใกล้ขึ้นเรื่อยๆ อย่างไรก็ตาม ไม่มีเหตุผลที่เป็นอันตรายสำหรับสิ่งนี้ และไม่มีใครรู้ว่าทำไมมันถึงมีผลกระทบนี้",
  str_item_intro_5425321 = "ต้นเห็ด II ที่มีการกลายพันธุ์บ่อยครั้ง ไม่เพียงแต่มีขนาดเล็กลงเท่านั้น แต่ยังเริ่มเติบโตเป็นกระจุกอีกด้วย โชคดีที่มันมีรูปร่างเหมือนกันเป็นส่วนใหญ่ ลักษณะเด่นที่สุดของมันคือหลังคาที่ส่องประกายแวววาวด้วยแสงทุกประเภท สร้างฉากชวนฝันเมื่อแสงกระทบกับแป้งที่ฟุ้งกระจายในอากาศ",
  str_item_intro_5425322 = "สกุลที่หายากของต้นเห็ดแลมเบนต์ที่ผสมพันธุ์กับโรสคริสตัลลอยด์ สีแดงที่ลุกโชนของต้นไม้ต้นนี้ทำให้ท้องฟ้าดูเหมือนทะเลเพลิง ในขณะที่จุดสว่างนั้นถูกเข้าใจผิดว่าเป็นประกายไฟ ด้วยเหตุนี้ต้นไม้ชนิดนี้จึงถูกเรียกว่าเห็ดเผาะ",
  str_item_intro_5425323 = "สกุลที่หายากของต้นเห็ดแลมเบนต์ที่ผสมพันธุ์กับโรสคริสตัลลอยด์ หลังคาสีม่วงดูน่ารักและยังปล่อยฝุ่นเรืองแสงที่กล่าวกันว่ามีเสน่ห์มาก นักวิชาการบางคนยังอ้างว่าต้นไม้นี้เป็นตัวแปรหรือญาติห่างๆ ของต้นเห็ดล่อลวง แต่นี่เป็นเพียงการคาดเดา",
  str_item_intro_5425331 = "ต้นเห็ด II ที่มีการกลายพันธุ์บ่อยครั้ง ลำต้นของต้นไม้นี้เติบโตอย่างคดเคี้ยวและมีหลังคาสองอัน นักวิชาการบางคนสันนิษฐานว่าต้นไม้ต้นนี้ดูดน้ำในปริมาณที่มากเกินไปเพื่อให้เรือนยอดทั้งสองยังคงมีชีวิตอยู่ได้ ซึ่งทำให้น้ำถูกขับออกจากเรือนยอดและตกลงมาเหมือนเม็ดฝน",
  str_item_intro_5425332 = "สกุลหายากของ Moist Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids หยาดฝนที่ตกจากต้นนี้เป็นสีเหลืองล้วนสร้างบรรยากาศยามอาทิตย์อัสดง เมื่อเม็ดฝนโปรยปรายลงมาอย่างรวดเร็ว ราวกับว่าต้นไม้ถูกห่อหุ้มด้วยม่านฝนยามอาทิตย์อัสดง",
  str_item_intro_5425333 = "สกุลหายากของ Moist Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids ต้นไม้นี้มีลักษณะคล้ายกับสัตว์ทะเลเนื่องจากมีสีฟ้า และเม็ดฝนที่ตกลงมาจากต้นไม้นี้เป็นเหมือนคลื่นสีฟ้าที่กระเซ็น ดังนั้นมันจึงถูกเรียกว่าเป็นผู้ควบคุมน้ำทะเล",
  str_item_intro_5425341 = "ต้นเห็ด II ที่มีการกลายพันธุ์บ่อยครั้ง มีลักษณะเด่นคือกิ่งอ่อนที่ร่วงหล่น เมื่อมองแวบแรก ต้นไม้นี้ดูเหมือนเคราของผู้อาวุโสที่ฉลาด ดังนั้นจึงเรียกอีกอย่างว่าเห็ดที่ฉลาด",
  str_item_intro_5425342 = "พืชสกุลหายากของ Lush Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids หนวดเคราสีเหลืองทำให้ต้นไม้นี้ดูฉลาดขึ้น และบางคนอ้างว่าต้นไม้นี้มีแสงคุ้มครอง เมื่อลมพัดผ่านลำต้นที่ยืดหยุ่นได้ ดูเหมือนว่าแสงแดดส่องผ่านช่องว่าง",
  str_item_intro_5425343 = "พืชสกุลหายากของ Lush Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids ลำต้นสีเขียวที่ยืดหยุ่นดูเหมือนเถาองุ่น ผู้ที่ชื่นชอบร่มเงาและวิวใต้ร่มไม้จะรู้สึกเหมือนอยู่ในป่าดิบชื้น",
  str_item_intro_5425411 = "Mushroom Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน เมื่อมองจากมุมใดมุมหนึ่ง หลังคาจะค่อนข้างโปร่งแสงเมื่อมองจากมุมต่างๆ เมื่อเติบโตจนมีขนาดใหญ่และบางมาก โดยธรรมชาติแล้ว หลายคนบอกว่าความรู้สึกโปร่งแสงนี้ไม่ได้มาจากเรือนยอดไม้ที่บาง แต่มาจากอากาศเย็นที่แผ่ออกมาจากต้นไม้ตลอดเวลา และทำให้นึกถึงน้ำแข็งใส",
  str_item_intro_5425412 = "สกุลหายากของ Diluted Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids หลังคาสีเหลืองและสายลมเย็นเป็นครั้งคราวสร้างภาพลวงตาของความรู้สึกหนาวเย็นแม้อยู่ภายใต้แสงแดดที่แผดเผา ดังนั้นบางคนจึงเรียกต้นไม้นี้ว่า \"ต้นไม้มหัศจรรย์แห่งดินแดนอาทิตย์เยือกแข็ง\"",
  str_item_intro_5425413 = "สกุลหายากของ Diluted Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids เรือนยอดสีแดงแวววาวและความรู้สึกโปร่งแสงเป็นธรรมชาติทำให้ผู้คนสงสัยว่านี่เป็นงานศิลปะที่มนุษย์สร้างขึ้นแทนที่จะเป็นการสร้างของธรรมชาติหรือไม่",
  str_item_intro_5425421 = "Mushroom Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน แม้ว่าเรือนยอดของต้นไม้ต้นนี้จะดูธรรมดา แต่บางครั้งก็ปล่อยลมออกมาซึ่งสร้างภาพลวงตาว่ากำลังหายใจอยู่ ต้นไม้ชนิดนี้ส่วนใหญ่อาศัยอยู่เป็นกลุ่มและสร้างหมอกจางๆ เมื่อพวกมันทั้งหมดปล่อยลมออกมาทีละตัว จึงเป็นที่มาของชื่อ",
  str_item_intro_5425422 = "สกุลหายากของ Misty Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids เมื่อเรือนยอดสีแดงของต้นไม้นี้หายใจ รูเล็กๆ ที่เปิดและปิดเป็นระยะๆ ทำให้ผู้คนนึกถึงบาดแผล นอกจากนี้ การระเบิดของอากาศที่ปล่อยออกมายังสร้างความประทับใจให้กับละอองเลือดในบางช่วงเวลา ทำให้ได้ชื่อผู้หวนคืนสนามรบที่น่าเศร้า",
  str_item_intro_5425423 = "สกุลหายากของ Misty Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids หมอกที่ปล่อยออกมาจากเรือนยอดสีฟ้าทำให้ผู้ชมนึกถึงฤดูหนาว ทำให้หลายคนเข้าใจผิดว่าต้นไม้ต้นนี้มาจากนอร์ธแลนด์ แต่ทั้งหมดนั้นผิด เนื่องจากลมที่ปล่อยออกมาจากต้นไม้นี้ค่อนข้างอุ่นและไม่เย็นเลย",
  str_item_intro_5425431 = "Mushroom Tree IV ที่ผ่านการกลายพันธุ์อย่างซับซ้อน เรือนยอดโตขึ้นมากจนสงสัยว่าลำต้นจะรับน้ำหนักไหวไหม เนื่องจากหลังคามีขนาดใหญ่เกินไป จึงปิดกั้นการมองเห็นท้องฟ้าทั้งหมดสำหรับผู้ที่อยู่ภายใต้หลังคา ด้วยเหตุนี้บางคนจึงเรียกมันว่าต้นไม้ที่ปกคลุมท้องฟ้า",
  str_item_intro_5425432 = "สกุลหายากของ Dome Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids ในบางครั้ง เรือนยอดสีเขียวส่งกลิ่นหอมของพืชน้ำ ทำให้ผู้พบเห็นเห็นภาพลวงตาว่าอยู่ติดกับแหล่งน้ำ ว่ากันว่าต้นไม้ชนิดนี้ให้สารอาหารแก่พืชน้ำในบริเวณใกล้เคียงให้เจริญเติบโต แต่ไม่มีใครยืนยันเรื่องนี้",
  str_item_intro_5425433 = "สกุลหายากของ Dome Mushroom Tree ที่ผสมพันธุ์กับ Rose Crystalloids เรือนยอดสีแดงสดสร้างภาพลวงตาของการเก็บเกี่ยวที่ดี และบางคนถึงกับกล่าวว่าได้กลิ่นหอมหวานของผลไม้ที่อยู่รอบๆ อย่างไรก็ตาม ต้นไม้ยูนิคนี้กินไม่ได้โดยสิ้นเชิง โดยเฉพาะทรงพุ่มซึ่งปรุงยากและไม่มีคุณค่าทางโภชนาการ",
  str_item_intro_5510001 = "ร่างกายที่อ้วนท้วนไม่ใช่อุปสรรคต่อการอยู่รอดเพราะมีท้องที่ใหญ่เต็มไปด้วยสารพิษร้ายแรง อย่างไรก็ตาม เนื้อที่แสนอร่อยของมันยังคงดึงดูดนักชิมมากมายที่ไม่กลัวความตาย",
  str_item_intro_5510002 = "ขึ้นชื่อเรื่องสีสันที่สดใส มีจำนวนมาก และเนื้อนุ่ม จึงครองโต๊ะอาหารได้",
  str_item_intro_5510003 = "ได้ชื่อมาจากรูปร่างที่เรียวยาวและมีรูปร่างเหมือนมีด และเคลื่อนที่เป็นกลุ่มเสมอ",
  str_item_intro_5510004 = "ปลาตัวผอมที่มีครีบเล็กมากซึ่งมองแวบแรกก็ดูเหมือนงูจริง ๆ มันชอบซ่อนตัวอยู่ในโขดหินใต้น้ำ และพุ่งออกไปทำให้คนตกใจ",
  str_item_intro_5510005 = "เป็นปลาที่ชอบอาศัยอยู่ในน้ำใส มีมากมายและกระจายอยู่ทั่วไป พบเจอได้ในหลาย ๆ ที่",
  str_item_intro_5510006 = "กล่าวกันว่าปลาชนิดนี้เป็นสัตว์นักล่าที่เก่งกาจในน้ำ แต่เนื่องจากเนื้อที่อร่อย มันจึงตกเป็นเป้าหมายของนักชิม และตอนนี้ได้กลายเป็น \"เมนูปกติ\" ในงานเลี้ยงระดับสูง",
  str_item_intro_5510007 = "ปลาร่างเรียวที่รวมตัวกันตามริมฝั่งแม่น้ำไม่ว่าในยามพักผ่อนหรือล่องน้ำ อาหารของมันคือสิ่งมีชีวิตเล็ก ๆ ทั้งหลายในน้ำ ไม่เพียงแต่กินเนื้อได้ น้ำมันปลาของมันยังใช้ทำสีต่าง ๆ ได้อีกด้วย",
  str_item_intro_5510008 = "ชอบเคลื่อนที่ไปเป็นฝูงและมีจำนวนมาก มันมีนิสัยรุนแรงและชอบที่จะกระแทกหัวใส่ศัตรูในการต่อสู้ที่ดุเดือดเหมือนหอก เนื้อมาไคระจะแน่น เกล็ดเล็ก ๆ ตากแห้งทำเป็นขนมกินเล่นได้",
  str_item_intro_5520001 = "เต่าที่ว่ายน้ำอย่างเชื่องช้า แทบจะเดินขึ้นฝั่งไม่ได้ อาจเป็นเพราะมันเดินช้ามาก จึงมีเปลือกแข็งอยู่ด้านหลัง ซึ่งใช้ป้องกันศัตรู",
  str_item_intro_5520002 = "สิ่งมีชีวิตในน้ำที่หายากนี้เติบโตในน้ำที่เย็นจัด และมักจะพบอาศัยอยู่ใต้ทะเลที่กลายเป็นน้ำแข็ง ร่างกายของมันโปร่งใส และมีสีสันที่สวยงามหลากหลาย และมีรยางค์คล้ายปีก จึงเป็นที่มาของชื่อ ภาพหายากในน้ำอุ่น เป็นไปได้มากว่าพวกมันหลงทาง...",
  str_item_intro_5520004 = "สัตว์น้ำเหล่านี้มีลำตัวแบนและว่ายน้ำได้ช้ามาก พวกเขาชอบที่จะสำรวจและพักผ่อนตามก้นแม่น้ำและลำธาร เนื่องจากมีจุดสวยงามมากมายบนหลัง ชาวประมงมักเข้าใจผิดว่าเป็นจุดไข่มุกกลุ่มใหญ่เมื่อมองลงไปในแม่น้ำและลำธาร จึงเป็นที่มาของชื่อนี้",
  str_item_intro_5520005 = "สิ่งมีชีวิตที่ชอบคลานใต้คลื่นและเป็นที่รู้จักจากรูปร่างที่เป็นเอกลักษณ์ ว่ากันว่าเมื่อแรกพบผู้คนคิดว่าเป็นสาหร่ายหรือปะการังชนิดแปลกๆ พวกเขาไม่รู้ว่ามันมีชีวิตจนกระทั่งมันเริ่มเคลื่อนไหวอย่างช้าๆ...",
  str_item_intro_5520006 = "ปลามหัศจรรย์ที่ชอบอาศัยอยู่ท่ามกลางสาหร่าย ปะการัง หรือแม้แต่ดอกไม้ทะเล มีลักษณะที่สดใสและใบหน้าตลกที่ทำให้ผู้ที่พบเห็นหัวเราะ บางคนให้ความเห็นว่าต้นไม้น้ำเต้นเมื่อใดก็ตามที่ปลาชนิดนี้อยู่ใกล้ ๆ ดังนั้นชื่อของมัน",
  str_item_intro_5520007 = "นี่น่าจะเป็นสิ่งมีชีวิตในน้ำที่เพิ่งค้นพบ ด้วยผิวหนังที่เรียบเนียนและกล้ามเนื้อที่อ่อนนุ่ม มันว่ายน้ำผ่านความลึกของมหาสมุทรด้วยอาการอิดโรยสง่างามซึ่งทำให้มันได้รับความนิยมอย่างรวดเร็วในหมู่ผู้สนใจรักสัตว์ มีคนบอกว่าผู้ชื่นชมบางคนจะรู้สึกมีความสุขทางร่างกายและจิตใจเมื่อใดก็ตามที่พวกเขาเห็นมันล่องเรือไปอย่างไร้จุดหมายในน้ำ สะบัดความกังวลและความขัดแย้งออกไปด้วยคลื่นหนวดของมัน",
  str_item_intro_5520016 = "ปลาชนิดนี้ชอบอาศัยอยู่ในผืนน้ำกว้างใหญ่ และเคยปรากฏตัวที่นี่... ผู้คนเคยกลัวมันเนื่องจากตัวสีดำและรูปร่างที่แปลกประหลาด แต่จริงๆแล้วมันอ่อนโยนมากและชอบว่ายน้ำสบายๆ ในน้ำ มันหลีกเลี่ยงที่จะหลีกเลี่ยงสัตว์น้ำขนาดเล็กอื่น ๆ ที่มันพบด้วยซ้ำ",
  str_item_intro_5520101 = "ด้วยสีสันที่สดใส ปลาไหลมาร์เบิลสีแดงขาวจึงกลายเป็นหนึ่งในปลาสวยงามที่ทรงคุณค่าที่สุด ไม่เพียงแต่มีชื่อเล่นว่า \"อัญมณีที่มีชีวิตในน้ำ\" แต่ยังกล่าวกันว่าจะนำโชคดีมาสู่ผู้เพาะพันธุ์อีกด้วย",
  str_item_intro_5520102 = "ปลาไหลมาร์เบิลสามสีเป็นที่รักของคนนับล้านเนื่องจากมีรูปแบบที่หลากหลายและถูกเรียกว่า \"ปลาที่สง่างาม\" เห็นทีไรก็สบายใจ หลายคนคิดว่าสามารถนำความสามัคคีมาสู่ครอบครัวได้",
  str_item_intro_5520103 = "ปลาสวยงามระดับสูง เป็นที่รู้จักในฐานะ \"ศิลปะที่ว่ายน้ำได้\" เนื่องจากการว่ายน้ำที่สง่างาม กล่าวกันว่าสามารถขจัดภัยพิบัติในอนาคตสำหรับผู้เพาะพันธุ์ได้",
  str_item_intro_5520104 = "ปลาไหลมาร์เบิลสีดำและสีขาวมีอารมณ์อ่อนโยนและมีลวดลายที่เป็นธรรมชาติ เป็นมิตรกับผู้คนโดยเฉพาะเด็ก ๆ ดังนั้นบางคนเชื่อว่าสามารถอวยพรให้เด็กเติบโตได้อย่างราบรื่น",
  str_item_intro_5520105 = "เกล็ดของมันส่องแสงสีทองงดงามภายใต้แสงแดด ดังนั้นเชื่อกันว่าปลาไหลมาร์เบิลสีทองจะนำมาซึ่งโชคลาภ และนักธุรกิจจำนวนมากต้องการเก็บปลาไหลเหล่านี้ไว้สองสามตัว",
  str_item_intro_5520201 = "ปลาสวยงามนี้ส่องแสงสีแดงในน้ำ เกล็ดของมันเด่นชัดมากจนเกือบจะทำให้ผิวของน้ำเป็นสีชมพู ทำให้เกิดภาพที่งดงาม",
  str_item_intro_5520202 = "แม้ว่าจะดู \"ชั่วร้าย\" เล็กน้อย แต่เกล็ดสีเลือดของมันจะเป็นสีแดงสดภายใต้แสงแดด ทำให้ผู้คนรู้สึกราวกับว่าปลานี้สวมเกราะที่ทำด้วยทับทิม",
  str_item_intro_5520203 = "ระยิบระยับด้วยเกล็ดสีน้ำเงิน ให้ความรู้สึกเย็นสบายอย่างอธิบายไม่ถูกเมื่อว่ายอย่างช้า ๆ ในน้ำ โดยเฉพาะอย่างยิ่งในช่วงกลางฤดูร้อน",
  str_item_intro_5520204 = "เกล็ดสีทองที่ประณีตทำให้ดูเหมือนนายพลในตำนาน และท่าทางการว่ายน้ำของมันก็ยิ่งใหญ่จนปลาตัวเล็กที่อยู่รอบ ๆ ต้องถอยหนีต่อหน้ามัน",
  str_item_intro_5520205 = "เมื่อเปรียบเทียบกับตัวอื่น ๆ ในคลาส มันดูสง่างามและสงบ เกล็ดสีขาวสีเงินและรูปทรงที่เพรียวบางทำให้มีกลิ่นอายของชนชั้นสูง",
  str_item_intro_5520301 = "ด้วยลำตัวแบนราบและมีสีสันตระการตา ปลาตัวนี้เปรียบเสมือนผีเสื้อที่ตกลงไปในน้ำอย่างสง่างาม",
  str_item_intro_5520302 = "ปลาสวยงามที่มีหัวสีขาวและลำตัวเป็นสีดำเป็นส่วนใหญ่ มันมีนิสัยอ่อนโยน หากสังเกตดี ๆ จุดแยกขาวดำจะต่างกันเล็กน้อย เรียกได้ว่าปลาผีเสื้อสีดำแต่ละตัวมีเอกลักษณ์เฉพาะตัว",
  str_item_intro_5520303 = "มีลำตัวสีเหลืองและสีขาวซึ่งแบ่งออกเป็นสามส่วนขนาดใหญ่จึงเป็นที่มาของชื่อ มีเสียงดังและชอบแกล้งปลาอื่น ดังนั้นน้ำจะมีชีวิตชีวาด้วยการปรากฏตัวของมัน",
  str_item_intro_5520304 = "ด้วยรูปลักษณ์ที่สวยงามของสีน้ำเงิน ความแวววาวของปลาสวยงามนี้จึงแตกต่างกันอย่างมาก เป็นปลาขี้อายและไม่ชอบแสดงออก มักซ่อนตัวอยู่ท่ามกลางโขดหินและพืชน้ำ จึงมีชื่อเล่นว่า \"สาวขี้อาย\"",
  str_item_intro_5520401 = "ด้วยสีสันที่สดใสและดวงตาที่โตและเต็มไปด้วยจิตวิญญาณ ทำให้ปลาชนิดนี้ชอบเข้าใกล้ปลาอื่น ๆ และมักถูกปฏิเสธ ทำให้เป็น \"ผีเสื้อแห่งสังคม\" ของปลาสวยงาม",
  str_item_intro_5520402 = "จุดด่างบนหลังทำให้มันได้ชื่อนี้ และถ้าจับคู่กับพืชน้ำที่มีสีคล้ายกัน... มันจะเป็นสีปกป้องตามธรรมชาติ ดังนั้นเมื่อตกแต่งเราต้องใส่ใจกับการจัดสีให้เข้ากับสิ่งแวดล้อมเพื่อมองเห็นมันได้อย่างชัดเจน",
  str_item_intro_5520403 = "ลำตัวส่วนใหญ่เป็นสีดำ และมีครีบสีเหลืองและขาวที่ด้านหลัง มีอารมณ์สงบ แต่เมื่อโกรธมันจะต่อสู้จนถึงที่สุด เหมือนกับหนาม... ดังนั้นอย่าแตะต้องมัน",
  str_item_intro_5520501 = "น้อยคนนักที่จะมีปลาสวยงามนี้เพราะมัน... น่าเกลียดจริง ๆ มีเพียงเคราที่ส่องแสงเท่านั้นที่ทำให้ดูแตกต่าง",
  str_item_intro_5520502 = "ปลาตกเบ็ดสีขาวดูเหมือนจะน่าพิสมัยกว่ามาก แต่แสงของปลานี้ก็ดูริบหรี่กว่าเช่นกัน บางทีอาจเป็นเรื่องของสีที่ตัดกัน",
  str_item_intro_5520601 = "ว่ากันว่าม้าน้ำชนิดนี้อาศัยอยู่ในทะเลลึกมาก ไม่มีใครรู้ว่ามันมาที่นี่ทำไม เนื่องจากเคยชินกับการอาศัยอยู่ในทะเลลึก จึงมักจะซุกซ่อนตัวอยู่ใต้น้ำและหาได้ยาก\nปกติจะซ่อนตัวไม่ให้ใครเห็น และจะปรากฏตัวเมื่อมีลูมินาอยู่ใกล้ ๆ เท่านั้น แต่ถ้าลูมินาแข็งแกร่งเกินไป มันก็จะกลัวจนหนีไปเลย",
  str_item_intro_5520602 = "ม้าน้ำตัวนี้ชอบอาศัยอยู่ในช่องว่างระหว่างก้อนหินในลำธาร ที่เรียกชื่อนี้เพราะมันเคลื่อนที่เร็วมาก ทำให้คนคิดว่าก้อนหินถูกย้อมเป็นสีเหลือง\nปกติจะซ่อนตัวไม่ให้ใครเห็น และจะปรากฏตัวเมื่อมีลูมินาอยู่ใกล้ ๆ เท่านั้น แต่ถ้าลูมินาแข็งแกร่งเกินไป มันก็จะกลัวจนหนีไปเลย",
  str_item_intro_5520603 = "ม้าน้ำสีขาวมักอาศัยอยู่ในแม่น้ำและลำธาร สีผิวของพวกมันคือการปกป้องตามธรรมชาติ และรูปแบบการว่ายน้ำในแนวดิ่งช่วยให้พวกมันซ่อนตัวในฟองอากาศใต้น้ำ หลบเลี่ยงศัตรูตามธรรมชาติได้ดี\nปกติจะซ่อนตัวไม่ให้ใครเห็น แต่เนื่องจากมีความไวต่อลูมินาต่ำ จึงจะปรากฏตัวเมื่อถูกลูมินาที่แข็งแกร่งกว่าดึงดูดเท่านั้น แต่ถ้าลูมินาแข็งแกร่งเกินไป มันก็จะกลัวจนหนีไปเลย",
  str_item_intro_5520701 = "สิ่งมีชีวิตใต้น้ำที่ชอบอาศัยอยู่ตามคุ้งแม่น้ำ มันดูดุร้ายมากเพราะมีรยางค์มากมาย แต่ว่านี่เป็นแค่รูปโฉมภายนอกเท่านั้น เพราะที่จริงแล้วมันเชื่องมาก และอาศัยอยู่อย่างสันโดษกลางดงสาหร่าย ทำให้หาตัวได้ยาก",
  str_item_intro_5520702 = "ชอบอาศัยอยู่ตามคุ้งแม่น้ำที่มีน้ำใส และอำพรางร่างกายส่วนใหญ่ไว้กับสันทรายสีเหลือง เนื่องจากสีผิวค่อนข้างจะกลมกลืนกับสีของทรายจนสัตว์อื่นมองแทบไม่เห็น ทำให้ง่ายต่อการซุ่มโจมตีสัตว์อื่นอย่างมาก",
  str_item_intro_5520801 = "อย่าหลงกลโดยขนาดที่เล็กอย่างไม่น่าเชื่อ มีน้ำหนัก 1 กิโลกรัม และเป็นปลาคาร์ปหัวโตที่เล็กที่สุดในโลก ตัวเล็กและธรรมดาอย่างที่เห็น ปลาตัวเล็กตัวนี้มีศักยภาพในการเจริญเติบโตมหาศาล...",
  str_item_intro_5520802 = "Bighead Carp ที่ใหญ่กว่าเล็กน้อย ด้วยน้ำหนักเพียง 5 กิโลกรัม จับได้ยากกว่ามาก แม้จะมีสีสันสดใสกว่าก็ตาม ดูเหมือนว่าน้ำหนักที่มากขึ้นจะมาพร้อมกับความตื่นตัวที่มากขึ้น",
  str_item_intro_5520803 = "ปลาคาร์พหัวโต 10 กิโล ด้วยร่างกายที่กลมโตและเต็มอิ่ม ดวงตาที่โปนของมันดูเหมือนกำลังพูดว่า \"ฉันโตขึ้นได้อีกนะ รู้ไหม!\"",
  str_item_intro_5520804 = "ปลาคาร์ปหัวโตที่แข็งแรงที่สุด เข้าได้ 20 กก. มันล่องลอยไปอย่างช้าๆและสงบสุขในน้ำ เติมผู้ดูด้วยความรู้สึกสงบที่ลึกซึ้งอย่างลึกลับ",
  str_item_intro_5520805 = "ปลาคาร์พหัวโตที่หนักถึง 50 กิโลกรัม! ราชาในหมู่ปลาคาร์พ ท้องของมันดูเหมือนจะเป็นที่มาของเส้นรอบวงที่น่าประทับใจ โดยธรรมชาติแล้วปลาขนาดนี้จะค่อนข้างก้าวร้าว สิ่งมีชีวิตใต้น้ำอื่นๆ มักจะหลีกเลี่ยง",
  str_item_intro_5520806 = "ปลาคาร์พหัวโตตัวนี้มีขนาดพอเหมาะ แต่ความนิยมของมันมาจากตัวมันที่ปิดทองอย่างยอดเยี่ยม ซึ่งปกคลุมไปด้วยเกล็ดรูปดาวที่แวววาว การมีอยู่ของปลาที่น่าเกรงขามเช่นนี้จะต้องเป็นของขวัญจากพระเจ้าอย่างแท้จริง",
  str_item_intro_5520811 = "แม้ว่ามันอาจจะดูเหมือนสัตว์น้ำที่ดุร้ายและดุร้ายมาก แต่ก้ามปูของมันใช้สำหรับเคลื่อนย้ายสิ่งกีดขวาง เช่น ก้อนหินและพืชน้ำที่ขัดขวางไม่ให้มันไปทำธุรกิจได้ ในความเป็นจริง การใช้กรงเล็บเหล่านี้ในการต่อสู้เป็นเพียงหน้าที่รองเท่านั้น เนื่องจากสัตว์ชนิดนี้มีความอ่อนโยนมาก และจะทำหน้าดุดันอย่างไม่เกรงกลัวเมื่อต้องป้องกันตัวเท่านั้น",
  str_item_intro_5520812 = "สิ่งมีชีวิตชนิดนี้เป็นที่รู้จักจากการซ่อนตัวอยู่ท่ามกลางโขดหินใต้น้ำ เนื่องจากมันชอบแบกหินเพื่อสร้าง \"ปราสาท\" ของมันเอง และซุ่มโจมตีสิ่งมีชีวิตที่โชคร้ายหรือแค่อยากรู้อยากเห็นเพื่อหาอาหารมื้อใหญ่ให้ตัวเอง",
  str_item_intro_5520014 = "ปลาหมึกชนิดนี้มีชื่อเสียงจากวงแหวนสีน้ำเงินบนลำตัว ไม่ค่อยพบเห็นในแม่น้ำ แต่เมื่อมันปรากฏขึ้น สัตว์น้ำจำนวนมากก็หลบหน้ามัน สาเหตุหลักมาจากพิษที่ทรงพลังในตัวของมันที่กล่าวกันว่าสามารถฆ่าได้ด้วยหยดเดียว พิษของมันคือเหตุผลว่าทำไมมันจึงสะดุดตาและไม่กลัวที่จะดึงดูดความสนใจของสิ่งมีชีวิตอื่น",
  str_item_intro_5520901 = "ปลาหายากอย่างยิ่งที่โดดเด่นด้วยลำตัวสีสันสดใสสวยงาม ตลอดจนโครงที่เล็กแต่ว่องไว ตื่นตัวอย่างไม่น่าเชื่อ มันสามารถซ่อนสีของมันไว้ที่สัญญาณแรกของการเคลื่อนไหวในบริเวณใกล้เคียง การจับปลาที่เข้าใจยากเช่นนี้จึงไม่ต้องใช้ความอดทนและความมุ่งมั่นเพียงเล็กน้อย อย่างไรก็ตาม การทำงานหนักของคนๆ หนึ่งจะได้ผลทันทีเมื่อเห็น \"ริบบิ้น\" หลากสีสันที่ลอยอย่างสง่างามในน้ำ",
  str_item_intro_5530001 = "ส้มหล่น! หอยนางรมนี้มีไข่มุกอยู่ด้วย ดูดีทั้งสีและรูปทรงและสามารถขายได้ราคาดี",
  str_item_intro_5530101 = "กระป๋องเก่า ๆ ไม่รู้ว่าใครเป็นคนโยนลงน้ำ แต่ที่แน่ ๆ คือเขาไม่ใส่ใจที่จะปกป้องสิ่งแวดล้อมเลย...",
  str_item_intro_5530201 = "รองเท้าคู่นี้คง \"มีชีวิตอยู่\" ในน้ำมาหลายปีแล้ว และแม้แต่สาหร่ายก็ยังยึดมันเป็นบ้าน",
  str_item_intro_5601101 = "วันหนึ่งฉันจะปกป้องบ้านเกิดของฉันได้ภายใต้ท้องฟ้าอันยิ่งใหญ่",
  str_item_intro_5601201 = "ฉันหวังว่าฉันจะเข้าใจพลังอันน่าทึ่งที่ส่งผ่าน Colossus...",
  str_item_intro_5602101 = "ความทรงจำคงอยู่ชั่วชีวิต แต่บันทึกอยู่ได้เป็นพันปี ฉันจะจดจำ จดบันทึก และเก็บมันไว้จนกว่าจะมีคนมาพบเจอ",
  str_item_intro_5602201 = "ฉันสาบานว่าจะหาพิมพ์เขียวเหล่านั้นให้พบ แม้จะต้องเดินทางไปจนสุดหล้าฟ้าเขียว",
  str_item_intro_5602202 = "คนนอกเคยบอกว่าทุกอย่างมีต้นทุน แล้วค่าความรู้ล่ะ?",
  str_item_intro_5602203 = "สมองได้รับการดูแลโดยการเรียนรู้ และชีวิตได้รับการดูแลโดยอารมณ์",
  str_item_intro_5603101 = "อย่ายอมแพ้ง่าย ๆ ถึงแม้การทดสอบจะล้มเหลว 99 ครั้ง แต่ก็อาจสำเร็จในครั้งต่อไป",
  str_item_intro_5603201 = "อะไรคือหลักการขั้นสูงสุดที่เปลี่ยนสิ่งหนึ่งให้เป็นอีกสิ่งหนึ่ง? คงจะดีถ้าเราสามารถหาทางไปสู่จุดกำเนิดของความรู้ได้",
  str_item_intro_5603202 = "แรงบันดาลใจก็เหมือนประกายไฟที่แวบวาบ ฉันจะใช้เวลาทั้งชีวิตเพื่อค้นหาวิธีที่จะทำให้มันคงอยู่ตลอดไป",
  str_item_intro_5603301 = "ใบมีดที่คมที่สุดไม่ใช่ตัวเลือกที่ดีที่สุดเสมอไป บางครั้งคนทื่อๆ ก็ทำงานได้อย่างมหัศจรรย์ อาจเป็นกรณีที่โต้ตอบกับเธอ...",
  str_item_intro_5604101 = "ต้นไม้ทุกต้นมีชะตากรรมของมันเอง ฉันมีเหมือนกันไหม ฉันหวังว่าจะพบคำตอบในไม่ช้า...",
  str_item_intro_5604201 = "ใบไม้มีสีเงินมั้ย? เธอบอกว่าไม่ แต่ฉันไม่เชื่อ ฉันก็เลยมาที่นี่",
  str_item_intro_5604202 = "วงปีเป็นเครื่องบ่งบอกอายุที่จารึกไว้บนต้นไม้ เป็นทั้งประวัติและความทรงจำ พูดคุยกับพวกเขาและคุณอาจเรียนรู้เกี่ยวกับอดีตที่เราไม่รู้... พวกเขายังเป็นวงปีของเราอีกด้วย",
  str_item_intro_5604203 = "โปรไฟล์ของเขาปรากฏขึ้นระหว่างเงาของใบไม้และต้นไม้ นี่คือโชคชะตาออกแบบ?",
  str_item_intro_5604301 = "พวกเขาเติบโตและเหี่ยวเฉาอย่างเงียบ ๆ วิถีชีวิตที่ห่างไกลนี้ควรค่าแก่การเรียนรู้",
  str_item_intro_5604302 = "รากของเราอยู่ที่ไหน? ฉันหวังว่าฉันจะค้นพบในชีวิตนี้ ...",
  str_item_intro_5605201 = "ระลอกคลื่นทำให้ฉันนึกถึงพ่อที่สอนฉันตกปลา",
  str_item_intro_5605301 = "คันเบ็ดสีขาวนั้นเป็นของที่ระลึกที่แม่มอบให้ และฉันจะส่งต่อให้ลูก ๆ ต่อไป",
  str_item_intro_5605302 = "สิ่งเดียวที่เชื่อมเราไว้เหลือเพียงเส้นด้ายบาง ๆ ฉันหวังว่ามันจะไม่ขาดจากกัน",
  str_item_intro_5605303 = "แม้ว่าของขวัญของเธอจะเป็นเหยื่อล่อ ฉันก็เต็มใจรับมัน",
  str_item_intro_5605304 = "บางครั้งการตกปลาไม่ได้เกี่ยวกับการจับ—มันเกี่ยวกับการเห็นแสงริบหรี่บนเกลียวคลื่น",
  str_item_intro_5605305 = "ฉันบอกได้ว่าน้ำไหลไปทางไหน แต่เมื่อไหร่ฉันจะรู้ได้ว่าเธอคิดอะไรอยู่?",
  str_item_intro_5605306 = "การเคลื่อนไหวเล็กน้อยของเบ็ดบ่งบอกว่าปลาได้กินเหยื่อแล้ว ถ้าชีวิตมีสัญญาณคล้าย ๆ กันให้เราเห็นเมื่อมีโอกาส",
  str_item_intro_5606201 = "ฉันหวังว่าจะไม่เป็นอย่างพ่อที่ไม่ประสบความสำเร็จอะไรเลย ขอให้ฉันโชคดี!",
  str_item_intro_5606301 = "ความขยันหมั่นเพียรจะปกปิดความโง่เขลาของฉัน และทุกคนจะเรียกฉันว่าอัจฉริยะจากก้นบึ้งของหัวใจ",
  str_item_intro_5606302 = "อย่าได้ดูถูกกองหินเชียวนะ คุณอาจเจอสมบัติล้ำค่าในนั้นก็ได้",
  str_item_intro_5606303 = "จำไว้เสมอว่าต้องลับปลายเสียมของคุณ!",
  str_item_intro_5606304 = "เช่นเดียวกับความรัก การขุดไม่เพียงต้องการความแข็งแกร่ง แต่ยังต้องใช้ทักษะด้วย!",
  str_item_intro_5606305 = "เส้นแร่มีกลิ่นบางอย่าง! จมูกของฉันไวมาก แต่จะดีกว่าถ้าฉันรู้ว่าเขาอยู่ที่ไหน...",
  str_item_intro_5606306 = "หากเราอดทน เราจะพบเส้นเลือดเส้นนั้นแน่นอนไม่ว่าจะอยู่ในหุบเขานี้หรือไม่ก็ตาม",
  str_item_intro_5607201 = "เขาคือตะกร้าที่ใส่หัวใจของฉันไว้ข้างใน",
  str_item_intro_5607301 = "คงจะดีถ้าเธอรับรู้ความหวังดีของฉันได้",
  str_item_intro_5607302 = "ตอนเด็ก ๆ มีผลไม้หล่นใส่หัวฉัน และฉันก็เป็นคนโชคดีตั้งแต่นั้นมา หวังว่ามันจะยังคงเดิมต่อไปในอนาคต",
  str_item_intro_5607303 = "ส่วนใหญ่คุณจะต้องตามผึ้งไปเพื่อหาน้ำหวานที่ดี ถ้าเพียงฉันสามารถเข้าใจพวกเขา ...",
  str_item_intro_5607304 = "ถ้าใจเราใส่ถุงมือได้ หนามคงไม่ทิ่มแทงได้ง่ายๆ...",
  str_item_intro_5607305 = "คุณต้องมีสายตาที่ดีเพื่อหาผลไม้ทั้งหมดในคราวเดียว ใช่ ฉันต้องการรักษาระดับนี้ไปตลอดชีวิต",
  str_item_intro_5608101 = "ฉันหวังว่าเขาจะยอมรับฉันได้เมื่อพืชผลโอบรับแสงแดด",
  str_item_intro_5608201 = "เราไม่ได้หว่านเมล็ดเพื่อเก็บเกี่ยวเท่านั้น แต่เป็นการปลูกความหวังมากกว่า",
  str_item_intro_5608301 = "ฉันชอบมองกังหันลมหมุนช้า ๆ เพราะไม่ต้องคิดอะไรทั้งนั้น นั่งมองแบบนั้นได้ทั้งวัน...",
  str_item_intro_5608302 = "เมล็ดพันธุ์เป็นสิ่งที่เหลือเชื่อ เพียงเล็กน้อยก็ปลูกพืชผลได้มากมาย! ดังนั้น... ตราบใดที่ยังมีเมล็ดพันธุ์ ก็ย่อมมีความหวัง!",
  str_item_intro_5608303 = "ฉันต้องการเธอ เหมือนกับที่ต้นไม้ต้องการดวงอาทิตย์",
  str_item_intro_5608304 = "เมื่อแดดแรงเกินไปก็จะเผาพืชผลทั้งหมด เช่นเดียวกับการดูแลผู้อื่น",
  str_item_intro_5608305 = "พืชผลไม่ควรปลูกชิดกันเกินไป—ต้องเว้นระยะด้วยร่อง ในลักษณะเดียวกับที่ฉันควรรักษาระยะห่างจากเธอ",
  str_item_intro_5609201 = "ถ้าปลูกหญ้าที่ไม่ต้องตัดได้ เราก็คงได้ใช้ทำเป็นพรมผืนใหญ่นอนสบาย ๆ!",
  str_item_intro_5609301 = "หยดน้ำนั้นอ่อนและแข็งในเวลาเดียวกัน ฉันจะกลายเป็นคนแบบนั้นได้ไหม?",
  str_item_intro_5609302 = "เราต้องการดินที่ดีเพื่อปลูกพืชที่แข็งแรง และเราเองก็ด้วยใช่ไหม? ขอบคุณอาวุโสที่ให้ดินที่แตกต่างกันแก่เรา เพื่อให้เรากลายเป็นคนในแบบที่เราอยากเป็น",
  str_item_intro_5609303 = "ฉันต้องการน้ำหวานที่หอมหวานที่สุดสำหรับลูกในอนาคตของฉัน",
  str_item_intro_5609304 = "อา... เมื่อไหร่เราจะได้เต้นอย่างผึ้งน้อย",
  str_item_intro_5609305 = "คุณไม่สามารถเพียงแค่เพ่งสายตาไปที่ดอกไม้ที่สวยงามเหล่านั้นได้ ใบไม้สีเขียวก็สมควรได้รับความสนใจเช่นกัน ใช่ไหม",
  str_item_intro_5610101 = "ฉันสามารถต้อนฝูงสัตว์ขนาดใหญ่ไปรอบๆ ได้ แต่ฉันไม่สามารถเข้าใจหัวใจของครอบครัวได้ ฉันหวังว่าลูกในอนาคตของฉันจะไม่เป็นเช่นนั้น",
  str_item_intro_5610201 = "ว่ากันว่าถ้าคุณเห็นลวดลายหน้ายิ้มเวลาเทนมใส่แก้ว คุณจะโชคดีไปตลอดปีเลย!",
  str_item_intro_5610202 = "ได้ยินว่าหมู่บ้านอื่น ๆ ใช้สุนัขลาดตระเวนมาช่วยต้อนฝูงสัตว์ แต่เขาคือหนึ่งเดียวสำหรับฉัน",
  str_item_intro_5610203 = "กล่าวกันว่ามีสิ่งมีชีวิตที่เรียกว่า \"อูฐ\" ซึ่งอาศัยอยู่ในทะเลทรายอันห่างไกล และคาดว่านมของมันก็ค่อนข้างอร่อย!",
  str_item_intro_5610204 = "วันหนึ่งข้าจะเห็นหญ้างอกขึ้นอีกครั้ง และทุ่งนาจะเกิดใหม่",
  str_item_intro_5610301 = "ฉันได้ยินมาว่าข้างนอกหุบเขามีทุ่งหญ้ากว้าง แต่ฉันชอบหญ้าสีเขียวที่นี่",
  str_item_intro_5610302 = "ชีสเป็นอาหารที่ดีที่สุดในโลก และหากคุณสามารถกินมันได้ทุกวันตลอดชีวิต แสดงว่าคุณอยู่ในสถานที่ที่เรียกว่าสวรรค์ในตำนาน",
  str_item_intro_5610303 = "พวกเขาบอกว่าชาวทะเลทรายตั้งเมืองตามแหล่งน้ำ เห็นฉันทนไม่ได้ที่จะอยู่ห่างจากเธอแม้แต่หลา บางทีเธออาจจะเป็นแหล่งน้ำของฉัน ... ?",
  str_item_intro_5611101 = "ผู้คนริมทะเลบอกว่ามีเรือลำหนึ่งที่ใหญ่มหึมาพอ ๆ กับเกาะเลย ฉันอยากเห็นจัง!",
  str_item_intro_5611201 = "ฉันทำหน้าที่เฝ้ายามได้ทั้งวันเลยนะถ้าไม่ต้องนอน",
  str_item_intro_5611202 = "ฉันจะไม่ปล่อยให้ความชั่วร้ายเข้าใกล้ที่นี่ โดยเฉพาะอย่างยิ่งไม่ใช่สิ่งที่เป็นอันตรายต่อเด็ก...",
  str_item_intro_5611203 = "หลังจากที่ได้เป็นผู้พิทักษ์สถานที่นี้แล้ว ฉันก็ไม่สามารถพักผ่อนได้แม้แต่ตอนกลางคืน",
  str_item_intro_5611204 = "ไม่สามารถเพิกเฉยรายละเอียดได้ มิฉะนั้น ภัยพิบัติอาจเกิดขึ้น",
  str_item_intro_5611301 = "ฉันเดินได้สามวันสามคืนโดยไม่รู้สึกเหนื่อย ฉันจะใช้ความสามารถนี้ในการลาดตระเวนหุบเขาและคอยสอดส่องคนนอก",
  str_item_intro_5611302 = "ข้าจะเป็นโล่พิทักษ์ผู้คนทั้งหลาย! ฮ่าฮ่า ฉันเรียนมาจากคำสาบานของอัศวินลูโมโพลิสน่ะ มันเท่ชะมัดเลย! พูดได้ก็ต้องทำได้!",
  str_item_intro_5611303 = "ถ้าเราจุดไฟให้ต้นไม้ใหญ่ที่ดูเหมือนคบเพลิงจริงๆ เราจะใช้เป็นสัญญาณยามได้หรือไม่?",
  str_item_intro_6400001 = "รับเพื่อปลดล็อคฉายา: Frontline Hero\nหลังจากได้รับ คุณสามารถใช้ชื่อในนามบัตร - อินเทอร์เฟซชื่อเรื่อง!",
  str_item_intro_6400002 = "รับเพื่อปลดล็อกชื่อ: Tactical Genius\nหลังจากได้รับ คุณสามารถใช้ชื่อในนามบัตร - อินเทอร์เฟซชื่อเรื่อง!",
