  str_item_intro_6500001 = "พื้นหลังนามบัตรเริ่มต้น สามารถเลือกได้ผ่านนามบัตร - พื้นหลัง!",
  str_item_intro_6500002 = "พื้นหลังนามบัตรเริ่มต้น สามารถเลือกได้ผ่านนามบัตร - พื้นหลัง!",
  str_item_intro_6500003 = "พื้นหลังนามบัตรเริ่มต้น สามารถเลือกได้ผ่านนามบัตร - พื้นหลัง!",
  str_item_intro_6500004 = "พื้นหลังนามบัตรเริ่มต้น สามารถเลือกได้ผ่านนามบัตร - พื้นหลัง!",
  str_item_intro_6500005 = "พื้นหลังนามบัตรเริ่มต้น สามารถเลือกได้ผ่านนามบัตร - พื้นหลัง!",
  str_item_intro_6500008 = "เนินเขาที่ปกคลุมด้วยผ้าห่มสีขาว แม้จะดูเยือกเย็นและนิ่งขรึม แต่ดูเหมือนว่าพวกมันจะเปล่งพลังบางอย่างออกมา",
  str_item_intro_6500011 = "ข้อตกลงอันร่มรื่นที่เกิดขึ้นในตรอกซอกซอยที่มืดมิดภายใต้ม่านหมอกในใจกลาง Umbraton เป็นสิ่งที่พบเห็นได้ทั่วไปสำหรับผู้อยู่อาศัย",
  str_item_intro_6500014 = "โรงงานซ่อมบำรุงใน Illumina Undercity สามารถซ่อมแซมอุปกรณ์ที่เสียหายจำนวนมากได้อย่างรวดเร็ว แม้กระทั่งเครื่องจักรขนาดใหญ่เหล่านั้น",
  str_item_intro_6500015 = "การเฉลิมฉลองใน Lumopolis นั้นยิ่งใหญ่เช่นเคย",
  str_item_intro_6500016 = "แหล่งน้ำที่อุดมสมบูรณ์ ทางแยก และลักษณะทางภูมิศาสตร์และภูมิประเทศที่สะดวกสบาย ล้วนมีส่วนช่วยให้อัมบราตันเจริญรุ่งเรือง",
  str_item_intro_6500017 = "เมื่อดวงอาทิตย์ถูกปกคลุมด้วยความมืดที่อธิบายไม่ได้ การเปลี่ยนแปลงอันน่าสะพรึงกลัวของโลกกำลังรออะไรอยู่?",
  str_item_intro_6500018 = "Northland ดินแดนแห่งน้ำแข็งตลอดกาล ดินแดนแห่งนี้ถูกปกครองโดยเบธเลเฮม และยังเป็นสถานที่ที่เธอปรารถนาจะปกป้องอีกด้วย",
  str_item_intro_6500020 = "ไม่ว่ายังไง ฉันจะไม่ปล่อยให้พวกวายร้ายทำลายคอนเสิร์ตเด็ดขาด! นี่คือความยุติธรรม!",
  str_item_intro_6500021 = "Northland ดินแดนแห่งน้ำแข็งตลอดกาล ดินแดนแห่งนี้ถูกปกครองโดยเบธเลเฮม และยังเป็นสถานที่ที่เธอปรารถนาจะปกป้องอีกด้วย",
  str_item_intro_6500024 = "ในขณะนั้น ความระแวดระวังของเธอดูเหมือนจะละลายหายไป และรอยยิ้มที่มีความสุขของเธอก็ฉายแววซุกซนแบบเด็กๆ ปกปิดความลับไว้สำหรับสองคนเท่านั้น",
  str_item_intro_6500026 = "งานเลี้ยง Rediesel Wrench ที่เป็นแก่นสารเรียกขาน—งานเลี้ยงฉลองที่มีชีวิตชีวาซึ่งกลายเป็นอาหารรสเลิศอันเลื่องชื่อในทะเลทราย",
  str_item_intro_6500033 = "เมื่อเหน็ดเหนื่อยจากการเดินทาง คุณสามารถหาเวลานั่งกับเพื่อนร่วมทางเหล่านี้ได้เสมอ ในขณะที่คุณพักผ่อน พูดคุย และฟังเรื่องราวของกันและกัน",
  str_item_intro_6500035 = "แสงแดดในปราสาทบนที่สูงยังคงไม่เปลี่ยนแปลงเป็นเวลาหลายปี ยืนอยู่หน้าภาพวาดสีน้ำมันขนาดใหญ่ เธอสวมชุดเก่าและใช้เวลาอยู่ที่นั่นเป็นเวลานาน จมอยู่ในความคิดลึก ๆ บางทีก็นึกถึง",
  str_item_intro_6500036 = "เมื่อมีฟลอรีนอยู่เคียงข้างคุณ แม้แต่ผืนน้ำที่อันตรายที่สุดก็จะปลอดภัย",
  str_item_intro_6500037 = "มีคนค้างอยู่ที่นี่มากว่าหนึ่งร้อยปีแล้ว เพียงเพื่อให้สามารถทำภารกิจที่ลืมเสียนาน",
  str_item_intro_6500038 = "เมื่อลมสง่างามเบาๆ พัดเผยความมืดมิดของอดีต แสงสว่างแห่งรุ่งอรุณจะเผาทุกความเศร้าให้หายไป เพื่อประกาศอนาคตใหม่ให้คุณ",
  str_item_intro_6500039 = "เหมือนประภาคาร เธอจะส่องแสงสว่างให้กับมหาสมุทรที่มืดมิด นำทางนักผจญภัยกลับสู่บ้าน",
  str_item_intro_6500041 = "แม้ว่าจะหนาวจัดและพื้นโลกจะถูกปกคลุมด้วยน้ำแข็งและหิมะ ถ้าคุณอยู่กับเพื่อนร่วมทางของคุณ คุณจะมีหัวใจที่อบอุ่นเสมอ สุขสันต์วันหยุดนะคะ ผู้นำทาง!",
  str_item_intro_6500042 = "เชโอลกระโดดสูงขึ้นไปในอากาศเพื่อขับไล่ศัตรูที่บุกเข้ามา ณ ช่วงเวลานี้ เธอได้เปิดเผยด้านของตัวเองที่ไม่มีใครรู้เลย",
  str_item_intro_6500043 = "มีการจัดตั้งสถานีสังเกตการณ์จำนวนมากตามชายแดนของทะเลทราย ที่นี่คือที่ที่พวกเขาไล่ขับศัตรูและป้องกันบ้านเกิดที่ห่างไกลของพวกเขา",
  str_item_intro_6500044 = "ร้านค้าอยู่ทุกที่ พร้อมกับเสียงความวุ่นวาย และใจกลางเมืองของ Twin Pavilions Bay ที่มีชีวิตชีวาอย่างคึกคัก มีทั้งชาวบ้านและนักท่องเที่ยวที่มาเยอะ กำลังเลือกซื้อสินค้าด้วยความสนใจอย่างมากในความวุ่นวาย",
  str_item_intro_6500045 = "\"ขอบคุณสำหรับการยอมรับของคุณ ไวท์ไนท์อัพไฮ!\"",
  str_item_intro_6500046 = "\"ฉันชอบที่จะได้มองไปไกลคนเดียว แต่ตอนนี้... ที่มีเธออยู่ที่นี่ มันเป็นความสุขแบบอื่น\"",
  str_item_intro_6500047 = "\"โลกนี้ยังคงเต็มไปด้วยสงคราม คุณจะร่วมมือกับฉันในการแก้ไขความขัดแย้งเหล่านี้ในวันที่จะมาถึงหรือไม่?\"",
  str_item_intro_6500049 = "\"ริบบิต! ริบบิต!\"",
  str_item_intro_6500051 = "เมื่อฝูงโดรนล้อมรอบ เด็กหญิงหันกลับมามองคุณ\n\"ทุกอย่างเรียบร้อยแล้วนะ\"",
  str_item_intro_6500053 = "สว่างและสดใส, เธอยิ้มและกระโดดเข้าสู่นรก\n\"อย่าปล่อยให้ใครได้ยิบอำนาจหรือความสุขของคุณ\"",
  str_item_intro_6500054 = "คุณควรเลือกเส้นทางไหนเมื่อคุณอยู่ที่ทางแยกของชะตากรรม?",
  str_item_intro_6500056 = "ทุกสิ่งที่คุณประสบผ่านมาจะนำทางทรู ออเดอร์สู่อนาคตที่ยิ่งใหญ่ยิ่งขึ้น ",
  str_item_intro_6500057 = "สายลมทะเล, น้ำแข็งไส, รถสามล้อ ความทรงจำของฤดูร้อนแรกที่ผ่านไปกับหญิงสาวยังคงอยู่อย่างชัดเจนเหมือนเดิม",
  str_item_intro_6500058 = "คำสัญญาของการรวมตัว, ที่วิญญาณพบกัน",
  str_item_intro_9993001 = "Aurorian ที่รอดชีวิตแบบสุ่มในทีมจะฟื้น HP 20% หลังจากชนะการต่อสู้",
  str_item_intro_9993002 = "ผู้สนับสนุน Aurorians +25% ฟื้นฟู HP จากคอมโบต่อเนื่องและสกิลใช้งานในการต่อสู้",
  str_item_intro_9993003 = "ฟื้นฟู HP +80% เมื่อใช้ผ้าพันแผลที่ได้รับในการต่อสู้",
