  str_item_intro_9993034 = "เพิ่ม HP 3% สำหรับ Converter และ Supporter Aurorians หลังจากชัยชนะทุกครั้ง สูงสุด 30%",
  str_item_intro_9993035 = "เพิ่ม ATK 1.5% ให้ออโรเรียนสไนเปอร์และออโรเรียนเดโทเนเตอร์ทุกครั้งที่ชนะ สูงสุด 15%",
  str_item_intro_9993036 = "สุ่มออโรเรียนที่รอดชีวิตในทีมหนึ่งรายให้รับเดเมจลดลง 1.5% หลังจากที่ชนะ โดยสะสมสแต็กได้ จนกว่าจะจบการสำรวจดินแดนลับ",
  str_item_intro_9994001 = "สุ่มออโรเรียนที่รอดชีวิตในทีมหนึ่งรายให้ฟื้นฟู HP 10% ทุกครั้งเมื่อสังหารอิคลิพไซท์ได้",
  str_item_intro_9994002 = "ผู้สนับสนุน Aurorians ฟื้นฟู 100% ของความเสียหายจากพิษใน HP ทุกครั้งที่ Poison ทำงานบน Eclipsite ที่เป็นพิษ",
  str_item_intro_9994003 = "ออโรเรียนเดโทเนเตอร์ทำดาเมจเพิ่มขึ้น 30% ใส่อิคลิพไซท์ที่ติดสถานะดีบัฟ",
  str_item_intro_9994004 = "สร้างพิษ 3 แต้มแก่ศัตรูทั้งหมดเมื่อ Eclipsite ที่ติดพิษ, Burning หรือ Bleeding ตาย",
  str_item_intro_9994005 = "ทุกๆ Eclipsites รอบ Eclipsites พิษ เผาไหม้ หรือเลือดออกจะสร้างพิษบน Eclipsites ใน 2 กลุ่มรอบข้าง",
  str_item_intro_9994006 = "ออโรเรียนสไนเปอร์ทำดาเมจเพิ่มขึ้น +30% เมื่อทีมติดสถานะดีบัฟ",
  str_item_intro_9994007 = "ออโรเรียนเดโทเนเตอร์จะทำดาเมจเพิ่ม +5% ทุกครั้งที่ได้รับดาเมจ (รีเซ็ตเมื่อสิ้นสุดการต่อสู้)",
  str_item_intro_9994008 = "เติมผ้าพันแผลในสนามรบหนึ่งชิ้นเมื่อเริ่มต้นการต่อสู้",
  str_item_intro_9994009 = "ความเสียหาย +20% สำหรับ Sniper Aurorians ทั้งหมดที่มี HP มากกว่า 70%",
  str_item_intro_9994010 = "ออโรเรียนเดโทเนเตอร์รับ\nดาเมจโบนัส 10% ของ HP\nที่เสียไปเมื่อโจมตี",
  str_item_intro_9994011 = "น้ำพุลูมินาฟื้นฟูเพิ่มขึ้น 5 MS",
  str_item_intro_9994012 = "น้ำพุลูมินาสามารถฟื้นฟู\nตัวละครเพิ่ม +1",
  str_item_intro_9994013 = "ออโรเรียนเดโทเนเตอร์ เพิ่ม ATK +10% ในพื้นที่อันตราย",
  str_item_intro_9994014 = "ออโรเรียนเดโทเนเตอร์ในพื้นที่\nเสี่ยงตายได้รับ ATK +10%",
  str_item_intro_9994015 = "ทำให้ Scroungers หนีช้าลง 4 รอบ",
  str_item_intro_9994016 = "ลดคูลดาวน์ 1 รอบสำหรับ Aurorians ทั้งหมดหลังจากสังหาร Eclipsite ขนาดใหญ่",
  str_item_intro_9994017 = "ออโรเรียนสไนเปอร์\nเพิ่ม ATK +20% เมื่อสังหาร\nอิคลิพไซท์ขนาดใหญ่ได้",
  str_item_intro_9994018 = "ฟื้นฟู HP 20% ให้ออโรเรียน\nที่มี HP เหลือน้อยที่สุด\nเมื่อสังหารอิคลิพไซท์\nขนาดใหญ่ได้",
  str_item_intro_9994019 = "มอนสเตอร์ขนาดเล็กทุกตัว\nได้รับสถานะเชื่องช้า",
  str_item_intro_9994020 = "HP เริ่มต้น -20% สำหรับมอนสเตอร์ขนาดเล็กทั้งหมด",
  str_item_intro_9994021 = "มอนสเตอร์ขนาดเล็กทุกตัวลด ATK -10%",
  str_item_intro_9994022 = "-1 คูลดาวน์สำหรับ\nทุกสกิลใช้งานที่ไม่สมบูรณ์\nของออโรเรียนคอนเวอร์เตอร์\nเมื่อเริ่มต้นการต่อสู้",
  str_item_intro_9994023 = "บินวนรอบออโรเรียนและทำดาเมจธาตุไฟ 1 ครั้ง เมื่อกัปตันโจมตี",
  str_item_intro_9994024 = "บินวนรอบออโรเรียนและทำดาเมจธาตุน้ำ 1 ครั้ง เมื่อกัปตันโจมตี",
  str_item_intro_9994025 = "บินวนรอบออโรเรียนและทำดาเมจธาตุไม้ 1 ครั้ง เมื่อกัปตันโจมตี",
  str_item_intro_9994026 = "บินวนรอบออโรเรียนและทำดาเมจธาตุสายฟ้า 1 ครั้ง เมื่อกัปตันโจมตี",
  str_item_intro_9995001 = "คืนชีพออโรเรียนหนึ่งรายด้วย HP 50% เมื่อถูกสังหาร (เฉพาะออโรเรียนที่ได้รับดาเมจถึงตายรายแรก)",
  str_item_intro_9995002 = "ความเสียหายจากการโจมตีครั้งเดียวที่ทำกับ Converter Aurorian ที่สวมใส่ของที่ระลึกจะต้องไม่เกิน 20% ของ HP สูงสุด",
  str_item_intro_9995003 = "ค่ารักษาที่เกินออกมาของ\nออโรเรียนสนับสนุนจะถูกแปลง\nเป็นโล่หนึ่งชั้น นาน 1 รอบ",
  str_item_intro_9995004 = "มีโอกาส 50% ที่จะปลดปล่อยคลื่นกระแทกที่ทำให้ศัตรูทั้งหมดมึนงง นาน 1 รอบ ในทุกการต่อสู้",
  str_item_intro_9995005 = "การโจมตีปกติของ Sniper Aurorians และความเสียหายแบบ Chain Combo จะลบโล่ Eclipsite ออกทันที",
  str_item_intro_9995006 = "สุ่ม 4 ช่องจาก 8 ช่องรอบตัว เปลื่ยนเป็นช่องหลากสีเมื่อเริ่มการต่อสู้",
  str_item_intro_9995007 = "รีเฟรชลูมินามิเตอร์ MS พิเศษ เมื่อเริ่มการต่อสู้",
  str_item_intro_9995008 = "เมื่อการแข่งขันเริ่มขึ้น กระเบื้อง 2×2 แบบสุ่ม 10 แผ่นจะถูกฟ้าผ่าซึ่งสร้างความเสียหายแบบคงที่ต่อยูนิตที่อยู่ในระยะ ออโรเรียนไม่ได้รับผลกระทบ",
  str_item_intro_9995009 = "ทิ้งระเบิดไว้ที่จุดเริ่มต้นของการเคลื่อนไหวของคุณ และจะระเบิดหลังจากคุณและพันธมิตรดำเนินการเสร็จแล้ว",
  str_item_intro_9995010 = "คอมโบการโจมตีปกติ\nต่อเนื่องกัน 5 ครั้ง\nจะทำดาเมจระเบิด 1 ครั้ง",
