  str_item_intro_9995017 = "เมื่อเริ่มการต่อสู้ ทำให้อิคลิพไซท์ติดสถานะเป็นแผลและทำดาเมจ 3% ในทุกช่องที่เดิน",
  str_item_intro_9995018 = "การโจมตีปกติของออโรเรียนสนับสนุนทำให้อิคลิพไซท์ติดสถานะตาบอด และมีโอกาสโจมตีพลาด 30%",
