  str_item_rpintro_9995001 = "งานฝีมือที่มีสัมพันธ์ลึกลับกับผืนแผ่นดิน คืนชีพให้แก่ผู้สวมใส่ทันทีเมื่อหัวใจหยุดเต้น",
  str_item_rpintro_9995002 = "ชุดเกราะน่าเกรงขามที่ได้รับพรสุริยะ ให้ผู้สวมใส่สามารถต้านทานศึกทรหดได้เรื่อย ๆ",
  str_item_rpintro_9995003 = "อุปกรณ์ปริศนาจากยุคเก่าที่สามารถตรวจจับและแปลงลูมินาไปเป็นสนามพลังป้องกันผู้สวมใส่ได้",
  str_item_rpintro_9995004 = "คริสตัลหยาบที่พื้นผิวแตกเล็กน้อยแสดงถึงพลังลูมินาที่เปี่ยมล้นภายใน แรงสัมผัสเพียงปลายนิ้วก็สามารถปลดปล่อยลูมินามหาศาลจนทำให้ศัตรูมึนงงได้",
  str_item_rpintro_9995005 = "อาวุธทรงอานุภาพจากยุคเก่า ไม่มีใครรู้ว่ามันทำมาจากอะไร เพียงแค่ว่ามันคมเกินกว่าที่เกราะใดจะต้านทานได้",
  str_item_rpintro_9995006 = "อัญมณีที่ส่องประกายทุกสี งดงามและเปลื่ยนแปลงอยู่ตลอด",
  str_item_rpintro_9995007 = "อุปกรณ์สำหรับการเก็บและเติมลูมินา",
  str_item_rpintro_9995008 = "ดาบเลื่องชื่อจากยุคเก่า ปลุกเสกด้วยพลังแห่งสายฟ้า ได้ยินเสียงฟ้าพิโรธชัดเจนเมื่อชักออกจากฝัก",
  str_item_rpintro_9995009 = "สิ่งของยุคเก่าที่สร้างขึ้นเพื่อจัดการกับผู้ตามไล่ ปล่อยลูมินาไว้บนเส้นทางที่จะระเบิดภายหลังเพื่อสังหารผู้ตามไล่",
  str_item_rpintro_9995010 = "สร้างสิ่งประดิษฐ์ยุคเก่าที่ดูสวยงามแต่เปี่ยมด้วยพลังอันน่าสะพรึงกลัว สังหารศัตรูให้ร่วงโรยราวกับดอกไม้ใบหญ้าด้วยระเบิด",
  str_item_rpintro_9995011 = "มันสามารถตรวจจับพลังชีวิตของศัตรูและปลิดชีวิตผู้ที่ใกล้จะสิ้นชีพเมื่อพกติดตัวไว้",
  str_item_rpintro_9995012 = "อุปกรณ์ทรงพลังจากยุคเก่าที่สามารถสร้างภาพลวงตาทำให้ศัตรูสับสนได้",
  str_item_rpintro_9995013 = "เรลิกโบราณที่เผยให้เห็นชะตากรรมของทุกสรรพสิ่ง... หรือไม่ก็เป็นเพียงแค่ภาพหลอนเท่านั้น",
  str_item_rpintro_9995014 = "กล้วยไม้สีแดงหายากที่ถูกพัฒนาขึ้นในยุคเก่า มันจะปรากฏ เบ่งบานและโรยราเป็นคู่ เหมือนกับว่ามันสร้างความผูกพันกับผู้สวมใส่และช่วยเหลือในการต่อสู้",
  str_item_rpintro_9995015 = "ไอเทมยุคเก่าที่สร้างความผูกพันลึกลับระหว่างนักสู้สองคน",
  str_item_rpintro_9995016 = "สิ่งประดิษฐ์ในช่วงสงครามยุคเก่า กล่าวกันว่ามันสามารถทำให้ชราภาพและเดินเซได้",
  str_item_rpintro_9995017 = "กล่าวกันว่าเป็นไอเทมลึกลับจากสงครามล้างโลกครั้งก่อน มันมีคำสาปรุนแรงพอที่จะทำให้ศัตรูบาดเจ็บสาหัสได้",
  str_item_rpintro_9995018 = "เลนส์สว่างขึ้นในการต่อสู้ ทำให้คู่ต่อสู้ตาบอด ขณะเดียวกันปกป้องผู้สวมใส่ อุปกรณ์เสริม",
  str_item_gift_open_cond_1003 = "มีเลเวล 10 เพื่อปลดล็อกแพ็กของขวัญ",
  str_item_gift_open_cond_1004 = "มีเลเวล 20 เพื่อปลดล็อกแพ็กของขวัญ",
