  str_item_1602371 = "มายา",
  str_item_1602381 = "มิทรา",
  str_item_intro_1600011 = "โฆษกหญิงจากนอร์ธแลนด์ เธอถือกระจกยักษ์ที่สะท้อนรูปลักษณ์พิเศษของตัวเองและปกปิดความลับมากมาย",
  str_item_intro_1600021 = "ผู้บัญชาการผู้เข้มงวด จริงจัง มุ่งมั่น หนักแน่น และมั่นใจ แห่งสหพันธรัฐอิลลูมินา เธอชนะศึกด้วยดาบยาวในมือมาหลายต่อหลายครั้ง",
  str_item_intro_1600031 = "ทำงานเป็นบัตเลอร์ให้ชนชั้นสูงในเมืองชั้นบนจนถูกขับไล่ไปยังลูโมโพลิสชั้นล่างเพราะไปขัดใจชนชั้นสูงอีกคนเข้า อย่างไรก็ดี มีบางคนบอกว่านั่นเป็นแค่การปิดบังภารกิจลับของเขา",
  str_item_intro_1600041 = "สัตว์คู่หูอันประกอบด้วยคนพเนจรสองคน ตอนนี้พวกเขาทำงานเป็นทหารรับจ้างอิสระที่โด่งดังเรื่องความกล้าหาญในการต่อสู้และอารมณ์ขัน",
  str_item_intro_1600051 = "เด็กสาวที่ระเหเร่ร่อนในอัมบราตันพร้อมกับเสียงหัวเราะบ้าคลั่ง เธอชอบเล่นเกมเสี่ยงตายกับคนอื่นเลยไม่แปลกใจนักที่เธอถูกสังคมรังเกียจ",
  str_item_intro_1600061 = "ลูกสาวคนรองของลอร์ดลูโมโพลิส รักอิสระตั้งแต่ยังเด็ก เธอได้ขึ้นเป็นกัปตันของหน่วยผู้พิทักษ์ด้วยความสามารถและความพยายาม",
  str_item_intro_1400071 = "มือสังหารสาวจากเรดีเซล เวรนช์ เธอทำงานคนเดียวและเชี่ยวชาญในภารกิจยาก ๆ",
  str_item_intro_1400081 = "เจ้าหน้าที่วิทยาการของเรดีเซล เวรนช์ ผู้ประดิษฐ์เครื่องยิงลำแสงอาทิตย์ เพิ่มโหมดการต่อสู้ที่แปลกใหม่",
  str_item_intro_1500091 = "หนุ่มเจ้าสเน่ห์จากทรู ออเดอร์ เขาดูปริ่มไปด้วยความรู้พร้อมกับรอยยิ้มอันน่าดึงดูด และมักจะสาธยายเกี่ยวกับแนวคิดทางวิชาการของเขาไปเรื่อย",
  str_item_intro_1600101 = "เด็กสาวร่าเริงแจ่มใสจากนอร์ธแลนด์ที่ปรารถนาจะท่องโลกและเห็นทุกอย่างผ่านแว่นตาสีชมพู",
  str_item_intro_1600111 = "ผู้บัญชาการกองทัพแห่งสหพันธรัฐอิลลูมินาที่มีพลังมังกร ถึงแม้ว่าเธอจะดูสันโดษและไม่เข้าสังคม แต่เธอคือคนหนึ่งที่คุณสามารถไว้ใจได้เลย",
  str_item_intro_1500121 = "เด็กสาวที่กล้าหาญจากสหพันธรัฐอิลลูมินาผู้ที่ต่อสู้เพื่อความยุติธรรมด้วยอุดมการณ์อันสูงส่ง",
  str_item_intro_1500131 = "สาวจากนอร์ธแลนด์ที่มีเวทมนตร์น้ำแข็งอันทรงพลังพอที่จะปกคลุมภูมิภาคหนึ่งภายใต้น้ำแข็งฤดูหนาว",
  str_item_intro_1600141 = "ลอร์ดแห่งลูโมโพลิส ผู้ไม่เคยพึงใจและมุ่งมั่นรักษากฎและระเบียบในเมืองอย่างไม่ย่อท้อ",
  str_item_intro_1400171 = "เด็กสาวตัวเตี้ยผู้เป็นกัปตันของเรดีเซล เวรนช์ สัมผัสว่องไวและเฉียบแหลมไร้ที่ติ ศัตรูน้อยคนนักที่สามารถจับตัวเธอได้",
  str_item_intro_1500181 = "ร็อกเกอร์อันเป็นที่ชื่นชอบของ เรดีเซล เวรนช์ ไม่เพียงแค่ปลุกใจกองทหารได้ แต่เธอยังสามารถนำทัพบุกประชิดได้ด้วย",
  str_item_intro_1600191 = "ผู้หญิงที่มีความเป็นผู้ใหญ่และมีเสน่ห์อันตราย เธอเป็นสมาชิก ทรู ออเดอร์ ที่มีความรู้ต้องห้ามบางอย่าง และรักในการกล่าวสนับสนุนความจริงบางสิ่ง",
  str_item_intro_1500201 = "นอร์ธวินด์",
  str_item_intro_1500211 = "หนุ่มน้อยจากสหพันธรัฐอิลลูมินา ผู้เชี่ยวชาญด้านวิทยาศาสตร์ธรรมชาติ ช่ำชองเรื่องการทำสวนและชอบลงโทษศัตรูด้วยพลังจากธรรมชาติ",
  str_item_intro_1300221 = "กบฏหนุ่มหัวรั้นในหมวกทรงกระต่าย หมกหมุ่นกับดีเซลและความรุนแรง เขาเป็นหนึ่งในเดสเปอราโดแห่ง เรดีเซล เวรนช์",
  str_item_intro_1600231 = "เด็กสาวที่ต่อต้านสังคมอย่างรุนแรง อาศัยคลาริเนตและความสามารถพิเศษของเธอในการควบคุมสัตว์เพื่อสร้างรังในอัมบราตันที่ยุ่งเหยิง",
  str_item_intro_1500241 = "คู่หูจากอิลลูมินา เบนนี่มีนิสัยหุนหันพลันแล่นและสะเพร่า ส่วนคุโระนั้นใจเย็นและมีสติ แม้จะแตกต่าง แต่ทั้งสองก็เข้ากันได้ดีและอยู่ในกลุ่มนักสู้ชั้นสูงของอิลลูมินา",
  str_item_intro_1600251 = "เจ้าหน้าที่โลจิสติกส์ของสหพันธรัฐอิลลูมินา พร้อมกับเป็นเจ้าของและคู่หูร่วมชีวิตของรถไฟสู่ยมโลก",
  str_item_intro_1600261 = "หนึ่งในเทวทูตทั้งสี่ของอัศวินลูโม เธอเป็นคนที่มองโลกในแง่ร้ายเสมอต้นเสมอปลาย ซึ่งน่าแปลกใจที่มันขัดกับรูปลักษณ์อันร้อนแรงของเธอ",
  str_item_intro_1600271 = "หนึ่งในเทวทูตทั้งสี่อันเลื่องชื่อแห่งอัศวินลูโม เธอเป็นคนขึงขังและแทบจะไม่แสดงรอยยิ้มออกมา ร่างกายของเธอได้รับการดัดแปลงโดยชาวอิลลูมินาหลังจากที่บาดเจ็บสาหัส เป็นผลทำให้เธอสูญเสียอารมณ์ความรู้สึกบางส่วนไป",
  str_item_intro_1600281 = "หนึ่งในเทวทูตทั้งสี่ของอัศวินลูโม เธอมีพลังการรักษาที่ไม่เหมือนใครและมองโลกในแง่ดีอย่างสุดโต่ง",
  str_item_intro_1600291 = "หนึ่งในเทวทูตทั้งสี่ของอัศวินลูโม เธอเป็นคนเงียบ เยือกเย็นและสงบราวกับว่าไม่มีอะไรมากวนใจเธอได้",
  str_item_intro_1600301 = "ผู้นำที่พูดจาโผงผางของเรดีเซล เวรนช์ ผู้ซึ่งสนิทสนมกับสมาชิกของเขาอย่างมากและหวงน้องสาวมากอีกด้วย เขาคือผู้ที่อุทิศตนเพื่อให้แน่ใจว่าทั้งแก๊งจะมีชีวิตรอด",
  str_item_intro_1500311 = "ชูมานน์",
  str_item_intro_1400321 = "เจ้าหน้าที่ศาลยุติธรรมแห่งลูโมและนางฟ้าปีกเดียว เธอเป็นคนจิตใจอ่อนไหวง่ายและรักเกียรติยศศักดิ์ศรีของตนมาก แม้ว่ายังเด็ก แต่แองเจิลก็แข็งกร้าวจากการต่อสู้เป็นเวลาหลายปี",
  str_item_intro_1500331 = "ยังถือว่าเด็กมากแต่เปี่ยมไปด้วยประสบการณ์เมื่อเทียบกับอายุของเธอ ขยันขันแข็งและกระตือรือล้น เธอคือผู้มีพรสวรรค์หน้าใหม่และเป็นที่ต้องการของสหพันธรัฐอิลลูมินา",
  str_item_intro_1500341 = "ซอนเน็ต",
  str_item_intro_1400351 = "คูเรียร์กร้านโลกบ้างานที่ไม่สามารถนอนหลับได้จนกว่างานทั้งหมดจะสำเร็จ",
  str_item_intro_1500361 = "ชายหนุ่มจากอัมบราตัน เขาเป็นหมาป่าเดียวดายผู้ขวางโลกไม่สนใจระเบียบกฎเกณฑ์ของลูโมโพลิสแม้แต่น้อย และตั้งตัวเป็นศัตรูกับเหล่าขุนนางอย่างเปิดเผย",
  str_item_intro_1600381 = "สาวนักขับขี่จักรกลยักษ์และเจ้าหน้าที่วิทยาการคนปัจจุบันในสหพันธรัฐอิลลูมินา ว่ากันว่าเธอคืออัจฉริยะที่เกษียณมาจากกองทัพ",
  str_item_intro_1400401 = "เด็กสาวจาก เรดีเซล เวรนช์ ชื่นชอบระเบิดและมักจะตื่นเต้นผิดวิสัยเมื่อมีอะไรระเบิด",
  str_item_intro_1400411 = "ผู้นำทางสำหรับคนใหม่ที่เพิ่งมาถึงลูโมโพลิส เธอสงบเสงี่ยมแม้ในยามภัยพิบัติ บอกใบ้ถึงอดีตที่ไม่ธรรมดา",
  str_item_intro_1400441 = "เสนาธิการที่เข้มงวดกวดขันแห่งสหพันธรัฐอิลลูมินา เธอสามารถวางแผนและจัดการทุกอย่างได้อย่างพิถีพิถัน",
  str_item_intro_1300461 = "เด็กสี่คนที่่ทำหน้าที่เป็นทีมกระจายเสียงของลูโมโพลิส ในฐานะที่เป็นสมาชิกคณะประสานเสียงของวิทยาลัย พวกเขาเพลิดเพลินไปกับการเยาะเย้ยคนอื่นอย่างไร้ความปราณีมากกว่าการที่จะเป็นเด็กไร้เดียงสาอย่างที่ควรจะเป็น",
  str_item_intro_1300471 = "นักวิจัยอัจฉริยะแห่งสหพันธรัฐอิลูมินาผู้กระหายในการศึกษาหาความรู้ สิ่งที่เธอสนใจมีเพียงความรู้ และผู้บัญชาการกองทัพคนหนึ่งเท่านั้น",
  str_item_intro_1400481 = "เป็นหัวหน้ากลุ่มสเปียร์โรว์ตั้งแต่อายุยังน้อย เธอปกครองอัมบราตันด้วยความมุ่งมั่นอันไร้ที่ติ และอาวุธลับอันแสนร้ายกาจ",
  str_item_intro_1300491 = "นักรบผู้แข็งแกร่งและตัวสูงที่มักจะเดินทั่วอัมบราตันในชุดเกราะเต็มยศและดาบขนาดใหญ่ เขาไม่เคยถอดหมวกเกราะออกเลย เป็นชายพูดน้อยที่ชอบใช้กำลังรุนแรงพูดแทนมากกว่า",
  str_item_intro_1200501 = "ถึงจะยิ้มแต่ก็ยังเป็นฉลามที่น่ากลัวอยู่! ผู้ปกป้องนิคมเล็ก แม้ว่าภายนอกจะดุร้ายและน่าสยองแต่ที่จริงอ่อนโยนเป็นอย่างมาก",
  str_item_intro_1300511 = "พลระเบิดจระเข้ผู้เงียบขรึมและสไนเปอร์เสียงดังเจื้อยแจ้วทำให้เป็นคู่หูเรดีเซล เวรนช์ประหลาดและคู่ทหารรับจ้างที่ไว้ใจได้",
  str_item_intro_1300521 = "คนส่งของที่ให้บริการส่งไปรษณีย์ของสหพันธรัฐอิลลูมินา คนเกียจคร้านเต็มตัวที่ไม่มีเกียรติในหน้าที่การงานเลยแม้แต่น้อย เธอจะทำทุกอย่างเพื่อเกี่ยงงานหรืออู้งาน",
  str_item_intro_1300531 = "พ่อค้าจากเรดีเซล เวรนช์ ในฐานะที่เป็นนักซื้อขายหน้าเงินทั่วไป เขาไม่เคยพลาดโอกาสสร้างกำไรเลย",
  str_item_intro_1300741 = "เจ้าหน้าที่ชั้นผู้น้อยของกองทัพอิลลูมินา เขาเป็นคนต่อต้านสังคมและเข้ากับเพื่อนร่วมงานไม่ได้...น่าจะเป็นนิสัยที่ได้มาจากสายเลือดปริศนาของเขา",
  str_item_intro_1300581 = "อัศวินใหม่ผู้กระตือรือร้นและจริงจังของลูโมโพลิส ท่าทางจะเครียดจากการรับแรงกดดันของหน้าที่อันหนักหน่วงที่แต่งตั้งให้ในช่วงที่ยังเด็กอย่างนี้",
  str_item_intro_1400161 = "สไนเปอร์เรดีเซล เวรนช์ที่ใช้ซูเปอร์เรลกันทรงพลังทำลายล้างศัตรูฝ่ายตรงข้ามจนเกลี้ยง",
  str_item_intro_1400541 = "กัปตันของผู้คุ้มภัยยามราตรีลูโม เท่ นิ่ง มีสติและเป็นที่ชื่นชมเรื่องจัดการทุกอย่างได้อย่างจริงจัง",
  str_item_intro_1400611 = "นักวิจัยสหพันธรัฐอิลลูมินาที่มองโลกในแง่ดีและร่าเริง มีความสามารถพิเศษในการดูดซับอารมณ์ลบจากผู้อื่นและรักษาความเจ็บปวดภายในของพวกเขา",
  str_item_intro_1400731 = "สมาชิกใหม่ของกิลด์อีสต์วานในอัมบราตัน พวกเขามักจะสมาธิสั้นอยู่เสมอ ดังนั้นโปรดระวังให้ดี!",
  str_item_intro_1500421 = "ผู้บัญชาการกองทัพของสหพันธรัฐอิลลูมินา ผู้กระหายสงครามที่ทนความน่าเบื่อในช่วงเวลาสงบสุขไม่ได้และต้องหาหนทางชนะทุกวิถีทาง",
  str_item_intro_1500761 = "สุภาพบุรุษใจเย็น มารยาทนอบน้อมและสุภาพที่กลับเป็นจอมโกหกเป็นนิสัย เขาเป็นนักต้มตุ๋นที่โด่งดังในอัมบราตันด้วย",
  str_item_intro_1500781 = "สมาชิกสเปียร์โรว์อัมบราตัน เก็บตัวและตื่นตระหนกยามเข้าสังคม เธอและเดย์นาพึ่งพากันและกันเพื่อเอาชีวิตรอดในอัมบราตัน",
  str_item_intro_1600771 = "ผู้ปกครองนอร์ธแลนด์ที่มากด้วยภูมิปัญญาและประสบการณ์มานานปี รับมือกับสถานการณ์ต่าง ๆ ได้อย่างสุขุมและเด็ดขาด",
  str_item_intro_1300591 = "สมาชิกสหภาพผู้ส่งสารที่รับผิดชอบติดต่อกับทรู ออเดอร์ ถึงจะมีข้อเสียแต่ทุกคนก็ยอมรับเธอเพราะเป็นคนเถรตรง ไม่มีอะไรปิดบัง",
  str_item_intro_1300801 = "นักวิจัยของสหพันธรัฐอิลลูมินา เธอเป็นอัจฉริยะที่คลั่งไคล้เครื่องจักรและโมเดล เธอคิดว่าการพูดคุยกันเป็นสิ่งที่ทำได้ยาก แต่ถึงอย่างนั้นเธอก็พูดได้ไม่หยุดเวลาได้คุยเรื่องที่คลั่งไคล้",
  str_item_intro_1300821 = "แฟรี่น่ารักและไร้เดียงสาจากป่าสนนอร์ธแลนด์ที่ไม่รู้วิถีความเป็นไปของโลก เธอมีเขาอัญมณีล้ำค่าหนึ่งคู่และปกป้องมันไว้อย่างดีตั้งแต่ยังเป็นเด็ก",
  str_item_intro_1400451 = "สมาชิกผู้บริหารของทรู ออเดอร์และผู้ติดตามของวิกตอเรีย เขาเป็นคนเงียบขรึมและยึดมั่นในแนวคิดของทรู ออเดอร์อย่างมาก เป้าหมายในชีวิตของเขาคือการเผยแพร่แนวคิดของทรู ออเดอร์",
  str_item_intro_1400571 = "หัวหน้าหน่วยข่าวกรองของสหพันธรัฐอิลลูมินา เธอมักจะเป็นคนสุภาพ เข้าหาง่ายและขี้เกียจอยู่หน่อย ๆ แต่อีกบุคลิกหนึ่งของเธอก็ค่อนข้างดื้อรั้นอยู่เหมือนกัน",
  str_item_intro_1400681 = "สมาชิกสหภาพผู้ส่งสารที่รับผิดชอบดูแลพื้นที่เรดีเซล เวรนช์ เธอเป็นคนมั่นใจ น่ารัก กล้าหาญและใจกล้าที่จะรับคำท้า เธอชอบป่วนไปเรื่อยขณะส่งจดหมายและเป็นคนเกเรตัวน้อยที่น่ารัก",
  str_item_intro_1400791 = "เจ้าหน้าที่สรรพากรลูโมผู้อิสระ ยุติธรรมและมีเหตุมีผล เธอมีนิสัยชอบแปลงค่าทุกอย่างเป็นทองเพื่อเทียบมูลค่า",
  str_item_intro_1400811 = "สมาชิกหนุ่มล่ำผู้หลุดโลกแห่งเรดีเซล เวรนช์ มั่นใจในตัวเอง มุ่งมั่นและไร้เดียงสา หลอกใครไม่เป็น อยากเป็นที่หนึ่งในทุกเรื่อง",
  str_item_intro_1400831 = "สมาชิกผู้ติดตามของสถาบันวิจัยวิทยาศาสตร์สหพันธรัฐอิลลูมินา เธอพูดเหมือนหุ่นยนต์รับใช้ แต่ที่จริงเป็นมนุษย์โคลนของสิ่งมีชีวิตบางอย่างที่ทรงพลังมาก",
  str_item_intro_1601231 = "เจ้าหน้าที่พิทักษ์กฎของอิลลูมินาคนนี้มักจะตกใจกลัวจนร้องไห้ขี้มูกโป่งแม้แต่ในสถานการณ์\nฉุกเฉินเล็กน้อย แต่เธอก็ยังคงมองโลกในแง่ดีและตั้งใจทำงานของตนเองในนามของ\nความยุติธรรมเสมอ",
  str_item_intro_1601201 = "สตรีชั้นสูงผู้ถือกำเนิดในครอบครัวที่มั่งคั่ง เธอเป็นคนฉลาดและชอบอ่านหนังสือคนเดียวในห้องเป็นที่สุด เพื่อนเพียงหนึ่งเดียวของเธอก็คือชุดเกราะขนาดยักษ์ที่มีชื่อว่าปอมเปย์ ซึ่งเธอเป็นคนปลุกพลังมันด้วยตัวเอง",
  str_item_intro_1500151 = "ฮาชิ ผู้ค้างานศิลปะแห่งอัมบราตัน รู้ดีทุกอย่างเกี่ยวกับวิจิตรศิลป์ ส่วนกินเป็นนักวาดผู้มีฝีมือหาตัวจับยาก ทั้งสองมีความผูกพันชนิดที่ไม่อาจแยกจากกันได้ และร่วมมือกันทำงานเป็นทหารรับจ้าง",
  str_item_intro_1501321 = "ชาวหุบเขาน้ำแข็งยอดสนแห่งนอร์ธแลนด์ ชอบทุกอย่างที่เป็นน้ำผึ้ง เถาบุปผาบนร่างกายของเธออาจดูสวยงาม แต่ที่จริงแล้วมีความสามารถพิเศษด้วย",
  str_item_intro_1601311 = "ชาวนอร์ธแลนด์ที่มีความใกล้ชิดกับเบธเลเฮม ผู้หลงใหลและรอบรู้ในเรื่องประวัติศาสตร์ เขาเชื่อว่านอร์ธแลนด์คือสวรรค์แหล่งสุดท้ายสำหรับออโรเรียน และต้องการปกป้องมันเอาไว้ด้วยพลังของเขา",
  str_item_intro_1601331 = "โทรุเป็นมังกรผู้โหดเหี้ยมที่ต่อสู้กับเทพเจ้าตัวต่อตัวจนเกือบตาย หลังจากหลงรักโคบายาชิในต่างโลกแล้ว โทรุจึงเลือกที่จะมาอยู่กับเธอในฐานะสาวใช้",
  str_item_intro_1601341 = "เป็นมังกรเหมือนกับโทรุ มีรูปร่างหน้าตาและนิสัยเหมือนเด็ก ถูกขับไล่ออกจากบ้านเกิดเพราะป่วนไปทั่วและติดตามโทรุมาตลอดตั้งแต่นั้นเป็นต้นมา",
  str_item_intro_1501351 = "มังกรผู้พยายามแก้ไขปัญหาความขัดแย้งของมนุษย์ ครั้งหนึ่งเคยถูกเรียกว่าแม่มดแห่งทะเลศักดิ์สิทธิ์ ซื่อสัตย์และขยัน เธอรักอาหารจานอร่อยและอดใจต้านทานของหวานแทบไม่ไหวเลย",
  str_item_intro_1501361 = "เคยเป็นเทพเจ้าผู้ปกครองวัฒนธรรมโบราณและอารยธรรม ทรงพลังอำนาจแต่ขาดความกระตือรือร้นและชอบผ่อนคลาย",
  str_item_intro_1401371 = "เพื่อนของโทรุที่เฝ้าถ้ำสมบัติในอีกโลกหนึ่ง เขาไม่เป็นมิตรและชอบถากถางเพราะเห็นคนโลภมากมามากมาย",
  str_item_intro_1601381 = "นักวิจัยจากสหพันธรัฐอิลลูมินา เธอมีเหตุผลและมีประสิทธิภาพมากในการทำงาน แต่จะขี้เกียจและทำตัวตามสบายในเวลาส่วนตัว ด้วยความชื่นชอบในเทคโนโลยีโบราณ เธอจึงเดินทางไปทั่วแอสตราเป็นเวลายาวนานเพื่อสำรวจซากปรักหักพังทุกชนิด",
  str_item_intro_1501391 = "เธอเกิดในลูโมโพลิสและเป็นสมาชิกสภานักเรียนของอุษาวิทยาลัย ติดตามฟลอรีนไปทุกหนทุกแห่งและมักจะมีความคิดที่แปลกประหลาด บางครั้งคำพูดของเธอก็ทำให้ผู้คนถึงกับอึ้ง",
  str_item_intro_1601401 = "เธอเกิดในลูโมโพลิสและเป็นอดีตประธานสภานักเรียนแห่งอุษาวิทยาลัย ด้วยหัวใจอันแสนอบอุ่นที่อยู่ภายในรูปลักษณ์อันเย็นชา เธอดูแลเพื่อนฝูงเป็นอย่างดีตลอดเส้นทางสู่การเป็นอัศวินที่โดดเด่น",
  str_item_intro_1601411 = "รูบี้เกิดในเรดีเซล เวรนช์ มีนิสัยร่าเริงและสนุกสนาน ชอบฟังเรื่องราวการผจญภัยมาตั้งแต่เด็ก เธอออกเดินทางผจญภัยทันทีหลังจากที่ได้เรียนรู้วิชาและมีทักษะเพียงพอ",
  str_item_intro_1501421 = "สมาชิกเรดีเซล เวรนช์ มักจะต้องพึ่งพารูบี้อยู่เสมอ ปากกับใจไม่ตรงกัน แต่เบื้องหลังคำพูดร้าย ๆ นั้น แท้จริงแล้วเธอมีจิตใจที่เอาใจใส่และอ่อนโยน",
  str_item_intro_1601431 = "มิโกะแห่งเกาะเมฆาผู้มีความรู้และมารยาทงดงาม เติบโตขึ้นมาโดยการเลี้ยงดูของโชกุนผู้ปกครองเกาะเมฆา เธอหวังว่าพลังของตนจะช่วยบรรเทาความทุกข์ของชาวเมืองได้",
  str_item_intro_1501441 = "สตรีร่างสูงใหญ่จากเกาะเมฆาผู้ซึ่งรินเนะเคยช่วยชีวิตไว้ เธออ้างว่าตนมองเห็น \"สิ่งนั้น\" และหวาดกลัวคนแปลกหน้า",
  str_item_intro_1601451 = "เกิดที่เกาะเมฆา เธอสูญเสียบ้านเนื่องจากสงคราม ต่อมาได้รับการช่วยเหลือและได้เรียนวิชานินจา เรื่องราวในอดีตทำให้เธอดูเย็นชา แต่ในส่วนลึกนั้นเธอภักดีต่อมิตรสหายเป็นอย่างมาก",
  str_item_intro_1601461 = "เกิดที่เกาะเมฆา ศึกษา \"ศิลปะแห่งชี่\" จากกิลด์หลิน เธอมีความสามารถในการต่อสู้ที่แข็งแกร่ง เป็นคนร่าเริงแจ่มใส และชอบต่อสู้เพื่อความยุติธรรมในระหว่างการเดินทาง",
  str_item_intro_1501471 = "เกิดที่เกาะเมฆา เรามักจะเห็นฝาแฝดคู่นี้ขายราเม็งคานิยะ\nจากรถเข็นของพวกเธอ ซึ่งก็ขายดีเป็นเทน้ำเทท่า\nพวกเธอหวังว่าจะทำเงินพร้อมกับสำรวจไปให้ถึงขีดจำกัด\nของอาหารอันโอชะทั้งปวง",
  str_item_intro_1201631 = "บุคคลปริศนาที่มาจากทางตอนเหนือ หลงใหลในการสร้างสรรค์ผลงานเกม ทุกครั้งที่พบเจอกับใครก็มักจะถามว่า \"คุณมีไอเดียอะไรไหม?\"",
  str_item_intro_1601481 = "สมาชิกทีมสำรวจของเรดีเซล เวรนช์ผู้มีหัวใจเป็นอิสระ และมักทำงานคนเดียวในการตรวจสอบข้อมูลมากมายหลายประเภทที่อาจมีประโยชน์กับเรดีเซล เวรนช์ ครั้งหนึ่งเธอเคยได้รับการยกย่องว่าเป็นนักแข่งในตำนาน",
  str_item_intro_1501491 = "ผู้จัดการพลาธิการแห่งเรดีเซล เวรนช์ แม้ว่าเขาจะดูไร้ระเบียบ แต่ที่จริงแล้วเขาเป็นคนที่รอบคอบมากและปกป้องทุกคนในเรดีเซล เวรนช์",
  str_item_intro_1601501 = "สมาชิกทรู ออเดอร์ เงียบ ๆ แต่มากความสามารถ ท่าทางเธอจะไม่มีความคิดเป็นของตัวเองหรือมีความทะเยอทะยานใด ๆ จุดประสงค์ในชีวิตของเธอคือรับคำสั่งและทำให้สำเร็จลุล่วง",
  str_item_intro_1601511 = "สมาชิกทรู ออเดอร์ มักขี้เกียจจนกว่าจะกระตือรือร้นขึ้นมา เขาเชื่ออย่างยิ่งว่าเขาถูกส่งมายังโลกนี้เพื่อเผยแพร่เพลงกล่อมเด็กนั่น",
  str_item_intro_1501521 = "เด็กสาวจอมเพ้อฝันและหัวดื้อที่พยายามอย่างยิ่งที่จะทำให้ผู้ใหญ่รอบตัวในทรู ออเดอร์พึงพอใจ เธอโหยหาความสนใจและได้รับเท่าไรก็ดูจะไม่เพียงพอ",
  str_item_intro_1601551 = "หลังจากใช้อุปกรณ์ \"คอร์ดลิงก์\" แม้ว่ารูปลักษณ์หน้าตาและความสามารถของผู้บัญชาการกองทัพแห่งสหพันธรัฐอิลลูมินาจะเปลี่ยนไป แต่จิตใจของเขายังคงกระหายการทำสงครามไม่เปลี่ยนแปลง",
  str_item_intro_1601541 = "กัปตันทีมสำรวจของอิลลูมินาผู้มีนิสัยสุภาพอ่อนโยน โชคชะตาได้นำพาให้เธอมาช่วยชีวิตหนุ่มน้อยเชื้อสายเคเลสไทต์คนสุดท้ายที่ติดอยู่ใต้ดิน และเปิดเส้นทางสู่การผจญภัยครั้งใหม่ที่น่าตื่นเต้น",
  str_item_intro_1601531 = "จอมทัพผู้ยิ่งใหญ่ที่แท้จริงแห่งสหพันธรัฐอิลลูมินา เธอไม่เพียงแต่กล้าหาญและมีทักษะในสนามรบเท่านั้น แต่ยังเป็นผู้นำที่จริงใจและมีความสามารถสูงซึ่งทุกคนในอิลลูมินาต่างก็ยอมรับนับถือ",
  str_item_intro_1601561 = "เธอเกิดในตระกูลชนชั้นสูงลูโมในอัมบราตัน ดูผิวเผินเหมือนจะเข้ากับคนอื่นได้ยาก แต่ที่จริงแล้วเข้าถึงง่ายพอสมควร... อืม น่าจะอย่างนั้นนะ",
  str_item_intro_1501571 = "เธอเกิดบนเกาะเมฆา ประสบกับความยากลำบากอย่างมากมายในช่วงวัยเด็ก หลังจากย้ายมาที่แอสตราเพื่อชีวิตความเป็นอยู่ที่ดีขึ้นก็เกิดมีหนี้สินก้อนโต สิ่งที่เธอปรารถนาคืองานที่มั่นคง",
  str_item_intro_1601581 = "หนุ่มน้อยจากต่างโลกที่มีพลังพิเศษในตัวเรียกว่า \"เพอร์โซน่า\"\nซ่อนใบหน้าที่แท้จริงภายใต้หน้ากากและใช้โค้ดเนมแทนชื่อจริง มีออร่าที่พิเศษส่งออกมาจากตัวเขา\nในโลกของเขา เขาเป็นหัวหน้าแฟนท่อมธีฟส์ จอมโจรแห่งจิตใจอันโลดโผน",
  str_item_intro_1601591 = "สมาชิกกลุ่มแฟนท่อมธีฟส์จากต่างโลก\nอัจฉริยะด้านการวางกลยุทธ์ของแก๊ง คอยวางแผนดำเนินการให้กับเพื่อนของเธอ\nสามารถใช้พลังพิเศษ \"เพอร์โซน่า\" ได้",
  str_item_intro_1501601 = "สมาชิกกลุ่มแฟนท่อมธีฟส์จากต่างโลก\nชายหนุ่มผู้มีนิสัยประหลาด ค่อนข้างจะแปลกแยกและเฉยเมย\nสามารถใช้พลังพิเศษ \"เพอร์โซน่า\" ได้",
  str_item_intro_1501611 = "เด็กสาวที่มาจากโลกเดียวกันกับแฟนท่อมธีฟส์\nทำงานกับพวกเขาเพียงชั่วคราวด้วยเหตุผลหลายประการ\nสามารถใช้พลังพิเศษ \"เพอร์โซน่า\" ได้",
  str_item_intro_1501621 = "สิ่งมีชีวิตลึกลับจากต่างโลก หน้าตาเหมือนแมวแต่พูดได้เหมือนคน\nเขาเป็นผู้ชี้แนะแฟนท่อมธีฟส์ในสถานการณ์ต่าง ๆ\nสามารถใช้พลังพิเศษ \"เพอร์โซน่า\" ได้",
  str_item_intro_1601641 = "คาร์ลีน เดอ ชวาตส์ พลังของเธอเปลี่ยนแปลงในขณะที่กำลังเดินทางไปสู่เมืองฮาร์เบอร์ ทำให้เธอมีความเข้าใจเรื่อง \"ภาวะผู้นำ\" ที่ลึกซึ้งยิ่งขึ้น",
  str_item_intro_1501651 = "วิศวกรยอดอัจฉริยะของอิลลูมินา มีนิสัยเก็บตัว ขี้อาย แต่ในใจก็อยากจะพูดคุยกับคนอื่น ๆ ความใฝ่ฝันของเธอคือการสร้างหุ่นยนต์ไดนามิกที่ทรงพลัง",
  str_item_intro_1601661 = "นักสัตว์มหัศจรรย์วิทยาตัวน้อยที่เอาแต่ใจและดื้อรั้น แต่กลับขี้แยชนิดที่คาดไม่ถึง เธอทุ่มเทความพยายามอย่างหนักเพื่อจะเป็นนักสัตว์มหัศจรรย์วิทยาที่เก่งกว่าอาจารย์วิคให้ได้",
  str_item_intro_1601671 = "หัวหน้าคณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์ และยังเป็นสมาชิกของทรู ออเดอร์อีกด้วย ลึกลับ น่ากลัว และเงียบขรึม ความทะเยอทะยานของเขาคือการเป็นนักมายากลที่ยิ่งใหญ่ที่สุด",
  str_item_intro_1501681 = "เด็กสาวที่จำต้องพลัดจากบ้านเกิดเพราะการโจมตีของอิคลิพไซท์ มีจิตใจบริสุทธิ์ ร่าเริงแจ่มใส และถือว่าการปกป้องเรือมรกตเป็นภาระหน้าที่ของเธอ บ่อยครั้งที่เธอทำหน้าที่เป็นแขกรับเชิญของคณะละครสัตว์เพื่อสร้างบรรยากาศให้สนุกสนาน",
  str_item_intro_1501301 = "สมาชิกของตระกูลทรอยแห่งลูโมโปลิส แต่ทำไมที่นั่งของเขาจึงต่ำสำหรับคนที่เกิดมาสูงเช่นนี้? บางทีคำตอบอาจอยู่ในบุคลิกของเขา",
  str_item_intro_1501711 = "ดูห่างเหิน แต่จริงๆ แล้วมีความรับผิดชอบสูง ร่วมมือกับพอลลักซ์เพื่อสร้างทหารรับจ้างคู่ขนานนามว่า \"เลือดของเรเวน\" เพื่อปกป้องเด็กๆ ที่อาศัยอยู่ในโบสถ์ได้ดียิ่งขึ้น",
  str_item_intro_1601701 = "สง่างามและมีความสามารถ เธอมีอดีตที่เธออยากจะทิ้งเอาไว้เบื้องหลัง ตอนนี้เป็นผู้พิทักษ์คริสตจักรที่แข็งกร้าวซึ่งให้ที่พักพิงแก่เด็กเร่ร่อนในความอิ่มเอิบที่ถูกเหยียบย่ำ",
  str_item_intro_1401691 = "เด็กสาวผู้ทรงพลังอย่างไร้เหตุผลซึ่งมาจากอัมบราตัน ภายใต้รูปลักษณ์ภายนอกที่เยือกเย็นและมีเสน่ห์ของเธอเต้นด้วยหัวใจที่บริสุทธิ์และแน่วแน่ และเธอถือว่างานใดๆ ที่มอบให้เธอเป็นส่วนหนึ่งของการฝึกเพื่อเป็นนักต้มตุ๋นตัวจริง",
  str_item_intro_1601721 = "สาวน่ารัก ร่าเริง และมองโลกในแง่ดี เพื่อไล่ตามความฝันของเธอในการทำงานในภาพยนตร์ เธอตั้งรกรากใน Umbraton's Alleywood ด้วยตัวเธอเองและพบว่ามีงานทำในอุตสาหกรรมภาพยนตร์ที่กำลังเฟื่องฟู แม้ว่าเธอจะผ่านความยากลำบากมานับไม่ถ้วน แต่เธอก็ไม่เคยคิดที่จะยอมแพ้",
  str_item_intro_1601731 = "หัวหน้าบัตเลอร์ของตระกูล Andersen ใน Umbraton สง่างาม สุภาพ และเป็นผู้ชอบความสมบูรณ์แบบต่อความผิด เขาสาบานที่จะตอบแทนความเมตตาของเจ้านายด้วยการรับใช้เขาด้วยกำลังและความจงรักภักดีทุก ๆ ออนซ์",
  str_item_intro_1601751 = "\"Cyborg สู้รบ\" ที่รู้จักกันในชื่อ Axelia เป็นสมาชิกของ Illumina Federation แม้จะมีชื่อเสียง แต่สภาพร่างกายของเธอก็น่าเป็นห่วงเป็นการส่วนตัว",
  str_item_intro_1501761 = "แพทย์ด้านการต่อสู้ของ Lumopolis ซึ่งครั้งหนึ่งเคยได้รับการช่วยชีวิตโดยแพทย์ชื่อ John; หลังจากนั้นเธอก็ตัดสินใจที่จะเป็นหมอที่ดี",
  str_item_intro_1601771 = "เกิดใน Umbraton ไอดอลสาวชื่อดังคนนี้มีโชคลาภ กระจายการมองโลกในแง่ดีและแง่บวกให้กับทุกคนที่เธอพบ",
  str_item_intro_1601781 = "นักสัตววิทยาที่อยู่อย่างสันโดษในป่า แม้ว่าเขามักจะทำให้ผู้คนโกรธเคืองด้วยคำพูดและการกระทำของเขา และรังแก Fia ลูกศิษย์ของเขา แต่เขาก็ใจดีกับสัตว์มหัศจรรย์ทุกตัว",
  str_item_intro_1501801 = "แม้ว่าปัจจุบันเธอจะเป็นเพียงนักข่าวฝึกหัดของสำนักข่าวเล็กๆ แห่งหนึ่ง แต่เธอก็กระตือรือร้นที่จะสัมภาษณ์ใครก็ตามที่เธอทำได้และรับฟังข่าวซุบซิบล่าสุดทั้งหมด เป้าหมายของเธอคือการเป็นนักข่าวที่มีชื่อเสียงที่สุดใน Umbraton",
  str_item_intro_1601811 = "ครั้งหนึ่งแม่ทัพใหญ่แห่งอาณาจักร Zhao ในหลงโจว ปัจจุบันเป็นคนพเนจร ไม่ว่าเมื่อไหร่หรือที่ไหน เขาก็ไม่สนใจนอกจากเป้าหมายส่วนตัวของเขาเอง",
  str_item_intro_1601821 = "กัปตันของ Shadowind ห่างเหิน เด็ดขาด สิ่งที่คุณเห็นคือสิ่งที่คุณได้รับ เป้าหมายของเธอคือการสร้างเรือพิสัยไกลที่ยิ่งใหญ่ที่สุดและทำให้เส้นทางการเดินทางปลอดภัยที่สุด",
  str_item_intro_1501831 = "แพทย์หนุ่มที่ศึกษาภายใต้หมอผู้ยิ่งใหญ่ Bucunzi ตัวเล็กแต่มีความทะเยอทะยาน เขาเป็นหมอที่เชื่อถือได้และมีลิ้นที่แหลมคม ที่กล่าวว่าคำชมเพียงคำเดียวก็เพียงพอที่จะทำให้เขาเป็นตัวของตัวเองเต็มที่",
  str_item_intro_1601841 = "สมาชิกอาวุโสของแผนก Rediesel Wrench ของ Courier Union เธอเป็นคนสบายๆ และไม่เป็นระเบียบ แต่ก็เป็นนักสังเกตที่ฉลาดมากเช่นกัน",
  str_item_intro_1501851 = "แม้ว่าเธอจะเป็นเพียงมือใหม่ แต่เธอก็เป็นหนึ่งในไม่กี่คนที่มีจิตสำนึกและมีความรับผิดชอบใน Courier Union อย่างไรก็ตาม การปฏิบัติตามกฎของสหภาพแรงงานที่เคร่งครัดมากเกินไปของเธอทำให้เกิดความผิดพลาดได้",
  str_item_intro_1601861 = "หญิงสาวผู้สูงศักดิ์ที่ได้รับตำแหน่งเป็นมรดก และเธอยังเป็นผู้พิพากษาของ Hall of Justice อีกด้วย เธอยังมีรัฐธรรมนูญพิเศษที่ทำให้เธอหลับตลอดเวลา",
  str_item_intro_1601891 = "ผู้พิพากษาผู้เที่ยงธรรมแห่ง Lumopolis ผู้เกลียดชังความชั่วร้ายทั้งหมด และเขาปฏิบัติต่อผู้อื่นอย่างเท่าเทียมกันเสมอ ในขณะเดียวกัน เขาก็มีด้านที่ดื้อรั้นและห่างเหิน",
  str_item_intro_1501901 = "ผู้พิพากษาที่มีพรสวรรค์สูงของ Lumo Hall of Justice ผู้ซึ่งไม่มีความทะเยอทะยานมากนักและต้องการใช้ชีวิตธรรมดาที่มีความสุขและมั่งคั่งเท่านั้น",
  str_item_intro_1601911 = "หมาป่าเดียวดายจาก Umbraton ที่มีเชื้อสายกึ่งมนุษย์ ซึ่งมักจะลงเอยด้วยการเข้าใจผิดโดยไม่จำเป็นเนื่องจากขาดไหวพริบโดยทั่วไป",
  str_item_intro_1501931 = "แม้จะเกิดในตระกูลขุนนาง แต่เธอก็เดินตามเส้นทางของตัวเองเสมอและทำตามหัวใจของเธอเพื่อเป็นผู้พิพากษาคุมประพฤติแห่งลูโมโปลิส",
  str_item_intro_1601921 = "กัปตันของอัศวินเหล็กหนาม เขามีบุคลิกที่เด็ดขาด สง่างามและเป็นมิตร เขาพยายามที่จะเปลี่ยน Lumopolis ที่เน่าเปื่อยให้กลับมามีชีวิตอีกครั้ง",
  str_item_intro_1601991 = "เธอเกิดในครอบครัวของทหารอิลลูมินา และปัจจุบันเป็นเจ้าหน้าที่ข่าวกรองอาวุโสของคณะกรรมการ แผนการมากมายถูกซ่อนอยู่ลึก ๆ ในดวงตาของเธอ",
  str_item_intro_1502001 = "เจ้าหน้าที่ข่าวกรองที่ใจเย็นและไว้ใจได้ของสมาพันธ์อิลลูมินาซึ่งส่งเรื่องร้องเรียนที่คาดไม่ถึงในบางครั้ง ไม่มีใครรู้ว่าการร้องเรียนเหล่านี้เกิดขึ้นโดยตั้งใจหรือไม่ตั้งใจ",
  str_item_intro_1602011 = "อัศวินลูโมโปลิสผู้ใช้ชีวิตอย่างสันโดษในอัมบราตัน แท้จริงแล้วเธอเป็นลูกสาวคนโตของครอบครัวชวาร์ตซ์ที่ไม่ค่อยมีใครพูดถึง เธอเป็นเด็กสาวที่บริสุทธิ์และใจดีที่ปรารถนาให้บิดาของเธอยอมรับ",
  str_item_intro_1602021 = "ในช่วงรุ่งเรือง ชวาร์ตษ์ถือดาบและต่อสู้กับสุริยุปราคา ไม่เพียงเป็นผู้ปกครองลูโมโปลิสที่เพิ่งขึ้นครองราชย์เท่านั้น เขายังเป็นนักรบผู้กล้าหาญที่ต่อสู้ในแนวหน้าเพื่อยับยั้งศัตรูของอารยธรรม",
  str_item_intro_1502031 = "Jakine ทูตฝ่ายเหนือมีความกระตือรือร้นและหลงใหลในธรรมชาติ แต่การทำนายที่ไม่ชำนาญและบุคลิกที่เลินเล่อของเธอมักทำให้เธอต้องพบกับปัญหาที่คาดไม่ถึง",
  str_item_intro_1602041 = "ทุกคนบอกว่าเธอหน้าตาคล้ายกับภรรยาที่ล่วงลับของเจ้าเมือง แต่เธอก็ไม่ได้เป็นเธอด้วยกัน โจชัวหวังว่าจะไปที่หลาย ๆ ที่ในโลกกับความมุ่งมั่นของเธอ...",
  str_item_intro_1502051 = "บล็องก์ซึ่งเกษียณจากการเป็นกัปตันของ Nightwatch Guard เมื่อหลายปีก่อน ได้สวมเครื่องแบบออกรบอีกครั้ง น้องโรจน์กลับมาแล้ว!",
  str_item_intro_1602061 = "เกิดขึ้นในความอุดมสมบูรณ์ในอัมบราตัน เธอสามารถใช้ชีวิตอย่างสบาย ๆ ในบ้านของเธอ แต่เธอเลือกที่จะออกเดินทางด้วยตัวเอง ด้วยความมุ่งมั่นที่แน่วแน่ในการทำให้ความฝันของเธอเป็นจริง",
  str_item_intro_1602071 = "ผู้จัดการรีสอร์ต Denuo Valley ที่มีคำขวัญในชีวิตว่า \"ใช้ชีวิตในขณะนี้\" เขาอาจดูเบาสมองจากภายนอก แต่น่าประหลาดใจที่เขาน่าเชื่อถือมากเมื่อเป็นเรื่องธุรกิจ",
  str_item_intro_1502081 = "เธอไม่ใช่เพียงแค่ผู้นำทางของ Lepidoz แต่ยังเป็นกลุ่มยุทธศาสตร์ที่อยู่ด้านหลังของเรดีเซล เวรนช์ อยู่ด้วย อย่างไรก็ตามในสายตาของทุกคน เธอดูเหมือนมาสคอตที่ร่าเริงและน่ารักมากกว่าอะไรอื่น...",
  str_item_intro_1400861 = "สมาชิกอุษาวิทยาลัยแห่งลูโมโพลิสและพิธีกรงานศพ เธอมองโลกในแง่ดีและใจกล้า แต่ก็อ่อนโยนและบอบบาง รับหน้าทุกอย่างด้วยความสุขุมและรอยยิ้ม",
  str_item_intro_1400911 = "นักดนตรีผู้อ่อนโยนและเป็นมิตรของลูโมโพลิสที่จมอยู่กับความทรงจำเศร้าสร้อยอย่างง่ายดาย เธอเสียครอบครัวไปเพราะสงครามเลยอาศัยอยู่ด้วยความทุกข์และทำใจปล่อยวางยาก",
  str_item_intro_1500701 = "ผู้เป็นกลางแห่งอัมบราตันที่ถือครองพลังแห่งมังกรอยู่ เธอเป็นคนหยิ่งยโสจองหองที่อารมณ์เสียอยู่ตลอดเวลา เธอมักรู้สึกว่าตนแบกรับโชคชะตาของครอบครัวไว้",
  str_item_intro_1500751 = "บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ที่มั่นใจในเทคโนโลยีการสื่อสารของเธอมาก เธอชอบบ่นและตะคอกคนอื่นในช่องสื่อสารแต่กลับหงุดหงิดเมื่อเจอปัญหา",
  str_item_intro_1500841 = "ผู้นำโลกใต้ดินแห่งอัมบราตัน มีนิสัยเด็ดขาด ไร้กังวล และภักดีต่อพวกพ้องข้างกายอย่างสุดใจ ครั้งหนึ่งเขาผ่านบททดสอบอันแสนสาหัสที่เดิมพันด้วยชีวิต และได้มาซึ่งเกียรติยศและอำนาจอันสูงส่งอย่างที่เป็นในปัจจุบัน",
  str_item_intro_1500881 = "สมาชิกเรดีเซล เวรนช์ที่มักได้รับงานสำรวจ เธอนอบน้อม ขี้อายและซุ่มซ่าม ควบคุมพลังมหาศาลของตนในการต่อสู้ไม่ได้เพราะตื่นเต้นเกินเหตุ ซึ่งแม็กกี้เองก็ค่อนข้างกลุ้มใจกับเรื่องนี้ด้วย",
  str_item_intro_1500901 = "นักร้องไอดอลของเรดีเซล เวรนช์ ดูภายนอกแล้วบาร์บาร่าอ่อนโยนและนิสัยดีแต่จะเผยด้านฉุนเฉียวออกมาเมื่อพบแฟนคลับที่ข้ามเส้นกันเกินไป",
  str_item_intro_1500921 = "สมาชิกทรู ออเดอร์ที่จริงใจและไม่ยืดหยุ่น เธอมักจะคิดอยู่อย่างเดียวเสมอและมุ่งมั่นทำให้สำเร็จเมื่อรู้ว่าคืออะไร เธอมีรสนิยมที่หาตัวจับยากและมักถกเถียงกับคนอื่น",
  str_item_intro_1600601 = "โจนาเป็นสมาชิกเรดีเซล เวรนช์และมือแม่นปืนผู้เชี่ยวชาญที่เคยเป็นนักล่าค่าหัวมาก่อน เธอดื้อด้านและไม่สนใจโลกเท่าไรนัก แต่ก็ไม่ปรานีต่อศัตรู ไม่มีใครเคยเห็นเธอโดยไม่ใส่กุญแจมือเลย",
  str_item_intro_1600641 = "ผู้บัญชาการกองทัพคุ้มกันสหพันธรัฐอิลลูมินาผู้มุ่งมั่นที่ท้าทายชิงอำนาจของสหพันธรัฐอิลลูมินา เธอเป็นคนคล่องแคล่ว ทำงานไม่รู้จักเหนื่อยเพื่อหาพลังที่มหาศาลยิ่งกว่า อีกทั้งยังมีความต้องการแรงกล้าที่จะผูกขาดทุกอย่างเสียด้วย",
  str_item_intro_1600891 = "ผู้พิพากษาสูงสุดแห่งศาลยุติธรรมลูโม เธอทั้งใจดี อ่อนโยน ซื่อตรง แกร่งและมีจิตใจอุทิศตน ด้านหวาดระแวงของเธอก็มีในใจแต่เธอสะกดมันเอาไว้",
  str_item_intro_1601031 = "ผู้ไต่สวนจากทรู ออเดอร์และนักติดตามกระตือรือร้นของวิกตอเรีย ดวงตาถูกยับยั้งเนื่องจาก \"พลังแห่งความพินาศ\" ของพวกเขา",
  str_item_intro_1500871 = "หนึ่งในทหารชนชั้นสูงที่ลูโมโพลิส เพลิดเพลินไปกับพลังและศักดิ์ศรีอันยิ่งใหญ่ ทั้งอนุรักษ์นิยมและมีความรับผิดชอบสูงแต่ก็หยิ่งยโสด้วย แม้ว่าจะค่อย ๆ พัฒนาตัวเองขึ้นมาก็ตาม",
  str_item_intro_1401011 = "เจ้าหน้าที่อิลลูมินาที่มีหน้าที่รับผิดชอบในการสื่อสาร เธอทำงานด้วยความนอบน้อมและอุตสาหะแม้จะมีแกล้งเล่นเป็นบางครั้งก็ตาม",
  str_item_intro_1401021 = "มิตรของสเปียร์โรว์ในอัมบราตัน เธอมีจิตใจรักอิสระและเป็นที่รู้จักด้วยอมยิ้มและกระแสไฟฟ้าที่ออกมาจากมือของเธอ",
  str_item_intro_1500991 = "ทหารรับจ้างเร่ร่อนในอัมบราตัน เกิดมาพร้อมคำสาปทำให้เป็นโลหิตจางและต้องพึ่งพาดาบเวทมนตร์เพื่อเอาตัวรอด",
  str_item_intro_1501001 = "สมาชิกทรู ออเดอร์ที่เกิดในครอบครัวชนชั้นสูงยุคโบราณ เธอถูกเลือกให้เฝ้าสุสานลับตั้งแต่ยังเด็ก ร่ำเรียนสูงและฉลาดเฉลียวแต่กลับเย็นชาเสียนี่",
  str_item_intro_1600931 = "เจ้าหน้าที่วิจัยในอิลลูมินาที่มีหน้าที่ดูแลชีววิทยาศาสตร์ ดูเหมือนจะเป็นคนชอบอู้และไม่เอาไหน แต่กลับแสดงด้านที่ใจเย็นในช่วงเวลาสำคัญ",
  str_item_intro_1500981 = "ไร้อารมณ์เพราะคำสาปแต่เหมือนจะเชื่อใจคนแรกที่เห็นในวันนั้น ๆ ได้ ตอนนี้อาศัยอยู่ในอัมบราตันอย่างสันโดษ ทำงานเป็นมือสังหารให้อีสต์วาน",
  str_item_intro_1400621 = "ผู้พิทักษ์ผืนป่าจากนอร์ธแลนด์ หนุ่มหล่อเหลาที่ท่าทางดูไม่ได้เรื่องแต่ใจกว้าง เขาใฝ่หาความสัมพันธ์ เขาดูเป็นวัยรุ่นอยู่เพราะยังเด็กอยู่มาก",
  str_item_intro_1400951 = "เกิดมามีร่างเป็นสัตว์ เธอเป็นทหารรับจ้างเร่ร่อนที่โมโหโกรธาใส่ทุกสิ่ง",
  str_item_intro_1300941 = "พลลาดตระเวนที่บริสุทธิ์ ใจดีและใสซื่อจากนอร์ธแลนด์ เธอเคยชินกับการลาดตระเวนคนเดียวในความหนาวเหน็บและนำความหวังนิจนิรันดร์ไปให้ผู้คน",
  str_item_intro_1600961 = "เกิดในอิลลูมินา เธอเร่ร่อนไปยังอัมบราตันเพื่อหาปู่ของเธอ เธอมักจะชอบเหม่อลอยและถูกหลอกอยู่บ่อยครั้ง",
  str_item_intro_1500971 = "มือสังหารในอัมบราตันที่ทำภารกิจ \"พิเศษ\" ให้อีสต์วาน ก่อนหน้านี้เขาเป็นแพทย์ผ่าตัดฝีมือดี",
  str_item_intro_1500561 = "นักล่าอิคลิพไซท์ผู้โดดเดี่ยวเร่ร่อนอยู่ในแอสตราด้วยความร่าเริง เขาพกปืนไรเฟิลสำหรับล่าและสมุดโน้ตไปทุกทีที่เขาไป เตรียมพร้อมออกล่าอิคลิพไซท์และเขียนบันทึกช่องโหว่ไว้พร้อมกัน",
  str_item_intro_1701071 = "วีรบุรุษโบราณที่ถูกขับไล่ แปลงกายเพราะเกลียดชังอิคลิพไซท์ ครั้งหนึ่งเคยดุร้ายอำมหิตแต่ได้สติกลับมาและมีนิสัยมองโลกในแง่ดี",
  str_item_intro_1701081 = "วีรบุรุษโบราณที่ถูกขับไล่ แปลงกายและได้รับพลังมหาศาล แต่กลับสร้างมหันตภัยเพราะไม่สามารถควบคุมพลังได้และยังรู้สึกผิดมาจนถึงทุกวันนี้",
  str_item_intro_1701091 = "วีรบุรุษโบราณที่ถูกขับไล่ เสียอารมณ์ความรู้สึกเกือบทั้งหมดไปหลังได้รับการแปลงกาย ว่ากันว่าถูกรัฐทิ้งหลังจากทำภารกิจจนสำเร็จ",
  str_item_intro_1701101 = "วีรบุรุษโบราณที่ถูกขับไล่ ต่อสู้กับอิคลิพไซท์ในแนวหน้าตั้งแต่ยังเยาว์ จอมเจื้อยแจ้วดื้อรั้น แปลงกายแล้วแต่ก็ยังใสบริสุทธิ์อยู่",
  str_item_intro_1501041 = "พลังมืดทำให้ดวงตาทั้งสองข้างของเธอสูญเสียการมองเห็น ดูจากภายนอกเธอเป็นคนที่สันโดษและเก็บตัว แต่เถรตรงเมื่อได้รู้จักใครสักคนแล้ว",
  str_item_intro_1601051 = "น้องสาวของซินซาที่ตกอยู่ใต้อำนาจอิคลิพไซท์และไม่สามารถควบคุมตัวเองได้ตั้งแต่เล็ก เธอกลับมามีความไร้เดียงสาหลังจากได้รับการรักษาแล้ว",
  str_item_intro_1500711 = "เจ้าของกิจการงานจิปาถะที่เดินทางจากตะวันออกไกลจนมาตั้งรกรากในอัมบราตันในท้ายที่สุด เขาคือสหายของอีสต์วาน และเป็นคนนอกรีตที่สุขุมเยือกเย็น ทำอะไร ๆ ได้อย่างมีประสิทธิภาพ",
  str_item_intro_1400671 = "เด็กสาวเสี้ยวอมนุษย์จากนอร์ธแลนด์ที่มีผมสีขาวและดำ ใสซื่อ ขี้เล่นและหัวรั้นอยู่บ้าง สงสัยในสิ่งรอบตัวอย่างมาก ตอนนี้เดินทางไปในโลกพร้อมกับตุ๊กตาเวทมนตร์สองตัว",
  str_item_intro_1601111 = "สมาชิกทรู ออเดอร์ผู้สามารถควบคุม \"อาณาเขตคริสตัล\" อันทรงพลังเพื่อจองจำศัตรูของเธอ อย่างไรก็ตาม คริสตัลสีเลือดนี้ก็ทำอันตรายกับจิตใจของเธอด้วยเช่นกัน ทำให้เธอกลายเป็นคนเข้าถึงยาก เงียบเชียบ และมักมองโลกในแง่ร้าย",
  str_item_intro_1601121 = "สายลับอิสระที่อาศัยอยู่ในอัมบราตันและผู้ครอบครองพลังเหนืออัคคี เธอเป็นคนห่ามและเถรตรง ชอบตามหาสิ่งใหม่ ๆ ที่น่าตื่นเต้น",
  str_item_intro_1501131 = "นักดนตรีและสมาชิกทรู ออเดอร์ ดูจากภายนอกเธอเป็นคนอบอุ่นและน่ารัก เธอยอมทำทุกอย่างเพื่อบรรลุเป้าหมายในการค้นพบท่วงท่าการเคลื่อนไหวอันสุดยอด เธอมั่นใจในความรู้ด้านดนตรีของตัวเองมาก และจงเกลียดจงชังในรูปแบบการเล่นดนตรีของลูโมโพลิส",
  str_item_intro_1501141 = "แม้ว่าเธอจะดูเหมือนนักล่ารางวัลทั่วไป แต่ที่จริงแล้วเธอคือสมาชิกทรู ออเดอร์ เธอเป็นคนสง่างามและอารมณ์ดีอยู่เสมอ ชอบดื่มเหล้าจิน และขณะนี้ก็กำลังสร้างเครือข่ายข่าวกรองให้กับทรู ออเดอร์พร้อมกับตามหาถิ่นที่อยู่ของบุคคลคนหนึ่งด้วย",
  str_item_intro_1601151 = "สมาชิกสหภาพผู้ส่งสารผู้ทำหน้าที่ให้บริการในภูมิภาคลูโมโพลิส สงบเงียบและสง่างาม มีพลังลึกลับในการสื่อสารกับสัตว์และพืช ไม่ว่าไปที่ไหน สัตว์ต่าง ๆ และหิ่งห้อยนับไม่ถ้วนก็ติดตามเธอไปทุกแห่งหน",
  str_item_intro_1601161 = "ช่างเทคนิคเรดีเซล เวรนช์ผู้มีอารมณ์ดีที่ปฏิเสธใครไม่เป็น ซึ่งเป็นอุปนิสัยที่มักทำให้เขาตกอยู่ในสถานการณ์ที่น่ารำคาญทุกรูปแบบ เขาเป็นผู้เชี่ยวชาญด้านการซ่อมแซมเครื่องจักรทุกประเภท แต่ก็อยากสร้างหุ่นยนต์เป็นของตนเองด้วยเช่นกัน",
  str_item_intro_1401271 = "เคยพักอาศัยอยู่ในทะเลทรายเรดีเซล แล้วจึงมาเข้าร่วมกับทรู ออเดอร์ ความสามารถของเธอเกี่ยวข้องกับการควบคุมเศษกระดาษวิเศษเพื่อโจมตีในการต่อสู้ แม้ปกติจะดูเป็นคนขี้ขลาดตาขาว แต่ความเชื่อว่าดวงวิญญาณมีอยู่จริงนั้นจัดได้ว่าคลั่งไคล้เลยทีเดียว",
  str_item_intro_1601191 = "ชาวอิลลูมินาที่เพิ่งมาใหม่ เป็นอัจฉริยะในการต่อสู้ แต่เป็นคนสันโดษ หุนหันพลันแล่น และมีปัญหาในการสื่อสาร เธอต้องการได้รับเกียรติยศในการต่อสู้และพิสูจน์ตัวเองอย่างยิ่ง",
  str_item_intro_1601221 = "มือปืนรับจ้างจากอัมบราตันผู้มีทักษะการยิงปืนที่น่ายกย่อง เข้มงวดกวดขันและมัธยัสถ์ ทั้งยังเป็นนักสะสมของเก่าที่กระตือรือร้นและหวังว่าจะเปิดร้านขายของเก่าของตัวเองหลังจากที่หาเงินทุนได้มากพอ",
  str_item_intro_1601171 = "ทหารผ่านศึกที่เคยรับใช้ในแนวป้องกันของอิลลูมินา ตอนนี้เขาได้เกษียณจากสนามรบและทำหน้าที่เป็นเจ้าหน้าที่โลจิสติกส์ให้กับสหพันธ์ อาจจะดูหยาบคายบ้าง แต่ภายใต้ภายนอกที่ดูแข็งแกร่งนั้นซ่อนอยู่หัวใจที่มีความสุภาพและอ่อนโยน คือหนึ่งในสหายที่คุณหวังว่าจะได้พบ มีคนบอกว่าเขาตกอยู่ในภาวะซึมเศร้าเนื่องจากอดีตที่เต็มไปด้วยความรุนแรง ตอนนี้เขาได้กลับมาจากความมืดมนของความพ่ายแพ้ แข็งแกร่งกว่าที่เคยเป็นมา",
  str_item_intro_1601211 = "สมาชิกทรู ออเดอร์ที่เป็นพวกหัวขบถ มีเหตุมีผล และจริงจังสุดขีดกับทุกคน เดิมทีเธอเป็นแม่ชีที่วิหารลูโมโพลิส แต่หลังจากความอยุติธรรมที่น่าเศร้าทำให้ชีวิตเปลี่ยนไป เธอได้ตระหนักถึงความเสแสร้งหลอกลวงที่แพร่กระจายอยู่ทั่วลูโมโพลิสและออกจากวิหารมา หลังจากนั้นจึงทุ่มเทเวลาให้กับการเปิดโปงธาตุแท้ของเมืองนี้มาตลอด",
  str_item_intro_1300651 = "สมาชิกสหภาพผู้ส่งสารที่รับผิดชอบการจัดส่งในนอร์ธแลนด์ เป็นผู้ส่งสารที่กระฉับกระเฉง แม้ว่าจะซุ่มซ่ามไปบ้าง รูปลักษณ์ภายนอกและสำเนียงที่มีเอกลักษณ์ทำให้เธอดูน่ารักและใสซื่อ",
  str_item_intro_1500551 = "ผู้พิพากษาของศาลยุติธรรมแห่งลูโม เขาเป็นคนพิถีพิถันในทุกเรื่อง จริงจัง และแน่วแน่ในการตัดสินใจของตนเอง ในนามของความยุติธรรม เขากำลังขุดลึกลงไปในคดีในอดีตเพื่อค้นหาความจริงที่ซ่อนอยู่",
  str_item_intro_1601261 = "หัวหน้ากิลด์การเงินแห่งอัมบราตันและลูกสาวบุญธรรมของอีสต์วาน เธอเป็นตัวแทนที่น่าเชื่อถือที่สุดของเขา ด้วยท่าทางที่จริงจังและอดทน เธอแสดงถึงความเป็นมืออาชีพตลอดเวลา",
  str_item_intro_1601291 = "รองผู้บัญชาการหน่วยทหารรับจ้างอัมบราตัน และผู้มีเกียรติที่รอบรู้ทุกอย่างในเมือง ตอนนี้เขากำลังทำงานอย่างหนักเพื่อขยายกองกำลังทหารรับจ้างของตนเอง",
  str_item_intro_1602371 = "ถูกลือกันว่าเป็นลูกขุนของตระกูลมิราจ ซึ่งเธอมีปัญหาในการรักษาความทรงจำ แต่ยังคงมีความสุขใจและใจดี ด้วยความขอบคุณที่ได้รับการรับเข้ามาอยู่ในเมืองฮาร์เบอร์ เธอจึงมุ่งมั่นที่จะช่วยเหลือผู้อื่น",
  str_item_intro_1602381 = "มิทรา ที่เกิดในตระกูลลองกินัส รักษาหน้าที่ที่มีอายุพันปีในการปกป้องความลับของดวงดาว แม้ว่าภายนอกของเธอจะเงียบสงบและมีขนสีดำ แต่เธอซ่อนคมชัดอยู่เบื้องล่างธรรมชาติที่สงบของเธอ",
  str_item_intro_1702361 = "เคลย์มอร์เคยเป็นที่ปรึกษาขวาของพระราชาและเป็นกัปตันของกลุ่มนักล่าผู้เงียบงัน โดยเขายึดถือความยุติธรรมด้วยความมั่นคงที่ไม่สั่นสะเทือน แม้ไม่ได้รับความโปรดปรานจากลูมินา แต่เขาก็สร้างอนาคตด้วยพลังดาว",
