  str_item_5234040 = "\"เทศกาลอาหารแลกน้ำมัน\"",
  str_item_5234041 = "“เข้าไปในบ้านผีสิง”",
  str_item_5234042 = "“สเปลนเดอร์ อิลลูมินา!”",
  str_item_5234031 = "รูปปั้นอสูรหนาม",
  str_item_5234032 = "รูปปั้นอสูรสามเขา",
  str_item_5241014 = "บอลลูนเจ้าอ้วนสีสด",
  str_item_5232007 = "เปลือกหอยลอยทะเล",
  str_item_5234035 = "อนุสาวรีย์เส้นสาย",
  str_item_5222001 = "พิมพ์เขียวรั้วต้นไม้เตี้ย",
  str_item_5222002 = "พิมพ์เขียวรั้วต้นไม้สูง",
  str_item_intro_5212001 = "\"ข้าจมเรือลำนี้ได้แล้ว เจ้าจะโดนตีเป็นรายต่อไป! เฮ้ย! ทำไมเจ้าถึงลื่นลงไปตามแขนของข้าได้เนี่ย? ก็ได้ คราวนี้ข้าจะปล่อยเจ้าไป เพราะดูท่าทางเจ้าสนุกสุดเหวี่ยงเลย!\"\nสไลเดอร์ตัวนี้น่าจะออกแบบตามหนวดของสัตว์ประหลาดในทะเล น่าตื่นเต้นใช่ไหมล่ะ?",
  str_item_intro_5212002 = "อยากรู้จังว่าใครเป็นคนย้ายเสาเรือมาไว้ที่นี่ อย่างไรก็ช่าง เราสามารถมองเห็นได้ไกลมากถ้าปีนขึ้นไปข้างบน จะตะโกนว่า \"กัปตัน! มีแผ่นดินข้างหน้า!\" เหมือนเวลาล่องเรือในทะเลก็ได้",
  str_item_intro_5212003 = "เต็นท์น้ำหนักเบาที่ตั้งอยู่ได้อย่างมั่นคงบนหาดทรายนุ่ม แถมยังทำจากวัสดุทนไฟซะด้วย น่าจะเป็นเพราะนักท่องเที่ยวชอบก่อกองไฟเล่นกันในเต็นท์นั่นเอง",
  str_item_intro_5212004 = "ชิงช้านี้กว้างพอที่จะนั่งคู่กันได้สองคน เหมาะสำหรับนั่งเล่นริมชายฝั่งทะเล คุณจะมีความทรงจำที่ดีจากลมทะเลที่พัดเอื่อยสัมผัสใบหน้าขณะที่นั่งเล่นบนชิงช้านี้",
  str_item_intro_5212005 = "เก้าอี้อาบแดดตัวนี้ทำจากซากเรือครึ่งลำ ดูเหมือนจะเป็นผลงานสร้างสรรค์อันน่าอัศจรรย์ของกลุ่มกะลาสี",
  str_item_intro_5212006 = "โครงป้ายที่ริมหาด จะวาดลวดลายหรือเขียนข้อความไว้ก็ได้ รวมทั้งสามารถผูกธงหลากสีเพื่อดึงดูดนักท่องเที่ยวได้อีกด้วย",
  str_item_intro_5212007 = "เพื่อการนำวัสดุหมุนเวียนกลับมาใช้ใหม่ กะลาสีบางส่วนจึงนำซากเรือครึ่งลำมาเลาะเอาไม้กระดานไปใช้ทำโต๊ะเก้าอี้ และนำกระดูกงูมาใช้ปลูกเถาวัลย์เพื่อให้ร่มเงาจากแสงแดด",
  str_item_intro_5212008 = "ร่มที่มีน้ำหนักค่อนข้างมาก เคลื่อนย้ายไปมาได้ยาก ที่ฐานของด้ามจับเป็นปลายแหลมซึ่งมีไว้ปักลงพื้นให้แน่นหนา",
  str_item_intro_5212009 = "เก้าอี้ตัวนี้ออกแบบมาให้โอบรัดร่างกาย ทำให้นอนสบายและมีพื้นที่มากมายไว้เหยียดแขนขาได้อย่างสบายใจ",
  str_item_intro_5212010 = "โต๊ะที่มีน้ำหนักเบา เคลื่อนย้ายง่าย นักท่องเที่ยวยกไปมาได้อย่างอิสระ ทำให้หาจุดเหมาะ ๆ เพื่อสังสรรค์กับเพื่อนฝูงริมหาดได้อย่างง่ายดาย",
  str_item_intro_5212011 = "ถ้าเหนื่อยนักก็พักก่อน! นี่แหละคือเวลาที่คุณต้องการเก้าอี้ตัวนี้! นั่งลงจิบเครื่องดื่มเพื่อฟื้นฟูพลังงานของคุณอย่างรวดเร็วเลย",
  str_item_intro_5212012 = "หา? เสาพวกนี้มันอยู่ใต้ทะเลไม่ใช่เหรอ? ที่นี่มีปะการังด้วยเหรอ? นี่ใครเอาขึ้นมาจากทะเลเมื่อไหร่กัน? พอตรวจสอบดูอย่างใกล้ชิดแล้ว จะเห็นได้ว่าที่จริงแล้วนี่คือรั้วไม้ที่ทาสีไว้อย่างชำนาญ มันทั้งสวยและช่วยสร้างบรรยากาศแห่งท้องทะเลได้เป็นอย่างดี",
  str_item_intro_5212013 = "การปูพื้นทรายละเอียดในพื้นที่นี้ช่วยสร้างบรรยากาศแห่งท้องทะเลได้อย่างมาก จนเหมือนว่าเราอยู่ริมหาดกันเลยทีเดียว",
  str_item_intro_5241018 = "ตู้ขนาดใหญ่ที่ใส่ก้อนหินและพืชน้ำ ทั้งยังมีอุปกรณ์ที่ทำให้น้ำไหลเวียนอยู่ตลอดเวลา เพื่อสร้างสภาพแวดล้อมให้ปลาว่ายน้ำกันได้อย่างปลอดภัยอีกด้วย",
  str_item_intro_5241019 = "เมื่อมองดูปะการังตกแต่งสีสันสดใสที่ตั้งอยู่บนฐานหินนี่แล้ว แทบรู้สึกเหมือนว่าเราอยู่ในทะเลแล้วก็เห็นฝูงปลาว่ายน้ำผ่านไปเลย...",
  str_item_intro_5241020 = "หนึ่งในซากปรักหักพังโบราณลึกลับ กล่าวกันว่าดูดซับ Lumina โดยรอบและปล่อยแสงที่ไม่เป็นอันตราย ซึ่งทำให้เป็นตัวเลือกในอุดมคติสำหรับการตกแต่ง การให้แสง หรือส่งสัญญาณไปยังระยะไกล",
  str_item_intro_5212014 = "เปลือกหอยอะไรใหญ่จังเลย! ใหญ่จนเหมือนไม่ใช่ของที่เกิดขึ้นเองตามธรรมชาติเลยนะ นี่เป็นของล้ำค่าที่หายากแน่นอนถ้ามีไข่มุกอยู่ข้างใน เปลือกหอยนี้ไม่สูญเปล่าแน่นอนเพราะมีคนเอาเบาะไปวางไว้ ทำให้เป็นโซฟาแสนสบาย",
  str_item_intro_5212015 = "เวลาที่ลูกโป่งรูปแมงกะพรุนนี้ลอยขึ้นไปบนฟ้า ริบบิ้นที่ห้อยลงมาจะกลายเป็น \"หนวด\" ทำให้ดูเหมือนแมงกะพรุนของจริงลอยอยู่บนฟ้า",
  str_item_intro_5212016 = "อย่าให้รูปลักษณ์ภายนอกทำให้คุณกลัว! มันแค่อยากช่วยให้แสงสว่างในเส้นทางของคุณเท่านั้นเอง เห็นไหม? ในปากไม่มีฟันสักซี่",
  str_item_intro_5212027 = "สตูลทรงสูงที่เสริมโต๊ะยาวได้อย่างลงตัว ความสูงที่ปรับได้และที่นั่งแบบหมุนได้ทำให้เป็นที่ชื่นชอบของเด็ก ๆ หลายคน",
  str_item_intro_5212028 = "หม้อสีเขียวที่ขาดไม่ได้ที่เสริมการตกแต่งตามเทศกาลอื่นๆ",
  str_item_intro_5212029 = "รั้วแถวทาสีพิเศษที่ใช้สำหรับกั้นช่วงเทศกาล ใส่เครื่องประดับอื่นๆ ลงไปได้เลย!",
  str_item_intro_5212030 = "สถานรับเลี้ยงเด็กที่จัดตั้งขึ้นโดยเฉพาะสำหรับเทศกาล Windelion โดยมีดอกแดนดิไลอันที่โตเต็มที่รอการปลดปล่อยในคืนเทศกาล",
  str_item_intro_5212031 = "โครงสร้างอาจเรียบง่ายและสร้างขึ้นด้วยไม้ทั่วไป แต่มีความทนทานเนื่องจากชิ้นส่วนเสริมแรง นอกจากใช้เป็นโคมแขวนแล้ว ยังสามารถใช้เป็นที่พักพิงชั่วคราวสำหรับสัตว์ขนาดเล็กได้อีกด้วย",
  str_item_intro_5212032 = "จัดแนวเสาต่ำสำหรับเทศกาลเหล่านี้และคุณจะได้รั้ว",
  str_item_intro_5234034 = "ภายนอกของงานหินดูค่อนข้างหยาบ แต่ภายในนั้นซับซ้อนมาก ด้วยพื้นที่ขนาดใหญ่ เพียงเปิดฝาเพื่อรีไซเคิลขยะภายในอย่างง่ายดาย",
  str_item_intro_5212020 = "เหมาะสำหรับริมถนน ผู้สัญจรผ่านไปมาสามารถวางสิ่งของชิ้นเล็กๆ ไว้บนนั้นหรือปรับเปลี่ยนตามความชอบและเปลี่ยนให้เป็นสถานที่สำคัญได้",
  str_item_intro_5212021 = "ดูเหมือนใหญ่ แต่ทำจากไม้และกลวงภายใน เบามากและสามารถเคลื่อนย้ายไปมาระหว่างสถานที่ต่างๆ ได้อย่างรวดเร็ว ส่วนใหญ่ใช้เป็นของประดับตกแต่งวันหยุดรอง",
  str_item_intro_5212022 = "เสาไม้เรียบง่ายที่เสริมความแข็งแรงภายในอย่างเห็นได้ชัดสำหรับสัตว์เล็กๆ จำนวนมากให้เกาะเกาะ คงจะดีที่คนอื่นพึ่งได้เหมือนกัน...",
  str_item_intro_5212023 = "น้ำหนักเบา พร้อมโครงสร้างพิเศษเพื่อรองรับโคมหลายตัวในคราวเดียว ใช้สำหรับประดับไฟหรือประดับตกแต่งในเทศกาลต่างๆ",
  str_item_intro_5212024 = "ประกอบด้วยเสาไม้และผ้าขาวประดับด้วยเถาวัลย์ต่างๆ ใบไม้เขียว และดอกไม้ต่างๆ ส่วนใหญ่ใช้ในเทศกาลต่างๆ จะนำโชคดีมาให้ถ้าม่านพัดคุณหรือถ้าลมพัดกลีบหรือใบไม้มาที่ไหล่ของคุณ",
  str_item_intro_5212025 = "ไม่รู้ใครสร้างรังแรกสำหรับเทศกาลนี้ แต่ดึงสัตว์เล็กจำนวนมาก สิ่งนี้จึงกลายเป็นประเพณีที่ไม่เป็นทางการสำหรับผู้คนในเทศกาลต่อมา มีข่าวลือว่ายิ่งสัตว์ตัวเล็ก ๆ ดึงดูดมากเท่าไร ผู้สร้างก็จะยิ่งได้รับพรมากขึ้นเท่านั้น",
  str_item_intro_5212026 = "โต๊ะนี้ค่อนข้างหนักเพราะทำจากไม้จริงมีหินรองรับ ควรจะเลือกเต้นเพื่อป้องกันไม่ให้พัง",
  str_item_intro_5234021 = "สามารถวางได้ไม่เฉพาะในห้องแต่ยังอยู่ในตู้ในเขตชานเมืองด้วย ไม้มีความแข็งแรงเพียงพอต่อแสงแดดและฝน โดยปกติจะทำหน้าที่เป็นที่เก็บข้อมูลชั่วคราวสำหรับอ็อบเจ็กต์ที่ไม่ได้ใช้งานอยู่ในปัจจุบัน",
  str_item_intro_5212018 = "ตุ๊กตา Windelion หลากสีสันซึ่งเป็นที่นิยมของเด็กๆ ในช่วงเทศกาล Windelion บรรจุกระดาษที่หกออกมาหลังจากถูกเปิดออก บางครั้งใส่ระฆังหรือ \"เหรียญนำโชค\" เพื่อดึงดูดเด็กๆ ให้มากขึ้น",
  str_item_intro_5212019 = "กลองยักษ์ที่ใหญ่พอที่จะให้คนเต้นได้ พื้นผิวบาง แต่แข็งแรงพอที่จะไม่แตกถ้าคุณกระโดดขึ้นไป! ด้วยโครงสร้างพิเศษทำให้ได้ยินเสียงจากระยะไกลมาก กลองยังมีความไวพอที่จะตอบสนองต่อการเปลี่ยนแปลงในลักษณะที่ผู้คนตีกลองและสร้างเสียงที่แตกต่างกัน",
  str_item_intro_5241021 = "สัตว์สเกลนั้นไม่ธรรมดา และ Pangalo ในตำนานนั้นหายากยิ่งกว่า! รีบไปถ่ายรูปกัน! คุณสามารถแกล้งเป็นหนึ่งในนั้นด้วยตัวคุณเอง!",
  str_item_intro_1601881 = "เกิดขึ้นเป็นเจ้าหญิงแห่งราชอาณาจักรเย, ดันตังตอนนี้ถูกกักตัวในราชอาณาจักรจิ แต่เธอยังคงควบคุมอารมณ์ให้สงบเสมอ ในขณะที่หลงใหลในการศึกษา และเงียบ ๆ รอโอกาสที่จะกลับไปยังเมืองบ้านของเธอ",
  str_item_intro_5212017 = "ไม่ทราบจุดประสงค์เฉพาะของรูปปั้นหินนี้ แต่กล่าวกันว่าเป็นวัตถุโบราณในสมัยโบราณ ชาวเคลเลสต์หลายคนจะมาขอพรและขอพรในช่วงเทศกาลวินเดอไลออน ว่ากันว่าเทียนจะฟังและส่งความปรารถนาไปยังรูปปั้นเพื่อช่วยด้วยพลังลึกลับของมัน",
  str_item_intro_5271001 = "สระว่ายน้ำขนาดใหญ่ที่กินพื้นที่กว้าง สามารถว่ายน้ำและเล่นสนุกด้วยกันได้พร้อมกันหลายคน",
  str_item_intro_5272001 = "โดยปกติแล้วนี่คือสิ่งปลูกสร้างขนาดเล็กที่มีที่อาบน้ำ สร้างไว้ข้าง ๆ สระว่ายน้ำเพื่อใช้ชำระร่างกาย และที่สำคัญกว่านั้นก็คือ \"ใช้เปลี่ยนเสื้อผ้า\"",
  str_item_intro_5272002 = "การว่ายน้ำเป็นกิจกรรมที่เหนื่อยมาก ดังนั้นคุณก็ควรพักผ่อนสักหน่อยถ้ารู้สึกเหนื่อยล้าเกินไป คงเหมือนสวรรค์เลยนะถ้าตอนนี้ได้ไอศกรีมจากเครื่องทำไอศกรีมอัตโนมัติสุดวิเศษเครื่องนี้",
  str_item_intro_5272003 = "ดนตรีคือสิ่งจำเป็น! เล่นน้ำก็เบื่อได้ง่าย ๆ เหมือนกันนะ ดังนั้นมานั่งเล่น เต้นตามจังหวะเพลงกันตรงนี้เถอะ!",
  str_item_intro_5272004 = "โซฟาเป่าลมตัวนี้นอนสบายมาก ถ้าเอาลงน้ำจะใช้เป็นเรือเล็กได้ด้วย เหมาะมากไม่ว่าจะใช้นอนพักผ่อนหรือให้คนอื่นเกาะเพื่อลอยตัวในน้ำ",
  str_item_intro_5272005 = "เนื่องจากเป็นเก้าอี้เป่าลม มันจึงมีน้ำหนักเบามาก สามารถพกพาไปได้ทั่วทุกแห่งหน และพอปล่อยลมออกก็เก็บใส่กระเป๋าเป้ได้อีกด้วย ไม่เปลืองพื้นที่เลยสักนิด",
  str_item_intro_5272006 = "นี่คือพรจากสวรรค์สำหรับคนที่ว่ายน้ำไม่เป็น! แม้แต่คนบนแผ่นดินที่ไม่คุ้นเคยกับน้ำยังนำมาใช้ลอยตัวและหัดว่ายน้ำได้",
  str_item_intro_5272007 = "ของเล่นที่ใช้งานได้ทั้งในสระน้ำและนอกสระ เมื่อเป่าลมจนพองจะใช้เป็นลูกบอลเด้งดึ๋งได้ แต่ที่สำคัญที่สุดคือมันไม่จมน้ำ!",
  str_item_intro_5272008 = "การว่ายน้ำเป็นการออกกำลังกายที่เหนื่อยมาก มานอนพักตรงนี้ก่อนเพื่อฟื้นฟูแรงกายในยามที่ต้องการ หมอนรูปปลานี้นอนสบายมาก และให้บรรยากาศชายหาดสุด ๆ",
  str_item_intro_5272009 = "ร่มคันนี้ค่อนข้างใหญ่และพกพาไปไหนไม่ค่อยสะดวกนัก แต่คุ้มค่าแก่การมีไว้ในครอบครองอย่างไม่ต้องสงสัย เพราะมันให้ร่มเงาที่จะปกป้องคุณจากแสงแดดโดยตรงในวันที่อากาศร้อน",
  str_item_intro_5272010 = "ของตกแต่งที่ประดับด้วยเปลือกหอยจากทะเลมากมาย ถ้าวางไว้ในจุดที่เหมาะสม จะทำให้รู้สึกเหมือนอยู่ริมหาด",
  str_item_intro_5272011 = "ปลาดาวเป็นที่นิยมอย่างมาก เพียงแค่มีของตกแต่งพวกนี้ไม่กี่ชิ้น ก็เพียงพอที่จะสะดุดตาใครหลายคน",
  str_item_intro_5272012 = "ป้ายดิสเพลย์ที่ดูเหมือนจะใช้เทคโนโลยีโบราณเพื่อแสดงภาพต่าง ๆ โดยอัตโนมัติ! และเหมือนจะมีอุปกรณ์ลึกลับที่เปลี่ยนภาพที่แสดงได้ เมื่อก่อนนี้คงใช้ทำอะไรที่สำคัญแน่นอน...",
  str_item_intro_5271002 = "ออกแบบโดย Caelesite ที่รักมหาสมุทร มีรูปปั้นที่เข้าคู่กันซึ่งคาดว่าจะนำมาซึ่งพรจากมหาสมุทร! อยากเที่ยวทะเลมาที่นี่สักครั้ง อาจจะเป็นประโยชน์!",
  str_item_intro_5272013 = "การได้เห็นมันในมหาสมุทรหมายความว่าการเดินทางของคุณจะอุดมสมบูรณ์! แต่สิ่งมีชีวิตเหล่านี้มีอยู่จริงหรือไม่? หรือเป็นเพียงจินตนาการของกะลาสีเรือ? อย่างไรก็ตามอย่างน้อยรูปปั้นนี้ก็สวยงามและจะดึงดูดสายตาของเยาวชน",
  str_item_intro_5272014 = "ในทะเล หมึกที่หลงทางบางตัวปีนขึ้นเรือโดยไม่ได้ตั้งใจและไม่สามารถกลับขึ้นสู่น้ำได้ เมื่อกะลาสีผู้ใจดีปล่อยพวกมัน พวกเขามักจะกลับมาในอีกสองสามวันต่อมาเพื่อมอบของขวัญเล็กๆ น้อยๆ เช่น ไข่มุกเม็ดเล็กๆ หรือเหรียญที่หายไปในทะเล รูปปั้นนี้แสดงถึงมิตรภาพและการให้",
  str_item_intro_5272015 = "หลายคนบอกว่าการเห็นปลาโลมากระโดดขณะล่องเรือหมายความว่าการเดินทางของคุณจะปลอดภัย ฉันสงสัยว่าพวกเขาอวยพรผู้ที่เดินทางบนบกหรือไม่?",
  str_item_intro_5271003 = "ด้วยอุปกรณ์ประกอบฉาก อุปกรณ์ และมุมกล้องที่เหมาะสม วิสัยทัศน์ทางศิลปะของผู้กำกับแม้แต่สถานที่ที่น่าทึ่งที่สุดก็สามารถกลายเป็นความจริงได้ ตั้งแต่ดันเจี้ยนที่เต็มไปด้วยอันตรายไปจนถึงดินแดนมหัศจรรย์ที่แปลกประหลาด เรื่องราวที่ยิ่งใหญ่ที่สุดจะเกิดขึ้นก่อนฉากหลังที่สร้างสรรค์อย่างเชี่ยวชาญ",
  str_item_intro_5273001 = "แม้จะเป็นเพียงฉากหลัง แต่ก็ยังสะท้อนความงดงามของพระราชวังเมื่อถ่ายด้วยฟิล์ม สมบูรณ์แบบสำหรับการถ่ายทำละครย้อนยุคที่เกิดขึ้นในราชสำนักของผู้ปกครอง",
  str_item_intro_5273002 = "เมื่อมองแวบแรก ดูเหมือนพื้นหินที่สร้างขึ้นอย่างเชี่ยวชาญ แต่ในความเป็นจริง ไม่มีอะไรมากไปกว่ากระดาษแผ่นเดียว! ในฐานะที่เป็น \"พื้น\" แบบเสา สามารถเปลี่ยนออกได้ค่อนข้างเร็ว",
  str_item_intro_5273003 = "แม้จะเป็นอุปกรณ์ประกอบฉาก แต่ \"กระจกวิเศษ\" นี้ค่อนข้างหนัก (เนื่องจากทำจากเหล็ก) โดยธรรมชาติแล้ว การชุบทองและอัญมณีเป็นของปลอม แต่กระจกมีคุณสมบัติพิเศษอย่างหนึ่ง: พื้นผิวไม่ได้สะท้อนแสงอะไรเลย! แต่มันจะเป็นเช่นนี้ได้อย่างไร? บางทีอาจเป็นกระจกวิเศษจริงๆ ก็ได้!",
  str_item_intro_5273004 = "พร็อพที่เรียบง่ายและไม่มีอะไรเพิ่มเติม อย่างไรก็ตาม เราไม่สามารถขนส่งต้นไม้ริบหรี่จริงจากนอร์ทแลนด์ได้ นี่เป็นเพียงอุปกรณ์ประกอบฉากที่ทำจากไม้ กระดาษ และริบบิ้น และไม่ควรมอบให้กับชาวเหนือ",
  str_item_intro_5273005 = "ไม้แขวนเสื้อในชื่อเท่านั้น จริง ๆ แล้วทำจากไม้อัดราคาถูก ทดแทนที่ยอมรับได้เนื่องจากไม่ค่อยเก็บเสื้อผ้าทุกชนิด",
  str_item_intro_5273006 = "หุ่นดินเผาที่ปกคลุมไปด้วยชั้นทรายขาวบริสุทธิ์ เมื่อมองแวบแรก มันดูเหมือนมนุษย์หิมะจริงๆ มีเพียงตัวนี้เท่านั้นที่มีรูปร่างภายใต้ความร้อนของไฟบนเวที",
  str_item_intro_5273007 = "พร็อพไม้คุณภาพสูงที่สร้างขึ้นโดยช่างฝีมือผู้ชำนาญ มันดูไม่ต่างจากรูปปั้นหินจริง โครงสร้างน้ำหนักเบายังช่วยให้เคลื่อนย้ายชุดได้ง่าย",
  str_item_intro_5273008 = "ตุ๊กตาเก่าแต่ของแท้ที่ผ่านการซักและตากให้แห้ง แม้ว่าบางส่วนจะดูค่อนข้างเก่าและทรุดโทรม แต่ในบางมุม เราอาจกล่าวได้ว่าค่อนข้างใหม่",
  str_item_intro_5273009 = "ไอ-อิท ลอย! ลอยได้จริง! นี่เป็นเพียงอุปกรณ์ประกอบฉากหรืออะไรที่น่ากลัวกว่านี้? อย่างไรก็ตาม วิธีการที่ลอยได้นั้นไม่ชัดเจน แต่ภาพยนตร์ต้องการสิ่งที่น่ากลัวจริงๆ หรือเปล่า?",
  str_item_intro_5273010 = "แม้ว่าจะเป็นเพียงฉากหลังที่ติดอยู่กับผนัง แต่ก็ยังสามารถเติมเต็มความรู้สึกหวาดกลัวให้กับผู้คนได้ อาจเป็นรูปแบบการวาดภาพที่สมจริงจนน่าตกใจ หรือห้องโดยสารในฉากหลังน่ากลัวเพียงนั้น? ไม่ว่าในกรณีใด นักแสดงที่แสดงอยู่ข้างหน้าอาจไม่ใช่แค่การแสดงเมื่อพวกเขากรีดร้อง",
  str_item_intro_5273011 = "เสาพื้นใช้ร่วมกับฉากหลังในห้องโดยสารที่มีผีสิง ดูเหมือนว่าจะส่งกลิ่นเหม็นอับของแผ่นพื้นเน่าเมื่อคลี่ออก เหมาะสำหรับหนังสยองขวัญหลายเรื่อง",
  str_item_intro_5273012 = "คัมภีร์โบราณจำลองที่ได้รับการออกแบบมาโดยเจตนาให้ดูเหมือนเก่า พร้อมข้อความที่เป็นลายลักษณ์อักษรและทุกอย่าง! เพื่อรักษาบรรยากาศของความสมจริง แต่ละหน้าจะมีข้อความเดียวกันกับต้นฉบับในรูปแบบเดียวกันทุกประการ แม้แต่หน้าปกก็เป็นฉบับคาร์บอนของกันและกัน! พวกเขาดูเหมือนเป็นส่วนหนึ่งของชุด อย่างไรก็ตาม เนื้อหายังคงเป็นปริศนา",
  str_item_intro_5273013 = "พร็อพที่ออกแบบให้ลอยอยู่กลางอากาศ บางทีมันอาจจะเป็นบ้านของบอลลูนเพื่อให้มันลอยอยู่ในอากาศ? ยึดกับพื้นด้วยลวดเพื่อป้องกันไม่ให้หลุดร่อน",
  str_item_intro_5273014 = "ของเล่นที่ใช้เล็กน้อยและไม่มีการเปลี่ยนแปลงซึ่งใช้เป็นอุปกรณ์ประกอบฉากในภาพยนตร์ต่างๆ มันมักจะให้ความสุขและความบันเทิงแก่เด็ก ๆ แต่เมื่อใช้ในภาพยนตร์สยองขวัญ... มันมีผลตรงกันข้ามทีเดียว",
  str_item_intro_5273015 = "ตั้งแต่หลุมฝังศพไปจนถึงเนินดิน ทั้งหมดทำจากไม้และกระดาษทั้งหมด น้ำหนักเบาและพกพาสะดวก สามารถผลิตได้ในปริมาณมากอย่างรวดเร็ว และเพิ่มบรรยากาศที่น่าสยดสยองให้กับทุกฉาก",
  str_item_intro_5273016 = "เครื่องส่งเสียง Prop มักทำจากไม้หรือโลหะ ไร้ประโยชน์อย่างสมบูรณ์สำหรับการสื่อสารผ่าน เมื่อคุณดูหนังสยองขวัญและเห็นฉากที่มีเครื่องส่งเสียง โดยปกติแล้วจะเป็นนักแสดงที่แสดงตัวละครที่ปลายทั้งสองของอุปกรณ์เอง! ซึ่งคงจะเหนื่อย",
  str_item_intro_5273017 = "ส่วนหน้ากากผีของเสื้อคลุมนั้นสมบูรณ์แบบสำหรับหนังสยองขวัญ แต่หมวก... ดูเหมือนว่าคนที่อยู่ในทะเลทรายจะใส่ บางทีอุปกรณ์ประกอบฉากนี้กำลังพยายามแยกออกเป็นบทบาทต่างๆ เช่นกัน?",
  str_item_intro_5273018 = "หม้อและดินเป็นของจริง แต่ดอกไม้ไม่ใช่ พวกเขาทำโดยใช้ผ้าย้อม ราคาถูกและง่ายต่อการสร้าง \"พืช\" ที่สดใสเหล่านี้จะไม่มีวันเหี่ยวเฉา",
  str_item_intro_5273019 = "เมื่อจัดวางอย่างเหมาะสมแล้ว เราเกือบจะได้กลิ่นหอมของไวน์ชั้นดีหรือได้ยินเสียงกระทบกันของแก้วกับเสียงเพลงอันแผ่วเบา ใครรู้บ้างว่าฉากดังๆถูกถ่ายใน \"บาร์\" แบบนี้มีกี่ฉาก?",
  str_item_intro_5273020 = "แผ่นพื้นไม้ดูเก่ากว่าที่เป็นจริงมาก และรูก็ช่วยเพิ่มเอฟเฟกต์เท่านั้น มันดูโทรมเหมาะกับการตั้งค่าบาร์จริงๆ",
  str_item_intro_5273021 = "อาจเป็นหนึ่งในอุปกรณ์ประกอบฉากที่แพงที่สุด (เนื่องจากเป็นของจริงทั้งหมด) มันผลิตเพลงที่ยอดเยี่ยมเมื่อมีการบันทึก เนื่องจากราคาสูง ผู้เขียนบทจึงมักถูกขอให้หลีกเลี่ยงการเขียนฉากที่เกี่ยวข้องกับการทำลายเครื่องเล่นแผ่นเสียงในทุกวิถีทาง สิ่งนี้จำกัดความคิดสร้างสรรค์เล็กน้อย แต่อย่างน้อยก็สามารถใช้สำหรับการลิปซิงค์ได้ในกรณีที่นักแสดงมีเสียงร้องที่แย่มาก! นั่นคือนกสองตัวที่มีหินก้อนเดียว!",
  str_item_intro_5273022 = "เคาน์เตอร์บาร์ทำจากไม้อัด ทนทานและเชื่อถือได้ แต่ไม่สามารถเทียบได้กับเคาน์เตอร์ไม้เนื้อแข็งในแท่งจริง อย่างไรก็ตาม เก้าอี้ถูกซื้อมาจากบาร์ของจริง! และด้วยการทาสีใหม่สักหนึ่งหรือสองอันก็ดูดีเหมือนใหม่!",
  str_item_intro_5273023 = "โต๊ะและเก้าอี้เน้นบรรยากาศของบาร์ ตั้งแต่การออกแบบไปจนถึงเครื่องประดับ ใครๆ ก็ยอมรับว่าพวกเขาอยู่ในบาร์ เพียงแค่เห็นอุปกรณ์ประกอบฉากเหล่านี้ก็สามารถบอกนักแสดงได้ว่าฉากที่จะเกิดขึ้นจะเกิดขึ้นในบาร์ โดยไม่ได้รับแจ้งจากผู้กำกับ",
  str_item_intro_5273024 = "เห็นได้ชัดว่ากรรมการบางคนยืมเฟอร์นิเจอร์แบบนี้มาถ่ายทำฉากที่ไม่ธรรมดา แม้ว่านี่จะเป็นเรื่องปกติสำหรับชุดสำนักงาน แต่ก็เหมาะสำหรับชุดบาร์หรือไม่? แทบจะเหมือนยืมมาจากสตูดิโออื่นเพราะขาดเงินทุน...",
  str_item_intro_5273025 = "เปียโนจริงนั้นหนักเกินไป และมักจะเกินงบประมาณของสตูดิโอ ดังนั้นจึงควรทำด้วยอุปกรณ์ประกอบฉากที่น่าเชื่อ! นอกจากนี้ ด้วยระดับความสามารถของนักแสดงหน้าใหม่ในปัจจุบัน แทบไม่มีความจำเป็นเลยที่จะจัดหาเปียโนจริงๆ ให้พวกเขา...",
  str_item_intro_5273026 = "เวทีไม้ที่สร้างขึ้นอย่างเร่งรีบ แม้ว่าจะไม่แข็งแรงเท่าเวทีจริง แต่ก็ต้องใช้ความพยายามเพียงเล็กน้อยในการสร้าง และสามารถสร้างใหม่ได้อย่างรวดเร็วในกรณีที่แตกหัก",
  str_item_intro_5273027 = "ชั้นวางใบมีดไม้นี้เป็นของจริง แต่ใบมีดบนนั้น... ไม่มีอะไรมากไปกว่าอุปกรณ์ประกอบฉาก การใช้มันควรจะค่อนข้างปลอดภัยเนื่องจากไม่มีขอบคม ดังนั้นพวกเขาจึงสามารถใช้ในฉากต่อสู้โดยไม่ทำให้นักแสดงที่เกี่ยวข้องได้รับบาดเจ็บสาหัส",
  str_item_intro_5273028 = "ในห้องที่มีแสงแดดจัด โต๊ะและเก้าอี้ถูกจัดไว้อย่างเรียบร้อย และคุณแทบจะได้กลิ่นชอล์ค\nต้องเตรียมที่นั่งริมหน้าต่างในแถวที่สองถึงแถวสุดท้ายนี้ไว้สำหรับคุณ",
  str_item_intro_5273029 = "พื้นไม้ทั่วไปที่ได้รับการดูแลเป็นพิเศษเพื่อให้ทนทานยิ่งขึ้น โปรดเปลี่ยนเป็นรองเท้าในร่มก่อนเดิน",
  str_item_intro_5273030 = "เครื่องทำอาหารหน้าตาประหลาดเป็นเครื่องกาชาปองด้วย ยากที่จะบอกว่ามีอะไรอยู่ข้างในจนกว่าคุณจะเปิดของที่หล่นออกมา",
  str_item_intro_5273031 = "อุปกรณ์ทำอาหารลึกลับที่ดีต่อสุขภาพมากกว่าการทอด แม้แต่ผู้ที่ไม่เคยทำอาหารมาก่อนก็สามารถใช้งานได้ง่าย",
  str_item_intro_5273032 = "ฟองอากาศจะเพิ่มขึ้นเรื่อยๆ และจำเป็นต้องคนตลอดเวลาเพื่อให้ส่วนผสมเข้ากันอย่างสมบูรณ์\nงานนี้ใครล่ะจะไม่หลงรักสาวสวย",
  str_item_intro_5273033 = "ถังบรรจุของเหลวลึกลับที่มีกลิ่นลางร้ายจางๆ",
  str_item_intro_5273034 = "เครื่องจักรที่ทำงานทั้งกลางวันและกลางคืนเพื่อจัดหาอาหารและเครื่องดื่ม ผู้ช่วยชีวิตคนเกียจคร้าน",
  str_item_intro_5273035 = "ต้องใช้ทักษะอย่างมากในการเล่นเครื่องดนตรีชนิดนี้ แต่ยังคงส่งเสียงดังในตอนกลางคืนแม้ว่าจะไม่มีใครอยู่ก็ตาม",
  str_item_intro_5273036 = "นี่เป็นเพียงอุปกรณ์ประกอบฉาก อย่ากินมัน!",
  str_item_intro_5273037 = "โรงแรมที่เต็มไปด้วยชีวิตชีวา เสียงอึกทึก และผู้คนทุกประเภท ไม่มีใครรู้ว่าใครอยู่ที่นั่นหรือจะเกิดอะไรขึ้นที่นั่น",
  str_item_intro_5273038 = "พื้นไม้ที่ส่งเสียงเอี๊ยดอ๊าดเมื่อเหยียบ",
  str_item_intro_5273039 = "เคาน์เตอร์ที่วางเครื่องบันทึกเงินสดในโรงแรม เจ้านายมักจะนั่งที่นี่ ดังนั้นคุณสามารถมาคุยกับเจ้านายได้ถ้าคุณรู้สึกเหงา",
  str_item_intro_5273040 = "จานพอร์ซเลนที่สวยงาม จะเห็นได้ว่าเจ้านายมีรสนิยมดีในการตกแต่ง",
  str_item_intro_5273041 = "เครื่องประดับแปลกๆ. บางทีแขกคนใดคนหนึ่งอาจมอบมันให้กับโรงแรม",
  str_item_intro_5273042 = "เมื่อพิจารณาจากขนาดของตัวอย่างที่ทำจากกระดูกปลาแล้ว ปลาตัวนี้ต้องแข็งแกร่งมากตอนที่มันยังมีชีวิตอยู่",
  str_item_intro_5273043 = "เฟอร์นิเจอร์ไม้ที่ทำขึ้นอย่างหยาบๆ เฟอร์นิเจอร์เป็นอันดับแรกเสมอเมื่อมีแขกอารมณ์ร้าย ดังนั้นอย่าซื้ออะไรแพงเกินไป",
  str_item_intro_5273044 = "โต๊ะและเก้าอี้ที่คุ้นเคยที่ทำให้คุณรู้สึกเหมือนอยู่บ้าน",
  str_item_intro_5273045 = "เฟอร์นิเจอร์นี้ดูอบอุ่นและสบายมาก มันคงจะรู้สึกดีมากที่ได้นอนอยู่ในนี้ทั้งวันในฤดูหนาว",
  str_item_intro_5273046 = "ไวน์ที่ต้มโดยเจ้านายจะมีกลิ่นหอมแรงเมื่อเปิดฝา ผู้ที่สูดดมมักจะตกอยู่ในภวังค์และเริ่มร้องไห้กับสิ่งที่พวกเขาเสียใจในชีวิต",
  str_item_intro_5273047 = "ของฝากจากที่ไหนสักแห่งที่ให้ความรู้สึกแปลกใหม่ บางทีบางคนอาจสงสัยว่ามีเรื่องราวที่น่าจดจำระหว่างเจ้านายเก่ากับจอกนี้จากดินแดนอื่นหรือไม่",
  str_item_intro_5273049 = "อีการ้องครวญครางท่ามกลางสายลมที่พัดโชยและสภาพแวดล้อมที่มืดสลัว นักรบผู้กล้าหาญที่เดินคนเดียวที่นี่ถูกกำหนดให้เริ่มต้นการเดินทางที่อันตราย",
  str_item_intro_5273050 = "มีสถานที่นิรนามเช่นนี้มากมายในยามทุกข์ยาก ขณะที่แอบอยู่ที่นี่ พยายามอย่าหักกิ่งเหี่ยวๆ ใต้ฝ่าเท้าหรือทิ้งร่องรอยของตัวเองไว้",
  str_item_intro_5273051 = "ดูเหมือนว่าตู้ธรรมดาไม่ว่าคุณจะมองอย่างไร แต่ดาบล้ำค่าจะโผล่ออกมาทันทีเมื่อกลไกถูกกระตุ้น โปรดดำเนินการนี้ภายใต้การดูแลของผู้เชี่ยวชาญ",
  str_item_intro_5273052 = "แผ่นตกแต่งที่มีลวดลายกกอยู่ หากใช้สิ่งนี้ในการตกแต่งฉาก ผู้คนจะรู้สึกอยากควบม้าอย่างอิสระในฉากนี้",
  str_item_intro_5273053 = "แผ่นตกแต่งที่สร้างภาพลักษณ์ของทุ่งข้าวสาลี ถ้าเอามาแต่งชุดซามูไรจะซุ่มโจมตีคนในไหม?",
  str_item_intro_5273054 = "แผ่นตกแต่งที่มีลวดลายดอกทานตะวันอยู่ หากใช้สิ่งนี้ในการตกแต่งฉาก บางทีมันอาจจะดึงดูดแสงแดดให้เข้ามาหาก็ได้",
  str_item_intro_5273055 = "เครื่องเล่นวิดีโอที่มีต้นกำเนิดลึกลับซึ่งมีผ้าที่ดูโบราณอยู่ข้างใต้ ดูเหมือนว่าจะแสดงข้อมูลสำคัญบางอย่างหากมีการใส่วิดีโอเทปเข้าไป",
  str_item_intro_5273056 = "แผนที่ต้นกำเนิดลึกลับ ดูเหมือนแผนที่ทหารที่ใช้ในช่วงสงคราม และดูเหมือนจะมีข้อมูลสำคัญบางอย่าง",
  str_item_intro_5273057 = "กล่องจดหมายที่มีต้นกำเนิดลึกลับ ไม่มีใครรู้ว่าอยู่ที่นี่มานานแค่ไหนแล้ว หากคุณสังเกตรอยขีดข่วนบนกล่องจดหมายอย่างใกล้ชิด คุณอาจเห็นข้อมูลสำคัญบางอย่างที่ผู้คนในอดีตทิ้งไว้",
  str_item_intro_5234040 = "Jomu พนักงานขายที่คล่องแคล่วของ Rediesel Wrench ได้โพสต์โฆษณาที่นี่จากทุกที่ ดูเหมือนว่าพวกเขาจะเชิญชวนให้ทุกคนเข้าร่วมงานที่เรียกว่า \"เทศกาลอาหารแลกน้ำมัน\" และอ้างว่ามีข้อเสนอดีๆ มากมายให้ใช้ประโยชน์ แม้ว่าจะอยู่กลางทะเลทราย... หวังว่าอาหารจะไม่แปลกเกินไปใช่ไหม?",
  str_item_intro_5234041 = "เห็นได้ชัดว่าเป็น \"ภาพยนตร์เปิดตัวที่น่าทึ่งโดยโปรดิวเซอร์/ผู้กำกับ/นักแสดง/กล้องอัจฉริยะที่อายุน้อยที่สุดและสวยที่สุดในประวัติศาสตร์\" มันควรจะเป็นทั้งเฮฮาและน่าสยดสยองซึ่งสามารถสรุปได้จากป้ายโฆษณา จะเป็นอย่างไรที่บ็อกซ์ออฟฟิศ? เราจะต้องรอดู!",
  str_item_intro_5234042 = "โฆษณารับสมัครงานสหพันธ์อิลลูมินา มันเปล่งประกายความมั่งคั่งของ Illumina \"แนวป้องกันที่แข็งแกร่งที่สุดและสุดท้าย ยืนหยัดเคียงข้างเราในการต่อสู้กับภัยพิบัติ Eclipsite!\" มันบอกว่า. หลายคนคงเคยชินกับการเรียกร้องให้ติดอาวุธนี้",
  str_item_intro_5234031 = "สัตว์ที่มีหนามแหลมบนหัว และท่าทางโมโหร้ายเสียด้วย โชคดีนะที่มันเป็นแค่รูปปั้น",
  str_item_intro_5234032 = "มันดูอ่อนโยนมากแม้จะมีเขายาวเฟื้อยก็เถอะ... ด้วยเหตุผลอะไรบางอย่าง ทำให้คุณอยากลูบหัวมันเล่น",
  str_item_intro_5241014 = "เกิดอะไรขึ้น? ทำไมตัวพองได้ขนาดนี้ล่ะ? ถึงอย่างนั้นก็ยังบินได้อยู่ดี และทำให้ผู้ใช้งานได้รับประสบการณ์การทะยานขึ้นสู่ท้องฟ้า",
  str_item_intro_5232007 = "เทคโนโลยีของเก้าอี้หินตัวนี้ทำงานได้อย่างน่าพิศวงมาก มันจะพองขึ้นหลังจากที่คุณนั่งลงไปแล้ว และทรงตัวเองได้ด้วย ไม่ต้องกลัว ลองนั่งดูเลย!",
  str_item_intro_5234035 = "ลายแกะสลักที่ซ้ำไปซ้ำมาที่อนุสาวรีย์โบราณนี้ทำให้เกิดลวดลายที่ว่ากันว่าแสดงถึงหลักการทางคณิตศาสตร์อะไรสักอย่าง แต่รายละเอียดนั้นไม่มีผู้ใดล่วงรู้",
  str_item_intro_5222001 = "พุ่มไม้โตเร็วที่นำมาปลูกรวมกันเพื่อสร้างเป็นกำแพงเตี้ย ๆ ใช้เป็นของตกแต่งและใช้แบ่งสัดส่วนพื้นที่ได้อีกด้วย",
  str_item_intro_5222002 = "กำแพงที่ทำจากพุ่มไม้สูงที่นำมาปลูกรวมกันอย่างหนาแน่น ปกติแล้วจะใช้เป็นกำแพงด้านนอกของสวน ว่ากันว่าบางที่จะปลูกพุ่มไม้สูง ๆ แบบนี้รวมกันเพื่อทำเป็นเขาวงกตที่ทำจากต้นไม้",
