  str_item_3661026 = "ไก่งวงอบวันหยุด",
  str_item_intro_3661026 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nวันหยุดมีไว้ฉลอง! ไก่งวงอบนี้คู่ควรกับการเป็นดาวเด่นของวันทั้งในด้านรูปลักษณ์และรสชาติ คุณกำลังรออะไรอยู่?",
  str_item_3661181 = "Colossus Clock",
  str_item_intro_3661181 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเดิมทีนาฬิกาแขวนนี้มีรูปร่างเป็นนกฮูก แต่พ่อค้าบางคนเปลี่ยนให้เป็นนาฬิกายักษ์ใหญ่แทนเพราะพวกเขาคิดว่ามันธรรมดาเกินไป มันดูดีอย่างน่าประหลาดใจ แต่น่าเสียดายที่ปีกของมันไม่ขยับ",
  str_item_3661182 = "Metal Spoon Knight",
  str_item_intro_3661182 = [[
Furniture item. Can be placed in rooms on your Colossus.
Take this! Spoon attack! The Metal Spoon Knight is famous for being a glutton. Its belly is so big that even its armor must be custom-made! Look at the drool dripping from its mouth. Has it set its sights on someone's food?]],
  str_item_3661027 = "โกลดี้แฟนแบนเนอร์",
  str_item_intro_3661027 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nมาทุ่มสุดตัวเพื่อโกลดี้! ให้เพลงของเธอกระจายไปทั่วทุกมุมของทวีป!",
  str_item_3000289 = "ค่าประสบการณ์ความชำนาญพิเศษ",
  str_item_3000290 = "คะแนนความชำนาญพิเศษ",
  str_item_3661183 = "บูธดีเจ",
  str_item_intro_3661183 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nบูธดีเจที่มีระบบลำโพงในตัว มีปุ่มมากมายที่ช่วยให้ผู้ควบคุมสามารถสร้างเสียงที่ไม่มีที่สิ้นสุด ด้วยจังหวะที่เปลี่ยนแปลงตลอดเวลา ต้องใช้ดีเจเพียงหนึ่งคนในการเติมบรรยากาศปาร์ตี้และทำให้ผู้ชมดื่มด่ำไปกับเสียงเพลงอันน่าหลงใหล",
  str_item_3661184 = "โปสเตอร์สาวในฝัน",
  str_item_intro_3661184 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nทำตามความฝันของคุณ! คุณก็สามารถเป็นแบบเธอได้เช่นกัน—หญิงสาวผู้ควบคุมเวที กระจายความรักและความหวังไปทั่วทั้งทวีป! อย่าละทิ้งความฝันของคุณ!",
  str_item_3661185 = "ตุ๊กตาทูร์ด็อก",
  str_item_intro_3661185 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nยืนอยู่แถวหน้าของเทรนด์ล่าสุดของ Umbraton เสมอ! แม้ว่าจะเป็นตุ๊กตา แต่ Tourdog ก็แสดงสุนทรียภาพที่มีวิสัยทัศน์ตลอดเวลา มีข่าวลือว่าหุ่นนี้เป็นที่นิยมในหมู่ผู้ติดตามของเขามาก ดังนั้นอย่าพลาดเด็ดขาด!",
  str_item_3661186 = "เมก้าบลาสเตอร์",
  str_item_intro_3661186 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nว่ากันว่ามีเพียงผู้กล้าหาญเท่านั้นที่กล้าเล่นเครื่องดนตรีอันทรงพลังนี้ เนื่องจากเสียงที่สร้างออกมานั้นแข็งแกร่งพอที่จะเอาชนะร่างกายที่อ่อนแอของแต่ละคนได้ แม้ว่ามันจะดูน่าเกรงขาม แต่ก็เหมาะสำหรับฝูงชนที่ตื่นตาตื่นใจในคอนเสิร์ตที่มีผู้คนคับคั่ง",
  str_item_5259309 = "จี้ที่มีศักยภาพ",
  str_item_5259310 = "หิน Hexing",
  str_item_5259311 = "กล่องล็อคลึกลับ",
  str_item_5259410 = "ดาบเคออส",
  str_item_5259411 = "ถุงมือ Berserker",
  str_item_5259412 = "รูปปั้นพันธบัตร",
  str_item_5259505 = "เข็มขัดพลังงาน",
  str_item_5259506 = "วิญญาณบ้าบิ่น",
  str_item_5259507 = "ดาบแห่งแสง",
  str_item_5259513 = "เกราะบ้าบิ่น",
  str_item_5259514 = "รูปปั้นเทพีสงคราม",
  str_item_intro_5259301 = "เพิ่ม Chain Combo Damage เมื่อเชื่อมต่อ 15 แผ่นขึ้นไป",
  str_item_intro_5259302 = "เมื่อคำนวณความเสียหาย พันธมิตรจะเพิกเฉยต่อผลกระทบด้านลบของการสวนกลับจากธาตุของตน",
  str_item_intro_5259303 = "สร้างความเสียหายเพิ่มเติมทันทีเมื่อทำให้ศัตรูติดพิษ/เผาไหม้/เลือดออก",
  str_item_intro_5259304 = "เพิ่ม Max HP ของพันธมิตรอย่างถาวร",
  str_item_intro_5259305 = "เมื่อไรก็ตามที่ HP ลดลงต่ำกว่า 50% ไอเท็มฟื้น HP จะถูกสร้างขึ้นในสนาม",
  str_item_intro_5259306 = "ฟื้นฟู HP เมื่อเริ่มแต่ละเวฟ",
  str_item_intro_5259307 = "มอบโล่เมื่อเริ่มทุกเวฟ",
  str_item_intro_5259308 = "สร้างความเสียหายสูงต่อศัตรูที่ไม่ใช่บอสรอบตัวคุณทุกรอบ",
  str_item_intro_5259309 = "ลดคูลดาวน์ของ Special Caelesite Gear ลง 1",
  str_item_intro_5259310 = "พันธมิตรและศัตรูทั้งหมดสูญเสียสัดส่วนของ HP ทุกรอบ",
  str_item_intro_5259311 = "สุ่มรับอุปกรณ์พิเศษ Caelestite แบบสุ่มเพิ่มเติม",
  str_item_intro_5259401 = "เพิ่มความเสียหายที่ศัตรูได้รับ",
  str_item_intro_5259402 = "เปลี่ยนเปอร์เซ็นต์การรักษาส่วนเกินของ Aurorian ให้เป็นเกราะป้องกัน",
  str_item_intro_5259403 = "ทำให้พันธมิตรและศัตรูทั้งหมดในพื้นที่เป็นพิษเมื่อศัตรูตาย\nลดความเสียหายพิษที่ได้รับจากพันธมิตร",
  str_item_intro_5259404 = "เพิ่มความเสียหายของ Chain Combo เมื่อได้รับผลจากดีบัฟ",
  str_item_intro_5259405 = "มีโอกาสน้อยมากที่จะฆ่าศัตรูที่ไม่ใช่บอสในทันที",
  str_item_intro_5259406 = "ฟื้นฟู HP ของพันธมิตรเมื่อ Active Skill สังหารศัตรู",
  str_item_intro_5259407 = "เพิ่มความเสียหายทั้งหมดของพรรคพวกเมื่อ HP สูงสุด",
  str_item_intro_5259408 = "ฟื้นฟู HP ของพันธมิตรเมื่อศัตรูได้รับพิษจากพิษ\nลดโอกาสที่พันธมิตรจะติดพิษ",
  str_item_intro_5259409 = "สะท้อนความเสียหายกลับไปที่ศัตรูเมื่อพวกเขาสร้างความเสียหายให้กับพันธมิตร",
  str_item_intro_5259410 = "เพิ่มความเสียหายของพันธมิตรเมื่อมี Aurorians อย่างน้อย 3 คนที่มีองค์ประกอบหลักต่างกันในทีม",
  str_item_intro_5259411 = "องค์ประกอบรองของ Aurorians สร้างความเสียหายโดยไม่มีการลดความเสียหาย",
  str_item_intro_5259412 = "โอกาสเปลี่ยนกัปตัน +5\nลดคูลดาวน์ Active Skill ของ Aurorians ที่กลายเป็นกัปตันเป็นครั้งแรกในรอบนี้ 1",
  str_item_intro_5259501 = "กัปตันปลดปล่อย Chain Combo เพิ่มเติมที่จุดเริ่มต้นของบรรทัด",
  str_item_intro_5259502 = "สร้างเอฟเฟกต์การระเบิดทุกๆ 5 การโจมตีปกติ",
  str_item_intro_5259503 = "สร้างกระเบื้องสีจำนวนเล็กน้อยภายใน 1 คลัสเตอร์รอบ ๆ ทุก ๆ รอบ",
  str_item_intro_5259504 = "สังหารศัตรูที่มี HP ต่ำกว่า 10% ทันที",
