  str_item_intro_5259506 = "แปลง DEF ของ Aurorian ที่เป็นพันธมิตรทั้งหมดเป็น ATK",
  str_item_intro_5259507 = "ไทล์แรกในบรรทัดอาจเป็นสีที่แตกต่างจากไทล์ถัดไป องค์ประกอบที่แตกต่างกันทั้งสองนี้จะกระตุ้นให้ชาว Aurorian ดำเนินการ",
