  str_item_intro_5259514 = "โอกาสเปลี่ยนกัปตัน +5\nออโรเรียนที่เป็นกัปตันในรอบนี้จะโจมตีด้วยองค์ประกอบหลักโดยไม่คำนึงถึงสีของการเชื่อมต่อ",
  str_item_rpintro_5259301 = "เพิ่มความเสียหายของ Chain Combo 30% เมื่อพันธมิตรเชื่อมต่อ 15 แผ่นหรือมากกว่า",
  str_item_rpintro_5259302 = "เมื่อสร้างความเสียหาย พันธมิตรจะเพิกเฉยต่อผลการลดความเสียหายจากการสวนกลับขององค์ประกอบ เมื่อได้รับความเสียหาย พันธมิตรจะเพิกเฉยต่อโบนัสของการสวนกลับธาตุของตน",
  str_item_rpintro_5259303 = "เมื่อทำให้ศัตรูติดพิษ/เผาไหม้/เลือดออก เป้าหมายจะสูญเสีย HP ทันที 50% ของการโจมตี สามารถเรียกใช้ได้หนึ่งครั้งต่อรอบในแต่ละเป้าหมาย",
  str_item_rpintro_5259304 = "เพิ่ม Max HP ของ Aurorians ในทีม 100% โดยไม่เปลี่ยน HP ปัจจุบัน",
  str_item_rpintro_5259305 = "เมื่อ HP ของพันธมิตรลดลงต่ำกว่า 50% ผ้าพันแผลซึ่งฟื้น 20% ของ HP สูงสุดเมื่อพันธมิตรผ่านมัน จะถูกสร้างขึ้นในตำแหน่งสุ่มบนสนาม",
  str_item_rpintro_5259306 = "ฟื้นฟู HP สูงสุด 20% เมื่อเริ่มแต่ละเวฟ",
  str_item_rpintro_5259307 = "ให้โล่เท่ากับ 40% ของ HP สูงสุดที่คงอยู่เป็นเวลา 1 รอบเมื่อเริ่มทุกเวฟ",
  str_item_rpintro_5259308 = "สร้างความเสียหายเท่ากับ 50% ของ Max HP แก่ศัตรูที่ไม่ใช่บอสทั้งหมดภายใน 1 กลุ่มรอบ ๆ เมื่อเริ่มทุกระลอก",
  str_item_rpintro_5259309 = "ลดคูลดาวน์ของ Special Caelesite Gear ลง 1 ในการต่อสู้ครั้งต่อๆ ไป",
  str_item_rpintro_5259310 = "พันธมิตรและศัตรูทั้งหมด (รวมถึงบอส) สูญเสีย 7% ของ HP ปัจจุบันเมื่อเริ่มรอบ",
  str_item_rpintro_5259311 = "มอบอุปกรณ์ Caelestite พิเศษแบบสุ่มที่คุณยังไม่มี สามารถใช้ในการต่อสู้ครั้งต่อๆ ไป และจะคำนวณคูลดาวน์แยกต่างหาก",
  str_item_rpintro_5259401 = "ความเสียหายทั้งหมดที่ได้รับจากศัตรูที่ถูกดีบัฟหรือมีเอฟเฟกต์ดีบัฟเพิ่มขึ้น 20%",
  str_item_rpintro_5259402 = "แปลงการรักษาส่วนเกินของ Aurorians 100% ให้เป็นเกราะป้องกันที่คงอยู่เป็นเวลา 1 รอบ",
  str_item_rpintro_5259403 = "สร้างพิษ 1 แต้มแก่พันธมิตรและศัตรูทั้งหมดในสนามเมื่อใดก็ตามที่ศัตรูตาย พันธมิตรได้รับความเสียหายพิษ -50%",
  str_item_rpintro_5259404 = "เพิ่มความเสียหายของ Chain Combo 30% เมื่อทีมของคุณได้รับผลกระทบจากดีบัฟ",
  str_item_rpintro_5259405 = "ศัตรูที่ไม่ใช่บอสมีโอกาส 3% ที่จะตายทันทีเมื่อได้รับความเสียหายใดๆ",
  str_item_rpintro_5259406 = "พันธมิตรฟื้น HP เท่ากับ 15% ของ Max HP ของผู้ร่าย เมื่อใดก็ตามที่ศัตรูถูกฆ่าโดย Active Skill",
  str_item_rpintro_5259407 = "เพิ่มความเสียหายทั้งหมด 20% เมื่อทีมของคุณมี HP สูงสุด",
  str_item_rpintro_5259408 = "เมื่อใดก็ตามที่ศัตรูได้รับความเสียหายจากพิษ พันธมิตรจะฟื้นฟู HP เท่ากับ 100% ของความเสียหายจากพิษนี้ พันธมิตรได้รับความเสียหายพิษ -50%",
  str_item_rpintro_5259409 = "สะท้อน 100% ของความเสียหายที่ได้รับกลับไปเมื่อศัตรูสร้างความเสียหายให้กับพันธมิตร",
  str_item_rpintro_5259410 = "เพิ่มความเสียหายทั้งหมดที่ทำได้โดยพันธมิตร 25% เมื่อมี Aurorians อย่างน้อย 3 คนที่มีองค์ประกอบหลักต่างกันในทีมของคุณ",
  str_item_rpintro_5259411 = "ธาตุรองของ Aurorians จะสร้างความเสียหายด้วยตัวคูณเดียวกันกับธาตุหลัก",
  str_item_rpintro_5259412 = "กัปตันเปลี่ยนโอกาส +5 เมื่อได้รับไอเทมนี้\nเมื่อเปลี่ยนกัปตัน คูลดาวน์สกิลเรียกใช้ของกัปตันคนใหม่จะลดลง 1 Aurorian แต่ละคนสามารถเรียกใช้เอฟเฟกต์นี้ได้เพียงครั้งเดียวในทุกรอบ",
  str_item_rpintro_5259501 = "สร้างภาพของกัปตัน Aurorian ที่จุดเริ่มต้น ภาพนี้ปล่อยเชนคอมโบในรอบนี้ด้วย",
  str_item_rpintro_5259502 = "สร้างการระเบิดที่โจมตีศัตรูเมื่อคอมโบการโจมตีปกติคูณด้วย 5",
  str_item_rpintro_5259503 = "แปลงกระเบื้อง 3 แผ่นภายใน 1 คลัสเตอร์โดยรอบเป็นกระเบื้องสีเมื่อเริ่มรอบ",
  str_item_rpintro_5259504 = "ศัตรูที่มี HP เหลือน้อยกว่า 10% จะพ่ายแพ้ทันที",
  str_item_rpintro_5259505 = "ลดคูลดาวน์ของสกิลเรียกใช้ของ Aurorian ทั้งหมดที่มีคูลดาวน์ 1 หากไม่มีการเชื่อมต่อในรอบนี้",
  str_item_rpintro_5259506 = "ลด DEF ของ Aurorians ทั้งหมดในทีมของคุณเป็น 0 และเพิ่ม ATK ของคุณตามจำนวน DEF ทั้งหมดที่ลดลง",
  str_item_rpintro_5259507 = "ไทล์แรกในบรรทัดอาจเป็นสีที่แตกต่างจากไทล์ถัดไป องค์ประกอบที่แตกต่างกันทั้งสองนี้จะกระตุ้นให้ชาว Aurorian ดำเนินการ",
  str_item_rpintro_5259508 = "เมื่อเชื่อมต่อสีอื่น ๆ ก็สามารถเชื่อมต่อกระเบื้องสีเขียวได้เช่นกัน",
  str_item_rpintro_5259509 = "เมื่อเชื่อมต่อสีอื่น ๆ ก็สามารถเชื่อมต่อกระเบื้องสีน้ำเงินได้เช่นกัน",
  str_item_rpintro_5259510 = "เมื่อเชื่อมต่อสีอื่น ๆ ก็สามารถเชื่อมต่อกระเบื้องสีแดงได้เช่นกัน",
  str_item_rpintro_5259511 = "เมื่อเชื่อมต่อสีอื่น ๆ ก็สามารถเชื่อมต่อกระเบื้องสีเหลืองได้เช่นกัน",
  str_item_rpintro_5259512 = "เพิ่มความเสียหายทั้งหมดที่ทำได้โดยพันธมิตร 25% แต่จุดเริ่มต้นของการเชื่อมต่อแต่ละครั้งจะกลายเป็นกระเบื้องแตกที่ไม่สามารถเคลื่อนที่ต่อไปได้เป็นเวลา 5 รอบ",
  str_item_rpintro_5259513 = "เพิ่มความเสียหายต่อเนื่องต่อเนื่องสูงสุด 80% ตามเปอร์เซ็นต์ของ HP ที่เสียไปโดยพันธมิตร",
  str_item_rpintro_5259514 = "โอกาสเปลี่ยนกัปตัน +5\nออโรเรียนที่เป็นกัปตันในรอบนี้จะโจมตีด้วยองค์ประกอบหลักโดยไม่คำนึงถึงสีของการเชื่อมต่อ",
