  str_item_intro_9994028 = "องค์ประกอบรองของ Aurorians สร้างความเสียหายโดยไม่มีการลดความเสียหาย",
  str_item_intro_9994029 = "โอกาสเปลี่ยนกัปตัน +3\nลดคูลดาวน์ Active Skill ของ Aurorians ที่กลายเป็นกัปตันเป็นครั้งแรกในรอบนี้ 1",
  str_item_intro_9995019 = "ลดคูลดาวน์ของ Active Skill ลง 1 ด้วยการแตะ 2 ครั้งขณะยืนนิ่ง",
  str_item_intro_9995020 = "ลด DEF ของ Aurorians ทั้งหมดในทีมของคุณเหลือ 50% และเพิ่ม ATK ตามจำนวน DEF ที่ลดลง",
  str_item_intro_9995021 = "เพิ่มความเสียหายต่อเนื่องต่อเนื่องสูงสุด 80% ตามเปอร์เซ็นต์ของ HP ที่เสียไปโดยพันธมิตร",
  str_item_intro_9995022 = "โอกาสเปลี่ยนกัปตัน +3\nออโรเรียนที่เป็นกัปตันในรอบนี้จะโจมตีด้วยองค์ประกอบหลักโดยไม่คำนึงถึงสีของการเชื่อมต่อ",
  str_item_rpintro_9994027 = "อาวุธที่ดูเหมือนจะหลอมรวมกับลูมิน่าได้อย่างสมบูรณ์แบบ... หายากจริงๆ...",
  str_item_rpintro_9994028 = "ว่ากันว่านักรบโบราณผู้หนึ่งพ่ายแพ้ในสนามรบเพราะเขาไม่สามารถออกแรงเต็มที่จากมือข้างที่ไม่ถนัด หลังจากความพ่ายแพ้ เขามีถุงมือที่ทำขึ้นเป็นพิเศษ แน่นอน เขาอยู่ยงคงกระพันในการต่อสู้ที่กำลังจะมาถึง",
  str_item_rpintro_9994029 = "มือเชื่อมต่อกับหัวใจของคุณ ดังนั้นจึงอาจกล่าวได้ว่าคนสองคนที่จับมือกันมีสายสัมพันธ์ทางจิตวิญญาณต่อกันและจะไม่มีวันแยกจากกัน",
  str_item_rpintro_9995019 = "พลังอันน่าทึ่งในวัตถุโบราณชิ้นนี้ช่วยให้ผู้สวมใส่ร่าย Luminatics อันทรงพลังทุกประเภทได้เร็วขึ้น ทำให้ผู้สวมใส่สามารถรับมือกับสถานการณ์อันตรายต่างๆ ได้",
  str_item_rpintro_9995020 = "ดังสุภาษิตโบราณที่ว่า \"ผู้ที่มีชีวิตอยู่ด้วยดาบก็ตายด้วยดาบ\" แม้ว่าสิ่งนี้จะทำให้สามารถเอาชนะศัตรูที่ทรงพลังมากได้ แต่ข้อสันนิษฐานก็คือคุณต้องต่อสู้อย่างกล้าหาญโดยไม่คำนึงถึงความปลอดภัยของคุณเอง...",
  str_item_rpintro_9995021 = "ตามเรื่องเล่าปากต่อปาก ชุดเกราะนี้มีพลังอันยิ่งใหญ่และน่าสะพรึงกลัว ทำให้เป็นสมบัติของบางคนและเป็นคำสาปสำหรับคนอื่น",
  str_item_rpintro_9995022 = "บางคนบอกว่ารูปปั้นนี้ไม่ได้แสดงถึงเทพเจ้า แต่เป็นนักรบหญิงในตำนานที่สามารถให้การสนับสนุนในการต่อสู้",
  str_item_3661187 = "เงื่อนพรหลงโจว",
  str_item_intro_3661187 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเชือกที่ทอเป็นเงื่อนสี่เหลี่ยมอย่างชำนาญเป็นเครื่องยืนยันถึงความคิดสร้างสรรค์ของช่างทอ สันนิษฐานว่ามาจากหลงโจว ที่ผู้คนแขวนไว้ในบ้านเพื่อปกป้องครอบครัวจากอันตราย",
  str_item_3661188 = "โคมไฟแขวนสูง",
  str_item_intro_3661188 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nชั้นวางโคมไฟจากหลงโจวที่มีโครงสร้างไม้อันเป็นเอกลักษณ์ ซึ่งมีโคมไฟสีแดงแขวนอยู่ ดูเหมือนว่าจะมีอำนาจที่จะนำผู้คนไปสู่อีกโลกหนึ่งในทันที",
  str_item_3661028 = "เครื่องประดับดวงดาว",
  str_item_intro_3661028 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nดวงดาวและองค์ประกอบทางกาแล็กซี่ร้อยเข้าด้วยกันเป็นเชือก เราสามารถชื่นชมเหลือบของจักรวาลเมื่อมันสว่างขึ้น สามารถวางไว้บนผนังหรือแขวนไว้บนต้นไม้กลางแจ้งเพื่อสร้างภาพลวงตาของท้องฟ้าที่เต็มไปด้วยดวงดาวในวันที่มีเมฆมาก",
