  str_item_intro_3661190 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nกลัวที่จะเปิดเผยความลับในใจของคุณ? ความลับอยู่ในจิตวิญญาณของคุณหรือไม่? ถ้าเป็นเช่นนั้น กล่องจดหมายนี้เหมาะสำหรับคุณ มีความอดทน ปลอดภัย และไว้ใจได้ ทำให้เป็นคนสนิทที่ยอดเยี่ยม",
  str_item_3661191 = "ตุ๊กตาพระจันทร์",
  str_item_intro_3661191 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nใครจะปฏิเสธหมีที่น่ารักเช่นนี้ได้ โดยเฉพาะคนที่มีหัวใจรัก! ถ้ามีคนให้ของขวัญชิ้นนี้แก่คุณ เห็นได้ชัดว่าพวกเขารู้สึกอย่างไรกับคุณ",
  str_item_3661192 = "ช่อมงกุฏ",
  str_item_intro_3661192 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nดอกไม้สีแดงและสีขาวเป็นสัญลักษณ์ของความรักที่เร่าร้อนและหัวใจที่บริสุทธิ์ เมื่อคุณมอบช่อดอกไม้นี้ให้กับคนที่คุณรัก ก็ถึงเวลาที่ต้องพูดสามคำนี้",
  str_item_3661029 = "ฮาร์ทเลิฟซีท",
  str_item_intro_3661029 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nที่นั่งพักผ่อนที่กว้างขวางและสะดวกสบายเหมาะสำหรับคู่รักที่จะมาพักผ่อนด้วยกัน ถ้าไม่มีใครนั่งด้วยก็ไม่เป็นไร ความรู้สึกเหมือนถูกห่อหุ้มด้วยเบาะนุ่มๆ ขนาดใหญ่ สามารถทำให้คุณรู้สึกเหมือนไม่ได้อยู่คนเดียว...",
  str_item_3661193 = "ปีกสีขาวบริสุทธิ์",
  str_item_intro_3661193 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nดังที่ว่ากันว่าเทวดาเป็นผู้พิทักษ์ความรัก บางคนแขวนปีกสีขาวเหล่านี้ไว้บนกำแพงด้วยความหวังว่าพวกเขาจะได้พบรักแท้ในเร็ววัน",
  str_item_3661194 = "สวอนเค้กทาวเวอร์",
  str_item_intro_3661194 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเค้กที่ตกแต่งด้วยหงส์สุดวิจิตร มันดูเหมือนงานศิลปะมากกว่าอาหาร... คุณแน่ใจหรือที่จะกินมัน?",
  str_item_3661030 = "ดาวลอย",
  str_item_intro_3661030 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nดูเหมือนว่าจะเหมาะกว่าเป็นบอลลูนที่ปรากฏในสวนสนุกแทนที่จะเป็นของประดับที่บ้าน แต่ก็ดูค่อนข้างพิเศษเมื่ออยู่ที่บ้านเช่นกัน อย่างไรก็ตาม มันอาจจะบินไปทุกที่หากคุณไม่ผูกมันไว้กับบางสิ่ง",
  str_item_3000308 = "บันทึกคดี",
  str_item_intro_3000308 = "ฉันได้บันทึกลักษณะบางอย่างของผู้ร้าย มาดูกันว่าพวกเขาจะช่วยให้เราเปิดเผยความจริงได้หรือไม่...",
  str_item_3661195 = "แผ่นเสียงคลาสสิก",
  str_item_intro_3661195 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเครื่องเล่นแผ่นเสียงคลาสสิกที่กล่าวกันว่าได้รับความนิยมใน Umbraton เมื่อหลายสิบปีก่อน เป็นเครื่องเล่นทั่วไปในบ้านของนักธุรกิจผู้มั่งคั่งหลายคน ดูเหมือนว่าจะถูกสร้างขึ้นโดยช่างฝีมือในยุคนั้นหรือผู้ที่พยายามอย่างมากในการค้นคว้าและออกแบบเสียงต่ำและการตกแต่ง ซึ่งทำให้สมาชิกรุ่นเก่าดื่มด่ำกับดนตรีและจิตวิญญาณแห่งอดีต",
  str_item_3661196 = "กระดานเบาะแส",
  str_item_intro_3661196 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nกระดานนี้ไม่เพียงแต่สามารถใช้วาดแผนที่ความคิดต่างๆ เพื่อวิเคราะห์คดีจากทุกมุมเท่านั้น แต่ยังเป็นสถานที่ที่สมบูรณ์แบบในการแปะเบาะแสสำคัญและภาพถ่ายของพยาน นอกจากนี้ยังแสดงข้อมูลที่รวบรวมจากแหล่งต่างๆ ได้สะดวก ช่วยให้เข้าถึงง่าย อนุมาน และสรุปผล และช่วยให้คุณค้นพบความจริงและผู้กระทำผิดได้อย่างรวดเร็ว",
  str_item_3661197 = "โต๊ะกาแฟของนักสืบ",
  str_item_intro_3661197 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเดิมใช้สำหรับดื่มชายามบ่ายและเล่นไพ่ ปัจจุบันโต๊ะกาแฟนี้เต็มไปด้วยหนังสือและเอกสารที่เกี่ยวข้องกับคดีอาญา พร้อมด้วยแว่นขยาย ท่อ และตะเกียงที่วางอยู่ข้างๆ ดูเหมือนว่าเจ้าของจะต้องเป็นนักสืบหรืออย่างน้อยก็เป็นนักสืบที่ชื่นชอบ",
  str_item_3661198 = "ราวแขวนเสื้อของนักสืบ",
  str_item_intro_3661198 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเมื่อออกไปทำการสอบสวน สิ่งสำคัญคือต้องดูส่วนนั้น เสื้อโอเวอร์โค้ตสามารถทนต่ออากาศที่หนาวเย็นในตอนกลางคืนและสามารถบรรจุสิ่งของต่างๆ ที่ใช้ในการดมกลิ่นเพื่อหาเบาะแส เช่น สมุดโน้ต แว่นขยาย และอาวุธขนาดเล็กสำหรับป้องกันตัว และแน่นอนว่าหมวกไม่ได้มีดีแค่ป้องกันลมเท่านั้น แต่ยังทำให้ผู้สวมใส่ดูเหมือนนักสืบอีกด้วย",
  str_item_3661031 = "โซฟาเหตุผลนิรนัย",
  str_item_intro_3661031 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nพวกเขากล่าวว่านักสืบบางคนสามารถสรุปความจริงของคดีได้โดยการนั่งบนโซฟาและวาดเบาะแสต่างๆ ที่รวบรวมโดยผู้อื่น ดูเหมือนว่าโซฟานี้ไม่เพียงแต่ให้ความผ่อนคลายเท่านั้นแต่ยังช่วยเพิ่มพลังให้กับจิตใจอีกด้วย",
  str_item_3661199 = "ที่วางท่อ",
  str_item_intro_3661199 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nชั้นวางของที่เต็มไปด้วยท่อ แม้ว่าคุณจะไม่ชอบกลิ่นยาสูบ แต่ไปป์ที่มีรูปทรงเป็นเอกลักษณ์เหล่านี้ก็คุ้มค่าแก่การสะสม",
  str_item_3661200 = "กล้องส่องทางไกลแบบตั้งพื้น",
  str_item_intro_3661200 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nคุณสมบัติที่ยอดเยี่ยมที่สุดของกล้องส่องทางไกลเหล่านี้คือความสามารถในการให้คุณเห็นทุกสิ่งในสภาพแวดล้อมที่ห่างไกล เลนส์มีความใสมาก แต่กระบอกเลนส์โลหะทำให้มีน้ำหนักมากจนต้องวางบนขาตั้งกล้องแบบพิเศษเพื่อให้มั่นคง",
  str_item_3661032 = "ปลอดภัย",
  str_item_intro_3661032 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\n“นี่คือคุกที่ปลอดภัยที่สุดและแข็งแกร่งที่สุดสำหรับสินค้าของคุณในทวีปนี้” พ่อค้ากล่าว แน่นอนว่ามือจับล็อคขนาดใหญ่นั้นดูแข็งแรง และเคสที่หนักก็ดูไม่เสียหายแม้แต่น้อย",
  str_item_3661033 = "เป็ดแชมป์",
  str_item_intro_3661033 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเป็ด Gronru ที่ออกแบบนี้เป็นรางวัลสำหรับผู้ชนะในเกมของเธอ! น่ารักอย่างไม่น่าเชื่อ รูปลักษณ์สีทองของมันเป็นสัญลักษณ์ของเกียรติยศของแชมป์เปี้ยน",
  str_item_3661207 = "พรมสั่ง",
  str_item_intro_3661207 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเหนือเมฆบนท้องฟ้าคือเมืองลอย ในฐานะที่เป็นแสงสว่างแห่งอารยธรรมของ Astra พรมนี้เป็นสัญลักษณ์ของตัวตนและสถานะและยังแสดงถึงระเบียบและพิธีกรรมอีกด้วย",
  str_item_3661208 = "Unfalling แบนเนอร์",
  str_item_intro_3661208 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nสัญลักษณ์ของ \"เมืองที่ไม่ล่มสลายชั่วนิรันดร์\" การปรากฏตัวของมันในทวีปหมายความว่าแสงแห่งอารยธรรมของ Lumopolis ส่องสว่างที่นี่",
  str_item_3661201 = "พิณส่วย",
  str_item_intro_3661201 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nพิณนี้ใช้ในงานเฉลิมฉลองที่ยิ่งใหญ่ในเมืองลูโมโปลิสโดยเฉพาะ รักษาไว้ด้วยรูปแบบเฉพาะของ Luminatics โทนเสียงของมันยังคงปรับแต่งได้อย่างไร้ที่ติ เฉพาะนักดนตรีที่มีทักษะมากที่สุดเท่านั้นที่สามารถเล่นท่วงทำนองอันไพเราะด้วยเครื่องดนตรีนี้ ซึ่งเหมาะสำหรับเพลงสรรเสริญ",
  str_item_3661202 = "นาฬิกาทรายริบหรี่",
  str_item_intro_3661202 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\n\"ท่ามกลางการไหลขึ้นลงของแสงสว่างและความมืด มีเพียงสิ่งประดิษฐ์นี้เท่านั้นที่สามารถวัดเวลาได้อย่างแม่นยำ\" ลือกันว่ามีเม็ดทรายที่งดงามที่สุดที่พบในทวีปนี้ และผ่านการสอบเทียบของ Luminatics ที่ไม่เหมือนใคร ความแม่นยำของนาฬิกาทรายนี้เทียบได้กับนาฬิกาที่ดีที่สุด",
  str_item_3661203 = "น้ำพุเหนือเมฆ",
  str_item_intro_3661203 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nในลานสูงเหนือเมฆ คุณสามารถรับรู้ถึงเสียงน้ำไหลที่นุ่มนวลได้หรือไม่? ไม่ต้องแปลกใจเพราะมันมาจาก Fountain Terrace ของ Lumopolis ได้รับพรจาก Luminatics ที่น่าหลงใหล น้ำดูเหมือนจะปรากฏขึ้นจากความว่างเปล่าโดยลงมาจากระดับหนึ่งไปอีกระดับหนึ่งอย่างสง่างาม แม้แต่จากสวรรค์เบื้องบน ผู้คนก็สามารถเพลิดเพลินกับภาพที่น่าหลงใหลของน้ำตกบนท้องฟ้าแห่งนี้",
  str_item_3661204 = "ดาบและโล่สุดท้าย",
  str_item_intro_3661204 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nในฐานะเมืองที่ไม่ยอมใคร ลูโมโพลิสตั้งตระหง่านเป็นปราการแห่งอารยธรรมขั้นสูงสุด ดาบและโล่นี้เป็นเสาหลักสุดท้ายของการป้องกันนี้... ดาบและโล่นี้เป็นสัญลักษณ์ของหน้าที่ ความกล้าหาญ และความมุ่งมั่นที่ไม่เปลี่ยนแปลงที่จะต่อสู้จนถึงที่สุด",
  str_item_3661034 = "ลูกแก้วแห่งวันเก่า",
  str_item_intro_3661034 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nการชำเลืองเข้าไปในคริสตัลอย่างรวดเร็วเผยให้เห็นเพียงภาพสะท้อนของคุณเอง แต่การตรวจสอบอย่างใกล้ชิดจะคลี่คลายฉากต่างๆ จากอดีต แก่นแท้ของความทรงจำอันน่าจดจำยังคงอยู่ต่อหน้าต่อตาคุณ เชื้อเชิญให้คุณดำดิ่งสู่ห้วงแห่งความทรงจำ...",
  str_item_3000325 = "หยดน้ำตาคริสตัล",
  str_item_intro_3000325 = "ว่ากันว่านี่คือน้ำตาของโลกนี้...สามารถรับได้ในวันนั้นเท่านั้นและบรรจุความจริงของโลกนี้ไว้\nใช้: สามารถนำไปแลกเปลี่ยนเป็นของใช้ใน Hall of Remembrance\nที่มา: ทำเนื้อเรื่องหลักหรือด่าน Raid ทรัพยากรให้สำเร็จซึ่งต้องใช้ปริซึม",
  str_item_3661205 = "เชิงเทียนสองแขน",
  str_item_intro_3661205 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\n\"แสงควรถูกเปล่งออกมาในความมืดเพื่อช่วยให้ผู้คนพบทางของพวกเขา\" เชิงเทียนนี้ใช้ Luminatics พิเศษของ Lumopolis สามารถติดตั้งกับผนังโดยอัตโนมัติโดยไม่ต้องใช้ตะขอ และเทียนจะไม่ดับง่ายเมื่อถูกลมพัด",
  str_item_3661206 = "แจกันหรูหรา",
  str_item_intro_3661206 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nแจกันขนาดใหญ่แต่ละใบมีราคาแพงพอที่คนธรรมดาจะใช้ชีวิตอย่างหรูหราเป็นเวลาสองสามปี ซึ่งใช้โดยขุนนางลูโม เป็นที่รู้จักจากรูปทรงที่สง่างาม อย่างไรก็ตาม พวกมันเป็นเพียงของตกแต่งที่มีค่าเล็กน้อยสำหรับคฤหาสน์อันโอ่อ่าของพวกเขา",
  str_item_3661035 = "ชุดทางการสง่างาม",
  str_item_intro_3661035 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเครื่องแต่งกายนี้สง่างามและเคร่งขรึมเพียงพอสำหรับพิธีการ เทศกาล หรืองานเต้นรำที่ยิ่งใหญ่ที่สุดใน Lumopolis ซึ่งมารยาทถือเป็นเกียรติสูงสุด เมื่อสวมใส่โดยคนที่ดูดีและมีรสนิยม ผู้สวมใส่จะต้องดึงดูดสายตาของทุกคนและกลายเป็นดาวเด่นของฝูงชน",
  str_item_3661209 = "รีสอร์ท ห้องพักผ่อนกันแดด",
  str_item_intro_3661209 = "เฟอร์นิเจอร์ไอเทม สามารถวางในห้องของคุณในโคลอสซัส\nไม่มีหรอกที่ปลายทางในวันหยุดที่สมบูรณ์แบบโดยไม่มีมัน ทั้งให้ความผ่อนคลายและป้องกันแสงแดด หากขาดแม้ชิ้นเดียวของสองชิ้น จิตวิญญาณในวันหยุดก็จะเสื่อมค่า",
  str_item_3661210 = "โฆษณาผนังสวนสนุก",
  str_item_intro_3661210 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องของคุณในโคลอสซัส\nดูเหมือนจะเป็นสิ่งที่ต้องมีในทุกสวนสนุก - ใหญ่โต น่าสนใจ ตกแต่งด้วยลายที่น่าสนใจและดึงดูดใจ ที่เสียงเรียกเสมือนว่า \"มาดูสิ! อย่าพลาด!\"",
  str_item_3661211 = "รถไอศกรีมรีสอร์ท",
  str_item_intro_3661211 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรถเข็นเหล่านี้นำเสนอของหวานเย็นๆในวันที่ร้อนแสบของฤดูร้อน พวกเขาทำหน้าที่เป็นสถานีเติมพลังขนาดเล็กที่กระจายอยู่ทั่วสวนสนุก มักดึงดูดเด็ก ๆ ที่อยู่รอบ ๆ และต้องการเพิ่มเติม",
  str_item_3661212 = "รีสอร์ทหางม้าในฤดูใบไม้ผลิ",
  str_item_intro_3661212 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nความสนุกที่เด็ก ๆ ชื่นชอบ ด้วยสปริงที่อยู่ด้านล่างทำให้ผู้ขี่กระโดดขึ้นลงอย่างอ่อนโยน มันทำให้เสียงกรีดร้องของเด็ก ๆ ตื่นเต้นไม่มีที่สิ้นสุด",
  str_item_3661213 = "เจ็ตสกีโอเอซิส",
  str_item_intro_3661213 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nการแข่งขันเจ็ตสกี้บนน้ำกลางทะเลทรายเป็นไปได้! ใครจะเชื่อ! มันเป็นไปได้ด้วยน้ำที่มากมายจากโอเอซิสที่กว้างใหญ่ ทำให้เจ็ตสกี้หาที่ใช้สอย และหลีกเลี่ยงจากการกลายเป็นสิ่งของของอดีต",
  str_item_3661214 = "ต้นกระบองเพชรทะเลทราย",
  str_item_intro_3661214 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nต้นไม้ที่พบมากที่สุดในทะเลทราย ปรับตัวให้เข้ากับสภาพแห้งแล้งได้อย่างน่าทึ่ง ถือเป็นสัญลักษณ์ของความยืนยง ทำให้คนนำมาปลูกในกระถางเพื่อตกแต่งบ้าน แต่อย่าลืมอย่ารดน้ำมากเกินไป เดี๋ยวมันจะเสียชีวิตจากการจมน้ำนะ!",
  str_item_level_2905111 = "สนามพลังงาน",
  str_item_10000100 = "กล่องเลือกออโรเรียนธาตุน้ำ",
  str_item_10000101 = "กล่องเลือกออโรเรียนไฟ",
  str_item_10000102 = "กล่องเลือกออโรเรียนแห่งป่า",
  str_item_10000103 = "กล่องเลือกธันเดอร์ออโรเรียน",
  str_item_intro_10000100 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ (<color=#ffffff>โนอาห์, ไฮแดรด, บาร์ตัน, เคลเคน, ฟิลิชี, โคแร็กซ์</color>)",
  str_item_intro_10000101 = "หลังจากใช้ สามารถเลือกออโรเรียน 5 ดาว 1 รายจากตัวเลือกต่อไปนี้ ไปร่วมผจญภัยกับคุณ (<color=#ffffff>เฟาสต์, เรจินา, เบนนี่กับคุโระ, ลีโอนา, อีสต์วาน, แม็กกี้, บาร์บาร่า</color>)",
