  str_item_3000327 = "เหรียญเครื่องคีบตุ๊กตา",
  str_item_intro_3000327 = "เหล่าโทเค็นเหล่านี้ถูกใช้ในเครื่อง Claw Machines และสถานที่เล่นเกมอื่น ๆ ทุกหนึ่งในนั้นมีรอยยิ้มแห่งความสุขของ Lorelei พร้อมกับความปรารถนาดีให้แขกทุกคนได้สนุกสนานในประสบการณ์ที่น่าพอใจ",
  str_item_3000328 = "เหรียญ Denuo Pass",
  str_item_intro_3000328 = "เหรียญที่ใช้ใน Denuo Valley Resort ด้วยความชำนาญในการทำงานและคุณภาพที่ยอดเยี่ยม สามารถแลกเปลี่ยนกับสกุลเงินของสังกัดอื่น ๆ ได้\nใช้เหรียญเหล่านี้อย่างเฉียบขาดในโหมดการจัดการเพื่ออัปเกรดอาคาร",
