  str_item_intro_3410644 = "มี: กล่องออเดอร์สีแดง IV ×15, กล่องออเดอร์สีแดง III ×25, แจสเปอร์แดง III ×25, แจสเปอร์แดง II ×10, แจสเปอร์แดง I ×6, ไนท์เทียม ×331,000, กล่องออเดอร์ร่วมมือ III ×8",
  str_item_intro_3410645 = "ประกอบด้วย: กล่องออเดอร์สีเหลือง II ×15, กล่องออเดอร์สีเหลือง I ×25, แจสเปอร์เหลือง II ×5, แจสเปอร์เหลือง I ×8, ไนท์เทียม ×35,000, กล่องออเดอร์ร่วมมือ I ×8",
  str_item_intro_3410646 = "ประกอบด้วย: กล่องออเดอร์สีเหลือง III ×15, กล่องออเดอร์สีเหลือง II ×25, แจสเปอร์เหลือง II ×30, แจสเปอร์เหลือง I ×7, ไนท์เทียม ×121,000, กล่องออเดอร์ร่วมมือ II ×8",
  str_item_intro_3410647 = "ประกอบด้วย: กล่องออเดอร์สีเหลือง IV ×15, กล่องออเดอร์สีเหลือง III ×25, แจสเปอร์เหลือง III ×25, แจสเปอร์เหลือง II ×10, แจสเปอร์เหลือง I ×6, ไนท์เทียม ×331,000, กล่องออเดอร์ร่วมมือ III ×8",
  str_item_intro_3000900 = "ฝ้ายเนื้อนุ่มที่มักใช้ทำไส้หรือประดิษฐ์เป็นเครื่องประดับ",
  str_item_intro_3000901 = "วัสดุเสื้อผ้าทั่วไปที่พบใน Astra ซึ่งเป็นที่รู้จักในด้านความแข็งแรง ความทนทาน และการย้อมสีได้ง่าย",
  str_item_intro_3000902 = "ย้อม. ซินซาแสดงให้คุณเห็นเพียงกระบอกเดียว แต่เขาบอกว่าจริง ๆ แล้วยังมีอีกหลายกระบอกในสีต่าง ๆ",
  str_item_intro_3000903 = "ปุ่มที่ใช้ในการตัดเย็บบ่อยครั้ง มันรู้สึกเย็นตามสัมผัสและมักถูกเด็ก ๆ คิดว่าเป็นเหรียญ",
  str_item_intro_3000904 = "ดูเหมือนลูกบอลเส้นด้ายธรรมดา ซินซาแสดงให้คุณเห็นเพียงสีดำ เกรงว่าคุณอาจทำสีผิดเพี้ยนไปหากคุณเล่นกับมัน",
  str_item_7000100 = "Sketchbook ขาดรุ่งริ่ง",
  str_item_7000101 = "ชิ้นส่วน Sketchbook: ด็อกเตอร์",
