  str_item_7000114 = "ชิ้นส่วน Sketchbook: ดอกไม้รุ่งอรุณ",
  str_item_7000115 = "ชิ้นส่วน Sketchbook: ประแจ",
  str_item_7000116 = "ชิ้นส่วน Sketchbook: Rediesel Boss",
  str_item_7000117 = "ชิ้นส่วน Sketchbook: ยักษ์ใหญ่",
  str_item_7000118 = "แตกหักสมุดสเก็ตช์: องค์ชายบัวบก",
  str_item_7000119 = "สมุดร่างที่สมบูรณ์",
  str_item_intro_7000100 = "สมุดสเก็ตช์ภาพพร้อมภาพวาดง่ายๆ มีหน้าเปิดที่แสดงภาพเด็กสาวนั่งอย่างสนุกสนานโดยมีบุคคลสามคนอยู่รอบๆ ตัวเธอ น่าแปลกที่หัวของคนเหล่านี้ในภาพวาดถูกฉีกออกหมด",
  str_item_intro_7000101 = "ดูเหมือนว่ากระดาษแผ่นนี้ถูกฉีกออกจากสมุดภาพ ภาพศีรษะของผู้หญิงลึกลับสวมเสื้อคลุมสีขาวคลุมเครือ",
  str_item_intro_7000102 = "บนแผ่นกระดาษเป็นภาพกระถางดอกไม้เซรามิกที่มีดินกองเล็กๆ",
  str_item_intro_7000103 = "กระดาษที่ค่อนข้างผุกร่อนคล้ายกับรายงานการวินิจฉัย",
  str_item_intro_7000104 = "ถ้วยน้ำชาที่ประดิษฐ์ขึ้นอย่างวิจิตรงดงาม เปี่ยมคุณค่า",
  str_item_intro_7000105 = "สิ่งมีชีวิตตัวเล็กสีขาวลึกลับที่ไม่ทราบที่มา มันแสดงให้เห็นถึงความชื่นชอบอย่างมากสำหรับดอกแดนดิไลอัน",
  str_item_intro_7000106 = "ของเล่นที่มีลักษณะเฉพาะ แม้ว่าการออกแบบพื้นฐานจะดูธรรมดาๆ แต่ก็มีสัญลักษณ์ของงานฝีมืออันประณีต",
  str_item_intro_7000107 = "กระดาษยับๆ เต็มไปด้วยลายมือที่คดเคี้ยว แม้จะดูเลอะเทอะ แต่ก็สัมผัสได้ถึงความตั้งใจจริงของผู้เขียน",
  str_item_intro_7000108 = "บัญชีแยกประเภทที่มีอายุมากซึ่งเผยให้เห็นว่าเจ้าของไม่มีนิสัยทางบัญชี แทนที่จะบันทึกรายรับและรายจ่าย มันทำหน้าที่เป็นภาชนะสำหรับบันทึกความคิดและไอเดียที่มีพรสวรรค์ของเธอ",
  str_item_intro_7000109 = "สมุดบันทึกที่ผุกร่อน เป็นของคนที่เรียนแล้ว",
  str_item_intro_7000110 = "ประแจขนาดใหญ่ตกแต่งด้วยสติกเกอร์น่ารัก",
  str_item_intro_7000111 = "ที่คาดผมลวดลายประณีตที่มีขนาดเล็กพอให้สัตว์ตัวเท่าตุ๊กตาสวมใส่ได้",
  str_item_intro_7000112 = "กบสีขาวสวมที่คาดผมคล้ายผ้าพันคอเพิ่มเสน่ห์",
  str_item_intro_7000113 = "เมล็ดพันธุ์ที่อ้างว้าง เหมือนคำสาบานที่เคร่งขรึม กำลังรอการค้นพบอยู่ที่มุมหนึ่ง",
  str_item_intro_7000114 = "หญิงสาวที่ตั้งชื่อตามดอกไม้ต้อนรับรุ่งอรุณ เธอตัวเล็กและเปล่งปลั่งเหมือนดอกไม้",
  str_item_intro_7000115 = "แผ่นกระดาษที่มีภาพวาดของประแจขนาดใหญ่ เครื่องมือขนาดใหญ่เช่นนี้ต้องเป็นของคนที่มีรูปร่างสูงและหล่อเหลา",
  str_item_intro_7000116 = "ผู้นำของ Rediesel Wrench ร่างที่เดินฝ่าพายุ เผชิญหน้ากับการสมรู้ร่วมคิด และหัวเราะเมื่อเผชิญกับความสิ้นหวัง ภายใต้ภายนอกที่เป็นเหล็ก ความอ่อนโยนยังคงอยู่",
  str_item_intro_7000117 = "ยักษ์ใหญ่รูปมังกรในตำนานที่วาดด้วยท่วงท่าที่น่ารักคล้ายกับร่างที่สง่างาม แต่ใครก็อดไม่ได้ที่จะชื่นชมปีกสีขาวบริสุทธิ์ของมัน",
  str_item_intro_7000118 = "ผู้ส่งสารสีขาวจากนอกโลก",
  str_item_intro_7000119 = "สมุดสเก็ตช์ที่มีลักษณะศิลป์น่ารัก โชว์ภาพของคนหลายคนที่กำลังหัวเราะอย่างสนุกสนาน",
  str_item_sub_intro_7000100 = "\"สิ่งเหล่านี้ควรเป็นความทรงจำที่มีความสุข แต่พวกเขาเต็มไปด้วยรูพรุน ... ฉันวาดใครกันแน่ในตอนนั้น\"",
  str_item_sub_intro_7000101 = "\"เฮ้ ใครสะเพร่าถึงขนาดฉีกหน้าหมอ? โดนสัตว์ตัวเล็กแทะ? ถ้าอย่างนั้นฉันก็ทำอะไรไม่ได้แล้ว\"",
  str_item_sub_intro_7000102 = "\"ฉันก็มีอ่างเครื่องปั้นเหล่านี้ที่บ้าน! ฉันมีคอลเลกชันเยอะเพราะฉันชอบมาก... แม้ว่าฉันจะไม่สามารถจำเหตุผลที่ชอบได้แน่นอน\"",
  str_item_sub_intro_7000103 = "\"ความกลัว ความโกรธ ความเจ็บปวด... ปัจจัยด้านลบทั้งหมดที่ส่งผลกระทบต่อสภาวะทางร่างกายและจิตใจของคุณได้ถูกขจัดออกไปเรียบร้อยแล้ว ยินดีด้วย ตอนนี้คุณเป็นเด็กที่แข็งแรงแล้ว\"",
  str_item_sub_intro_7000104 = "“นอกจากฉันแล้ว หมอยังมีคนไข้คนอื่นๆ ที่ต้องดูแล มีหญิงสาวผู้สูงศักดิ์จากลูโมโปลิสผู้ชื่นชอบชาดำและถือถ้วยชาใบเล็กๆ ไปทุกที่... ฉันหวังว่าตอนนี้เธอจะหายดีแล้ว”",
  str_item_sub_intro_7000105 = "\"คางคกเป็นไร? ฉันรักคางคกที่สุด! ... ห๊ะ? คุณไม่ใช่คางคกเหรอ?\"",
  str_item_sub_intro_7000106 = "\"ถึงคนที่ฉันรัก, เมื่อเราไม่สามารถอยู่ข้างๆ เธอได้, ขอให้ของขวัญเล็กๆ นี้สร้างความสุขให้เธอ...\"",
  str_item_sub_intro_7000107 = "“เราต้องงดเว้นการใช้ภาษาหยาบคายต่อหน้า *** ให้ทุกคนรับผิดชอบร่วมกัน ใครก็ตามที่ฝ่าฝืนกฎนี้จะต้องกินซอสร้อนดิบสิบแปดขวด และฉันก็ไม่มีข้อยกเว้น”",
  str_item_sub_intro_7000108 = "\"ฉันต้องบอกว่าฉันรู้สึกประหลาดใจอย่างมากกับความรุนแรงของมัน ฉันเคยเชื่อว่าระดับของ ** แสดงถึงขีดจำกัดของสิ่งที่เมล็ดพืชสามารถบรรลุได้ และความก้าวหน้าที่แท้จริงควรอยู่ที่อิทธิพลของ ** ที่มีต่อบุคลิกภาพ อย่างไรก็ตาม พลังดิบ รุนแรง และเหนือจินตนาการของ ** ทำให้ฉันหลงใหล ฉันประหลาดใจที่เมล็ดพันธุ์สามารถใช้ความสามารถเช่นนี้ได้ ความแข็งแกร่งนี้ พลังนี้ เป็นสิ่งที่ **** ต้องการอย่างแท้จริง ตอนนี้ฉันโหยหาพลังของ ** เพื่อ พลิกโฉมโลก\"",
  str_item_sub_intro_7000109 = "\"เมื่อเราไปถึงที่เกิดเหตุ เราตกใจอย่างมากกับร่องรอยการทำลายล้างที่รุนแรง เราคาดเดาว่าบุคคลหนึ่งปลดปล่อยพลังงานมหาศาล ทำลายสิ่งอำนวยความสะดวกและอาคารทั้งหมดตั้งแต่ใต้ดินจนถึงพื้นผิว... เป็นการยากที่จะเข้าใจว่าสัตว์ประหลาดชนิดใดสามารถครอบครองได้ พลังขนาดนั้น...\"",
  str_item_sub_intro_7000110 = "\"สติกเกอร์ลายดอกไม้นี่คุ้นๆ...",
  str_item_sub_intro_7000111 = "\"ผ้าคาดหัวสีขาวลายเส้นสีดำ... เคยเห็นที่ไหนมาก่อนนะ...\"",
  str_item_sub_intro_7000112 = "“ท่านมีข้อความอะไรจะแจ้งแก่ข้าพเจ้า ท่านจะนำทางข้าพเจ้าผู้หลงทางไปตามทางได้หรือไม่”",
  str_item_sub_intro_7000113 = "“ถ้าเธอพรากดอกไม้ไปจากโลกของฉัน ใจฉันคงจมดิ่งลึกลงไปในเหวลึกไกล ฉันเดาว่า”",
  str_item_sub_intro_7000114 = "\"ฉันอยากกลับไปปลูกดอกไม้ทั่ว Red-Eye Gorge\"",
  str_item_sub_intro_7000115 = "\"ด้วยทักษะดังกล่าว คุณสามารถจับภาพความสุดยอดของประแจนี้ได้จริงหรือ... ถ้าใครกล้าวิจารณ์มัน พวกเขาอาจสัมผัสได้ถึงพลังของประแจจริงๆ...\"",
  str_item_sub_intro_7000116 = "\"เขามักจะหาฉันเจอ!\"",
  str_item_sub_intro_7000117 = "\"เดาสิว่าคนประเภทไหนที่ควบคุมยักษ์ใหญ่ได้ขนาดนี้... ล้อเล่นหรือเปล่า! ฉันไม่ได้ล้อเลียนเลปิดอซเลย!",
  str_item_sub_intro_7000118 = "\"รักษาตัวไว้ แล้วเราจะได้พบกันใหม่\"",
  str_item_sub_intro_7000119 = "\"โลกแห่งความจริงและความสุขที่แท้จริง\"",
  str_item_get_7000100 = "ได้รับในฝัน: ตื่นขึ้นในวายุพายุ",
