  str_item_7000201 = "ปากกาขนนก",
  str_item_7000202 = "รายงานเกรด",
  str_item_7000203 = "แท่งชี้",
  str_item_7000204 = "แบบอย่างกฎหมาย (1)",
  str_item_7000205 = "รายงานสืบสวนลับ",
  str_item_7000206 = "แบบอย่างกฎหมาย (2)",
  str_item_intro_7000200 = "แว่นขยายที่ออกแบบอย่างเฉพาะเจาะจงและมีการระบายสีที่โดดเด่น เป็นเครื่องมือที่ขาดไม่ได้ในการสืบสวน",
  str_item_intro_7000201 = "ปากกาขนนกทองวิ้งว้างที่รู้สึกหนักในมือคุณ",
  str_item_intro_7000202 = "รายงานผลการเรียนเยี่ยมจากอุษาวิทยาลัย โชว์ความสามารถในระดับยอดเยี่ยม",
  str_item_intro_7000203 = "ไม้เท้าถูกเก็บอยู่ในมุมห้อง ดูเหมือนจะไม่น่าสนใจ ปลุกความทรงจำเกี่ยวกับวัยเด็กของอิริดอน",
  str_item_intro_7000204 = "ตัวอย่างที่เหลือจากผู้พิพากษาโรเดลล์ โนเวค ซึ่งสะท้อนถึงลักษณะของเขาที่เย็นชาและไม่ยอมประนีประนอม",
  str_item_intro_7000205 = "รายงานการสืบสวนความลับที่เขียนโดยพ่อของอิริดอน นานก่อนการพิจารณาคดีมรดกของบารอน พ่อของเขารู้เรื่องเจตนาที่ซ่อนอยู่เบื้องหลังมรดก",
  str_item_intro_7000206 = "ตัวอย่างคดีที่ผู้พิพากษาโรเดล โนเวคทิ้งไว้ ด้วยคำตัดสินที่นำไปสู่การกำจัดตระกูลหมด",
  str_item_sub_intro_7000200 = "\"นี่เป็นจินตนาการของฉันเท่านั้นหรือไม่ หรือแว่นขยายนี้จริง ๆ กำลังเรียกชื่อฉัน? นั่นไม่น่าเป็นไปได้ แต่แว่นขยายนี้ดูคุ้น ๆ จัง... มันเป็นของฉันหรือเปล่า? มันเกิดอะไรขึ้นกับฉัน? ทำไมฉันถึงจำเรื่องนี้ไม่ได้?\"",
  str_item_sub_intro_7000201 = "\"ทำไมเหรอ? ทำไมฉันไม่เคยชนะใจพวกเขาไม่ว่าจะเป็นพ่อหรือเพื่อนร่วมวัยของฉัน...\"",
  str_item_sub_intro_7000202 = "\"ฉันไม่ได้พยายามที่สุดเหรอ...?\"",
  str_item_sub_intro_7000203 = "\"ต้องใช้ความพยายามเท่าไหร่ในการลืมช่วงเวลาเศร้าหมองจากวัยเด็กของฉัน?\"",
  str_item_sub_intro_7000204 = "\"ฉันควรนำความคิดเบื้องหลังการตัดสินนี้ไปข้างหน้าหรือไม่...\"",
  str_item_sub_intro_7000205 = "ฉ-ฉันทำอะไรลงไปเนี่ย...?",
  str_item_sub_intro_7000206 = "\"ฉันเชื่อว่า...ฉันมีคำตอบของตัวเอง\"",
