  str_item_7000319 = "น้ำหนักทองคำ",
  str_item_7000320 = "น้ำหนักทองคำ",
  str_item_intro_7000300 = "ดูเหมือนว่านอดิริจะไม่มีตราสัญลักษณ์อยู่บนตัวเธอ",
  str_item_intro_7000301 = "คำให้การจากสมาชิกสภานักเรียน: ครอบครัวของแพมกำลังเผชิญกับความยากลำบากทางการเงิน",
  str_item_intro_7000302 = "มีความสัมพันธ์แข่งขันระหว่าง Nodirri และ Pam",
  str_item_intro_7000303 = "คำให้การจากผู้ดูแลประตูเก่า: Nodirri เคยเข้าไปในห้องเรียนด้วยตัวเองก่อนหน้านี้",
  str_item_intro_7000304 = "อาชญากรรมต่อทรัพย์สิน",
  str_item_intro_7000305 = "การกระทำที่ขัดต่อความสงบเรียบร้อยของประชาชน",
  str_item_intro_7000306 = "พินัยกรรมของคุณปู่ได้รับการยืนยันว่าเป็นของแท้แล้ว",
  str_item_intro_7000307 = "พบลายนิ้วมือของเจอร์รี่บนเครื่องมือที่ปู่ใช้ฆ่าตัวตาย",
  str_item_intro_7000308 = "คำให้การของเพื่อนบ้าน: คุณปู่กล่าวว่าต้องการส่งต่อทุกอย่างให้หลานสาวของเขา",
  str_item_intro_7000309 = "พยานให้การ: ไม่มีความผิดปกติใดๆ เมื่อปู่ทำพินัยกรรม",
  str_item_intro_7000310 = "การปลอมเอกสาร",
  str_item_intro_7000311 = "กฎหมายสืบทอดพินัยกรรม",
  str_item_intro_7000312 = "พบตราตระกูลไพรัสในห้องของกอทิเยร์",
  str_item_intro_7000313 = "คำสาปที่มีร์เรน กอทิเยร์เขียนในสมุดวาดของเขา",
  str_item_intro_7000314 = "ตระกูลกอทิเยร์จับตัวสมาชิกตระกูลไพรัสเพื่อนำไปทดลอง",
  str_item_intro_7000315 = "ตระกูลไพรัสยังคงวิจัยคริสตัลแดง",
  str_item_intro_7000316 = "การทรยศ",
  str_item_intro_7000317 = "ความผิดในการกระจายข่าวลือ",
  str_item_intro_7000318 = "พบหลักฐานสำหรับคดีขโมยตราสัญลักษณ์ดอว์น!",
  str_item_intro_7000319 = "พบหลักฐานสำหรับคดีพินัยกรรมของปู่!",
  str_item_intro_7000320 = "พบหลักฐานสำหรับคดีทรยศของตระกูลกอทิเยร์!",
  str_item_sub_intro_7000300 = "เมื่อได้ยินเรื่องราวของคดีจาก Pam นอดิริ ก็โกรธอย่างชัดเจน ซึ่งเธอก้าวใกล้กับ Pam และยิงคำถามเป็นหมื่นเสียงเกี่ยวกับเหตุผลที่เธอจะป้ายสีเธออย่างนี้ ในการพิสูจน์ความบริสุทธิ์ของตัวเอง นอดิริยินดีให้อิริดอนค้นตัวเธอ และดังที่คาดหวัง ไม่พบข้อกล่าวหาใดๆ",
  str_item_sub_intro_7000301 = "ในทางไปห้องเรียนเอง อิริดอนถูกเข้าใกล้อย่างลับๆ โดยสมาชิกของสภานักเรียน ที่แชร์มุมมองของเขาอย่างเต็มใจว่า \"ครอบครัวของแพมไม่เคยเป็นบ้านชั้นสูงชนชั้นสูง และพ่อแม่ของเธอไม่เคยดำรงตำแหน่งในรัฐบาล ในช่วงนี้ดูเหมือนว่าพวกเขากำลังประสบปัญหาทางการเงินเพื่อเหตุผลบางอย่าง!\"",
  str_item_sub_intro_7000302 = "บนกระดานประกาศของโรงเรียน อิริดอนพบประกาศจากโบสถ์ลูโมโพลิส: ปีนี้พวกเขาได้รับนักศึกษาแม่ชีสองคนคือ แพม และ โนดีร์ อย่างไรก็ตาม เพียงหนึ่งคนเท่านั้นที่สุดท้ายจะมีโอกาสได้รับการสงวนไว้ที่โบสถ์",
  str_item_sub_intro_7000303 = "อิริดอนเดินใกล้ห้องเรียนเองและเห็นผู้คุมประตูชรากำลังหลับใกล้ๆ ชัดเจนว่าผู้คุมประตูไม่ได้ลืมอิริดอน เนื่องจากได้รับความช่วยเสริมจากอิริดอนหลายครั้งในระหว่างเรียน ผู้คุมประตูกล่าวว่าวันนี้นอกจาก Pam แล้ว มีเพียง Nodirri เข้าห้องเรียนเอง เขาสงสัยในตอนนั้นว่าทำไม Nodirri ถึงใช้ผ้าเช็ดหน้าเปิดประตู \"อาจเป็นเพราะเธอกลัวเชื้อโรค ฉันไม่คิดมากในตอนนั้น\"",
  str_item_sub_intro_7000304 = "การลักขโมยทรัพย์สินที่มีความสำคัญ เมื่อมูลค่าของที่ถูกขโมยมากขึ้น สามารถถูกลงโทษด้วยการจำคุกตั้งแต่สามถึงสิบปีและปรับเงิน",
  str_item_sub_intro_7000305 = "การดูหมิ่นหรือให้ความเสียหายต่อชื่อเสียงของผู้อื่นอย่างเปิดเผย หากมีเหตุการณ์ร้ายแรง อาจถูกจำคุกสูงสุดถึงสามปีและปรับเงิน",
  str_item_sub_intro_7000306 = "เจอร์รี่นำพินัยกรรมที่เขาถืออยู่มาให้อิริดอน หลังจากการเปรียบเทียบและวิเคราะห์อย่างรอบคอบ อิริดอนยืนยันว่าพินัยกรรมของปู่ของแพมจริงๆ นั้นเขียนโดยตัวเขาเอง ในพินัยกรรม ปู่มอบตำแหน่งและทรัพย์สินให้เจอร์รี่ โดยกล่าวว่า \"ฉันมีชีวิตอยู่นานพอแล้ว และฉันไม่มีความเสียใจ\" อิริดอนให้ความสนใจในคำพูดนี้เป็นพิเศษ เนื่องจากดูเหมือนว่าปู่ให้ความเป็นนัยว่าเขาตั้งใจจะฆ่าตัวตายเมื่อเขียนพินัยกรรม",
  str_item_sub_intro_7000307 = "อิริดอนไปถึงบ้านของปู่ของ Pam และพบว่าเขาตัดสินใจตัดชีวิตตัวเองด้วยมีดผลไม้ขนาดเล็ก อย่างไรก็ตาม เมื่อตรวจสอบมีดใกล้ชิด อิริดอนพบลายนิ้วมือของ Jerry บนมีด และ Jerry อธิบายว่าเขามักเตรียมอาหาร ดังนั้นการมีลายนิ้วมือของเขาบนเครื่องครัวไม่น่าแปลกใจ อิริดอนประเมินสถานการณ์ใหม่และยืนยันว่าปู่ของ Pam ฆ่าตัวตายเอง",
  str_item_sub_intro_7000308 = "อิริดอนเคาะประตูบ้านเพื่อนบ้านของคุณปู่ และเพื่อนบ้านบอกอิริดอนว่า ถึงแม้คุณปู่จะบ่นเรื่องความไม่สามารถของลูกชายเขาบ่อย ๆ แต่เขาก็ยังค่อยๆ คุยขยายความเกี่ยวกับหลานสาวของเขา คุณปู่ยังเคยบอกเปิดเผยให้คนอื่นรู้ว่าเขาตั้งใจจะส่งต่อตำแหน่งและทรัพย์สินให้หลานสาวของเขา โดยไม่ทิ้งอะไรให้ลูกชายเลย",
  str_item_sub_intro_7000309 = "พยานในการทำพินัยกรรมคือคนรับใช้คนเก่าที่ได้รับการศึกษาดี คนรับใช้คนเก่าแสดงความยินดีอย่างยิ่งที่ได้รับเชิญจากปู่ให้เป็นพยาน ในขณะที่คำพูดออกจากปากคนรับใช้คนเก่า เขารู้สึกว่าพูดผิดพลาดอย่างกะทันหัน คนรับใช้รู้สึกอายและยังคงอธิบายว่าไม่มีอะไรแปลกประหลาดเมื่อปู่ทำพินัยกรรม และเขายืนยันซ้ำ ๆ ว่านี่คือความประสงค์ที่แท้จริงของปู่จริง ๆ",
  str_item_sub_intro_7000310 = "การทำปลอมเอกสารสาธารณะหรือส่วนตัวเพื่อกิจกรรมทุจริตจะถูกลงโทษด้วยการจำคุกตั้งแต่สามถึงสิบปีและปรับ",
  str_item_sub_intro_7000311 = "พินัยกรรมที่ถูกต้องตามกฎหมายจำเป็นต้องปฏิบัติตามในการแบ่งปันทรัพย์สินตามเนื้อหาที่ระบุไว้",
  str_item_sub_intro_7000312 = "อิริดอนเข้าเร็วๆ ลับๆ ไปในห้องของตระกูลกอทิเยร์ที่ลูโมโพลิสชั้นล่าง ค้นหาอย่างระมัดระวัง ในที่สุดเธอก็พบตราประจำตระกูลไพรัสซ่อนอยู่ในมุมห้อง ทั้งตระกูลกอทิเยร์และไพรัสถูกเนรเทศไปยังลูโมโพลิสชั้นล่างเนื่องจากคดีคริสตัลแสงเลือด มันเป็นไปได้หรือไม่ว่าทั้งสองตระกูลนี้กำลังร่วมมือกันในการกบฏ? อิริดอนไม่กล้าคิดต่อไป  \"แพมก็เป็นสมาชิกของตระกูลไพรัสเช่นกัน...\"",
  str_item_sub_intro_7000313 = "อิริดอนพบบ้านที่สภาพเสื่อมโทรมอีกหลัง และข้างในเธอพบสมุดวาดภาพที่ลงชื่อว่า \"มีร์เรน กอทิเยร์\" ในหนังสือมีลวดลายบางอย่างที่อิริดอนรู้สึกยากในการเข้าใจ อิริดอนยักคิ้ว และในหมู่ลวดลายเธอค้นพบข้อความบรรทัดเล็ก ๆ: \"ทำไมคุณจึงทำให้ฉันเสียใจแบบนี้... ทำไม, ทำไมเถอะ?! ฉันจะควบคุมชะตาชีวิตของฉันเองอีกครั้ง... แม้ว่าฉันจะต้องใช้พลังของพวกเขา\"",
  str_item_sub_intro_7000314 = "อิคลิพไซท์พิลึกปรากฏขึ้นอย่างกะทันหันบนถนน ไม่รู้ลังเล อิริดอนเดินหน้าและแทงอกของอิคลิพไซท์ ทำให้มันล้มลงบนพื้น แต่อย่างกะทันหัน หัวใจของอิคลิพไซท์เหมือนตื่นขึ้นจากความสับสน ยกมือขึ้นในทิศทางของฝูงชน ดูเหมือนกำลังพยายามพูดอะไร อิริดอนเข้าใกล้ ได้ยินเสียงกระซิบของอิคลิพไซท์ \"กอทิเยร์... แสวงแค้น... ต่อต้านไพรัส... พวกเขา... จับเรา... เพื่อทดลอง... พวกเขากำลังวางแผน... การกบฏ!\"",
  str_item_sub_intro_7000315 = "ในขณะที่อิริดอนคิดคำนึงถึงการดำเนินการสืบสวนต่อไป ผู้สัญจรที่แตกสึกหน้าตัวเข้ามาอย่างไม่เปิดเผย คนนี้อ้างว่าทราบข้อมูลเกี่ยวกับเหตุการณ์ล่าสุดในลูโมโพลิสชั้นล่าง โดยเปิดเผยว่าครอบครัวพีรัสยังคงทำการวิจัยเกี่ยวกับคริสตัลแสงเลือด อิริดอนถามว่าทำไมเขาถึงเปิดเผยข้อมูลนี้ และผู้สัญจรแยกปากของเขา เปิดเผยฟันที่เข้มข้นและพูดว่า \"คุณสามารถนำฉันกลับไปยังลูโมโพลิสคอร์ทยาร์ดได้หรือไม่?\"",
  str_item_sub_intro_7000316 = "การวางแผนหรือพยายามขัดขวางการปกครองของลูโมโพลิสโดยเจตนาจะส่งผลให้ต้องรับโทษจำคุกตลอดชีวิต และอาจถูกตัดสินประหารชีวิตในกรณีที่ร้ายแรงขึ้น",
  str_item_sub_intro_7000317 = "การกระจายข่าวลือเท็จเกี่ยวกับผู้อื่นโดยเจตนาจะนำไปสู่การต้องโทษจำคุกสูงสุดหนึ่งปีและปรับเงิน",
  str_item_sub_intro_7000318 = "อิงตามหลักฐานและคำให้การของพยาน อิริดอนสามารถสืบค้นว่า Nodirri เป็นคนร้ายที่ขโมยตราอัศวินของดอว์น",
  str_item_sub_intro_7000319 = "คุณถือว่ามรดกนั้นถูกต้อง และคนรับใช้เจอร์รี่จะสืบทอดตำแหน่งของคุณปู่ของแพมและทรัพย์สินของเขาทั้งหมด...",
  str_item_sub_intro_7000320 = "คุณได้รวบรวมหลักฐานและคำให้การครบถ้วน ยืนยันว่ามีร์เรน กอทิเยร์ได้ลักพาตัวสมาชิกตระกูลไพรัสเพื่อทดลองและมีเจตนารมณ์ก่อกบฏ",
  str_item_7000400 = "กุญแจเก่า",
  str_item_7000401 = "คุกกี้ของเดย์นา",
  str_item_7000402 = "พิมพ์เขียวสำหรับบ้านใหม่",
  str_item_7000403 = "ทรอมโบนสง่างาม",
  str_item_7000404 = "โน้ตดนตรีใหม่",
  str_item_7000405 = "ภาพเหมือนของเดย์นา",
  str_item_7000406 = "ภาพเหมือนของโรบิน",
  str_item_7000407 = "ท่านหญิงในภาพเหมือนของกาน้ำชา",
  str_item_7000408 = "ภาพเหมือนปลาโลมาสีขาว",
  str_item_intro_7000400 = "กุญแจไปยังห้องใต้หลังคาที่ป้าให้คอนนอลลี ใช้มันอย่างระมัดระวังเพื่อไม่ให้กุญแจเก่ากรีดร้องและรบกวนคนอื่น",
  str_item_intro_7000401 = "คุกกี้ที่คอนนอลลีนำมาให้เดย์นา แต่ถูกเงือกยามขโมยไป พวกนี้ไม่หวานตามคำขอของเดย์นา",
  str_item_intro_7000402 = "ภาพวาดสำหรับป้อมของเจ้าสมุทร อาจไม่ถูกต้อง แต่ควีนคอนนอลลีขอสงวนสิทธิ์ในการตีความทั้งหมด",
  str_item_intro_7000403 = "เครื่องดนตรีใหม่ที่ชาวเมืองค้นพบให้คอนนอลลีสามารถเล่นเสียงดังและมีอำนาจมากขึ้นเพื่อสื่อความโกรธ",
  str_item_intro_7000404 = "บทเพลงแห่งวารีที่คอนนอลลีพบในห้องใต้หลังคาเก่า ณ ปัจจุบันถูกเซ็นชื่อใหม่แล้ว",
  str_item_intro_7000405 = "ภาพเหมือนของเดย์นาที่ถูกวาดโดยศิลปินในเมืองใต้ทะเล ณ ปัจจุบันถูกวางไว้บนที่นั่งว่างๆ ของควีนคอนนอลลี เพื่อใช้เป็นเครื่องประดับในการฝึกฝนคำปราศรัยของเธอ",
  str_item_intro_7000406 = "ภาพเหมือนของโรบินที่วาดโดยศิลปินในเมืองใต้ทะเล ณ ปัจจุบันถูกวางไว้ในที่นั่งว่างๆ ของควีนคอนนอลลีเพื่อใช้เป็นอุปกรณ์เสริมในการซ้อมคำปราศรัย",
  str_item_intro_7000407 = "ภาพเหมือนของที่ปรึกษาลึกลับที่วาดโดยศิลปินในเมืองใต้ทะเล ณ ปัจจุบันถูกวางไว้ในที่นั่งว่างโดยควีนคอนนอลลีเพื่อเป็นของตกแต่งในการซ้อมคำปราศรัยของเธอ",
  str_item_intro_7000408 = "ภาพวาดปลาเป็นมิตรโดยศิลปินในเมืองใต้ทะเล ณ ปัจจุบันถูกวางไว้บนที่นั่งว่างของควีนคอนนอลลีเป็นเครื่องประดับในการซ้อมคำปราศรัยของเธอ",
  str_item_sub_intro_7000400 = "\"เธอนอนอยู่ในห้องใต้หลังคา กินสิ่งที่คนอื่นปฏิเสธ พูดเสียงกระซิบอ่อน ซ่อนตัวในมุมที่สุด! กวาดห้องในเวลากลางวัน เล่นเครื่องดนตรีในเวลากลางคืน ปลอบใจความเหงาของเธอด้วยดนตรี!\"",
  str_item_sub_intro_7000401 = "\"คุกกี้ของฉัน! คอนนอลลีให้ฉันนั่นแหละ! ทำไมลูกน้องตัวสกปรกถึงไม่ยอมปล่อยคุกกี้ไว้เลยนะ!\"",
  str_item_sub_intro_7000402 = "\"โลกอื่น ที่... ความงามยิ่งใหญ่... สนุกสนาน!\"",
  str_item_sub_intro_7000403 = "ความเจ็บปวดและความเศร้า... จะพบกับการช่วยเสียงด้วยดนตรี!",
  str_item_sub_intro_7000404 = "\"มันเคยแสดงความปรารถนาให้ฉันตั้งชื่อใหม่ให้มัน ฉันคิดอย่างหนักและนาน Rubinstein, Salieri, Leopold, Dvorak... นั่นคือชื่อโปรดของมัน... อะไร, ชื่อที่ใกล้ชิดกันขึ้น?\"",
  str_item_sub_intro_7000405 = "\"ฉันดุเกินไป คุณว่างั้นเหรอ? ฉันจะไม่ดุได้ยังไงเมื่อฉันต้องยืนหายใจเพื่อพี่น้องของฉัน?\"",
  str_item_sub_intro_7000406 = "ใช่ครับ มีปลาตัวหนึ่งเคยเรียกฉันว่าแบนราบและไม่น่าสังเกตครับ... แต่นั่นเองที่ทำให้ฉันอยู่รอด...",
  str_item_sub_intro_7000407 = "\"คุณอยากให้ฉันกลับมาจากการเกษียณ? งั้น คุณต้องจ่ายค่าใช้จ่ายนะ\"",
  str_item_sub_intro_7000408 = "\"ฉันเป็นใครสำหรับควีนคอนนอลลี คุณถามหรือ? นั่นเป็นความลับ!\"",
  str_item_7000801 = "โบราณ",
  str_item_intro_7000801 = "ของเก่าที่พบได้ทุกมุมของ Twin Pavilions Bay สิ่งประดิษฐ์ทางวัฒนธรรมของหลงโจวมีค่าสูงในประเทศอื่น ๆ แต่บางอย่างได้รับผ่านการซื้อขายที่ซื่อสัตย์ที่มีการสั่งซื้อและการชำระเงินที่เกี่ยวข้อง ในขณะที่อื่น ๆ ถูกขโมยในแชโดว์โดยขโมย",
  str_item_6030101 = "สมุดสเก็ตช์จิ๋ว",
  str_item_6030102 = "อุณหภูมิรอยยิ้ม",
  str_item_6030103 = "รุ่งอรุณของอีฟ",
