  str_item_6030113 = "สายตาที่เฝ้ามองของเขา",
  str_item_6030114 = "คำสาบานศักดิ์สิทธิ์ของเธอ",
  str_item_6030115 = "ดาบรีกัล",
  str_item_6030116 = "หวานใจแห่งรถจักร",
  str_item_6030117 = "ลุคใหม่ของหินแห่งการล่า",
  str_item_6030118 = "ป่าครีม",
  str_item_6030119 = "ป้ายทหารสุนัข",
