  str_item_6030121 = "ธงอิลลูมินา",
  str_item_6030122 = "ความคิดของนิคินิส",
  str_item_6030123 = "ความปรารถนาของ Nepolis",
  str_item_6030124 = "กระจกนอร์ธแลนด์",
  str_item_intro_6030101 = "เหรียญยืนเคียงข้างฉัน\nสมุดวาดขนาดเล็กแสดงลายเส้นที่เด็กๆ แต่มันไม่สามารถปกปิดความรู้สึกของความลังเลและความผูกพันภายใน ทำให้ยากที่จะจากลา",
  str_item_intro_6030102 = "เหรียญยืนโดยฉัน.\nแม้ว่าวันโลกาวินาศจะมาถึง เขาก็จะเตรียมน้ำในอุณหภูมิที่เหมาะสมสำหรับน้องสาวเสมอ",
  str_item_intro_6030103 = "เหรียญยืนโดยฉัน.\nในปีที่มืดมนนั้น ดอกไม้นี้คือรุ่งอรุณของเธอ",
  str_item_intro_6030104 = "เหรียญยืนเคียงข้างฉัน\nการยอมรับจากวัด Lumopolis",
  str_item_intro_6030105 = "เหรียญยืนเคียงข้างฉัน\nสายตาคมของอิริดอนไม่ปล่อยให้มีตราชั่งไม่สมดุล",
  str_item_intro_6030106 = "เหรียญยืนเคียงข้างฉัน\nในวันนั้น พาโลม่ายังยินดีที่จะเชื่อ...",
  str_item_intro_6030107 = "เหรียญยืนเคียงข้างฉัน\nนี่คือความยินดีจากท่านอควาลอร์ดที่ยิ่งใหญ่! คุณมนุษย์เหล่านี้ ยืดแขนขาของคุณเพื่อรับความกรุณาของฉัน!",
  str_item_intro_6030108 = "เหรียญยืนเคียงข้างฉัน\nฉันเล่นเพลงนี้คนเดียวด้วยความหวังของสมาชิกครอบครัว ความใส่ใจจากเพื่อนสนิท และ... ความรักและความกล้า",
  str_item_intro_6030109 = "เหรียญยืนเคียงข้างฉัน\nฉันมองหาที่พักอาศัยเท่านั้น แต่ที่น่าประหลาดใจ ฉันกลับสามารถทำให้มันกลายเป็นบ้านที่สวยงาม",
  str_item_intro_6030110 = "เหรียญยืนเคียงข้างฉัน\nความอบอุ่นที่ฉันรู้สึกอยู่ตอนนี้ เป็นแสงสว่างของพระอาทิตย์ในตอนเช้าหรือความอบอุ่นของคุณหลังจากผ่านพ้นหนามที่คมเ sharp?",
  str_item_intro_6030111 = "เหรียญยืนเคียงข้างฉัน\nมีคนน้อยมากที่รู้ว่าดอกไม้ของต้นไทรบริสุทธิ์ก็บานด้วย แต่มันมีขนาดเล็กกว่าดอกวิสเทอเรีย มีสีม่วงอ่อน และดูเหมือนกระโปรงของนักดาบ",
  str_item_intro_6030112 = "เหรียญยืนเคียงข้างฉัน\nเมื่อวันหนึ่งเธอผ่านไปที่แม่น้ำทองที่พร่างพราย แน่นอนเธอจะรำลึกถึงการขับเรือในฝันของเธอ และรอคอยการแบ่งปันการขับเรือกับบุคคลบางคน",
  str_item_intro_6030113 = "เหรียญยืนเคียงข้างฉัน\n\"คุณคือเหตุผลที่ทำให้โลกนี้คุ้มค่าที่จะปกป้อง\"",
  str_item_intro_6030114 = "เหรียญยืนเคียงข้างฉัน\n\"คุณคือเหตุผลที่ฉันต้องการปกป้องโลกนี้\"",
  str_item_intro_6030115 = "เหรียญยืนเคียงข้างฉัน\nมันได้รับพลังที่ไม่ธรรมดาผ่านการสลั่มด้วยความรักของรีกัล บางทีนี่เป็นเหตุผลเดียวที่ทำให้เธอสามารถอยู่ข้างๆ เขาในรูปแบบที่แตกต่างไป",
  str_item_intro_6030116 = "เหรียญยืนเคียงข้างฉัน\nเมื่อมันออกไป มันดูเหมือนเครื่องจักรที่เย็นชาและไม่มีความรู้สึก เมื่อมันกลับมาเท่านั้น ธรรมชาติที่หวานนั้นจึงเป็นที่เห็นชัดเจน",
  str_item_intro_6030117 = "เหรียญยืนเคียงข้างฉัน\nเนื่องจากการทิ้งมันไปไม่ได้... มันอาจจะเป็นสิ่งประดิษฐ์แฟชั่นที่ไม่ซ้ำใครได้เช่นกัน",
  str_item_intro_6030118 = "เหรียญยืนเคียงข้างฉัน ต้นไม้ที่ไหลเรียกด้วยครีมหนาและดอกไม้ที่ผลิตผลไม้ที่หวานที่สุด... สถานที่ที่เหมาะสมที่สุดสำหรับการปิกนิก หากมีโอกาสเกิดขึ้น",
  str_item_intro_6030119 = "เหรียญยืนเคียงข้างฉัน แท็กทุกอันแทนที่ชีวิตหนึ่ง ขอให้วิญญาณที่รุ่งเรืองทั้งหมดนี้สงบสุข",
  str_item_intro_6030120 = "เหรียญยืนเคียงข้างฉัน ผู้นี้มีพ่อแม่คือใคร? ผู้นี้มีลูกหรือพี่น้องหรือไม่? ชื่อที่ถูกสลักบนหินยังคงเงียบสงบ ในขณะที่สะท้อนเส้นทางที่อยู่ข้างหน้า",
  str_item_intro_6030121 = "เหรียญยืนเคียงข้างฉัน ธงกระพริบกระเป๋าในลมขณะที่เสียงเรียกสู้ส่งเสียงดัง ผู้ป้องกันที่ไม่เห็นแก่ตัวที่สุดของแอสตร้าก้าวไปอย่างกล้าหาญ ไม่เคยถอยหลังขณะที่พวกเขาขังความมืดอยู่ที่อยู่ไกล",
  str_item_intro_6030122 = "เหรียญยืนเคียงข้างฉัน\n\"ทั้งหมดที่ฉันต้องการคืออยู่ข้างๆ พี่สาวของฉัน...\"",
  str_item_intro_6030123 = "เหรียญยืนเคียงข้างฉัน\n\"ทุกสิ่งที่ฉันปรารถนาคือให้น้องสาวของฉันรอดชีวิต...\"",
  str_item_intro_6030124 = "เหรียญยืนเคียงข้างฉัน กระจกนี้ได้เห็นการล่มสลายของสิ่งต่างๆมากมาย บางทีอาจเป็นเวลาที่จะให้มันเห็นสิ่งใหม่ๆ",
  str_item_6130101 = "แผ่นหินที่ระลึก Stand By Me",
  str_item_6130102 = "กระจกยืนเคียงข้างฉัน",
  str_item_6130103 = "กระดานคอนเสิร์ต Stand By Me",
  str_item_6130104 = "กระดานฝัน Stand By Me",
  str_item_6130105 = "คณะกรรมการสายตาที่ร่วมกัน",
  str_item_6130106 = "กระดาน Stand By Me",
  str_item_6130107 = "กระดานทหาร Stand By Me",
  str_item_6130108 = "กระดานบทกวี Stand By Me",
  str_item_intro_6130101 = "คณะกรรมการอนุสรณ์ Stand By Me.\nมันจบแล้ว; อดีตผ่านไปแล้ว กลับบ้านกันเถอะ",
  str_item_intro_6130102 = "คณะกรรมการอนุสรณ์ Stand By Me.\nผู้ที่อยู่ในกระจก, มาตื่นขึ้นมาด้วยกัน.",
  str_item_intro_6130103 = "คณะกรรมการอนุสรณ์ Stand By Me.\nจิตใจของฉันยังไม่เคยแข็งแกร่งขนาดนี้ และเสียงของฉันยังไม่เคยสวยงามขนาดนี้",
  str_item_intro_6130104 = "คณะกรรมการอนุสรณ์ Stand By Me.\nเธอต่อสู้กับคำสาปทุกวันหลังจากตื่นขึ้นในตอนเช้า แต่ฝันของเธอสว่างสดใส: เธอจะต้อนรับแสงเช้าที่สว่างเบาในเมืองที่เรียบร้อยและคึกคัก",
  str_item_intro_6130105 = "คณะกรรมการอนุสรณ์ Stand By Me.\nแม้ว่าพันปีอาจจะสลายเป็นฝุ่น หายไปเป็นอันขาด แต่หัวใจของฉันยังคงมั่นคง",
  str_item_intro_6130106 = "คณะกรรมการอนุสรณ์ Stand By Me.\nคลิก-คลัก, คลิก-คลัก! ยึดติดกับราง, รถไฟวิ่งผ่านฝันที่สดใส มันวิ่งผ่าน Cream Forest, ผ่านน้ำตาลที่น้ำตาล, และผ่านความเสียใจที่กำลังเกิดขึ้นของนักเดินทางคนเดียว...",
  str_item_intro_6130107 = "คณะกรรมการอนุสรณ์ Stand By Me.\n\"ฉันยินดีที่จะถูกทำให้แข็งแกร่งได้นับไม่ถ้วน ฉันเชื่ออย่างแน่นอนว่าการทดสอบเหล่านี้จะนำฉันไปสู่แสงของ Illumina กระสุนเหล็กเต็มที่ถูกขัดแต่งนี้บรรจุความปรารถนาที่ไม่สั่นสะเทือนของเรา\"",
  str_item_intro_6130108 = "คณะกรรมการอนุสรณ์ Stand By Me.\n\"ร่างกายของเธอถูกปิดทับด้วยหิมะ, วิญญาณของเธอถูกมัดมากับกระจก, และหน้าของเธอถูกมงกุฎด้วยดอกไม้ที่เหี่ยวย่น, แต่ความรักของเธอไม่เคยเหี่ยวย่น.\"",
  str_item_3001000 = "เศษฝัน",
  str_item_intro_3001000 = "ชิ้นส่วนที่ได้รับจากเรื่องราวที่ความเป็นจริงและภาพลวงตามัวหมองสลับซับซ้อนกัน ระลึกถึงร่องรอยของโลกแห่งความเป็นจริง สามารถแลกเปลี่ยนเพื่อรับรางวัลไอเทมในร้าน Authentic Dreamscapes ได้",
  str_item_get_3001000 = "ความฝัน - การแปลง Token ของ Theme Store หมดอายุ",
  str_item_3001001 = "การเปลี่ยนแปลง",
  str_item_intro_3001001 = "ของที่ระลึกที่ทิ้งไว้หลังจากเผชิญความท้าทายและเติบโต สามารถแลกเป็นรางวัลไอเทมได้ใน Dream - Awakening in the Storm - Memory Workshop",
  str_item_get_3001001 = "ความฝัน - ตื่นขึ้นในระยะพายุ",
  str_item_3001002 = "เศษตะกอน",
  str_item_intro_3001002 = "ชิ้นส่วนที่ได้รับหลังจากเผชิญกับความท้าทายและเติบโต สามารถแลกเป็นรางวัลไอเทมได้ใน Dream - Awakening in the Storm - Memory Workshop",
  str_item_get_3001002 = "ความฝัน - ตื่นขึ้นในระยะพายุ",
  str_item_3001003 = "ปัญญา",
  str_item_intro_3001003 = "ความสำคัญในการทำให้อีฟมีความสามารถในการคิดอย่างมีเหตุผลและจิตใจชัดเจน เพื่อสามารถต้านทานโอเมนใน Awakening in the Storm ได้ คะแนน Wit จะเติมเต็มขึ้น 3 คะแนนทุกวันเวลา 05:00 (UTC+0) หรือ 00:00 (UTC-5) (จะไม่มีคะแนนถ้าถึงขีดจำกัดแล้ว)",
  str_item_get_3001003 = "การกู้คืนอัตโนมัติเมื่อเวลาผ่านไป",
  str_item_3001004 = "ระลอกคลื่นแห่งความสุข",
  str_item_intro_3001004 = "ถ้วยโปรดของอีฟมีเพียงน้ำธรรมดาเท่านั้น แต่มันเสริมพลังให้เธอ รวบรวมและอัพเกรดระดับ \"รอยยิ้มนำไปสู่ความสุข\"",
  str_item_get_3001004 = "ได้รับจากการเคลียร์ด่าน Nightmare ใน Dream ด้วย 3 ดาวเป็นครั้งแรก",
  str_item_3001005 = "น้ำหนักถ่วงแห่งวิญญาณ",
  str_item_intro_3001005 = "น้ำหนักที่ได้รับระหว่างการตามหาตัวตนที่แท้จริงเพื่อสมดุลในตาชั่งชีวิต สามารถนำไปแลกเปลี่ยนรางวัลไอเทมใน ดรีม - การทดสอบในริมฝั่งทองคำ - การประมูลทดลอง",
  str_item_get_3001005 = "ด่านฝัน - ทดลองในคลื่นทองคำ",
  str_item_3001006 = "เทียนเที่ยงธรรม",
  str_item_intro_3001006 = "เปลวไฟเทียนดาวที่เหลืออยู่บนเส้นทางในการตามหาความยุติธรรมในหัวใจของคน สามารถนำไปแลกของรางวัลในฝัน - การทดสอบในริมฝีพระอาทิตย์ทองคำ - การประมูลทดลอง",
  str_item_get_3001006 = "ด่านฝัน - ทดลองในคลื่นทองคำ",
  str_item_3001007 = "ปัญญา",
  str_item_intro_3001007 = "เป็นกุญแจสำคัญในการช่วยให้คนสามารถรักษาราชันและความชัดเจน มันจะถูกใช้ในระหว่างการสำรวจ แต่สามารถเติมเต็มคืนค่อย ๆ กับเวลา",
  str_item_get_3001007 = "การกู้คืนอัตโนมัติเมื่อเวลาผ่านไป",
  str_item_3001008 = "แสงความยุติธรรม",
  str_item_intro_3001008 = "แสงยุติธรรมที่อิริดอนได้เรียกคืนด้วยความพยายามของตัวเธอเอง สะสมมันเพื่อเลื่อนระดับความสนใจในความจริง",
  str_item_get_3001008 = "ได้รับจากการเคลียร์ด่าน Nightmare ใน Dream ด้วย 3 ดาวเป็นครั้งแรก",
  str_item_3001010 = "เปลือกหอยสะท้อนเสียง",
  str_item_intro_3001010 = "ภายในเปลือกหอยที่สะท้อนเสียงเพลงนี้ คือชิ้นส่วนของโน้ตเพลงโบราณที่สามารถนำไปแลกของรางวัลในฝัน: คาเฟ่ฟองน้ำใต้ทะเลแฟนตาเซียของคอนนอลลี",
  str_item_get_3001010 = "ฝัน: สเตจแฟนตาซีใต้น้ำของคอนนอลลี",
  str_item_3001011 = "ฟลูออโรฟอร่าอร่อยๆ",
  str_item_intro_3001011 = "สาหร่ายเรืองแสงที่มุมของชั้นล่างของมหาสมุทรนำไปใช้ในการทำเครื่องดื่มยอดนิยมในทะเลลึก สามารถนำไปแลกของรางวัลใน คาเฟ่ฟองน้ำทะเลแฟนตาเซียใต้น้ำของคอนนอลลีในฝัน",
  str_item_get_3001011 = "ฝัน: สเตจแฟนตาซีใต้น้ำของคอนนอลลี",
  str_item_3001012 = "ปัญญา",
  str_item_intro_3001012 = "เป็นกุญแจสำคัญในการช่วยให้คนสามารถรักษาราชันและความชัดเจน มันจะถูกใช้ในระหว่างการสำรวจ แต่สามารถเติมเต็มคืนค่อย ๆ กับเวลา",
  str_item_get_3001012 = "ฝัน: สเตจแฟนตาเซียใต้น้ำของคอนนอลลี",
  str_item_3001013 = "ศึกษาเกี่ยวกับแพกต์",
  str_item_intro_3001013 = "คอนนอลลีพยายามที่จะเข้าใจทุกสิ่งที่อควาลอร์ดบรรยายและทำความเข้าใจในปัญญาลึกลับ สะสมเพื่อปรับปรุงระดับการเชื่อมต่ออควา",
  str_item_get_3001013 = "ได้รับจากการเคลียร์ด่าน Nightmare ใน Dream ด้วย 3 ดาวเป็นครั้งแรก",
  str_item_3001014 = "พวงผมวิสเทอเรีย",
  str_item_intro_3001014 = "ตรงผมที่ทำจากดอกไม้เล็กๆที่แข็งแรง สามารถใช้แลกของรางวัลใน ฝัน - เพลงดาบใต้ม่านฝัน - การแลกเปลี่ยนสีเขียว",
