  str_item_intro_3000131 = "สามารถใช้เพื่อรับสมัครครั้งเดียวจากงานรับสมัครเฉพาะ Twilight Symphony\nไอเทมนี้จะหมดอายุในที่สุดและจะไม่ถูกแปลงเป็นไอเทมอื่น โปรดจำไว้ใช้มันก่อนที่งานรับสมัครเฉพาะ Twilight Symphony จะสิ้นสุด",
  str_item_10000992 = "กล่องเคลเคนยูไนเต็ด",
