  str_item_3755025 = "ดอกรุ่งอรุณ",
  str_item_intro_3755023 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n*เสียงร้อง*... คุณชอบมั้ย?",
  str_item_intro_3755024 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nดอกเพ็กผืน? อย่าหนีจากฉันนะ!",
  str_item_intro_3755025 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nดอกไม้ขาวเล็ก ๆ นี้ แต่ก็เป็นตัวแทนของดอว์น...",
  str_item_3661219 = "ภาพเหมือนอัศวิน Fiat",
  str_item_intro_3661219 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nภาพเหมือนที่สร้างขึ้นตามรูปของอิริดอนในวันที่เธอเป็นอัศวิน ดูเหมือนว่าเป็นของขวัญที่เด็กหญิงไม่สามารถส่งได้\n\"ท่านหญิงอิริดอน ข้าขอขอบคุณอย่างแท้จริงสำหรับความช่วยเสริมและความห่วงใยต่อเนื่องของท่าน ข้าหวังว่าท่านจะยังคงยึดถือค่าของความยุติธรรมและความเมตตา นำลูโมโพลิสสู่อนาคตที่สว่างใส\"",
  str_item_3661220 = "ภาพเหมือนแม่ชีผู้บริสุทธิ์",
  str_item_intro_3661220 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nภาพเหมือนที่สร้างขึ้นตามรูปของพาโลม่าในวันที่เธอเป็นนักบวช ดูเหมือนว่าเป็นของขวัญที่พ่อไม่สามารถให้ได้\n\"แพม, ขอให้คุณมีความสง่างามและใจดีตลอดไป และขอให้ครอบครัวของเรามีความสุขตลอดไป\"",
  str_item_3751039 = "ความมุ่งมั่นแน่วแน่",
