  str_item_3751400 = "พูดอะไรน่ะ",
  str_item_intro_3751039 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ดีเนียร์, ไรน์ฮาร์ต... ไม่ว่าจะเกิดอะไรขึ้น ขอให้เราแต่ละคนพบเส้นทางของตัวเอง\"",
  str_item_intro_3751040 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ฉันไม่มีเจตนาหรือสนใจในการสร้างศัตรู - เขาเป็นแค่อุปสรรคในทางของฉัน\"",
  str_item_intro_3751041 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ผู้รู้เท่าทันอิลลูมิน่าสามารถเป็นใครก็ได้—คุณ, ฉัน, หรือใครก็ตาม—ตราบใดที่พวกเขานำทางออโรเรียนสู่ความท้าทาย\"",
  str_item_intro_3751398 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"โอ้ ท้องฟ้ายามค่ำคืน...มันเหมือนห้องสมุดที่ไม่มีที่สิ้นสุด ซึ่งเก็บความลับของโลกทั้งหมด\"",
  str_item_intro_3751399 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อาจจะมีวันหนึ่งที่ฉันสามารถใช้พลังนี้ที่โชคชะตามอบให้ฉันอย่างคล่องแคล่ว\"",
  str_item_intro_3751400 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"หืม?\"",
  str_item_3751552 = "หัวข้อต้องห้าม",
  str_item_intro_3751552 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ไม่ต้องมาเล่นตลกเรื่องไอศกรีมแท่งอีกละ!\"",
  str_item_3751553 = "ทวีตตี้สนุกสนาน",
  str_item_intro_3751553 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ใกล้ถึงวันหยุดแล้ว ฉันวางแผนการพักผ่อนเรียบร้อยแล้ว อยากรู้ว่าทวีตตี้วางแผนอะไรกันเหรอ?\"",
  str_item_3763034 = "ความประหลาดใจที่หวาน",
  str_item_intro_3763034 = "ปลดล็อกกรอบอวาตาร์ที่เกี่ยวข้อง\nซารย่ากังวลว่าความหนาวของเหนืออาจจะรุนแรงเกินไปสำหรับคุณ ดังนั้นเธอให้หมวกของเธอให้คุณ",
  str_item_3661215 = "โต๊ะเขียน",
  str_item_intro_3661215 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nโต๊ะเขียนที่มีรสนิยมดีทำจากไม้ ที่นำความสงบสุขมาให้ในขณะทำงาน",
  str_item_3661216 = "โต๊ะกาแฟขนาดเล็ก",
  str_item_intro_3661216 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโต๊ะกาแฟไม้ขนาดเล็ก ส่วนหนึ่งของพื้นผิวทำจากหินอ่อน ทำให้มีความสง่างาม",
  str_item_3661217 = "โต๊ะข้างนกฮูก",
  str_item_intro_3661217 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nนกฮูกนั่งอยู่บนโต๊ะขนาดเล็กนี้เหมือนกำลังมองไกลไปในทิศทาง",
  str_item_3661218 = "ไม้กวาดเวทมนตร์",
  str_item_intro_3661218 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nตำนานบางตัวกล่าวว่าหากคุณนั่งอยู่บนมัน มันจะบินสูงขึ้นไปในอากาศ สิ่งประดิษฐ์แบบนี้มาจากที่ไหนกันนะ?",
  str_item_5234055 = "เครื่องประดับเรือ",
  str_item_intro_5234055 = "เรือขนาดเล็กสีสดใสที่ยืนตั้งขึ้นและใช้เป็นของตกแต่ง แค่มองเห็นมันจริงๆ แล้วจะกระตุ้นความอยากล่องเรือไปยังแดนไกลหรือไม่?",
  str_item_3661052 = "หิ่งห้อยสั้นชั่ว",
  str_item_intro_3661052 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nมันสามารถลอยอยู่ในอากาศเท่านั้น และไม่สามารถเคลื่อนที่ไปรอบ ๆ ... งั้นมันมีไว้ทำอะไร? สำหรับแขวนของ? ราวจับมือ?",
  str_item_3000338 = "ซากโบราณ",
  str_item_intro_3000338 = "เศษส่วนของเครื่องมือโบราณที่กระจัดกระจายตัวทั่วที่ในหลายปีที่ผ่านมา หากมีใครยอมรับคุณค่าของสิ่งเหล่านี้ พวกเขาอาจยินดีจ่ายเงินค่าตอบแทนเพื่อเสนอซื้อชิ้นส่วนเหล่านี้",
  str_item_3751401 = "บาสเก็ตบอลของบร็อค",
  str_item_3751402 = "รองมือใหม่เทเบิลเทนนิส",
  str_item_3751403 = "อีสปอร์ต โปร กรอนรู",
  str_item_3751404 = "อาจารย์นักแม่นปืน ชารอน",
  str_item_intro_3751401 = "ปลดล็อคอวตารที่เกี่ยวข้อง ลองดูเลย์เอาต์สามขั้นตอนของฉันสิ! เย้! ทำไมมันต้องเด้งตรงจากหน้ากระดานด้วยล่ะ!",
  str_item_intro_3751402 = "ปลดล็อคอวตารที่เกี่ยวข้อง กีฬาคือชีวิต! แม้ว่าฉันจะเป็นมือใหม่ แต่ฉันก็จะทุ่มสุดตัวที่มีบนโต๊ะปิงปอง!",
  str_item_intro_3751403 = "ปลดล็อคอวตารที่เกี่ยวข้อง เมื่อพูดถึงการเล่นเกม ฉันจะไม่มีวันปล่อยให้ตัวเองถูกทิ้งไว้ข้างหลัง! แค่ดูฉันเป็นเจ้าของพวกมือใหม่ในการแข่งขัน Esports ครั้งใหญ่ครั้งต่อไป!",
  str_item_intro_3751404 = "ปลดล็อคอวตารที่เกี่ยวข้อง คุณไม่รู้เหรอ? ฉันก็แสดงได้อย่างงดงามเสมอในสนามยิงปืนเช่นกัน!",
  str_item_3440011 = "โลงศพแห่งแสง",
  str_item_intro_3440011 = "เปิดเพื่อรับหนึ่งในรายการต่อไปนี้แบบสุ่ม: ไนท์เทียม ×10,000, ไนท์เทียม ×5,000, แจสเปอร์ทั่วไป II ×2, แจสเปอร์ทั่วไป I ×3, ซับไลม์ ×100 หรือ ซับไลม์ ×50",
  str_item_3440012 = "กล่องแห่งเสน่ห์",
  str_item_intro_3440012 = "เปิดเพื่อรับไอเทมต่อไปนี้แบบสุ่ม: ไนท์เทียม ×5,000, ไนท์เทียม ×2,000, ไนท์เทียม ×1,000, แจสเปอร์ทั่วไป II ×1, แจสเปอร์ทั่วไป I ×2 หรือ ซับไลม์ ×30",
  str_item_3440013 = "โลงศพแห่งทะเล",
  str_item_intro_3440013 = "เปิดเพื่อรับสิ่งของต่อไปนี้แบบสุ่ม: ของขวัญไม่ทราบผู้ส่ง II ×1, กล่องออเดอร์ร่วมมือ III ×2, ไนท์เทียม ×20,000 หรือ แจสเปอร์ทั่วไป II ×4",
  str_item_3440019 = "โลงศพแห่งทะเล",
  str_item_intro_3440019 = "เปิดเพื่อรับสิ่งของต่อไปนี้แบบสุ่ม: ของขวัญไม่ทราบผู้ส่ง II ×1, กล่องออเดอร์ร่วมมือ III ×2, ไนท์เทียม ×20,000 หรือ แจสเปอร์ทั่วไป II ×4",
  str_item_3755036 = "อัศวินยุติธรรมอิริดอน",
  str_item_intro_3755036 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ฉันจะไม่ปล่อยให้หลักฐานใดหลุดพ้น!\"",
  str_item_3755037 = "ครัวของแพม",
  str_item_intro_3755037 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อาจดูไม่หรูหรา แต่เชื่อฉันเถอะ รสชาติมันยอดเยี่ยม!\"",
  str_item_6110001 = "แผงศิลป์ Stand By Me",
  str_item_intro_6110001 = "คณะกรรมการอนุสรณ์ Stand By Me.\nลวดลายบนกระดานนี้เรียกความคิดถึงผู้มาเยือนจากไกลที่ถูกพามาที่นี่ด้วยลมพัดจากทะเล พร้อมกับเสียงเพลงปิ่นของปี่ และเสียงกระดาษห้อย...",
  str_item_3661221 = "โมเดลรถไฟที่ระลึก",
  str_item_intro_3661221 = "ของขวัญสำหรับผู้ชมในงานเปิดฉายหนังของคารอน รถจักรยาน์ขนาดเล็กที่ยิ่งใหญ่นี้ รวมถึงการแสดงของนักแสดงดังที่น่าประทับใจ ทำให้ผู้ชมประทับใจมาก\n\"จำความรู้สึกนี้ไว้!\"",
  str_item_3000027 = "บัตรของขวัญหัวใจ",
  str_item_3000028 = "ลูกโป่งหัวใจ",
  str_item_intro_3000027 = "ใช้มันเพื่อโหวตให้ออโรเรียนที่คุณชอบในงานโหวตชุด\n\"ความหวงใยของฉันจะถูกส่งถึงพวกเขาหรือไม่?\"",
  str_item_intro_3000028 = "ใช้มันเพื่อโหวตชุดที่คุณชอบในงานโหวตชุดแต่งกาย\n\"กรุณาส่งให้ผู้รับอย่างระมัดระวัง มิฉะนั้นความรักของคุณอาจหายไปในท้องฟ้า\"",
  str_item_3661222 = "ภาพเหมือนสาวคลาริเนต",
  str_item_3661223 = "ภาพเสียงควีนน้ำ",
  str_item_intro_3661222 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nสินค้านี้เดิมทีผลิตเป็นกาน้ำชาพิเศษสำหรับร้านกาแฟ แต่ไม่ได้รับความนิยมเนื่องจากการออกแบบที่มีการปล่อยน้ำออกจากปาก\n\"อย่าใช้หน้าตาของฉันสำหรับสิ่งแบบนี้นะ!\"",
  str_item_intro_3661223 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nภาพเหมือนสวยงามของราชินีที่ถูกทำให้โปร่งเพื่อลดน้ำหนัก มีคนเสนอว่าอาจนำไปใช้เป็นภาชนะใส่น้ำมันฟลูโอโรโฟร่า แต่ราชินีปฏิเสธอย่างเข้มงวด\n\"อืม, ทำไม... มันต้องเกิดขึ้นกับฉันเสมอ...?\"",
  str_item_3661224 = "ล็อกเกอร์เวชภัณฑ์",
  str_item_3661225 = "เตียงป่วย",
  str_item_3661226 = "รถเข็น",
  str_item_3661227 = "แถวที่นั่ง",
  str_item_intro_3661224 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nตู้เก็บของไม้ที่มีขวดและกระปุกหลากหลายใส่อยู่ หวังว่าเซรั่มเหล่านี้จะช่วยบรรเทาความทุกข์ของผู้อื่น",
  str_item_intro_3661225 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nเตียงที่ทำขึ้นเพื่อผู้ป่วยเป็นพิเศษ หากคุณรู้สึกไม่สบาย มาพักผ่อนที่นี่",
  str_item_intro_3661226 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรถเข็นทางการแพทย์ที่เรียบง่าย มีความสำคัญมากแม้ว่าพื้นที่จำกัด",
  str_item_intro_3661227 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nแถวของที่นั่ง บางทีคุณอาจบรรเทาความวิตกกังวลของคุณโดยการคุยกับเพื่อนคู่ความสนุกที่นั่งรอบ ๆ คุณ",
  str_item_5234056 = "ลานบ้านอันสงบ",
  str_item_intro_5234056 = "สถานที่สวยงามสำหรับระบายความร้อนและพักผ่อน คุณสามารถมาที่นี่หากคุณรู้สึกว่ามีปัญหาอะไร",
  str_item_3000344 = "โหลคอลเลคชั่น",
  str_item_intro_3000344 = "ฉันต้องเก็บเพิ่มเท่าไหร่ถึงจะหยุดได้...?",
  str_item_3000345 = "บัตรสนุก",
  str_item_intro_3000345 = "คูปองสำหรับการจับฉลากที่ดูธรรมดาเหล่านี้ที่ทำโดยกิลด์อัมบราตันเป็นสกุลเงินที่กำหนดสำหรับเกมกล่องสุ่มความประหลาดใจ",
  str_item_3661228 = "ปูที่สร้างจากเตาหลอม",
  str_item_3661229 = "โมเดลเรือนำโชค",
  str_item_intro_3661228 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเดิมทีสร้างขึ้นโดยซวนจีเพื่อช่วยช่างฝีมือในการประกอบเครื่องกล ตัวอัตโนมัติหลงโจวนี้สูญเสียความสามารถในการเคลื่อนไหวหลังจากใช้งานหลายปี อย่างไรก็ตาม มันยังคงเป็นชิ้นตกแต่งที่โดดเด่นและน่าสนใจ",
  str_item_intro_3661229 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nบนเรือแห่งโชคลาภที่ชาวหลงโจวส่งออกสู่ทะเล มีความปรารถนาร่วมอยู่มากมาย เช่น เหรียญทองแดงและกระจกที่ติดอยู่ที่ข้อต่อ สร้างรูปแบบของดวงดาวเจ็ดดวงตามพระจันทร์ หมายความว่าโชคลาภและการเดินทางที่รุ่งเรือง ถึงแม้ว่าตัวนี้จะเป็นแค่โมเดลที่สร้างโดยซวนจี ก็ไม่ขาดรายละเอียดที่จำเป็นและความปรารถนาจากใจ",
  str_item_3763035 = "น้ำทิพย์รักษา",
  str_item_intro_3763035 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"ไม่ต้องกังวลครับ มันไม่ทำร้ายคุณหรอก...\"",
  str_item_3751554 = "อ่อนแอ",
  str_item_intro_3751554 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ขอโทษ, ขอโทษ... ฉัน... ฉันโอเค... แค่ต้องการพักผ่อนเล็กน้อย\"",
  str_item_3751555 = "ดวงใจของความกตัญญู",
  str_item_intro_3751555 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"วันนี้ฉันจ่ายนะ!\"",
  str_item_3751405 = "ผู้รักษาที่ใส่ใจ",
  str_item_intro_3751405 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"กรุณานั่งลง แล้วให้ฉันตรวจสอบดูนะครับ/ค่ะ\"",
  str_item_3751406 = "ความแข็งแกร่งเหนือกว่า",
  str_item_intro_3751406 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ฉันจะล่าใครก็ตามที่หาญที่จะยืมเงินคุณแล้วไม่จ่าย!\"",
  str_item_3751407 = "วัตถุโบราณทะเลลึก",
  str_item_intro_3751407 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\nสมบัติที่ถูกกลบซ่อนลึกในมหาสมุทร\nทนต่อการสึกหรอและการกัดกร่อนจากน้ำทะเลอยู่เสมอ หวังว่าวันหนึ่งจะกลับมาปรากฏตัวบนบก",
  str_item_3751408 = "คำเชิญของ Xuan Ji",
  str_item_intro_3751408 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ชาวเคเลสไทต์มีความเชื่อที่คล้ายคลึงกับคนในเผ่าพันธุ์ของฉัน คุณสนใจที่จะไปเยือนเยเพื่อแลกเปลี่ยนวัฒนธรรมกันหรือไม่?\"",
  str_item_3751556 = "กลไกทองแดงคอปเปอร์ฟอร์จ",
  str_item_intro_3751556 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"สร้างจากเครื่องจักรที่ไม่มีฟังก์ชันปฏิบัติการ หากคุณคิดว่ามันสวยงาม ก็คุ้มค่าที่จะครอบครอง\"",
  str_item_3751409 = "ฝนทองคำตก",
  str_item_intro_3751409 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"แม้ว่านี่จะไม่ถึง 1% ของความมั่งคั่งของฉัน แต่ก็ไม่มีเหตุผลที่จะปฏิเสธเงินฟรี\"",
  str_item_3751410 = "การสะท้านของเจ้าแห่งเงา",
  str_item_intro_3751410 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"เร็วๆ นี้จะถึงวันหยุดแล้ว ฉันควรพักผ่อนหน่อย\"",
  str_item_3751557 = "เช็กเมท",
  str_item_intro_3751557 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อย่าลังเล ทำให้ศัตรูตกใจและชนะ\"",
  str_item_3751558 = "เหรียญนำโชค",
  str_item_intro_3751558 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"เหรียญดวงนี้สำหรับคุณ ที่รับประกันว่าจะได้รับความโชคลาภในปีที่กำลังจะมา\"",
  str_item_3763036 = "งูหมอก",
  str_item_intro_3763036 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nงูควันที่คลุมเครือนี้จะกลืนกินทุกอย่างในที่สุด.",
  str_item_3751411 = "มาดื่มชากันสิ",
  str_item_intro_3751411 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ตอนนี้สามทุ่มแล้ว คุณอยากดื่มชาไหม?\"",
  str_item_3751559 = "ดอกซากุระบาน",
  str_item_intro_3751559 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"สีแปลกประหลาดถูกส่องลงบนใบหน้าของฮิอิโระ อาจจะเป็นเพราะสีของดอกซากุระที่บานเร็วในสถานที่ที่ห่างไกล\"",
  str_item_3751560 = "คร็อกเกตเก๋าเก๋",
  str_item_intro_3751560 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ปัญญาที่ทำให้ฉันอิ่ม ไม่ใช่อาหาร\"",
  str_item_3751412 = "ผู้บัญชาการฉลาด",
  str_item_intro_3751412 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ออโรเรียนเป็นศัตรูของตัวเอง\"",
  str_item_3763037 = "ของขวัญซากุระ",
  str_item_intro_3763037 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\nเส้นเลือดของตระกูลซากุระได้รับการคุ้มครองฮิอิโระอย่างเงียบ ๆ ในนามของสมาชิกในตระกูลที่เหลือ",
  str_item_3751561 = "ถูเสือ",
  str_item_3751562 = "ไม่เผ็ด",
  str_item_3751563 = "เบา",
  str_item_3751564 = "ปานกลาง",
  str_item_3751565 = "แอสตราเผ็ด",
  str_item_intro_3751561 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ใครจะทนต่อความอยากจะเอาหัวมาเช็ดกับเสือน้อยน่ารักที่มีพลังงานอร่อยแบบนี้ได้บ้าง?\"",
  str_item_intro_3751562 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ระดับความเผ็ดนี้ไม่ใช่อะไรสำหรับเรดีเซล เวรนช์เลย\"",
  str_item_intro_3751563 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ชาวเย ชอบอาหารเผ็ด แม้ว่ารสเผ็ดมากๆ จะเกินไปสำหรับดันตัง แต่เธอเป็นคนทำอาหารที่เก่งและเข้าใจความงดงามของรสชาตินี้\"",
  str_item_intro_3751564 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"คุณต้องรับประทานอาหารอย่างมีความสง่างามเสมอ! คาร์ลีนต้องเตือนตัวเองอยู่เสมอว่าเธอไม่สามารถลืมมารยาทการทานอาหารของอัศวินลูโม่เพียงเพราะความร้อนแรงในปากของเธอ.\"",
  str_item_intro_3751565 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"อ๊ากกกกกกกกก! อัสตราเผ็ด! นั่นคือสิ่งแรกที่นกสตาร์ลิงก์พูดหลังจากที่กินซอสพริก.\"",
