  str_item_9997046 = "คริสตัลสตัน",
  str_item_9997047 = "กล่องลูมินาวิเศษ",
  str_item_intro_9997004 = "เติมผ้าพันแผลในสนามรบหนึ่งชิ้นเมื่อเริ่มต้นการต่อสู้",
  str_item_intro_9997005 = "มอบโล่เท่ากับ 20% ของ HP สูงสุดที่คงอยู่เป็นเวลา 2 รอบเมื่อเริ่มต้นการต่อสู้",
  str_item_intro_9997008 = "ฟื้นฟู HP ให้เป็น 30% เมื่อเริ่มการต่อสู้หาก HP ปัจจุบันต่ำกว่า 30%",
  str_item_intro_9997009 = "สูญเสีย 7% ของ HP ปัจจุบันในตอนเริ่มของแต่ละรอบ หลังจากนั้นทำความเสียหายเท่ากับ 150% ของ ATK เฉลี่ยของทีมให้กับศัตรูภายใน 2 กลุ่มรอบ ๆ",
  str_item_intro_9997010 = "เพิ่มความเสียหายของสกิลใช้งานของ Aurorians 50% สูญเสีย 8% ของ HP ปัจจุบันทุกครั้งที่ใช้ Active Skill",
  str_item_intro_9997011 = "เพิ่มความเสียหายต่อเนื่องต่อเนื่องสูงสุด 40% ตามเปอร์เซ็นต์ของ HP ที่เสียไปโดยพันธมิตร",
  str_item_intro_9997012 = "เพิ่มความเสียหายของ Aurorian 20% เมื่อ HP ปัจจุบันสูงกว่า 70%",
  str_item_intro_9997013 = "เมื่อโจมตีศัตรู 3 ตัวหรือมากกว่าในเวลาเดียวกัน สามารถสร้างสายฟ้าที่โจมตีศัตรูทั้งหมด ทำความเสียหายเท่ากับ 100% ของค่า ATK เฉลี่ยของทีม",
  str_item_intro_9997014 = "สร้างกระเบื้องสี 1 แผ่นแบบสุ่มในสนามเมื่อเริ่มแต่ละรอบ",
  str_item_intro_9997015 = "เมื่อเคลียร์อย่างน้อย 15 ช่องพร้อมกันด้วยการแตะ 1 ครั้ง จะเพิ่มความเสียหายจากคอมโบต่อเนื่องของออโรเรียน 30% ไม่สามารถใช้คอมโบต่อเนื่องหากเคลียร์น้อยกว่า 8 ช่องพร้อมกัน",
  str_item_intro_9997016 = "ยิ่งอยู่ใกล้ศัตรูเท่าไหร่ ความเสียหายจากคอมโบต่อเนื่องของออโรเรียนก็ยิ่งสูงขึ้น สามารถเพิ่มได้ถึง 20%",
  str_item_intro_9997017 = "ยิ่งอยู่ห่างจากศัตรูมากเท่าไหร่ ความเสียหายจากคอมโบต่อเนื่องของออโรเรียนก็ยิ่งสูงขึ้น สามารถเพิ่มขึ้นสูงสุด 30%",
  str_item_intro_9997018 = "Detonator Aurorians มีโอกาส 30% ในการสาปคอมโบต่อเนื่องเพิ่ม 1 ครั้ง",
  str_item_intro_9997019 = "เพิ่มจำนวนเป้าหมายของคอมโบต่อเนื่องของออโรเรียนเดโทเนเตอร์ 1 คน",
  str_item_intro_9997020 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9997021 = "ในตอนเริ่มต้นการต่อสู้ ลดคูลดาวน์ Active Skill ของ Aurorians คอนเวอร์เตอร์ 1 รอบ",
  str_item_intro_9997023 = "เมื่อสกิลใช้งานหรือสกิลคอมโบต่อเนื่องที่ออโรเรียนใช้ทำดาเมจ มีโอกาส 30% ที่จะรักษาผลของพิษ/เผาไหม้/เลือดออกของเป้าหมายทันทีหนึ่งครั้ง",
  str_item_intro_9997024 = "ความเสียหายทั้งหมดที่ได้รับจากศัตรูที่ถูกดีบัฟหรือมีเอฟเฟกต์ดีบัฟเพิ่มขึ้น 20%",
  str_item_intro_9997025 = "ฆ่าศัตรูที่มี HP ต่ำกว่า 7%",
  str_item_intro_9997026 = "หลังจากแตะเพื่อนำไทล์ออก หากชาวออโรเรียนยังไม่ได้ใช้คอมโบต่อเนื่องในรอบนี้ ลดคูลดาวน์ของ Active Skill ของ Aurorian ทั้งหมด 1",
  str_item_intro_9997027 = "แปลงเปอร์เซ็นต์การรักษาส่วนเกินของ Aurorians ให้เป็น 1 สแต็กเกราะป้องกันที่คงอยู่เป็นเวลา 1 รอบ",
  str_item_intro_9997028 = "เมื่อศัตรูที่ติดพิษ/เผาไหม้/เลือดออกถูกควบคุม ทำให้ศัตรูอื่น ๆ แบบสุ่มในสนามรบติดพิษ 1 สแต็ก",
  str_item_intro_9997029 = "ลดจำนวนช่องที่ต้องถอนเพื่อเรียกใช้สกิลสนับสนุนฝ่ายลง 5 ช่อง",
  str_item_intro_9997030 = "เมื่อ Aurorian ใช้ Active Skill ลดคูลดาวน์ของ Active Skills ของ Aurorians ที่มีความสัมพันธ์กัน 1 รอบ",
  str_item_intro_9997031 = "ลดคูลดาวน์ของการใช้สกิลใช้งานครั้งแรกในการรบ 2 ครั้ง",
  str_item_intro_9997033 = "ตัวบ่งชี้จะปรากฏอย่างสุ่มในสนามรบในตอนต้นของแต่ละรอบ หลังจากทำลายตัวบ่งชี้นี้ ความเสียหายของ Chain Combo จะเพิ่มขึ้น 25% ในรอบนี้",
  str_item_intro_9997035 = "Aurorians สามารถกินเลือดได้ 2% เมื่อทำความเสียหาย และสูญเสีย 15% ของ HP ปัจจุบันในตอนเริ่มของทุกรอบ",
  str_item_intro_9997003 = "ฟื้นฟู 10% ของ Max HP หลังจากชนะการต่อสู้",
  str_item_intro_9997006 = "เพิ่ม Max HP 3% สำหรับออโรเรียนทั้งหมดหลังจากชนะการต่อสู้",
  str_item_intro_9997007 = "เพิ่ม DEF ของ Aurorians ทั้งหมด 1.5% หลังจากชนะการต่อสู้",
  str_item_intro_9997032 = "เพิ่ม ATK 1% ให้กับออโรเรียนทั้งหมดหลังจากชนะการต่อสู้",
  str_item_intro_9997022 = "เพิ่มจำนวนรอบทั้งหมด +10 เมื่อได้รับไอเทมนี้ ",
  str_item_intro_9997036 = "เมื่อแตะเพื่อนำไทล์ออก มีโอกาส 25% ที่จะเพิ่มจำนวนความพยายามในการนำออก 1 ครั้ง",
  str_item_intro_9997037 = "เมื่อแตะเพื่อลบช่อง สุ่มทำให้ศัตรูในระยะของช่องที่ถูกลบได้รับ 1 สแต็กของพิษ, เลือดออก หรือเผาไหม้",
  str_item_intro_9997038 = "เมื่อแตะเพื่อลบช่อง, ทำดาเมจเท่ากับ 120% ของค่า ATK เฉลี่ยของทีมให้กับศัตรูที่อยู่ในระยะของช่องที่ถูกลบ",
  str_item_intro_9997034 = "ศัตรูได้รับความเสียหายเท่ากับ 150% ของ ATK เฉลี่ยของทีม 1 ครั้งสำหรับทุกช่องที่พวกเขาเคลื่อนที่ภายในพื้นที่ของช่องที่ถูกแตะและจะถูกนำออกในรอบนี้",
  str_item_intro_9997039 = "ในตอนเริ่มต้นการต่อสู้ อุปกรณ์ Caelestite พิเศษแบบสุ่ม 1 ชิ้นสามารถใช้งานได้ครั้งเดียว",
  str_item_intro_9997040 = "รับ Special Caelestite Gear: แปลง 2 ช่องที่เลือกเป็นช่องสี สามารถใช้ได้หนึ่งครั้งสำหรับทุก 60 ช่องที่ถูกนำออก",
  str_item_intro_9997041 = "รับอุปกรณ์ Caelestite พิเศษ: เลือกพื้นที่ 3x3 และนำเอาชิ้นสีน้ำเงินทั้งหมดออกจากพื้นที่ สามารถใช้ได้ครั้งละ 1 สำหรับทุก 50 ชิ้นที่ถูกนำออก",
  str_item_intro_9997042 = "รับอุปกรณ์ Caelestite พิเศษ: เลือกพื้นที่ 3x3 และลบชิ้นสีแดงทั้งหมดภายใน สามารถใช้งานครั้งละ 1 สำหรับทุก 50 ชิ้นที่ถูกนำออก",
  str_item_intro_9997043 = "รับอุปกรณ์ Caelestite พิเศษ: เลือกพื้นที่ 3x3 และลบกระเบื้องสีเขียวทั้งหมดภายใน สามารถใช้งานครั้งละ 1 สำหรับทุก 50 กระเบื้องที่ถูกลบ",
  str_item_intro_9997044 = "รับอุปกรณ์ Caelestite พิเศษ: เลือกพื้นที่ 3x3 และนำเอาชิ้นสีเหลืองทั้งหมดออกจากพื้นที่ สามารถใช้ได้ครั้งละ 50 ชิ้นที่ถูกนำออก",
  str_item_intro_9997045 = "รับอุปกรณ์ Caelestite พิเศษ: รีเซ็ตทุกช่องในสนามรบ สามารถใช้ได้ครั้งละ 1 สำหรับทุก 80 ช่องที่ถูกเอาออก",
  str_item_intro_9997046 = "รับอุปกรณ์ Caelestite พิเศษ: เลือก 1 สีและรีเซ็ตชิ้นตัวเลือกทั้งหมดของสีนี้จากสนามรบ สามารถใช้ได้ครั้งละ 80 ชิ้นที่ถูกนำออก",
  str_item_intro_9997047 = "รับอุปกรณ์พิเศษ Caelestite: เลือก 1 กระเบื้องและนำออก 4 กระเบื้องที่ใกล้ที่สุดของสีเดียวกัน สามารถใช้ได้ครั้งละ 1 สำหรับทุก 60 กระเบื้องที่ถูกนำออก",
  str_item_rpintro_9997004 = "ตัวเสริมสำหรับโพชั่นฟื้นฟู ทำให้รักษาได้ดีขึ้น",
  str_item_rpintro_9997005 = "อาวุธยุคเก่าคลาสสิกที่สลักร่ายพรศักดิ์สิทธิ์ไว้ มีประสิทธิภาพเฉพาะเมื่อใช้กับศัตรูที่คล่องแคล่ว",
  str_item_rpintro_9997008 = "รูปปั้นที่ถูกอนุรักษ์อย่างสมบูรณ์ ที่ให้พลังรักษาแก่ผู้ถือมัน",
  str_item_rpintro_9997009 = "สิ่งของยุคเก่าที่ทั้งสาปแช่งผู้ใช้และให้พลังเท่าเทียมกันในการตอบแทน",
  str_item_rpintro_9997010 = "กล่าวกันว่าเป็นไอเทมลึกลับจากสงครามล้างโลกครั้งก่อน มันมีคำสาปรุนแรงพอที่จะทำให้ศัตรูบาดเจ็บสาหัสได้",
  str_item_rpintro_9997011 = "ใส่สิ่งนี้เพื่อเปลี่ยนความทุกข์เป็นความแข็งแกร่ง และในที่สุดคว้าชัยชนะ",
  str_item_rpintro_9997012 = "พกมันไว้และจะได้รับการคุ้มครองจากเทพีแห่งชัยชนะ ไร้พ่ายในทุกสนามต่อสู้",
  str_item_rpintro_9997013 = "ดาบเลื่องชื่อจากยุคเก่า ปลุกเสกด้วยพลังแห่งสายฟ้า ได้ยินเสียงฟ้าพิโรธชัดเจนเมื่อชักออกจากฝัก",
  str_item_rpintro_9997014 = "อัญมณีที่ส่องประกายทุกสี งดงามและเปลื่ยนแปลงอยู่ตลอด",
  str_item_rpintro_9997015 = "ดาบยุคเก่าที่ยิ่งใหญ่ เมื่อถือครอบครอง คุณจะสามารถรู้สึกพลังภายในตัวคุณเติบโต",
  str_item_rpintro_9997016 = "อาวุธยุคเก่าคลาสสิกที่สลักร่ายพรศักดิ์สิทธิ์ไว้ มีประสิทธิภาพเมื่อใช้กับศัตรูที่คล่องแคล่ว",
  str_item_rpintro_9997017 = "อาวุธยุคเก่าคลาสสิกที่สลักร่ายพรศักดิ์สิทธิ์ไว้ มีประสิทธิภาพเฉพาะเมื่อใช้กับศัตรูที่คล่องแคล่ว",
  str_item_rpintro_9997018 = "ดาบสั้นที่คบกริบ ตีขึ้นจากโลหะชั้นเลิศของยุคเก่า",
  str_item_rpintro_9997019 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_rpintro_9997020 = "สีทายุคเก่าที่ดูดซึมลูมินาได้",
  str_item_rpintro_9997021 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9997023 = "เรลิกจากยุคเก่า อาจต้องคำสาปที่รุนแรงมาก ผู้สวมใส่จะได้รับอันตรายจากพิษ",
  str_item_rpintro_9997024 = "ดาบที่เลื่องชื่อในยุคเก่า ผู้ใช้สามารถรับรู้ได้ถึงพลังมหาศาลเปรียบดั่งเทพเจ้า",
  str_item_rpintro_9997025 = "มันสามารถตรวจจับพลังชีวิตของศัตรูและปลิดชีวิตผู้ที่ใกล้จะสิ้นชีพเมื่อพกติดตัวไว้",
  str_item_rpintro_9997026 = "เข็มขัดที่สวมใส่แนบแน่น จะให้ลูมินาที่จำเป็นให้กับผู้สวมเมื่อถูกกระตุ้นภายใต้เงื่อนไขบางอย่าง",
  str_item_rpintro_9997027 = "อุปกรณ์ปริศนาจากยุคเก่าที่สามารถตรวจจับและแปลงลูมินาไปเป็นสนามพลังป้องกันผู้สวมใส่ได้",
  str_item_rpintro_9997028 = "กล่าวกันว่าคือไอเทมต้องสาปที่สร้างขึ้นโดยนักรบผู้ยิ่งใหญ่เพื่อนำมาซึ่งจุดจบของศัตรูทั้งหมด",
  str_item_rpintro_9997029 = "เครื่องรางจากยุคเก่าที่สามารถใช้รักษาลูมินาในระดับจุลภาคได้ ทำดาเมจรุนแรงกับศัตรู",
  str_item_rpintro_9997030 = "รายการยุคเก่าเพื่อสร้างลูมินาใหม่ให้กับออโรเรียนที่มีความสัมพันธ์กัน",
  str_item_rpintro_9997031 = "ใช้ไอเทมยุคเก่านี้เพื่อกู้คืนส่วนหนึ่งของลูมินาที่สูญหายอย่างรวดเร็ว",
  str_item_rpintro_9997033 = "อุปกรณ์สำหรับการเก็บและเติมลูมินา",
  str_item_rpintro_9997035 = "ดาบใบยักษ์ที่ให้สัมผัสอันน่าสะพรึงกลัว คาดว่าเคยใช้สำหรับการประลองถึงฆาตในอดีตกาล จะมีการนองเลือดเมื่อถูกนำมาใช้",
  str_item_rpintro_9997003 = "เทียนเปล่งแสงอบอุ่นที่สามารถรักษาออโรเรียนที่บาดเจ็บได้",
  str_item_rpintro_9997006 = "รูปปั้นที่สาบสูญของยุคเก่าที่ทำจากวัสดุคุณภาพสูง ทนทาน เบา และให้พรแก่ผู้ที่มีมันในครอบครอง",
  str_item_rpintro_9997007 = "โล่โบราณจากยุคเก่า เป็นทรงรีสมบูรณ์แบบและผสานกับพลังแห่งสุริยะเพื่อป้องกันทุกการโจมตีที่อันตราย",
  str_item_rpintro_9997032 = "ตราโบราณยุคเก่าที่มีโครงสร้างแสนลึกลับ ใช้ในการรักษาลูมินาในระดับจุลภาค เพิ่มทักษะการต่อสู้",
  str_item_rpintro_9997022 = "ถุงนอนที่สูญหายและถูกหลงลืม ช่วยฟื้นฟูพละกำลัง",
  str_item_rpintro_9997036 = "เป็นไปได้ว่าเขียนขึ้นโดยนักปราชญ์โบราณ โดยมีรายละเอียดของเอฟเฟกต์ชนะทางของธาตุต่าง ๆ พร้อมกับแนะนำกลยุทธ์ที่มีประสิทธิภาพ",
  str_item_rpintro_9997037 = "รูปภาพโบราณฝีมือศิลปินนิรนามที่พรรณาถึงความโหดร้ายของโรคระบาด ศิลปินคนดังกล่าวก็ตายด้วยโรคระบาด ทำให้รูปภาพนั้นมีพลังที่น่าสะพรึงกลัว",
  str_item_rpintro_9997038 = "อาวุธที่ดูเหมือนจะหลอมรวมกับลูมิน่าได้อย่างสมบูรณ์แบบ... หายากจริงๆ...",
  str_item_rpintro_9997034 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9997039 = "เหรียญโบราณปริศนาที่เพิ่มความเร็วให้ออโรเรียนผู้เป็นเจ้าของเป็นบางโอกาส ทำให้มีความคล่องตัวมากขึ้น",
  str_item_rpintro_9997040 = "กล้วยไม้สีแดงหายากที่ถูกพัฒนาขึ้นในยุคเก่า มันจะปรากฏ เบ่งบานและโรยราเป็นคู่ เหมือนกับว่ามันสร้างความผูกพันกับผู้สวมใส่และช่วยเหลือในการต่อสู้",
  str_item_rpintro_9997041 = "ดูเหมือนโคลอสซัสย่อส่วนจากยุคเก่าที่ช่วยเจ้าของในการต่อสู้",
  str_item_rpintro_9997042 = "ดูเหมือนโคลอสซัสย่อส่วนจากยุคเก่าที่ช่วยเจ้าของในการต่อสู้",
  str_item_rpintro_9997043 = "ดูเหมือนโคลอสซัสย่อส่วนจากยุคเก่าที่ช่วยเจ้าของในการต่อสู้",
  str_item_rpintro_9997044 = "ดูเหมือนโคลอสซัสย่อส่วนจากยุคเก่าที่ช่วยเจ้าของในการต่อสู้",
  str_item_rpintro_9997045 = "ไอเทมยุคเก่าที่สร้างความผูกพันลึกลับระหว่างนักสู้สองคน",
  str_item_rpintro_9997046 = "คริสตัลหยาบที่พื้นผิวแตกเล็กน้อยแสดงถึงพลังลูมินาที่เปี่ยมล้นภายใน แรงสัมผัสเพียงปลายนิ้วก็สามารถปลดปล่อยลูมินามหาศาลจนทำให้ศัตรูมึนงงได้",
  str_item_rpintro_9997047 = "เทคโนโลยียุคเก่า มันบรรจุลูมินาได้มากกว่าที่ขนาดของมันปรากฏให้เห็น",
  str_item_3000349 = "โทเค็น Cloudrover",
  str_item_intro_3000349 = "โทเค็นที่สามารถแลกเป็นสิทธิพิเศษจากกิลด์เหนือเมฆ ลูกค้าที่ภักดีเท่านั้นที่มีโอกาสได้รับสิ่งนี้",
  str_item_3000134 = "สตาร์แฟลร์พิเศษลาเคซิสที่ใจโลภ",
  str_item_intro_3000134 = "สามารถใช้เพื่อรับสมัครครั้งเดียวจากการรับสมัครเฉพาะปัจจุบัน\nรายการนี้จะหมดอายุ ดังนั้นโปรดใช้ก่อนที่จะสิ้นสุดการรับสมัครเฉพาะของ Avaricious Lachesis ปัจจุบัน มิฉะนั้นจะหายไป จะไม่เปลี่ยนเป็นรายการอื่นเมื่อหมดอายุ",
  str_item_3420133 = "ชุดการสรรหา 2.5 ปี",
  str_item_intro_3420133 = "เลือก Aurorian จากรายการ Aurorian 6 ดาวต่อไปนี้เพื่อต่อสู้เคียงข้างคุณ: <color=#ffffff>ดันตัง, ซาร์ยา, แอนโทนี, ลอเรเล่ย์, ซีนา, โจชัว, ชวาตส์: อัลไลตี้คลามอร์, ยิงเอล, เลโอ, ฮาติ, ทิน่า, เลน, เจเรียห์, มูยู่ไป, จงซู, วิค, แอกเซเลีย, ลิลิกา, มินอส, โพลลุกซ์, เจโน, เฟีย, คาร์ลีน: สมอลเดอริ่งโซล, นีน่า, บาร์ตัน: เดฟท์เบลดส์, ไจลส์, เลนอร์, แอเชอร์, เหยา, อาเมะโมริ, รินเนะ, ฟลอรีน, รูบี้, เชอวาน, โนวิโอ, เฮดี้, เบเธล, ลุค, พาโลม่า, แกรม, เรวี่, สโมกกี้, เฟลอร์, เบริล, ฮิอิโระ, ซินซา, อีฟ, อูริเอล, คาร์ลีน, ชาโรนา, ซาริเอล, ราฟาเอล, คอนนอลลี, คารอน, เอซี่, วิกตอเรีย, โจนา, นิคินิส, กาบริเอล, มิการ์ด, ไมเคิล, กรอนรู, อิริดอน, วราธ.</color>.หมายเหตุ: ชุดนี้จะหมดอายุเวลา 09:00 น. 28 กุมภาพันธ์ 2024 (UTC+0), 04:00 น. 28 กุมภาพันธ์ 2024 (UTC-5) รับตรงเวลา มิฉะนั้นจะถูกเปลี่ยนเป็น 3,000 Lumamber โดยอัตโนมัติและส่งถึงคุณทางกล่องจดหมายในเกม",
  str_item_3661231 = "ราชาบัลลังก์เงา",
  str_item_intro_3661231 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nกิลด์ Cloudrover ได้ทำเก้าอี้หนังแข็งที่หรูหราและเด่นชัดนี้ขึ้นมาเป็นพิเศษสำหรับอีสต์วาน ด้วยความที่เป็นสินค้าที่มีเทคนิคพิเศษ จึงไม่ขาดแคลนผู้ซื้อแม้ว่าราคาจะสูง",
  str_item_3661232 = "รุ่นเรือเหาะเหนือเมฆ",
  str_item_intro_3661232 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณ\nด้วยความนิยมของยานอากาศ Cloudrover ซึ่งเป็นจุดหมายที่รวมทุกอย่างที่คุณต้องการเช่นการท่องเที่ยว, ช้อปปิ้ง, สันทนาการ, และการพักผ่อน ไม่แปลกใจที่จะมีโมเดลของยานอากาศนี้ให้ลูกค้าซื้อในขนาดต่าง ๆ แม้ว่าโมเดลนี้จะไม่ใหญ่ที่สุด แต่มันถูกทำด้วยการทำงานที่ละเอียดที่สุด",
  str_item_3661233 = "แสงเฉลิมฉลอง",
  str_item_intro_3661233 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nส่องสว่างในพื้นที่ที่มืดด้วยแถวของไฟสีเหล่านี้ หวังว่าแสงสว่างจากไฟที่สว่างอ่อน ๆ นี้จะให้ความอบอุ่นให้คุณในวันที่ควรจะฉลองนี้",
  str_item_3661234 = "กล่องของขวัญคาร์นิวัล",
  str_item_intro_3661234 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nออโรเรียนได้มอบของขวัญนี้ให้คุณด้วยความคิดค้น แม้ว่ามันจะไม่มีค่ามาก แต่คุณค่าที่แท้จริงของมันอยู่ที่ความพยายามและความทุ่มเทที่มันแทนที่ ขอให้ของขวัญนี้นำโชคดีมาให้คุณในปีที่จะถึง",
  str_item_5234057 = "รถเข็นน้ำแข็ง",
  str_item_intro_5234057 = "รถม้าประดิษฐ์ทำจากน้ำแข็ง ลักษณะที่เป็นคริสตัลทำให้ดูสบายตาและผ่อนคลายอย่างมาก",
  str_item_3661236 = "ภาพเหมือนนักดาบที่เปลี่ยนชุด",
  str_item_3661237 = "ภาพเหมือนนักดาบนักพายเรือ",
  str_item_3661241 = "แฟนของบูล",
  str_item_3661242 = "โคมไฟต้นไม้",
  str_item_intro_3661236 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nงานฝีมือของช่างฝีมือคนหนึ่ง ตุ๊กตานี้สามารถเปลี่ยนชุดอื่น ๆ แบบสุ่มได้เร็วทันทีเมื่อกดปุ่ม ว่ากันว่าตุ๊กตานี้ได้รับแ inspiration จากศิลปะการแสดงแบบหนึ่งของหลงโจว\n\"ถ้าฉันต้องการที่จะรับบทเป็นคนจากหลงโจว... ฉันจำเป็นต้องเรียนรู้วิธีเปลี่ยนชุดในทันทีเหมือนนี้หรือไม่?\"",
  str_item_intro_3661237 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nเพื่อระลึกถึงความสำเร็จในการทำงานร่วมกับนักดาบ ช่างฝีมือได้สร้างภาพเหมือนจากท่าทางของนักดาบเมื่อทำภารกิจเสร็จสิ้น\n\"คุณต้องการที่ว่างที่อีกฝั่งของเรือ? แน่นอน แค่บอกฉันเมื่อคุณต้องการเพิ่มใครสักคนที่นั่น\"",
  str_item_intro_3661241 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nพัดลมนี้ใช้เฉพาะในห้องปฏิบัติการของนักวิทยาศาสตร์อิลลูมินา ขาของมันสามารถงอได้ยืดหยุ่นหรือแนบไว้บนพื้นผิว บางคนกล่าวว่าพัดลมนี้ได้รับแ inspiration จากหุ่นยนต์ที่ชื่อว่า Bool.",
  str_item_intro_3661242 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nโคมไฟที่ออกแบบอย่างประณีต ที่ให้แสงที่พืชต้องการเพื่อการเจริญเติบโต และสร้างบรรยากาศที่อบอุ่นและเป็นธรรมชาติภายในห้อง",
  str_item_3000352 = "ขนเคเลสไทต์",
  str_item_intro_3000352 = "ขนที่มีลักษณะเฉพาะที่น่าตื่นตาตื่นใจนี้ถูกกล่าวว่ามีค่ามากสำหรับชาวเคเลสไทต์",
  str_item_3661243 = "โซฟาเป็นทรงซูโม่",
  str_item_3661244 = "งานศิลปะปีใหม่: มังกร",
  str_item_3661238 = "ตกแต่งไฟเย็น",
  str_item_3661239 = "จี้ปีใหม่",
  str_item_3661240 = "ชั้นวางแสนดี",
  str_item_intro_3661243 = "รายการเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณ\nโซฟาขี้เกียจทรงขนมจีบ พร้อมกล่องเสียงที่เคยมีเสียงร้องเพลง:\n\"ขนมจีบ มีขนมจีบมากมาย!\"\n\"มาทำขนมจีบด้วยกันทุกคน!\"\nตอนนี้ อุปกรณ์เสียงได้ถูกถอดออกโดยออโรเรียนที่เบื่อเสียงรบกวน ซึ่งคืนความสงบสุขให้กับยานโคลอสซัสอีกครั้ง",
  str_item_intro_3661244 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nภาพวาดปีใหม่ของ \"หญิงสาวมังกร\" ซึ่งเป็นสิ่งของเทศกาลที่นิยมในราชวงศ์จิ แต่ \"ภาพเหมือน\" ที่ได้รับจากเฉินนี่นี้เป็นภาพเดียวที่วาดภาพลักษณ์ของหญิงสาวมังกรได้ถูกต้อง.",
  str_item_intro_3661238 = "รายการเฟอร์นิเจอร์. สามารถวางไว้ในห้องบน Colossus ของคุณ\nเมื่อเทศกาลดั้งเดิมของหลงโจวใกล้เข้ามา เพื่อให้เพื่อน ๆ หลงโจวบน Colossus รู้สึกถึงบรรยากาศเฉลิมฉลอง ทุกคนบน Colossus จึงแขวนตกแต่งประดับไฟระเบิดที่ทำร่วมกัน หวังว่าจะสามารถขจัดความไม่โชคดีและเชิญโชคดีมายังบ้าน",
  str_item_intro_3661239 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nในปัจจุบันเป็นสินค้าขายดีที่อ่าว Twin Pavilions มันเป็นของตกแต่งจากหลงโจวที่ต้องมีในช่วงเวลาเฉลิมฉลอง ซึ่งเป็นสัญลักษณ์ของความหวังในอนาคตที่สดใส",
  str_item_intro_3661240 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nที่วางของที่ทำจากไม้นี้ถูกสร้างขึ้นโดยช่างฝีมือจากอ่าว Twin Pavilions มีลายสลักที่ซับซ้อนและออกแบบมาเพื่อทั้งการเก็บของและการชื่นชม ทำให้ห้องในยานโคลอสซัสมีความสง่างามแบบคลาสสิก",
  str_item_intro_3763039 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"ดอกพีชบานอ่อนโยนและงดงาม ส่งเสริมความงามที่สดใส และโชคลาภมาถึง ในการกอดที่สดใสของพวกเขา.\"",
  str_item_intro_3751417 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"แคลิสไทท์ได้รับหมวกพิเศษเป็นของขวัญปีใหม่และยินดีที่จะใส่มัน!\"",
  str_item_intro_3751566 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"เชนนี่มอบพระคุณ ให้ความมั่งคั่งและความรุ่งเรือง!\"\nสาวมังกรที่ได้รับความเคารพเป็นเทพเจ้าแห่งทะเลจะสามารถมอบความสุขให้กับโลกธรรมดาได้หรือไม่? เชนนี่อาจจะไม่รู้ แต่เธอตั้งใจที่จะลอง!",
  str_item_intro_3751567 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"รสชาติของฉันคือมาตรฐาน!\"\nในฐานะผู้สื่อข่าวของอัสตรา, ผู้นำทางมีประสบการณ์มากในการชิมอาหาร โดยมีรสชาติที่ละเอียดอ่อน",
  str_item_intro_3763038 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"สะสมการ์ดฤดูใบไม้ผลิทั้งหมดเพื่อเรียกมังกรศักดิ์สิทธิ์!\"\nไม่แน่ใจว่ามันจริงหรือไม่ แต่การเก็บสะสมการ์ดนี้ทำให้ปีใหม่ของ Longzhou สนุกขึ้นเยอะเลย.",
  str_item_intro_3751413 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ฉันมีรายการที่ยาวนานของสิ่งที่ฉันต้องการดู - เกราะยักษ์ที่ถูกกลั่นกรองบน Azurite, การแสดงที่เต็มไปด้วยเสียงดังในทะเลทราย, การต่อสู้อย่างรุนแรงใต้ดิน...\"\nแม้แต่เทพเจ้ายังมีความปรารถนามากมายสำหรับปีใหม่.",
  str_item_intro_3751414 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nระวังสัตว์ประจำปีที่อัมบราตัน สัตว์กินคนที่มีเขายาว! ลองดู \"ศาลาวัดที่ถูกห้าม\" ภาพยนตร์สยองขวัญล่าสุดของแอลลีย์วูด ฉายในฤดูใบไม้ผลินี้!\n\"เอาล่ะ... บทของฉันคืออะไรนะ...?\"",
  str_item_intro_3751415 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"นี่ค่ะ, แค่สิ่งเล็กๆ ที่ฉันทำขึ้นมา... ฉันสามารถทำสิ่งอื่นๆ นอกจากไอศกรีมแท่งได้นะ!\"\nสิ่งเดียวที่ซาร์ยาทำสำเร็จหลังจากล้มเหลวอย่างไม่รู้จบ, พร้อมความหวานเพิ่มเติมเพื่อแสดงความรู้สึกของเธอ.",
  str_item_intro_3751416 = "ปลดล็อกรูปประจำตัวแบบเดียวกัน\nหวังว่าการพบกันในวันนี้จะทำให้คุณรู้สึกถึงความอบอุ่นและแข็งแรง ไม่ว่าเราจะอยู่ที่ไหน ท้องฟ้าข้างบนยังคงเดิม",
  str_item_intro_3751568 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"แม้ว่าจะมีหลายคนที่แสดงความชอบฉัน แต่ฉันคิดว่าผู้นำทางนั้นเป็นคนพิเศษที่สุด เรามีความสัมพันธ์ที่แท้จริงจากใจ!\"",
  str_item_intro_3751569 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ทำหัวใจด้วยมือ จริงหรอ?... โอเค รับท่านี้ของฉันและขอบคุณ... แต่อย่ายินดีเกินไปนะ!\"",
  str_item_3763039 = "ดอกไม้แห่งโชคชะตา",
  str_item_3751417 = "เคเลสไทต์พร้อมหมวกมังกร",
  str_item_3751566 = "หญิงสาวมังกรลองโจวในปีมังกร",
  str_item_3751567 = "ทูตนักกิน",
  str_item_3763038 = "มังกรทะยานแห่งฤดูใบไม้ผลิ",
  str_item_3751413 = "คำอธิษฐานปีใหม่",
