  str_item_3751419 = "ครบรอบพันคืน",
  str_item_3751570 = "ลิมโบที่ลุกไหม้",
  str_item_3763040 = "เพลิงสุดท้าย",
  str_item_3751421 = "หัวใจพันวัน",
  str_item_3751422 = "ลูกศรรักษ์รัก",
  str_item_intro_3751421 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ผู้นำทาง, ทางนี้!\"\nความรักได้เป็นเพื่อนที่คอยสนับสนุนคุณในการเดินทางนี้มาเป็นระยะเวลาพันวัน ด้วยพรจากทุกคน ขอให้คุณสามารถทำต่อไป!",
  str_item_intro_3751422 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"จับตาขณะนี้; วันนี้อาจเป็นจุดเปลี่ยนแปลงของชะตากรรมของเรา!\"",
  str_item_intro_3763041 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"ผู้ที่มั่นคงจะได้รับความรุ่งโรจน์!\"\nขอบคุณสำหรับคำแนะนำและการปกป้องตลอดหนึ่งพันวันของความมั่นคงและความเป็นเพื่อน รอคอยการผจญภัยในอนาคตด้วยกัน.",
  str_item_intro_3751420 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"คุณก็อยากเข้าร่วมการทดลองพิเศษในวันมูนคราวน์หรือไม่?\"",
  str_item_intro_3751419 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\nผู้นำทาง, ขอบคุณที่คอยคอยอยู่กับฉันมาพันวันใต้ท้องฟ้านี้ โปรดดำเนินการแนะนำฉันในอนาคตต่อไป!",
  str_item_intro_3751570 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"คุณต้องการอยู่ในลิมโบกับฉันหรือไม่? จับมือฉันเถอะ แล้วปล่อยให้ความหวังของเราสว่างสดใส!\"",
  str_item_intro_3763040 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"ชุดของฉันจะลุกเป็นไฟเมื่อยาหมดอายุ คุณจะตามรอยไฟที่เหลือมาหาฉันไหม?\"",
  str_item_3751042 = "ข้อความจากนักท่องเที่ยว",
  str_item_3751043 = "ผลของการฝึกฝน",
  str_item_3751044 = "สัจธรรมยืนยง",
  str_item_3751045 = "ผู้พิทักษ์ในการเดินทาง",
  str_item_3751046 = "คนรักปาร์ตี้น้ำชา",
  str_item_3751047 = "เนื้อเรื่องของฉัน",
  str_item_3751048 = "พี่น้องร่วมรบ",
