  str_item_intro_3751428 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"อ๊ะ, ขอโทษที่ทำให้คุณเห็นฉันอย่างนี้ คราวหน้าฉันจะรักษาสติไว้ให้ดี\"",
  str_item_intro_3751575 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"ออกเดินทางสู่การผจญภัยใหม่!\"",
  str_item_intro_3751576 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"การใช้เวลาฤดูร้อนกับเพื่อน ๆ นี่แหละที่ดีที่สุด!\"",
  str_item_intro_3751587 = "ปลดล็อกรูปประจำตัวที่เกี่ยวข้อง\n\"เนื่องจากความดื้อรั้นนี้สามารถชนะแผ่นดินได้ การเผชิญหน้ากับทะเลไม่ควรจะเป็นปัญหา... ใช่ไหม?\"",
  str_item_intro_3751588 = "ปลดล็อกอวาตาร์ที่เกี่ยวข้อง\n\"บีบ-บีบ, กำลังเปิดโหมดนำทางทางน้ำ...\"",
  str_item_intro_3763044 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"ทุกคนที่อาบแสงนี้จะรู้สึกว่าหัวใจของพวกเขากำลังสว่างขึ้น\"",
  str_item_intro_3763045 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"การมาถึงอัสตราเป็นอุบัติเหตุที่ทำให้ตกใจที่สุดในฤดูร้อนนี้!\"",
  str_item_intro_3763051 = "ปลดล็อกกรอบรูปประจำตัวที่เกี่ยวข้อง\n\"วงยางว่ายน้ำที่ทันสมัยที่ทำให้คนอยากไปทะเลเมื่อมองเห็นครั้งแรก อย่าพลาดฤดูร้อนที่ผ่านไปเร็วๆนี้—ดำเนินการอย่างรวดเร็วและใช้มันเพื่อกอดรับฤดูกาล!\"",
  str_item_3661248 = "รูปปั้นฮีโร่โบราณ",
  str_item_3661249 = "รูปปั้นเจ้าหน้าที่โบราณ",
  str_item_intro_3661248 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nปรากฏการณ์เก่าแก่ที่ถูกค้นพบเมื่อเร็ว ๆ นี้และถูกระบุว่าเป็นนักรบพลเรือนที่ได้รับเกียรติในยุคที่ผ่านมาตามชุดและหมวกของมัน นักโบราณคดีทำหมายว่าเฉพาะขุนนางเท่านั้นที่มีสิทธิ์สั่งสร้างรูปปั้นของพวกเขาในยุคนั้น ซึ่งหมายความว่าเขาต้องได้รับความสำเร็จที่น่าทึ่งมากจนคนทั่วไปสร้างรูปปั้นนี้เพื่อชื่นชม\n\"ฉันจะปกป้องโลกที่เธอรัก!\"",
  str_item_intro_3661249 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nประวัติศาสตร์โบราณที่ถูกค้นพบเมื่อเร็ว ๆ นี้และถูกระบุว่าเป็นเจ้าหน้าที่ระดับสูงในกองทัพจากการแต่งกายและหมวกที่สวม นักโบราณคดีทำหมายว่าเจ้าหน้าที่ทางทหารในยุคนั้นๆ มาจากชนชั้นสูงเกือบทั้งหมด ดังนั้น ไม่เหมือนกับรูปปั้นของนักรบพลเรือน รูปปั้นนี้น่าจะมาจากมือของศิลปินที่ทุ่มเทให้บริการชนชั้นสูง\n\"ทิ้งส่วนที่เหลือให้ฉัน; ฉันจะดูแลมัน\"",
  str_item_3661250 = "รูปปั้นหมาป่าหิมะ",
  str_item_3661251 = "เชิงเทียนสน",
  str_item_3661252 = "ชั้นหนังสือของโรบิน",
  str_item_3661253 = "สเตอริโอสำหรับคอลเลคเตอร์",
  str_item_3661254 = "โต๊ะต่ำสำหรับพักผ่อน",
  str_item_intro_3661250 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nรูปปั้นที่ได้รับความรักจากชาวนอร์ธแลนด์ ซึ่งถูกสร้างขึ้นเพื่อเป็นเครื่องแสดงถึงความยินดีต่อเพื่อนร่วมทีมที่สูญเสียไปในการต่อสู้ โดยถูกออกแบบมาจากการ์ดของนอร์ธแลนด์",
  str_item_intro_3661251 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nทำจากไม้สนที่ดีที่สุด ตัวเชิงเทียนที่มีบรรยากาศนี้ปล่อยกลิ่นสนอ่อนๆ ช่วยในการผ่อนคลายและการนอนหลับ",
  str_item_intro_3661252 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nชั้นหนังสือที่มีรูปทรงเรียบง่ายทำจากไม้คุณภาพสูง มันปล่อยกลิ่นหอมอ่อนๆ",
  str_item_intro_3661253 = "รายการเฟอร์นิเจอร์ สามารถวางไว้ในห้องบน Colossus ของคุณ\nสเตอริโอที่มีความสง่างามเหมาะสำหรับงานที่เป็นทางการ สีของเสียงของมันเหมาะสมกับขบวนเดินเป็นพิธีมากกว่าเพลงเฮฟวี่เมทัลที่แอนเซียชื่นชอบ",
  str_item_intro_3661254 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nโต๊ะที่ทันสมัยและเป็นมิตรกับงบประมาณ ที่สมบูรณ์แบบสำหรับช่วงเวลาว่างของผู้อยู่ในเมือง ขายดีทุกที่",
  str_item_3661256 = "นาฬิกาวินเทจ",
  str_item_3661257 = "ภาพวาดตกแต่งยามค่ำคืนที่สดใส",
  str_item_3661258 = "ตุ๊กตาแฮร์ฮาวด์",
  str_item_3661260 = "เรดีเซลกริลล์",
  str_item_intro_3661256 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nโครงเหล็กของนาฬิกานี้ถูกประดิษฐ์อย่างมีรสนิยม และหน้าปัดได้รับการปรับปรุงเฉพาะเพื่อให้มีเงาทองแดงเมื่อผ่านเวลา",
  str_item_intro_3661257 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nภาพวาดตกแต่งที่สวยงามของดวงจันทร์ตั้งอยู่บนท้องฟ้าในเวลากลางคืน จากศูนย์กลางของภาพวาด มันปล่อยแสงอ่อนๆและอบอุ่น",
  str_item_intro_3661258 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nตุ๊กตาทรงบีเกิ้ล ดวงตาของมันดูเหมือนกำลังบอกว่า \"ฉันเห็นมัน ฉันต้องการมัน และฉันต้องได้มัน!\"",
  str_item_intro_3661260 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณ\nเป็นเตาย่างที่พบได้บ่อยที่สุดในค่ายของเรดีเซล เวรนช์ ถึงแม้จะสร้างขึ้นจากเศษๆ เหล็ก แต่เตาย่างนี้สามารถให้รสชาติที่หอมกรอบและน่าทานแก่อาหาร - หรืออย่างน้อยเรดีเซล เวรนช์ก็คิดอย่างนั้น",
  str_item_3661265 = "ภาพเหมือนนักท่องเที่ยวที่มีความสง่างาม",
  str_item_3661266 = "รูปปั้นแคร์รอตที่น่าขนลุก",
  str_item_intro_3661265 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nตำนานพูดถึงนักเดินทางที่สร้างเมือง Folta ที่หวานหอมในแดนที่มีนมและน้ำผึ้งไหลไม่รู้จบ...\n\"เมืองนี้อยู่ที่ไหนนะ? หรือว่า... อยู่ในโลกที่แตกต่างอย่างสิ้นเชิง?\"",
  str_item_intro_3661266 = "รายการเฟอร์นิเจอร์. สามารถวางในห้องบนยักษ์ใหญ่ของคุณ\nสำหรับเด็ก ๆ ที่ไม่ชอบการทานแครอท ตาสีเขียวที่ส่องสว่างและหนวดที่คมขึ้นนั้นน่ากลัวกว่า Eclipsite ใด ๆ ...\n\"โป... แต่ฉันคือโปโป้ แครอทน้อยที่ยากจน...\"",
  str_item_3661267 = "เกมอาร์เคดย้อนหลัง",
  str_item_intro_3661267 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\n\"ถ้าฉันจะอยู่บนยานโคลอสซัส ฉันต้องนำสิ่งนี้มาด้วย... ไม่งั้นฉันจะไม่รอด.\"\nเมื่อได้รับคำขอแบบนี้ นักเร่งทางยินดีที่จะเสี่ยงเจ็บกล้ามเนื้อเพื่อรองรับเพื่อนของเขา",
  str_item_3661268 = "ของตกแต่งกำแพงแว่นกันแดดพิกเซล",
  str_item_intro_3661268 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\n\"คุณแพ้แล้ว อิงเกล ทิ้งของรางวัลไว้\"\nรางวัลที่ได้มาอย่างยากลำบากหลังจากที่เอาชนะอิงเกล ดูเหมือนจะเป็นสินค้าจากเกม",
  str_item_3661271 = "กล่องเก็บตุ๊กตา",
  str_item_intro_3661271 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nสำหรับผู้สะสมตุ๊กตาผ้าที่มักจะทำหายของของตัวเอง นี่อาจจะเป็นการประดิษฐ์ที่ยอดเยี่ยมที่สุดในโลก",
  str_item_3661272 = "นาฬิกาเท้าแมว",
  str_item_intro_3661272 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nนาฬิกาแขวนที่น่ารักยิ่งนักในรูปร่างของพวงมาลัยแมว มันเป็นเรื่องน่าเสียดายที่ต้องแขวนสิ่งที่นุ่มนวลมากขนาดนี้บนผนัง",
  str_item_3661273 = "พื้นที่เวทีนักศึกษาปีหนึ่ง",
  str_item_intro_3661273 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nขณะนี้มีข่าวลือที่กระจายไปทั่วอิลลูมินา: นักเรียนใหม่ที่ตะโกนความฝันของตนจากบนโถงจะกลายเป็นฮีโร่ที่ได้รับความเคารพในวันหนึ่ง ๆ",
  str_item_3661274 = "เตาผิงเหล็กหล่อ",
  str_item_intro_3661274 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเตาไฟทำจากเหล็กหล่อที่ผลิตในสหพันธรัฐอิลลูมินา นอกจากความสามารถในการทำความร้อนที่น่านับถือแล้ว ลักษณะที่เก่าแก่และเปลวไฟที่อบอุ่นยังเพิ่มความน่ารักและอบอุ่นให้กับทุกห้อง",
  str_item_3661275 = "แมทของเอนไลต์เทนเมนต์",
  str_item_intro_3661275 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเตียงหรูหราจากเมืองวารากิ สบายและอบอุ่น มีลักษณะที่เป็นคลาสสิกอย่างเด่นชัด ผู้ศึกษาของทรู ออเดอร์มองว่ามันเป็นเตียงที่เปิดเผยความสุกฤดูขัตติยา.",
  str_item_3661276 = "กระจกของวันพรุ่งนี้",
  str_item_intro_3661276 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\n\"ผู้ที่แสวงหาความจริงจะมองเข้าไปในกระจกไม้โบราณนี้และเห็นภาพของสิ่งที่ยังจะมาถึง\" จริง ๆ แล้ว ใครคิดเรื่องนี้ขึ้นมานะ...?",
  str_item_3661277 = "ภาพเหมือนทหารผู้กล้าหาญ",
  str_item_intro_3661277 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเสียงดังที่แทบท่วมท้นจากการโจมตีของอิคลิพไซท์ ทำให้สัญญาณจากแตรสั่งโจมตีหายไป แต่เมื่อทหารหนึ่งที่กล้าหาญยกธงและเดินหน้า พันธ์มนุษย์ที่เป็นพันธ์มนุษย์ตามมาอย่างใกล้ชิด\n\"อุทิศให้กับผู้กล้าที่ไม่กลัวตายและสู้ตายเพื่อชีวิตของพวกเขา\"",
  str_item_3661278 = "รูปปั้นของกระดิ่งวันสิ้นโลก",
  str_item_intro_3661278 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nรูปปั้นที่น่ารังเกียจและน่ากลัว ลักษณะที่เลวร้ายทำให้คนคิดว่ามันถูกสร้างขึ้นมาเพื่อเป็นศัตรูของโลก\nมีคำกล่าวว่าเมื่อมันเดินหน้าไป ชุดเกราะเหล็กที่มันสวมใส่จะส่งเสียงดังเบา ๆ — เป็นเพลงเรเควียมที่เต็มไปด้วยความเกลียดชังของกระด bells งหัวเวลาพระอาทิตย์ตก",
  str_item_3661262 = "รุ่นผู้พิทักษ์ซากโบราณ",
  str_item_intro_3661262 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nแบบจำลองที่เฟลอร์สร้างขึ้น ที่เธอคิดถึงผู้พิทักษ์ของซากปรักษาอยู่เสมอ\n\"มันอาจถือว่าเป็นชนิดหนึ่งของเมคา!\"",
  str_item_3661263 = "หม้อหลอมเล่นแร่แปรธาตุ",
  str_item_intro_3661263 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nด้วยสิ่งนี้ อาเตลเยของริซ่าบนยานโคลอสซัสสามารถเปิดทำการได้ที่สุด!",
  str_item_3661264 = "ภาพทรงจำแห่งการผจญภัย",
  str_item_intro_3661264 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเมื่อฤดูร้อนนี้จบลง มารำลึกถึงความทรงจำด้วยกัน!",
  str_item_3661279 = "หมวกลมฤดูร้อน",
  str_item_intro_3661279 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nเมื่อวางมือทั้งสองข้างลงบนมัน คุณจะรู้สึกถึงลมทะเลที่ละมุนละไม่ ซึ่งจับจดได้ถึงจิตอาสาของทะเลในฤดูร้อน นี่คือชิ้นเฟอร์นิเจอร์ที่จำเป็นสำหรับผู้ที่หลงใหลในการเดินเรือ",
  str_item_3661280 = "ห่วงยางสายลมฤดูร้อน",
  str_item_intro_3661280 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nออกแบบด้วยสีสันคลาสสิกและโครงสร้างที่แข็งแรง ไม่ว่าจะวางในบ้านหรือใช้ที่ทะเล มันก็เป็นที่ชื่นชมอยู่เสมอ",
  str_item_3661281 = "แบนเนอร์ลมฤดูร้อน",
  str_item_intro_3661281 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nธงตกแต่งที่เรียบง่ายแต่สง่างาม ที่เหมาะสำหรับทุกพื้นที่ที่ต้องการบรรยากาศทางทะเล",
  str_item_3661282 = "หอยสังข์ผู้ดูแลนกทะเล",
  str_item_intro_3661282 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\n\"หอยสังข์ใหญ่, ตู้ตู้ตู้. นกนางนวลได้ยินแล้วตกจากท้องฟ้า.\"\nไม่แน่ใจว่ามาจากที่ไหน แต่เพลงนี้ได้กระจายตัวในยานโคลอสซัส",
  str_item_3661283 = "บลาสเตอร์ฟองสบู่แสนสดชื่น",
  str_item_intro_3661283 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nปืนฟองสบู่ที่ติดอยู่บนฐาน ดูเหมือนว่าจะพ่นฟองสบู่เมื่อกดเพียงครั้งเดียว\n\"เครื่องประดับที่เรียบง่ายจริง ๆ! หวังว่ามันจะไม่ทำให้ทุกคนหลับ\"",
  str_item_3661284 = "ภาพเหมือนนาร์ซิสซัสสีขาว",
  str_item_intro_3661284 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nนิคินิสชอบปลูกดอกนาร์ซิสสุด ๆ  เธอใส่ใจกับต้นไม้ของเธอมาก และจะขว้างใครที่ทับทิบพวกมันลงในทะเลสะท้อน",
  str_item_3661285 = "ภาพเหมือนลิลลี่บริสุทธิ์",
  str_item_intro_3661285 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nเนโปลิสชอบปลูกดอกลิลลี่ นางมักจะเก็บดอกไม้เหล่านี้เพื่อให้เป็นของขวัญ ทิ้งเฉพาะกลิ่นหอมที่หวานหวานอยู่เฉย ๆ",
  str_item_3661286 = "รัศมีดาวจรัสแสง",
  str_item_intro_3661286 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสของคุณได้\nภาพวาดของมิทรา - รอยยิ้มชั่วขณะของอคิลลีส\nดวงดาวที่ไม่ยอมท้อ ขอให้คุณและเพื่อนร่วมทางของคุณส่องสว่างอีกครั้ง",
  str_item_3661287 = "ดาบคู่",
  str_item_intro_3661287 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nของจำลองของอาวุธที่ใช้โดยกัปตันและรองกัปตันของ Silent Hunter\nดูสิ! นี่คือจุดสูงสุดของการเป็นผู้บุกเบิกและความมุ่งมั่นในการปกป้อง! นั่นคือสิ่งที่ Silent Hunters ทั้งหมดเป็นอยู่",
  str_item_3661288 = "แผงควบคุมนักล่า",
  str_item_intro_3661288 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nที่นั่งที่มิธราตั้งขึ้นสำหรับสัตว์นักล่า\nพวกมันอาจดูเหมือนเป็นสิ่งที่ไม่เป็นอันตรายเมื่ออยู่บนนั่น แต่หนังเล็บของพวกมันนั้นไม่ใช่เรื่องตลกเลย",
  str_item_3661289 = "สตาร์บาวนด์ ยูนิตี้",
  str_item_intro_3661289 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องต่าง ๆ บนยานโคลอสซัสได้\nชิ้นงานเก่าที่ได้รับการซ่อมแซม\nหากดวงดาวที่ลาดเฉียบข้ามท้องฟ้าสามารถหาที่อยู่ที่เขาเป็นของตัวเองในความอ่อนโยนของเวลาได้...\nเมย์ คุณได้รับความสุขที่มาช้า",
  str_item_3661290 = "ทำนองแห่งแสงจันทร์",
  str_item_intro_3661290 = "ไอเทมเฟอร์นิเจอร์ สามารถวางในห้องบนยานโคลอสซัสของคุณได้\nเพลงจากลูดวีส, ชาว Caelestite\nมันบริสุทธิ์และงดงามเหมือนแสงจันทร์ พร้อมกับความเศร้าที่ไม่สามารถสั่นสะเทือนได้ เมย์ คุณได้รับความสุขที่มาช้า",
