  str_item_9998074 = "บลาสเตอร์",
  str_item_9998075 = "Caltrops ที่สว่างทับทิม",
  str_item_9998076 = "สีรับแสง",
  str_item_intro_9998002 = "เมื่อเริ่มต้นแต่ละรอบ สุ่มให้สถานะพิษ, การเลือดออก, หรือการเผาไหม้ 1 สแต็กให้กับศัตรูทั้งหมดในสนาม; ผลกระทบจะซ้ำกัน 4 ครั้ง ลดความเสียหายที่ Aurorians ทำให้ลง 15%",
  str_item_intro_9998003 = "ความเสียหายทั้งหมดที่ได้รับจากศัตรูที่ถูกดีบัฟหรือมีเอฟเฟกต์ดีบัฟเพิ่มขึ้น 20%",
  str_item_intro_9998004 = "เมื่อเอาช่องออก สุ่มทำให้ศัตรูในระยะของช่องที่ถูกเอาออกได้รับสถานะพิษ, เลือดออก หรือเผาไหม้ 1 สแต็ก; ผลกระทบนี้จะเกิดซ้ำ 5 ครั้ง",
  str_item_intro_9998005 = "เมื่อศัตรูที่ติดพิษ/เผาไหม้/เลือดออกถูกเอาชนะ จะสร้างพิษ 1 แต้ม, เลือดออก และเผาไหม้แก่ศัตรูที่ยังคงอยู่ทั้งหมดในสนาม",
  str_item_intro_9998006 = "เพิ่มความเสียหายที่ศัตรูได้รับจากพิษ, เลือดออก, หรือเผาไหม้ขึ้น 100%",
  str_item_intro_9998007 = "เมื่อสำเร็จในการทำให้ศัตรูติดพิษ, เผาไหม้, หรือเลือดออก, เป้าหมายจะสูญเสีย 1% ของ HP ปัจจุบันทันที",
  str_item_intro_9998008 = "มอบอุปกรณ์พิเศษ Caelestite: ใช้เวลา 2 รอบเพื่อใช้ทักษะสนับสนุนฝ่าย Lv.2 ทันที สามารถใช้ได้เพียงครั้งละ 1 รอบ",
  str_item_intro_9998009 = "ยิ่งอยู่ใกล้กับศัตรู ความเสียหายจากคอมโบต่อเนื่องของออโรเรียนจะยิ่งสูงขึ้น สูงสุดถึง 30%",
  str_item_intro_9998010 = "มอบโอกาส 30% ให้ Detonator Aurorians สามารถใช้ Chain Combo เพิ่มเติม; สำหรับแต่ละแผ่นที่ถูกนำออกในรอบนี้ โอกาสในการทำงานจะเพิ่มขึ้น 1%",
  str_item_intro_9998011 = "กัปตันจะต่อสู้โดยอาศัยธาตุของตนเองเท่านั้น โดยสร้างดาเมจเพิ่มขึ้น 100%",
  str_item_intro_9998012 = "เมื่อหัวหน้าทีมใช้คอมโบต่อเนื่อง จะสร้างเงาที่ตำแหน่งที่กำลังจะถูกลบออก และปล่อยคอมโบต่อเนื่องในเวลาเดียวกัน",
  str_item_intro_9998013 = "หลังจากชัยชนะครั้งถัดไป จะได้รับโอกาสเพิ่มเติม 2 ครั้งในการเลือก Enlightenment Gear ในการต่อสู้ครั้งถัดไป มีผลครั้งเดียว",
  str_item_intro_9998014 = "มอบโอกาสในการสับเปลี่ยนเมื่อเลือกอุปกรณ์ Enlightenment สามารถใช้ได้ 8 ครั้ง",
  str_item_intro_9998015 = "ลบอุปกรณ์ Caelestite พิเศษเริ่มต้นและให้โอกาส 2 ครั้งทันทีสำหรับการเลือกอุปกรณ์ Enlightenment",
  str_item_intro_9998016 = "เมื่อออโรเรียนโจมตีศัตรู 3 รายหรือมากกว่าด้วยสกิลใช้งานในเวลาเดียวกัน จะสร้างสายฟ้าที่โจมตีศัตรูทั้งหมด ทำความเสียหายเท่ากับ 200% ของ ATK เฉลี่ยของทีม",
  str_item_intro_9998017 = "หลังจากเปลี่ยนกัปตัน คูลดาวน์สกิลเรียกใช้ของกัปตันคนใหม่จะลดลง 1 รอบ Aurorian เดียวกันสามารถเรียกใช้ได้สูงสุดเพียงครั้งเดียวต่อรอบ",
  str_item_intro_9998018 = "ทำให้ทีมเป็นอมตะในรอบที่ 1 เมื่อ HP ของทีมลดลงเหลือ 1% แล้วฟื้นฟู 20% ของ Max HP ผลกระทบนี้สามารถเกิดขึ้นได้เพียงครั้งเดียวในการต่อสู้ สูงสุดทั้งหมด 2 ครั้ง",
  str_item_intro_9998019 = "คืนค่า 35% ของ HP ที่ทีมสูญเสียหลังจากชนะการต่อสู้",
  str_item_intro_9998020 = "เติมผ้าพันแผลบนสนามในช่วงเริ่มต้นการต่อสู้",
  str_item_intro_9998021 = "เพิ่มความเสียหายของ Aurorians 15% เมื่อ HP ปัจจุบันของทีมสูงกว่า 90%",
  str_item_intro_9998022 = "ให้โล่เท่ากับ 40% ของ HP สูงสุดที่คงอยู่เป็นเวลา 2 รอบเมื่อเริ่มทุกเวฟ",
  str_item_intro_9998023 = "ถ้า HP ปัจจุบันต่ำกว่า 50% จะฟื้นฟู HP สู่ 50% ที่จุดเริ่มต้นของการต่อสู้",
  str_item_intro_9998024 = "ผู้สนับสนุน Aurorians +40% ผลการฟื้นฟูจากคอมโบต่อเนื่องและสกิลที่ใช้งานในการต่อสู้",
  str_item_intro_9998025 = "สำหรับแต่ละองค์ประกอบหลักของ Aurorians ในทีม จะเพิ่มความเสียหายที่ Aurorians สร้างขึ้น 6% ด้วยการเพิ่มสูงสุด 24%",
  str_item_intro_9998026 = "เมื่อ Aurorians ทำความเสียหาย จะไม่สนใจเอฟเฟกต์การลดความเสียหายจากการถูกธาตุตอบโต้ เมื่อรับความเสียหาย จะไม่สนใจโบนัสจากการมีธาตุตอบโต้ของพวกเขา",
  str_item_intro_9998027 = "ธาตุรองของ Aurorian จะสร้างความเสียหายด้วยตัวคูณเดียวกันกับธาตุหลักของพวกเขา",
  str_item_intro_9998028 = "ทำให้ Aurorians ที่มีความผูกพันสามารถเพิกเฉยต่อธาตุของช่องที่จะถูกลบออกเมื่อร่ายคอมโบต่อเนื่อง",
  str_item_intro_9998029 = "สำหรับแต่ละชุดของ Aurorians ที่มีความผูกพัน จะฟื้นฟู 5% ของ HP สูงสุดของทีมในตอนเริ่มแต่ละรอบ",
  str_item_intro_9998030 = "สำหรับแต่ละชุดของ Aurorians ที่มีความผูกพัน มีโอกาส 40% ที่จะได้รับค่าชาร์จเพิ่มเติม 1 ครั้งสำหรับอุปกรณ์ Caelestite พิเศษเมื่อลบแผ่น ถ้ามีชุดความผูกพันหลายชุด จะทำงานอย่างอิสระ",
  str_item_intro_9998031 = "Aurorians ที่มีความผูกพันกันสืบทอด 20% ของ Basic ATK จากกันและกัน",
  str_item_intro_9998032 = "เมื่อ Aurorian ใช้สกิลใช้งาน จะลดเวลาคูลดาวน์สกิลใช้งานของออโรเรียนที่มีการผูกมัด 1 รอบ สามารถเรียกใช้ได้สูงสุด 5 ครั้งต่อการต่อสู้",
  str_item_intro_9998033 = "ลดเวลาคูลดาวน์ของการใช้สกิลใช้งานครั้งแรกในแต่ละการรบ 2 รอบทันทีหลังจากใช้สกิล",
  str_item_intro_9998034 = "หลังจากแตะเพื่อนำไทล์ออก หากชาวออโรเรียนยังไม่ได้ใช้คอมโบต่อเนื่องในรอบนี้ ลดคูลดาวน์ของ Active Skill ของ Aurorian ทั้งหมด 1",
  str_item_intro_9998035 = "ยิ่งออโรเรียนอยู่ไกลจากศัตรู ดาเมจจากคอมโบต่อเนื่องของพวกเขาก็ยิ่งสูงขึ้น สามารถเพิ่มได้สูงสุดถึง 50%",
  str_item_intro_9998036 = "เพิ่มจำนวนเป้าหมายของคอมโบต่อเนื่องของ Sniper Aurorians อีก 2 คน",
  str_item_intro_9998037 = "Aurorians ได้รับ Life Drain 3% เมื่อทำความเสียหายและสูญเสีย 10% ของ HP ปัจจุบันที่เริ่มต้นของแต่ละรอบ",
  str_item_intro_9998038 = "ยิ่ง HP ปัจจุบันต่ำลง ความเสียหายจาก Chain Combo ของ Aurorian ก็ยิ่งสูงขึ้น สูงสุดเพิ่มขึ้น 50%",
  str_item_intro_9998039 = "พันธมิตรและศัตรูทั้งหมดสูญเสีย 7% ของ HP ปัจจุบันเมื่อเริ่มแต่ละรอบ",
  str_item_intro_9998040 = "เมื่อ HP ปัจจุบันของ Aurorian อยู่ที่ 50%, จะเพิ่มความเสียหายที่ Aurorian ทำให้ขึ้น 30%; สำหรับแต่ละ 1% ของความแตกต่าง HP, การเพิ่มพลังนี้จะลดลง 5%",
  str_item_intro_9998041 = "สูญเสีย 7% ของ HP ปัจจุบันในตอนเริ่มของแต่ละรอบ หลังจากนั้นทำความเสียหายเท่ากับ 150% ของ ATK เฉลี่ยของทีมให้กับศัตรูภายใน 2 กลุ่มรอบ ๆ",
  str_item_intro_9998042 = "ในตอนเริ่มต้นการต่อสู้, สูญเสีย 70% ของ HP ปัจจุบันและทำดาเมจต่อศัตรูทั้งหมดเท่ากับ 300% ของความสูญเสียนี้",
  str_item_intro_9998043 = "เพิ่มความเสียหายจาก Active Skill ของ Aurorians ถึง 80% สูญเสีย 8% ของ HP ปัจจุบันทุกครั้งที่ใช้ Active Skill",
  str_item_intro_9998044 = "ละเว้นจำนวนช่องที่แตะและนำออก และให้ออโรเรียนสามารถใช้คอมโบต่อเนื่องระดับสูงสุดของพวกเขาในแต่ละครั้งหลังจากการนำออก",
  str_item_intro_9998045 = "ในตอนต้นของการต่อสู้ ได้รับโอกาสใช้งาน 1 ครั้งสำหรับอุปกรณ์ Caelestite พิเศษทั้งหมด",
  str_item_intro_9998046 = "การใช้งาน Special Caelestite Gear แต่ละครั้งจะทำให้สกิลสนับสนุนฝ่าย Lv.1 ทำงานครั้งหนึ่ง; มีผล 2 ครั้งต่อการต่อสู้",
  str_item_intro_9998047 = "ขยายระยะทางที่มีผลของ Special Caelestite Gear ตั้งแต่เริ่มต้นเป็น 5×5; ได้รับโอกาสใช้งาน 1 ครั้งหลังจากสะสมพลังงาน 40 แต้ม",
  str_item_intro_9998048 = "เพิ่มประสิทธิภาพการเติมเต็มของโอกาสการใช้งาน Special Caelestite Gear ขึ้น 50%",
