  str_item_intro_9998050 = "เพิ่มความเสียหายที่ออโรเรียนทำให้ขึ้น 20%; การใช้รอบเพิ่มเป็นสองเท่า",
  str_item_intro_9998051 = "ลด DEF ของ Aurorians ทั้งหมดในทีมเป็นศูนย์ และเปลี่ยน 50% ของ DEF พื้นฐานของพวกเขาเป็น ATK",
  str_item_intro_9998052 = "เพิ่ม Max HP ของ Aurorians ทั้งหมด 2% สำหรับแต่ละชิ้นของ Enlightenment Gear ที่ครอบครอง",
  str_item_intro_9998053 = "เพิ่ม DEF ของออโรเรียนทั้งหมด 1.5% สำหรับแต่ละชิ้นของ Enlightenment Gear ที่ครอบครอง",
  str_item_intro_9998054 = "เพิ่ม ATK 1% สำหรับออโรเรียนทั้งหมดสำหรับแต่ละชิ้นของอุปกรณ์สติปัญญาที่ครอบครอง",
  str_item_intro_9998055 = "ดักเพิ่มดาเมจจะปรากฏขึ้นอย่างสุ่มในสนามรบในตอนเริ่มแต่ละรอบ หลังจากทำลายดักนี้ ดาเมจของ Chain Combo จะเพิ่มขึ้น 35% ในรอบนี้",
  str_item_intro_9998056 = "ที่เริ่มต้นของแต่ละคลื่น จะมี Energy Candy Jar ปรากฏขึ้นอย่างสุ่มบนสนามรบ ซึ่งจะมอบโอกาสใช้งาน 1 ครั้งสำหรับอุปกรณ์ Caelestite พิเศษแบบสุ่มเมื่อถูกทำลาย",
  str_item_intro_9998057 = "เพิ่มจำนวนของทั้งหมดที่สามารถนำออกได้ในสนามรบเป็น 2 ตัวเมื่อเกิด",
  str_item_intro_9998058 = "เมื่อเริ่มต้นแต่ละระลอก, เครื่องจ่ายพลังงานเคลื่อนที่จะสุ่มปรากฏในสนามรบ ซึ่งจะมอบรอบเพิ่มเติม 3 รอบเมื่อถูกนำออก",
  str_item_intro_9998059 = "ในตอนเริ่มของแต่ละรอบ ทำลายช่องที่อยู่ด้านล่าง ทำให้ความเสียหายที่ Aurorians ทำให้เพิ่มขึ้น 15%",
  str_item_intro_9998060 = "รีเซ็ตจำนวนความสามารถของอุปกรณ์ Enlightenment ทั้งหมดกลับสู่สถานะเริ่มต้น",
  str_item_intro_9998061 = "มอบอุปกรณ์ Caelestite พิเศษ: แปลงทุกแผ่นกระเบื้องบนสนามเป็นกระเบื้องสี มาพร้อมกับโอกาสใช้งาน 2 ครั้งเมื่อได้รับ",
  str_item_intro_9998062 = "เพิ่มความเสียหายจาก Chain Combo ต่อศัตรูภายในระยะของแผ่นที่ถูกนำออก 35%",
  str_item_intro_9998063 = "เมื่อแตะเพื่อลบไทล์ จะทำความเสียหายเท่ากับ 150% ของ ATK เฉลี่ยของทีมต่อศัตรูที่อยู่ในระยะของไทล์ที่ถูกลบ",
  str_item_intro_9998064 = "เมื่อแตะเพื่อลบไทล์ จะได้รับโล่เท่ากับ 0.5% ของ HP สูงสุดสำหรับแต่ละไทล์ที่ถูกลบ คงอยู่เป็นเวลา 1 รอบ",
  str_item_intro_9998065 = "เมื่อลบอย่างน้อย 15 ช่องพร้อมกันด้วยการแตะเพียงครั้งเดียว จะเพิ่มความเสียหายจากคอมโบต่อเนื่องของออโรเรียน 30% คอมโบต่อเนื่องไม่สามารถใช้งานได้หากลบน้อยกว่า 7 ช่องพร้อมกัน",
  str_item_intro_9998066 = "เพิ่ม Basic ATK ของออโรเรียนที่มี ATK ต่ำที่สุดในทีมขึ้น 60%",
  str_item_intro_9998067 = "ลดจำนวนกระเบื้องที่จำเป็นในการเรียกใช้ทักษะสนับสนุนฝ่าย: ลด 5 สำหรับทักษะสนับสนุนฝ่ายระดับ 1; ลด 10 สำหรับทักษะสนับสนุนฝ่ายระดับ 2.",
  str_item_intro_9998068 = "เปิดใช้งานสกิลสนับสนุนฝ่ายเพื่อผลักศัตรูถอยหลังไป 1 ช่อง",
  str_item_intro_9998069 = "ในตอนเริ่มของแต่ละรอบ สำหรับ Aurorian ทุกคนในทีมที่อยู่ในฝ่ายเดียวกับฝ่ายสนับสนุนทักษะ ทุก Special Caelestite Gear จะได้รับการชาร์จ 3 ครั้ง",
