  str_item_intro_9011001 = "เมื่อเริ่มรอบ ทำดาเมจคงที่ 4,444 ให้กับศัตรูทั้งหมด และสังหารศัตรูที่มี HP น้อยกว่า 6%",
  str_item_intro_9011002 = "สร้างช่องหลากสีในพื้นที่รอบ ๆ ในทุกรอบ ด้วยปริมาณเท่ากับจำนวนประเภทขององค์ประกอบหลักของ Aurorians ในทีม ทักษะนี้จะถูกดำเนินการเพิ่มอีก 2 ครั้งในตอนต้นของการต่อสู้",
  str_item_intro_9011003 = "แปลงทุกกระเบื้องเป็นกระเบื้องสีในรอบที่สามของการต่อสู้ หลังจากการเชื่อมต่อกระเบื้องสิ้นสุด ทุกกระเบื้องสีจะถูกลบทิ้ง",
  str_item_intro_9011004 = "เพิ่มความเสียหายที่ Aurorians ทำให้เมื่อ HP เท่ากับค่าสูงสุดของพวกเขา 15%",
  str_item_intro_9011005 = "หลังจากที่เสร็จสิ้นเวที Dream Devourer ได้รับดอกเบี้ยเท่ากับ 30% ของจำนวน Dream Coin ที่คุณมีอยู่ในปัจจุบัน",
  str_item_intro_9011006 = "ใช้ได้ครั้งเดียว: ได้รับระเบิดฝัน 2 ลูก",
  str_item_intro_9011007 = "ยิ่งคุณมีเหรียญดรีมเพียงพอ ดาเมจจากการโจมตีปกติของคุณยิ่งสูงขึ้น",
  str_item_intro_9011008 = "ไทล์แรกในแถวอาจมีสีที่แตกต่างจากไทล์ที่ตามมา ทำให้ออโรเรียนทั้งสองประเภทสามารถเข้าร่วมการต่อสู้ได้",
  str_item_intro_9011009 = "สุ่ม Dream Orbs ทั้งหมดที่ไม่ได้ติดตั้งใหม่ (ไม่ต่ำกว่าระดับเดิม) และแต่ละ Dream Orb มีโอกาส 30% ที่จะเพิ่มเรตติ้ง",
  str_item_intro_9011010 = "เมื่อสีของช่องที่เชื่อมต่อตรงกับธาตุของกัปตัน ดรีมออร์บจะได้รับการชาร์จ 1 ครั้งสำหรับทุก 2 ช่องที่เชื่อมต่อ",
  str_item_intro_9011011 = "เมื่อสกิล Dream Orb ทำความเสียหาย จะทำการคำนวณสุ่มภายในช่วงที่กำหนด และเลือกค่าที่สูงกว่าเป็นความเสียหายที่ทำออกมา ทำให้ช่วงของความเสียหายแปรผันเพิ่มขึ้น 10%",
  str_item_intro_9011012 = "ตั้งค่าคะแนนของ Dream Orbs ที่ได้รับในภายหลังเป็น 1 ดาวเป็นค่าเริ่มต้น",
  str_item_intro_9011013 = "เมื่อเลือก Dream Divination Card จะลดตัวเลือกที่มีอยู่ลง 1 แต่จะเพิ่มผลรางวัลจากการ์ดเป็นสองเท่า",
  str_item_intro_9011014 = "ลด Max HP ของ Aurorians ทั้งหมด 20% หลังจากเข้าสู่การต่อสู้ แต่เพิ่มจำนวนการ์ด Dream Divination ที่สามารถเลือกได้ +1 ในระหว่างการดำเนินการ",
  str_item_intro_9011015 = "ก่อนการเชื่อมต่อแผ่นกระเบื้อง, เมื่อใดก็ตามที่ Aurorian เคลื่อนที่, ทำให้เกิดความเสียหายในพื้นที่ทรงเพชรที่จุดที่ลง, โดยเฉลี่ย 150% ของ ATK ของพวกเขา นอกจากนี้ Dream Orb ยังได้รับ 1 ค่าชาร์จสำหรับแต่ละวงรอบของการเคลื่อนที่",
  str_item_intro_9011016 = "เมื่อคอมโบต่อเนื่องของออโรเรียนประเภท Converter และ Supporter ทำความเสียหาย จะสุ่มทำให้เกิดสถานะ Poisoned, Bleeding, หรือ Burning 1 สแต็กให้กับเป้าหมาย",
  str_item_intro_9011017 = "เมื่อทำดาเมจใส่ศัตรูที่ติดพิษ, เลือดออก หรือเผาไหม้ จะเพิ่มความเสียหายสำหรับแต่ละผลกระทบ",
  str_item_intro_9011018 = "หลังจากทำให้เป้าหมายติดสถานะพิษ, เลือดออก หรือเผาไหม้ 1 สแต็ก มีโอกาสที่จะทำให้เกิดสถานะเลวร้ายแบบสุ่มเพิ่มอีก 1 สแต็ก ผลของการกระทำนี้สามารถเกิดซ้ำได้ โดยความน่าจะเป็นจะลดลงครึ่งหนึ่งทุกครั้งที่เกิดขึ้น",
  str_item_intro_9011019 = "เมื่อศัตรูตาย จะสุ่มให้สถานะพิษ, เลือดออก หรือเผาไหม้ 1 สแต็กแก่ศัตรูทั้งหมด",
  str_item_intro_9011020 = "เมื่อโจมตีปกติ กัปตันจะทำดาเมจเพิ่มเติมด้วยธาตุไฟเท่ากับ 50% ของ ATK รวมของทีม",
  str_item_intro_9011021 = "เมื่อเริ่มการโจมตีปกติ กัปตันจะทำดาเมจแบบธันเดอร์เพิ่มเติมเท่ากับ 50% ของ ATK รวมของทีม",
  str_item_intro_9011022 = "เมื่อเริ่มการโจมตีปกติ กัปตันจะทำความเสียหายเพิ่มเติมจากธาตุป่าเท่ากับ 50% ของ ATK รวมของทีม",
  str_item_intro_9011023 = "เมื่อเริ่มการโจมตีปกติ กัปตันจะทำความเสียหายเพิ่มเติมจากธาตุน้ำเท่ากับ 50% ของ ATK รวมของทีม",
  str_item_intro_9011024 = "เมื่อเริ่มแต่ละรอบ แปลงกระเบื้องสีแดงที่ใกล้ที่สุด 3 แผ่นเป็นกระเบื้องสี",
  str_item_intro_9011025 = "เมื่อเริ่มแต่ละรอบ แปลงกระเบื้องสีเหลืองที่ใกล้ที่สุด 3 แผ่นเป็นกระเบื้องสี",
  str_item_intro_9011026 = "เมื่อเริ่มแต่ละรอบ แปลงกระเบื้องสีเขียวที่ใกล้ที่สุด 3 แผ่นเป็นกระเบื้องสี",
  str_item_intro_9011027 = "เมื่อเริ่มแต่ละรอบ แปลงกระเบื้องสีน้ำเงินที่ใกล้ที่สุด 3 แผ่นเป็นกระเบื้องสี",
  str_item_intro_9011028 = "เมื่อเริ่มแต่ละรอบ แปลงไทล์สูงสุด 1 แผ่นภายใต้แต่ละศัตรูเป็นไทล์สี",
  str_item_intro_9011029 = "เมื่อได้รับความเสียหาย จะแปลงกระเบื้อง 3 แผ่นภายใน 2 คลัสเตอร์โดยรอบเป็นกระเบื้องสี",
  str_item_intro_9011030 = "ที่เริ่มต้นของแต่ละรอบ, ออโรเรียนที่มี HP ต่ำกว่าจะฟื้นฟูตามสัดส่วนของ HP ที่สูญเสียไป",
  str_item_intro_9011031 = "หลังจากชนะในการต่อสู้ ออโรเรียนทั้งหมดจะฟื้นฟู 20% ของ HP ของพวกเขา",
  str_item_intro_9011032 = "ถ้าได้รับช่องสีมืดในรอบปัจจุบัน จะได้รับ 1 สแต็กของ Battle Spirit",
  str_item_intro_9011033 = "ออโรเรียนผู้สนับสนุนจะได้รับ 1 ชั้นของ Battle Spirit เมื่อใช้สกิลใช้งานหรือคอมโบต่อเนื่องเพื่อฟื้นฟู HP ของทีม",
  str_item_intro_9011034 = "เมื่อสกิลใช้งานของออโรเรียนทำให้ศัตรูถูกดันกลับหรือดึงมา จะได้รับสแต็ค Battle Spirit ตามจำนวนเป้าหมายที่ได้รับผลกระทบ ผลกระทบนี้สามารถเกิดขึ้นได้สูงสุด 3 ครั้งต่อรอบ",
  str_item_intro_9011035 = "ได้รับตราจิตสู้ 1 สแต็กเมื่อมอนสเตอร์ติดสถานะพิษ, เลือดออก หรือเผาไหม้ ผลกระทบนี้สามารถเรียกใช้ได้สูงสุด 4 ครั้งต่อรอบ",
  str_item_intro_9011036 = "ได้รับเหรียญดรีมเท่ากับ 4 เท่าของระดับทุกครั้งที่ระดับดรีมเพิ่มขึ้น",
  str_item_intro_9011037 = "ได้รับเหรียญดรีมเท่ากับ 7 เท่าของการเพิ่มขึ้นเมื่อดอกเบี้ยดรีมเพิ่มขึ้น",
  str_item_intro_9011038 = "ได้รับ 4 Dream Coins สำหรับแต่ละ Eclipsite ที่ถูกเอาชนะในการต่อสู้",
  str_item_intro_9011039 = "ใช้งานครั้งเดียว: จับไพ่ทำนายดวงชะตาจากสำรับของคุณ 5 ใบ และได้รับดอกเบี้ยความฝันเท่ากับผลรวมของขั้นตอนทั้งหมด",
  str_item_intro_9011040 = "รับรางวัลสองชิ้นพร้อมกันใน Treasure Dream Realm.",
  str_item_intro_9011041 = "ได้รับ 30 คะแนนประสบการณ์ความฝันทุกครั้งที่ผ่านทางสังเวียนความฝันที่อันตราย",
  str_item_intro_9011042 = "ลดราคาของสินค้าที่สามารถซื้อได้และลดค่าใช้จ่ายในการสุ่มใหม่ Dream Gear, Aurorians, และสินค้าอื่น ๆ ลง 35%",
  str_item_intro_9011043 = "เมื่อได้รับ Aurorians ที่ถูกส่งไปใน Unexplored Dream Realms จะกลับมาทันที และการได้รับ Dream Coins และ Dream Interest จากการส่งนั้นจะเพิ่มเป็นสองเท่า",
  str_item_intro_9011044 = "ได้รับ 40 EXP ฝันทุกครั้งที่ผ่านค่าย",
  str_item_intro_9011045 = "การใช้งานครั้งเดียว: ออโรเรียนทั้งหมดสูญเสีย 70% ของ HP ปัจจุบัน; ได้รับ 25 Dream EXP สำหรับแต่ละออโรเรียนที่สูญเสีย HP",
  str_item_intro_9011046 = "ใช้งานครั้งเดียว: ใช้เหรียญดรีมครึ่งหนึ่งของปัจจุบันและได้รับ Dream EXP 2 คะแนนสำหรับแต่ละเหรียญดรีมที่ใช้ไป",
  str_item_intro_9011047 = "เพิ่มความเสียหายจาก Active Skills ของ Aurorians อย่างมาก; Aurorians สูญเสีย HP เมื่อทำความเสียหาย",
  str_item_9011048 = "บลาสเตอร์",
  str_item_9011049 = "สตอมเปอร์",
  str_item_9011050 = "ผู้พิฆาตราชัน",
  str_item_9011051 = "วอลล์เบรกเกอร์",
  str_item_9011052 = "ปืนหยุดเคลื่อนไหว",
  str_item_9011053 = "ดาบอัสนี",
  str_item_intro_9011048 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลอัพเกรดอัลกอริทึม</u></color></link>; ศัตรูที่อยู่ในสนามน้อยลง ดาเมจสุดท้ายจะสูงขึ้น",
  str_item_intro_9011049 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลอัปเกรดอัลกอริทึม</u></color></link>; กัปตันได้รับ 3 <link=\"1006\"><color=#98500f><u>แต้มโอเวอร์โหลด</u></color></link> เมื่อเริ่มการโจมตีปกติ",
  str_item_intro_9011050 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลอัพเกรดอัลกอริทึม</u></color></link>; สกิลใช้งานของ Aurorians: สร้าง <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link> 4 คะแนนสำหรับแต่ละศัตรูที่ถูกโจมตี",
  str_item_intro_9011051 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลอัพเกรดอัลกอริทึม</u></color></link>; ที่เริ่มต้นของรอบ, HP ของทีมยิ่งต่ำ <link=\"1006\"><color=#98500f><u>แต้มโอเวอร์โหลด</u></color></link> ที่ได้รับก็จะยิ่งมากขึ้น",
  str_item_intro_9011052 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลอัพเกรดอัลกอริทึม</u></color></link>; ได้รับ 8 <link=\"1006\"><color=#98500f><u>แต้มโอเวอร์โหลด</u></color></link> ทุกครั้งที่ได้รับความเสียหาย",
  str_item_intro_9011053 = "เปิดใช้งาน <link=\"1005\"><color=#98500f><u>โมดูลการอัปเกรดอัลกอริทึม</u></color></link>; เพิ่มเกณฑ์การทริกเกอร์ของ Data Bomb สู่ 120 <link=\"1006\"><color=#98500f><u>แต้มโอเวอร์โหลด</u></color></link>, ทำให้ความเสียหายที่สร้างให้กับมอนสเตอร์ขนาดใหญ่มากขึ้น.",
  str_item_intro_9011054 = "ไม่เข้าสู่ออโรราไทม์อีกต่อไป; แทนที่จะได้ค่า +1ms ทุกครั้งที่ควรจะเข้าสู่ออโรราไทม์ และได้รับทอง 5 ชิ้น (ออโรราไทม์ที่ถูกขัดขวางโดยคลื่นมอนสเตอร์หรือชัยชนะในการต่อสู้ก็นับด้วย)",
  str_item_intro_9011055 = "เมื่อศัตรูตาย จะเปลี่ยนช่องที่อยู่ด้านล่างมันสูงสุด 1 ช่องให้เป็นช่องสีมืด",
  str_item_intro_9011056 = "เมื่อเริ่มรอบ แปลงชิ้นส่วน 2 ชิ้นที่ใกล้ที่สุดของธาตุเดียวกันกับกัปตันเป็นชิ้นส่วนสีเข้ม",
  str_item_intro_9011057 = "เพิ่มจำนวนตัวเลือกที่ให้ในการเลือก Dream Gear 1 ตัว",
  str_item_intro_9011058 = "การรีเฟรชตัวเลือก Dream Gear ครั้งแรกเป็นฟรี",
  str_item_intro_9011059 = "สำหรับแต่ละชิ้นของ Dream Gear ที่ครอบครอง, เพิ่ม ATK ของ Detonator และ Sniper Aurorians 0.5%",
  str_item_intro_9011060 = "สำหรับแต่ละชิ้นของ Dream Gear ที่ครอบครอง จะเพิ่ม DEF ของ Converter และ Supporter Aurorians 2%",
  str_item_intro_9011061 = "สำหรับแต่ละชิ้นของ Dream Gear ที่ครอบครอง, เพิ่ม Max HP ของ Aurorians ทั้งหมด 1.5%",
  str_item_intro_9011062 = "ทุกครั้งที่เริ่มรอบใหม่ จะสร้างนาฬิกา 1 ตัว (สามารถมีได้สูงสุด 1 ตัวในเวลาเดียวกัน) ลดรอบคูลดาวน์ของสกิลของออโรเรียนที่มีรอบคูลดาวน์สูงสุดลง 1 รอบ",
  str_item_intro_9011063 = "ทำให้เกิดสถานะ<link=\"1010\"><color=#98500f><u>ตาบอด</u></color></link> ในเป้าหมายที่ได้รับดาเมจ",
  str_item_intro_9011064 = "ทุกครั้งที่ได้รับความเสียหาย ออโรเรียนทั้งหมดจะได้รับโบนัสความเสียหาย 5% สูงสุดถึง 30% (รีเซ็ตที่สิ้นสุดการต่อสู้)",
  str_item_intro_9011065 = "เพิ่มความเสียหายจากการโจมตีปกติ 30% ผลลัพธ์นี้จะหมดอายุหลังจากได้รับความเสียหาย",
  str_item_intro_9011066 = "ลด DEF ของ Aurorians ทั้งหมดลงครึ่งหนึ่งและเพิ่ม ATK ของตัวเองตามจำนวน DEF ที่ลดลง",
  str_item_intro_9011067 = "สร้างภาพของกัปตัน Aurorian ที่จุดเริ่มต้น ภาพนี้ปล่อยเชนคอมโบในรอบนี้ด้วย",
  str_item_intro_9011068 = "เพิ่มความเสียหาย 3.5% สำหรับแต่ละ Aurorian ที่มีองค์ประกอบหลักที่แตกต่างกันในทีม",
  str_item_intro_9011069 = "ธาตุรองสามารถสร้างความเสียหายตามตัวคูณของธาตุหลัก โดยมีการเพิ่มตัวคูณเมื่อธาตุหลักและธาตุรองเป็นเดียวกัน",
  str_item_intro_9011070 = "กัปตันก่อนหน้านี้สามารถถูกปรับใช้ในการต่อสู้ได้โดยไม่คำนึงถึงธาตุของช่องที่เชื่อมต่อ",
  str_item_intro_9011071 = "โอกาสเปลี่ยนกัปตัน +2 ในแต่ละการต่อสู้\nเมื่อเปลี่ยนกัปตัน คูลดาวน์สกิลเรียกใช้ของกัปตันคนใหม่จะลดลง 1 Aurorian แต่ละคนสามารถเรียกใช้เอฟเฟกต์นี้ได้เพียงครั้งเดียวในทุกรอบ",
  str_item_intro_9011072 = "หลังจากการเชื่อมต่อชิ้นส่วนหรือการเคลื่อนที่แต่ละครั้ง ชิ้นส่วนเริ่มต้นต้องเป็นธาตุเดียวกันกับกัปตัน",
  str_item_intro_9011073 = "เพิ่มความเสียหายที่ทำได้โดยพันธมิตรทั้งหมด 15% แต่จะเปลี่ยนแปลงกระเบื้องเริ่มต้นของแต่ละเส้นที่เชื่อมต่อเป็นกระเบื้องแตกที่ไม่สามารถผ่านไปได้เป็นเวลา 8 รอบ",
  str_item_intro_9011074 = "เมื่อทักษะที่ใช้งานของ Aurorians ทำให้ศัตรูถอยหลังหรือดึงมา จะทำความเสียหายคงที่ 3,000 หน่วยสำหรับแต่ละช่องที่เป้าหมายเดินทาง",
  str_item_intro_9011075 = "ทุกออโรเรียนเพิ่มเลเวลการพัฒนา +1 (ไม่ใช้กับออโรเรียนที่เลเวลการพัฒนาถึงสูงสุดแล้ว)",
  str_item_intro_9011076 = "ใช้งานครั้งเดียว: เลือกออโรเรียนใด ๆ เข้าร่วมทีม; เพิ่มระดับการพัฒนาของออโรเรียนนี้สูงสุด",
  str_item_intro_9011077 = "Detonator Aurorians สร้างสแต็ก <link=\"1003\"><color=#98500f><u>Meltdown</u></color></link> 1 สแต็กให้กับเป้าหมายที่ถูกโจมตีด้วย Chain Combos ของพวกเขา",
  str_item_intro_9011078 = "สกิลที่ใช้งานของออโรเรียนเดโทเนเตอร์มีโอกาส 40% ที่จะทำให้เป้าหมาย <link=\"1011\"><color=#98500f><u>อัมพฤกษ์</u></color></link>",
  str_item_intro_9011079 = "ขยายระยะของคอมโบต่อเนื่องระดับสูงสุดของออโรเรียน Detonator ไปถึง 2 คลัสเตอร์",
  str_item_intro_9011080 = "การโจมตีปกติของออโรเรียนเดโทเนเตอร์สร้างความเสียหายเพิ่มเติมที่ไม่สนใจ DEF และยังทำให้เกิดความเสียหายเพิ่มเติมเท่ากับ 10% ของ HP ที่ออโรเรียนเสียไปให้กับเป้าหมาย",
  str_item_intro_9011081 = "การโจมตีปกติของออโรเรียนเดโทเนเตอร์มีโอกาส 30% ที่จะสร้างความเสียหาย 150%",
  str_item_intro_9011082 = "สำหรับแต่ละออโรเรียนเดโทเนเตอร์ที่ถูกส่งออก, เพิ่มความเสียหายที่ทำโดย Chain Combos ของออโรเรียนเดโทเนเตอร์ทั้งหมด 4%",
  str_item_intro_9011083 = "การโจมตีปกติของ Sniper Aurorians สร้าง <link=\"1004\"><color=#98500f><u>Wisdom</u></color></link> เท่ากับ 20% ของ ATK ของพวกเขาต่อเป้าหมาย",
  str_item_intro_9011084 = "เพิ่มความเสียหายที่สร้างจาก Chain Combos ของ Sniper Aurorians ต่อมอนสเตอร์ที่ครอบครองหลายแผ่นกระเบื้อง",
  str_item_intro_9011085 = "ขยายระยะของคอมโบต่อเนื่องเป้าหมายเดียวของ Sniper Aurorians ออกไป 2 ชั้น และเพิ่มจำนวนเป้าหมายขึ้น 1",
  str_item_intro_9011086 = "เพิ่มความเสียหายจากคอมโบต่อเนื่องของออโรเรียนเดโทเนเตอร์ตามจำนวน HP ที่สูญเสีย สูงสุดไม่เกิน 50%",
  str_item_intro_9011087 = "สกิลที่ใช้งานของ Sniper Aurorians มีโอกาส 30% ที่จะสร้าง <link=\"1012\"><color=#98500f><u>ความกลัว</u></color></link> ให้กับเป้าหมาย",
  str_item_intro_9011088 = "สำหรับแต่ละ Sniper Aurorian ที่ถูกส่งออก, เพิ่มความเสียหายที่ทำโดยการโจมตีปกติของ Sniper Aurorians ทั้งหมด 5%",
