  str_item_intro_8800102 = "ดอกไม้ที่บานในความหนาว ปล่อยกลิ่นหอมอ่อนๆ ที่ละมุนละไม่",
  str_item_intro_8800101 = "ก้อนน้ำแข็งที่พบได้ทุกที่ ที่สร้างความเย็นเมื่อรวมกันเป็นจำนวนมาก.",
