  str_item_intro_8800402 = "อัญมณีเหลืองที่มีพลังแสงฟ้าประจุอยู่ภายใน",
  str_item_intro_8800401 = "แร่ที่ไม่เด่น มีความหนาแน่นมากกว่าหินปกติบ้าง",
