  str_item_intro_8800213 = "นุ่มและหวาน, ทุกคำที่เคี้ยวเป็นความสุข.",
  str_item_intro_8800313 = "ตุ๊กตาวินเดเลียนที่มีเสน่ห์ทั้งในเรื่องของการมองเห็นและการสัมผัส มีศักยภาพที่จะกลายเป็นของขวัญที่ได้รับความนิยม",
  str_item_intro_8800413 = "ลูกแก้วคริสตัลที่ปล่อยแสงสว่างที่น่าหลงใหล ที่เหมาะสำหรับการตกแต่งบ้าน",
  str_item_intro_8800112 = "ครีมทาแก้เจ็บเข่าเป็น และรอยช้ำที่ฤทธิ์ดีเร็ว มันเป็นสิ่งจำเป็นที่ต้องมีสำหรับที่บ้านและการเดินทาง",
  str_item_intro_8800212 = "มันช่วยลดการเสียดทานและทำให้ผิวเรียบ ทำให้เหมาะสำหรับการใช้งานหลายครั้ง",
  str_item_intro_8800312 = "ไม้กระถางที่มีชีวิตชีวาและเป็นมิตรกับสิ่งแวดล้อม สามารถเจริญเติบโตได้ดีในที่ที่มีแสงแดด",
  str_item_intro_8800412 = "มีดที่คมมาก ๆ มันตัดทุกอย่างได้ง่าย ๆ ช่างฝีมือชอบใช้",
  str_item_intro_8800111 = "เหมาะสำหรับใช้เย็นสินค้า และยังปลอดภัยในการดื่มด้วย",
  str_item_intro_8800211 = "ระเบิดแรงสูงที่ต้องจัดการอย่างระมัดระวัง",
